insert into public.mushroom_lookalikes_i18n (edible_slug,lookalike_slug,lang,visual_differences,smell_differences,habitat_differences,spore_print_differences,pro_tip,key_differences,verified) values
('agaricus_augustus','agaricus_moelleri','en','The prince (Agaricus augustus) with a brownish-scaly cap that yellows under pressure, large; inky mushroom grey-brown spotted, guineafowl-like, smaller.','The prince: anise/bitter almond. Inky mushroom: carbolic/ink, unpleasant when cooked. The smell is the central distinguishing feature.','The prince at path edges, in coniferous forest, on compost; inky mushroom parks/gardens/forest edge. Overlap possible near settlements.','Both chocolate-brown — NOT a distinguishing feature.','The carbolic smell and chrome-yellow stem base are the unmistakable sign of the toxic mushroom — when in doubt, discard the entire find, do not rely on size.','{"The prince (Agaricus augustus) smells pleasantly of anise/bitter almond; the inky mushroom of carbolic/ink","The stem base of the inky mushroom turns immediately and strongly chrome-yellow; the prince yellows only faintly/on the outside","The prince with a brownish-scaly (not grey-spotted) cap that yellows pleasantly under pressure; the inky mushroom grey-brown guineafowl-mottled","When heated anise aroma (edible) vs ink/carbolic smell (toxic)","The prince grows very large (cap often 10-25 cm); but striking size alone is NOT proof of safety — smell + stem base remain mandatory"}','f'),
('agaricus_augustus','agaricus_moelleri','es','Champiñón gigante (Agaricus augustus) con sombrero parduzco-escamoso que amarillea a la presión, grande; champiñón perlado gris-pardo moteado, como una pintada, más pequeño.','Champiñón gigante: anís/almendra amarga. Champiñón perlado: fenol/tinta, desagradable al cocinar. El olor es el criterio de distinción central.','Champiñón gigante en los bordes de los caminos, en bosque de coníferas, sobre compost; champiñón perlado parques/jardines/borde del bosque. Solapamiento posible cerca de los asentamientos.','Ambos marrón chocolate — NO es un criterio de distinción.','El olor a fenol y la base del pie amarillo cromo son la señal inequívoca del hongo tóxico — en caso de duda, desechar toda la recolección, no fiarse del tamaño.','{"El champiñón gigante (Agaricus augustus) huele agradablemente a anís/almendra amarga; el champiñón perlado a fenol/tinta","La base del pie del champiñón perlado vira de inmediato y con fuerza a amarillo cromo; el champiñón gigante amarillea solo débilmente/por fuera","Champiñón gigante con sombrero parduzco-escamoso (no manchado de gris) que amarillea agradablemente a la presión; champiñón perlado gris-pardo moteado como una pintada","Al calentar, aroma de anís (comestible) vs olor a tinta/fenol (tóxico)","El champiñón gigante se vuelve muy grande (sombrero a menudo 10-25 cm); pero un tamaño llamativo por sí solo NO es prueba de seguridad — olor + base del pie siguen siendo obligatorios"}','f'),
('agaricus_augustus','agaricus_moelleri','fr','Agaric géant (agaric impérial) à chapeau brunâtre-squameux jaunissant à la pression, grand ; agaric perlé gris-brun moucheté, comme une pintade, plus petit.','Agaric géant : anis/amande amère. Agaric perlé : phénol/encre, désagréable à la cuisson. L''odeur est le critère de distinction central.','Agaric géant au bord des chemins, en forêt de conifères, sur le compost ; agaric perlé parcs/jardins/lisière. Chevauchement possible près des habitations.','Les deux brun chocolat — PAS un critère de distinction.','L''odeur de phénol et la base du pied jaune chrome sont le signe infaillible du champignon toxique — en cas de doute, jeter toute la récolte, ne pas se fier à la taille.','{"L''agaric géant (agaric impérial) sent agréablement l''anis/l''amande amère ; l''agaric perlé le phénol/l''encre","La base du pied de l''agaric perlé vire immédiatement et fortement au jaune chrome ; l''agaric géant ne jaunit que faiblement/en surface","Agaric géant à chapeau brunâtre-squameux (non taché de gris) qui jaunit agréablement à la pression ; agaric perlé gris-brun moucheté comme une pintade","Au chauffage, arôme d''anis (comestible) vs odeur d''encre/de phénol (toxique)","L''agaric géant devient très grand (chapeau souvent 10-25 cm) ; mais une taille frappante seule n''est PAS une preuve de sûreté — odeur + base du pied restent obligatoires"}','f'),
('agaricus_augustus','agaricus_moelleri','it','Prataiolo gigante (prataiolo imperiale) con cappello brunastro-squamoso che ingiallisce alla pressione, grande; prataiolo perlato grigio-bruno maculato, come una faraona, più piccolo.','Prataiolo gigante: anice/mandorla amara. Prataiolo perlato: fenolo/inchiostro, sgradevole in cottura. L''odore è il criterio distintivo centrale.','Prataiolo gigante ai margini dei sentieri, in bosco di conifere, sul compost; prataiolo perlato parchi/giardini/margini. Sovrapposizione possibile vicino agli insediamenti.','Entrambi bruno cioccolato — NON un criterio distintivo.','L''odore di fenolo e la base del gambo giallo cromo sono il segno inequivocabile del fungo velenoso — nel dubbio gettare l''intero raccolto, non affidarsi alle dimensioni.','{"Il prataiolo gigante (prataiolo imperiale) odora gradevolmente di anice/mandorla amara; il prataiolo perlato di fenolo/inchiostro","La base del gambo del prataiolo perlato vira subito e intensamente al giallo cromo; il prataiolo gigante ingiallisce solo debolmente/in superficie","Prataiolo gigante con cappello brunastro-squamoso (non macchiato di grigio) che ingiallisce gradevolmente alla pressione; prataiolo perlato grigio-bruno maculato come una faraona","Al riscaldamento profumo di anice (commestibile) vs odore di inchiostro/fenolo (velenoso)","Il prataiolo gigante diventa molto grande (cappello spesso 10-25 cm); ma una taglia vistosa da sola NON è prova di sicurezza — odore + base del gambo restano obbligatori"}','f'),
('agaricus_augustus','agaricus_xanthodermus','en','Smell + discolouration at the stem base (anise vs. carbolic; faintly yellow vs. chrome-yellow).','Anise (edible) vs. carbolic/ink (poisonous) — the most important criterion','both forest/park/garden','both chocolate-brown','Cut into the stem base: strong chrome-yellow + carbolic smell = Yellow-staining mushroom (Agaricus xanthodermus, poisonous). With white field mushrooms, also rule out a volva (Amanita / deathcap).','{"The Prince (Agaricus augustus): anise/almond smell, weak yellowing","Yellow-staining mushroom (Agaricus xanthodermus): carbolic/ink smell (intensifies on heating), chrome-yellow stem base"}','t'),
('agaricus_augustus','agaricus_xanthodermus','es','Olor + decoloración en la base del pie (anís vs. carbol/fenol; ligeramente amarillo vs. amarillo cromo).','Anís (comestible) vs. carbol/fenol/tinta (tóxico) — el criterio más importante','ambos en bosque/parque/jardín','ambos marrón chocolate','Cortar la base del pie: amarillo cromo intenso + olor a carbol/fenol = champiñón amarilleante (Agaricus xanthodermus, tóxico). En los champiñones blancos, descartar además la volva (Amanita / oronja mortal).','{"Champiñón gigante (Agaricus augustus): olor a anís/almendra, amarilleo débil","Champiñón amarilleante (Agaricus xanthodermus): olor a carbol/fenol/tinta (se intensifica al calentar), base del pie de color amarillo cromo"}','t'),
('agaricus_augustus','agaricus_xanthodermus','fr','Odeur + coloration à la base du pied (anis vs. carbol; jaune faible vs. jaune chrome).','Anis (comestible) vs. carbol/encre (toxique) — critère le plus important','les deux en forêt/parc/jardin','les deux brun chocolat','Inciser la base du pied : jaune chrome vif + odeur de carbol = agaric jaunissant (toxique). Pour les agarics blancs, exclure en plus une volve (amanite phalloïde).','{"Agaric auguste : odeur d''anis/d''amande, jaunissement faible","Agaric jaunissant : odeur de carbol/d''encre (renforcée à la cuisson), base du pied jaune chrome"}','t'),
('agaricus_augustus','agaricus_xanthodermus','it','Odore + viraggio del colore alla base del gambo (anice vs. carbolico; debolmente giallo vs. giallo cromo).','Anice (commestibile) vs. carbolico/inchiostro (velenoso) — il criterio più importante','entrambi bosco/parco/giardino','entrambi marrone cioccolato','Incidere la base del gambo: giallo cromo intenso + odore carbolico = prataiolo giallo (velenoso). Negli agarici bianchi escludere inoltre la volva (Amanita phalloides).','{"Prataiolo gigante (Agaricus augustus): odore di anice/mandorla, ingiallimento debole","Prataiolo giallo (Agaricus xanthodermus): odore carbolico/di inchiostro (intensificato col calore), base del gambo giallo cromo"}','t'),
('agaricus_campestris','agaricus_moelleri','en','Inky/karbolic mushroom (Agaricus moelleri) with a grey-brown spotted, guineafowl-mottled cap; field mushroom pure white to cream, smooth. Caution: both small to medium-sized, easily confused in the field.','Toxic mushroom: smell of carbolic/ink/iodine, disgustingly intensified when cooked. Field mushroom: pleasantly mushroomy and mild. Here the smell is a reliable distinguishing feature.','Inky mushroom rather in parks, gardens, at forest edges and near settlements; field mushroom on mown meadows and pastures. Habitat overlap possible, so do not rely on it alone.','Both have a chocolate-brown spore print — NOT a distinguishing feature.','On EVERY agaric, cut the stem base AND smell it: chrome-yellow staining plus a carbolic/ink smell (also test during a brief sauté) = toxic agaric, discard the entire basket contents, not just the single specimen.','{"The inky/carbolic mushroom smells unpleasantly of carbolic/ink/iodine (pharmacy, hospital), the smell intensifying and becoming sickening when heated; the field mushroom smells pleasantly mushroomy and mild","The stem base of the inky mushroom turns immediately and strongly chrome-yellow when scratched/cut (especially in the bulb area); the field mushroom at most faintly reddish/brownish","The field mushroom has pink gills from the start, later chocolate-brown (never pure white); pure white gills in a young agaric = warning sign towards the toxic agaric","Cap surface of the inky mushroom grey-brown spotted/scaly (guineafowl-mottled); field mushroom pure white to cream, smooth to scaly","The carbolic smell AND chrome-yellow stem base occur together and reliably rule out any edible agaric"}','f'),
('agaricus_campestris','agaricus_moelleri','es','Champiñón perlado (Agaricus moelleri) con sombrero gris-pardo moteado, jaspeado como el plumaje de una pintada; champiñón silvestre blanco puro a crema, liso. Atención: ambos de tamaño pequeño-mediano, fácilmente confundibles en el campo.','Hongo tóxico: olor a fenol/tinta/yodo, desagradablemente intensificado al cocinar. Champiñón silvestre: agradablemente fúngico y suave. Aquí el olor es un criterio de distinción fiable.','Champiñón perlado más bien en parques, jardines, en los bordes del bosque y cerca de los asentamientos; champiñón silvestre en prados segados y pastos. Solapamiento de hábitat posible, no fiarse solo de esto.','Ambos esporada marrón chocolate — NO es un criterio de distinción.','En CADA champiñón cortar la base del pie Y olerla: viraje amarillo cromo más olor a fenol/tinta (probar también durante un breve salteado) = champiñón tóxico, desechar todo el contenido del cesto, no solo el ejemplar aislado.','{"El champiñón perlado/fenólico huele desagradablemente a fenol/tinta/yodo (farmacia, hospital), olor intensificado y nauseabundo al calentar; el champiñón silvestre huele agradablemente a hongo, suave","La base del pie del champiñón perlado vira de inmediato y con fuerza a amarillo cromo al rascarla/cortarla (sobre todo en la zona del bulbo); el champiñón silvestre como mucho débilmente rojizo/parduzco","El champiñón silvestre tiene láminas rosas desde el principio, luego marrón chocolate (nunca blanco puro); láminas blanco puro en un champiñón joven = señal de alarma hacia el champiñón tóxico","Superficie del sombrero del champiñón perlado gris-pardo moteada/escamosa (jaspeada como una pintada); champiñón silvestre blanco puro a crema, de liso a escamoso","El olor a fenol Y la base del pie amarillo cromo aparecen juntos y excluyen con certeza cualquier champiñón comestible"}','f'),
('agaricus_campestris','agaricus_moelleri','fr','Agaric perlé (psalliote pintade) à chapeau gris-brun moucheté, tacheté comme un plumage de pintade ; agaric champêtre blanc pur à crème, lisse. Attention : les deux sont petits à moyens et facilement confondables sur le terrain.','Champignon toxique : odeur de phénol/encre/iode, désagréablement renforcée à la cuisson. Agaric champêtre : agréablement fongique et douce. Ici l''odeur est un critère de distinction fiable.','Agaric perlé plutôt dans les parcs, jardins, en lisière de forêt et près des habitations ; agaric champêtre dans les prairies fauchées et les pâturages. Un chevauchement d''habitat est possible, ne pas s''y fier seul.','Les deux ont une sporée brun chocolat — PAS un critère de distinction.','Sur CHAQUE agaric, couper la base du pied ET sentir : virage jaune chrome plus odeur de phénol/encre (à tester aussi lors d''une brève cuisson) = agaric toxique, jeter tout le contenu du panier, pas seulement le spécimen isolé.','{"L''agaric perlé/phénolé sent désagréablement le phénol/l''encre/l''iode (pharmacie, hôpital), odeur renforcée et écœurante au chauffage ; l''agaric champêtre sent agréablement le champignon, doux","La base du pied de l''agaric perlé vire immédiatement et fortement au jaune chrome quand on la gratte/coupe (surtout dans la zone du bulbe) ; l''agaric champêtre tout au plus faiblement rougeâtre/brunâtre","L''agaric champêtre a des lames roses dès le début, puis brun chocolat (jamais blanc pur) ; des lames blanc pur chez un jeune agaric = signal d''alerte vers l''agaric toxique","Surface du chapeau de l''agaric perlé gris-brun mouchetée/squameuse (tachetée comme une pintade) ; agaric champêtre blanc pur à crème, lisse à squameux","L''odeur de phénol ET la base du pied jaune chrome apparaissent ensemble et excluent avec certitude tout agaric comestible"}','f'),
('agaricus_campestris','agaricus_moelleri','it','Prataiolo perlato (psalliota della faraona) con cappello grigio-bruno maculato, screziato come il piumaggio di una faraona; prataiolo dei prati bianco puro-crema, liscio. Attenzione: entrambi piccolo-medi, facilmente confondibili sul campo.','Fungo velenoso: odore di fenolo/inchiostro/iodio, sgradevolmente accentuato in cottura. Prataiolo dei prati: gradevolmente fungino e delicato. Qui l''odore è un criterio distintivo affidabile.','Prataiolo perlato piuttosto in parchi, giardini, ai margini dei boschi e vicino agli insediamenti; prataiolo dei prati su prati falciati e pascoli. Sovrapposizione di habitat possibile, non affidarsi solo a questo.','Entrambi sporata bruno cioccolato — NON un criterio distintivo.','Su OGNI prataiolo tagliare la base del gambo E annusare: viraggio giallo cromo più odore di fenolo/inchiostro (testare anche con una breve rosolatura) = prataiolo velenoso, gettare l''intero contenuto del cesto, non solo il singolo esemplare.','{"Il prataiolo perlato/fenolico odora sgradevolmente di fenolo/inchiostro/iodio (farmacia, ospedale), odore accentuato e nauseante al riscaldamento; il prataiolo dei prati odora gradevolmente di fungo, delicato","La base del gambo del prataiolo perlato vira subito e intensamente al giallo cromo quando viene grattata/tagliata (soprattutto nella zona del bulbo); il prataiolo dei prati al massimo debolmente rossastro/brunastro","Il prataiolo dei prati ha lamelle rosa fin dall''inizio, poi bruno cioccolato (mai bianco puro); lamelle bianco puro in un prataiolo giovane = segnale d''allarme verso il prataiolo velenoso","Superficie del cappello del prataiolo perlato grigio-bruno maculata/squamosa (screziata come una faraona); prataiolo dei prati bianco puro-crema, da liscio a squamoso","L''odore di fenolo E la base del gambo giallo cromo compaiono insieme ed escludono con certezza ogni prataiolo commestibile"}','f'),
('agaricus_campestris','amanita_phalloides','en','Field mushroom: white-beige cap, pink gills that turn brown. Deathcap (Amanita phalloides): olive-green cap, white gills that stay white.','Field mushroom: pleasant mushroomy. Deathcap (Amanita phalloides): faintly sweetish.','Field mushroom: meadows, pastures. Deathcap (Amanita phalloides): deciduous forest, oaks.','Field mushroom: dark brown. Deathcap (Amanita phalloides): white.','ALWAYS check the stem base — a bulb in a membranous sac (volva) = NEVER eat!','{"Field mushroom NEVER has a bulb in a sac, the deathcap (Amanita phalloides) always does","Field mushroom gills turn pink then chocolate-brown, deathcap (Amanita phalloides) gills stay white"}','t'),
('agaricus_campestris','amanita_phalloides','es','Champiñón: sombrero blanco-beige, láminas rosadas que se vuelven marrones. Oronja mortal (Amanita phalloides): sombrero verde oliva, láminas blancas que permanecen blancas.','Champiñón: agradable, a hongo. Oronja mortal: ligeramente dulzón.','Champiñón: prados, pastizales. Oronja mortal: bosque de frondosas, robles.','Champiñón: marrón oscuro. Oronja mortal: blanco.','SIEMPRE comprobar la base del pie — bulbo dentro de una funda membranosa (volva) = ¡NUNCA comer!','{"El champiñón NUNCA tiene bulbo dentro de una funda; la oronja mortal siempre","Las láminas del champiñón se vuelven rosadas y marrón chocolate; las de la oronja mortal permanecen blancas"}','t'),
('agaricus_campestris','amanita_phalloides','fr','Champignon de Paris : chapeau blanc-beige, lamelles roses devenant brunes. Amanite phalloïde : chapeau vert olive, lamelles blanches restant blanches.','Champignon de Paris : agréable, odeur de champignon. Amanite phalloïde : faiblement sucrée.','Champignon de Paris : prairies, pâturages. Amanite phalloïde : forêt de feuillus, chênes.','Champignon de Paris : brun foncé. Amanite phalloïde : blanc.','TOUJOURS vérifier la base du pied — bulbe dans une volve membraneuse = NE JAMAIS manger !','{"Le champignon de Paris n''a JAMAIS de bulbe dans une volve, l''amanite phalloïde en a toujours un","Les lamelles du champignon de Paris deviennent roses puis brun chocolat, celles de l''amanite phalloïde restent blanches"}','t'),
('agaricus_campestris','amanita_phalloides','it','Prataiolo: cappello bianco-beige, lamelle rosa che diventano marroni. Tignosa verdognola: cappello verde oliva, lamelle bianche che restano bianche.','Prataiolo: gradevole, fungino. Tignosa verdognola: debolmente dolciastro.','Prataiolo: prati, pascoli. Tignosa verdognola: bosco di latifoglie, querce.','Prataiolo: marrone scuro. Tignosa verdognola: bianco.','Controllare SEMPRE la base del gambo — bulbo in una volva membranosa = MAI mangiare!','{"Il prataiolo non ha MAI un bulbo nella volva, la tignosa verdognola sempre","Le lamelle del prataiolo diventano rosa e marrone cioccolato, quelle della tignosa verdognola restano bianche"}','t'),
('agaricus_campestris','fliegenpilz_var_alba','en','Field mushroom: pink-brown gills, ringed stem without bulbous volva; white fly agaric: white gills, warted belted bulb.','Field mushroom pleasantly mushroomy; white fly agaric inconspicuous.','Field mushroom on open grassland; fly agaric var. alba in/at the forest, mycorrhizal.','Field mushroom with brown spore print vs. white spore print in the fly agaric.','Golden Agaricus rule: never eat a "mushroom" with gills that stay white — the spore print (brown vs. white) makes the difference.','{"The field mushroom has free gills that are pink when young, later blackish-brown, and a brown spore print; the white fly agaric keeps white gills and has a white spore print","Agaricus mushrooms have no volva and no warted-belted bulb — the white fly agaric shows veil warts and a rimmed, striated bulb base","Habitat: field mushroom on open, fertilised meadows/pastures; white fly agaric in the forest under birch/conifer","Reject any supposed Agaricus with white gills immediately — white gills point to Amanita"}','f'),
('agaricus_campestris','fliegenpilz_var_alba','es','Champiñón silvestre: láminas rosa-marrón, pie anillado sin volva bulbosa; amanita matamoscas blanca: láminas blancas, bulbo verrugoso con cinturones.','Champiñón silvestre agradablemente fúngico; amanita matamoscas blanca discreta.','Champiñón silvestre en praderas abiertas; matamoscas var. alba en/al borde del bosque, micorrízica.','Champiñón silvestre con esporada marrón frente a esporada blanca de la amanita matamoscas.','Regla de oro del champiñón: nunca comer un «champiñón» cuyas láminas permanezcan blancas — la impronta de esporada (marrón frente a blanca) marca la diferencia.','{"El champiñón silvestre tiene láminas libres rosas de joven, luego negro-marrones, y esporada marrón; la amanita matamoscas blanca conserva láminas blancas y tiene esporada blanca","Los champiñones no tienen volva ni bulbo verrugoso-cinturado — la amanita matamoscas blanca muestra verrugas de velo y una base de bulbo marginada-estriada","Hábitat: champiñón silvestre en praderas/pastos abiertos y abonados; amanita matamoscas blanca en el bosque bajo abedul/conífera","Rechazar de inmediato todo supuesto champiñón con láminas blancas — las láminas blancas apuntan a Amanita"}','f'),
('agaricus_campestris','fliegenpilz_var_alba','fr','Agaric champêtre : lamelles rose-brun, pied annelé sans volve bulbeuse ; amanite tue-mouches blanche : lamelles blanches, bulbe verruqueux ceinturé.','Agaric champêtre agréablement fongique ; amanite tue-mouches blanche discrète.','Agaric champêtre en prairies ouvertes ; amanite tue-mouches var. alba en/au bord de forêt, mycorhizienne.','Agaric champêtre à sporée brune contre sporée blanche chez l''amanite tue-mouches.','Règle d''or de l''agaric : ne jamais manger un « champignon » dont les lamelles restent blanches — l''empreinte de sporée (brune contre blanche) fait la différence.','{"L''agaric champêtre a des lamelles libres roses jeunes puis brun-noir et une sporée brune ; l''amanite tue-mouches blanche garde des lamelles blanches et a une sporée blanche","Les agarics n''ont pas de volve ni de bulbe verruqueux-ceinturé — l''amanite tue-mouches blanche montre des verrues de voile et une base de bulbe marginée-striée","Habitat : agaric champêtre sur prairies/pâtures ouvertes et fertilisées ; amanite tue-mouches blanche en forêt sous bouleau/conifère","Rejeter immédiatement tout prétendu agaric à lamelles blanches — des lamelles blanches indiquent une Amanita"}','f'),
('agaricus_campestris','fliegenpilz_var_alba','it','Prataiolo (campestre): lamelle rosa-brune, gambo anellato senza volva bulbosa; ovolaccio bianco: lamelle bianche, bulbo verrucoso a cinture.','Prataiolo campestre gradevolmente fungino; ovolaccio bianco discreto.','Prataiolo campestre in prati aperti; ovolaccio var. alba nel/ai margini del bosco, micorrizico.','Prataiolo campestre con sporata bruna contro sporata bianca dell''ovolaccio.','Regola d''oro del prataiolo: non mangiare mai un «prataiolo» con lamelle che restano bianche — l''impronta sporale (bruna contro bianca) fa la differenza.','{"Il prataiolo campestre ha lamelle libere rosa da giovani poi bruno-nere e una sporata bruna; l''ovolaccio bianco mantiene lamelle bianche e ha una sporata bianca","I prataioli non hanno volva né bulbo verrucoso-cinturato — l''ovolaccio bianco mostra verruche di velo e una base del bulbo marginato-striata","Habitat: prataiolo campestre su prati/pascoli aperti e concimati; ovolaccio bianco nel bosco sotto betulla/conifera","Scartare subito ogni presunto prataiolo con lamelle bianche — lamelle bianche indicano un''Amanita"}','f'),
('agaricus_silvicola','agaricus_moelleri','en','Wood mushroom pure white silky (yellows faintly); inky mushroom grey-brown spotted with guineafowl-mottled cap. Caution: similar whitish appearance.','Wood mushroom: pleasant smell of anise/bitter almond. Toxic mushroom: carbolic/ink/iodine, unpleasant when cooked. The smell is the most important distinguishing feature.','Wood mushroom in coniferous/mixed forest; inky mushroom in parks, gardens, at forest edges. Habitat helps but is not absolutely discriminating.','Both chocolate-brown — NOT a distinguishing feature.','The smell test and scratch test at the stem base are mandatory: carbolic smell plus chrome-yellow base = toxic, never eat. An anise smell without a chrome-yellow base argues for the wood mushroom — when in doubt, make a spore print and consult an expert.','{"The thin-fleshed wood mushroom smells distinctly of anise/bitter almond (pleasant); the inky mushroom of carbolic/ink/iodine (unpleasant)","The stem base of the wood mushroom turns at most faintly yellowish when cut; that of the inky mushroom immediately and strongly chrome-yellow","When heated the anise aroma becomes pleasantly sweet, the inky mushroom stinks more strongly of ink/carbolic","The wood mushroom has a pure white, silky cap (yellows slightly under pressure); the inky mushroom grey-brown spotted/scaly","Both have pale gills when young — therefore NEVER decide on gill colour alone, but combine smell + stem-base reaction"}','f'),
('agaricus_silvicola','agaricus_moelleri','es','Champiñón anisado blanco puro sedoso (amarillea ligeramente); champiñón perlado gris-pardo moteado con sombrero jaspeado como una pintada. Atención: aspecto blanquecino similar.','Champiñón anisado: agradable olor a anís/almendra amarga. Hongo tóxico: fenol/tinta/yodo, desagradable al cocinar. El olor es el criterio de distinción más importante.','Champiñón anisado en bosque de coníferas/mixto; champiñón perlado en parques, jardines, bordes del bosque. El hábitat ayuda pero no es absolutamente discriminante.','Ambos marrón chocolate — NO es un criterio de distinción.','La prueba olfativa y de rascado en la base del pie es obligatoria: olor a fenol más base amarillo cromo = tóxico, nunca comer. Olor a anís sin base amarillo cromo aboga por el champiñón anisado — en caso de duda, hacer la esporada y consultar a un experto.','{"El champiñón anisado de carne delgada huele claramente a anís/almendra amarga (agradable); el champiñón perlado a fenol/tinta/yodo (desagradable)","La base del pie del champiñón anisado vira como mucho débilmente a amarillento al cortarla; la del champiñón perlado de inmediato y con fuerza a amarillo cromo","Al calentar, el aroma de anís se vuelve agradablemente dulce, el champiñón perlado apesta más a tinta/fenol","El champiñón anisado tiene sombrero blanco puro, sedoso (amarillea ligeramente a la presión); el champiñón perlado gris-pardo moteado/escamoso","Ambos tienen láminas claras de jóvenes — por eso NUNCA decidir solo por el color de las láminas, sino combinar olor + reacción de la base del pie"}','f'),
('agaricus_silvicola','agaricus_moelleri','fr','Agaric anisé blanc pur soyeux (jaunit légèrement) ; agaric perlé gris-brun moucheté avec chapeau tacheté comme une pintade. Attention : aspect blanchâtre similaire.','Agaric anisé : odeur agréable d''anis/amande amère. Champignon toxique : phénol/encre/iode, désagréable à la cuisson. L''odeur est le critère de distinction le plus important.','Agaric anisé en forêt de conifères/mixte ; agaric perlé dans les parcs, jardins, en lisière de forêt. L''habitat aide mais n''est pas absolument discriminant.','Les deux brun chocolat — PAS un critère de distinction.','Le test olfactif et le grattage de la base du pied sont obligatoires : odeur de phénol plus base jaune chrome = toxique, ne jamais manger. Une odeur d''anis sans base jaune chrome plaide pour l''agaric anisé — en cas de doute, faire la sporée et consulter un spécialiste.','{"L''agaric anisé à chair mince sent nettement l''anis/l''amande amère (agréable) ; l''agaric perlé le phénol/l''encre/l''iode (désagréable)","La base du pied de l''agaric anisé vire tout au plus faiblement au jaunâtre à la coupe ; celle de l''agaric perlé immédiatement et fortement au jaune chrome","Au chauffage, l''arôme d''anis devient agréablement sucré, l''agaric perlé pue davantage l''encre/le phénol","L''agaric anisé a un chapeau blanc pur, soyeux (jaunit légèrement à la pression) ; l''agaric perlé gris-brun moucheté/squameux","Les deux ont des lames claires lorsqu''ils sont jeunes — ne JAMAIS décider sur la seule couleur des lames, mais combiner odeur + réaction de la base du pied"}','f'),
('agaricus_silvicola','agaricus_moelleri','it','Prataiolo anisato bianco puro setoso (ingiallisce leggermente); prataiolo perlato grigio-bruno maculato con cappello screziato come una faraona. Attenzione: aspetto biancastro simile.','Prataiolo anisato: gradevole odore di anice/mandorla amara. Fungo velenoso: fenolo/inchiostro/iodio, sgradevole in cottura. L''odore è il criterio distintivo più importante.','Prataiolo anisato in bosco di conifere/misto; prataiolo perlato in parchi, giardini, ai margini dei boschi. L''habitat aiuta ma non è assolutamente discriminante.','Entrambi bruno cioccolato — NON un criterio distintivo.','La prova olfattiva e di grattatura alla base del gambo è obbligatoria: odore di fenolo più base giallo cromo = velenoso, mai mangiare. Odore di anice senza base giallo cromo depone per il prataiolo anisato — nel dubbio fare la sporata e consultare un esperto.','{"Il prataiolo anisato a carne sottile odora nettamente di anice/mandorla amara (gradevole); il prataiolo perlato di fenolo/inchiostro/iodio (sgradevole)","La base del gambo del prataiolo anisato vira al massimo debolmente al giallastro al taglio; quella del prataiolo perlato subito e intensamente al giallo cromo","Al riscaldamento il profumo di anice diventa gradevolmente dolce, il prataiolo perlato puzza maggiormente di inchiostro/fenolo","Il prataiolo anisato ha cappello bianco puro, setoso (ingiallisce leggermente alla pressione); il prataiolo perlato grigio-bruno maculato/squamoso","Entrambi hanno lamelle chiare da giovani — quindi MAI decidere solo dal colore delle lamelle, ma combinare odore + reazione della base del gambo"}','f'),
('agaricus_silvicola','fliegenpilz_var_alba','en','Agaricus (wood mushroom): pink to brown gills, smooth stem with ring, no bulbous volva; white fly agaric: white gills, warted belted bulb.','Wood mushroom smelling of anise/marzipan; white fly agaric inconspicuous.','Wood mushroom in forests; white fly agaric mycorrhizal under birch/conifer.','Wood mushroom with brown spore print vs. white spore print in the fly agaric — decisive distinguishing feature.','The spore-print test and gill colour are lifesavers: white gills + white spore print + bulbous volva = never eat as an Agaricus.','{"The wood mushroom has free gills that are pink when young and later chocolate brown, and a brown spore print; the white fly agaric has permanently WHITE gills and a white spore print","Agaricus mushrooms have NO volva and no warted, belted bulbous base — the white fly agaric has warted veil remnants and a striated-rimmed bulb","The wood mushroom smells distinctly of anise/marzipan; the white fly agaric is odourless","Young white fly agaric bulbs look agaric-like — therefore always dig out the stem base and check gill colour + spore print"}','f'),
('agaricus_silvicola','fliegenpilz_var_alba','es','Champiñón (de bosque): láminas rosas a marrones, pie liso con anillo, sin volva bulbosa; amanita matamoscas blanca: láminas blancas, bulbo verrugoso con cinturones.','Champiñón anisado huele a anís/mazapán; amanita matamoscas blanca discreta.','Champiñón anisado en bosques; amanita matamoscas blanca micorrízica bajo abedul/conífera.','Champiñón anisado con esporada marrón frente a esporada blanca de la amanita matamoscas — carácter distintivo decisivo.','La prueba de esporada y el color de las láminas salvan la vida: láminas blancas + esporada blanca + volva bulbosa = nunca comer como champiñón.','{"El champiñón anisado tiene láminas libres que de jóvenes son rosas y luego marrón chocolate, y esporada marrón; la amanita matamoscas blanca tiene láminas permanentemente BLANCAS y esporada blanca","Los champiñones NO poseen volva ni base bulbosa verrugoso-cinturada — la amanita matamoscas blanca tiene restos de velo verrugosos y un bulbo estriado-marginado","El champiñón anisado huele claramente a anís/mazapán; la amanita matamoscas blanca es inodora","Los bulbos jóvenes de amanita matamoscas blanca parecen champiñones — por eso desenterrar siempre la base del pie y comprobar color de láminas + esporada"}','f'),
('agaricus_silvicola','fliegenpilz_var_alba','fr','Agaric : lamelles roses à brunes, pied lisse avec anneau, sans volve bulbeuse ; amanite tue-mouches blanche : lamelles blanches, bulbe verruqueux ceinturé.','Agaric anisé sentant l''anis/le massepain ; amanite tue-mouches blanche discrète.','Agaric anisé en forêts ; amanite tue-mouches blanche mycorhizienne sous bouleau/conifère.','Agaric anisé à sporée brune contre sporée blanche chez l''amanite tue-mouches — caractère de séparation décisif.','L''épreuve de la sporée et la couleur des lamelles sauvent la vie : lamelles blanches + sporée blanche + volve bulbeuse = ne jamais manger comme agaric.','{"L''agaric anisé a des lamelles libres qui sont roses jeunes puis brun chocolat, et une sporée brune ; l''amanite tue-mouches blanche a des lamelles durablement BLANCHES et une sporée blanche","Les agarics ne possèdent AUCUNE volve et aucune base bulbeuse verruqueuse-ceinturée — l''amanite tue-mouches blanche a des restes de voile verruqueux et un bulbe strié-marginé","L''agaric anisé sent nettement l''anis/le massepain ; l''amanite tue-mouches blanche est inodore","Les jeunes bulbes d''amanite tue-mouches blanche ressemblent à des agarics — toujours déterrer la base du pied et vérifier la couleur des lamelles + la sporée"}','f'),
('agaricus_silvicola','fliegenpilz_var_alba','it','Prataiolo: lamelle rosa fino a brune, gambo liscio con anello, senza volva bulbosa; ovolaccio bianco: lamelle bianche, bulbo verrucoso a cinture.','Prataiolo all''anice odora di anice/marzapane; ovolaccio bianco discreto.','Prataiolo all''anice nei boschi; ovolaccio bianco micorrizico sotto betulla/conifera.','Prataiolo all''anice con sporata bruna contro sporata bianca dell''ovolaccio — carattere distintivo decisivo.','La prova della sporata e il colore delle lamelle salvano la vita: lamelle bianche + sporata bianca + volva bulbosa = mai mangiare come prataiolo.','{"Il prataiolo all''anice ha lamelle libere che da giovani sono rosa e poi bruno cioccolato, e una sporata bruna; l''ovolaccio bianco ha lamelle stabilmente BIANCHE e sporata bianca","I prataioli NON possiedono volva né base bulbosa verrucoso-cinturata — l''ovolaccio bianco ha resti di velo verrucosi e un bulbo striato-marginato","Il prataiolo all''anice odora nettamente di anice/marzapane; l''ovolaccio bianco è inodore","I giovani bulbi di ovolaccio bianco sembrano prataioli — perciò dissotterrare sempre la base del gambo e controllare colore delle lamelle + sporata"}','f'),
('amanita_caesarea','amanita_muscaria','en','Caesar''s mushroom uniformly yellow (gills/stem/ring) with a sac-like white volva and a smooth orange-red cap; fly agaric white (gills/stem/ring) with a warty bulb and cap-skin flecks (possibly washed off).','Both inconspicuous and mild — smell is NOT a distinguishing feature.','Caesar''s mushroom thermophilic, in Switzerland extremely rare only in southern locations (Ticino); fly agaric common with birch/spruce throughout the country.','Both white spore print — NOT a distinguishing feature.','Never eat an orange-red mushroom without checking gills, stem AND ring: all white = fly agaric (toxic). Only uniformly YELLOW gills/stem/ring plus a sac-like white volva argue for Caesar''s mushroom — when in doubt, expert/mushroom inspection (VAPKO).','{"The fly agaric has PURE WHITE gills, a white stem and a white ring — Caesar''s mushroom has YELLOW gills, a yellow stem and a yellow ring","The fly agaric has a warty bulb with rings of warts; Caesar''s mushroom a thick-skinned, sac-like, lobed white volva (eggshell-like sheath)","The fly agaric cap bears white, washable flecks (veil remnants); Caesar''s mushroom cap is smooth orange-red without a fleck pattern","DANGER: a fly agaric washed clean by rain or faded loses its white flecks and can look orange — then only the gill/stem/ring colour (white!) and the warty bulb decide","Caesar''s mushroom is a pronounced rarity in Switzerland (only warm southern locations, especially Ticino) — an orange-red Amanita outside such locations is most probably a fly agaric"}','f'),
('amanita_caesarea','amanita_muscaria','es','Oronja completamente amarilla (láminas/pie/anillo) con volva blanca en forma de saco y sombrero liso rojo-anaranjado; matamoscas (Amanita muscaria) blanco (láminas/pie/anillo) con bulbo verrugoso y copos cuticulares (posiblemente lavados).','Ambos discretos y suaves — el olor NO es un criterio de distinción.','Oronja termófila, en Suiza extremadamente rara solo en zonas meridionales (Tesino); matamoscas frecuente bajo abedul/abeto rojo en todo el país.','Ambos esporada blanca — NO es un criterio de distinción.','Nunca comer un hongo rojo-anaranjado sin comprobar láminas, pie Y anillo: todo blanco = matamoscas (tóxico). Solo láminas/pie/anillo completamente AMARILLOS más una volva blanca en forma de saco abogan por la oronja — en caso de duda, experto/control de setas (VAPKO).','{"El matamoscas tiene láminas BLANCO PURO, pie blanco y anillo blanco — la oronja tiene láminas AMARILLAS, pie amarillo y anillo amarillo","El matamoscas tiene un bulbo verrugoso con cinturones de verrugas; la oronja una volva blanca gruesa, en forma de saco, lobulada (vaina como cáscara de huevo)","El sombrero del matamoscas lleva copos blancos lavables (restos de velo); el sombrero de la oronja es liso rojo-anaranjado sin patrón de copos","PELIGRO: un matamoscas lavado por la lluvia o desteñido pierde los copos blancos y puede parecer naranja — entonces solo deciden el color de láminas/pie/anillo (¡blanco!) y el bulbo verrugoso","La oronja es una rareza marcada en Suiza (solo zonas meridionales cálidas, sobre todo Tesino) — una Amanita rojo-anaranjada fuera de tales zonas es con alta probabilidad un matamoscas"}','f'),
('amanita_caesarea','amanita_muscaria','fr','Oronge entièrement jaune (lames/pied/anneau) avec une volve blanche en sac et un chapeau lisse rouge-orangé ; amanite tue-mouches blanche (lames/pied/anneau) avec un bulbe verruqueux et des flocons cuticulaires (éventuellement délavés).','Les deux discrètes et douces — l''odeur n''est PAS un critère de distinction.','Oronge thermophile, en Suisse extrêmement rare uniquement dans les régions méridionales (Tessin) ; amanite tue-mouches fréquente sous bouleau/épicéa dans tout le pays.','Les deux ont une sporée blanche — PAS un critère de distinction.','Ne jamais manger un champignon rouge-orangé sans vérifier les lames, le pied ET l''anneau : tout blanc = amanite tue-mouches (toxique). Seuls des lames/pied/anneau entièrement JAUNES plus une volve blanche en sac plaident pour l''oronge — en cas de doute, spécialiste/contrôle des champignons (VAPKO).','{"L''amanite tue-mouches a des lames BLANC PUR, un pied blanc et un anneau blanc — l''oronge a des lames JAUNES, un pied jaune et un anneau jaune","L''amanite tue-mouches a un bulbe verruqueux à bourrelets ; l''oronge une volve blanche épaisse, en sac, lobée (gaine en coquille d''œuf)","Le chapeau de l''amanite tue-mouches porte des flocons blancs lavables (restes de voile) ; le chapeau de l''oronge est lisse rouge-orangé sans motif de flocons","DANGER : une amanite tue-mouches délavée par la pluie ou décolorée perd ses flocons blancs et peut paraître orange — seules la couleur des lames/du pied/de l''anneau (blanc !) et le bulbe verruqueux décident alors","L''oronge est une rareté prononcée en Suisse (uniquement régions méridionales chaudes, surtout Tessin) — une amanite rouge-orangée hors de telles régions est très probablement une amanite tue-mouches"}','f'),
('amanita_caesarea','amanita_muscaria','it','Ovolo buono interamente giallo (lamelle/gambo/anello) con volva bianca a sacco e cappello liscio rosso-arancio; ovolo malefico (amanita muscaria) bianco (lamelle/gambo/anello) con bulbo verrucoso e fioccosità cuticolari (eventualmente dilavate).','Entrambi discreti e delicati — l''odore NON è un criterio distintivo.','Ovolo buono termofilo, in Svizzera estremamente raro solo nelle regioni meridionali (Ticino); amanita muscaria frequente sotto betulla/abete rosso in tutto il Paese.','Entrambi sporata bianca — NON un criterio distintivo.','Non mangiare mai un fungo rosso-arancio senza controllare lamelle, gambo E anello: tutto bianco = amanita muscaria (velenosa). Solo lamelle/gambo/anello interamente GIALLI più una volva bianca a sacco depongono per l''ovolo buono — nel dubbio esperto/controllo dei funghi (VAPKO).','{"L''amanita muscaria ha lamelle BIANCO PURO, gambo bianco e anello bianco — l''ovolo buono ha lamelle GIALLE, gambo giallo e anello giallo","L''amanita muscaria ha un bulbo verrucoso con cinture di verruche; l''ovolo buono una volva bianca spessa, a sacco, lobata (guaina a guscio d''uovo)","Il cappello dell''amanita muscaria porta fiocchi bianchi lavabili (resti di velo); il cappello dell''ovolo buono è liscio rosso-arancio senza disegno di fiocchi","PERICOLO: un''amanita muscaria dilavata dalla pioggia o scolorita perde i fiocchi bianchi e può apparire arancione — allora decidono solo il colore di lamelle/gambo/anello (bianco!) e il bulbo verrucoso","L''ovolo buono in Svizzera è una spiccata rarità (solo regioni meridionali calde, soprattutto Ticino) — un''Amanita rosso-arancio fuori da tali zone è con alta probabilità amanita muscaria"}','f'),
('amanita_crocea','amanita_gemmata','en','Toxic mushroom: yellowish cap with white flake remnants, (fleeting) ring on the stem, onion-like bulb with a rimmed sheath. Orange grisette (Amanita crocea): orange-yellow, grooved-rimmed, flake-free cap, NO ring, high free sheath.','Both inconspicuous — smell is NOT a distinguishing feature.','Both near broadleaf/conifer trees on rather acidic soil; habitat does not separate reliably.','Both white spore print — NOT a distinguishing feature.','Grisettes NEVER have a ring nor a rimmed bulb — any yellow Amanita WITH a ring collar and/or a bulb is suspicious (the gemmed Amanita / jonquil Amanita contains ibotenic acid/muscimol and muscarine) and does not belong in the basket.','{"The jonquil Amanita (Amanita gemmata) has an onion-like bulb with a rimmed, transient sheath AND a (often fleeting) ring — grisettes (including the orange grisette) NEVER have a ring","The grisette has a high, membranous, free sheath (volva) at the stem base, no bulb; cap margin distinctly grooved/furrowed","The cap of the toxic mushroom bears white, angular veil remnants (cap-skin flakes) and is deep to pale yellow (can fade in dry weather); the grisette cap is orange-yellow, flake-free, with a grooved margin","Stem of the grisette without a hanging ring collar; any ringed yellow Amanita is suspicious","Important: faded gemmata caps can appear paler/more similar — therefore ALWAYS check the ring + bulb shape, not just the cap colour"}','f'),
('amanita_crocea','amanita_gemmata','es','Hongo tóxico: sombrero amarillento con restos de copos blancos, anillo (fugaz) en el pie, bulbo en forma de cebolla con vaina marginada. Amanita azafranada (Amanita crocea): sombrero amarillo-anaranjado, de margen estriado-surcado, sin copos, SIN anillo, vaina libre alta.','Ambos discretos — el olor NO es un criterio de distinción.','Ambos junto a frondosas/coníferas en suelo más bien ácido; el hábitat no separa de forma fiable.','Ambos esporada blanca — NO es un criterio de distinción.','Las amanitas envainadas (Vaginatae) NUNCA tienen anillo ni bulbo marginado — toda amanita amarilla CON collar de anillo y/o bulbo es sospechosa (la amanita gemada / amanita amarilla contiene ácido iboténico/muscimol y muscarina) y no va al cesto.','{"La amanita gemada (Amanita gemmata) tiene un bulbo en forma de cebolla con vaina marginada y fugaz Y un anillo (a menudo fugaz) — las amanitas envainadas (incluida la amanita azafranada) NUNCA tienen anillo","La amanita envainada posee una vaina (volva) alta, membranosa y libre en la base del pie, ningún bulbo; margen del sombrero claramente estriado/surcado","El sombrero del hongo tóxico lleva restos de velo blancos y angulosos (copos cuticulares) y es de amarillo intenso a pálido (puede desteñirse con tiempo seco); el sombrero de la amanita azafranada es amarillo-anaranjado, sin copos, con margen estriado","Pie de la amanita envainada sin collar de anillo colgante; toda amanita amarilla con anillo es sospechosa","Importante: los sombreros de gemmata desteñidos pueden parecer más pálidos/más similares — por eso comprobar SIEMPRE el anillo + la forma del bulbo, no solo el color del sombrero"}','f'),
('amanita_crocea','amanita_gemmata','fr','Champignon toxique : chapeau jaunâtre avec restes de flocons blancs, anneau (fugace) sur le pied, bulbe en oignon à gaine marginée. Amanite safran : chapeau jaune-orangé, à marge striée-sillonnée, sans flocons, SANS anneau, haute gaine libre.','Les deux discrètes — l''odeur n''est PAS un critère de distinction.','Les deux près de feuillus/conifères sur sol plutôt acide ; l''habitat ne sépare pas de manière fiable.','Les deux ont une sporée blanche — PAS un critère de distinction.','Les amanites engainées n''ont JAMAIS d''anneau ni de bulbe marginé — toute amanite jaune AVEC manchette d''anneau et/ou bulbe est suspecte (l''amanite jonquille contient de l''acide iboténique/muscimol et de la muscarine) et ne va pas dans le panier.','{"L''amanite jonquille a un bulbe en oignon à gaine marginée et fugace ET un anneau (souvent fugace) — les amanites engainées (y compris l''amanite safran orangée) n''ont JAMAIS d''anneau","L''amanite engainée possède une gaine (volve) haute, membraneuse et libre à la base du pied, pas de bulbe ; marge du chapeau nettement striée/sillonnée","Le chapeau du champignon toxique porte des restes de voile blancs et anguleux (flocons cuticulaires) et est jaune vif à pâle (peut se décolorer par temps sec) ; le chapeau de l''amanite safran est jaune-orangé, sans flocons, à marge striée","Le pied de l''amanite engainée sans manchette d''anneau pendante ; toute amanite jaune annelée est suspecte","Important : les chapeaux de gemmata décolorés peuvent paraître plus pâles/plus semblables — donc TOUJOURS regarder l''anneau + la forme du bulbe, pas seulement la couleur du chapeau"}','f'),
('amanita_crocea','amanita_gemmata','it','Fungo velenoso: cappello giallastro con resti di fiocchi bianchi, anello (fugace) sul gambo, bulbo a cipolla con guaina marginata. Amanita fulva crocea (bubbola): cappello giallo-arancio, con margine striato-solcato, senza fiocchi, SENZA anello, alta guaina libera.','Entrambi discreti — l''odore NON è un criterio distintivo.','Entrambi presso latifoglie/conifere su suolo piuttosto acido; l''habitat non separa in modo affidabile.','Entrambi sporata bianca — NON un criterio distintivo.','Le amanite a guaina (Vaginatae) non hanno MAI anello né bulbo marginato — ogni amanita gialla CON collare ad anello e/o bulbo è sospetta (l''amanita gemmata contiene acido ibotenico/muscimolo e muscarina) e non va nel cesto.','{"L''amanita gemmata ha un bulbo a cipolla con guaina marginata e fugace E un anello (spesso fugace) — le amanite a guaina (compresa la bubbola giallo-arancio) non hanno MAI anello","L''amanita a guaina possiede una guaina (volva) alta, membranosa e libera alla base del gambo, nessun bulbo; margine del cappello nettamente striato/solcato","Il cappello del fungo velenoso porta resti di velo bianchi e angolosi (fiocchi cuticolari) ed è giallo intenso o pallido (può scolorire con tempo secco); il cappello della bubbola è giallo-arancio, senza fiocchi, con margine striato","Il gambo dell''amanita a guaina senza collare ad anello pendente; ogni amanita gialla con anello è sospetta","Importante: i cappelli di gemmata scoloriti possono apparire più pallidi/più simili — quindi guardare SEMPRE anello + forma del bulbo, non solo il colore del cappello"}','f'),
('amanita_fulva','amanita_gemmata','en','Tawny grisette red-brown, grooved, flake-free, ringless, with a high sheath; toxic mushroom yellowish, flaky, with a (fleeting) ring and a rimmed bulb.','Both inconspicuous — NOT a distinguishing feature.','Both near broadleaf/conifer trees on rather acidic soil; habitat does not separate.','Both white spore print — NOT a distinguishing feature.','Pay attention to ring and bulb: grisettes are always ringless with a high free sheath; a yellow Amanita with a ring or rimmed bulb is the toxic jonquil Amanita — when in doubt, leave it standing.','{"The tawny grisette is RINGLESS — the jonquil Amanita has a (often fleeting) hanging ring","Grisette with a high, free, red-brown-spotted sheath (volva) at the stem base instead of an onion-like bulb with a rimmed sheath","Cap of the grisette red-brown to foxy, smooth, strongly grooved at the margin, without veil flakes; toxic mushroom yellow (faded in dry weather) with white cap-skin flakes","Stem of the grisette without a mottled ring zone and without a collar","The tawny grisette should in any case only be eaten well cooked — raw, grisettes are indigestible"}','f'),
('amanita_fulva','amanita_gemmata','es','Amanita envainada leonada pardo-rojiza, estriada, sin copos, sin anillo, con vaina alta; hongo tóxico amarillento, escamoso, con anillo (fugaz) y bulbo marginado.','Ambos discretos — NO es un criterio de distinción.','Ambos junto a frondosas/coníferas en suelo más bien ácido; el hábitat no separa.','Ambos esporada blanca — NO es un criterio de distinción.','Prestar atención al anillo y al bulbo: las amanitas envainadas son siempre sin anillo con vaina libre alta; una amanita amarilla con anillo o bulbo marginado es la amanita gemada tóxica — en caso de duda, dejarla en el lugar.','{"La amanita leonada envainada es SIN ANILLO — la amanita gemada tiene un anillo colgante (a menudo fugaz)","Amanita envainada con vaina (volva) alta, libre, manchada de pardo-rojizo en la base del pie en lugar de un bulbo en forma de cebolla con vaina marginada","Sombrero de la amanita envainada pardo-rojizo a leonado, liso, fuertemente estriado en el margen, sin copos de velo; hongo tóxico amarillo (desteñido con tiempo seco) con copos cuticulares blancos","Pie de la amanita envainada sin zona de anillo jaspeada y sin collar","La amanita leonada envainada debe en cualquier caso comerse solo bien cocida — crudas, las amanitas envainadas son indigestas"}','f'),
('amanita_fulva','amanita_gemmata','fr','Amanite engainée brun-roux, striée, sans flocons, sans anneau, à haute gaine ; champignon toxique jaunâtre, floconneux, avec anneau (fugace) et bulbe marginé.','Les deux discrètes — PAS un critère de distinction.','Les deux près de feuillus/conifères sur sol plutôt acide ; l''habitat ne sépare pas.','Les deux ont une sporée blanche — PAS un critère de distinction.','Faire attention à l''anneau et au bulbe : les amanites engainées sont toujours sans anneau avec une haute gaine libre ; une amanite jaune avec anneau ou bulbe marginé est l''amanite jonquille toxique — en cas de doute, la laisser sur place.','{"L''amanite fauve engainée est SANS ANNEAU — l''amanite jonquille a un anneau pendant (souvent fugace)","Amanite engainée à gaine (volve) haute, libre, tachée de brun-roux à la base du pied au lieu d''un bulbe en oignon à gaine marginée","Chapeau de l''amanite engainée brun-roux à fauve, lisse, fortement strié au bord, sans flocons de voile ; champignon toxique jaune (décoloré par temps sec) avec flocons cuticulaires blancs","Pied de l''amanite engainée sans zone d''anneau tachetée et sans manchette","L''amanite fauve engainée ne doit de toute façon être mangée que bien cuite — crues, les amanites engainées sont indigestes"}','f'),
('amanita_fulva','amanita_gemmata','it','Amanita a guaina (bubbola fulva) bruno-rossiccia, striata, senza fiocchi, senza anello, con alta guaina; fungo velenoso giallastro, fioccoso, con anello (fugace) e bulbo marginato.','Entrambi discreti — NON un criterio distintivo.','Entrambi presso latifoglie/conifere su suolo piuttosto acido; l''habitat non separa.','Entrambi sporata bianca — NON un criterio distintivo.','Fare attenzione ad anello e bulbo: le amanite a guaina sono sempre senza anello con alta guaina libera; un''amanita gialla con anello o bulbo marginato è l''amanita gemmata velenosa — nel dubbio lasciarla sul posto.','{"La bubbola bruno-rossiccia è SENZA ANELLO — l''amanita gemmata ha un anello pendente (spesso fugace)","Amanita a guaina con guaina (volva) alta, libera, macchiata di bruno-rossiccio alla base del gambo invece di un bulbo a cipolla con guaina marginata","Cappello della bubbola bruno-rossiccio fino a fulvo, liscio, fortemente striato al margine, senza fiocchi di velo; fungo velenoso giallo (scolorito con tempo secco) con fiocchi cuticolari bianchi","Gambo della bubbola senza zona ad anello screziata e senza collare","La bubbola bruno-rossiccia va comunque mangiata solo ben cotta — crude le bubbole sono indigeste"}','f'),
('amanita_rubescens','amanita_franchetii','en','rubescens reddens at the flesh/bruised spots and has greyish-pink veil; franchetii does not redden and shows sulphur-yellow veil flakes plus a yellow-rimmed ring and yellow flocculose belts at the stem base.','Both inconspicuous-mushroomy; no reliable smell feature.','Both in warm broadleaf woodland; franchetii distinctly more thermophilic and rarer.','Both white spore print – no distinguishing feature.','Pressure test: the blusher (rubescens) ALWAYS reddens (cut/squeeze the flesh, wait a few minutes). If it stays whitish-yellow and the flakes are yellow, it is franchetii – leave it. Note: the panther cap (deadly) also belongs to this confusion group – beginners to mushroom inspection.','{"Blusher (rubescens): flesh and bruised spots REDDEN distinctly (wine-red), often reddish maggot tunnels – Franchet''s amanita (franchetii): flesh does NOT redden.","franchetii has yellow to sulphur-yellow veil flakes on the cap, a yellow-rimmed ring and yellowish flocculose belts at the stem base – rubescens has dirty-grey to reddish, NON-yellow veil remnants.","franchetii is poisonous/intolerable (strongly poisonous raw); rubescens only poisonous raw, edible when thoroughly cooked – when in doubt: no reddening + yellow flakes = do not eat.","franchetii looks like a ''small blusher without red'' – precisely the missing reddening plus the yellow flakes is the warning sign."}','f'),
('amanita_rubescens','amanita_franchetii','es','rubescens enrojece en la carne/zonas de presion y tiene velo gris-rosado; franchetii no enrojece y muestra floculos del velo amarillo azufre mas un anillo de borde amarillo y cinturones floconosos amarillos en la base del pie.','Ambos discretos-fungicos; ningun caracter olfativo fiable.','Ambos en bosques de frondosas calidos; franchetii claramente mas termofilo y mas raro.','Ambos esporada blanca – ningun caracter distintivo.','Prueba de presion: la amanita rojiza/rubescente (rubescens) enrojece SIEMPRE (cortar/aplastar la carne, esperar unos minutos). Si permanece blanco-amarillenta y los floculos son amarillos, es franchetii – dejarla. Nota: la amanita pantera (mortal) tambien pertenece a este grupo de confusion – principiantes al control de setas.','{"Amanita rojiza (rubescens): la carne y las zonas de presion ENROJECEN claramente (rojo vinoso), a menudo galerias de larvas rojizas – Amanita de Franchet (franchetii): la carne NO enrojece.","franchetii tiene floculos del velo amarillos a amarillo azufre sobre el sombrero, anillo de borde amarillo y cinturones floconosos amarillentos en la base del pie – rubescens tiene restos del velo gris sucio a rojizo, NO amarillos.","franchetii es toxica/mal tolerada (fuertemente toxica cruda); rubescens solo toxica cruda, comestible bien cocida – en caso de duda: sin enrojecimiento + floculos amarillos = no comer.","franchetii parece una ''pequena amanita rojiza sin rojo'' – justamente la ausencia de enrojecimiento mas los floculos amarillos es la senal de advertencia."}','f'),
('amanita_rubescens','amanita_franchetii','fr','rubescens rougit à la chair/aux points de pression et a un voile gris-rosé ; franchetii ne rougit pas et montre des flocons de voile jaune soufre plus un anneau bordé de jaune et des ceintures de flocons jaunes à la base du pied.','Les deux discrètes et fongiques ; pas de critère olfactif fiable.','Les deux dans les forêts de feuillus chaudes ; franchetii nettement plus thermophile et plus rare.','Les deux à sporée blanche – pas un critère distinctif.','Test de pression : l''amanite rougissante ROUGIT TOUJOURS (couper/presser la chair, attendre quelques minutes). Si cela reste blanc-jaunâtre et que les flocons sont jaunes, c''est franchetii – laisser sur place. Attention : l''amanite panthère (mortelle) appartient aussi à ce groupe de confusion – débutants au contrôle des champignons.','{"Amanite rougissante (rubescens) : chair et points de pression ROUGISSENT nettement (rouge vineux), souvent galeries de vers rougeâtres – Amanite à flocons jaunes/rugueuse (franchetii) : chair ne rougit PAS.","franchetii a des flocons de voile jaunes à jaune soufre sur le chapeau, un anneau bordé de jaune et des ceintures de flocons jaunâtres à la base du pied – rubescens a des restes de voile gris sale à rougeâtre, NON jaunes.","franchetii est toxique/mal tolérée (crue fortement toxique) ; rubescens seulement toxique crue, comestible bien cuite – en cas de doute : pas de rougissement + flocons jaunes = ne pas manger.","franchetii ressemble à une « petite amanite rougissante sans rouge » – c''est précisément l''absence de rougissement plus les flocons jaunes qui est l''avertissement."}','f'),
('amanita_rubescens','amanita_franchetii','it','rubescens arrossa alla carne/nei punti di pressione e ha velo grigio-rosa; franchetii non arrossa e mostra fioccosita del velo giallo zolfo piu un anello bordato di giallo e cinture fioccose gialle alla base del gambo.','Entrambi inappariscenti-fungini; nessun carattere olfattivo affidabile.','Entrambi in boschi di latifoglie caldi; franchetii nettamente piu termofilo e piu raro.','Entrambi sporata bianca – nessun carattere distintivo.','Test di pressione: l''amanita rosseggiante (rubescens) arrossa SEMPRE (tagliare/schiacciare la carne, attendere alcuni minuti). Se rimane bianco-giallastra e le fioccosita sono gialle, e franchetii – lasciarla. Nota: anche l''amanita panterina (mortale) appartiene a questo gruppo di confusione – principianti al controllo dei funghi.','{"Amanita rosseggiante (rubescens): la carne e i punti di pressione ARROSSANO nettamente (rosso vinoso), spesso gallerie di larve rossastre – Amanita di Franchet (franchetii): la carne NON arrossa.","franchetii ha fioccosita del velo gialle a giallo zolfo sul cappello, anello bordato di giallo e cinture fioccose giallastre alla base del gambo – rubescens ha resti del velo grigio sporco a rossastro, NON gialli.","franchetii e tossica/mal tollerata (fortemente tossica da cruda); rubescens solo tossica da cruda, commestibile ben cotta – nel dubbio: nessun arrossamento + fioccosita gialle = non mangiare.","franchetii sembra una ''piccola amanita rosseggiante senza rosso'' – proprio l''assenza di arrossamento piu le fioccosita gialle e l''avvertimento."}','f'),
('amanita_rubescens','amanita_gemmata','en','Blusher with pinkish reddening at pressure/bite marks and a strongly grooved ring (cap colour variable); toxic mushroom usually bright yellow, not reddening, with a fleeting ring.','Both inconspicuous and mild — NOT a reliable distinguishing feature.','Both in broadleaf/conifer forest; habitat does not separate.','Both white spore print — NOT a distinguishing feature.','The blusher MUST redden and is only edible well cooked — a yellow Amanita that does NOT redden never belongs in the basket (jonquil Amanita: ibotenic acid/muscimol and muscarine). Raw, the blusher is also toxic.','{"The blusher reddens distinctly to wine-red/flesh-pink when injured/grub-eaten — the jonquil Amanita NEVER reddens, its flesh stays white-yellowish (most reliable distinguishing feature)","The blusher has a robust ring, grooved (ridged) on the upper side; the ring of the toxic mushroom is thin and transient (often absent)","Cap colour of the blusher very variable (whitish, brown-yellowish, flesh-pink to red-brown) — therefore do NOT rely on colour alone; toxic mushroom usually deep lemon/ochre-yellow, fading in dry weather","Bulb of the blusher rounded with veil rings (without a rimmed sheath); toxic mushroom with an onion-like bulb and a rimmed remnant sheath","Stem base/bite marks of the blusher often tinged pink/wine-red, not in the toxic mushroom"}','f'),
('amanita_rubescens','amanita_gemmata','es','Amanita rojiza (Amanita rubescens) con enrojecimiento rosado en los puntos de presión/mordedura y anillo fuertemente estriado (color del sombrero variable); hongo tóxico por lo general amarillo vivo, que no enrojece, con anillo fugaz.','Ambos discretos y suaves — NO es un criterio de distinción fiable.','Ambos en bosque de frondosas/coníferas; el hábitat no separa.','Ambos esporada blanca — NO es un criterio de distinción.','La amanita rojiza DEBE enrojecer y solo es comestible bien cocida — una amanita amarilla que NO enrojece nunca va al cesto (amanita gemada: ácido iboténico/muscimol y muscarina). Cruda, la amanita rojiza también es tóxica.','{"La amanita rojiza enrojece claramente a rojo vinoso/rosa carne al ser herida/comida por larvas — la amanita gemada NUNCA enrojece, su carne permanece blanco-amarillenta (criterio de distinción más fiable)","La amanita rojiza tiene un anillo robusto, estriado (acanalado) por la parte superior; el anillo del hongo tóxico es fino y fugaz (a menudo ausente)","Color del sombrero de la amanita rojiza muy variable (blanquecino, pardo-amarillento, rosa carne a pardo-rojizo) — por eso NO fiarse solo del color; hongo tóxico por lo general amarillo limón/ocre intenso, que se destiñe con tiempo seco","Bulbo de la amanita rojiza redondeado con cinturones de velo (sin vaina marginada); hongo tóxico con bulbo en forma de cebolla y resto de vaina marginada","Base del pie/marcas de mordedura de la amanita rojiza a menudo teñidas de rosa/rojo vinoso, no en el hongo tóxico"}','f'),
('amanita_rubescens','amanita_gemmata','fr','Amanite rougissante avec rougissement rosé aux points de pression/morsure et anneau fortement strié (couleur du chapeau variable) ; champignon toxique généralement jaune vif, ne rougissant pas, à anneau fugace.','Les deux discrètes et douces — PAS un critère de distinction fiable.','Les deux en forêt de feuillus/conifères ; l''habitat ne sépare pas.','Les deux ont une sporée blanche — PAS un critère de distinction.','L''amanite rougissante DOIT rougir et n''est comestible que bien cuite — une amanite jaune qui NE rougit PAS ne va jamais dans le panier (amanite jonquille : acide iboténique/muscimol et muscarine). Crue, l''amanite rougissante est aussi toxique.','{"L''amanite rougissante rougit nettement en rouge vineux/rose chair en cas de blessure/morsure de larve — l''amanite jonquille ne rougit JAMAIS, sa chair reste blanc-jaunâtre (critère de distinction le plus fiable)","L''amanite rougissante a un anneau robuste, strié (cannelé) sur le dessus ; l''anneau du champignon toxique est mince et fugace (souvent absent)","Couleur du chapeau de l''amanite rougissante très variable (blanchâtre, brun-jaunâtre, rose chair à brun-roux) — ne donc PAS se fier à la seule couleur ; champignon toxique généralement jaune citron/ocre soutenu, se décolorant par temps sec","Bulbe de l''amanite rougissante arrondi avec bourrelets de voile (sans gaine marginée) ; champignon toxique à bulbe en oignon et reste de gaine marginée","Base du pied/points de morsure de l''amanite rougissante souvent teintés de rose/rouge vineux, pas chez le champignon toxique"}','f'),
('amanita_rubescens','amanita_gemmata','it','Tignosa vinata con arrossamento rosato nei punti di pressione/morso e anello fortemente striato (colore del cappello variabile); fungo velenoso di solito giallo vivo, non arrossante, con anello fugace.','Entrambi discreti e delicati — NON un criterio distintivo affidabile.','Entrambi in bosco di latifoglie/conifere; l''habitat non separa.','Entrambi sporata bianca — NON un criterio distintivo.','La tignosa vinata DEVE arrossare ed è commestibile solo ben cotta — un''amanita gialla che NON arrossa non va mai nel cesto (amanita gemmata: acido ibotenico/muscimolo e muscarina). Cruda anche la tignosa vinata è velenosa.','{"La tignosa vinata arrossa nettamente in rosso vinoso/rosa carne in caso di ferita/morso di larva — l''amanita gemmata non arrossa MAI, la sua carne resta bianco-giallastra (criterio distintivo più affidabile)","La tignosa vinata ha un anello robusto, striato (scanalato) superiormente; l''anello del fungo velenoso è sottile e fugace (spesso assente)","Colore del cappello della tignosa vinata molto variabile (biancastro, bruno-giallastro, rosa carne fino a bruno-rossiccio) — quindi NON affidarsi solo al colore; fungo velenoso di solito giallo limone/ocra intenso, che scolorisce con tempo secco","Bulbo della tignosa vinata arrotondato con cinture di velo (senza guaina marginata); fungo velenoso con bulbo a cipolla e resto di guaina marginata","Base del gambo/punti di morso della tignosa vinata spesso tinti di rosa/rosso vinoso, non nel fungo velenoso"}','f'),
('amanita_rubescens','amanita_pantherina','en','The reddening test + ring (grooved vs. smooth) + bulb are decisive.','barely distinguishable','both all forest types','both white','The Blusher (Amanita rubescens) is for experienced foragers only. Check ALL features TOGETHER (reddening + grooved ring + bulb without a rimmed sheath).','{"Blusher (Amanita rubescens): flesh reddens (especially at the stem base / maggot tunnels), grooved ring, grey veil flakes","Panther cap (Amanita pantherina): flesh NEVER reddens, smooth ring, pure-white flakes, rimmed-bulbous base, toxins heat-stable"}','t'),
('amanita_rubescens','amanita_pantherina','es','Decide la prueba de enrojecimiento + el anillo (estriado vs. liso) + el bulbo.','apenas distinguibles','ambos en todos los tipos de bosque','ambos blanco','La amanita rojiza (Amanita rubescens) solo para personas con experiencia. Comprobar TODAS las características EN CONJUNTO (enrojecimiento + anillo estriado + bulbo sin vaina con reborde).','{"Amanita rojiza (Amanita rubescens): la carne enrojece (sobre todo en la base del pie / galerías de larvas), anillo estriado, copos del velo grises","Amanita pantera (Amanita pantherina): la carne NUNCA enrojece, anillo liso, copos blanco puro, base bulbosa con reborde, toxinas termoestables"}','t'),
('amanita_rubescens','amanita_pantherina','fr','Le test de rougissement + l''anneau (strié vs. lisse) + le bulbe sont décisifs.','à peine distinguables','les deux dans tous les types de forêt','les deux blanc','L''amanite rougissante n''est réservée qu''aux personnes expérimentées. Vérifier TOUS les caractères ENSEMBLE (rougissement + anneau strié + bulbe sans gaine marginée).','{"Amanite rougissante : la chair rougit (surtout à la base du pied/dans les galeries de larves), anneau strié, flocons de vélum gris","Amanite panthère : la chair ne rougit JAMAIS, anneau lisse, flocons d''un blanc pur, base bulbeuse marginée, toxines thermostables"}','t'),
('amanita_rubescens','amanita_pantherina','it','Decidono il test dell''arrossamento + l''anello (striato vs. liscio) + il bulbo.','quasi indistinguibili','entrambi in tutti i tipi di bosco','entrambi bianco','L''Amanita rubescens (tignosa vinata) solo per esperti. Verificare TUTTI i caratteri INSIEME (arrossamento + anello striato + bulbo senza guaina marginata).','{"Tignosa vinata (Amanita rubescens): la carne arrossa (soprattutto base del gambo/gallerie dei vermi), anello striato, fioccosità del velo grigia","Tignosa bigia (Amanita pantherina): la carne NON arrossa MAI, anello liscio, fioccosità bianca pura, base bulbosa marginata, tossine termostabili"}','t'),
('amanita_rubescens','amanita_porphyria','en','porphyria greyish-brown with a coppery-violet porphyry tone, grey veil remnants and a sharply rimmed bulb, no reddening; rubescens fleshy-brown-reddish with a clavate, non-rimmed bulb and distinct reddening.','porphyria distinctly musty of raw potatoes/potato sprouts; rubescens neutral-mushroomy.','porphyria mainly in coniferous woodland on acidic soil; rubescens more widely distributed in broadleaf and coniferous woodland.','Both white spore print (porphyria amyloid) – microscopic, no field feature.','The bulb and pressure test decide: sharply rimmed bulb + potato/radish smell + no reddening = porphyria, leave it. The blusher always reddens. When in doubt have it checked.','{"Grey veiled amanita / porphyry amanita (porphyria): sharply set-off, rimmed-bulbous stem base and coppery violet-greyish-brown (porphyry-coloured) cap tone, flesh does NOT redden – Blusher (rubescens): clavately thickened, NON-rimmed bulb, flesh and bruised spots REDDEN distinctly.","porphyria smells characteristically musty of raw potatoes/potato sprouts (radish/potato note) – rubescens inconspicuous-mushroomy.","porphyria contains bufotenine plus heat-stable gastrointestinal toxins and is classified as poisonous – do not eat; rubescens only poisonous raw, edible when thoroughly cooked.","Missing reddening + potato/radish smell + sharply rimmed bulb = porphyria, not the blusher."}','f'),
('amanita_rubescens','amanita_porphyria','es','porphyria gris-parda con tono porfido cobrizo-violeta, restos del velo grises y bulbo de borde neto, sin enrojecimiento; rubescens pardo-carne-rojiza con bulbo claviforme no marginado y enrojecimiento claro.','porphyria claramente rancio a patatas crudas/brotes de patata; rubescens neutro-fungico.','porphyria sobre todo en bosques de coniferas en suelo acido; rubescens mas ampliamente distribuida en bosques de frondosas y coniferas.','Ambos esporada blanca (porphyria amiloide) – microscopica, en el campo ningun caracter.','El bulbo y la prueba de presion deciden: bulbo de borde neto + olor a patata/rabano + sin enrojecimiento = porphyria, dejarla. La amanita rojiza siempre enrojece. En caso de duda, hacerla revisar.','{"Amanita porfido (porphyria): base del pie con bulbo netamente marginado y sombrero de tono cobrizo violeta-gris-pardo (color porfido), la carne NO enrojece – Amanita rojiza (rubescens): bulbo claviforme engrosado, NO marginado, la carne y las zonas de presion ENROJECEN claramente.","porphyria huele de forma caracteristica rancio a patatas crudas/brotes de patata (nota rabano/patata) – rubescens discreto-fungico.","porphyria contiene bufotenina mas toxinas gastrointestinales termoestables y esta clasificada como toxica – no comer; rubescens solo toxica cruda, comestible bien cocida.","Ausencia de enrojecimiento + olor a patata/rabano + bulbo de borde neto = porphyria, no la amanita rojiza."}','f'),
('amanita_rubescens','amanita_porphyria','fr','porphyria gris-brun avec une teinte porphyre cuivré-violacée, des restes de voile gris et un bulbe à bord marginé, pas de rougissement ; rubescens brun-chair-rougeâtre avec un bulbe en massue, non marginé, et un rougissement net.','porphyria nettement terne, de pommes de terre crues/germes de pommes de terre ; rubescens neutre-fongique.','porphyria principalement dans les forêts de conifères sur sol acide ; rubescens plus largement répandue dans les forêts de feuillus et de conifères.','Les deux à sporée blanche (porphyria amyloïde) – microscopique, pas de critère de séparation sur le terrain.','Le bulbe et le test de pression décident : bulbe nettement marginé + odeur de pomme de terre/radis + pas de rougissement = porphyria, laisser sur place. L''amanite rougissante rougit toujours. En cas de doute, au contrôle des champignons.','{"Amanite porphyre (porphyria) : base du pied bulbeuse, nettement marginée, et chapeau gris-brun violacé-cuivré (couleur porphyre), chair ne rougit PAS – Amanite rougissante (rubescens) : bulbe épaissi en massue, NON marginé, chair et points de pression ROUGISSENT nettement.","porphyria sent de façon caractéristique le terne, les pommes de terre crues/germes de pommes de terre (note radis/pomme de terre) – rubescens discrète-fongique.","porphyria contient de la bufoténine plus des poisons gastro-intestinaux thermostables et est classée toxique – ne pas manger ; rubescens seulement toxique crue, comestible bien cuite.","Absence de rougissement + odeur de pomme de terre/radis + bulbe nettement marginé = porphyria, pas l''amanite rougissante."}','f'),
('amanita_rubescens','amanita_porphyria','it','porphyria grigio-bruna con tono porfido rame-violetto, resti del velo grigi e bulbo a bordo netto, senza arrossamento; rubescens bruno-carne-rossastra con bulbo claviforme non bordato e netto arrossamento.','porphyria nettamente smorto, odore di patate crude/germogli di patata; rubescens neutro-fungino.','porphyria soprattutto in boschi di conifere su suolo acido; rubescens piu ampiamente diffusa in boschi di latifoglie e conifere.','Entrambi sporata bianca (porphyria amiloide) – microscopica, sul campo nessun carattere.','Il bulbo e il test di pressione decidono: bulbo a bordo netto + odore di patata/ravanello + nessun arrossamento = porphyria, lasciarla. L''amanita rosseggiante arrossa sempre. Nel dubbio far controllare.','{"Amanita porfido (porphyria): base del gambo a bulbo nettamente bordato e cappello di tono rame violetto-grigio-bruno (color porfido), la carne NON arrossa – Amanita rosseggiante (rubescens): bulbo claviforme ingrossato, NON bordato, la carne e i punti di pressione ARROSSANO nettamente.","porphyria odora in modo caratteristico smorto di patate crude/germogli di patata (nota ravanello/patata) – rubescens inappariscente-fungino.","porphyria contiene bufotenina piu tossine gastrointestinali termostabili ed e classificata tossica – non mangiare; rubescens solo tossica da cruda, commestibile ben cotta.","Assenza di arrossamento + odore di patata/ravanello + bulbo a bordo netto = porphyria, non l''amanita rosseggiante."}','f'),
('amanita_rubescens','fliegenpilz-roetlich','en','The royal fly agaric has a leather-brown to dark grey-brown cap with yellowish-grey veil flecks and a yellow to yellow-brown zone beneath the cap skin; the blusher reddens pink to wine-red at feeding and pressure spots and does not show this yellow subcuticular zone.','Both smell inconspicuously mushroomy — smell does NOT help to tell them apart here, so the reddening and the yellow layer beneath the cap skin are the decisive features.','The royal fly agaric only in acidic coniferous forest as a spruce symbiont (more in upland areas); the blusher widely distributed in deciduous, coniferous and mixed forest, also at lower elevations.','Both are white-spored — the spore print does not separate the two; decisive are the reddening and the yellow subcuticular zone beneath the cap skin.','With brown-capped amanitas ALWAYS cut the flesh and observe for 10-15 min: if it reddens pink/wine-red = blusher; if it stays white with a yellow layer directly beneath the cap skin = poisonous royal fly agaric, leave it standing. When in doubt with gilled amanitas, generally refrain.','{"The blusher (edible) reddens markedly on injury, pressure and maggot feeding to flesh- to wine-red/pink — the brown royal fly agaric (Amanita regalis) NEVER does this.","Royal fly agaric: white flesh, but directly beneath the cap skin a characteristic yellow to yellow-brown zone (visible in longitudinal/cross section) — in the blusher this yellow layer is absent.","Cap colour of the royal fly agaric: leather-brown to dark grey-brown with yellowish to grey-white, wipeable veil flecks; blusher: reddish-brown to flesh-brownish with grey to reddish-tinged skin remnants.","The royal fly agaric grows as a spruce symbiont almost only in acidic coniferous forest (more upland/higher elevations) — the blusher prefers deciduous and mixed forest, also at lower altitudes and widely distributed.","The royal fly agaric contains ibotenic acid/muscimol like the red fly agaric (pantherina syndrome: confusion, hallucinations, convulsions, in larger amounts circulatory collapse/respiratory paralysis) — not an edible mushroom, not even cooked."}','f'),
('amanita_rubescens','fliegenpilz-roetlich','es','La amanita real tiene un sombrero pardo cuero a pardo-gris oscuro con copos del velo gris-amarillentos y una zona amarilla a pardo-amarilla bajo la cutícula; la amanita rojiza enrojece de rosa a rojo vinoso en las zonas roídas y de presión y no muestra esta zona subcuticular amarilla.','Ambas huelen a hongo de forma poco llamativa — el olor NO ayuda aquí a distinguirlas, por lo que el enrojecimiento y la capa amarilla bajo la cutícula son los caracteres decisivos.','La amanita real solo en bosque ácido de coníferas como simbionte del abeto rojo (más bien en montaña); la amanita rojiza ampliamente distribuida en bosque de frondosas, coníferas y mixto, también a menor altitud.','Ambas de esporas blancas — la esporada no separa a las dos; decisivos son el enrojecimiento y la zona subcuticular amarilla bajo la cutícula.','Con las amanitas de sombrero pardo SIEMPRE cortar la carne y observar 10-15 min: si enrojece rosa/rojo vinoso = amanita rojiza; si permanece blanca con una capa amarilla justo bajo la cutícula = amanita real tóxica, dejarla. En caso de duda con las amanitas laminadas, renunciar por regla general.','{"La amanita rojiza (comestible) enrojece netamente, por herida, presión y ataque de gusanos, de rojo carne a rojo vinoso/rosa — la amanita real parda (Amanita regalis) NUNCA lo hace.","Amanita real: carne blanca, pero justo bajo la cutícula una característica zona amarilla a pardo-amarilla (visible en sección longitudinal/transversal) — en la amanita rojiza falta esta capa amarilla.","Color del sombrero de la amanita real: pardo cuero a pardo-gris oscuro con copos del velo amarillentos a gris-blancos, que se pueden limpiar; amanita rojiza: pardo-rojizo a pardo carne con restos de piel grises a teñidos de rojizo.","La amanita real crece como simbionte del abeto rojo casi solo en bosque ácido de coníferas (más bien montaña/altitudes elevadas) — la amanita rojiza prefiere bosques de frondosas y mixtos, también a baja altitud y ampliamente distribuida.","La amanita real contiene ácido iboténico/muscimol como la amanita matamoscas roja (síndrome panterínico: confusión, alucinaciones, convulsiones, en mayores cantidades colapso circulatorio/parálisis respiratoria) — no es un hongo comestible, ni siquiera cocinado."}','f'),
('amanita_rubescens','fliegenpilz-roetlich','fr','L''amanite royale a un chapeau brun cuir à brun-gris foncé avec des flocons de voile gris-jaunâtre et une zone jaune à brun-jaune sous la cuticule; l''amanite rougissante rougit en rose à rouge vineux aux endroits rongés ou pressés et ne présente pas cette zone sous-cuticulaire jaune.','Toutes deux ont une odeur fongique discrète — l''odeur n''aide PAS ici à les distinguer, ce sont donc le rougissement et la couche jaune sous la cuticule qui sont les caractères décisifs.','L''amanite royale uniquement en forêt de conifères acide comme symbiote de l''épicéa (plutôt en montagne); l''amanite rougissante largement répandue en forêt de feuillus, de conifères et mixte, aussi à basse altitude.','Les deux ont une sporée blanche — la couleur de la sporée ne les sépare pas; déterminants sont le rougissement et la zone sous-cuticulaire jaune sous la cuticule.','Chez les amanites à chapeau brun, TOUJOURS couper la chair et observer 10-15 min: si elle rougit rose/rouge vineux = amanite rougissante; si elle reste blanche avec une couche jaune juste sous la cuticule = amanite royale toxique, à laisser. En cas de doute sur les amanites à lames, renoncer en règle générale.','{"L''amanite rougissante (comestible) rougit nettement, lors de blessure, pression et attaque de vers, en rouge chair à rouge vineux/rose — l''amanite royale brune (Amanita regalis) ne le fait JAMAIS.","Amanite royale: chair blanche, mais juste sous la cuticule une zone jaune à brun-jaune caractéristique (visible en coupe longitudinale/transversale) — chez l''amanite rougissante cette couche jaune est absente.","Couleur du chapeau de l''amanite royale: brun cuir à brun-gris foncé avec des flocons de voile jaunâtres à gris-blanc, essuyables; amanite rougissante: brun-rougeâtre à brun chair avec des restes de voile gris à teintés de rougeâtre.","L''amanite royale pousse comme symbiote de l''épicéa presque uniquement en forêt de conifères acide (plutôt montagne/altitudes élevées) — l''amanite rougissante préfère les forêts de feuillus et mixtes, aussi à basse altitude et largement répandue.","L''amanite royale contient de l''acide iboténique/muscimol comme l''amanite tue-mouches rouge (syndrome panthérinien: confusion, hallucinations, convulsions, à fortes doses collapsus circulatoire/paralysie respiratoire) — pas un champignon comestible, même cuit."}','f'),
('amanita_rubescens','fliegenpilz-roetlich','it','L''ovolo reale ha un cappello da bruno cuoio a bruno-grigio scuro con fiocchi del velo grigio-giallastri e una zona gialla o bruno-gialla sotto la cuticola; l''amanita rosata arrossa in rosa fino a rosso vinoso nei punti rosicchiati e di pressione e non mostra questa zona sottocuticolare gialla.','Entrambe hanno un odore fungino poco appariscente — l''odore qui NON aiuta a distinguerle, perciò l''arrossamento e lo strato giallo sotto la cuticola sono i caratteri decisivi.','L''ovolo reale solo nel bosco acido di conifere come simbionte dell''abete rosso (piuttosto in montagna); l''amanita rosata ampiamente diffusa in boschi di latifoglie, conifere e misti, anche a quote più basse.','Entrambe a spore bianche — il colore della sporata non le separa; decisivi sono l''arrossamento e la zona sottocuticolare gialla sotto la cuticola.','Nelle amanite dal cappello bruno SEMPRE tagliare la carne e osservare 10-15 min: se arrossa rosa/rosso vinoso = amanita rosata; se resta bianca con uno strato giallo subito sotto la cuticola = ovolo reale tossico, da lasciare. Nel dubbio, con le amanite lamellate in generale rinunciare.','{"L''amanita rosata (commestibile) arrossa nettamente, per ferita, pressione e attacco di larve, in rosso carne fino a rosso vinoso/rosa — l''ovolo reale bruno (Amanita regalis) non lo fa MAI.","Ovolo reale: carne bianca, ma subito sotto la cuticola una caratteristica zona gialla fino a bruno-gialla (visibile in sezione longitudinale/trasversale) — nell''amanita rosata questo strato giallo manca.","Colore del cappello dell''ovolo reale: da bruno cuoio a bruno-grigio scuro con fiocchi del velo giallastri fino a grigio-bianchi, asportabili; amanita rosata: da bruno-rossastro a bruno carnicino con residui di velo grigi fino a sfumati di rossastro.","L''ovolo reale cresce come simbionte dell''abete rosso quasi solo nel bosco acido di conifere (piuttosto montagna/quote elevate) — l''amanita rosata preferisce boschi di latifoglie e misti, anche a quote basse e ampiamente diffusa.","L''ovolo reale contiene acido ibotenico/muscimolo come l''ovolo malefico rosso (sindrome panterinica: confusione, allucinazioni, convulsioni, in dosi maggiori collasso circolatorio/paralisi respiratoria) — non è un fungo commestibile, nemmeno cotto."}','f'),
('amanita_strobiliformis','amanita_echinocephala','en','echinocephala bears firm, pointed-pyramidal, NON-wipeable veil spines and tends to discolour dirty greenish-grey; strobiliformis has soft, fringed-tattered, wipeable veil flakes on a white-greyish-brownish cap, without a green tone.','echinocephala insignificant to faintly unpleasant; strobiliformis neutral with a slight radish note – smell alone is NOT a reliable feature.','Both thermophilic on calcareous soil in broadleaf woodland – habitat does not separate them, only the veil does.','Both white spore print – no distinguishing feature.','For any white, warty large amanita on lime: check the veil remnants – hard, non-wipeable pyramidal spines = hands off. The veil form can be washed out by weather – when in doubt ALWAYS have it checked (VAPKO).','{"Solitary lepidella / hedgehog amanita (echinocephala): pointed, pyramidal-spiny, NON-wipeable veil remnants on the cap – Warted amanita (strobiliformis): fringed-tattered, soft, wipeable veil flakes, NO hard pyramidal spines.","echinocephala smells insignificant to faintly unpleasant and often discolours dirty greenish-grey at the stem base and gills – strobiliformis smells neutral with a faint radish component, gills pure white to cream.","echinocephala is classified as (mildly) poisonous / gastrointestinally intolerable – to be safe, NEVER eat it.","Both whitish, large, warty and on calcareous soil – only the veil form (hard spines vs soft fringes) separates them reliably."}','f'),
('amanita_strobiliformis','amanita_echinocephala','es','echinocephala lleva aguijones del velo firmes, puntiagudos y piramidales, NO eliminables al frotar, y tiende a colorearse de gris-verdoso sucio; strobiliformis lleva floculos del velo blandos, deshilachados-desgarrados, eliminables al frotar sobre un sombrero blanco-grisaceo-parduzco, sin tono verde.','echinocephala insignificante a debilmente desagradable; strobiliformis neutro con leve nota de rabano – el olor por si solo NO es un caracter seguro.','Ambos termofilos en suelo calcareo en bosque de frondosas – el habitat no los separa, solo el velo.','Ambos esporada blanca – ningun caracter distintivo.','Para cualquier amanita blanca, verrugosa y grande sobre caliza: examinar los restos del velo – aguijones piramidales duros y no eliminables al frotar = no tocar. La forma del velo puede estar deslavada por el tiempo – en caso de duda SIEMPRE hacerla revisar (VAPKO).','{"Amanita de cabeza espinosa (echinocephala): restos del velo puntiagudos, piramidales-espinosos, NO eliminables al frotar sobre el sombrero – Amanita deshilachada (strobiliformis): floculos del velo deshilachados-desgarrados, blandos, eliminables al frotar, NINGUN aguijon piramidal duro.","echinocephala huele insignificante a debilmente desagradable y a menudo se colorea de gris-verdoso sucio en la base del pie y las laminas – strobiliformis huele neutro con debil componente de rabano, laminas blanco puro a crema.","echinocephala esta clasificada como (debilmente) toxica / mal tolerada a nivel gastrointestinal – por seguridad, NUNCA consumirla.","Ambas blanquecinas, grandes, verrugosas y sobre suelo calcareo – solo la forma del velo (aguijones duros vs flecos blandos) las separa con seguridad."}','f'),
('amanita_strobiliformis','amanita_echinocephala','fr','echinocephala porte des aiguillons de voile fermes, en pyramide pointue, non essuyables, et tend à se décolorer en gris-verdâtre sale ; strobiliformis présente des flocons de voile mous, frangés-déchiquetés, essuyables, sur un chapeau blanc-gris-brunâtre, sans teinte verte.','echinocephala insignifiante à faiblement désagréable ; strobiliformis neutre avec une légère note de radis – l''odeur seule n''est PAS un critère de séparation sûr.','Les deux thermophiles sur sol calcaire en forêt de feuillus – l''habitat ne sépare pas, seul le voile le fait.','Les deux à sporée blanche – pas un critère distinctif.','Pour toute amanite blanche et verruqueuse sur calcaire : vérifier les restes de voile – aiguillons pyramidaux durs, non essuyables = ne pas toucher. La forme du voile peut être délavée par les intempéries – en cas de doute, TOUJOURS au contrôle des champignons (VAPKO).','{"Amanite à tête échinée (echinocephala) : restes de voile en pyramide pointue et épineuse, NON essuyables sur le chapeau – Amanite à voile frangé (strobiliformis) : flocons de voile frangés-déchiquetés, mous, essuyables, AUCUN aiguillon pyramidal dur.","echinocephala sent l''insignifiant à faiblement désagréable et se décolore souvent en gris-verdâtre sale à la base du pied et aux lamelles – strobiliformis sent neutre avec une faible composante de radis, lamelles blanc pur à crème.","echinocephala est classée comme (faiblement) toxique / mal tolérée digestivement – par sécurité, ne JAMAIS la prendre comme comestible.","Les deux blanchâtres, grandes, verruqueuses et sur sol calcaire – seule la forme du voile (aiguillons durs vs. franges molles) les sépare sûrement."}','f'),
('amanita_strobiliformis','amanita_echinocephala','it','echinocephala porta aculei del velo sodi, appuntiti e piramidali, NON asportabili, e tende a colorarsi di grigio-verde sporco; strobiliformis porta fioccosita del velo molli, sfrangiate-lacere, asportabili su cappello bianco-grigio-brunastro, senza tono verde.','echinocephala insignificante o debolmente sgradevole; strobiliformis neutro con leggera nota di ravanello – l''odore da solo NON e un carattere sicuro.','Entrambi termofili su suolo calcareo nel bosco di latifoglie – l''habitat non separa, solo il velo.','Entrambi sporata bianca – nessun carattere distintivo.','Per ogni grande amanita bianca e verrucosa su calcare: esaminare i resti del velo – aculei piramidali duri e non asportabili = non toccare. La forma del velo puo essere dilavata dal tempo – nel dubbio SEMPRE far controllare (VAPKO).','{"Amanita dalla testa spinosa (echinocephala): resti del velo appuntiti, piramidali-spinosi, NON asportabili sul cappello – Amanita sfrangiata (strobiliformis): fioccosita del velo sfrangiate-lacere, molli, asportabili, NESSUN aculeo piramidale duro.","echinocephala odora di insignificante o debolmente sgradevole e si colora spesso di grigio-verde sporco alla base del gambo e alle lamelle – strobiliformis odora neutro con debole componente di ravanello, lamelle bianco puro a crema.","echinocephala e classificata come (debolmente) tossica / mal tollerata a livello gastrointestinale – per sicurezza, MAI consumarla.","Entrambe biancastre, grandi, verrucose e su suolo calcareo – solo la forma del velo (aculei duri vs frange molli) le separa con sicurezza."}','f'),
('amanita_strobiliformis','amanita_ovoidea','en','ovoidea: smooth-mealy white egg-shaped mushroom with a thick, yellowish to pale-orange tinged sac volva and a soon-disintegrating ring; strobiliformis with fringed-tattered veil flakes and a turnip-shaped bulb.','ovoidea with age carrion-like unpleasant; strobiliformis neutral with a slight radish note.','Both thermophilic on lime – habitat does not separate them, rather the veil and volva form.','Both white spore print – no distinguishing feature.','Never eat large white amanitas on lime as a beginner – the egg/warted amanita group borders the nephrotoxic A. proxima and deadly death caps. Always have it checked (VAPKO).','{"Egg amanita (ovoidea): when young purely egg-shaped-white, smooth to mealy-flocculose, with a thick, sac-like, yellowish to pale-orange tinged volva at the base and a soon-disintegrating membranous ring – Warted amanita (strobiliformis): fringed-tattered veil flakes on the cap, turnip-shaped bulb with an ephemeral sheath.","ovoidea''s veil leaves mealy-smooth remnants, the ring crumbles early – strobiliformis with distinctly fringed, tattered veil.","ovoidea with age has a carrion-like unpleasant smell; strobiliformis neutral with a faint radish note.","WARNING: ovoidea itself is considered edible, but because of confusion with the nephrotoxic ochre-sheathed egg amanita (A. proxima, volva remaining yellow-ochre) and deadly death caps, it is NEVER suitable for beginners.","Both large, white and lime-loving – the veil structure (fringed vs mealy-smooth with sac volva) is the main distinguishing feature."}','f'),
('amanita_strobiliformis','amanita_ovoidea','es','ovoidea: hongo blanco en forma de huevo, liso-harinoso, con volva gruesa en saco, tenida de amarillento a naranja claro, y un anillo que se desintegra pronto; strobiliformis con floculos del velo deshilachados-desgarrados y un bulbo napiforme.','ovoidea con la edad olor desagradable a carrona; strobiliformis neutro con leve nota de rabano.','Ambos termofilos sobre caliza – el habitat no los separa, mas bien el velo y la forma de la volva.','Ambos esporada blanca – ningun caracter distintivo.','Nunca comer como principiante grandes amanitas blancas sobre caliza – el grupo de la amanita ovoide/deshilachada limita con A. proxima (nefrotoxica) y las amanitas mortales. Siempre hacerla revisar (VAPKO).','{"Amanita ovoide (ovoidea): de joven puramente ovoide-blanca, lisa a harinoso-floconosa, con volva gruesa, en saco, tenida de amarillento a naranja claro en la base y un anillo membranoso que se desintegra pronto – Amanita deshilachada (strobiliformis): floculos del velo deshilachados-desgarrados sobre el sombrero, bulbo napiforme con una vaina efimera.","El velo de ovoidea deja restos harinoso-lisos, el anillo se desmenuza pronto – strobiliformis con velo claramente deshilachado, desgarrado.","ovoidea con la edad tiene olor desagradable a carrona; strobiliformis neutro con debil nota de rabano.","ATENCION: ovoidea en si se considera comestible, pero por la confusion con la amanita ovoide de volva ocre nefrotoxica (A. proxima, volva que permanece amarillo-ocre) y las amanitas mortales, NUNCA es adecuada para principiantes.","Ambas grandes, blancas y calcicolas – la estructura del velo (deshilachada vs harinoso-lisa con volva en saco) es el caracter principal."}','f'),
('amanita_strobiliformis','amanita_ovoidea','fr','ovoidea champignon blanc en forme d''œuf, lisse-farineux, avec une volve en sac épaisse teintée de jaunâtre à orange clair et un anneau se désagrégeant vite ; strobiliformis avec des flocons de voile frangés-déchiquetés et un bulbe napiforme.','ovoidea désagréable, cadavérique avec l''âge ; strobiliformis neutre avec une légère note de radis.','Les deux thermophiles sur calcaire – l''habitat ne sépare pas, plutôt le voile et la forme de la volve.','Les deux à sporée blanche – pas un critère distinctif.','Ne jamais manger les grandes amanites blanches sur calcaire en tant que débutant – le groupe autour de l''amanite ovoïde/à voile frangé jouxte A. proxima (toxique rénal) et les amanites phalloïdes mortelles. Toujours contrôle des champignons (VAPKO).','{"Amanite ovoïde (ovoidea) : jeune purement ovoïde-blanche, lisse à farineuse-floconneuse, avec une volve épaisse, en sac, teintée de jaunâtre à orange clair à la base et un anneau membraneux se désagrégeant vite – Amanite à voile frangé (strobiliformis) : flocons de voile frangés-déchiquetés sur le chapeau, bulbe napiforme avec une gaine éphémère.","Le voile d''ovoidea laisse des restes farineux-lisses, l''anneau s''effrite tôt – strobiliformis avec un voile nettement frangé, déchiqueté.","ovoidea avec l''âge a une odeur désagréable cadavérique ; strobiliformis neutre avec une faible note de radis.","ATTENTION : ovoidea elle-même est certes considérée comestible, mais à cause de la confusion avec l''amanite ovoïde à gaine ocre (A. proxima, volve restant jaune-ocre, toxique rénal) et les amanites phalloïdes mortelles, elle n''est JAMAIS adaptée aux débutants.","Les deux grandes, blanches et calcicoles – la structure du voile (frangé vs. farineux-lisse avec volve en sac) est le critère principal de séparation."}','f'),
('amanita_strobiliformis','amanita_ovoidea','it','ovoidea: fungo bianco a forma di uovo, liscio-farinoso, con volva spessa a sacco, tinta di giallastro a arancio chiaro, e un anello che si disgrega presto; strobiliformis con fioccosita del velo sfrangiate-lacere e bulbo napiforme.','ovoidea con l''eta odore sgradevole di carogna; strobiliformis neutro con leggera nota di ravanello.','Entrambi termofili su calcare – l''habitat non separa, piuttosto il velo e la forma della volva.','Entrambi sporata bianca – nessun carattere distintivo.','Non mangiare mai da principianti grandi amanite bianche su calcare – il gruppo dell''amanita ovoide/sfrangiata confina con A. proxima (nefrotossica) e le amanite mortali. Sempre far controllare (VAPKO).','{"Amanita ovoidea (ovoidea): da giovane puramente ovoide-bianca, liscia a farinosa-fioccosa, con volva spessa, a sacco, tinta di giallastro a arancio chiaro alla base e un anello membranoso che si disgrega presto – Amanita sfrangiata (strobiliformis): fioccosita del velo sfrangiate-lacere sul cappello, bulbo napiforme con guaina effimera.","Il velo di ovoidea lascia resti farinoso-lisci, l''anello si sbriciola presto – strobiliformis con velo nettamente sfrangiato, lacero.","ovoidea con l''eta ha odore sgradevole di carogna; strobiliformis neutro con debole nota di ravanello.","ATTENZIONE: ovoidea stessa e considerata commestibile, ma a causa della confusione con l''amanita ovoide a volva ocra nefrotossica (A. proxima, volva che resta giallo-ocra) e le amanite mortali, NON e MAI adatta ai principianti.","Entrambe grandi, bianche e calcicole – la struttura del velo (sfrangiata vs farinosa-liscia con volva a sacco) e il carattere principale."}','f'),
('amanita_strobiliformis','fliegenpilz_var_alba','en','Warted amanita (A. strobiliformis): large, soft, wipeable mealy veil patches on the cap, unstriated bulb margin; white fly agaric: warted belted veil patches on the cap and a striated-rimmed bulb.','Warted amanita pleasant when young, unpleasant when old; white fly agaric inconspicuous — smell does not separate reliably.','Fly agaric var. alba under birch/conifer on acidic soil; Amanita strobiliformis on calcareous broadleaf-forest soil.','Both with white spore print — not a distinguishing feature.','For EVERY white Amanita, fully dig out the stem base and check the bulb, veil belt and striation — eat white amanitas only with absolute certainty of identification.','{"The warted amanita bears soft, mealy-cottony, easily wipeable veil patches and NO striated bulb margin; the white fly agaric has warted belted veil remnants and a distinctly striated-rimmed bulb base","In the white fly agaric the ring is membranous-hanging with a toothed margin and the stem base shows concentric veil belt rings; in the warted amanita these belt zones are absent","Habitat check: white fly agaric under birch/pine/spruce (mycorrhiza, acidic soils); warted amanita on warm calcareous broadleaf-forest soils","When in doubt, leave both standing — NEVER eat an all-white Amanita without sure identification (the phalloides/virosa group is deadly)"}','f'),
('amanita_strobiliformis','fliegenpilz_var_alba','es','Amanita de velo (A. strobiliformis): grandes copos harinosos blandos y limpiables en el sombrero, margen del bulbo no estriado; amanita matamoscas blanca: copos verrugosos en cinturones sobre el sombrero y bulbo estriado-marginado.','Amanita de velo joven agradable, vieja desagradable; amanita matamoscas blanca discreta — el olor no separa con seguridad.','Matamoscas var. alba bajo abedul/conífera en suelo ácido; Amanita strobiliformis en suelo calcáreo de bosque de frondosas.','Ambas con esporada blanca — sin carácter distintivo.','Para CUALQUIER amanita blanca, desenterrar completamente la base del pie y comprobar bulbo, cinturón de velo y estriación — consumir las amanitas blancas solo con certeza de determinación absoluta.','{"La amanita de velo lleva copos de velo blandos, harinoso-algodonosos, fácilmente limpiables y NINGÚN margen de bulbo estriado; la amanita matamoscas blanca tiene restos de velo verrugosos en cinturón y una base de bulbo claramente estriado-marginada","En la amanita matamoscas blanca el anillo es membranoso-colgante con margen dentado y la base del pie muestra anillos concéntricos de velo; en la amanita de velo faltan estas zonas en cinturón","Comprobación del hábitat: amanita matamoscas blanca bajo abedul/pino/abeto rojo (micorriza, suelos ácidos); amanita de velo en suelos calcáreos cálidos de bosque de frondosas","En caso de duda, dejar ambas en su sitio — NUNCA consumir una amanita totalmente blanca sin determinación segura (el grupo phalloides/virosa es mortal)"}','f'),
('amanita_strobiliformis','fliegenpilz_var_alba','fr','Amanite à voile (A. strobiliformis) : grands flocons farineux mous et essuyables sur le chapeau, marge du bulbe non striée ; amanite tue-mouches blanche : flocons verruqueux en bandes sur le chapeau et bulbe strié-marginé.','Amanite à voile jeune agréable, vieille désagréable ; amanite tue-mouches blanche discrète — l''odeur ne sépare pas de façon sûre.','Amanite tue-mouches var. alba sous bouleau/conifère sur sol acide ; Amanita strobiliformis sur sol calcaire de forêt feuillue.','Toutes deux à sporée blanche — pas de caractère distinctif.','Pour TOUTE amanite blanche, déterrer entièrement la base du pied et vérifier bulbe, ceinture de voile et striation — ne consommer les amanites blanches qu''avec une certitude de détermination absolue.','{"L''amanite à voile porte des flocons de voile mous, farineux-ouatés, facilement essuyables et AUCUNE marge de bulbe striée ; l''amanite tue-mouches blanche a des restes de voile verruqueux en ceinture et une base de bulbe nettement striée-marginée","Chez l''amanite tue-mouches blanche l''anneau est membraneux-pendant à marge dentelée et la base du pied montre des anneaux concentriques de voile ; chez l''amanite à voile ces zones en ceinture font défaut","Vérification de l''habitat : amanite tue-mouches blanche sous bouleau/pin/épicéa (mycorhize, sols acides) ; amanite à voile sur sols calcaires chauds de forêt feuillue","Dans le doute, laisser les deux sur place — ne JAMAIS consommer une amanite entièrement blanche sans détermination sûre (le groupe phalloides/virosa est mortel)"}','f'),
('amanita_strobiliformis','fliegenpilz_var_alba','it','Amanita a velo (A. strobiliformis): grandi fiocchi farinosi molli e asportabili sul cappello, margine del bulbo non striato; ovolaccio bianco (amanita muscaria var. alba): fiocchi verrucosi a cinture sul cappello e bulbo striato-marginato.','Amanita a velo da giovane gradevole, da vecchia sgradevole; ovolaccio bianco discreto — l''odore non separa con sicurezza.','Ovolaccio var. alba sotto betulla/conifera su suolo acido; Amanita strobiliformis su suolo calcareo di bosco di latifoglie.','Entrambe con sporata bianca — nessun carattere distintivo.','Per OGNI amanita bianca dissotterrare completamente la base del gambo e controllare bulbo, cintura di velo e striatura — consumare le amanite bianche solo con assoluta certezza di determinazione.','{"L''amanita a velo porta fiocchi di velo molli, farinoso-cotonosi, facilmente asportabili e NESSUN margine del bulbo striato; l''ovolaccio bianco ha resti di velo verrucosi a cintura e una base del bulbo nettamente striato-marginata","Nell''ovolaccio bianco l''anello è membranoso-pendente con margine dentellato e la base del gambo mostra anelli concentrici di velo; nell''amanita a velo queste zone a cintura mancano","Verifica dell''habitat: ovolaccio bianco sotto betulla/pino/abete rosso (micorriza, suoli acidi); amanita a velo su suoli calcarei caldi di bosco di latifoglie","Nel dubbio lasciare entrambe sul posto — non consumare MAI un''amanita interamente bianca senza determinazione sicura (il gruppo phalloides/virosa è mortale)"}','f'),
('amanita_vaginata','amanita_porphyria','en','vaginata ringless with a volva sheath and a strongly grooved cap margin; porphyria with a ring and a rimmed onion bulb, coppery violet-greyish-brown cap.','porphyria of raw potatoes/radish; vaginata odourless to mild.','porphyria prefers acidic coniferous woodland; vaginata in broadleaf and coniferous woodland.','Both white spore print – no field distinguishing feature.','Grisettes (ringless amanitas) NEVER have a ring. If you find a ring plus a rimmed bulb, it is a bulbed amanita – with a violet tone and potato smell, the poisonous porphyria. More importantly: ringless grey grisettes can be confused with deadly young death caps – always dig up the volva and bulb, when in doubt have it checked.','{"Grey grisette (vaginata): WITHOUT a ring/collar and with a membranous sheath (volva) at the non-bulbous base, cap margin distinctly grooved – Porphyry amanita (porphyria): with a pendent ring and a sharply rimmed, onion-shaped bulb (NO free sheath).","porphyria greyish-brown with a coppery-violet-porphyry tone and potato/radish smell – vaginata plainly grey, mild and without conspicuous smell.","vaginata stem ringless and slender; porphyria stem with a ring zone and a set-off bulb.","porphyria contains bufotenine and is poisonous; vaginata edible when thoroughly cooked (poisonous raw) – the presence of ring + bulb points to porphyria.","Rule of thumb: ring + rimmed bulb = not a grisette, but a bulbed amanita (here the poisonous porphyria)."}','f'),
('amanita_vaginata','amanita_porphyria','es','vaginata sin anillo con vaina-volva y margen del sombrero fuertemente estriado; porphyria con anillo y bulbo en cebolla marginado, sombrero cobrizo violeta-gris-pardo.','porphyria a patatas crudas/rabano; vaginata inodora a suave.','porphyria prefiere bosques de coniferas acidos; vaginata en bosques de frondosas y coniferas.','Ambos esporada blanca – ningun caracter de campo.','Las amanitas con vaina (de tipo vaginata) NUNCA tienen anillo. Si encuentras un anillo mas un bulbo marginado, es una amanita con bulbo – con tono violeta y olor a patata, la toxica porphyria. Mas importante: las amanitas grises sin anillo pueden confundirse con jovenes amanitas mortales – siempre desenterrar la volva y el bulbo, en caso de duda hacerla revisar.','{"Amanita vaginata gris (vaginata): SIN anillo/manguito y con vaina membranosa (volva) en la base no bulbosa, margen del sombrero netamente estriado – Amanita porfido (porphyria): con anillo colgante y bulbo en cebolla netamente marginado (NINGUNA vaina libre).","porphyria gris-parda con tono cobrizo-violeta-porfido y olor a patata/rabano – vaginata simplemente gris, suave y sin olor llamativo.","Pie de vaginata sin anillo y esbelto; pie de porphyria con zona anular y bulbo diferenciado.","porphyria contiene bufotenina y es toxica; vaginata comestible bien cocida (toxica cruda) – la presencia de anillo + bulbo apunta a porphyria.","Regla: anillo + bulbo marginado = no una amanita con vaina, sino una amanita con bulbo (aqui la toxica porphyria)."}','f'),
('amanita_vaginata','amanita_porphyria','fr','vaginata sans anneau avec une gaine volvaire et un bord de chapeau fortement strié ; porphyria avec anneau et bulbe oignon marginé, chapeau gris-brun violacé-cuivré.','porphyria de pommes de terre crues/radis ; vaginata inodore à douce.','porphyria préfère les forêts de conifères acides ; vaginata dans les forêts de feuillus et de conifères.','Les deux à sporée blanche – pas de critère distinctif sur le terrain.','Les amanites engainées n''ont JAMAIS d''anneau. Si tu trouves un anneau plus un bulbe marginé, c''est une amanite à bulbe – avec teinte violette et odeur de pomme de terre, la toxique porphyria. Plus important : les amanites engainées grises sans anneau peuvent être confondues avec de jeunes amanites phalloïdes mortelles – toujours déterrer la volve et le bulbe, en cas de doute contrôle des champignons.','{"Amanite vaginée grise (vaginata) : SANS anneau/manchette et avec une gaine membraneuse (volve) à la base non bulbeuse, bord du chapeau nettement strié – Amanite porphyre (porphyria) : avec anneau pendant et bulbe en oignon nettement marginé (AUCUNE gaine libre).","porphyria gris-brun avec une teinte porphyre violacé-cuivré et une odeur de pomme de terre/radis – vaginata simplement grise, douce et sans odeur marquante.","Pied de vaginata sans anneau et élancé ; pied de porphyria avec zone annulaire et bulbe distinct.","porphyria contient de la bufoténine et est toxique ; vaginata comestible bien cuite (toxique crue) – la présence d''anneau + bulbe indique porphyria.","Règle : anneau + bulbe marginé = pas une amanite engainée, mais une amanite à bulbe (ici la toxique porphyria)."}','f'),
('amanita_vaginata','amanita_porphyria','it','vaginata senza anello con guaina-volva e margine del cappello fortemente striato; porphyria con anello e bulbo a cipolla bordato, cappello rame violetto-grigio-bruno.','porphyria odore di patate crude/ravanello; vaginata inodore a mite.','porphyria preferisce boschi di conifere acidi; vaginata in boschi di latifoglie e conifere.','Entrambi sporata bianca – nessun carattere sul campo.','Le amanite a guaina (vaginate) non hanno MAI un anello. Se trovi un anello piu un bulbo bordato, e un''amanita a bulbo – con tono violetto e odore di patata, la tossica porphyria. Piu importante: le amanite grigie senza anello possono essere confuse con giovani amanite mortali – sempre dissotterrare volva e bulbo, nel dubbio far controllare.','{"Amanita vaginata grigia (vaginata): SENZA anello/manicotto e con guaina membranosa (volva) alla base non bulbosa, margine del cappello nettamente striato – Amanita porfido (porphyria): con anello pendente e bulbo a cipolla a bordo netto (NESSUNA guaina libera).","porphyria grigio-bruna con tono rame-violetto-porfido e odore di patata/ravanello – vaginata semplicemente grigia, mite e senza odore marcato.","Gambo di vaginata senza anello e slanciato; gambo di porphyria con zona anulare e bulbo distinto.","porphyria contiene bufotenina ed e tossica; vaginata commestibile ben cotta (tossica da cruda) – la presenza di anello + bulbo indica porphyria.","Regola: anello + bulbo bordato = non un''amanita a guaina, ma un''amanita a bulbo (qui la tossica porphyria)."}','f'),
('austernpilz','galerina_marginata','en','Oyster mushroom (Pleurotus): shell-/fan-shaped cap 5-25 cm, white/grey/brown, in overlapping tile-like clusters; lateral or absent stem; broad whitish decurrent gills. Deadly galerina (Galerina marginata): small convex ochre- to cinnamon-brown caplet 1-4 cm with a central slender brownish stem, a ring zone in the upper third of the stem, gills turning cinnamon-brown with age.','Oyster mushroom (Pleurotus): mild, pleasantly mushroomy-anise-like. Deadly galerina (Galerina marginata): faintly mealy to inconspicuous — smell is NOT a reliable distinguishing feature, so do not rely on it.','Both grow on wood, but: the oyster mushroom (Pleurotus) prefers deciduous wood (beech/poplar), growing in clustered, bracket-like form, often high on the trunk; the deadly galerina (Galerina marginata) grows on rotting deadwood (frequently coniferous wood, but also deciduous), small, single to bundled, rather near the ground / on fallen logs.','Oyster mushroom (Pleurotus): WHITE to pale lilac-grey. Deadly galerina (Galerina marginata): RUST-/CINNAMON-BROWN. This is the most reliable single feature — the spore print separates the two with certainty.','Golden rule: a true oyster mushroom (Pleurotus) sits laterally/stemless as a thick, fleshy bracket on the wood and gives a WHITE to lilac-grey spore print. As soon as there is a central stem with a ring remnant OR the spore print comes out brown, it is NOT an oyster mushroom — then hands off (the deadly galerina, Galerina marginata, contains deadly amatoxins, the same poison as the deathcap). When in doubt, always make a spore print before eating.','{"Spore powder: oyster mushroom (Pleurotus) white to lilac-grey; deadly galerina (Galerina marginata) rust-/cinnamon-brown (a spore print on dark + light paper is the most reliable distinguishing feature).","Stem: the oyster mushroom (Pleurotus) has a lateral/eccentric, short or almost absent stem and NO ring; the deadly galerina (Galerina marginata) has a central, slender stem with a membranous ring-zone remnant in the upper third.","Growth form: the oyster mushroom (Pleurotus) grows in overlapping tile-like fashion in thick, fleshy clusters/brackets directly on the wood; the deadly galerina (Galerina marginata) grows small, single to bundled, with a thin-fleshed, convex caplet on deadwood.","Gills: the oyster mushroom (Pleurotus) has broad, whitish gills running down the (lateral) stem; the deadly galerina (Galerina marginata) has narrow gills, pale ochre when young, turning cinnamon-brown with age (due to the brown spore powder).","Size/consistency: the oyster mushroom (Pleurotus) is large (cap 5-25 cm), tough-fleshy; the deadly galerina (Galerina marginata) is small (cap mostly 1-4 cm), fragile, with a distinct stem like a normal gilled mushroom."}','t'),
('austernpilz','galerina_marginata','es','Seta de ostra (Pleurotus): sombrero en forma de concha/abanico de 5-25 cm, blanco/gris/marrón, en grupos imbricados (como tejas); pie lateral o ausente; láminas anchas, blanquecinas y decurrentes. Galerina (Galerina marginata): sombrerito pequeño y convexo de color ocre a marrón canela de 1-4 cm, con pie central delgado y parduzco, zona anular en el tercio superior del pie; con la edad, láminas de color marrón canela.','Seta de ostra: suave, agradable, a hongo y ligeramente a anís. Galerina: débilmente harinoso o inapreciable — el olor NO es una característica distintiva segura, por lo que no hay que fiarse de él.','Ambas sobre madera, pero: la seta de ostra prefiere madera de frondosas (haya/álamo), en grupos a modo de consolas, a menudo a gran altura en el tronco; la galerina crece sobre madera muerta y podrida (con frecuencia coníferas, pero también frondosas), pequeña, solitaria a agrupada, más bien a ras de suelo o sobre troncos caídos.','Seta de ostra: BLANCO a lila-grisáceo pálido. Galerina: MARRÓN HERRUMBRE/CANELA. Esta es la característica individual más fiable — la esporada separa ambas con seguridad.','Regla de oro: una verdadera seta de ostra se asienta de forma lateral/sin pie como una consola gruesa y carnosa sobre la madera y da una esporada BLANCA a lila-grisácea. En cuanto hay un pie central con restos de anillo O la esporada resulta marrón, NO es una seta de ostra — entonces, no tocar (la galerina contiene amatoxinas mortales, el mismo veneno que la oronja mortal/Amanita phalloides). En caso de duda, hacer siempre una esporada antes de comer.','{"Esporada: seta de ostra blanca a lila-grisácea; galerina marrón herrumbre/canela (la esporada sobre papel oscuro y claro es la característica distintiva más segura).","Pie: la seta de ostra tiene un pie lateral/excéntrico, corto o casi ausente, y NINGÚN anillo; la galerina tiene un pie central y delgado con restos membranosos de una zona anular en el tercio superior.","Forma de crecimiento: la seta de ostra crece de forma imbricada (como tejas) en grupos/consolas gruesos y carnosos directamente sobre la madera; la galerina crece pequeña, solitaria a agrupada, con un sombrerito convexo de carne fina sobre madera muerta.","Láminas: la seta de ostra con láminas anchas, blanquecinas y decurrentes sobre el pie (lateral); la galerina con láminas estrechas, de jóvenes de color ocre pálido y que con la edad viran a marrón canela (por el polvo de esporas marrón).","Tamaño/consistencia: la seta de ostra grande (sombrero de 5-25 cm), de carne dura; la galerina pequeña (sombrero por lo general de 1-4 cm), frágil, con un pie marcado como una seta laminada normal."}','t'),
('austernpilz','galerina_marginata','fr','Pleurote en huître : chapeau en forme de coquille/d''éventail de 5-25 cm, blanc/gris/brun, en touffes imbriquées ; pied latéral ou absent ; lamelles larges, blanchâtres, décurrentes. Galère marginée : petit chapeau convexe de 1-4 cm, ocre à brun cannelle, avec un pied central élancé brunâtre, zone annulaire dans le tiers supérieur du pied, lamelles brun cannelle avec l''âge.','Pleurote en huître : doux, agréable, odeur de champignon rappelant l''anis. Galère marginée : faiblement farineuse à insignifiante — l''odeur n''est PAS un critère de distinction fiable, ne pas s''y fier.','Les deux sur bois, mais : le pleurote en huître préfère le bois de feuillus (hêtre/peuplier), en touffes en forme de console, souvent haut sur le tronc ; la galère marginée sur bois mort en décomposition (souvent résineux, mais aussi feuillus), petite, isolée à groupée, plutôt près du sol/sur troncs couchés.','Pleurote en huître : BLANC à lilas-gris pâle. Galère marginée : BRUN ROUILLE/CANNELLE. C''est le caractère isolé le plus fiable — la sporée sépare les deux avec certitude.','Règle d''or : un véritable pleurote en huître est fixé latéralement/sans pied comme une console épaisse et charnue sur le bois et donne une sporée BLANCHE à lilas-gris. Dès qu''un pied central avec un reste d''anneau est présent OU que la sporée est brune, ce n''est PAS un pleurote en huître — alors ne pas y toucher (la galère marginée contient des amatoxines mortelles, le même poison que l''amanite phalloïde). En cas de doute, toujours faire une sporée avant de consommer.','{"Sporée : pleurote en huître blanc à lilas-gris ; galère marginée brun rouille/cannelle (la sporée sur papier foncé + clair est le critère de distinction le plus sûr).","Pied : le pleurote en huître a un pied latéral/excentré, court ou presque absent et AUCUN anneau ; la galère marginée a un pied central, élancé, avec un reste de zone annulaire membraneuse dans le tiers supérieur.","Forme de croissance : le pleurote en huître pousse en tuiles imbriquées, en touffes/consoles épaisses et charnues directement sur le bois ; la galère marginée pousse petite, isolée à groupée, avec un petit chapeau convexe à chair mince sur le bois mort.","Lamelles : le pleurote en huître a des lamelles larges, blanchâtres, décurrentes le long du pied (latéral) ; la galère marginée a des lamelles étroites, jeunes d''un ocre pâle, devenant brun cannelle avec l''âge (à cause de la sporée brune).","Taille/consistance : le pleurote en huître est grand (chapeau 5-25 cm), tenace-charnu ; la galère marginée est petite (chapeau le plus souvent 1-4 cm), fragile, avec un pied distinct comme un champignon à lamelles ordinaire."}','t'),
('austernpilz','galerina_marginata','it','Gelone (Pleurotus ostreatus): cappello a forma di conchiglia/ventaglio di 5-25 cm, bianco/grigio/marrone, in cespi embricati a tegola; gambo laterale o assente; lamelle larghe biancastre decorrenti. Galerina marginata: piccolo cappellino convesso da ocra a marrone cannella di 1-4 cm con gambo centrale slanciato brunastro, zona anulare nel terzo superiore del gambo, da vecchio lamelle marrone cannella.','Gelone: mite, gradevolmente fungino-anisato. Galerina marginata: debolmente farinoso fino a impercettibile - l''odore NON è un carattere distintivo sicuro, quindi non affidarsi ad esso.','Entrambi su legno, ma: il gelone predilige legno di latifoglie (faggio/pioppo), in cespi a mensola, spesso in alto sul tronco; la Galerina marginata su legno morto marcescente (spesso conifere, ma anche latifoglie), piccola, da singola a fascicolata, piuttosto vicino al suolo/su tronchi distesi.','Gelone: BIANCO fino a grigio-lilla pallido. Galerina marginata: MARRONE RUGGINE/CANNELLA. Questo è il carattere singolo più affidabile - la sporata distingue i due con sicurezza.','Regola d''oro: un vero gelone sta lateralmente/senza gambo come una spessa mensola carnosa sul legno e dà una sporata BIANCA fino a grigio-lilla. Non appena è presente un gambo centrale con resto di anello OPPURE la sporata risulta marrone, NON è un gelone - allora giù le mani (la Galerina marginata contiene amatossine mortali, lo stesso veleno della tignosa verdognola). Nel dubbio fare sempre una sporata prima di mangiare.','{"Sporata: gelone bianca fino a grigio-lilla; Galerina marginata marrone ruggine/cannella (la sporata su carta scura + chiara è il carattere distintivo più sicuro).","Gambo: il gelone ha un gambo laterale/eccentrico, corto o quasi assente, e NESSUN anello; la Galerina marginata ha un gambo centrale, slanciato, con un resto membranoso di zona anulare nel terzo superiore.","Forma di crescita: il gelone cresce embricato a tegola in cespi/mensole spessi e carnosi direttamente sul legno; la Galerina marginata cresce piccola, da singola a fascicolata, con cappellino convesso a carne sottile su legno morto.","Lamelle: il gelone con lamelle larghe, biancastre, decorrenti sul gambo (laterale); la Galerina marginata con lamelle strette, da giovani di colore ocra pallido, che da vecchie virano al marrone cannella (per il sporo marrone).","Dimensione/consistenza: il gelone grande (cappello 5-25 cm), tenace-carnoso; la Galerina marginata piccola (cappello per lo più 1-4 cm), fragile, con un gambo distinto come un normale fungo a lamelle."}','t'),
('butterpilz','tricholoma_ustale','en','The slippery jack (Suillus luteus) has pores/tubes and a ring on the stem; T. ustale has gills that become rust-spotted, without a ring.','both inconspicuous/mild to faintly mealy - NOT a reliable distinguishing feature.','The slippery jack grows with pine, T. ustale in broadleaf woodland with beech/oak.','Slippery jack: olive-brown spore print (bolete); T. ustale: white (gilled mushroom).','Check the underside of the cap: tubes/pores = slippery jack/bolete, gills = tricholoma. Never take a gilled mushroom with a brown slimy cap as a slippery jack.','{"The slippery jack (edible) is a bolete with TUBES/PORES under the cap and usually a ring on the stem; the burnt knight (T. ustale) has GILLS and no ring.","The resemblance comes only from the brown, slimy-greasy cap seen from a distance - from above the T. ustale cap can recall a slippery jack.","The slippery jack''s cap cuticle peels off easily, tubes yellowish; T. ustale gills become rust-spotted.","The slippery jack grows in mycorrhiza with pine, T. ustale in broadleaf woodland.","Taste: slippery jack mild, T. ustale somewhat bitter."}','f'),
('butterpilz','tricholoma_ustale','es','El boleto anillado (Suillus luteus) tiene tubos/poros y un anillo en el pie; T. ustale tiene laminas que se manchan de herrumbre, sin anillo.','ambos discretos/suaves a debilmente harinosos - NO es un caracter distintivo fiable.','El boleto anillado crece bajo pinos, T. ustale en bosque de frondosas bajo haya/roble.','Boleto anillado: esporada pardo-olivacea (boleto); T. ustale: esporada blanca (hongo laminado).','Comprobar la cara inferior del sombrero: tubos/poros = boleto anillado/boleto, laminas = tricoloma. Nunca recoger como boleto anillado un hongo laminado con sombrero pardo viscoso.','{"El boleto anillado (comestible) es un boleto con TUBOS/POROS bajo el sombrero y normalmente un anillo en el pie; el tricoloma quemado (T. ustale) tiene LAMINAS y ningun anillo.","La semejanza solo viene del sombrero pardo, viscoso-grasiento visto de lejos - desde arriba el sombrero de T. ustale puede recordar a un boleto anillado.","La cuticula del boleto anillado se pela facilmente, tubos amarillentos; las laminas de T. ustale se manchan de herrumbre.","El boleto anillado crece en micorriza con pino, T. ustale en bosque de frondosas.","Sabor: boleto anillado suave, T. ustale algo amargo."}','f'),
('butterpilz','tricholoma_ustale','fr','Le bolet jaune (Suillus luteus) a des tubes et un anneau sur le pied; T. ustale a des lames qui se tachent de rouille, sans anneau.','les deux discrets/doux a faiblement farineux - ce n''est PAS un critere de distinction fiable.','Le bolet jaune pousse sous les pins, T. ustale en foret de feuillus sous hetre/chene.','Bolet jaune: sporee brun olive (bolet); T. ustale: sporee blanche (champignon a lames).','Verifiez le dessous du chapeau: tubes = bolet jaune/bolet, lames = tricholome. Ne jamais ramasser un champignon a lames avec chapeau brun visqueux comme bolet jaune.','{"Le bolet jaune (comestible) est un bolet avec des TUBES sous le chapeau et generalement un anneau au pied; le tricholome brule (T. ustale) a des LAMES et pas d''anneau.","La ressemblance ne vient que du chapeau brun, gluant-visqueux vu de loin - de dessus, le chapeau de T. ustale peut rappeler un bolet jaune.","La cuticule du bolet jaune se pele facilement, tubes jaunatres; les lames de T. ustale se tachent de rouille.","Le bolet jaune pousse en mycorhize sous les pins, T. ustale en foret de feuillus.","Saveur: bolet jaune doux, T. ustale un peu amer."}','f'),
('butterpilz','tricholoma_ustale','it','Il boleto giallo (Suillus luteus) ha tubuli e un anello sul gambo; T. ustale ha lamelle che si macchiano di ruggine, senza anello.','entrambi inappariscenti/miti o debolmente farinosi - NON e un carattere distintivo affidabile.','Il boleto giallo cresce sotto i pini, T. ustale nel bosco di latifoglie sotto faggio/quercia.','Boleto giallo: sporata bruno-olivacea (boleto); T. ustale: sporata bianca (fungo a lamelle).','Controllare il sotto del cappello: tubuli = boleto giallo/boleto, lamelle = tricoloma. Mai raccogliere come boleto giallo un fungo a lamelle con cappello bruno vischioso.','{"Il boleto giallo (commestibile) e un boleto con TUBULI sotto il cappello e di solito un anello sul gambo; il tricoloma bruciato (T. ustale) ha LAMELLE e nessun anello.","La somiglianza nasce solo dal cappello bruno, viscido-vischioso visto da lontano - dall''alto il cappello di T. ustale puo ricordare un boleto giallo.","La cuticola del boleto giallo si pela facilmente, tubuli giallastri; le lamelle di T. ustale si macchiano di ruggine.","Il boleto giallo cresce in micorriza sotto i pini, T. ustale nel bosco di latifoglie.","Sapore: boleto giallo mite, T. ustale un po'' amaro."}','f'),
('butyriboletus_appendiculatus','caloboletus_calopus','en','Butter bolete: brown cap, yellow stipe with yellow net, weak blueing. Scarlet-stemmed bolete (bitter beech bolete): grey cap, red-yellow netted stipe, strong blueing.','Both inconspicuous — the bitter taste is the decisive distinguishing feature.','Both thermophilous in deciduous/mixed forest (oak/beech); habitat does not separate them.','Both olive-brown spore print — NOT a distinguishing feature.','Taste test (tiny piece, spit out): every bitter bolete leaves the basket — the mild butter bolete is never bitter. With a red stipe net plus strong blueing, check especially carefully.','{"The scarlet-stemmed bolete tastes strongly BITTER (stays bitter even cooked) — the butter bolete tastes mild and pleasant","Cap of the butter bolete warm brown to leather-yellow; scarlet-stemmed bolete clay-grey/grey-brown","The butter bolete blues only weakly/slowly; the scarlet-stemmed bolete blues rapidly and strongly blue-green","Butter bolete stipe yellow with a fine yellow net and a rooting extension; scarlet-stemmed bolete stipe strongly red-netted below","Flesh of the butter bolete golden-yellow and mild; bitter in the scarlet-stemmed bolete"}','f'),
('butyriboletus_appendiculatus','caloboletus_calopus','es','Boleto apendiculado: sombrero pardo, pie amarillo con retículo amarillo, azuleamiento débil. Boleto de pie hermoso: sombrero gris, pie con retículo rojo-amarillo, azuleamiento marcado.','Ambos poco llamativos — el sabor amargo es el carácter de separación decisivo.','Ambos termófilos en bosque de frondosas/mixto (roble/haya); el hábitat no los separa.','Ambos con esporada pardo-oliva — NO es un carácter distintivo.','Prueba de sabor (trocito mínimo, escupir): todo boleto amargo sale de la cesta — el dulce boleto apendiculado nunca es amargo. Con retículo del pie rojo más azuleamiento marcado, comprobar con especial cuidado.','{"El boleto de pie hermoso sabe fuertemente AMARGO (sigue amargo incluso cocinado) — el boleto apendiculado sabe suave y agradable","Sombrero del boleto apendiculado pardo cálido a amarillo cuero; boleto de pie hermoso gris arcilloso/gris-pardo","El boleto apendiculado azulea solo débil/lentamente; el boleto de pie hermoso azulea rápida e intensamente azul-verde","Pie del boleto apendiculado amarillo con fino retículo amarillo y prolongación radicante; pie del boleto de pie hermoso fuertemente reticulado de rojo en la parte inferior","Carne del boleto apendiculado amarillo oro y suave; amarga en el boleto de pie hermoso"}','f'),
('butyriboletus_appendiculatus','caloboletus_calopus','fr','Bolet appendiculé: chapeau brun, pied jaune à réseau jaune, bleuissement faible. Bolet à beau pied: chapeau gris, pied à réseau rouge-jaune, bleuissement marqué.','Tous deux discrets — le goût amer est le caractère de séparation décisif.','Tous deux thermophiles en forêt de feuillus/mixte (chêne/hêtre); l''habitat ne sépare pas.','Tous deux à sporée brun-olive — PAS un caractère distinctif.','Test gustatif (minuscule morceau, recracher): tout bolet amer sort du panier — le bolet appendiculé doux n''est jamais amer. En cas de réseau du pied rouge plus bleuissement marqué, vérifier particulièrement.','{"Le bolet à beau pied a un goût fortement AMER (reste amer même cuit) — le bolet appendiculé a un goût doux et agréable","Chapeau du bolet appendiculé brun chaud à jaune cuir; bolet à beau pied gris argileux/gris-brun","Le bolet appendiculé ne bleuit que faiblement/lentement; le bolet à beau pied bleuit rapidement et fortement en bleu-vert","Pied du bolet appendiculé jaune à fin réseau jaune et prolongement radicant; pied du bolet à beau pied fortement réticulé de rouge en bas","Chair du bolet appendiculé jaune d''or et douce; amère chez le bolet à beau pied"}','f'),
('butyriboletus_appendiculatus','caloboletus_calopus','it','Boleto appendicolato: cappello bruno, gambo giallo con reticolo giallo, viraggio al blu debole. Boleto dal bel piede: cappello grigio, gambo a reticolo rosso-giallo, viraggio al blu marcato.','Entrambi poco appariscenti — il sapore amaro è il carattere distintivo decisivo.','Entrambi termofili nel bosco di latifoglie/misto (quercia/faggio); l''habitat non separa.','Entrambi a sporata bruno-olivastra — NON è un carattere distintivo.','Prova di assaggio (pezzettino minuscolo, sputare): ogni boleto amaro esce dal cesto — il dolce boleto appendicolato non è mai amaro. Con reticolo del gambo rosso più viraggio al blu marcato, controllare con particolare attenzione.','{"Il boleto dal bel piede ha un sapore fortemente AMARO (resta amaro anche cotto) — il boleto appendicolato ha un sapore dolce e gradevole","Cappello del boleto appendicolato bruno caldo fino a giallo cuoio; boleto dal bel piede grigio argilla/grigio-bruno","Il boleto appendicolato vira al blu solo debolmente/lentamente; il boleto dal bel piede vira rapidamente e intensamente in blu-verde","Gambo del boleto appendicolato giallo con fine reticolo giallo e prolungamento radicante; gambo del boleto dal bel piede in basso fortemente reticolato di rosso","Carne del boleto appendicolato giallo oro e dolce; amara nel boleto dal bel piede"}','f'),
('butyriboletus_appendiculatus','roehrling_flockenstielig','en','Clay-grey to grey-brown cap + red lower stipe part in the scarlet-stemmed bolete vs. ochre/chestnut-brown cap + mostly yellow stipe in the butter bolete.','Both inconspicuously mushroomy — smell does not separate them; the taste test (bitter vs. mild) is decisive.','Scarlet-stemmed bolete on acidic, poor soil/coniferous/montane forest; butter bolete thermophilous in deciduous forest on limestone.','Both olive-brown spore print — not a distinguishing feature.','For every bolete with a stipe net, do the bitter taste test: bitter = throw away. Net on the stipe + bitter taste = scarlet-stemmed bolete, inedible. The butter bolete is moreover protected/rare — when in doubt, leave it standing.','{"The scarlet-stemmed bolete (Caloboletus calopus) tastes distinctly BITTER — the taste test (tip of the tongue, spit out) is the safe distinguishing criterion; the butter bolete tastes mild-nutty","The scarlet-stemmed bolete has a pale clay-grey/grey-brown cap; the butter bolete has a warm ochre to chestnut-brown cap","Scarlet-stemmed bolete stipe with a strongly red area and net in the lower part; butter bolete stipe mostly yellow with a fine yellowish net and only a reddish base","Both blue under pressure/when cut (pores/flesh) — blueing alone does NOT separate them; decisive are the bitter taste and the stipe colour","The scarlet-stemmed bolete prefers acidic, poor soil (readily coniferous/montane forest); the butter bolete is thermophilous in deciduous forest on calcareous soil"}','f'),
('butyriboletus_appendiculatus','roehrling_flockenstielig','es','Sombrero gris-arcilloso a gris-pardo + parte inferior del pie roja en el boleto de pie hermoso vs. sombrero ocre/pardo-castaño + pie mayoritariamente amarillo en el boleto apendiculado.','Ambos con olor fongico poco llamativo — el olor no los separa; la prueba de sabor (amargo vs. suave) es decisiva.','Boleto de pie hermoso en suelo ácido y pobre/bosque de coníferas/de montaña; boleto apendiculado termófilo en bosque de frondosas sobre caliza.','Ambos con esporada pardo-oliva — no es un carácter distintivo.','Para todo boleto con retículo en el pie, hacer la prueba del amargor: amargo = desechar. Retículo en el pie + sabor amargo = boleto de pie hermoso, incomible. El boleto apendiculado está además protegido/es raro — en caso de duda, dejarlo.','{"El boleto de pie hermoso (Caloboletus calopus) sabe claramente AMARGO — la prueba de sabor (punta de la lengua, escupir) es el criterio de separación seguro; el boleto apendiculado sabe suave-avellanado","El boleto de pie hermoso tiene un sombrero gris-arcilloso pálido/gris-pardo; el boleto apendiculado tiene un sombrero ocre cálido a pardo-castaño","Pie del boleto de pie hermoso con una zona fuertemente roja y retículo en la parte inferior; pie del boleto apendiculado mayoritariamente amarillo con fino retículo amarillento y solo la base rojiza","Ambos azulean a la presión/al corte (poros/carne) — el azuleamiento por sí solo NO los separa; decisivos son el sabor amargo y el color del pie","El boleto de pie hermoso prefiere suelo ácido y pobre (gustosamente bosque de coníferas/de montaña); el boleto apendiculado termófilo en bosque de frondosas sobre suelo calcáreo"}','f'),
('butyriboletus_appendiculatus','roehrling_flockenstielig','fr','Chapeau gris-argileux à gris-brun + partie inférieure du pied rouge chez le bolet à beau pied vs. chapeau ocre/brun-marron + pied majoritairement jaune chez le bolet appendiculé.','Tous deux à odeur fongique discrète — l''odeur ne sépare pas; le test gustatif (amer vs. doux) est décisif.','Bolet à beau pied sur sol acide et pauvre/forêt de conifères/de montagne; bolet appendiculé thermophile en forêt de feuillus sur calcaire.','Tous deux à sporée brun-olive — pas un caractère distinctif.','Pour tout bolet à réseau du pied, faire le test de l''amertume: amer = jeter. Réseau au pied + goût amer = bolet à beau pied, immangeable. Le bolet appendiculé est en outre protégé/rare — en cas de doute, le laisser.','{"Le bolet à beau pied (Caloboletus calopus) a un goût nettement AMER — le test gustatif (pointe de la langue, recracher) est le critère de séparation sûr; le bolet appendiculé a un goût doux-noisette","Le bolet à beau pied a un chapeau gris-argileux pâle/gris-brun; le bolet appendiculé a un chapeau ocre chaud à brun-marron","Pied du bolet à beau pied avec une zone fortement rouge et un réseau dans la partie inférieure; pied du bolet appendiculé majoritairement jaune avec un fin réseau jaunâtre et seulement la base rougeâtre","Tous deux bleuissent à la pression/coupe (pores/chair) — le bleuissement seul ne sépare PAS; décisifs sont le goût amer et la couleur du pied","Le bolet à beau pied préfère un sol acide et pauvre (volontiers forêt de conifères/de montagne); le bolet appendiculé thermophile en forêt de feuillus sur sol calcaire"}','f'),
('butyriboletus_appendiculatus','roehrling_flockenstielig','it','Cappello grigio-argilla a grigio-bruno + parte inferiore del gambo rossa nel boleto dal bel piede vs. cappello ocra/bruno-castano + gambo prevalentemente giallo nel boleto appendicolato.','Entrambi con odore fungino poco appariscente — l''odore non separa; il test di assaggio (amaro vs. dolce) è decisivo.','Boleto dal bel piede su suolo acido e povero/bosco di conifere/di montagna; boleto appendicolato termofilo nel bosco di latifoglie su calcare.','Entrambi a sporata bruno-olivastra — non è un carattere distintivo.','Per ogni boleto con reticolo sul gambo fare la prova dell''amaro: amaro = buttare. Reticolo sul gambo + sapore amaro = boleto dal bel piede, immangiabile. Il boleto appendicolato è inoltre protetto/raro — nel dubbio lasciarlo.','{"Il boleto dal bel piede (Caloboletus calopus) ha un sapore nettamente AMARO — la prova di assaggio (punta della lingua, sputare) è il criterio distintivo sicuro; il boleto appendicolato ha un sapore dolce-nocciola","Il boleto dal bel piede ha un cappello grigio-argilla pallido/grigio-bruno; il boleto appendicolato ha un cappello ocra caldo fino a bruno-castano","Gambo del boleto dal bel piede con una zona fortemente rossa e reticolo nella parte inferiore; gambo del boleto appendicolato prevalentemente giallo con fine reticolo giallastro e solo la base rossastra","Entrambi virano al blu alla pressione/al taglio (pori/carne) — il viraggio da solo NON separa; decisivi sono il sapore amaro e il colore del gambo","Il boleto dal bel piede preferisce suolo acido e povero (volentieri bosco di conifere/di montagna); il boleto appendicolato termofilo nel bosco di latifoglie su suolo calcareo"}','f'),
('butyriboletus_appendiculatus','rubroboletus_legaliae','en','Red pores + pale pink/grey-pink cap in Le Gal''''s bolete vs. yellow pores + ochre/chestnut-brown cap in the butter bolete.','Le Gal''''s bolete smells of celery/lovage; butter bolete mild and mushroomy.','Both thermophilous in deciduous forest (oak/beech) on limestone — habitat overlaps, does not separate.','Both olive-brown — not a distinguishing feature.','Golden bolete rule: red pores = not in the basket without certain identification. Only yellow pores + mild flesh + absence of celery smell in the butter bolete are harmless (it is also protected/rare).','{"Le Gal''''s bolete has RED to orange-red/blood-red pores; the butter bolete has YELLOW pores — red pores in boletes are a general warning sign","Le Gal''''s bolete has a pale white-/grey-pink to old-rose cap; the butter bolete a warm ochre to chestnut-brown cap","Le Gal''''s bolete smells of celery/lovage and is toxic/intolerable even cooked; the butter bolete smells mildly mushroomy and is mild-edible","Le Gal''''s bolete stipe with a red net on a reddish-orange ground; butter bolete stipe mostly yellow with a fine yellowish net","Both can blue — blueing alone is NOT enough; decisive is the pore colour (red vs. yellow) plus celery smell"}','f'),
('butyriboletus_appendiculatus','rubroboletus_legaliae','es','Poros rojos + sombrero rosa pálido/gris-rosado en el boleto de Le Gal vs. poros amarillos + sombrero ocre/pardo-castaño en el boleto apendiculado.','Boleto de Le Gal con olor a apio/levístico; boleto apendiculado suave y fongico.','Ambos termófilos en bosque de frondosas (roble/haya) sobre caliza — el hábitat se solapa, no los separa.','Ambos pardo-oliva — no es un carácter distintivo.','Regla de oro de los boletos: poros rojos = no a la cesta sin determinación segura. Solo poros amarillos + carne suave + ausencia de olor a apio en el boleto apendiculado son inofensivos (él mismo protegido/raro).','{"El boleto de Le Gal tiene poros ROJOS a rojo-anaranjado/rojo sangre; el boleto apendiculado tiene poros AMARILLOS — los poros rojos en los boletos son una señal de alarma general","El boleto de Le Gal tiene un sombrero pálido blanco-/gris-rosado a rosa viejo; el boleto apendiculado un sombrero ocre cálido a pardo-castaño","El boleto de Le Gal huele a apio/levístico y es tóxico/mal tolerado incluso cocinado; el boleto apendiculado huele suavemente a hongo y es suave-comestible","Pie del boleto de Le Gal con retículo rojo sobre fondo rojizo-anaranjado; pie del boleto apendiculado mayoritariamente amarillo con fino retículo amarillento","Ambos pueden azulear — el azuleamiento por sí solo NO basta; decisivo es el color de los poros (rojo vs. amarillo) más el olor a apio"}','f'),
('butyriboletus_appendiculatus','rubroboletus_legaliae','fr','Pores rouges + chapeau rose pâle/gris-rosé chez le bolet de Le Gal vs. pores jaunes + chapeau ocre/brun-marron chez le bolet appendiculé.','Bolet de Le Gal sentant le céleri/la livèche; bolet appendiculé doux et fongique.','Tous deux thermophiles en forêt de feuillus (chêne/hêtre) sur calcaire — l''habitat se chevauche, ne sépare pas.','Tous deux brun-olive — pas un caractère distinctif.','Règle d''or des bolets: pores rouges = pas dans le panier sans détermination sûre. Seuls des pores jaunes + chair douce + absence d''odeur de céleri chez le bolet appendiculé sont sans danger (lui-même protégé/rare).','{"Le bolet de Le Gal a des pores ROUGES à rouge-orangé/rouge sang; le bolet appendiculé a des pores JAUNES — des pores rouges chez les bolets sont un signal d''alarme général","Le bolet de Le Gal a un chapeau pâle blanc-/gris-rosé à vieux rose; le bolet appendiculé un chapeau ocre chaud à brun-marron","Le bolet de Le Gal sent le céleri/la livèche et est toxique/mal toléré même cuit; le bolet appendiculé sent doucement le champignon et est doux-comestible","Pied du bolet de Le Gal à réseau rouge sur fond rougeâtre-orangé; pied du bolet appendiculé majoritairement jaune à fin réseau jaunâtre","Tous deux peuvent bleuir — le bleuissement seul ne suffit PAS; décisives sont la couleur des pores (rouge vs. jaune) plus l''odeur de céleri"}','f'),
('butyriboletus_appendiculatus','rubroboletus_legaliae','it','Pori rossi + cappello rosa pallido/grigio-rosato nel boleto di Le Gal vs. pori gialli + cappello ocra/bruno-castano nel boleto appendicolato.','Boleto di Le Gal odore di sedano/levistico; boleto appendicolato dolce e fungino.','Entrambi termofili nel bosco di latifoglie (quercia/faggio) su calcare — l''habitat si sovrappone, non separa.','Entrambi bruno-olivastri — non è un carattere distintivo.','Regola d''oro dei boleti: pori rossi = non nel cesto senza determinazione sicura. Solo pori gialli + carne dolce + assenza di odore di sedano nel boleto appendicolato sono innocui (esso stesso protetto/raro).','{"Il boleto di Le Gal ha pori ROSSI fino a rosso-arancio/rosso sangue; il boleto appendicolato ha pori GIALLI — pori rossi nei boleti sono un segnale d''allarme generale","Il boleto di Le Gal ha un cappello pallido bianco-/grigio-rosato fino a rosa antico; il boleto appendicolato un cappello ocra caldo fino a bruno-castano","Il boleto di Le Gal odora di sedano/levistico ed è tossico/mal tollerato anche cotto; il boleto appendicolato odora delicatamente di fungo ed è dolce-commestibile","Gambo del boleto di Le Gal con reticolo rosso su fondo rossastro-arancio; gambo del boleto appendicolato prevalentemente giallo con fine reticolo giallastro","Entrambi possono virare al blu — il viraggio da solo NON basta; decisivi sono il colore dei pori (rosso vs. giallo) più l''odore di sedano"}','f'),
('butyriboletus_appendiculatus','rubroboletus_satanas','en','The butter bolete has yellow pores and a yellow stipe, the Satan''''s bolete red pores and a red-netted stipe.','The Satan''''s bolete smells of carrion when old; the butter bolete pleasantly mushroomy.','Both calcicolous in warm oak/beech forests — not a distinguishing feature.','Both olive-brown spore print — not separating.','With red or orange pores always leave it standing — yellow-pored thick-footed boletes are edible, red-pored ones are taboo.','{"The butter bolete (thick-footed bolete) has YELLOW pores, the Satan''''s bolete red to orange pores.","The butter bolete blues only weakly in the yellow flesh and has no carrion smell; the Satan''''s bolete smells repulsively of carrion when old.","The butter bolete has a brown, velvety cap; the Satan''''s bolete when young a pale, chalk-white to whitish-grey-green cap.","Butter bolete stipe yellow with a fine yellow net, often with a rooting appendage; Satan''''s bolete stipe red-netted and bulbous.","Both grow on limestone in warm deciduous forest — the red pore colour is the safety criterion."}','f'),
('butyriboletus_appendiculatus','rubroboletus_satanas','es','El boleto apendiculado tiene poros amarillos y pie amarillo, el boleto de Satanás poros rojos y pie reticulado de rojo.','El boleto de Satanás huele, de viejo, a carroña; el boleto apendiculado agradablemente a hongo.','Ambos calcícolas en cálidos robledales/hayedos — no es un carácter distintivo.','Ambos con esporada pardo-oliva — no los separa.','Con poros rojos o anaranjados dejar siempre en el sitio — los boletos de pie grueso con poros amarillos son comestibles, los de poros rojos están prohibidos.','{"El boleto apendiculado (boleto de pie grueso) tiene poros AMARILLOS, el boleto de Satanás poros de rojos a anaranjados.","El boleto apendiculado azulea solo débilmente en la carne amarilla y no tiene olor a carroña; el boleto de Satanás huele, de viejo, repugnantemente a carroña.","El boleto apendiculado tiene un sombrero pardo, aterciopelado; el boleto de Satanás, de joven, un sombrero claro, blanco calcáreo a blanco-grisáceo-verdoso.","Pie del boleto apendiculado amarillo con fino retículo amarillo, a menudo con apéndice radicante; pie del boleto de Satanás reticulado de rojo y bulboso.","Ambos crecen sobre caliza en bosque cálido de frondosas — el color rojo de los poros es el criterio de seguridad."}','f'),
('butyriboletus_appendiculatus','rubroboletus_satanas','fr','Le bolet appendiculé a des pores jaunes et un pied jaune, le bolet Satan des pores rouges et un pied réticulé de rouge.','Le bolet Satan sent, en vieillissant, la charogne; le bolet appendiculé est agréablement fongique.','Tous deux calcicoles dans des chênaies/hêtraies chaudes — pas un caractère distinctif.','Tous deux à sporée brun-olive — non séparateur.','Avec des pores rouges ou orange, toujours laisser sur place — les bolets à pied épais à pores jaunes sont comestibles, ceux à pores rouges sont à proscrire.','{"Le bolet appendiculé (bolet à pied épais) a des pores JAUNES, le bolet Satan des pores rouges à orange.","Le bolet appendiculé ne bleuit que faiblement dans sa chair jaune et n''a pas d''odeur de charogne; le bolet Satan sent, en vieillissant, de façon répugnante la charogne.","Le bolet appendiculé a un chapeau brun, velouté; le bolet Satan, jeune, un chapeau clair, blanc calcaire à blanc-grisâtre-verdâtre.","Pied du bolet appendiculé jaune à fin réseau jaune, souvent avec un appendice radicant; pied du bolet Satan réticulé de rouge et bulbeux.","Tous deux poussent sur calcaire en forêt de feuillus chaude — la couleur rouge des pores est le critère de sécurité."}','f'),
('butyriboletus_appendiculatus','rubroboletus_satanas','it','Il boleto appendicolato ha pori gialli e gambo giallo, il boleto di Satana pori rossi e gambo reticolato di rosso.','Il boleto di Satana odora, da vecchio, di carogna; il boleto appendicolato gradevolmente fungino.','Entrambi calcicoli in caldi querceti/faggeti — non è un carattere distintivo.','Entrambi a sporata bruno-olivastra — non separa.','Con pori rossi o arancioni lasciare sempre sul posto — i boleti dal piede grosso a pori gialli sono commestibili, quelli a pori rossi sono vietati.','{"Il boleto appendicolato (boleto dal piede grosso) ha pori GIALLI, il boleto di Satana pori da rossi ad arancioni.","Il boleto appendicolato vira al blu solo debolmente nella carne gialla e non ha odore di carogna; il boleto di Satana odora, da vecchio, in modo ripugnante di carogna.","Il boleto appendicolato ha un cappello bruno, vellutato; il boleto di Satana, da giovane, un cappello chiaro, bianco calcareo fino a bianco-grigio-verdastro.","Gambo del boleto appendicolato giallo con fine reticolo giallo, spesso con appendice radicante; gambo del boleto di Satana reticolato di rosso e bulboso.","Entrambi crescono su calcare nel caldo bosco di latifoglie — il colore rosso dei pori è il criterio di sicurezza."}','f'),
('calocybe_gambosa','hebeloma_crustuliniforme','en','St George''s mushroom cream-white with densely crowded white gills; Hebeloma (poison pie) clay-grey pale with weeping, later rust-brown gills.','St George''s mushroom mealy-cucumbery (edible marker); Hebeloma radish-like (toxicity hint).','Both can appear in spring — St George''s mushroom classically around St George''s Day (late April/May) in fairy rings on meadows/forest edges.','St George''s mushroom with white spore print vs. rust-olive in the weeping Hebeloma — the most reliable distinguishing feature.','Always take a spore print: white = possible St George''s mushroom, rust/brown = Hebeloma and discard; additionally check mealy smell (good) vs. radish smell (warning).','{"St George''s mushroom smells strongly mealy-cucumbery; the weeping Hebeloma smells radish-like — the radish smell is a warning sign","St George''s mushroom has a WHITE spore print; Hebeloma crustuliniforme has a rust to brown-olive spore print","In the weeping Hebeloma, watery droplets hang on the gill edges when young and leave brown spore spots — in St George''s mushroom these weeping gills are absent","St George''s mushroom has densely crowded, white, straight-attached gills when young; Hebeloma gills are pale grey-brown and turn rust-brown"}','f'),
('calocybe_gambosa','hebeloma_crustuliniforme','es','Seta de San Jorge crema-blanca con láminas blancas apretadas; hebeloma («lacrimoso») gris-arcilla pálido con láminas lacrimosas y luego pardo-herrumbre.','Seta de San Jorge con olor harinoso-a pepino (marcador de comestible); hebeloma con olor a rábano (indicio de toxicidad).','Ambos pueden aparecer en primavera — la seta de San Jorge clásicamente hacia San Jorge (finales de abril/mayo) en corros de brujas en praderas/bordes de bosque.','Seta de San Jorge con esporada blanca frente a herrumbre-oliva en el hebeloma lacrimoso — carácter distintivo más seguro.','Hacer siempre una impronta de esporada: blanco = posible seta de San Jorge, herrumbre/pardo = hebeloma a descartar; comprobar además el olor harinoso (bueno) frente al olor a rábano (advertencia).','{"La seta de San Jorge huele fuertemente a harina/pepino; el hebeloma lacrimoso huele a rábano — el olor a rábano es una señal de alarma","La seta de San Jorge tiene esporada BLANCA; Hebeloma crustuliniforme tiene esporada herrumbre a pardo-oliva","En el hebeloma lacrimoso, de joven cuelgan gotitas acuosas del filo de las láminas que dejan manchas de esporas pardas — en la seta de San Jorge faltan estas láminas lacrimosas","La seta de San Jorge tiene de joven láminas apretadas, blancas, de inserción recta; las láminas del hebeloma son gris-pardas claras y viran a pardo-herrumbre"}','f'),
('calocybe_gambosa','hebeloma_crustuliniforme','fr','Mousseron de la Saint-Georges crème-blanc à lamelles blanches serrées ; hébélome (« faux clitocybe larmoyant ») gris-argile pâle à lamelles larmoyantes puis brun-rouille.','Mousseron de la Saint-Georges à odeur farineuse-de concombre (marqueur de comestible) ; hébélome à odeur de raifort (indice de toxicité).','Tous deux peuvent apparaître au printemps — le mousseron classiquement vers la Saint-Georges (fin avril/mai) en ronds de sorcière sur prairies/lisières.','Mousseron à sporée blanche contre rouille-olive chez l''hébélome larmoyant — caractère de séparation le plus sûr.','Toujours faire une empreinte de sporée : blanc = mousseron possible, rouille/brun = hébélome et à rejeter ; vérifier en plus l''odeur de farine (bon) contre l''odeur de raifort (avertissement).','{"Le mousseron de la Saint-Georges sent fortement la farine/le concombre ; l''hébélome larmoyant sent le raifort — l''odeur de raifort est un signal d''alarme","Le mousseron a une sporée BLANCHE ; Hebeloma crustuliniforme a une sporée rouille à brun-olive","Chez l''hébélome larmoyant, des gouttelettes aqueuses pendent jeunes au tranchant des lamelles et laissent des taches de spores brunes — chez le mousseron ces lamelles larmoyantes font défaut","Le mousseron a jeune des lamelles serrées, blanches, droitement attachées ; les lamelles de l''hébélome sont gris-brun clair et virent au brun-rouille"}','f'),
('calocybe_gambosa','hebeloma_crustuliniforme','it','Prugnolo (fungo di San Giorgio) crema-bianco con lamelle bianche fitte; hebeloma («lacrimoso») grigio-argilla pallido con lamelle lacrimanti poi bruno-ruggine.','Prugnolo dall''odore farinoso-di cetriolo (marcatore di commestibile); hebeloma dall''odore di rafano (indizio di tossicità).','Entrambi possono comparire in primavera — il prugnolo classicamente attorno a San Giorgio (fine aprile/maggio) in cerchi delle streghe su prati/margini boschivi.','Prugnolo con sporata bianca contro ruggine-oliva nell''hebeloma lacrimoso — carattere distintivo più sicuro.','Fare sempre un''impronta sporale: bianco = possibile prugnolo, ruggine/bruno = hebeloma da scartare; controllare inoltre l''odore farinoso (buono) contro l''odore di rafano (avvertimento).','{"Il prugnolo odora fortemente di farina/cetriolo; l''hebeloma lacrimoso odora di rafano — l''odore di rafano è un segnale di allarme","Il prugnolo ha sporata BIANCA; Hebeloma crustuliniforme ha sporata ruggine fino a bruno-oliva","Nell''hebeloma lacrimoso da giovane pendono goccioline acquose dal filo delle lamelle che lasciano macchie sporali brune — nel prugnolo queste lamelle lacrimanti mancano","Il prugnolo ha da giovane lamelle fitte, bianche, attaccate dritte; le lamelle dell''hebeloma sono grigio-brune chiare e virano al bruno-ruggine"}','f'),
('calocybe_gambosa','hebeloma_sinapizans','en','St George''s mushroom cream-white, compact, white gills; Hebeloma (bitter poison pie) clay-brown with grey-brown gills and a bulbous base.','St George''s mushroom mealy-cucumbery; bitter poison pie with an intense radish smell.','St George''s mushroom appears in spring (May) in fairy rings; Hebeloma sinapizans mainly August–October in broadleaf forest (beech, limestone).','St George''s mushroom with white spore print vs. rust-brown in the bitter poison pie — the most reliable distinguishing feature.','Spore print + smell decide: white powder and mealy smell = possible St George''s mushroom; rust-brown powder and radish smell = Hebeloma and absolutely discard.','{"St George''s mushroom smells of meal/cucumber; the bitter poison pie smells strongly of radish and tastes bitter — the radish smell is a warning sign","St George''s mushroom has a WHITE spore print; Hebeloma sinapizans has a rust-brown spore print","St George''s mushroom gills white and crowded when young; Hebeloma gills grey-brown, emarginate-attached, NOT weeping, often with a cone-like projection into the stem (lengthwise cut)","The bitter poison pie is squat-fleshy on calcareous soils under beech, main growth late in the year"}','f'),
('calocybe_gambosa','hebeloma_sinapizans','es','Seta de San Jorge crema-blanca, compacta, láminas blancas; hebeloma (de rábano) pardo-arcilla con láminas gris-pardas y base bulbosa.','Seta de San Jorge harinosa-a pepino; hebeloma de rábano con olor a rábano intenso.','La seta de San Jorge aparece en primavera (mayo) en corros de brujas; Hebeloma sinapizans sobre todo de agosto a octubre en bosque de frondosas (haya, caliza).','Seta de San Jorge con esporada blanca frente a herrumbre-pardo en el hebeloma de rábano — carácter distintivo más seguro.','La impronta de esporada + el olor deciden: polvo blanco y olor harinoso = posible seta de San Jorge; polvo herrumbre-pardo y olor a rábano = hebeloma y descartar imperativamente.','{"La seta de San Jorge huele a harina/pepino; el hebeloma de rábano huele fuertemente a rábano y sabe amargo — el olor a rábano es una señal de alarma","La seta de San Jorge tiene esporada BLANCA; Hebeloma sinapizans tiene esporada herrumbre-parda","Láminas de la seta de San Jorge de joven blancas y apretadas; láminas del hebeloma gris-pardas, escotado-adheridas, NO lacrimosas, a menudo con una prolongación cónica en el pie (corte longitudinal)","El hebeloma de rábano es rechoncho-carnoso en suelos calcáreos bajo haya, crecimiento principal tarde en el año"}','f'),
('calocybe_gambosa','hebeloma_sinapizans','fr','Mousseron de la Saint-Georges crème-blanc, compact, lamelles blanches ; hébélome à odeur de raifort (« faux clitocybe ») brun-argile à lamelles gris-brun et base bulbeuse.','Mousseron de la Saint-Georges farineux-de concombre ; hébélome à odeur de raifort intense.','Mousseron apparaît au printemps (mai) en ronds de sorcière ; Hebeloma sinapizans surtout d''août à octobre en forêt feuillue (hêtre, calcaire).','Mousseron à sporée blanche contre rouille-brun chez l''hébélome à odeur de raifort — caractère de séparation le plus sûr.','L''empreinte de sporée + l''odeur décident : poudre blanche et odeur de farine = mousseron possible ; poudre rouille-brun et odeur de raifort = hébélome et à rejeter impérativement.','{"Le mousseron sent la farine/le concombre ; l''hébélome à odeur de raifort sent fortement le raifort et a un goût amer — l''odeur de raifort est un signal d''alarme","Le mousseron a une sporée BLANCHE ; Hebeloma sinapizans a une sporée rouille-brun","Lamelles du mousseron jeunes blanches et serrées ; lamelles de l''hébélome gris-brun, échancrées-attachées, NON larmoyantes, souvent avec un prolongement en forme de cône dans le pied (coupe longitudinale)","L''hébélome à odeur de raifort est trapu-charnu sur sols calcaires sous hêtre, croissance principale tard dans l''année"}','f'),
('calocybe_gambosa','hebeloma_sinapizans','it','Prugnolo (fungo di San Giorgio) crema-bianco, compatto, lamelle bianche; hebeloma (di rafano) bruno-argilla con lamelle grigio-brune e base bulbosa.','Prugnolo farinoso-di cetriolo; hebeloma di rafano dall''odore di rafano intenso.','Il prugnolo compare in primavera (maggio) in cerchi delle streghe; Hebeloma sinapizans soprattutto da agosto a ottobre nel bosco di latifoglie (faggio, calcare).','Prugnolo con sporata bianca contro ruggine-bruno nell''hebeloma di rafano — carattere distintivo più sicuro.','L''impronta sporale + l''odore decidono: polvere bianca e odore di farina = possibile prugnolo; polvere ruggine-bruna e odore di rafano = hebeloma da scartare assolutamente.','{"Il prugnolo odora di farina/cetriolo; l''hebeloma di rafano odora fortemente di rafano e ha sapore amaro — l''odore di rafano è un segnale di allarme","Il prugnolo ha sporata BIANCA; Hebeloma sinapizans ha sporata ruggine-bruna","Lamelle del prugnolo da giovani bianche e fitte; lamelle dell''hebeloma grigio-brune, smarginato-attaccate, NON lacrimanti, spesso con un prolungamento conico nel gambo (taglio longitudinale)","L''hebeloma di rafano è tozzo-carnoso su suoli calcarei sotto faggio, crescita principale tardi nell''anno"}','f'),
('calocybe_gambosa','inocybe_erubescens','en','Both appear in spring, pale-coloured; the fibrecap (Inocybe erubescens) is radially fibrous/cracked and reddening, the St. George''s mushroom (Calocybe gambosa) is smooth-fleshy.','St. George''s mushroom (Calocybe gambosa) strongly mealy-cucumbery; fibrecap (Inocybe erubescens) sweetish-spermatic','both meadows/forest edges, calcareous soil, same season','St. George''s mushroom (Calocybe gambosa) white, fibrecap (Inocybe erubescens) brown','DEADLY (muscarine). White gills + mealy smell + no reddening are mandatory — otherwise hands off.','{"St. George''s mushroom (Calocybe gambosa): white gills at every age + mealy smell, flesh does NOT redden","Fibrecap (Inocybe erubescens): flesh reddens, grey-brown gills, brown spore powder, high muscarine content"}','t'),
('calocybe_gambosa','inocybe_erubescens','es','Ambos de primavera, claros; el Inocybe (Inocybe erubescens) es de fibras radiales/agrietado y enrojece, mientras que la seta de San Jorge (Calocybe gambosa) es lisa y carnosa.','Seta de San Jorge: fuertemente harinoso, a pepino; Inocybe: dulzón-espermático','ambos en prados / bordes de bosque, en suelos calcáreos, misma temporada','Seta de San Jorge blanco, Inocybe marrón','MORTAL (muscarina). Láminas blancas + olor harinoso + ausencia de enrojecimiento son obligatorios — de lo contrario, no tocar.','{"Seta de San Jorge (Calocybe gambosa): láminas blancas a cualquier edad + olor harinoso, la carne NO enrojece","Inocybe (Inocybe erubescens): la carne enrojece, láminas de color gris-marrón, polvo de esporas marrón, alto contenido en muscarina"}','t'),
('calocybe_gambosa','inocybe_erubescens','fr','Les deux au printemps, clairs ; l''inocybe est fibrilleux radialement/craquelé et rougit, le mousseron de la Saint-Georges est lisse-charnu.','Mousseron de la Saint-Georges : fortement farineux-concombre ; inocybe : sucré-spermatique','les deux en prairies/lisières de forêt, sur sol calcaire, même saison','Mousseron de la Saint-Georges blanc, inocybe brun','MORTEL (muscarine). Lamelles blanches + odeur de farine + absence de rougissement sont obligatoires — sinon n''y touchez pas.','{"Mousseron de la Saint-Georges : lamelles blanches à tout âge + odeur de farine, la chair ne rougit PAS","Inocybe : la chair rougit, lamelles gris-brun, sporée brune, forte teneur en muscarine"}','t'),
('calocybe_gambosa','inocybe_erubescens','it','Entrambi primaverili, chiari; l''inocibe (Inocybe erubescens) a fibre radiali/screpolato e arrossante, il prugnolo (Calocybe gambosa) liscio-carnoso.','Prugnolo fortemente farinoso-cetriolato; inocibe dolciastro-spermatico','entrambi prati/margini di bosco, su suolo calcareo, stessa stagione','Prugnolo bianco, inocibe marrone','MORTALE (muscarina). Lamelle bianche + odore farinoso + assenza di arrossamento sono obbligatori — altrimenti giù le mani.','{"Prugnolo (Calocybe gambosa): lamelle bianche a ogni età + odore farinoso, la carne NON arrossa","Inocibe (Inocybe erubescens): la carne arrossa, lamelle grigio-marroni, sporata marrone, alto contenuto di muscarina"}','t'),
('calocybe_gambosa','inocybe_rimosa','en','The ochre-brown, conical-umbonate and radially split cap of the fibrecap stands in clear contrast to the smooth, whitish, convex cap of St. George''''s mushroom.','St. George''''s mushroom: distinctly mealy-cucumber (fresh flour); fibrecap: spermatic/sour-earthy — the mealy smell is the most important confirmatory feature for St. George''''s mushroom.','Both in meadows, hedges, path and forest edges in spring; habitat and season overlap, therefore separable only by smell and spore colour.','St. George''''s mushroom: WHITE spore print; conical fibrecap: tobacco-/grey-brown spore print — an unambiguous distinguishing feature.','Harvest St. George''''s mushrooms only if they clearly smell mealy-cucumber AND give a white spore print; every conical, radially split cap with brown spore dust and an unpleasant smell is a fibrecap — discard at once.','{"St. George''''s mushroom smells strongly mealy-cucumber; the conical fibrecap smells spermatic/earthy-unpleasant","St. George''''s mushroom cap whitish to cream, smooth, with an inrolled margin; fibrecap cap ochre/straw-brown, conical-umbonate and radially SPLIT (cracked cap surface)","St. George''''s mushroom gills white to cream, crowded; fibrecap gills pale when young, soon clay-grey-brown","Fibrecaps contain muscarine (sweating, salivation, visual disturbance 15-120 min) — the closely related deadly fibrecap (Inocybe erubescens) at the same site has even caused fatalities; St. George''''s mushroom is non-toxic","Both appear in spring (April/May) at the same site — confusion is dangerous precisely for this reason"}','f'),
('calocybe_gambosa','inocybe_rimosa','es','El sombrero ocre-pardo, cónico-mamelonado y rasgado radialmente del inocibe contrasta claramente con el sombrero liso, blanquecino y convexo de la seta de San Jorge.','Seta de San Jorge: marcadamente harinoso-a pepino (harina fresca); inocibe: espermático/ácido-terroso — el olor a harina es el carácter de confirmación más importante para la seta de San Jorge.','Ambos en prados, setos, bordes de caminos y linderos de bosque en primavera; el hábitat y la estación se solapan, por lo que solo separables por olor y color de la esporada.','Seta de San Jorge: esporada BLANCA; inocibe cónico: esporada pardo-tabaco/pardo-gris — carácter distintivo inequívoco.','Recolectar las setas de San Jorge solo si huelen claramente a harina-pepino Y dan esporada blanca; todo sombrero cónico, rasgado radialmente, con polvo de esporas pardo y olor desagradable es un inocibe — desechar de inmediato.','{"La seta de San Jorge huele fuertemente a harina-pepino; el inocibe cónico huele a espermático/terroso-desagradable","Sombrero de la seta de San Jorge blanquecino a crema, liso, con margen enrollado; sombrero del inocibe ocre/pardo paja, cónico-mamelonado y RASGADO radialmente (superficie del sombrero agrietada)","Láminas de la seta de San Jorge blancas a crema, apretadas; láminas del inocibe pálidas de jóvenes, pronto pardo-gris arcilloso","Los inocibes contienen muscarina (sudoración, salivación, trastornos de la visión 15-120 min) — el inocibe de Patouillard muy afín (Inocybe erubescens), en el mismo lugar, ha causado incluso muertes; la seta de San Jorge es inocua","Ambos aparecen en primavera (abril/mayo) en el mismo lugar — la confusión es peligrosa precisamente por ello"}','f'),
('calocybe_gambosa','inocybe_rimosa','fr','Le chapeau ocre-brun, conique-mamelonné et déchiré radialement de l''inocybe contraste nettement avec le chapeau lisse, blanchâtre et convexe du mousseron de la Saint-Georges.','Mousseron de la Saint-Georges: nettement farineux-concombre (farine fraîche); inocybe: spermatique/aigre-terreux — l''odeur de farine est le caractère de confirmation le plus important pour le mousseron.','Tous deux dans les prés, haies, bords de chemins et lisières au printemps; l''habitat et la saison se chevauchent, d''où une séparation uniquement par l''odeur et la couleur de la sporée.','Mousseron de la Saint-Georges: sporée BLANCHE; inocybe à chapeau conique: sporée brun-tabac/brun-gris — caractère distinctif sans équivoque.','Ne récolter les mousserons que s''ils sentent clairement la farine-concombre ET donnent une sporée blanche; tout chapeau conique, déchiré radialement, à poussière sporale brune et à odeur désagréable est un inocybe — à éliminer aussitôt.','{"Le mousseron de la Saint-Georges sent fortement la farine-concombre; l''inocybe à chapeau conique sent le spermatique/terreux-désagréable","Chapeau du mousseron blanchâtre à crème, lisse, à marge enroulée; chapeau de l''inocybe ocre/brun paille, conique-mamelonné et DÉCHIRÉ radialement (surface du chapeau fissurée)","Lames du mousseron blanches à crème, serrées; lames de l''inocybe jeunes pâles, bientôt brun-gris argileux","Les inocybes contiennent de la muscarine (sueurs, salivation, troubles de la vue 15-120 min) — l''inocybe de Patouillard très proche (Inocybe erubescens), au même endroit, a même provoqué des décès; le mousseron est inoffensif","Tous deux apparaissent au printemps (avril/mai) au même endroit — la confusion est dangereuse précisément pour cette raison"}','f'),
('calocybe_gambosa','inocybe_rimosa','it','Il cappello ocra-bruno, conico-umbonato e fessurato radialmente dell''inocibe contrasta nettamente con il cappello liscio, biancastro e convesso del prugnolo.','Prugnolo: marcatamente farinoso-cetriolo (farina fresca); inocibe: spermatico/acidulo-terroso — l''odore di farina è il carattere di conferma più importante per il prugnolo.','Entrambi in prati, siepi, bordi di sentieri e margini boschivi in primavera; l''habitat e la stagione si sovrappongono, perciò separabili solo tramite odore e colore della sporata.','Prugnolo: sporata BIANCA; inocibe conico: sporata bruno-tabacco/bruno-grigia — carattere distintivo inequivocabile.','Raccogliere i prugnoli solo se odorano chiaramente di farina-cetriolo E danno sporata bianca; ogni cappello conico, fessurato radialmente, con polvere sporale bruna e odore sgradevole è un inocibe — eliminare subito.','{"Il prugnolo odora fortemente di farina-cetriolo; l''inocibe conico odora di spermatico/terroso-sgradevole","Cappello del prugnolo biancastro fino a color crema, liscio, con margine arrotolato; cappello dell''inocibe ocra/bruno paglia, conico-umbonato e FESSURATO radialmente (superficie del cappello screpolata)","Lamelle del prugnolo bianche fino a crema, fitte; lamelle dell''inocibe da giovani pallide, presto bruno-grigio argilla","Gli inocibi contengono muscarina (sudorazione, salivazione, disturbi della vista 15-120 min) — l''inocibe di Patouillard molto affine (Inocybe erubescens), nello stesso luogo, ha causato perfino decessi; il prugnolo è innocuo","Entrambi compaiono in primavera (aprile/maggio) nello stesso luogo — la confusione è pericolosa proprio per questo"}','f'),
('calvatia_gigantea','amanita_phalloides','en','Giant puffball: smooth, white to cream-coloured, closed outer skin, spherical, without stem/sheath/volva. Young A. phalloides in the egg: white to olive-tinged membranous universal veil, spherical-egg-shaped — deceptively similar externally, so only the cut counts.','Young puffball: pleasantly mushroomy-mild. A. phalloides mature: sweetish-honey-like to unpleasant; in the egg stage barely smellable, therefore NOT a reliable feature — never treat smell as a clearance.','Giant puffball: meadows, pastures, gardens, path edges, nutrient-rich soils (not a mycorrhizal fungus). A. phalloides: mycorrhizal fungus in deciduous/mixed forest, especially with oak and beech. Overlap at forest edges/parks possible — location alone does not protect.','Not relevant for the puffball (no gills). A. phalloides: white spore print. In the egg stage neither is informative — the distinction is made solely via the lengthwise cut.','Cut EVERY small, spherical ''puffball'' completely lengthwise (top to bottom) BEFORE use. Only if the surface is uniformly pure white and homogeneous — without any stem/gill/cap outline — is it a puffball. At the slightest internal structure: deadly death cap, discard the entire basket.','{"CUT TEST (decisive): the giant puffball has a completely homogeneous, pure-white fruit mass without internal structure. In the young death cap in the egg stage, developing gills, stem and bulb are already recognisable in the lengthwise cut as a silhouette/''embryo'' = deadly, discard immediately.","Interior colour: young puffball pure white and homogeneous inside. Any yellowish/greenish discolouration or a darker mushroom outline in the cut = not a puffball.","Outer covering: the puffball has a smooth, leathery-closed outer skin without a volva. The death cap egg sits in a membranous universal veil (velum universale), from which the volva and stem base develop.","A mature giant puffball (>10 cm up to 50 cm) is unmistakable — confusion is only possible with small, spherical young specimens. Rule of thumb: do not eat any ''puffball'' smaller than a palm without a cut check."}','t'),
('calvatia_gigantea','amanita_phalloides','es','Bejín gigante: piel exterior lisa, blanca a crema, cerrada, esférica, sin pie/envoltura/volva. A. phalloides joven en el huevo: envoltura general membranosa blanca a teñida de oliva, esférica-ovoide; externamente engañosamente similar, por lo que solo cuenta el corte.','Bejín joven: agradablemente suave, a hongo. A. phalloides madura: dulzón-amielado hasta desagradable; en el estadio de huevo apenas perceptible, por lo que NO es un rasgo fiable; nunca interpretar el olor como autorización para consumir.','Bejín gigante: prados, pastizales, jardines, bordes de caminos, suelos ricos en nutrientes (no es hongo micorrícico). A. phalloides: hongo micorrícico de bosques de frondosas/mixtos, sobre todo junto a roble y haya. Posible solapamiento en bordes de bosque/parques; el hábitat por sí solo no protege.','En el bejín no es relevante (sin láminas). A. phalloides: esporada blanca. En el estadio de huevo ninguno de los dos es concluyente; la distinción se hace únicamente mediante el corte longitudinal.','Cortar CADA pequeño ''bejín'' esférico ANTES de usarlo, longitudinalmente (de arriba abajo) y por completo. Solo si la superficie es de un blanco puro y homogénea en toda su extensión —sin ninguna silueta de pie/láminas/sombrero— es un bejín. Ante la mínima estructura interna: oronja verde mortal, desechar todo el cesto.','{"PRUEBA DE CORTE (decisiva): el bejín gigante tiene una carne completamente homogénea, de un blanco puro y sin estructura interna. En la oronja verde joven en estadio de huevo, en el corte longitudinal ya se reconocen láminas incipientes, pie y bulbo como silueta/''embrión'' = mortal, desechar de inmediato.","Color interior: el bejín joven es por dentro de un blanco puro y homogéneo. Cualquier coloración amarillenta/verdosa o una silueta de hongo más oscura en el corte = no es un bejín.","Envoltura exterior: el bejín tiene una piel exterior lisa, coriácea y cerrada, sin volva. El huevo de la oronja verde está dentro de una envoltura general membranosa (velo universal), a partir de la cual se forman la volva y la base del pie.","El bejín gigante maduro (>10 cm hasta 50 cm) es inconfundible; la confusión solo es posible con ejemplares jóvenes, pequeños y esféricos. Regla práctica: no comer ningún ''bejín'' más pequeño que la palma de la mano sin control por corte."}','t'),
('calvatia_gigantea','amanita_phalloides','fr','Vesse-de-loup géante : peau extérieure lisse, blanche à crème, fermée, sphérique, sans pied/enveloppe/volve. A. phalloides jeune dans l''œuf : enveloppe générale membraneuse blanche à teintée d''olive, sphérique-ovoïde — extérieurement à s''y méprendre, c''est pourquoi seule la coupe compte.','Vesse-de-loup jeune : agréablement champignonnée-douce. A. phalloides mûr : douceâtre-mielleux jusqu''à désagréable ; au stade « œuf » à peine perceptible, donc PAS un critère fiable — ne jamais considérer l''odeur comme un feu vert.','Vesse-de-loup géante : prés, pâturages, jardins, bords de chemins, sols riches en nutriments (pas un champignon mycorhizien). A. phalloides : champignon mycorhizien des forêts de feuillus/mixtes, surtout sous chêne et hêtre. Recouvrement possible en lisière de forêt/dans les parcs — le lieu seul ne protège pas.','Chez la vesse-de-loup : non pertinent (pas de lamelles). A. phalloides : sporée blanche. Au stade « œuf », les deux ne sont pas significatifs — distinction uniquement par la coupe longitudinale.','Couper CHAQUE petite « vesse-de-loup » sphérique entièrement dans la longueur (du haut vers le bas) AVANT utilisation. Ce n''est une vesse-de-loup que si la surface est d''un blanc pur et homogène d''un bout à l''autre — sans aucun contour de pied/de lamelles/de chapeau. À la moindre structure interne : amanite phalloïde mortelle, jeter tout le panier.','{"TEST DE COUPE (décisif) : la vesse-de-loup géante a une chair fertile entièrement homogène, d''un blanc pur, sans structure interne. Chez la jeune amanite phalloïde au stade « œuf », la coupe longitudinale révèle déjà des lamelles, un pied et un bulbe ébauchés, en silhouette/« embryon » = mortelle, jeter immédiatement.","Couleur interne : jeune vesse-de-loup d''un blanc pur et homogène à l''intérieur. Toute coloration jaunâtre/verdâtre ou tout contour de champignon plus sombre à la coupe = pas une vesse-de-loup.","Enveloppe externe : la vesse-de-loup a une peau extérieure lisse, coriace-fermée, sans volve. L''œuf de l''amanite phalloïde est logé dans une enveloppe générale membraneuse (velum universale), d''où se forment la volve et la base du pied.","La vesse-de-loup géante mûre (>10 cm jusqu''à 50 cm) est inconfondable — la confusion n''est possible que pour de petits jeunes spécimens sphériques. Règle empirique : ne pas manger une « vesse-de-loup » plus petite qu''une paume de main sans contrôle par coupe."}','t'),
('calvatia_gigantea','amanita_phalloides','it','Vescia gigante: pelle esterna liscia, bianca fino a color crema, chiusa, sferica, senza gambo/involucro/volva. A. phalloides giovane nell''uovo: involucro generale membranoso da bianco a tonalità olivastra, sferico-ovoidale — esteriormente ingannevolmente simile, perciò conta solo il taglio.','Vescia giovane: gradevolmente di fungo-lieve. A. phalloides matura: dolciastra-simile al miele fino a sgradevole; nello stadio a uovo appena percepibile, perciò NON un carattere affidabile — non considerare mai l''odore come via libera.','Vescia gigante: prati, pascoli, giardini, bordi di sentiero, suoli ricchi di nutrienti (non fungo micorrizico). A. phalloides: fungo micorrizico nel bosco di latifoglie/misto, soprattutto presso quercia e faggio. Sovrapposizione possibile ai margini dei boschi/nei parchi — il luogo da solo non protegge.','Nella vescia non rilevante (nessuna lamella). A. phalloides: sporata bianca. Nello stadio a uovo entrambe non significative — distinzione unicamente attraverso il taglio longitudinale.','Tagliare completamente per il lungo (dall''alto verso il basso) OGNI piccola ''vescia'' sferica PRIMA dell''utilizzo. Solo se la superficie è uniformemente di un bianco puro e omogenea — senza alcuna sagoma di gambo/lamelle/cappello — è una vescia. Alla minima struttura interna: mortale amanita falloide, gettare l''intero cesto.','{"TEST DEL TAGLIO (decisivo): la vescia gigante ha una massa carnosa completamente omogenea, di un bianco puro, senza struttura interna. Nella giovane amanita falloide nello stadio a uovo, nel taglio longitudinale sono già riconoscibili lamelle, gambo e bulbo abbozzati come sagoma/''embrione'' = mortale, gettare subito.","Colore interno: vescia giovane all''interno di un bianco puro e omogenea. Qualsiasi viraggio giallastro/verdastro o una sagoma di fungo più scura nel taglio = non è una vescia.","Involucro esterno: la vescia ha una pelle esterna liscia, coriacea-chiusa, senza volva. L''uovo dell''amanita falloide è racchiuso in un involucro generale membranoso (velum universale), dal quale si formano volva e base del gambo.","La vescia gigante matura (>10 cm fino a 50 cm) è inconfondibile — confusione possibile solo con piccoli esemplari giovani, sferici. Regola pratica: non mangiare alcuna ''vescia'' più piccola di un palmo di mano senza controllo del taglio."}','t'),
('calvatia_gigantea','amanita_verna','en','Puffball: smooth white, closed, structureless outer skin, spherical. A. verna when young: pure-white veil egg; when mature, completely white with a membranous volva and ring. The egg stages are externally almost identical.','A. verna: inconspicuous to slightly unpleasant. Young puffball: mild-mushroomy. No reliable distinguishing feature in the young stage.','A. verna: mycorrhizal in (often calcareous) warmth-favoured deciduous/mixed forests with oak/sweet chestnut, appearing especially in spring/early summer, Mediterranean-tinged (southern locations). Giant puffball: grassland/pastures, more in late summer/autumn. Seasonal and location differences exist, but do not replace the cut test.','Puffball not relevant. A. verna: white spore print. In the egg stage worthless for the distinction — the cut decides.','Lengthwise cut through every small white spherical mushroom: if the silhouette of a little mushroom (stem + cap rudiment) shows in the white flesh, it is the deadly spring death cap — not the puffball.','{"A young A. verna egg is pure white and spherical like a young puffball — confusion is therefore real, especially because verna also grows in more open, warmer locations.","CUT TEST: homogeneous white puffball mass vs. an already recognisable stem + gill rudiment + bulb in the interior of the Amanita = deadly.","A. verna has a membranous volva and a stem-base bulb; the puffball has no volva and no stem.","Only the young spherical stage is confusable; a mature Amanita with cap/stem/ring is unambiguous."}','t'),
('calvatia_gigantea','amanita_verna','es','Bejín: piel exterior blanca lisa, cerrada y sin estructura, esférica. A. verna joven: huevo de velo de un blanco puro; madura completamente blanca con volva membranosa y anillo. Los estadios de huevo son externamente casi idénticos.','A. verna: inodora a ligeramente desagradable. Bejín joven: suave, a hongo. No es un rasgo distintivo fiable en el estadio joven.','A. verna: micorriza en bosques de frondosas/mixtos cálidos (a menudo calcáreos) junto a roble/castaño, aparece sobre todo en primavera/comienzos de verano, de carácter mediterráneo (umbrales del sur/zonas soleadas). Bejín gigante: praderas/pastizales, más bien a finales de verano/otoño. Existen diferencias de temporada y hábitat, pero no sustituyen la prueba de corte.','Bejín no relevante. A. verna: esporada blanca. En el estadio de huevo carece de valor para la distinción; el corte es lo decisivo.','Corte longitudinal en cada pequeño hongo esférico blanco: si en la carne blanca aparece la silueta de un pequeño hongo (pie + esbozo del sombrero), es la oronja blanca de primavera, mortal, y no el bejín.','{"El huevo joven de A. verna es de un blanco puro y esférico como un bejín joven; la confusión es por ello real, sobre todo porque verna también crece en zonas más abiertas y cálidas.","PRUEBA DE CORTE: masa de bejín blanca y homogénea frente a pie + esbozo de láminas + bulbo ya reconocibles en el interior en la Amanita = mortal.","A. verna posee volva membranosa y bulbo en la base del pie; el bejín no tiene volva ni pie.","Solo el estadio joven esférico es confundible; la Amanita madura con sombrero/pie/anillo es inequívoca."}','t'),
('calvatia_gigantea','amanita_verna','fr','Vesse-de-loup : peau extérieure lisse, blanche, fermée, sans structure, sphérique. A. verna jeune : œuf de velum d''un blanc pur ; mûr, entièrement blanc avec volve membraneuse et anneau. Les stades « œuf » sont extérieurement quasi identiques.','A. verna : discrète à légèrement désagréable. Vesse-de-loup jeune : douce-champignonnée. Pas un critère de distinction fiable au stade jeune.','A. verna : mycorhizien des forêts de feuillus/mixtes (souvent calcaires) à climat favorisé sous chêne/châtaignier, apparaît surtout au printemps/début d''été, à tonalité méditerranéenne (expositions sud). Vesse-de-loup géante : prairies/pâturages, plutôt fin d''été/automne. Des différences de saison et de station existent, mais ne remplacent pas le test de coupe.','Vesse-de-loup non pertinente. A. verna : sporée blanche. Au stade « œuf », sans valeur pour la distinction — la coupe décide.','Coupe longitudinale à travers chaque petit champignon blanc en boule : si la silhouette d''un petit champignon (pied + ébauche de chapeau) apparaît dans la chair blanche, c''est l''amanite printanière mortelle — et non la vesse-de-loup.','{"Le jeune œuf d''A. verna est d''un blanc pur et sphérique comme une jeune vesse-de-loup — la confusion est de ce fait réelle, d''autant que verna pousse aussi dans des stations plus ouvertes et plus chaudes.","TEST DE COUPE : masse blanche homogène de la vesse-de-loup vs. pied + ébauche de lamelles + bulbe déjà reconnaissables à l''intérieur chez l''amanite = mortelle.","A. verna possède une volve membraneuse et un bulbe à la base du pied ; la vesse-de-loup n''a ni volve ni pied.","Seul le jeune stade sphérique est confondable ; l''amanite mûre avec chapeau/pied/anneau est sans équivoque."}','t'),
('calvatia_gigantea','amanita_verna','it','Vescia: pelle esterna liscia, bianca, chiusa, senza struttura, sferica. A. verna giovane: uovo-velum di un bianco puro; matura completamente bianca con volva membranosa e anello. Gli stadi a uovo sono esteriormente quasi identici.','A. verna: poco appariscente fino a leggermente sgradevole. Vescia giovane: lieve-di fungo. Nessun carattere distintivo affidabile nello stadio giovane.','A. verna: micorriza in boschi di latifoglie/misti caldi (spesso calcarei) presso quercia/castagno, compare soprattutto in primavera/inizio estate, di tonalità mediterranea (esposizioni a sud). Vescia gigante: prateria/pascoli, piuttosto fine estate/autunno. Differenze di stagione e di luogo presenti, ma non sostituiscono il test del taglio.','Vescia non rilevante. A. verna: sporata bianca. Nello stadio a uovo inutile per la distinzione — decide il taglio.','Taglio longitudinale attraverso ogni piccolo fungo sferico bianco: se nella carne bianca si mostra la sagoma di un piccolo fungo (gambo + abbozzo del cappello), è l''amanita falloide primaverile, mortale — non la vescia.','{"L''uovo giovane di A. verna è di un bianco puro e sferico come una giovane vescia — la confusione è perciò reale, soprattutto perché la verna cresce anche in esposizioni più aperte e calde.","TEST DEL TAGLIO: massa bianca omogenea della vescia vs. gambo + abbozzo di lamelle + bulbo già riconoscibili all''interno nell''amanita = mortale.","A. verna possiede volva membranosa e bulbo alla base del gambo; la vescia non ha volva né gambo.","Confondibile solo nello stadio giovane sferico; l''amanita matura con cappello/gambo/anello è inequivocabile."}','t'),
('calvatia_gigantea','gemeiner-fliegenpilz-var-alba','en','Puffball: smooth, closed white skin, rounded, no stem. A. virosa when young: pure-white egg in a membranous covering; when grown, pure white with a pointed-conical cap, ring and membranous volva. In the egg stage it is barely separable externally from the puffball.','A. virosa when ripe: unpleasant, sweetish-disgusting (old finds). Young puffball: mild-mushroomy. Smell in the young/egg stage is unreliable — do not treat it as a clearance.','A. virosa: mycorrhizal in acidic coniferous/mixed forest, often with spruce/birch, rather in colder/montane mountain regions. Giant puffball: open grassland, pastures, gardens. Lower location overlap than with phalloides, but the cut test remains mandatory.','Puffball: no gills/no spore drop relevant. A. virosa: white spore print. In the confusable egg stage not usable — only the cut counts.','On every small white spherical mushroom make a lengthwise cut: a white mushroom-''embryo'' visible in the cut (stem + developing cap) exposes the destroying angel (white death cap). Only a structureless white mass = puffball.','{"A young A. virosa egg is PURE WHITE and spherical — visually practically identical to a young white puffball. Precisely for this reason the cut test is most important here.","CUT TEST: puffball = uniformly homogeneous white mass throughout; A. virosa already shows developing gills, stem and bulb in the lengthwise cut (mushroom outline inside) = deadly.","A. virosa has a membranous, sack-like volva at the stem base and (later) a ring; the puffball has neither volva nor stem nor ring.","Confusion only in the young, spherical stage — as soon as cap/stem appear on the Amanita, the distinction is trivial."}','t'),
('calvatia_gigantea','gemeiner-fliegenpilz-var-alba','es','Bejín (Bovist): piel blanca lisa y cerrada, redondeada, sin pie. A. virosa de joven: huevo de un blanco puro dentro de una envoltura membranosa; ya desarrollada de un blanco puro con sombrero cónico-puntiagudo, anillo y volva membranosa. En el estadio de huevo es externamente casi imposible de distinguir del bejín.','A. virosa madura: desagradable, dulzón-repugnante (ejemplares viejos). Bejín joven: suave, a hongo. El olor en el estadio joven/de huevo no es fiable; no debe interpretarse como autorización para consumir.','A. virosa: micorriza en bosques de coníferas/mixtos ácidos, a menudo junto a abeto rojo/abedul, más bien en regiones de montaña frías/montanas. Bejín gigante: praderas abiertas, pastizales, jardines. Menor solapamiento de hábitat que con phalloides, pero la prueba de corte sigue siendo obligatoria.','Bejín: sin láminas/sin esporada relevante. A. virosa: esporada blanca. En el estadio de huevo confundible no es utilizable; solo cuenta el corte.','En cualquier pequeño hongo esférico blanco, hacer un corte longitudinal: un ''embrión'' de hongo blanco visible en el corte (pie + sombrero incipiente) delata a la oronja blanca (Amanita virosa). Solo una masa blanca sin estructura = bejín.','{"El huevo joven de A. virosa es de un BLANCO PURO y esférico, ópticamente casi idéntico a un bejín blanco joven. Precisamente por eso la prueba de corte es aquí lo más importante.","PRUEBA DE CORTE: bejín = masa blanca homogénea en toda su extensión; A. virosa muestra en el corte longitudinal ya láminas incipientes, pie y bulbo (silueta del hongo en su interior) = mortal.","A. virosa tiene una volva membranosa en forma de saco en la base del pie y (más tarde) un anillo; el bejín no tiene ni volva ni pie ni anillo.","La confusión solo es posible en el estadio joven, esférico; en cuanto en la Amanita aparecen sombrero/pie, la distinción es trivial."}','t'),
('calvatia_gigantea','gemeiner-fliegenpilz-var-alba','fr','Vesse-de-loup : peau blanche lisse et fermée, arrondie, sans pied. A. virosa jeune : œuf d''un blanc pur dans une enveloppe membraneuse ; à maturité, entièrement blanc avec un chapeau conique-pointu, un anneau et une volve membraneuse. Au stade « œuf », extérieurement à peine dissociable de la vesse-de-loup.','A. virosa mûr : odeur désagréable, douceâtre-écœurante (vieux spécimens). Vesse-de-loup jeune : douce-champignonnée. L''odeur au stade jeune/œuf n''est pas fiable — ne pas la considérer comme un feu vert.','A. virosa : mycorhizien des forêts de conifères/mixtes acides, souvent sous épicéa/bouleau, plutôt dans les régions de montagne plus froides/montagnardes. Vesse-de-loup géante : prairies ouvertes, pâturages, jardins. Recouvrement de stations moindre que chez phalloides, mais le test de coupe reste obligatoire.','Vesse-de-loup : pas de lamelles/pas de sporée pertinente. A. virosa : sporée blanche. Au stade « œuf » confondable, inutilisable — seule la coupe compte.','Pour tout petit champignon blanc en boule, faire une coupe longitudinale : un « embryon » de champignon blanc visible à la coupe (pied + chapeau ébauché) démasque l''amanite vireuse. Seule une masse blanche sans structure = vesse-de-loup.','{"Le jeune œuf d''A. virosa est d''un BLANC PUR et sphérique — optiquement quasi identique à une jeune vesse-de-loup blanche. C''est précisément pourquoi le test de coupe est ici le plus important.","TEST DE COUPE : vesse-de-loup = masse blanche homogène d''un bout à l''autre ; A. virosa montre en coupe longitudinale des lamelles, un pied et un bulbe déjà ébauchés (contour de champignon à l''intérieur) = mortelle.","A. virosa possède une volve membraneuse, en forme de sac, à la base du pied et (plus tard) un anneau ; la vesse-de-loup n''a ni volve, ni pied, ni anneau.","Confusion uniquement au stade jeune et sphérique — dès que le chapeau/le pied de l''amanite apparaissent, la distinction est triviale."}','t'),
('calvatia_gigantea','gemeiner-fliegenpilz-var-alba','it','Vescia: pelle bianca liscia e chiusa, tondeggiante, senza gambo. A. virosa da giovane: uovo di un bianco puro in un involucro membranoso; da adulta di un bianco puro con cappello acuto-conico, anello e volva membranosa. Nello stadio a uovo esteriormente quasi indistinguibile dalla vescia.','A. virosa matura: sgradevole, dolciastra-disgustosa (vecchi ritrovamenti). Vescia giovane: lieve-di fungo. L''odore nello stadio giovane/a uovo è inaffidabile — non considerarlo come via libera.','A. virosa: micorriza in bosco acido di conifere/misto, spesso presso abete rosso/betulla, piuttosto regioni montane più fredde/montane. Vescia gigante: prateria aperta, pascoli, giardini. Minore sovrapposizione di habitat rispetto alla phalloides, ma il test del taglio resta obbligatorio.','Vescia: nessuna lamella/nessuna sporata rilevante. A. virosa: sporata bianca. Nello stadio a uovo confondibile non utilizzabile — conta solo il taglio.','Per ogni piccolo fungo sferico bianco fare un taglio longitudinale: un ''embrione'' di fungo bianco visibile nel taglio (gambo + cappello abbozzato) smaschera l''amanita falloide bianca. Solo una massa bianca senza struttura = vescia.','{"L''uovo giovane di A. virosa è di un BIANCO PURO e sferico — otticamente praticamente identico a una giovane vescia bianca. Proprio per questo il test del taglio è qui il più importante.","TEST DEL TAGLIO: vescia = massa bianca omogenea uniforme; A. virosa mostra nel taglio longitudinale già lamelle, gambo e bulbo abbozzati (sagoma del fungo all''interno) = mortale.","A. virosa ha una volva membranosa, a sacco, alla base del gambo e (più tardi) un anello; la vescia non ha né volva né gambo né anello.","Confusione solo nello stadio giovane, sferico — non appena nell''amanita compaiono cappello/gambo, la distinzione è banale."}','t'),
('calvatia_gigantea','scleroderma_citrinum','en','Giant puffball large, white, smooth and soft-shelled; common earthball small (3-10 cm), yellow-brown, hard and coarsely areolate-scurfy.','Earthball unpleasantly metallic; young giant puffball mild and pleasant.','Giant puffball on nutrient-rich, fertilised meadows, pastures, gardens and nettle margins; earthball on acidic forest soil, mycorrhizal near trees.','Earthball, when cut, early brown-black-spored; young giant puffball pure white inside without dark spore mass — edible only in this state.','Eat only large white puffballs that are COMPLETELY snow-white and homogeneous in longitudinal section. Any dark marbling, yellowish discolouration or hard shell means either overripe (inedible) or earthball (toxic).','{"Confusion in practice only with YOUNG/small specimens: mature giant puffballs (15-50 cm) are unmistakable, but young small ones are spherical and whitish like a puffball.","Giant puffball, when cut and young, uniformly snow-white and soft like cotton wool; earthball, when cut already young, dark/greyish marbled.","The earthball has a hard, thick, tough shell; the giant puffball a thin, soft, leathery casing.","The earthball smells metallic-unpleasant; the young giant puffball mildly mushroomy."}','f'),
('calvatia_gigantea','scleroderma_citrinum','es','Bejín gigante grande, blanco, liso y de cáscara blanda; escleroderma pequeño (3-10 cm), pardo-amarillo, duro y de superficie groseramente areolada-costrosa.','Escleroderma de olor metálico desagradable; bejín gigante joven suave y agradable.','Bejín gigante en prados ricos en nutrientes y abonados, pastos, jardines y orlas de ortigas; escleroderma sobre suelo forestal ácido, micorrízico junto a los árboles.','Escleroderma, al corte, con esporas pardo-negras tempranamente; bejín gigante joven interior blanco puro sin masa esporal oscura — comestible solo en este estado.','Comer solo los bejines grandes y blancos que, en sección longitudinal, sean COMPLETAMENTE blanco nieve y homogéneos. Todo veteado oscuro, coloración amarillenta o cáscara dura significa o sobremadurez (incomible) o escleroderma (tóxico).','{"Confusión en la práctica solo en los ejemplares JÓVENES/pequeños: los bejines gigantes adultos (15-50 cm) son inconfundibles, pero los jóvenes pequeños son esféricos y blanquecinos como un bejín.","Bejín gigante, al corte y de joven, uniformemente blanco nieve y blando como algodón; escleroderma, al corte ya de joven, veteado oscuro/grisáceo.","El escleroderma tiene una cáscara dura, gruesa y tenaz; el bejín gigante una envoltura fina, blanda y coriácea.","El escleroderma huele a metálico-desagradable; el bejín gigante joven huele suavemente a hongo."}','f'),
('calvatia_gigantea','scleroderma_citrinum','fr','Vesse-de-loup géante grande, blanche, lisse et à enveloppe molle; scléroderme petit (3-10 cm), brun-jaune, dur et à surface grossièrement aréolée-croûteuse.','Scléroderme à odeur métallique désagréable; jeune vesse-de-loup géante douce et agréable.','Vesse-de-loup géante sur prairies riches et fertilisées, pâturages, jardins et ourlets d''orties; scléroderme sur sol forestier acide, mycorhizien près des arbres.','Scléroderme, à la coupe, à spores brun-noir précocement; jeune vesse-de-loup géante intérieur d''un blanc pur sans masse sporale sombre — comestible uniquement dans cet état.','Ne manger que les vesses grandes et blanches qui, en coupe longitudinale, sont COMPLÈTEMENT blanc neige et homogènes. Toute marbrure sombre, coloration jaunâtre ou enveloppe dure signifie soit surmaturité (immangeable) soit scléroderme (toxique).','{"Confusion en pratique seulement chez les JEUNES/petits exemplaires: les vesses-de-loup géantes adultes (15-50 cm) sont impossibles à confondre, mais les jeunes petites sont sphériques et blanchâtres comme une vesse.","Vesse-de-loup géante, à la coupe et jeune, uniformément blanc neige et molle comme de l''ouate; scléroderme, à la coupe déjà jeune, marbré sombre/grisâtre.","Le scléroderme a une enveloppe dure, épaisse et coriace; la vesse-de-loup géante une enveloppe fine, molle et cuir.","Le scléroderme sent le métallique-désagréable; la jeune vesse-de-loup géante sent doucement le champignon."}','f'),
('calvatia_gigantea','scleroderma_citrinum','it','Vescia gigante grande, bianca, liscia e a guscio molle; scleroderma piccolo (3-10 cm), bruno-giallo, duro e a superficie grossolanamente areolata-crostosa.','Scleroderma odore metallico sgradevole; giovane vescia gigante dolce e gradevole.','Vescia gigante su prati ricchi e concimati, pascoli, giardini e bordure di ortiche; scleroderma su suolo forestale acido, micorrizico presso gli alberi.','Scleroderma, al taglio, con spore bruno-nere precocemente; giovane vescia gigante interno bianco puro senza massa sporale scura — commestibile solo in questo stato.','Mangiare solo le vesce grandi e bianche che, in sezione longitudinale, sono COMPLETAMENTE bianco neve e omogenee. Ogni marezzatura scura, colorazione giallastra o guscio duro significa o sovramaturazione (immangiabile) o scleroderma (tossico).','{"Confusione in pratica solo negli esemplari GIOVANI/piccoli: le vesce giganti adulte (15-50 cm) sono inconfondibili, ma quelle giovani piccole sono sferiche e biancastre come una vescia.","Vescia gigante, al taglio e da giovane, uniformemente bianco neve e molle come ovatta; scleroderma, al taglio già da giovane, marezzato scuro/grigiastro.","Lo scleroderma ha un guscio duro, spesso e tenace; la vescia gigante un involucro sottile, molle e simile a cuoio.","Lo scleroderma odora di metallico-sgradevole; la giovane vescia gigante odora delicatamente di fungo."}','f'),
('champignon-de-paris','agaricus_xanthodermus','en','Yellow-staining mushroom (Karbol-Champignon): the stem base turns immediately chrome-yellow when cut, the cap centre is often greyish-metallic, and the stem base is bulbous without any flap of skin. Cultivated/field mushroom: the cut surface stays whitish to slightly reddish, with no yellow stem base.','The yellow-staining mushroom smells pungently of carbolic/phenol/ink (intensified by heating and by rubbing the stem base). Edible mushrooms smell pleasantly mushroomy, nutty, or of aniseed.','Both grow on nutrient-rich meadows, pastures, in parks and at forest edges, from summer to autumn — location does NOT help with the distinction.','Both are chocolate-brown — spore print colour is NOT a distinguishing feature here; watch for yellow staining and smell.','Cut the stem base lengthwise: strong chrome-yellow staining at the stem base + a carbolic/ink smell = toxic, discard the mushroom. Do not taste it orally. The consequences are severe gastrointestinal complaints (nausea, vomiting, diarrhoea), usually not life-threatening.','{"The stem base stains immediately and intensely chrome-yellow (bright yellow) when cut/squeezed — edible mushrooms stain at most faintly yellowish at the cap margin, NEVER strongly yellow at the stem base.","Smells unpleasant of carbolic/phenol or ink (best detected on the rubbed stem base or when heating) — edible mushrooms smell mushroomy, nutty, or of aniseed/almond.","Stem base bulbously thickened WITHOUT any flap of skin/volva; young cap often with a grey-metallic sheen in the centre; gills pink when young, dark chocolate-brown with age.","Identical growing site (meadows, pastures, parks, forest edges, nutrient-rich soils), hence frequent real-world confusion — location does NOT help with the distinction."}','t'),
('champignon-de-paris','agaricus_xanthodermus','es','Champiñón amarilleante (Karbol/de bosque): la base del pie se vuelve inmediatamente de color amarillo cromo al cortarla, el centro del sombrero a menudo es grisáceo-metálico, la base del pie es bulbosa sin piel lobulada. Champiñón de cultivo/champiñón de prado: la superficie de corte permanece blanquecina o ligeramente rojiza, sin base del pie amarilla.','El champiñón amarilleante huele penetrante a carbólico/fenol/tinta (se intensifica al calentarlo y al frotar la base del pie). Los champiñones comestibles huelen agradablemente a hongo, a nuez o a anís.','Ambos en prados ricos en nutrientes, pastizales, parques y bordes de bosque, de verano a otoño; el hábitat NO ayuda a distinguirlos.','Ambos de color marrón chocolate; aquí el color de la esporada NO es un rasgo distintivo; fijarse en el amarilleamiento y en el olor.','Cortar la base del pie longitudinalmente: un amarilleamiento intenso de color amarillo cromo en la base del pie + olor a carbólico/tinta = tóxico, desechar el hongo. No probar por vía oral. Las consecuencias son molestias gastrointestinales fuertes (náuseas, vómitos, diarrea), por lo general no potencialmente mortales.','{"La base del pie se vuelve inmediatamente de un intenso amarillo cromo (amarillo brillante) al cortarla/aplastarla; los champiñones comestibles amarillean a lo sumo levemente en el borde del sombrero, NUNCA de forma intensa en la base del pie.","Huele desagradablemente a carbólico/fenol o a tinta (se percibe mejor en la base del pie frotada o al calentarlo); los champiñones comestibles huelen a hongo, a nuez o a anís/almendra.","Base del pie engrosada de forma bulbosa SIN piel lobulada/volva; el sombrero joven a menudo con un brillo gris-metálico en el centro; láminas rosadas de jóvenes, marrón chocolate oscuro con la edad.","Lugar de crecimiento idéntico (prados, pastizales, parques, bordes de bosque, suelos ricos en nutrientes), por lo que la confusión real es frecuente; el hábitat NO ayuda a distinguirlos."}','t'),
('champignon-de-paris','agaricus_xanthodermus','fr','Agaric jaunissant : la base du pied vire immédiatement au jaune chrome à la coupe, le centre du chapeau est souvent gris-métallique, la base du pied est bulbeuse sans peau lobée. Champignon de Paris/agaric des prés : la surface de coupe reste blanchâtre à légèrement rosée, pas de base de pied jaune.','L''agaric jaunissant dégage une odeur âcre de carbol/phénol/encre (renforcée à la chauffe et en frottant la base du pied). Les champignons comestibles sentent agréablement le champignon, la noisette ou l''anis.','Les deux poussent dans des prés riches en nutriments, des pâturages, des parcs et en lisière de forêt, de l''été à l''automne – le lieu de croissance n''aide PAS à les distinguer.','Les deux ont une sporée brun chocolat – la couleur de la sporée n''est ici PAS un critère de distinction ; se fier au jaunissement et à l''odeur.','Entailler la base du pied dans le sens de la longueur : un jaunissement jaune chrome vif à la base du pied + une odeur de carbol/d''encre = toxique, jeter le champignon. Ne pas le goûter par voie orale. Les suites sont de violents troubles gastro-intestinaux (nausées, vomissements, diarrhée), en règle générale non mortels.','{"La base du pied vire immédiatement et intensément au jaune chrome (jaune éclatant) à la coupe/au pincement – les champignons comestibles jaunissent tout au plus légèrement au bord du chapeau, JAMAIS fortement au jaune à la base du pied.","Dégage une odeur désagréable de carbol/phénol ou d''encre (perceptible surtout sur la base du pied frottée ou à la chauffe) – les champignons comestibles sentent le champignon, la noisette ou l''anis/l''amande.","Base du pied épaissie en bulbe SANS peau lobée/volve ; le jeune chapeau présente souvent un reflet gris-métallique au centre ; lamelles roses jeunes, brun chocolat foncé avec l''âge.","Lieu de croissance identique (prés, pâturages, parcs, lisières de forêt, sols riches en nutriments), d''où une confusion réelle fréquente – le lieu de croissance n''aide PAS à les distinguer."}','t'),
('champignon-de-paris','agaricus_xanthodermus','it','Prataiolo giallo (Agaricus xanthodermus): la base del gambo, al taglio, vira immediatamente al giallo cromo, il centro del cappello è spesso grigiastro-metallico, la base del gambo è bulbosa senza pelle a lembi. Champignon coltivato/prataiolo: la superficie di taglio rimane biancastra fino a leggermente rossastra, nessuna base del gambo gialla.','Il prataiolo giallo odora in modo pungente di carbolo/fenolo/inchiostro (intensificato al riscaldamento e sfregando la base del gambo). I prataioli commestibili odorano gradevolmente di fungo, di nocciola o di anice.','Entrambi su prati ricchi di nutrienti, pascoli, nei parchi e ai margini dei boschi, dall''estate all''autunno – il luogo di crescita NON aiuta nella distinzione.','Entrambi color cioccolato – qui il colore della sporata NON è un carattere distintivo; fare attenzione all''ingiallimento e all''odore.','Tagliare la base del gambo per il lungo: un netto viraggio al giallo cromo alla base del gambo + odore di carbolo/inchiostro = velenoso, gettare il fungo. Non assaggiare per via orale. Le conseguenze sono violenti disturbi gastro-intestinali (nausea, vomito, diarrea), di norma non pericolosi per la vita.','{"La base del gambo, al taglio/alla compressione, vira immediatamente in modo intenso al giallo cromo (giallo brillante) – i prataioli commestibili viranno al massimo debolmente al giallastro sul bordo del cappello, MAI in modo deciso al giallo alla base del gambo.","Odora sgradevolmente di carbolo/fenolo ovvero di inchiostro (percepibile al meglio alla base del gambo sfregata o al riscaldamento) – i prataioli commestibili odorano di fungo, di nocciola o di anice/mandorla.","Base del gambo ingrossata a bulbo SENZA pelle a lembi/volva; il cappello giovane ha spesso un riflesso grigio-metallico al centro; lamelle rosa da giovani, color cioccolato scuro da vecchie.","Luogo di crescita identico (prati, pascoli, parchi, margini dei boschi, suoli ricchi di nutrienti), perciò frequente confusione reale – il luogo NON aiuta nella distinzione."}','t'),
('champignon-de-paris','amanita_phalloides','en','Amanita phalloides: gills stay white, a membranous white volva at the bulbous stem base, cap olive-green to (var. alba/young) white. Mushroom (champignon): pink-brown gills, no volva, stem base without a sheath.','Amanita phalloides is inconspicuous when young, mouldy-sweetish like artificial honey to unpleasant when old. Champignon smells pleasantly mushroomy/nutty/aniseed-like.','Amanita phalloides as a mycorrhizal fungus in deciduous forest (especially with oak, beech); champignons on open cultivated land, meadows and pastures.','Amanita phalloides white, champignon brown — a white spore print is a clear warning sign.','Halve a suspicious white button/egg lengthwise: the presence of white gills + a volva sheath at the base = death cap, deadly. As little as about 20 g is life-threatening — when in doubt, VAPKO mushroom inspection / Tox Info Suisse 145.','{"Gills always pure white (even in the old mushroom) — champignon gills are pink when young, brown/blackish-brown when old.","Stem base with a bulbous base surrounded by a membranous, flappy white sheath (volva) — the champignon completely lacks the volva.","Spore print white (champignon brown).","Young specimens resemble a white ''egg'' and are especially easily confused with young closed champignons — always cut them open; in section the developing white gill/volva structure shows (uniformly white-green inside, never pink)."}','t'),
('champignon-de-paris','amanita_phalloides','es','Amanita phalloides: láminas que permanecen blancas, volva membranosa blanca en la base bulbosa del pie, sombrero de verde oliva hasta (var. alba/joven) blanco. Champiñón: láminas de color rosa-marrón, sin volva, base del pie sin vaina.','Amanita phalloides de joven inodora; de vieja huele a moho dulzón, como a miel artificial, hasta desagradable. El champiñón huele agradablemente a hongo/nuez/anís.','Amanita phalloides es un hongo micorrícico de bosques de frondosas (sobre todo bajo roble, haya); los champiñones crecen en terreno agrícola abierto, prados y pastizales.','Amanita phalloides blanca, champiñón marrón; una esporada blanca es una clara señal de alarma.','Partir longitudinalmente el botón/huevo blanco sospechoso: la presencia de láminas blancas + envoltura de volva en la base = oronja verde (Amanita phalloides), mortal. Ya unos 20 g aprox. son potencialmente mortales; en caso de duda, control de hongos VAPKO / Tox Info Suisse 145.','{"Láminas siempre de un blanco puro (también en el ejemplar viejo); las láminas del champiñón son rosadas de jóvenes y marrones/marrón negruzco de viejas.","Base del pie con una base bulbosa rodeada por una vaina membranosa lobulada blanca (volva); en el champiñón la volva falta por completo.","Esporada blanca (champiñón marrón).","Los ejemplares jóvenes se asemejan a un ''huevo'' blanco y se confunden con especial facilidad con champiñones jóvenes cerrados; cortar siempre, en el corte se aprecia la estructura incipiente de láminas/volva blanca (interior uniformemente blanco-verdoso, nunca rosado)."}','t'),
('champignon-de-paris','amanita_phalloides','fr','Amanita phalloides : lamelles restant blanches, volve membraneuse blanche à la base bulbeuse du pied, chapeau vert olive à (var. alba/jeune) blanc. Champignon de Paris : lamelles rose-brun, pas de volve, base du pied sans gaine.','Amanita phalloides jeune : odeur discrète ; âgé : moisi-douceâtre rappelant le miel artificiel, jusqu''à désagréable. Champignon de Paris : agréablement champignonné/de noisette/d''anis.','Amanita phalloides est un champignon mycorhizien des forêts de feuillus (surtout sous chêne, hêtre) ; les champignons de Paris poussent en terrain cultivé ouvert, dans les prés et les pâturages.','Amanita phalloides : blanche ; champignon de Paris : brune – une sporée blanche est un signal d''alarme clair.','Couper en deux dans la longueur tout bouton/œuf blanc suspect : l''ébauche de lamelles blanches + une enveloppe de volve à la base = amanite phalloïde, mortelle. Environ 20 g suffisent déjà à mettre la vie en danger – en cas de doute, contrôle des champignons VAPKO / Tox Info Suisse 145.','{"Lamelles toujours d''un blanc pur (même chez le champignon âgé) – les lamelles du champignon de Paris sont roses jeunes, brunes/brun-noir âgées.","Base du pied bulbeuse, entourée d''une gaine membraneuse blanche lobée (volve) – chez le champignon de Paris, la volve est totalement absente.","Sporée blanche (champignon de Paris : brune).","Les jeunes exemplaires ressemblent à un « œuf » blanc et se confondent particulièrement facilement avec de jeunes champignons de Paris encore fermés – toujours couper ; à la coupe apparaît la structure de lamelles/volve blanche ébauchée (intérieur uniformément blanc-vert, jamais rose)."}','t'),
('champignon-de-paris','amanita_phalloides','it','Amanita phalloides: lamelle che restano bianche, volva membranosa bianca alla base bulbosa del gambo, cappello da verde-oliva a (var. alba/giovane) bianco. Champignon: lamelle rosa-brune, nessuna volva, base del gambo senza guaina.','Amanita phalloides da giovane poco appariscente, da vecchia di muffa-dolciastra come miele artificiale fino a sgradevole. Champignon gradevolmente di fungo/nocciola/anice.','Amanita phalloides come fungo micorrizico nel bosco di latifoglie (soprattutto presso quercia, faggio); i prataioli su terreni coltivati aperti, prati e pascoli.','Amanita phalloides bianca, champignon bruna – una sporata bianca è un chiaro segnale d''allarme.','Dimezzare per il lungo il sospetto bottone/uovo bianco: presenza di lamelle bianche + involucro-volva alla base = amanita falloide, mortale. Già ca. 20 g sono pericolosi per la vita – nel dubbio controllo funghi VAPKO / Tox Info Suisse 145.','{"Lamelle sempre di un bianco puro (anche nel fungo vecchio) – le lamelle del champignon sono rosa da giovani, brune/bruno-nere da vecchie.","Base del gambo con base bulbosa circondata da una guaina membranosa a lembi bianca (volva) – nel champignon la volva manca completamente.","Sporata bianca (champignon bruna).","Gli esemplari giovani assomigliano a un ''uovo'' bianco e vengono confusi con particolare facilità con i giovani champignon chiusi – tagliare sempre: nel taglio si mostra la struttura abbozzata di lamelle/volva bianche (all''interno uniformemente bianco-verde, mai rosa)."}','t'),
('champignon-de-paris','gemeiner-fliegenpilz-var-alba','en','Amanita virosa: pure white, often conical cap, gills stay white, bulbous stem base with a lobed white volva. Champignon: gills pink to brown, no volva, stem base not enclosed in a membranous sheath.','Amanita virosa inconspicuous to sweetish-sickening (rotting flesh). Champignon pleasantly mushroomy/nutty/aniseed-like.','Amanita virosa in woodland (often spruce/coniferous forest, acidic soils); champignons on meadows, pastures, compost, cultivated land.','Amanita virosa white, champignon brown – the spore print is a reliable distinguishing criterion (white = danger).','Always twist the mushroom out of the ground completely, including the stem base, and check for a volva (membranous sheath) at the base of the bulb – volva + permanently white gills + white spore powder = deadly, hands off. If in doubt, Tox Info Suisse 145 / VAPKO mushroom inspection.','{"The gills stay pure white at EVERY age – champignon gills are pink when young and turn chocolate-brown to blackish-brown when old (never permanently white).","At the stem base a bulbous, swollen base with a membranous, lobed white sheath (volva/egg-membrane) – champignons NEVER have a volva.","Spore powder white; champignon spore powder is brown.","Grows mostly in (coniferous) woodland, often near spruce – champignons prefer meadows, pastures and cultivated land."}','t'),
('champignon-de-paris','gemeiner-fliegenpilz-var-alba','es','Amanita virosa: sombrero blanco puro, a menudo cónico, las láminas permanecen blancas, base del pie bulbosa con volva blanca lobulada. Champiñón: láminas de rosa a marrón, sin volva, base del pie sin vaina membranosa.','Amanita virosa: discreto a dulzón-repugnante (carne en descomposición). Champiñón: agradable, a champiñón/anuez/anisado.','Amanita virosa en el bosque (a menudo abetos/bosque de coníferas, suelos ácidos); los champiñones en prados, pastos, compost, terreno cultivado.','Amanita virosa blanco, champiñón marrón – la esporada es un criterio de distinción fiable (blanco = peligro).','Extrae siempre el hongo completo, incluida la base del pie, girándolo fuera del suelo, y comprueba si hay una volva (vaina membranosa) en la base bulbosa – volva + láminas que permanecen blancas + esporada blanca = mortal, no lo toques. En caso de sospecha, Tox Info Suisse 145 / control de setas VAPKO.','{"Las láminas permanecen de un blanco puro a CUALQUIER edad – las láminas del champiñón son rosadas de jóvenes y se vuelven marrón chocolate hasta marrón negruzco al envejecer (nunca blancas de forma permanente).","En la base del pie hay una base bulbosamente engrosada con una vaina membranosa, lobulada y blanca (volva/envoltura del huevo) – los champiñones NUNCA tienen volva.","Esporada blanca; la esporada del champiñón es marrón.","Crece sobre todo en el bosque (de coníferas), a menudo junto a abetos – los champiñones prefieren prados, pastos y terreno cultivado."}','t'),
('champignon-de-paris','gemeiner-fliegenpilz-var-alba','fr','Amanita virosa: chapeau d''un blanc pur, souvent conique, lamelles restant blanches, base du pied bulbeuse avec une volve blanche en lambeaux. Champignon de Paris: lamelles roses à brunes, pas de volve, base du pied sans gaine membraneuse.','Amanita virosa: discrète à douceâtre-écœurante (chair en décomposition). Champignon de Paris: agréable, fongique/de noisette/anisée.','Amanita virosa en forêt (souvent épicéas/forêt de conifères, sols acides); les champignons de Paris dans les prairies, pâturages, composts et terres cultivées.','Amanita virosa blanche, champignon de Paris brune – la sporée est un critère de distinction fiable (blanc = danger).','Toujours extraire le champignon entièrement du sol, avec la base du pied, et vérifier la présence d''une volve (gaine membraneuse) au pied du bulbe – volve + lamelles restant blanches + sporée blanche = mortel, n''y touchez pas. En cas de doute, Tox Info Suisse 145 / contrôle des champignons VAPKO.','{"Les lamelles restent d''un blanc pur à TOUT âge – les lamelles du champignon de Paris sont roses lorsqu''elles sont jeunes et deviennent brun chocolat à brun-noir en vieillissant (jamais durablement blanches).","À la base du pied, une base bulbeuse épaissie avec une gaine membraneuse blanche en lambeaux (volve/voile) – les champignons de Paris n''ont JAMAIS de volve.","Sporée blanche; la sporée du champignon de Paris est brune.","Pousse le plus souvent en forêt (de conifères), souvent près des épicéas – les champignons de Paris préfèrent les prairies, pâturages et terres cultivées."}','t'),
('champignon-de-paris','gemeiner-fliegenpilz-var-alba','it','Amanita virosa: cappello bianco puro, spesso conico, lamelle che restano bianche, base del gambo bulbosa con volva bianca lobata e membranosa. Champignon (prataiolo): lamelle da rosa a brune, nessuna volva, base del gambo senza guaina membranosa.','Amanita virosa: odore insignificante fino a dolciastro-nauseante (carne in putrefazione). Champignon (prataiolo): gradevole odore fungino/di nocciola/anisato.','Amanita virosa: nel bosco (spesso abeti rossi/conifere, suoli acidi); i prataioli su prati, pascoli, compost, terreni coltivati.','Amanita virosa: bianco; Champignon (prataiolo): bruno – la sporata in massa è un criterio di distinzione affidabile (bianco = pericolo).','Estrarre sempre il fungo completo dal terreno, compresa la base del gambo, e verificare la presenza di una volva (guaina membranosa) alla base bulbosa – volva + lamelle che restano bianche + sporata in massa bianca = mortale, non toccare. In caso di sospetto Tox Info Suisse 145 / controllo funghi VAPKO.','{"Le lamelle restano bianche pure a OGNI età – le lamelle del prataiolo sono da giovani rosa e da vecchie diventano da bruno-cioccolato a bruno-nerastre (mai bianche in modo permanente).","Alla base del gambo una base bulbosa ingrossata con guaina bianca membranosa e lobata (volva/velo generale) – i prataioli non hanno MAI una volva.","Sporata in massa bianca; la sporata in massa del prataiolo è bruna.","Crescita per lo più nel bosco (di conifere), spesso presso abeti rossi – i prataioli prediligono prati, pascoli e terreni coltivati."}','t'),
('chlorophyllum_rhacodes','lepiota_brunneoincarnata','en','The flesh that reddens saffron/orange when cut is typical of the edible shaggy parasol and is absent in the small toxic dapperling, which is flesh-pink-brown.','Shaggy parasol with a mild mushroomy smell; toxic dapperling with a sweetish-fruity smell — smell is not a reliable criterion.','Shaggy parasol in nutrient-rich spots, compost, conifer forest, gardens; toxic dapperling in sandy-grassy, park-like places — overlap possible.','Both with whitish spore print — not a distinguishing feature, therefore check the size, the saffron reaction of the flesh and the ring.','Only harvest the (shaggy) parasol if the cap is large (over 8 cm) AND the flesh reddens saffron-orange on rubbing/cutting — always leave small parasols under 8 cm standing.','{"The shaggy parasol is large: cap 8-20 cm; the flesh-pink dapperling is small: only 2-5 cm.","Shaggy parasol: the flesh turns saffron/orange-red when cut/rubbed; the toxic dapperling does not turn saffron-red.","Shaggy parasol: thick movable ring, smooth stem (NOT snake-patterned); toxic dapperling: only a fleeting fibrous ring zone, flesh-brown scaly stem.","The flesh-pink dapperling contains deadly amatoxins; the shaggy parasol is edible (can, raw/insufficiently cooked, cause gastrointestinal upset)."}','f'),
('chlorophyllum_rhacodes','lepiota_brunneoincarnata','es','La carne que enrojece azafrán/naranja al corte es típica de la apagador rojizo/galamperna rojiza comestible y falta en la pequeña lepiota tóxica, de color pardo-rosa carne.','Galamperna rojiza con olor suave a champiñón; lepiota tóxica con olor dulzón-afrutado — el olor no es un criterio seguro.','Galamperna rojiza en lugares ricos en nutrientes, compost, bosque de coníferas, jardines; lepiota tóxica en lugares arenoso-herbosos, tipo parque — solapamiento posible.','Ambas con esporada blanquecina — no es un criterio distintivo, por ello verificar el tamaño, la reacción azafrán de la carne y el anillo.','Recolectar la galamperna (rojiza) solo si el sombrero es grande (más de 8 cm) Y si la carne enrojece azafrán-naranja al frotar/cortar — dejar siempre en el sitio las pequeñas lepiotas de menos de 8 cm.','{"La galamperna rojiza es grande: sombrero 8-20 cm; la lepiota pardo-rosada es pequeña: solo 2-5 cm.","Galamperna rojiza: la carne vira a azafrán/naranja-rojo al cortar/frotar; la lepiota tóxica no vira a azafrán-rojo.","Galamperna rojiza: anillo grueso desplazable, pie liso (NO jaspeado); lepiota tóxica: solo una fugaz zona anular fibrosa, pie con escamas pardo carne.","La lepiota pardo-rosada contiene amatoxinas mortales; la galamperna rojiza es comestible (puede, cruda/insuficientemente cocida, causar molestias gastrointestinales)."}','f'),
('chlorophyllum_rhacodes','lepiota_brunneoincarnata','fr','La chair qui rougit safran/orange à la coupe est typique de la lépiote déguenillée comestible et fait défaut à la petite lépiote toxique, brun-rose chair.','Lépiote déguenillée à odeur douce de champignon ; lépiote toxique à odeur douceâtre-fruitée — l''odeur n''est pas un critère sûr.','Lépiote déguenillée dans les endroits riches en nutriments, composts, forêt de conifères, jardins ; lépiote toxique dans les endroits sablonneux-herbeux, de type parc — chevauchement possible.','Les deux à sporée blanchâtre — pas un critère de distinction, c''est pourquoi il faut vérifier la taille, la réaction safran de la chair et l''anneau.','Ne récolter la lépiote (déguenillée) que si le chapeau est grand (plus de 8 cm) ET si la chair rougit safran-orange au frottement/à la coupe — laisser systématiquement sur place les petites lépiotes de moins de 8 cm.','{"La lépiote déguenillée est grande : chapeau 8-20 cm ; la lépiote brun-incarnat est petite : seulement 2-5 cm.","Lépiote déguenillée : la chair vire au safran/orange à la coupe/au frottement ; la lépiote toxique ne vire pas au safran.","Lépiote déguenillée : anneau épais coulissant, pied lisse (NON chiné) ; lépiote toxique : seulement une zone annulaire fibreuse fugace, pied à squames brun chair.","La lépiote brun-incarnat contient des amatoxines mortelles ; la lépiote déguenillée est comestible (peut, crue/insuffisamment cuite, provoquer des troubles gastro-intestinaux)."}','f'),
('chlorophyllum_rhacodes','lepiota_brunneoincarnata','it','La carne che arrossa zafferano/arancio al taglio è tipica della mazza di tamburo rossastra commestibile e manca alla piccola lepiota tossica, bruno-rosa carne.','Mazza di tamburo rossastra dall''odore mite di fungo; lepiota tossica dall''odore dolciastro-fruttato — l''odore non è un criterio sicuro.','Mazza di tamburo rossastra in luoghi ricchi di nutrienti, compost, bosco di conifere, giardini; lepiota tossica in luoghi sabbioso-erbosi, tipo parco — sovrapposizione possibile.','Entrambe con sporata biancastra — non è un criterio distintivo, perciò verificare la dimensione, la reazione zafferano della carne e l''anello.','Raccogliere la mazza di tamburo (rossastra) solo se il cappello è grande (oltre 8 cm) E se la carne arrossa zafferano-arancio allo sfregamento/al taglio — lasciare sempre sul posto le piccole lepiote sotto gli 8 cm.','{"La mazza di tamburo rossastra è grande: cappello 8-20 cm; la lepiota bruno-incarnata è piccola: solo 2-5 cm.","Mazza di tamburo rossastra: la carne vira allo zafferano/arancio al taglio/sfregamento; la lepiota tossica non vira allo zafferano.","Mazza di tamburo rossastra: anello spesso scorrevole, gambo liscio (NON zigrinato); lepiota tossica: solo una fugace zona anulare fibrosa, gambo con squame bruno carne.","La lepiota bruno-incarnata contiene amatossine mortali; la mazza di tamburo rossastra è commestibile (può, cruda/cotta insufficientemente, causare disturbi gastrointestinali)."}','f'),
('clavariadelphus_truncatus','ramaria_formosa','en','The truncate club (truncate Hercules'' club) is a single, apically truncate club; the beautiful coral (handsome clavaria) is repeatedly branched — the branching is the key feature.','Both inconspicuous to faintly mushroomy; smell does not separate them.','The Hercules'' club mainly in calcareous coniferous woodland; the beautiful coral rather in broadleaf woodland — a habitat difference, but not absolutely reliable.','Hercules'' club ochre-yellowish spore print, beautiful coral likewise ochrish — no practical distinguishing feature.','Only harvest unbranched, apically truncate clubs — as soon as a fungus branches shrub-like and/or tastes bitter, the poisonous beautiful coral threatens.','{"Truncate Hercules'' club: simple, unbranched club-shaped fruiting bodies with a flat-truncate, often slightly depressed apex; beautiful coral richly branched like a shrub.","Hercules'' club mostly yellow-ochre to orange-brown, solitary/clavate; beautiful coral orange-salmon with many yellow branch tips.","Hercules'' club tastes mild to sweetish; beautiful coral bitter and gastrointestinally poisonous.","Hercules'' club typically grows in lime-loving coniferous woodland (often spruce/fir); beautiful coral rather in broadleaf woodland.","The unbranched club form of the Hercules'' club rules out confusion on close inspection — confusion only happens fleetingly at young, coral-like stages."}','f'),
('clavariadelphus_truncatus','ramaria_formosa','es','La clavaria truncada (maza de Hercules truncada) es una maza unica, truncada en el apice; la ramaria hermosa (coral hermoso) esta ramificada muchas veces — la ramificacion es el caracter clave.','Ambos discretos a debilmente fungicos; el olor no los separa.','La maza de Hercules sobre todo en bosque de coniferas rico en caliza; la ramaria hermosa mas bien en bosque de frondosas — diferencia de estacion, pero no absolutamente fiable.','Maza de Hercules esporada amarillo-ocre, ramaria hermosa tambien ocracea — ningun caracter practico.','Recolectar solo mazas no ramificadas, truncadas en el apice — en cuanto un hongo se ramifica en arbusto y/o sabe amargo, amenaza la toxica ramaria hermosa.','{"Maza de Hercules truncada: cuerpos fructiferos simples, no ramificados, en forma de maza con apice plano-truncado, a menudo ligeramente deprimido; ramaria hermosa ricamente ramificada como un arbusto.","Maza de Hercules generalmente amarillo-ocre a pardo-naranja, solitaria/claviforme; ramaria hermosa naranja-salmon con muchas puntas de ramas amarillas.","Maza de Hercules sabe suave a dulzona; ramaria hermosa amarga y gastrointestinalmente toxica.","Maza de Hercules crece tipicamente en bosque de coniferas calcicola (a menudo abeto rojo/abeto blanco); ramaria hermosa mas bien en bosque de frondosas.","La forma de maza no ramificada de la maza de Hercules excluye una confusion mirando con atencion — una confusion solo ocurre fugazmente en estadios jovenes coraliformes."}','f'),
('clavariadelphus_truncatus','ramaria_formosa','fr','La massue d''Hercule tronquee est une massue unique, tronquee au sommet; la belle clavaire (ramaire jolie) est multiplement ramifiee — la ramification est le critere cle.','Les deux discrets a faiblement fongiques; l''odeur ne separe pas.','La massue d''Hercule surtout en foret de coniferes riche en calcaire; la belle clavaire plutot en foret de feuillus — difference de station, mais pas absolument fiable.','Massue d''Hercule sporee jaune-ocre, belle clavaire egalement ocree — pas de critere pratique.','Ne recolter que des massues non ramifiees, tronquees au sommet — des qu''un champignon se ramifie en buisson et/ou a un gout amer, gare a la toxique belle clavaire.','{"Massue d''Hercule tronquee: fructifications simples, non ramifiees, en forme de massue, a sommet aplati-tronque, souvent legerement deprime; belle clavaire richement ramifiee comme un buisson.","Massue d''Hercule generalement jaune-ocre a brun-orange, isolee/claviforme; belle clavaire orange-saumon avec de nombreuses pointes de rameaux jaunes.","Massue d''Hercule a saveur douce a sucree; belle clavaire amere et gastro-intestinalement toxique.","Massue d''Hercule pousse typiquement en foret de coniferes calcicole (souvent epicea/sapin); belle clavaire plutot en foret de feuillus.","La forme en massue non ramifiee de la massue d''Hercule exclut une confusion en regardant attentivement — une confusion ne survient que furtivement aux jeunes stades coralliformes."}','f'),
('clavariadelphus_truncatus','ramaria_formosa','it','La clavaria troncata (mazza d''Ercole troncata) e una clava singola, troncata all''apice; la ramaria bella e ripetutamente ramificata — la ramificazione e il carattere chiave.','Entrambi inappariscenti a debolmente fungini; l''odore non separa.','La mazza d''Ercole soprattutto in bosco di conifere ricco di calcare; la ramaria bella piuttosto in bosco di latifoglie — differenza di stazione, ma non assolutamente affidabile.','Mazza d''Ercole sporata giallo-ocra, ramaria bella anch''essa ocracea — nessun carattere pratico.','Raccogliere solo clave non ramificate, troncate all''apice — appena un fungo si ramifica a cespuglio e/o ha sapore amaro, c''e il rischio della tossica ramaria bella.','{"Mazza d''Ercole troncata: corpi fruttiferi semplici, non ramificati, a forma di clava con apice piatto-troncato, spesso leggermente depresso; ramaria bella riccamente ramificata come un cespuglio.","Mazza d''Ercole generalmente giallo-ocra a bruno-arancio, isolata/claviforme; ramaria bella arancio-salmone con molte punte dei rami gialle.","Mazza d''Ercole ha sapore mite a dolciastro; ramaria bella amara e gastrointestinalmente tossica.","Mazza d''Ercole cresce tipicamente in bosco di conifere calcicolo (spesso abete rosso/abete bianco); ramaria bella piuttosto in bosco di latifoglie.","La forma a clava non ramificata della mazza d''Ercole esclude una confusione guardando con attenzione — una confusione avviene solo fugacemente negli stadi giovani coralliformi."}','f'),
('clavulina_coralloides','ramaria_formosa','en','Crested coral fungus whitish and delicate with comb-like toothed tips; the beautiful coral (Ramaria formosa) is large, orange-salmon coloured with yellow branch tips.','Both mild and mushroomy, no distinguishing odour.','Both on the forest floor; the crested coral often at path edges and in deciduous/coniferous forest, the beautiful coral prefers deciduous forest — habitat does not distinguish reliably.','Crested coral white spore print, beautiful coral ochre-yellowish — spore colour distinguishes reliably.','Avoid coloured (orange/yellow) corals on principle; only small, white, mild-tasting corals are suitable for beginners — bitter taste or reddish discolouration = poisonous.','{"Crested coral (Clavulina coralloides/cristata): dainty, white to cream, with finely toothed/comb-like branch tips; the beautiful coral is distinctly larger, fleshy and orange-salmon coloured.","The crested coral stays whitish and does not turn wine-red; the beautiful coral discolours reddish-brownish when pressed.","Crested coral mild and small (a few cm); beautiful coral bitter and more massive.","The beautiful coral has orange branches with yellow tips — the colour rules out the white crested coral.","The beautiful coral is gastrointestinally poisonous/laxative; confusion is practically only conceivable at the juvenile stage."}','f'),
('clavulina_coralloides','ramaria_formosa','es','Clavulina coralloide blanquecina y delicada con puntas dentadas en forma de cresta; la Ramaria formosa es grande, de color naranja-salmón con puntas de las ramas amarillas.','Ambas de olor suave y fúngico, ningún olor distintivo.','Ambas en el suelo del bosque; la Clavulina coralloide a menudo en bordes de senderos y en bosque de frondosas/coníferas, la Ramaria formosa prefiere el bosque de frondosas — el hábitat no distingue de forma fiable.','Clavulina coralloide: esporada blanca; Ramaria formosa: esporada ocre-amarillenta — el color de la esporada distingue de forma fiable.','Evitar por principio las clavarias coloreadas (naranja/amarillas); solo las pequeñas clavarias blancas de sabor suave son aptas para principiantes — sabor amargo o coloración rojiza = venenosa.','{"Clavulina coralloide (Clavulina coralloides/cristata): grácil, blanca a crema, con puntas de las ramas finamente dentadas/en forma de cresta; la Ramaria formosa es netamente más grande, carnosa y de color naranja-salmón.","La Clavulina coralloide permanece blanquecina y no se torna rojo vinoso; la Ramaria formosa vira a rojizo-parduzco a la presión.","Clavulina coralloide suave y pequeña (pocos cm); Ramaria formosa amarga y más maciza.","La Ramaria formosa tiene ramas naranjas con puntas amarillas — el color excluye a la blanca Clavulina coralloide.","La Ramaria formosa es gastrointestinalmente venenosa/laxante; la confusión solo es prácticamente concebible en estado juvenil."}','f'),
('clavulina_coralloides','ramaria_formosa','fr','Clavaire crêtée blanchâtre et délicate aux pointes dentelées en forme de crête ; la Clavaire jolie est grande, de couleur orange-saumon avec des pointes de rameaux jaunes.','Les deux ont une odeur douce et fongique, aucune odeur ne permet de les distinguer.','Les deux poussent au sol forestier ; la Clavaire crêtée souvent en bordure de chemins et en forêt de feuillus/conifères, la Clavaire jolie préfère la forêt de feuillus — l''habitat ne permet pas une distinction fiable.','Clavaire crêtée : sporée blanche ; Clavaire jolie : sporée ocre-jaunâtre — la couleur de la sporée permet une distinction fiable.','Éviter par principe les clavaires colorées (orange/jaune) ; seules les petites clavaires blanches au goût doux conviennent aux débutants — goût amer ou coloration rougeâtre = vénéneuse.','{"Clavaire crêtée (Clavulina coralloides/cristata) : gracile, blanche à crème, avec des pointes de rameaux finement dentelées/en forme de crête ; la Clavaire jolie est nettement plus grande, charnue et de couleur orange-saumon.","La Clavaire crêtée reste blanchâtre et ne se colore pas en rouge vineux ; la Clavaire jolie se colore en rougeâtre-brunâtre à la pression.","Clavaire crêtée douce et petite (quelques cm) ; Clavaire jolie amère et plus massive.","La Clavaire jolie a des rameaux orange à pointes jaunes — la couleur exclut la Clavaire crêtée blanche.","La Clavaire jolie est gastro-intestinale/laxative ; la confusion n''est pratiquement envisageable qu''au stade juvénile."}','f'),
('clavulina_coralloides','ramaria_formosa','it','Clavulina coralloide biancastra e delicata con punte dentellate a forma di cresta; la Ramaria formosa è grande, di colore arancio-salmone con punte dei rami gialle.','Entrambe hanno odore lieve e fungino, nessun odore distintivo.','Entrambe sul suolo del bosco; la Clavulina coralloide spesso ai bordi dei sentieri e in bosco di latifoglie/conifere, la Ramaria formosa predilige il bosco di latifoglie — l''habitat non distingue in modo affidabile.','Clavulina coralloide: sporata bianca; Ramaria formosa: sporata ocra-giallastra — il colore della sporata distingue in modo affidabile.','Evitare per principio le ramarie colorate (arancio/gialle); solo le piccole ramarie bianche dal sapore mite sono adatte ai principianti — sapore amaro o colorazione rossastra = velenosa.','{"Clavulina coralloide (Clavulina coralloides/cristata): esile, bianca o crema, con punte dei rami finemente dentellate/a cresta; la Ramaria formosa è nettamente più grande, carnosa e di colore arancio-salmone.","La Clavulina coralloide resta biancastra e non si colora di rosso vinoso; la Ramaria formosa vira al rossastro-brunastro sotto pressione.","Clavulina coralloide mite e piccola (pochi cm); Ramaria formosa amara e più massiccia.","La Ramaria formosa ha rami arancioni con punte gialle — il colore esclude la bianca Clavulina coralloide.","La Ramaria formosa è gastrointestinale/lassativa; la confusione è praticamente possibile solo allo stadio giovanile."}','f'),
('clitocybe_nebularis','ampulloclitocybe_clavipes','en','Large, fleshy clouded funnel cap, grey-frosted vs. smaller clavipes, white-grey to grey-brown; both with club-shaped base.','Clouded funnel cap strongly and peculiarly perfumed; clavipes faintly fruity.','Clouded funnel cap often in fairy rings in coniferous/deciduous forest in late autumn; clavipes in similar locations, no reliable separating feature.','Clouded funnel cap pale cream spore print, clavipes white.','Do not combine small, soft funnel caps with a club-shaped, spongy base with alcohol; always cook the clouded funnel cap thoroughly.','{"Both have a club-shaped thickened stem base — the key feature lies in the habit and cap colour: clouded funnel cap distinctly larger and fleshier (cap up to 20 cm), grey-frosted; clavipes smaller with white-grey to grey-brown cap and darker centre.","Clouded funnel cap with elastic flesh and gills that can be pushed off the cap flesh easily as in blewits; clavipes gills whitish and widely decurrent.","Smell separates them: clouded funnel cap strong, peculiarly perfumed-sweetish; clavipes only faintly fruity-mushroomy.","clavipes causes a coprine syndrome with alcohol; the clouded funnel cap is only of limited digestibility and indigestible for many (cook thoroughly, not raw)."}','f'),
('clitocybe_nebularis','ampulloclitocybe_clavipes','es','Gran clitocibe nebuloso carnoso, gris pruinoso vs. clavipes más pequeño, gris-blanco a gris-pardo; ambos con base claviforme.','Clitocibe nebuloso fuerte y extrañamente perfumado; clavipes débilmente afrutado.','Clitocibe nebuloso a menudo en corros de brujas en bosque de coníferas/frondosas a finales de otoño; clavipes en estaciones similares, ningún criterio de separación seguro.','Clitocibe nebuloso: esporada crema pálido; clavipes: esporada blanca.','No combinar con alcohol los pequeños clitocibes blandos con base claviforme esponjosa; cocinar bien el clitocibe nebuloso.','{"Ambos tienen la base del pie engrosada en maza — el criterio clave está en el porte y el color del sombrero: clitocibe nebuloso netamente más grande y carnoso (sombrero hasta 20 cm), gris pruinoso; clavipes más pequeño con sombrero gris-blanco a gris-pardo y centro más oscuro.","Clitocibe nebuloso de carne elástica y láminas que se desprenden fácilmente de la carne del sombrero como en los tricolomas; las láminas del clavipes blanquecinas y muy decurrentes.","El olor distingue: clitocibe nebuloso fuerte, extrañamente perfumado-dulzón; clavipes solo débilmente afrutado-fúngico.","El clavipes provoca un síndrome coprínico con el alcohol; el clitocibe nebuloso solo es parcialmente tolerado e indigesto para muchos (cocinar bien, no crudo)."}','f'),
('clitocybe_nebularis','ampulloclitocybe_clavipes','fr','Grand clitocybe nébuleux gris pruineux, charnu vs. clavipes plus petit, blanc-gris à gris-brun ; les deux avec une base en massue.','Clitocybe nébuleux fortement parfumé de façon particulière ; clavipes faiblement fruité.','Clitocybe nébuleux souvent en ronds de sorcières en forêt de conifères/feuillus à la fin de l''automne ; clavipes mêmes stations, pas de critère de séparation sûr.','Clitocybe nébuleux à sporée crème pâle, clavipes blanche.','Ne pas combiner les petits clitocybes mous à base en massue spongieuse avec de l''alcool ; pour le clitocybe nébuleux, toujours bien cuire.','{"Les deux ont une base du pied épaissie en massue – le critère clé réside dans le port et la couleur du chapeau : clitocybe nébuleux nettement plus grand et plus charnu (chapeau jusqu''à 20 cm), gris pruineux ; clavipes plus petit avec un chapeau blanc-gris à gris-brun et un centre plus sombre.","Clitocybe nébuleux à chair élastique et lamelles qui se détachent facilement de la chair du chapeau comme chez les lépistes ; lamelles de clavipes blanchâtres et largement décurrentes.","L''odeur sépare : clitocybe nébuleux fort, parfumé-sucré de façon particulière ; clavipes seulement faiblement fruité-fongique.","clavipes provoque avec l''alcool un syndrome coprinien ; le clitocybe nébuleux n''est que partiellement tolérable et indigeste pour beaucoup (bien cuire, pas cru)."}','f'),
('clitocybe_nebularis','ampulloclitocybe_clavipes','it','Grande Clitocybe nebularis carnoso, grigio pruinoso vs. clavipes più piccolo, grigio-bianco a grigio-bruno; entrambi con base claviforme.','Clitocybe nebularis fortemente e stranamente profumato; clavipes debolmente fruttato.','Clitocybe nebularis spesso in cerchi delle streghe in bosco di conifere/latifoglie nel tardo autunno; clavipes in stazioni simili, nessun criterio di separazione sicuro.','Clitocybe nebularis: sporata crema pallido; clavipes: sporata bianca.','Non abbinare all''alcol i piccoli clitocybi molli con base claviforme spugnosa; cuocere bene il Clitocybe nebularis.','{"Entrambi hanno la base del gambo ingrossata a clava — il criterio chiave sta nel portamento e nel colore del cappello: Clitocybe nebularis nettamente più grande e carnoso (cappello fino a 20 cm), grigio pruinoso; clavipes più piccolo con cappello grigio-bianco a grigio-bruno e centro più scuro.","Clitocybe nebularis con carne elastica e lamelle che si staccano facilmente dalla carne del cappello come nei tricolomi; le lamelle del clavipes biancastre e nettamente decorrenti.","L''odore distingue: Clitocybe nebularis forte, stranamente profumato-dolciastro; clavipes solo debolmente fruttato-fungino.","Il clavipes provoca una sindrome coprinica con l''alcol; il Clitocybe nebularis è solo parzialmente tollerato e indigesto per molti (cuocere bene, non crudo)."}','f'),
('clitocybe_nebularis','entoloma_sinuatum','en','Livid pinkgill (Entoloma sinuatum): more compact, fleshy, light grey to clay-yellowish/ivory-coloured cap; gills whitish-yellowish when young, flesh-pink when old, short and notched (sinuate) at the attachment, not decurrent. Clouded funnel (Clitocybe nebularis): large (10-25 cm) cloud-grey cap with whitish-cream, crowded gills that run shortly down the stem.','Clouded funnel: obtrusively sweetish-spicy (perceived as unpleasant by many). Livid pinkgill: mealy-rancid with a sourish-radish-like, unpleasant note.','Livid pinkgill: lime-loving, in deciduous and mixed forests (especially beech, oak, hornbeam) on calcareous/loamy soil, rather rare, May-November; grows singly, in groups OR in fairy rings. Clouded funnel: common and often in masses, deciduous and coniferous forest, late autumn (Oct-Nov), likewise forms rows and fairy rings. WARNING: fairy-ring growth is NOT suitable for distinguishing them — both species show it.','DECISIVE: Livid pinkgill flesh-pink to pinkish-brown (Entoloma genus characteristic). Clouded funnel white to pale cream-yellowish. A simple spore print on white paper separates the two reliably — this is the most dependable feature.','A spore print is mandatory: pink/flesh-pink powder = pinkgill = do NOT eat. The clouded funnel drops white to pale cream-coloured powder and has shortly decurrent, crowded gills. Do NOT rely on the growth form — BOTH species can form rows and fairy rings, this is NO distinguishing feature.','{"Spore powder (SAFEST feature): Livid pinkgill flesh-pink to pinkish-brown (pinkgill genus) — clouded funnel white to pale cream-yellowish. A spore print on white paper separates the two unambiguously.","Gill colour in age: Livid pinkgill gills whitish/yellowish when young, clearly flesh-PINK in age due to the spores — clouded funnel gills stay white to cream-yellowish, NEVER pink.","Gill attachment: Clouded funnel gills run shortly DOWN the stem (funnel-typical), crowded; livid pinkgill gills are notched (sinuate) at the attachment, short, stiff and stand little crowded — NOT decurrent.","Smell: Clouded funnel obtrusively sweetish-spicy; livid pinkgill mealy-rancid with an unpleasant sourish-radish-like note."}','t'),
('clitocybe_nebularis','entoloma_sinuatum','es','Entoloma sinuatum (pardillo gigante): sombrero más compacto y carnoso, de color gris claro a amarillo arcilloso/marfil; láminas de jóvenes blanquecino-amarillentas, de viejas de color rosa carne, cortas y unidas de forma escotada (sinuada), no decurrentes. Pardilla (Clitocybe nebularis): sombrero grande (10-25 cm) de color gris niebla con láminas blanquecino-cremosas, apretadas y brevemente decurrentes por el pie.','Pardilla: dulzón-especiado penetrante (percibido por muchos como desagradable). Pardillo gigante: harinoso-rancio con un matiz ácido-rabanoso desagradable.','Pardillo gigante: amante de la cal, en bosques caducifolios y mixtos (sobre todo haya, roble, carpe) sobre suelo calcáreo/arcilloso, más bien raro, de mayo a noviembre; crece solitario, en grupos O en corros de brujas. Pardilla: frecuente y a menudo en masa, bosque caducifolio y de coníferas, otoño tardío (oct-nov), forma también hileras y corros de brujas. ATENCIÓN: el crecimiento en corro de brujas NO sirve para la distinción — ambas especies lo presentan.','DECISIVO: pardillo gigante de color rosa carne a rosa pardo (rasgo del género Entoloma). Pardilla blanca a crema-amarillenta pálida. Una simple esporada sobre papel blanco distingue ambas con seguridad — es el carácter más fiable.','La esporada es obligatoria: polvo rosa/rosa carne = pardillo (Entoloma) = NO comer. La pardilla deja una esporada blanca a crema pálida y tiene láminas brevemente decurrentes y apretadas. NO te fíes de la forma de crecimiento — AMBAS especies pueden formar hileras y corros de brujas, eso NO es un carácter distintivo.','{"Esporada (carácter MÁS SEGURO): pardillo gigante de color rosa carne a rosa pardo (género Entoloma) — pardilla blanca a crema-amarillenta pálida. La esporada sobre papel blanco las distingue inequívocamente.","Color de las láminas al envejecer: las láminas del pardillo gigante son de jóvenes blanquecinas/amarillentas, de viejas claramente de color rosa CARNE por las esporas — las láminas de la pardilla permanecen blancas a crema-amarillentas, NUNCA rosadas.","Inserción de las láminas: las láminas de la pardilla son brevemente DECURRENTES por el pie (típico de Clitocybe), apretadas; las láminas del pardillo gigante están unidas de forma escotada (sinuada), cortas, rígidas y poco apretadas — NO decurrentes.","Olor: pardilla dulzón-especiado penetrante; pardillo gigante harinoso-rancio con un matiz ácido-rabanoso desagradable."}','t'),
('clitocybe_nebularis','entoloma_sinuatum','fr','Entolome livide (grand entolome): chapeau plus compact, plus charnu, gris clair à jaune argileux/ivoire; lamelles blanchâtres-jaunâtres lorsqu''elles sont jeunes, rose chair en vieillissant, courtes et échancrées (sinuées) à l''insertion, non décurrentes. Clitocybe nébuleux: grand chapeau (10-25 cm) gris brouillard avec des lamelles blanchâtres-crème, serrées et brièvement décurrentes sur le pied.','Clitocybe nébuleux: douceâtre-épicé envahissant (perçu comme désagréable par beaucoup). Entolome livide: farineux-rance avec une note acidulée-raphanoïde désagréable.','Entolome livide: calcicole, dans les forêts de feuillus et mixtes (surtout hêtre, chêne, charme) sur sols calcaires/argileux, plutôt rare, de mai à novembre; pousse isolé, en groupes OU en ronds de sorcières. Clitocybe nébuleux: fréquent et souvent en masse, forêts de feuillus et de conifères, fin de l''automne (oct.-nov.), forme également des rangées et des ronds de sorcières. ATTENTION: la croissance en rond de sorcières NE permet PAS de distinguer les deux espèces — toutes deux la présentent.','DÉCISIF: entolome livide rose chair à rose-brun (caractère du genre Entoloma). Clitocybe nébuleux blanche à crème-jaunâtre pâle. Une simple sporée sur papier blanc sépare les deux avec certitude — c''est le critère le plus fiable.','La sporée est obligatoire: poudre rose/rose chair = entolome (Rötling) = NE PAS manger. Le clitocybe nébuleux laisse une sporée blanche à crème pâle et a des lamelles brièvement décurrentes et serrées. Ne vous fiez PAS à la forme de croissance — les DEUX espèces peuvent former des rangées et des ronds de sorcières, ce n''est PAS un critère de distinction.','{"Sporée (critère le PLUS SÛR): entolome livide rose chair à rose-brun (genre des entolomes/Rötling) — clitocybe nébuleux blanche à crème-jaunâtre pâle. Une sporée sur papier blanc sépare les deux sans équivoque.","Couleur des lamelles à maturité: les lamelles de l''entolome livide sont blanchâtres/jaunâtres lorsqu''elles sont jeunes, et deviennent nettement ROSE chair avec l''âge sous l''effet des spores — les lamelles du clitocybe nébuleux restent blanches à crème-jaunâtre, JAMAIS roses.","Insertion des lamelles: les lamelles du clitocybe nébuleux sont brièvement DÉCURRENTES sur le pied (typique des clitocybes), serrées; les lamelles de l''entolome livide sont échancrées (sinuées) à l''insertion, courtes, rigides et peu serrées — NON décurrentes.","Odeur: clitocybe nébuleux douceâtre-épicé envahissant; entolome livide farineux-rance avec une note désagréable acidulée-raphanoïde."}','t'),
('clitocybe_nebularis','entoloma_sinuatum','it','Entoloma lividum (Riesenrötling): cappello più compatto, carnoso, da grigio chiaro a giallo-argilla/avorio; lamelle da giovani biancastre-giallastre, da vecchie rosa-carne, corte e attaccate in modo smarginato (sinuato), non decorrenti. Clitocybe nebularis (Nebbiolo): cappello grande (10-25 cm) grigio-nebbia con lamelle biancastre-crema, fitte e brevemente decorrenti sul gambo.','Clitocybe nebularis (Nebbiolo): odore invadente dolciastro-aromatico (percepito da molti come sgradevole). Entoloma lividum (Riesenrötling): farinoso-rancido con nota acidula-rafanoide, sgradevole.','Entoloma lividum (Riesenrötling): calcofilo, in boschi di latifoglie e misti (soprattutto faggio, quercia, carpino) su suolo calcareo/argilloso, piuttosto raro, da maggio a novembre; cresce isolato, in gruppi OPPURE in cerchi delle streghe. Clitocybe nebularis (Nebbiolo): frequente e spesso in gran quantità, in boschi di latifoglie e conifere, tardo autunno (ott-nov), forma anch''esso file e cerchi delle streghe. ATTENZIONE: la crescita in cerchio delle streghe NON serve per la distinzione — entrambe le specie la presentano.','DECISIVO: Entoloma lividum (Riesenrötling) rosa-carne fino a rosa-bruno (carattere distintivo del genere Entoloma). Clitocybe nebularis (Nebbiolo) bianco fino a crema-giallastro pallido. Una semplice sporata su carta bianca distingue i due con sicurezza — è il carattere più affidabile.','La sporata è obbligatoria: polvere rosa/rosa-carne = Entoloma (Rötling) = NON mangiare. Il Nebbiolo (Clitocybe nebularis) rilascia una polvere da bianca a crema pallida e ha lamelle brevemente decorrenti e fitte. NON affidarti alla forma di crescita — ENTRAMBE le specie possono formare file e cerchi delle streghe, NON è un criterio di distinzione.','{"Sporata in massa (carattere PIÙ SICURO): Entoloma lividum (Riesenrötling) da rosa-carne a rosa-bruno (genere Entoloma) — Clitocybe nebularis (Nebbiolo) da bianco a crema-giallastro pallido. La sporata su carta bianca distingue inequivocabilmente i due.","Colore delle lamelle con l''età: le lamelle dell''Entoloma lividum (Riesenrötling) da giovani biancastre/giallastre, da vecchie nettamente rosa-CARNE per via delle spore — le lamelle del Clitocybe nebularis (Nebbiolo) restano da bianche a crema-giallastre, MAI rosa.","Attacco delle lamelle: le lamelle del Clitocybe nebularis (Nebbiolo) sono brevemente DECORRENTI sul gambo (tipico dei clitocibi), fitte; le lamelle dell''Entoloma lividum (Riesenrötling) sono attaccate in modo smarginato (sinuato), corte, rigide e poco fitte — NON decorrenti.","Odore: Clitocybe nebularis (Nebbiolo) invadente dolciastro-aromatico; Entoloma lividum (Riesenrötling) farinoso-rancido con sgradevole nota acidula-rafanoide."}','t'),
('clitocybe_odora','clitocybe_fragrans','en','Blue-green colouration of the aniseed funnel cap vs. fragrans small, pale watery-grey.','Both smell of aniseed; odora stronger/more persistent, fragrans weaker and more fleeting.','Both in deciduous/coniferous/mixed forest; no reliable separating feature via habitat.','Both white to pale cream spore print; not distinctive.','Aniseed smell alone does not protect — never collect small, pale, watery aniseed funnel caps because of muscarine.','{"The aniseed funnel cap is distinctly blue-green to grey-green coloured, more robust in habit; fragrans is pale grey-brown/light watery and smaller, without blue/green tones.","fragrans contains muscarine (sweating, salivation/lacrimation, miosis, gastrointestinal upset); the aniseed funnel cap is edible cooked (as a seasoning, in small amounts) — poisonous raw.","Both smell of aniseed; the green one usually smells more intensely/persistently, in fragrans the aniseed smell evaporates quickly on drying.","fragrans cap pale with often translucently striate margin and darker centre; odora coloured more uniformly blue-green."}','f'),
('clitocybe_odora','clitocybe_fragrans','es','Coloración azul-verde del clitocibe anisado verde vs. fragrans pequeño, gris acuoso pálido.','Ambos con olor a anís; odora más fuerte/persistente, fragrans más débil y más fugaz.','Ambos en bosque de frondosas/coníferas/mixto; ningún criterio de separación fiable a través del hábitat.','Ambos con esporada blanca a crema pálido; no distintiva.','El olor a anís por sí solo no protege — no recolectar nunca pequeños clitocibes anisados pálidos y acuosos por la muscarina.','{"El clitocibe anisado verde está netamente coloreado de azul-verde a gris-verde, más robusto de porte; fragrans es gris-pardo pálido/claro acuoso y más pequeño, sin tonos azules/verdes.","fragrans contiene muscarina (sudoración, salivación/lagrimeo, miosis, trastornos gastrointestinales); el clitocibe anisado verde es comestible cocinado (como condimento, en pequeñas cantidades) — venenoso crudo.","Ambos huelen a anís; el verde huele por lo general más intensa/duraderamente, en fragrans el olor a anís se desvanece rápidamente al secarse.","Sombrero de fragrans pálido con margen a menudo estriado por transparencia y centro más oscuro; odora coloreado más uniformemente de azul-verde."}','f'),
('clitocybe_odora','clitocybe_fragrans','fr','Coloration bleu-vert du clitocybe anisé vs. fragrans pâle, gris aqueux, petit.','Les deux d''anis ; odora plus fort/plus durable, fragrans plus faible et plus volatile.','Les deux en forêt de feuillus/conifères/mixte ; pas de critère de séparation fiable via l''habitat.','Les deux à sporée blanche à crème pâle ; non discriminant.','L''odeur d''anis seule ne protège pas - ne jamais récolter les petits clitocybes anisés pâles, aqueux à cause de la muscarine.','{"Le clitocybe anisé est nettement coloré en bleu-vert à gris-vert, plus robuste de port ; fragrans est gris-brun pâle/aqueux clair et plus petit, sans teintes bleues/vertes.","fragrans contient de la muscarine (sudation, salivation/larmoiement, myosis, troubles gastro-intestinaux) ; le clitocybe anisé est comestible cuit (comme condiment, en petites quantités) - cru toxique.","Les deux sentent l''anis ; l''anisé sent généralement plus intensément/durablement, chez fragrans l''odeur d''anis s''évapore vite au séchage.","Chapeau de fragrans pâle avec un bord souvent strié par transparence et un centre plus sombre ; odora coloré en bleu-vert plus uniforme."}','f'),
('clitocybe_odora','clitocybe_fragrans','it','Colorazione blu-verde del Clitocybe odora vs. fragrans piccolo, grigio acquoso pallido.','Entrambi odore di anice; odora più forte/persistente, fragrans più debole e più fugace.','Entrambi in bosco di latifoglie/conifere/misto; nessun criterio di separazione affidabile tramite l''habitat.','Entrambi sporata bianca a crema pallido; non distintiva.','L''odore di anice da solo non protegge — non raccogliere mai piccoli clitocybi anisati pallidi e acquosi a causa della muscarina.','{"Il Clitocybe odora è nettamente colorato di blu-verde a grigio-verde, più robusto nel portamento; fragrans è grigio-bruno pallido/chiaro acquoso e più piccolo, senza toni blu/verdi.","fragrans contiene muscarina (sudorazione, salivazione/lacrimazione, miosi, disturbi gastrointestinali); il Clitocybe odora è commestibile cotto (come aromatizzante, in piccole quantità) — velenoso crudo.","Entrambi odorano di anice; il verde odora di solito più intensamente/durevolmente, in fragrans l''odore di anice svanisce rapidamente all''essiccamento.","Cappello di fragrans pallido con margine spesso striato per trasparenza e centro più scuro; odora colorato più uniformemente di blu-verde."}','f'),
('clitopilus_prunulus','clitocybe_fragrans','en','The miller cream-white with soft gills later flushed pink; fragrans pale grey, gills stay white.','The miller intensely mealy-cucumber; fragrans aniseed — clearly different.','Both in forest and at forest edges; no reliable separating feature via habitat.','The miller pink/salmon-pink, fragrans white — the most reliable distinguishing feature.','Always make a spore print AND check the smell separately: white-spored, non-mealy funnel caps are potentially highly poisonous — when in doubt, leave them entirely.','{"Decisive is the spore print: the miller pink/salmon-pink, fragrans pure white — the spore print makes the difference unambiguous.","Smell separates additionally: the miller strongly of fresh flour/cucumber, fragrans of aniseed.","The miller''s gills become pink-tinged with maturity from the spores and are conspicuously soft; fragrans gills stay whitish.","fragrans contains muscarine (sweating, salivation, miosis); the miller is a good edible — the main danger, however, is confusion with highly poisonous white funnel caps."}','f'),
('clitopilus_prunulus','clitocybe_fragrans','es','El molinero blanco-crema con láminas blandas más tarde teñidas de rosa; fragrans gris pálido, las láminas permanecen blancas.','El molinero intensamente harinoso-pepino; fragrans anisado — claramente diferente.','Ambos en bosque y en bordes de bosque; ningún criterio de separación fiable a través del hábitat.','El molinero rosa/rosa salmón, fragrans blanco — el criterio de distinción más seguro.','Hacer siempre una esporada Y comprobar el olor por separado: los clitocibes de esporas blancas y no harinosos son potencialmente muy venenosos — en caso de duda, dejarlos por completo en el sitio.','{"Decisiva es la esporada: el molinero rosa/rosa salmón, fragrans blanco puro — la esporada hace la diferencia inequívoca.","El olor distingue además: el molinero fuertemente a harina fresca/pepino, fragrans a anís.","Las láminas del molinero se tornan rosadas con la madurez por las esporas y son notablemente blandas; las láminas de fragrans permanecen blanquecinas.","fragrans contiene muscarina (sudoración, salivación, miosis); el molinero es un buen comestible — el peligro principal, sin embargo, es la confusión con los clitocibes blancos muy venenosos."}','f'),
('clitopilus_prunulus','clitocybe_fragrans','fr','Meunier crème-blanc avec des lamelles molles plus tard teintées de rose ; fragrans gris pâle, lamelles restant blanches.','Meunier intensément farineux-concombre ; fragrans d''anis - clairement différent.','Les deux en forêt et aux lisières ; pas de critère de séparation fiable via l''habitat.','Meunier rose/rose saumon, fragrans blanche - le critère de distinction le plus sûr.','Toujours faire une sporée ET vérifier l''odeur séparément : les clitocybes à spores blanches, non farineux, sont potentiellement très toxiques - en cas de doute laisser entièrement sur place.','{"Le décisif est la sporée : meunier rose/rose saumon, fragrans blanc pur - la sporée rend la différence sans équivoque.","L''odeur sépare en plus : meunier fortement de farine fraîche/concombre, fragrans d''anis.","Les lamelles du meunier deviennent roses avec la maturité par les spores et sont remarquablement molles ; les lamelles de fragrans restent blanchâtres.","fragrans contient de la muscarine (sudation, salivation, myosis) ; le meunier est un bon comestible - le danger principal est cependant la confusion avec des clitocybes blancs très toxiques."}','f'),
('clitopilus_prunulus','clitocybe_fragrans','it','Clitopilus prunulus bianco-crema con lamelle molli più tardi sfumate di rosa; fragrans grigio pallido, le lamelle restano bianche.','Clitopilus prunulus intensamente farinoso-cetriolo; fragrans anisato — chiaramente diverso.','Entrambi in bosco e ai margini del bosco; nessun criterio di separazione affidabile tramite l''habitat.','Clitopilus prunulus rosa/rosa salmone, fragrans bianco — il criterio di distinzione più sicuro.','Fare sempre la sporata E verificare l''odore separatamente: i clitocybi con spore bianche e non farinosi sono potenzialmente molto velenosi — in caso di dubbio lasciare completamente sul posto.','{"Decisiva è la sporata: Clitopilus prunulus rosa/rosa salmone, fragrans bianco puro — la sporata rende la differenza inequivocabile.","L''odore distingue in più: Clitopilus prunulus fortemente di farina fresca/cetriolo, fragrans anisato.","Le lamelle del Clitopilus prunulus diventano rosate con la maturità per le spore e sono notevolmente molli; le lamelle di fragrans restano biancastre.","fragrans contiene muscarina (sudorazione, salivazione, miosi); il Clitopilus prunulus è un buon commestibile — il pericolo principale è tuttavia la confusione con i clitocybi bianchi molto velenosi."}','f'),
('clitopilus_prunulus','clitocybe_phyllophila','en','Both small and white; the funnel cap (clitocybe) looks glassy/varnished and frosted, the miller dull and chamois-like — but only the spore print distinguishes them reliably (pink vs white).','Miller = clear flour/cucumber smell; lead-white funnel cap = musty-sweetish/perfumed smell. The flour smell is the main confirmatory feature — but on its own not conclusive.','Both in hardwood/conifer forest; the lead-white funnel cap often in troops in leaf/needle litter, at path edges and in gardens.','Miller pink, lead-white funnel cap white/cream — the spore print is the most reliable distinguishing feature. When uncertain, ALWAYS make a spore print.','Only eat the miller if the flour smell is clear AND the spore print is pink — any white funnel cap with white spores, a perfumed/musty smell is muscarine-suspect and stays put.','{"The miller smells strongly and clearly of fresh flour/cucumber; the lead-white funnel cap smells musty-sweetish to perfumed — the smell is an important confirmatory feature.","The miller''s spore print is pink (gills flushing pinkish-red with age); in the lead-white funnel cap it is white to cream — the spore print is the MOST RELIABLE distinguishing feature.","The miller''s gills are distinctly decurrent and easily detachable; in the lead-white funnel cap they are only weakly/faintly decurrent.","The lead-white funnel cap is listed as muscarine-suspect/toxic (sweating/salivation/lacrimation syndrome; toxin content disputed in the literature, therefore conservatively treated as toxic) — the miller is safely edible.","The cap of the lead-white funnel cap is glassy-varnished white and frosted; the miller is dull grey-white, often somewhat distorted."}','f'),
('clitopilus_prunulus','clitocybe_phyllophila','es','Ambos pequeños y blancos; el clitocibe parece vidrioso/como barnizado y pruinoso, el harinero mate y agamuzado — pero solo la esporada los distingue con seguridad (rosa vs blanca).','Harinero = claro olor a harina/pepino; clitocibe blanco plomizo = olor a moho-dulzón/perfumado. El olor a harina es el principal criterio de confirmación — pero por sí solo no concluyente.','Ambos en bosque de frondosas/coníferas; el clitocibe blanco plomizo a menudo en grupos en la hojarasca de hojas/acículas, en los bordes de los caminos y en los jardines.','Harinero rosa, clitocibe blanco plomizo blanca/crema — la esporada es el criterio distintivo más seguro. En caso de incertidumbre, hacer SIEMPRE una esporada.','Consumir el harinero solo si el olor a harina es claro Y la esporada rosa — todo clitocibe blanco de esporas blancas, con olor perfumado/a moho es sospechoso de muscarina y se queda en el sitio.','{"El harinero huele fuerte y claramente a harina fresca/pepino; el clitocibe blanco plomizo huele a moho-dulzón hasta perfumado — el olor es un criterio de confirmación importante.","La esporada del harinero es rosa (láminas que con la edad viran a rosa-rojizo); en el clitocibe blanco plomizo es blanca o crema — la esporada es el criterio distintivo MÁS SEGURO.","Las láminas del harinero son claramente decurrentes y se desprenden con facilidad; en el clitocibe blanco plomizo solo son débil/discretamente decurrentes.","El clitocibe blanco plomizo figura como sospechoso de muscarina/tóxico (síndrome sudoriano: sudoración/salivación/lagrimeo; contenido de toxina discutido en la literatura, por ello tratado con prudencia como tóxico) — el harinero es comestible sin peligro.","El sombrero del clitocibe blanco plomizo es blanco vidrioso-barnizado y pruinoso; el harinero es gris-blanco mate, a menudo algo deformado."}','f'),
('clitopilus_prunulus','clitocybe_phyllophila','fr','Les deux petits et blancs ; le clitocybe paraît vitreux/comme verni et pruineux, le meunier mat et chamoisé — mais seule la sporée distingue avec certitude (rose vs blanc).','Meunier = nette odeur de farine/concombre ; clitocybe blanc de plomb = odeur de moisi-douceâtre/parfumée. L''odeur de farine est le principal critère de confirmation — mais à elle seule non probante.','Les deux en forêt de feuillus/conifères ; le clitocybe blanc de plomb souvent en troupes dans la litière de feuilles/aiguilles, en bordure de chemins et dans les jardins.','Meunier rose, clitocybe blanc de plomb blanc/crème — la sporée est le critère de distinction le plus sûr. En cas d''incertitude, TOUJOURS faire une sporée.','Ne consommer le meunier que si l''odeur de farine est nette ET la sporée rose — tout clitocybe blanc à spores blanches, à odeur parfumée/de moisi est suspect de muscarine et reste sur place.','{"Le meunier sent fortement et nettement la farine fraîche/le concombre ; le clitocybe blanc de plomb sent le moisi-douceâtre à parfumé — l''odeur est un critère de confirmation important.","La sporée du meunier est rose (lames devenant rose-rougeâtre avec l''âge) ; chez le clitocybe blanc de plomb elle est blanche à crème — la sporée est le critère de distinction le PLUS SÛR.","Les lames du meunier sont nettement décurrentes et se détachent facilement ; chez le clitocybe blanc de plomb elles ne sont que faiblement/discrètement décurrentes.","Le clitocybe blanc de plomb est considéré comme suspect de muscarine/toxique (syndrome sudorien : sudation/salivation/larmoiement ; teneur en toxine débattue dans la littérature, donc traité par prudence comme toxique) — le meunier est comestible sans danger.","Le chapeau du clitocybe blanc de plomb est blanc vitreux et pruineux comme verni ; le meunier est gris-blanc mat, souvent un peu déformé."}','f'),
('clitopilus_prunulus','clitocybe_phyllophila','it','Entrambi piccoli e bianchi; il clitocybe appare vitreo/come verniciato e pruinoso, il fungo di farina opaco e camosciato — ma solo la sporata distingue con certezza (rosa vs bianca).','Fungo di farina = netto odore di farina/cetriolo; clitocybe bianco-plumbeo = odore di muffa-dolciastro/profumato. L''odore di farina è il principale criterio di conferma — ma da solo non probante.','Entrambi in bosco di latifoglie/conifere; il clitocybe bianco-plumbeo spesso a gruppi nella lettiera di foglie/aghi, ai bordi dei sentieri e nei giardini.','Fungo di farina rosa, clitocybe bianco-plumbeo bianca/crema — la sporata è il criterio distintivo più sicuro. In caso di incertezza fare SEMPRE la sporata.','Consumare il fungo di farina solo se l''odore di farina è netto E la sporata rosa — ogni clitocybe bianco a spore bianche, dall''odore profumato/di muffa è sospetto di muscarina e va lasciato sul posto.','{"Il fungo di farina odora fortemente e nettamente di farina fresca/cetriolo; il clitocybe bianco-plumbeo odora di muffa-dolciastro fino a profumato — l''odore è un criterio di conferma importante.","La sporata del fungo di farina è rosa (lamelle che con l''età virano al rosa-rossastro); nel clitocybe bianco-plumbeo è bianca o crema — la sporata è il criterio distintivo PIÙ SICURO.","Le lamelle del fungo di farina sono nettamente decorrenti e si staccano facilmente; nel clitocybe bianco-plumbeo sono solo debolmente/discretamente decorrenti.","Il clitocybe bianco-plumbeo è classificato come sospetto di muscarina/tossico (sindrome sudorina: sudorazione/salivazione/lacrimazione; contenuto di tossina dibattuto in letteratura, perciò trattato per prudenza come tossico) — il fungo di farina è commestibile senza pericolo.","Il cappello del clitocybe bianco-plumbeo è bianco vitreo e pruinoso come verniciato; il fungo di farina è grigio-bianco opaco, spesso un po'' deformato."}','f'),
('clitopilus_prunulus','hebeloma_crustuliniforme','en','The miller (sweetbread mushroom): white-grey, decurrent gills; Hebeloma: clay-grey pale, emarginate, weeping gills.','The miller strongly mealy; weeping Hebeloma radish-like.',NULL,'The miller with pink spore print vs. rust/brown-olive in the weeping Hebeloma — decisive feature.','Spore-print colour secures the identification: pink + decurrent gills + mealy smell = the miller, rust-brown + radish smell + weeping gills = toxic mushroom.','{"The miller has gills clearly decurrent down the stem and a PINK spore print; the weeping Hebeloma has emarginate-attached gills and a rust/brown-olive spore print","The miller smells intensely mealy (especially at the gills); Hebeloma crustuliniforme smells radish-like","Weeping gills with droplets and brown spotting are typical of the Hebeloma and absent in the miller","The miller''s cap is white-grey, often somewhat irregular/distorted; the Hebeloma''s cap is clay-grey pale with a darker centre"}','f'),
('clitopilus_prunulus','hebeloma_crustuliniforme','es','Molinera (clitopilo): blanco-gris, láminas decurrentes; hebeloma: gris-arcilla pálido, láminas escotadas, lacrimosas.','Molinera fuertemente harinosa; hebeloma lacrimoso con olor a rábano.',NULL,'Molinera con esporada rosa frente a herrumbre/pardo-oliva en el hebeloma lacrimoso — carácter decisivo.','El color de la esporada asegura la determinación: rosa + láminas decurrentes + olor harinoso = molinera, herrumbre-pardo + olor a rábano + láminas lacrimosas = hongo tóxico.','{"La molinera tiene láminas claramente decurrentes a lo largo del pie y una esporada ROSA; el hebeloma lacrimoso tiene láminas escotado-adheridas y una esporada herrumbre/pardo-oliva","La molinera huele intensamente a harina (sobre todo en las láminas); Hebeloma crustuliniforme huele a rábano","Las láminas lacrimosas con gotitas y manchas pardas son típicas del hebeloma y faltan en la molinera","El sombrero de la molinera es blanco-gris, a menudo algo irregular/deformado; el sombrero del hebeloma es gris-arcilla pálido con centro más oscuro"}','f'),
('clitopilus_prunulus','hebeloma_crustuliniforme','fr','Meunier (clitopile petite-prune) : blanc-gris, lamelles décurrentes ; hébélome : gris-argile pâle, lamelles échancrées, larmoyantes.','Meunier fortement farineux ; hébélome larmoyant à odeur de raifort.',NULL,'Meunier à sporée rose contre rouille/brun-olive chez l''hébélome larmoyant — caractère décisif.','La couleur de la sporée assure la détermination : rose + lamelles décurrentes + odeur de farine = meunier, rouille-brun + odeur de raifort + lamelles larmoyantes = champignon toxique.','{"Le meunier a des lamelles nettement décurrentes le long du pied et une sporée ROSE ; l''hébélome larmoyant a des lamelles échancrées-attachées et une sporée rouille/brun-olive","Le meunier sent intensément la farine (surtout aux lamelles) ; Hebeloma crustuliniforme sent le raifort","Des lamelles larmoyantes avec gouttelettes et taches brunes sont typiques de l''hébélome et font défaut chez le meunier","Chapeau du meunier blanc-gris, souvent un peu irrégulier/déformé ; chapeau de l''hébélome gris-argile pâle à centre plus foncé"}','f'),
('clitopilus_prunulus','hebeloma_crustuliniforme','it','Fungo della farina (clitopilo): bianco-grigio, lamelle decorrenti; hebeloma: grigio-argilla pallido, lamelle smarginate, lacrimanti.','Fungo della farina fortemente farinoso; hebeloma lacrimoso dall''odore di rafano.',NULL,'Fungo della farina con sporata rosa contro ruggine/bruno-oliva nell''hebeloma lacrimoso — carattere decisivo.','Il colore della sporata garantisce la determinazione: rosa + lamelle decorrenti + odore di farina = fungo della farina, ruggine-bruno + odore di rafano + lamelle lacrimanti = fungo tossico.','{"Il fungo della farina ha lamelle nettamente decorrenti lungo il gambo e una sporata ROSA; l''hebeloma lacrimoso ha lamelle smarginato-attaccate e una sporata ruggine/bruno-oliva","Il fungo della farina odora intensamente di farina (specialmente alle lamelle); Hebeloma crustuliniforme odora di rafano","Lamelle lacrimanti con goccioline e macchie brune sono tipiche dell''hebeloma e mancano nel fungo della farina","Cappello del fungo della farina bianco-grigio, spesso un po'' irregolare/deformato; cappello dell''hebeloma grigio-argilla pallido con centro più scuro"}','f'),
('coprinopsis_atramentaria','coprinopsis_picacea','en','Magpie inkcap spotted black and white vs. common inkcap uniformly grey, longitudinally pleated, without white veil flecks.','Magpie inkcap musty-tarry; common inkcap inconspicuously mushroomy.','Magpie inkcap solitary in humus-/lime-rich beech/deciduous woods; common inkcap clustered on stumps, path edges and in gardens.','Both black, deliquescing spore print; not distinctive.','White, wipeable veil flecks on a dark cap characterise the inedible magpie inkcap; and never consume common inkcaps with alcohol.','{"Young magpie inkcaps can be confused with the common inkcap: the magpie inkcap bears white, wipeable veil scales on a dark ground (black-and-white pattern); the common inkcap is uniformly grey to grey-brown with a longitudinally pleated/furrowed cap without white flecks.","The magpie inkcap smells musty-tarry and is inedible; the common inkcap is (only without alcohol) edible with reservations.","Magpie inkcap more slender and taller with a fragile stem; common inkcap more squat and mostly growing in clusters.","Caution: the common inkcap contains coprine and is poisonous with alcohol — not a ''safe'' edible."}','f'),
('coprinopsis_atramentaria','coprinopsis_picacea','es','Coprino pícaro moteado de negro y blanco vs. coprino de tinta uniformemente gris, con pliegues longitudinales, sin escamas de velo blancas.','Coprino pícaro olor a moho-alquitrán; coprino de tinta olor fúngico discreto.','Coprino pícaro solitario en hayedos/bosques de frondosas ricos en humus/cal; coprino de tinta en grupos sobre tocones, bordes de senderos y en jardines.','Ambos con esporada negra y deliciscente; no distintiva.','Escamas de velo blancas y desprendibles sobre sombrero oscuro caracterizan al coprino pícaro no comestible; y no consumir nunca los coprinos de tinta con alcohol.','{"Los coprinos pícaros jóvenes pueden confundirse con el coprino de tinta: el coprino pícaro lleva escamas de velo blancas y desprendibles sobre fondo oscuro (patrón negro-blanco); el coprino de tinta es uniformemente gris a gris-pardo con sombrero de pliegues longitudinales/surcado sin manchas blancas.","El coprino pícaro huele a moho-alquitrán y es no comestible; el coprino de tinta es (solo sin alcohol) comestible con reservas.","Coprino pícaro más esbelto y más alto con pie frágil; coprino de tinta más rechoncho y creciendo por lo general en grupos.","Atención: el coprino de tinta contiene coprina y es venenoso con el alcohol — no un comestible «seguro»."}','f'),
('coprinopsis_atramentaria','coprinopsis_picacea','fr','Coprin pie tacheté noir-blanc vs. coprin noir d''encre uniformément gris, longitudinalement plissé, sans flocons de voile blancs.','Coprin pie de moisi-goudronné ; coprin noir d''encre discret-fongique.','Coprin pie isolé dans les forêts de hêtres/feuillus riches en humus/calcaire ; coprin noir d''encre en touffes sur les souches, bords de chemins et dans les jardins.','Les deux à sporée noire, déliquescente ; non discriminant.','Les flocons de voile blancs, essuyables, sur chapeau sombre caractérisent le coprin pie non comestible ; et ne jamais consommer les coprins noirs d''encre avec de l''alcool.','{"Les jeunes coprins pies peuvent être confondus avec le coprin noir d''encre : le coprin pie porte des écailles de voile blanches, essuyables, sur fond sombre (motif noir-blanc) ; le coprin noir d''encre est uniformément gris à gris-brun avec un chapeau longitudinalement plissé/sillonné sans taches blanches.","Le coprin pie sent le moisi-goudronné et est non comestible ; le coprin noir d''encre est (seulement sans alcool) comestible avec réserve.","Coprin pie plus élancé et plus haut avec un pied fragile ; coprin noir d''encre plus trapu et poussant le plus souvent en touffes.","Attention : le coprin noir d''encre contient de la coprine et est lui-même toxique avec l''alcool - pas un comestible « sûr »."}','f'),
('coprinopsis_atramentaria','coprinopsis_picacea','it','Coprinopsis picacea macchiato di nero e bianco vs. Coprinopsis atramentaria uniformemente grigio, a pieghe longitudinali, senza fiocchi di velo bianchi.','Coprinopsis picacea odore di muffa-catrame; Coprinopsis atramentaria odore fungino discreto.','Coprinopsis picacea isolato in faggete/boschi di latifoglie ricchi di humus/calcare; Coprinopsis atramentaria in ciuffi su ceppi, bordi dei sentieri e nei giardini.','Entrambi sporata nera e deliquescente; non distintiva.','Fiocchi di velo bianchi e asportabili su cappello scuro caratterizzano il Coprinopsis picacea non commestibile; e non consumare mai i Coprinopsis atramentaria con l''alcol.','{"I giovani Coprinopsis picacea possono essere confusi con il Coprinopsis atramentaria: il Coprinopsis picacea porta squame di velo bianche e asportabili su fondo scuro (motivo nero-bianco); il Coprinopsis atramentaria è uniformemente grigio a grigio-bruno con cappello a pieghe longitudinali/solcato senza macchie bianche.","Il Coprinopsis picacea odora di muffa-catrame ed è non commestibile; il Coprinopsis atramentaria è (solo senza alcol) commestibile con riserva.","Coprinopsis picacea più slanciato e più alto con gambo fragile; Coprinopsis atramentaria più tozzo e che cresce per lo più in ciuffi.","Attenzione: il Coprinopsis atramentaria contiene coprina ed è velenoso con l''alcol — non un commestibile «sicuro»."}','f'),
('cortinarius_praestans','cortinarius_traganus','en','C. praestans large, wrinkled violet-brown cap with whitish veil and scales; C. traganus smaller, lilac throughout with club-shaped stem.','C. praestans mild; C. traganus repulsively goaty – the smell warns against traganus.','C. praestans in lime-rich deciduous forest (beech/oak); C. traganus rather in acidic coniferous forest.','Both rust-brown – the spore print does NOT separate here; only habit, smell and gill colour distinguish.','Have cortinars validated only by experienced mushroom inspectors (VAPKO) – the genus contains deadly species; as a beginner, leave ALL webcaps.','{"C. praestans is large and robust with a wrinkled violet-brown cap, whitish veil scales and pale clay-coloured, later rust-brown gills; C. traganus is lilac-coloured throughout and more slender.","Smell: C. praestans mild/pleasant; C. traganus unpleasantly goaty.","C. traganus has saffron-ochre to lilac flesh tones and a club-shaped thickened stem; C. praestans firm whitish flesh.","Both are cortinars with rust-brown spore print – the identification of edible cortinars is permitted ONLY to experts."}','f'),
('cortinarius_praestans','cortinarius_traganus','es','C. praestans grande, sombrero pardo-violeta rugoso con velo blanquecino y escamas; C. traganus más pequeño, enteramente lila con pie claviforme.','C. praestans suave; C. traganus olor caprino repugnante – el olor advierte sobre traganus.','C. praestans en bosque de frondosas calcáreo (haya/roble); C. traganus más bien en bosque de coníferas ácido.','Ambos pardo-herrumbre – la esporada aquí NO distingue; solo el porte, el olor y el color de las láminas distinguen.','Hacer validar los cortinarios solo por controladores de setas experimentados (VAPKO) – el género contiene especies mortales; como principiante, dejar TODOS los cortinarios en el sitio.','{"C. praestans es grande y robusto con sombrero pardo-violeta rugoso, escamas de velo blanquecinas y láminas pálido color arcilla, más tarde pardo-herrumbre; C. traganus está enteramente coloreado de lila y es más esbelto.","Olor: C. praestans suave/agradable; C. traganus desagradable, caprino.","C. traganus tiene tonos de carne azafrán-ocre a lila y pie engrosado en maza; C. praestans carne firme blanquecina.","Ambos son cortinarios con esporada pardo-herrumbre – la determinación de cortinarios comestibles está permitida SOLO a expertos."}','f'),
('cortinarius_praestans','cortinarius_traganus','fr','C. praestans grand, chapeau brun-violet ridé avec un voile blanchâtre et des écailles ; C. traganus plus petit, entièrement lilas avec un pied en massue.','C. praestans doux ; C. traganus répugnant, de bouc – l''odeur met en garde contre traganus.','C. praestans en forêt de feuillus calcaire (hêtre/chêne) ; C. traganus plutôt en forêt de conifères acide.','Les deux brun rouille – la sporée ne sépare PAS ici ; seuls le port, l''odeur et la couleur des lamelles distinguent.','Ne faire valider les cortinaires en général que par des contrôleurs de champignons expérimentés (VAPKO) – le genre contient des espèces mortelles ; en tant que débutant, laisser TOUS les cortinaires sur place.','{"C. praestans est grand et robuste avec un chapeau brun-violet ridé, des écailles de voile blanchâtres et des lamelles ocre pâle, plus tard brun rouille ; C. traganus est coloré en lilas de façon uniforme et plus élancé.","Odeur : C. praestans douce/agréable ; C. traganus désagréable, de bouc-chèvre.","C. traganus a des teintes de chair safran-ocre à lilas et un pied épaissi en massue ; C. praestans une chair blanchâtre ferme.","Les deux sont des cortinaires à sporée brun rouille – la détermination des cortinaires comestibles n''est permise QU''aux experts."}','f'),
('cortinarius_praestans','cortinarius_traganus','it','C. praestans grande, cappello bruno-violetto rugoso con velo biancastro e squame; C. traganus più piccolo, interamente lilla con gambo claviforme.','C. praestans mite; C. traganus odore caprino ripugnante – l''odore mette in guardia da traganus.','C. praestans in bosco di latifoglie calcareo (faggio/quercia); C. traganus piuttosto in bosco di conifere acido.','Entrambi bruno-ruggine – la sporata qui NON distingue; solo il portamento, l''odore e il colore delle lamelle distinguono.','Far validare i cortinari solo da controllori di funghi esperti (VAPKO) – il genere contiene specie mortali; da principiante, lasciare TUTTI i cortinari sul posto.','{"C. praestans è grande e robusto con cappello bruno-violetto rugoso, squame di velo biancastre e lamelle pallido color argilla, più tardi bruno-ruggine; C. traganus è interamente colorato di lilla e più slanciato.","Odore: C. praestans mite/gradevole; C. traganus sgradevole, caprino-becco.","C. traganus ha toni di carne zafferano-ocra a lilla e gambo ingrossato a clava; C. praestans carne soda biancastra.","Entrambi sono cortinari con sporata bruno-ruggine – la determinazione dei cortinari commestibili è permessa SOLO agli esperti."}','f'),
('cuphophyllus_pratensis','hygrocybe_conica','en','The eponymous blackening (cap/stem turn ink-black on pressure or with age) characterises the conical waxcap; the meadow waxcap stays pale apricot-coloured and never blackens.','Both largely odourless – no separating feature.','Both on unfertilised meadows/poor grassland – habitat does not separate; therefore pay attention to shape and blackening.','Both with white spore print – no separating feature.','Pressure test: if the fruiting body blackens at contact points or if the cap is sharply conical and fire-coloured, leave it (conical waxcap). Only collect blunt, pale-orange, non-blackening waxcaps with decurrent waxy gills.','{"Conical waxcap: sharply conical, vivid yellow-orange-red cap that turns BLACK on touch/with age (whole fruiting body blackening) – characteristic blackening","Meadow waxcap: bluntly convex to flattening, pale ochre-orange/apricot-coloured cap, does NOT blacken","Meadow waxcap with widely decurrent, distant, thickish waxy gills; conical waxcap with rather free/adnate gills","The conical waxcap is regarded as slightly poisonous/suspected of causing gastrointestinal upset – the meadow waxcap is a good edible"}','f'),
('cuphophyllus_pratensis','hygrocybe_conica','es','El ennegrecimiento epónimo (sombrero/pie se vuelven negro tinta a la presión o con la edad) caracteriza al higróforo cónico; el higróforo de los prados permanece de color albaricoque pálido y no ennegrece nunca.','Ambos prácticamente inodoros – ningún criterio de separación.','Ambos sobre prados no abonados/pastos pobres – el hábitat no distingue; por ello atender a la forma y al ennegrecimiento.','Ambos con esporada blanca – ningún criterio de separación.','Prueba de presión: si el cuerpo fructífero ennegrece en los puntos de contacto o si el sombrero es cónico puntiagudo y color fuego, dejarlo en el sitio (higróforo cónico). Recolectar solo los higróforos obtusos, naranja pálido, que no ennegrecen, con láminas cerosas decurrentes.','{"Higróforo cónico: sombrero cónico puntiagudo, vivo amarillo-naranja-rojo, que se vuelve NEGRO al tacto/con la edad (todo el cuerpo fructífero ennegreciendo) – ennegrecimiento característico","Higróforo de los prados: sombrero obtuso-convexo a aplanándose, ocre-naranja pálido/color albaricoque, NO ennegrece","Higróforo de los prados con láminas cerosas ampliamente decurrentes, espaciadas y engrosadas; higróforo cónico con láminas más bien libres/adnatas","El higróforo cónico se considera ligeramente venenoso/sospechoso de causar trastornos gastrointestinales – el higróforo de los prados es un buen comestible"}','f'),
('cuphophyllus_pratensis','hygrocybe_conica','fr','Le noircissement éponyme (chapeau/pied deviennent noir d''encre à la pression ou avec l''âge) caractérise l''hygrocybe conique ; le hygrophore des prés reste abricot pâle et ne noircit jamais.','Les deux largement inodores – pas un critère de séparation.','Les deux sur prairies non fertilisées/pelouses maigres – l''habitat ne sépare pas ; donc faire attention à la forme et au noircissement.','Les deux à sporée blanche – pas un critère de séparation.','Test de pression : si le carpophore noircit aux points de contact ou si le chapeau est conique-pointu et couleur de feu, laisser sur place (hygrocybe conique). Ne récolter que les hygrophores obtus, orange pâle, ne noircissant pas, à lamelles cireuses décurrentes.','{"Hygrocybe conique : chapeau conique-pointu, jaune-orange-rouge vif, qui NOIRCIT au toucher/avec l''âge (tout le carpophore noircissant) – noircissement caractéristique","Hygrophore des prés : chapeau obtus-convexe à s''aplatissant, ocre-orange/abricot pâle, ne noircit PAS","Hygrophore des prés à lamelles cireuses largement décurrentes, espacées, épaissies ; hygrocybe conique à lamelles plutôt libres/adnexées","Hygrocybe conique considérée comme faiblement toxique/suspecte gastro-intestinale – hygrophore des prés bon comestible"}','f'),
('cuphophyllus_pratensis','hygrocybe_conica','it','L''annerimento eponimo (cappello/gambo diventano nero inchiostro alla pressione o con l''età) caratterizza l''Hygrocybe conica; il Cuphophyllus pratensis resta di colore albicocca pallido e non annerisce mai.','Entrambi pressoché inodori – nessun criterio di separazione.','Entrambi su prati non concimati/magri – l''habitat non distingue; quindi badare alla forma e all''annerimento.','Entrambi con sporata bianca – nessun criterio di separazione.','Test di pressione: se il corpo fruttifero annerisce nei punti di contatto o se il cappello è conico appuntito e color fuoco, lasciare sul posto (Hygrocybe conica). Raccogliere solo gli igrofori ottusi, arancio pallido, non anneriti, con lamelle cerose decorrenti.','{"Hygrocybe conica: cappello conico appuntito, vivace giallo-arancio-rosso, che ANNERISCE al tatto/con l''età (intero corpo fruttifero annerente) – annerimento caratteristico","Cuphophyllus pratensis: cappello ottuso-convesso a spianantesi, ocra-arancio pallido/color albicocca, NON annerisce","Cuphophyllus pratensis con lamelle cerose largamente decorrenti, distanziate e ingrossate; Hygrocybe conica con lamelle piuttosto libere/adnate","L''Hygrocybe conica è considerato debolmente velenoso/sospetto di disturbi gastrointestinali – il Cuphophyllus pratensis è un buon commestibile"}','f'),
('cuphophyllus_virgineus','hygrocybe_conica','en','The snowy waxcap is small, white and does not blacken; the conical waxcap is sharply conical, fiery-coloured and blackens.','Both nearly odourless – not a distinguishing feature.','Both on poor meadows/lawns – habitat does not distinguish; colour and blackening are decisive.','Both with white spore print – not a distinguishing feature.','Blackening + sharply conical fiery colour = conical waxcap (leave it). Use only white, non-blackening waxcaps with decurrent gills.','{"Conical waxcap: sharply conical cap, vividly coloured yellow/orange/red, blackens on touch and completely with age","Snowy waxcap: smaller, whitish-ivory, bluntly convex cap, does NOT blacken","Snowy waxcap with white waxy, distant, widely decurrent gills; conical waxcap vividly coloured and blackening","Conical waxcap mildly poisonous/suspected of gastrointestinal effects – snowy waxcap a mild edible"}','f'),
('cuphophyllus_virgineus','hygrocybe_conica','es','La higróforo virginal es pequeña, blanca y no ennegrece; la higróforo cónico es cónico-puntiagudo, color fuego y ennegrece.','Ambos casi inodoros – no es un carácter distintivo.','Ambos en prados/céspedes pobres – el hábitat no distingue; el color y el ennegrecimiento son determinantes.','Ambos con esporada blanca – no es un carácter distintivo.','Ennegrecimiento + color fuego cónico-puntiagudo = higróforo cónico (dejarlo). Usar solo los higróforos blancos, no ennegrecientes, con láminas decurrentes.','{"Higróforo cónico: sombrero cónico-puntiagudo, vivamente coloreado amarillo/naranja/rojo, ennegrece al tacto y por completo con la edad","Higróforo virginal: sombrero más pequeño, blanquecino-marfil, convexo obtuso, NO ennegrece","Higróforo virginal con láminas cerosas blancas, espaciadas, ampliamente decurrentes; higróforo cónico vivamente coloreado y ennegreciente","Higróforo cónico levemente tóxico/sospechoso de efectos gastrointestinales – higróforo virginal comestible suave"}','f'),
('cuphophyllus_virgineus','hygrocybe_conica','fr','Le hygrophore blanc de neige est petit, blanc et ne noircit pas ; l''hygrocybe conique est conique-pointu, couleur de feu et noircit.','Les deux presque inodores – pas un critère de séparation.','Les deux sur prairies/pelouses maigres – la station ne sépare pas ; la couleur et le noircissement sont déterminants.','Les deux à sporée blanche – pas un critère de séparation.','Noircissement + couleur de feu conique-pointue = hygrocybe conique (laisser sur place). N''utiliser que les hygrophores blancs, ne noircissant pas, à lamelles décurrentes.','{"Hygrocybe conique : chapeau conique-pointu, fortement coloré en jaune/orange/rouge, noircit au toucher et avec l''âge complètement","Hygrophore blanc de neige : chapeau plus petit, blanchâtre-ivoire, obtus-convexe, ne noircit PAS","Hygrophore blanc de neige à lamelles cireuses largement décurrentes, espacées, blanches ; hygrocybe conique vivement colorée et noircissante","Hygrocybe conique faiblement toxique/suspecte gastro-intestinale – hygrophore blanc de neige comestible doux"}','f'),
('cuphophyllus_virgineus','hygrocybe_conica','it','La cuffia verginea è piccola, bianca e non annerisce; l''igroforo conico è conico-appuntito, color fuoco e annerisce.','Entrambi quasi inodori – nessun carattere distintivo.','Entrambi su prati/tappeti erbosi magri – l''habitat non distingue; colore e annerimento sono determinanti.','Entrambi con sporata bianca – nessun carattere distintivo.','Annerimento + color fuoco conico-appuntito = igroforo conico (da lasciare). Usare solo le cuffie bianche, non anneribili, con lamelle decorrenti.','{"Igroforo conico: cappello conico-appuntito, vivacemente colorato giallo/arancio/rosso, annerisce al tatto e completamente con l''età","Cuffia verginea: cappello più piccolo, biancastro-avorio, convesso ottuso, NON annerisce","Cuffia verginea con lamelle cerose bianche, distanziate, ampiamente decorrenti; igroforo conico vivacemente colorato e anneribile","Igroforo conico leggermente tossico/sospetto di disturbi gastrointestinali – cuffia verginea commestibile mite"}','f'),
('cyclocybe_aegerita','gymnopilus_junonius','en','Pioppino has a lighter, often cracked-areolate brown cap and paler gills; G. junonius is uniformly bright orange with rust-brown gills.','Pioppino pleasantly spicy; G. junonius mealy-rancid with strongly bitter taste.','Pioppino prefers hardwood (especially poplar, often cultivated); G. junonius on stumps and trunk bases of hardwood and conifers.','Pioppino: tobacco-brown spore print. G. junonius: rust-brown spore print – similar, so additionally check bitterness/cap colour.','Taste test (spit out): strongly bitter = rustgill = do not eat. Pioppino is mild and mostly on hardwood.','{"Spore print: pioppino tobacco-/olive-brown, G. junonius pure rust-brown; taste of pioppino mild, G. junonius extremely bitter.","Cap colour: pioppino light ochre to dark brown, often cracked-areolate; G. junonius bright orange rust-yellow.","Stem: pioppino tough-fibrous, pale with a membranous ring; G. junonius thicker, fibrous, orange-tinged.","Pioppino grows mostly on hardwood (especially poplar); G. junonius more often on stumps and trunk bases of conifers and hardwood."}','f'),
('cyclocybe_aegerita','gymnopilus_junonius','es','El piopino tiene un sombrero pardo más claro, a menudo agrietado-areolado, y láminas más pálidas; G. junonius es uniformemente naranja brillante con láminas pardo-herrumbre.','Piopino agradablemente especiado; G. junonius harinoso-rancio con sabor fuertemente amargo.','El piopino prefiere la madera de frondosas (sobre todo álamo, a menudo cultivado); G. junonius sobre tocones y bases de troncos de frondosas y coníferas.','Piopino: esporada pardo-tabaco. G. junonius: esporada pardo-herrumbre – similar, por eso verificar además el amargor/color del sombrero.','Prueba de sabor (escupir): fuertemente amargo = gimnopilo = no comer. El piopino es suave y por lo general sobre madera de frondosas.','{"Esporada: piopino pardo-tabaco/oliváceo, G. junonius pardo-herrumbre puro; sabor del piopino suave, G. junonius extremadamente amargo.","Color del sombrero: piopino de ocre claro a pardo oscuro, a menudo agrietado-areolado; G. junonius naranja-amarillo herrumbre brillante.","Pie: piopino tenaz-fibroso, claro con anillo membranoso; G. junonius más grueso, fibroso, con tonos naranja.","El piopino crece en su mayoría sobre madera de frondosas (sobre todo álamo); G. junonius más a menudo sobre tocones y bases de troncos de coníferas y frondosas."}','f'),
('cyclocybe_aegerita','gymnopilus_junonius','fr','Le pholiote du peuplier a un chapeau brun plus clair, souvent crevassé-aréolé, et des lamelles plus pâles ; G. junonius est uniformément orange vif avec des lamelles brun rouille.','Pholiote du peuplier agréablement épicé ; G. junonius farineux-rance avec un goût fortement amer.','Pholiote du peuplier préfère le bois de feuillus (surtout peuplier, souvent cultivé) ; G. junonius sur souches et bases de troncs de feuillus et de conifères.','Pholiote du peuplier : sporée brun tabac. G. junonius : sporée brun rouille – semblable, donc vérifier en plus l''amertume/la couleur du chapeau.','Test gustatif (recracher) : fortement amer = gymnopile = ne pas manger. Le pholiote du peuplier est doux et le plus souvent sur bois de feuillus.','{"Sporée : pholiote du peuplier brun tabac/olive, G. junonius brun rouille pur ; goût du pholiote du peuplier doux, G. junonius extrêmement amer.","Couleur du chapeau : pholiote du peuplier ocre clair à brun foncé, souvent crevassé-aréolé ; G. junonius orange-jaune rouille éclatant.","Pied : pholiote du peuplier coriace-fibrilleux, clair avec un anneau membraneux ; G. junonius plus épais, fibrilleux, teinté d''orange.","Pholiote du peuplier pousse le plus souvent sur bois de feuillus (surtout peuplier) ; G. junonius plus fréquent sur souches et bases de troncs de conifères et de feuillus."}','f'),
('cyclocybe_aegerita','gymnopilus_junonius','it','Il piopparello ha un cappello bruno più chiaro, spesso screpolato-areolato, e lamelle più pallide; G. junonius è uniformemente arancio brillante con lamelle bruno-ruggine.','Piopparello gradevolmente speziato; G. junonius farinoso-rancido con gusto fortemente amaro.','Il piopparello predilige il legno di latifoglie (soprattutto pioppo, spesso coltivato); G. junonius su ceppi e basi dei tronchi di latifoglie e conifere.','Piopparello: sporata bruno-tabacco. G. junonius: sporata bruno-ruggine – simile, quindi verificare in più amarezza/colore del cappello.','Prova di assaggio (sputare): fortemente amaro = gimnopilo = non mangiare. Il piopparello è mite e per lo più su legno di latifoglie.','{"Sporata: piopparello bruno-tabacco/olivastro, G. junonius bruno-ruggine puro; gusto del piopparello mite, G. junonius estremamente amaro.","Colore del cappello: piopparello da ocra chiaro a bruno scuro, spesso screpolato-areolato; G. junonius arancio-giallo ruggine brillante.","Gambo: piopparello tenace-fibroso, chiaro con anello membranoso; G. junonius più spesso, fibroso, tinto d''arancio.","Il piopparello cresce per lo più su legno di latifoglie (soprattutto pioppo); G. junonius più spesso su ceppi e basi dei tronchi di conifere e latifoglie."}','f'),
('disciotis_venosa','gyromitra_gigas','en','The bleach cup is a flat brown bowl lying on the ground with a veined inner surface; the snow morel (giant false morel) is an upright brain-shaped cap.','The bleach cup smells distinctly of chlorine (typical, especially at breakage points); the snow morel smells unspecifically mushroomy.','The bleach cup in spring on moist, calcareous soils/floodplain forest; the snow morel a wood saprobiont – the appearance times overlap.','Both ascomycetes with pale spore print – not a distinguishing feature.','The chlorine smell and the flat cup shape characterise the bleach cup. Leave anything upright and brain-shaped (false morel risk of confusion) and consume both species only well cooked.','{"Bleach cup: bowl-/cup-shaped, spread out flat, inner surface brown with veined-wrinkled surface, short/absent stem, characteristic chlorine smell","Snow morel: upright, tuberous, brain-like convoluted cap on a distinct thick stem, no cup-shaped structure","Bleach cup edible only well cooked (raw indigestible); the snow morel itself contains hardly any gyromitrin, but can scarcely be distinguished from deadly false morel species – therefore avoid","Bleach cup surface veined-ribbed but flat; false morel surface strongly three-dimensional, bulging"}','f'),
('disciotis_venosa','gyromitra_gigas','es','La disciotis venosa es un cuenco pardo plano, apoyado en el suelo, con la cara interna venosa; la giromitra gigante es un sombrero erecto en forma de cerebro.','La disciotis venosa huele claramente a cloro (típico, sobre todo en los puntos de rotura); la giromitra gigante huele de forma inespecífica fúngica.','La disciotis venosa en primavera sobre suelos húmedos, ricos en cal/bosque de ribera; la giromitra gigante saprobionte de la madera – los periodos de aparición se solapan.','Ambos ascomicetos con esporada clara – no es un carácter distintivo.','El olor a cloro y la forma plana de cuenco caracterizan a la disciotis venosa. Dejar todo lo erecto en forma de cerebro (riesgo de confusión con giromitras) y consumir ambas especies solo bien cocinadas.','{"Disciotis venosa: en forma de cuenco/copa, extendida plana, cara interna parda con superficie venosa-rugosa, pie corto/ausente, olor a cloro característico","Giromitra gigante: sombrero erecto, tuberoso, sinuoso como un cerebro, sobre un pie grueso definido, sin estructura de cuenco","Disciotis venosa comestible solo bien cocinada (cruda indigesta); la giromitra gigante misma apenas contiene giromitrina, pero apenas se distingue de las especies de giromitra mortales – por eso evitar","Superficie de la disciotis venosa venosa-acostillada pero plana; superficie de la giromitra fuertemente tridimensional, abombada"}','f'),
('disciotis_venosa','gyromitra_gigas','fr','Le pézize veiné est une coupe brune plate, posée au sol, à face interne veinée ; le gyromitre géant un chapeau dressé en forme de cerveau.','Le pézize veiné sent nettement le chlore (typique, surtout aux cassures) ; le gyromitre géant sent fongique non spécifique.','Pézize veiné au printemps sur sols humides, riches en calcaire/forêt alluviale ; gyromitre géant comme saprobionte lignicole – la période d''apparition se chevauche.','Les deux ascomycètes à sporée claire – pas un critère de séparation.','L''odeur de chlore et la forme plate-en coupe caractérisent le pézize veiné. Laisser sur place tout ce qui est dressé en forme de cerveau (risque de confusion avec les gyromitres) et ne consommer les deux espèces que bien cuites.','{"Pézize veiné : en forme de coupe/cupule, étalé à plat, face interne brune à surface veinée-ridée, pied court/absent, odeur de chlore caractéristique","Gyromitre géant : chapeau dressé, bosselé-circonvolué en forme de cerveau sur un pied épais net, pas de structure en coupe","Pézize veiné comestible seulement bien cuit (cru mal toléré) ; gyromitre géant lui-même contenant peu de gyromitrine, mais à peine séparable des espèces de gyromitres mortelles – donc à éviter","Surface du pézize veiné veinée-côtelée mais plate ; surface du gyromitre fortement tridimensionnelle bombée"}','f'),
('disciotis_venosa','gyromitra_gigas','it','Il disciotis venato è una coppa bruna piatta, adagiata al suolo, con faccia interna venata; la gyromitra gigante è un cappello eretto a forma di cervello.','Il disciotis venato odora nettamente di cloro (tipico, specie nei punti di rottura); la gyromitra gigante odora in modo aspecifico fungino.','Il disciotis venato in primavera su suoli umidi, ricchi di calcare/bosco golenale; la gyromitra gigante saprobionte del legno – i periodi di comparsa si sovrappongono.','Entrambi ascomiceti con sporata chiara – nessun carattere distintivo.','L''odore di cloro e la forma piatta a coppa caratterizzano il disciotis venato. Lasciare tutto ciò che è eretto a forma di cervello (rischio di confusione con le gyromitre) e consumare entrambe le specie solo ben cotte.','{"Disciotis venato: a forma di coppa/cupola, disteso piatto, faccia interna bruna con superficie venata-rugosa, gambo corto/assente, odore di cloro caratteristico","Gyromitra gigante: cappello eretto, tuberoso, sinuoso a forma di cervello, su un gambo spesso distinto, senza struttura a coppa","Disciotis venato commestibile solo ben cotto (crudo indigesto); la gyromitra gigante stessa contiene a malapena giromitrina, ma si distingue a malapena dalle gyromitre mortali – quindi da evitare","Superficie del disciotis venato venata-costoluta ma piatta; superficie della gyromitra fortemente tridimensionale, bombata"}','f'),
('eierschwamm','cortinarius_orellanus','en','Chanterelle: yolk-yellow with funnel shape and ridges. Webcap (Raukopf): red-brown-orange with true gills.','Chanterelle: apricot-fruity. Webcap: radish-like.','Chanterelle: May-Oct coniferous forest. Webcap: Sep-Nov deciduous forest.','Chanterelle: pale yellow. Webcap: rust-brown.','GOLDEN RULE: turn the cap over — TRUE gills or RIDGES? If in doubt, VAPKO!','{"Chanterelle has RIDGES, webcap has TRUE gills","Chanterelle is egg-yellow-apricot, webcap orange-red-brown"}','t'),
('eierschwamm','cortinarius_orellanus','es','Rebozuelo: amarillo yema con forma de embudo y pliegues. Cortinario (Cortinarius orellanus): pardo rojizo-anaranjado con láminas verdaderas.','Rebozuelo: afrutado a albaricoque. Cortinario: a rábano.','Rebozuelo: de mayo a octubre, bosque de coníferas. Cortinario: de septiembre a noviembre, bosque caducifolio.','Rebozuelo: amarillo pálido. Cortinario: pardo herrumbre.','REGLA DE ORO: dale la vuelta al sombrero — ¿láminas VERDADERAS o PLIEGUES? En caso de duda, ¡VAPKO!','{"El rebozuelo tiene PLIEGUES, el cortinario tiene láminas VERDADERAS","El rebozuelo es amarillo yema-albaricoque, el cortinario anaranjado-pardo rojizo"}','t'),
('eierschwamm','cortinarius_orellanus','fr','Girolle (chanterelle): jaune d''œuf, en forme d''entonnoir et à plis. Cortinaire (Raukopf): brun-roux à orange avec de véritables lamelles.','Girolle: fruitée, d''abricot. Cortinaire: de radis (raphanoïde).','Girolle: de mai à octobre, forêt de conifères. Cortinaire: de septembre à novembre, forêt de feuillus.','Girolle: jaune pâle. Cortinaire: brun-rouille.','RÈGLE D''OR: retournez le chapeau — de VRAIES lamelles ou des PLIS? En cas de doute, VAPKO!','{"La girolle a des PLIS, le cortinaire (Raukopf) a de VRAIES lamelles","La girolle est jaune d''œuf-abricot, le cortinaire est orange-brun-roux"}','t'),
('eierschwamm','cortinarius_orellanus','it','Galletto (Pfifferling): giallo tuorlo con forma a imbuto e pseudolamelle (pliche). Cortinarius (Raukopf): da bruno-rossastro a arancione con vere lamelle.','Galletto (Pfifferling): fruttato di albicocca. Cortinarius (Raukopf): rafanoide (di ravanello).','Galletto (Pfifferling): mag-ott, bosco di conifere. Cortinarius (Raukopf): set-nov, bosco di latifoglie.','Galletto (Pfifferling): giallo pallido. Cortinarius (Raukopf): bruno-ruggine.','REGOLA D''ORO: rovesciare il cappello — VERE lamelle o PSEUDOLAMELLE (pliche)? In caso di dubbio VAPKO!','{"Il galletto (Pfifferling) ha PSEUDOLAMELLE (pliche), il Cortinarius (Raukopf) ha VERE lamelle","Il galletto (Pfifferling) è giallo tuorlo-albicocca, il Cortinarius (Raukopf) è da arancione a bruno-rossastro"}','t'),
('eierschwamm','hygrophoropsis_aurantiaca','en','Ridges (chanterelle) vs. true gills (false one); texture firm vs. soft.','Chanterelle fruity (apricot); false one nonspecific/musty','Chanterelle deciduous/coniferous forest; false one mainly conifer litter/deadwood','both pale','The false chanterelle is mildly poisonous (gastrointestinal). Check blunt ridges vs. sharp detachable gills. If strongly orange-red, additionally rule out the olive-tree mushroom (poisonous).','{"True chanterelle: blunt, firmly fused ridges, firm-fleshy","False chanterelle: true thin, strongly forked, easily detachable gills, soft"}','t'),
('eierschwamm','hygrophoropsis_aurantiaca','es','Pliegues (rebozuelo) frente a láminas verdaderas (falso rebozuelo); consistencia firme frente a blanda.','Rebozuelo afrutado (albaricoque); falso rebozuelo inespecífico/a moho','Rebozuelo en bosque caducifolio/de coníferas; falso rebozuelo sobre todo en hojarasca de coníferas/madera muerta','ambos pálidos','El falso rebozuelo es ligeramente tóxico (gastrointestinal). Comprobar pliegues romos frente a láminas afiladas y desprendibles. Si es de un naranja-rojo intenso, descartar además el hongo del olivo (Omphalotus, tóxico).','{"Rebozuelo verdadero: pliegues romos, firmemente soldados, de carne firme","Falso rebozuelo: láminas verdaderas finas, muy bifurcadas, fácilmente desprendibles, blandas"}','t'),
('eierschwamm','hygrophoropsis_aurantiaca','fr','Plis (girolle) vs. véritables lamelles (la fausse girolle); consistance ferme vs. molle.','Girolle fruitée (abricot); la fausse non spécifique/de moisi','Girolle forêt de feuillus/de conifères; la fausse surtout litière d''aiguilles/bois mort','les deux pâles','La fausse girolle est faiblement toxique (troubles gastro-intestinaux). Vérifiez les plis émoussés vs. les lamelles vives et détachables. Si la couleur est d''un orange-rouge soutenu, excluez en plus le clitocybe de l''olivier (toxique).','{"Vraie girolle: plis émoussés, fermement soudés, ferme-charnue","Fausse girolle: véritables lamelles fines, fortement fourchues, facilement détachables, molle"}','t'),
('eierschwamm','hygrophoropsis_aurantiaca','it','Pseudolamelle/pliche (galletto, Pfifferling) vs. vere lamelle (falso galletto); consistenza soda vs. molle.','Galletto (Pfifferling) fruttato (albicocca); il falso aspecifico/muffito.','Galletto (Pfifferling) in bosco di latifoglie/conifere; il falso soprattutto su lettiera di aghi/legno morto.','entrambi pallido.','Il falso galletto (Hygrophoropsis aurantiaca) è debolmente tossico (gastro-intestinale). Verificare pseudolamelle/pliche ottuse vs. lamelle nette e staccabili. In caso di colore arancio-rosso intenso escludere inoltre l''Omphalotus (fungo dell''olivo, tossico).','{"Galletto vero (Pfifferling): pseudolamelle/pliche ottuse, saldamente concresciute, soda-carnoso","Falso galletto: vere lamelle sottili, fortemente forcate, facilmente staccabili, molle"}','t'),
('eierschwamm','omphalotus_olearius','en','The jack-o''-lantern is a strong orange with true thin, crowded gills and a funnel-shaped depressed cap, in clusters on wood; the chanterelle is pale yellow with thick, forked, decurrent ridges, single on the ground.','The chanterelle smells pleasantly fruity of apricot; the jack-o''-lantern smells inconspicuous to slightly unpleasant, without an apricot note.','Jack-o''-lantern in clusters on hardwood/stumps/roots (heat-loving, rare in Switzerland and only in mild locations); chanterelle single out of the ground in conifer and hardwood forest, frequent in Switzerland.','Both whitish to pale cream — the spore print does NOT separate them. Decisive are true gills vs thick ridges and the growth form (wood vs ground).','True, sharp-edged gills + clustered growth directly on wood = NEVER a chanterelle, no matter how yellow. A chanterelle has only thick, forked, decurrent ridges and stands single out of the ground.','{"The jack-o''-lantern has true, sharp-edged, crowded gills; the chanterelle has NO true gills, but only blunt, forked, thick ridges (thickened veined folds) that run far down the stem.","The jack-o''-lantern grows in clusters directly on/against wood and roots (oak, olive, sweet chestnut, stumps); the true chanterelle grows single to scattered out of the forest floor (mycorrhiza), never in clusters on wood.","Colour of the jack-o''-lantern strong orange to orange-red/brown-orange; chanterelle pale egg-yellow to yolk-yellow, uniform.","The gills of the fresh jack-o''-lantern glow faintly green in the dark (bioluminescence) — the chanterelle never.","Chanterelle flesh is fibrous-tough, pale yellow throughout and tears in fibres; jack-o''-lantern flesh is softer, orange-brown towards the base."}','f'),
('eierschwamm','omphalotus_olearius','es','El clitocibe luminiscente/seta del olivo es de un naranja intenso con verdaderas láminas finas, apretadas, y sombrero deprimido en embudo, en grupos sobre madera; el rebozuelo/cantarela es amarillo pálido con pliegues gruesos, bifurcados, decurrentes, aislado en el suelo.','El rebozuelo huele agradablemente afrutado a albaricoque; la seta del olivo huele discreta o ligeramente desagradable, sin nota de albaricoque.','Seta del olivo en grupos sobre madera de frondosas/tocones/raíces (termófila, en Suiza rara y solo en estaciones cálidas); rebozuelo aislado saliendo del suelo en bosque de coníferas y frondosas, frecuente en Suiza.','Ambos blanquecinos a crema pálido — la esporada NO los distingue. Decisivos son las verdaderas láminas vs los pliegues gruesos y la forma de crecimiento (madera vs suelo).','Verdaderas láminas de arista cortante + crecimiento en grupos directamente sobre madera = NUNCA un rebozuelo, por amarillo que sea. Un rebozuelo solo tiene pliegues gruesos, bifurcados, decurrentes y crece aislado fuera del suelo.','{"La seta del olivo tiene verdaderas láminas de arista cortante, apretadas; el rebozuelo NO tiene verdaderas láminas, sino solo pliegues romos, bifurcados, gruesos (repliegues venosos engrosados) que descienden mucho por el pie.","La seta del olivo crece en grupos directamente sobre/contra la madera y las raíces (roble, olivo, castaño, tocones); el verdadero rebozuelo crece aislado o disperso saliendo del suelo del bosque (micorriza), nunca en grupos sobre madera.","Color de la seta del olivo naranja intenso a naranja-rojo/pardo-anaranjado; rebozuelo amarillo pálido a amarillo yema, uniforme.","Las láminas de la seta del olivo fresca brillan débilmente de verde en la oscuridad (bioluminiscencia) — el rebozuelo nunca.","La carne del rebozuelo es fibrosa-tenaz, amarillo pálido en todo su espesor y se rasga en fibras; la carne de la seta del olivo es más blanda, naranja-parda hacia la base."}','f'),
('eierschwamm','omphalotus_olearius','fr','Le clitocybe de l''olivier est d''un orange vif avec de vraies lames fines, serrées, et un chapeau creusé en entonnoir, en touffes sur bois ; la girolle est jaune pâle avec des plis épais, fourchus, décurrents, isolée au sol.','La girolle a une agréable odeur fruitée d''abricot ; le clitocybe de l''olivier a une odeur discrète à légèrement désagréable, sans note d''abricot.','Clitocybe de l''olivier en touffes sur bois de feuillus/souches/racines (thermophile, rare en Suisse et seulement en stations douces) ; girolle isolée sortant du sol en forêt de conifères et de feuillus, fréquente en Suisse.','Les deux blanchâtres à crème pâle — la sporée ne les distingue PAS. Décisifs sont les vraies lames vs les plis épais et le mode de croissance (bois vs sol).','De vraies lames à arête tranchante + croissance en touffes directement sur bois = JAMAIS une girolle, aussi jaune soit-elle. Une girolle n''a que des plis épais, fourchus, décurrents et pousse isolée hors du sol.','{"Le clitocybe de l''olivier a de vraies lames à arête tranchante, serrées ; la girolle n''a PAS de vraies lames, mais seulement des plis épais, fourchus, émoussés (replis veineux épaissis) qui descendent loin sur le pied.","Le clitocybe de l''olivier pousse en touffes directement sur/contre le bois et les racines (chêne, olivier, châtaignier, souches) ; la vraie girolle pousse isolée à dispersée hors du sol forestier (mycorhize), jamais en touffes sur bois.","Couleur du clitocybe de l''olivier orange vif à orange-rouge/brun-orangé ; girolle jaune pâle à jaune d''œuf, uniforme.","Les lames du clitocybe de l''olivier frais luisent faiblement vert dans l''obscurité (bioluminescence) — jamais la girolle.","La chair de la girolle est fibreuse-tenace, jaune pâle de part en part et se déchire en fibres ; la chair du clitocybe de l''olivier est plus molle, orange-brun vers la base."}','f'),
('eierschwamm','omphalotus_olearius','it','L''omfaloto dell''olivo è di un arancione vivo con vere lamelle sottili, fitte, e cappello depresso a imbuto, a ciuffi su legno; il finferlo/gallinaccio è giallo pallido con pliche spesse, forcate, decorrenti, isolato al suolo.','Il finferlo ha un gradevole odore fruttato di albicocca; l''omfaloto dell''olivo ha odore poco appariscente o leggermente sgradevole, senza nota di albicocca.','Omfaloto dell''olivo a ciuffi su legno di latifoglie/ceppaie/radici (termofilo, in Svizzera raro e solo in stazioni miti); finferlo isolato dal suolo in bosco di conifere e latifoglie, frequente in Svizzera.','Entrambi biancastri a crema pallido — la sporata NON li distingue. Decisivi sono le vere lamelle vs le pliche spesse e la forma di crescita (legno vs suolo).','Vere lamelle a spigolo tagliente + crescita a ciuffi direttamente su legno = MAI un finferlo, per quanto giallo. Un finferlo ha solo pliche spesse, forcate, decorrenti e cresce isolato dal suolo.','{"L''omfaloto dell''olivo ha vere lamelle a spigolo tagliente, fitte; il finferlo NON ha vere lamelle, ma solo pliche ottuse, forcate, spesse (pieghe venose ispessite) che scendono molto sul gambo.","L''omfaloto dell''olivo cresce a ciuffi direttamente su/contro il legno e le radici (quercia, olivo, castagno, ceppaie); il vero finferlo cresce isolato o sparso dal suolo del bosco (micorriza), mai a ciuffi su legno.","Colore dell''omfaloto dell''olivo arancione vivo fino a arancio-rosso/bruno-arancio; finferlo giallo pallido a giallo tuorlo, uniforme.","Le lamelle dell''omfaloto dell''olivo fresco brillano debolmente di verde al buio (bioluminescenza) — il finferlo mai.","La carne del finferlo è fibrosa-tenace, gialla pallida in tutto lo spessore e si lacera in fibre; la carne dell''omfaloto dell''olivo è più molle, arancio-bruna verso la base."}','f'),
('flockenstieliger_hexenpilz','rubroboletus_satanas','en','Stem with red flecks (NO network) and immediate intense blackish-blue bluing in the dotted-stem bolete (scarletina bolete) versus a red stem network and weak bluing in the Devil''s bolete.','The Devil''s bolete smells of carrion when old, the scarletina bolete smells pleasantly mushroomy.','The scarletina bolete also grows in acidic conifer forests; the Devil''s bolete is strictly confined to warm calcareous hardwood forest.','Both olive-brown — not distinguishing.','A flecked stem without a network argues for the edible scarletina bolete; a red network on the stem is a warning signal towards the Devil''s bolete — when in doubt, discard, and thorough cooking is mandatory.','{"The scarletina bolete has NO stem network, but red flecks/dots on a yellow stem; the Devil''s bolete has a distinct red stem network — this is the most important distinguishing feature.","The scarletina bolete blues immediately and intensely to blackish-blue; the Devil''s bolete only weakly.","The scarletina bolete has a brown to dark-brown-brick-red cap; the Devil''s bolete when young has a pale, chalk-white-grey-green cap.","The Devil''s bolete smells of carrion when old; the scarletina bolete smells pleasantly mushroomy.","Both have red pores — the scarletina bolete is edible only when thoroughly cooked (raw toxic), the Devil''s bolete stays toxic."}','f'),
('flockenstieliger_hexenpilz','rubroboletus_satanas','es','Pie con flóculos rojos (SIN retículo) y azulamiento inmediato e intenso a negro-azul en el boleto de pie punteado (Neoboletus erythropus) frente a retículo rojo en el pie y azulamiento débil en el boleto de Satanás.','El boleto de Satanás huele a carroña al envejecer, el boleto de pie punteado huele agradablemente a champiñón.','El boleto de pie punteado crece también en bosques ácidos de coníferas; el boleto de Satanás está estrictamente limitado a bosques cálidos de frondosas sobre suelo calcáreo.','Ambos pardo oliva — no distintivo.','Un pie floculoso sin retículo aboga por el boleto de pie punteado comestible; un retículo rojo en el pie es una señal de alarma hacia el boleto de Satanás — en caso de duda, descartar, y la cocción completa es obligatoria.','{"El boleto de pie punteado NO tiene retículo en el pie, sino flóculos/puntos rojos sobre pie amarillo; el boleto de Satanás tiene un nítido retículo rojo en el pie — este es el criterio distintivo más importante.","El boleto de pie punteado azulea de inmediato e intensamente a negro-azul; el boleto de Satanás solo débilmente.","El boleto de pie punteado tiene sombrero pardo a pardo oscuro-rojo ladrillo; el boleto de Satanás de joven tiene sombrero claro, blanco cal-gris-verde.","El boleto de Satanás huele a carroña al envejecer; el boleto de pie punteado huele agradablemente a champiñón.","Ambos tienen poros rojos — el boleto de pie punteado solo es comestible bien cocido (crudo tóxico), el boleto de Satanás permanece tóxico."}','f'),
('flockenstieliger_hexenpilz','rubroboletus_satanas','fr','Pied à flocons rouges (PAS de réseau) et bleuissement immédiat et intense en noir-bleu chez le bolet à pied rouge (bolet Satan comestible) contre réseau rouge sur le pied et bleuissement faible chez le bolet Satan.','Le bolet Satan sent la charogne en vieillissant, le bolet à pied rouge sent agréablement le champignon.','Le bolet à pied rouge pousse aussi dans les forêts de conifères acides ; le bolet Satan est strictement limité aux forêts de feuillus calcaires et chaudes.','Les deux brun olive — non distinctif.','Un pied floconneux sans réseau plaide pour le bolet à pied rouge comestible ; un réseau rouge sur le pied est un signal d''alarme vers le bolet Satan — en cas de doute, rejeter, et une cuisson complète est obligatoire.','{"Le bolet à pied rouge n''a PAS de réseau sur le pied, mais des flocons/points rouges sur un pied jaune ; le bolet Satan a un net réseau rouge sur le pied — c''est le critère de distinction le plus important.","Le bolet à pied rouge bleuit immédiatement et intensément en noir-bleu ; le bolet Satan seulement faiblement.","Le bolet à pied rouge a un chapeau brun à brun foncé-rouge brique ; le bolet Satan a jeune un chapeau clair, blanc calcaire-gris-vert.","Le bolet Satan sent la charogne en vieillissant ; le bolet à pied rouge sent agréablement le champignon.","Les deux ont des pores rouges — le bolet à pied rouge n''est comestible que bien cuit (cru toxique), le bolet Satan reste toxique."}','f'),
('flockenstieliger_hexenpilz','rubroboletus_satanas','it','Gambo con fioccosità rosse (NESSUN reticolo) e immediato e intenso viraggio al nero-blu nel boleto dal piede rosso (Neoboletus erythropus) contro reticolo rosso sul gambo e viraggio debole nel boleto di Satana.','Il boleto di Satana da vecchio odora di carogna, il boleto dal piede rosso odora gradevolmente di fungo.','Il boleto dal piede rosso cresce anche nei boschi acidi di conifere; il boleto di Satana è strettamente limitato ai boschi caldi di latifoglie su suolo calcareo.','Entrambi bruno oliva — non distintivo.','Un gambo fioccoso senza reticolo depone per il boleto dal piede rosso commestibile; un reticolo rosso sul gambo è un segnale d''allarme verso il boleto di Satana — in caso di dubbio scartare, e la cottura completa è obbligatoria.','{"Il boleto dal piede rosso NON ha reticolo sul gambo, ma fiocchi/punti rossi su gambo giallo; il boleto di Satana ha un netto reticolo rosso sul gambo — questo è il criterio distintivo più importante.","Il boleto dal piede rosso vira subito e intensamente al nero-blu; il boleto di Satana solo debolmente.","Il boleto dal piede rosso ha cappello bruno fino a bruno scuro-rosso mattone; il boleto di Satana da giovane ha cappello chiaro, bianco calce-grigio-verde.","Il boleto di Satana da vecchio odora di carogna; il boleto dal piede rosso odora gradevolmente di fungo.","Entrambi hanno pori rossi — il boleto dal piede rosso è commestibile solo ben cotto (crudo tossico), il boleto di Satana resta tossico."}','f'),
('gymnopus_dryophilus','gymnopus_peronatus','en','The wood woollyfoot looks tougher, leather-brown to yellow-brown, with a distinctly strigose-felted stem base; the russet toughshank is more delicate with a glabrous stem.','Both rather unspecifically mushroomy; the wood woollyfoot often smells vinegary-sour when rubbed and tastes burning-acrid – the acrid taste (sample, spit out) is the decisive distinguishing feature.','Both in hardwood/conifer forest litter, often in troops – habitat does not distinguish; the wood woollyfoot prefers drier litter and appears longer into autumn.','Both with white to cream spore print – not a distinguishing feature.','Small taste test (chew, do NOT swallow, spit out): if after a short time it burns peppery-acrid, it is the suspect wood woollyfoot. Only collect small brown litter mushrooms if you know them unambiguously.','{"Wood woollyfoot: taste acrid-burning peppery (the taste test burns after a short time), stem base strigose-felted white-felted, flesh tough-leathery","Russet toughshank: taste mild, stem glabrous/smooth without strigose base, stem often yellowish-reddish","Wood woollyfoot often in troops in dense hardwood litter, appears longer into autumn; russet toughshank cap hygrophanous red-brown fading","Wood woollyfoot regarded as inedible to mildly poisonous (acrid, stomach-irritating, indications of hydrocyanic compounds) – russet toughshank mildly edible"}','f'),
('gymnopus_dryophilus','gymnopus_peronatus','es','La colibia ardiente parece más tenaz, pardo-cuero a pardo-amarillo, con base del pie marcadamente estrigosa-afieltrada; la colibia de los robles es más delicada con pie glabro.','Ambas de olor fúngico más bien inespecífico; la colibia ardiente huele a menudo al frotarla a vinagre-ácido y sabe ardiente-acre – el sabor acre (prueba, escupir) es el carácter distintivo decisivo.','Ambas en la hojarasca de bosque de frondosas/coníferas, a menudo en grupos – el hábitat no distingue; la colibia ardiente prefiere hojarasca más seca y aparece más tiempo entrado el otoño.','Ambas con esporada de blanca a crema – no es un carácter distintivo.','Pequeña prueba de sabor (masticar, NO tragar, escupir): si tras un breve momento arde a pimienta-acre, es la sospechosa colibia ardiente. Recoger pequeños hongos pardos de hojarasca solo si se conocen inequívocamente.','{"Colibia ardiente: sabor acre-ardiente a pimienta (la prueba de sabor arde tras un breve momento), base del pie estrigosa-afieltrada blanco-afieltrada, carne tenaz-coriácea","Colibia de los robles: sabor suave, pie glabro/liso sin base estrigosa, pie a menudo amarillento-rojizo","Colibia ardiente a menudo en grupos en densa hojarasca de frondosas, aparece más tiempo entrado el otoño; colibia de los robles sombrero higrófano pardo-rojo que se decolora","Colibia ardiente considerada no comestible a levemente tóxica (acre, irritante para el estómago, indicios de compuestos cianhídricos) – colibia de los robles comestible suave"}','f'),
('gymnopus_dryophilus','gymnopus_peronatus','fr','Le collybie à pied feutré paraît plus coriace, brun-cuir à jaune-brun, avec une base du pied nettement strigueuse-feutrée ; le collybie des chênes est plus délicat avec un pied glabre.','Les deux plutôt fongiques non spécifiques ; le collybie à pied feutré sent souvent acide-vinaigré au frottement et a un goût brûlant-âcre – le goût âcre (échantillon, recracher) est le critère de séparation décisif.','Les deux dans la litière de forêt de feuillus/conifères, souvent en troupe – l''habitat ne sépare pas ; le collybie à pied feutré préfère les litières plus sèches et apparaît plus tard dans l''automne.','Les deux à sporée blanche à crème – pas un critère de séparation.','Petit échantillon gustatif (mâcher, NE PAS avaler, recracher) : si après peu de temps cela brûle de façon poivrée-âcre, c''est le collybie à pied feutré suspect de toxicité. Ne récolter les petits champignons bruns de litière que si on les connaît sans équivoque.','{"Collybie à pied feutré : goût âcre-brûlant poivré (l''échantillon gustatif brûle après peu de temps), base du pied strigueuse-feutrée blanc-feutrée, chair coriace-cuir","Collybie des chênes : goût doux, pied glabre/lisse sans base strigueuse, pied souvent jaunâtre-rougeâtre","Collybie à pied feutré souvent en troupe dans une litière de feuillus dense, apparaît plus tard dans l''automne ; chapeau du collybie des chênes hygrophane brun-rouge se décolorant","Collybie à pied feutré considéré comme non comestible à faiblement toxique (âcre, irritant pour l''estomac, indices de composés cyanogènes) – collybie des chênes doux comestible"}','f'),
('gymnopus_dryophilus','gymnopus_peronatus','it','La gymnopus bruciante appare più tenace, bruno-cuoio-bruno-giallo, con base del gambo nettamente strigosa-feltrata; la gymnopus amica dei boschi è più delicata con gambo glabro.','Entrambe d''odore fungino piuttosto aspecifico; la gymnopus bruciante odora spesso allo sfregamento di aceto-acidulo e ha gusto bruciante-acre – il gusto acre (assaggio, sputare) è il carattere distintivo decisivo.','Entrambe nella lettiera di bosco di latifoglie/conifere, spesso in gruppi – l''habitat non distingue; la gymnopus bruciante predilige lettiere più asciutte e compare più a lungo nell''autunno.','Entrambe con sporata da bianca a crema – nessun carattere distintivo.','Piccola prova di assaggio (masticare, NON deglutire, sputare): se dopo poco brucia pepato-acre, è la gymnopus bruciante sospetta. Raccogliere i piccoli funghi bruni di lettiera solo se li si conosce con certezza.','{"Gymnopus bruciante: gusto acre-bruciante pepato (l''assaggio brucia dopo poco), base del gambo strigosa-feltrata bianco-feltrata, carne tenace-coriacea","Gymnopus amica dei boschi: gusto mite, gambo glabro/liscio senza base strigosa, gambo spesso giallastro-rossastro","Gymnopus bruciante spesso in gruppi in fitta lettiera di latifoglie, compare più a lungo nell''autunno; gymnopus amica dei boschi cappello igrofano bruno-rosso che impallidisce","Gymnopus bruciante considerata non commestibile a leggermente tossica (acre, irritante per lo stomaco, indizi di composti cianidrici) – gymnopus amica dei boschi commestibile mite"}','f'),
('hallimasch','cortinarius_orellanus','en','Honey fungus (Hallimasch): honey-yellow with ring, in clusters. Webcap (Raukopf): orange-red-brown, single.','Honey fungus: sourish. Webcap: radish-like.','Honey fungus: tree stumps, roots. Webcap: ground, deciduous forest.','Honey fungus: white. Webcap: rust-brown.','Be especially careful with young mushrooms. Make a spore print.','{"Honey fungus has a ring + grows parasitically on trees, webcap single","Spore powder: honey fungus white, webcap rust-brown"}','t'),
('hallimasch','cortinarius_orellanus','es','Armillaria (hallimasch): amarillo miel con anillo, en grupos cespitosos. Cortinario (Cortinarius orellanus): anaranjado-pardo rojizo, solitario.','Armillaria: agrio. Cortinario: a rábano.','Armillaria: tocones, raíces. Cortinario: suelo, bosque caducifolio.','Armillaria: blanco. Cortinario: pardo herrumbre.','Presta especial atención con los hongos jóvenes. Haz una esporada.','{"Armillaria tiene anillo + es parásita sobre el árbol; el cortinario es solitario","Esporada: Armillaria blanca, cortinario pardo herrumbre"}','t'),
('hallimasch','cortinarius_orellanus','fr','Armillaire (Hallimasch): jaune miel avec un anneau, en touffes. Cortinaire (Raukopf): orange-brun-roux, isolé.','Armillaire: acidulée. Cortinaire: de radis (raphanoïde).','Armillaire: souches d''arbres, racines. Cortinaire: au sol, forêt de feuillus.','Armillaire: blanche. Cortinaire: brun-rouille.','Soyez particulièrement vigilant avec les jeunes champignons. Faites une sporée.','{"L''armillaire a un anneau + est parasite sur l''arbre, le cortinaire (Raukopf) est isolé","Sporée: armillaire blanche, cortinaire brun-rouille"}','t'),
('hallimasch','cortinarius_orellanus','it','Chiodino (Hallimasch): giallo-miele con anello, in fascetti (cespitoso). Cortinarius (Raukopf): da arancione a bruno-rossastro, isolato.','Chiodino (Hallimasch): acidulo. Cortinarius (Raukopf): rafanoide (di ravanello).','Chiodino (Hallimasch): ceppi d''albero, radici. Cortinarius (Raukopf): a terra, bosco di latifoglie.','Chiodino (Hallimasch): bianco. Cortinarius (Raukopf): bruno-ruggine.','Prestare particolare attenzione con i funghi giovani. Eseguire la sporata.','{"Il chiodino (Hallimasch) ha l''anello + parassita sull''albero, il Cortinarius (Raukopf) è isolato","Sporata in massa: chiodino (Hallimasch) bianco, Cortinarius (Raukopf) bruno-ruggine"}','t'),
('hallimasch','gymnopilus_junonius','en','Honey fungus has a honey- to brown-coloured cap with dark scales and a white ring; G. junonius is bright orange rust-yellow with rust-brown gills.','Honey fungus mild-mushroomy in smell; G. junonius mealy-rancid and very bitter in taste.','Both clustered on/around wood and roots; honey fungus parasitic on living trees and stumps, G. junonius on stumps and trunk bases.','Honey fungus: white spore print. G. junonius: rust-brown spore print – this is the decisive distinguishing feature.','Make a spore print: white = possibly edible species (honey fungus only well cooked, raw poisonous!), rust-brown = rustgill = discard. Additionally, taste test: bitter = poisonous.','{"Spore print: honey fungus WHITE to cream, G. junonius rust-brown – the spore print distinguishes reliably.","Gills: honey fungus whitish to pale flesh-pink, decurrent on the stem; G. junonius yellow when young, later rust-brown.","Taste: G. junonius extremely bitter; honey fungus (raw poisonous!) mild to slightly tart, must be thoroughly cooked.","Honey fungus often has dark scales on a pale cap and a white ring; G. junonius uniformly orange rust-yellow."}','f'),
('hallimasch','gymnopilus_junonius','es','La armilaria tiene sombrero de miel a pardo con pequeñas escamas oscuras y un anillo blanco; G. junonius es naranja-amarillo herrumbre brillante con láminas pardo-herrumbre.','La armilaria de olor suave-fúngico; G. junonius harinoso-rancio y muy amargo al gusto.','Ambos en grupos sobre/alrededor de la madera y las raíces; la armilaria parásita de árboles vivos y tocones, G. junonius sobre tocones y bases de troncos.','Armilaria: esporada blanca. G. junonius: esporada pardo-herrumbre – este es el carácter distintivo decisivo.','Hacer una esporada: blanca = especie posiblemente comestible (armilaria solo bien cocinada, ¡cruda tóxica!), pardo-herrumbre = gimnopilo = desechar. Además, prueba de sabor: amargo = tóxico.','{"Esporada: armilaria BLANCA a crema, G. junonius pardo-herrumbre – la esporada distingue con seguridad.","Láminas: armilaria blanquecinas a rosa carne pálido, decurrentes sobre el pie; G. junonius de joven amarillas, luego pardo-herrumbre.","Sabor: G. junonius extremadamente amargo; armilaria (¡cruda tóxica!) suave a ligeramente áspera, debe cocinarse bien.","La armilaria tiene a menudo escamas oscuras sobre sombrero claro y un anillo blanco; G. junonius uniformemente naranja-amarillo herrumbre."}','f'),
('hallimasch','gymnopilus_junonius','fr','Armillaire au chapeau miel à brun avec de petites écailles sombres et un anneau blanc ; G. junonius orange-jaune rouille éclatant avec des lamelles brun rouille.','Armillaire doux-fongique ; G. junonius farineux-rance et très amer au goût.','Les deux en touffes sur/autour du bois et des racines ; armillaire parasite sur arbres vivants et souches, G. junonius sur souches et bases de troncs.','Armillaire : sporée blanche. G. junonius : sporée brun rouille – c''est le critère de séparation décisif.','Faire une sporée : blanche = espèce éventuellement comestible (armillaire seulement bien cuit, cru toxique !), brun rouille = gymnopile = jeter. En plus, test gustatif : amer = toxique.','{"Sporée : armillaire BLANCHE à crème, G. junonius brun rouille – la sporée sépare sûrement.","Lamelles : armillaire blanchâtre à rose-chair pâle, décurrentes au pied ; G. junonius jeune jaune, plus tard brun rouille.","Goût : G. junonius extrêmement amer ; armillaire (cru toxique !) doux à légèrement âpre, doit être bien cuit.","L''armillaire a souvent de petites écailles sombres sur un chapeau clair et un anneau blanc ; G. junonius uniformément orange-jaune rouille."}','f'),
('hallimasch','gymnopilus_junonius','it','Il chiodino ha cappello dal miele al bruno con piccole squame scure e un anello bianco; G. junonius è arancio-giallo ruggine brillante con lamelle bruno-ruggine.','Il chiodino dall''odore mite-fungino; G. junonius farinoso-rancido e molto amaro al gusto.','Entrambi cespitosi su/attorno al legno e alle radici; il chiodino parassita di alberi vivi e ceppi, G. junonius su ceppi e basi dei tronchi.','Chiodino: sporata bianca. G. junonius: sporata bruno-ruggine – è il carattere distintivo decisivo.','Fare una sporata: bianca = specie possibilmente commestibile (chiodino solo ben cotto, crudo tossico!), bruno-ruggine = gimnopilo = da buttare. Inoltre, prova di assaggio: amaro = tossico.','{"Sporata: chiodino BIANCA a crema, G. junonius bruno-ruggine – la sporata distingue con sicurezza.","Lamelle: chiodino biancastre a rosa carne pallido, decorrenti sul gambo; G. junonius da giovani gialle, poi bruno-ruggine.","Gusto: G. junonius estremamente amaro; chiodino (crudo tossico!) mite a leggermente aspro, deve essere ben cotto.","Il chiodino ha spesso squame scure su cappello chiaro e un anello bianco; G. junonius uniformemente arancio-giallo ruggine."}','f'),
('hallimasch','hypholoma_fasciculare','en','The sulphur-yellow-greenish gill tone of the sulphur tuft clearly distinguishes it from the pale flesh-coloured-gilled honey fungus with its finely scaly cap and a true whitish ring.','Only the taste test separates the sulphur tuft: honey fungus mild, sulphur tuft intensely bitter (only chew a sample, never swallow).','Both in clusters on wood/stumps; habitat does not separate them, so gill colour, ring and spore print colour must be checked.','Honey fungus: WHITE spore print; sulphur tuft (green-gilled): dark violet-/purple-brown spore print — a clear, reliable distinguishing feature.','The honey fungus has a true whitish ring and a WHITE spore print — if the true ring is missing or the spore print is dark violet-brown and the taste bitter, it is the sulphur tuft. Always cook honey fungus thoroughly, discard the cooking water.','{"Honey fungus: gills whitish to pale flesh-brown, pale rust-brown with age; sulphur tuft: gills sulphur-yellow-greenish to greenish-black.","Honey fungus: distinct whitish, flocculose-cottony ring on the stem; sulphur tuft: only a fleeting ring zone, no true ring.","Honey fungus: cap with fine dark, mostly wipe-off scales; sulphur tuft: cap smooth, sulphur- to ochre-yellow.","Honey fungus: toxic raw, but edible well-cooked and mild (discard the cooking water); sulphur tuft: bitter and toxic both raw and cooked."}','f'),
('hallimasch','hypholoma_fasciculare','es','El tono de las láminas amarillo azufre-verdoso del hifoloma lo distingue claramente de la armilaria de láminas color carne claro, de sombrero finamente escamoso y con verdadero anillo blanquecino.','Solo la prueba de sabor separa al hifoloma: armilaria suave, hifoloma intensamente amargo (masticar solo una muestra, nunca tragar).','Ambos en grupos sobre madera/tocones; el hábitat no los separa, por ello hay que verificar obligatoriamente el color de las láminas, el anillo y el color de la esporada.','Armilaria: esporada BLANCA; hifoloma en grupos de láminas verdes: esporada pardo-violácea/púrpura oscura — criterio distintivo nítido y seguro.','La armilaria tiene un verdadero anillo blanquecino y esporada BLANCA — si falta el verdadero anillo o la esporada es pardo-violácea oscura y el sabor amargo, es el hifoloma. Cocer siempre bien la armilaria, desechar el agua de cocción.','{"Armilaria: láminas blanquecinas a pardo carne claro, pardo herrumbre claro con la edad; hifoloma: láminas amarillo azufre-verdoso a verde-negruzco.","Armilaria: anillo nítido, blanquecino, flocoso-algodonoso en el pie; hifoloma: solo una fugaz zona anular, ningún verdadero anillo.","Armilaria: sombrero con finas escamitas oscuras, en general eliminables al frotar; hifoloma: sombrero liso, amarillo azufre a amarillo ocre.","Armilaria: tóxica cruda, pero comestible bien cocida y suave (desechar el agua de cocción); hifoloma: amargo y tóxico tanto crudo como cocido."}','f'),
('hallimasch','hypholoma_fasciculare','fr','La teinte des lames jaune soufre-verdâtre de l''hypholome le distingue clairement de l''armillaire couleur chair claire, à chapeau finement squameux et à véritable anneau blanchâtre.','Seul le test gustatif sépare l''hypholome : armillaire doux, hypholome intensément amer (n''en mâcher qu''un échantillon, ne jamais l''avaler).','Les deux en touffes sur bois/souches ; l''habitat ne les sépare pas, il faut donc impérativement vérifier la couleur des lames, l''anneau et la couleur de la sporée.','Armillaire : sporée BLANCHE ; hypholome en touffes à lames vertes : sporée brun violacé/pourpre foncé — critère de distinction net et sûr.','L''armillaire a un véritable anneau blanchâtre et une sporée BLANCHE — si le véritable anneau manque ou si la sporée est brun violacé foncé et le goût amer, c''est l''hypholome. Toujours bien cuire l''armillaire, jeter l''eau de cuisson.','{"Armillaire : lames blanchâtres à brun chair clair, brun rouille clair avec l''âge ; hypholome : lames jaune soufre-verdâtre à vert-noirâtre.","Armillaire : anneau net, blanchâtre, floconneux-cotonneux sur le pied ; hypholome : seulement une zone annulaire fugace, pas de véritable anneau.","Armillaire : chapeau à fines squamules sombres, généralement effaçables ; hypholome : chapeau lisse, jaune soufre à jaune ocre.","Armillaire : toxique cru, mais comestible bien cuit et doux (jeter l''eau de cuisson) ; hypholome : amer et toxique aussi bien cru que cuit."}','f'),
('hallimasch','hypholoma_fasciculare','it','La tonalità delle lamelle giallo zolfo-verdastra del falso chiodino/ipoloma lo distingue chiaramente dal chiodino (armillaria) color carne chiaro, a cappello finemente squamoso e con vero anello biancastro.','Solo la prova del gusto separa l''ipoloma: armillaria mite, ipoloma intensamente amaro (masticare solo un assaggio, non inghiottire mai).','Entrambi a ciuffi su legno/ceppaie; l''habitat non li separa, perciò bisogna verificare obbligatoriamente il colore delle lamelle, l''anello e il colore della sporata.','Armillaria: sporata BIANCA; ipoloma a ciuffi con lamelle verdi: sporata bruno-violacea/porpora scura — criterio distintivo netto e sicuro.','L''armillaria ha un vero anello biancastro e sporata BIANCA — se manca il vero anello o se la sporata è bruno-violacea scura e il sapore amaro, è l''ipoloma. Cuocere sempre bene l''armillaria, gettare l''acqua di cottura.','{"Armillaria: lamelle biancastre a bruno carnicino chiaro, bruno ruggine chiaro con l''età; ipoloma: lamelle giallo zolfo-verdastre a verde-nerastro.","Armillaria: anello netto, biancastro, fioccoso-cotonoso sul gambo; ipoloma: solo una fugace zona anulare, nessun vero anello.","Armillaria: cappello con fini squamette scure, per lo più asportabili; ipoloma: cappello liscio, giallo zolfo a giallo ocra.","Armillaria: tossica cruda, ma commestibile ben cotta e mite (gettare l''acqua di cottura); ipoloma: amaro e tossico sia crudo sia cotto."}','f'),
('hallimasch','pholiota_squarrosa','en','Coarse, spreading, shaggy scales on cap and stem in the shaggy scalycap (shaggy pholiota) instead of the fine, wipe-off, fleeting flecks of the honey fungus.','The shaggy scalycap smells obtrusively of radish/leek, the honey fungus mildly mushroomy.','Both in clusters on hardwood/conifer wood and stumps, same autumn season — the site does NOT serve to distinguish them.','Shaggy scalycap rust-brown spore print, honey fungus white — note the gill colour with age (make a spore print).','Spore print colour decides: rust-brown = never a honey fungus, hands off. Always examine cluster fungi on wood individually, never harvest wholesale as honey fungus. The honey fungus is moreover only edible when thoroughly cooked.','{"Shaggy scalycap: dry, spreading (shaggy), coarse brown scales on cap AND stem; the honey fungus has only fine, fleeting, appressed flecks on the cap.","Spore print: scalycap rust-brown → gills turning brown; honey fungus white → gills staying pale/cream-white.","The honey fungus has a thick, membranous, white ring; the scalycap''s ring is shaggy-fibrous/woolly and indistinct.","The shaggy scalycap smells obtrusively spicy-radish/leek, the honey fungus rather mushroomy-mild.","The scalycap''s taste is bitter/unpleasant (spit out the sample, never swallow raw)."}','f'),
('hallimasch','pholiota_squarrosa','es','Escamas gruesas, erizadas y enmarañadas en el sombrero y el pie en la foliota escamosa, en lugar de los finos flóculos eliminables y fugaces de la armilaria.','La foliota escamosa huele de forma penetrante a rábano/puerro, la armilaria tiene un olor suave a champiñón.','Ambas en grupos sobre madera de frondosas/coníferas y tocones, misma estación otoñal — la estación NO sirve para distinguirlas.','Foliota escamosa esporada pardo herrumbre, armilaria esporada blanca — observar el color de las láminas con la edad (hacer una esporada).','El color de la esporada decide: pardo herrumbre = nunca una armilaria, no tocar. Examinar siempre individualmente los hongos en grupos sobre madera, nunca recolectar en bloque como armilaria. La armilaria además solo es comestible bien cocida.','{"Foliota escamosa: escamas pardas secas, erizadas (enmarañadas), gruesas en el sombrero Y el pie; la armilaria solo tiene finos flóculos fugaces, adheridos, en el sombrero.","Esporada: foliota pardo herrumbre → láminas que pardean; armilaria blanca → láminas que permanecen claras/blanco crema.","La armilaria tiene un anillo grueso, membranoso, blanco; el anillo de la foliota es erizado-fibroso/lanoso e indistinto.","La foliota escamosa huele de forma penetrante especiada-rábano/puerro, la armilaria más bien suave-champiñón.","El sabor de la foliota es amargo/desagradable (escupir la muestra, nunca tragar cruda)."}','f'),
('hallimasch','pholiota_squarrosa','fr','Des écailles grossières, dressées et hérissées sur le chapeau et le pied chez la pholiote écailleuse, au lieu des fines flocons effaçables et fugaces de l''armillaire.','La pholiote écailleuse a une odeur envahissante de radis/poireau, l''armillaire une odeur douce de champignon.','Les deux en touffes sur bois de feuillus/conifères et souches, même saison d''automne — la station NE permet PAS de les distinguer.','Pholiote écailleuse sporée brun rouille, armillaire sporée blanche — observer la couleur des lames avec l''âge (faire une sporée).','La couleur de la sporée décide : brun rouille = jamais une armillaire, ne pas y toucher. Toujours examiner individuellement les champignons en touffes sur bois, ne jamais récolter en bloc comme armillaire. L''armillaire n''est en outre comestible que bien cuite.','{"Pholiote écailleuse : écailles brunes sèches, dressées (hérissées), grossières sur le chapeau ET le pied ; l''armillaire n''a que de fines flocons fugaces, appliqués, sur le chapeau.","Sporée : pholiote brun rouille → lames brunissant ; armillaire blanche → lames restant claires/blanc crème.","L''armillaire a un anneau épais, membraneux, blanc ; l''anneau de la pholiote est hérissé-fibreux/laineux et indistinct.","La pholiote écailleuse a une odeur envahissante épicée-radis/poireau, l''armillaire plutôt douce-champignon.","Goût de la pholiote amer/désagréable (recracher l''échantillon, ne jamais avaler cru)."}','f'),
('hallimasch','pholiota_squarrosa','it','Squame grossolane, sporgenti e irte sul cappello e sul gambo nella foliota squarrosa, al posto dei fini fiocchi asportabili e fugaci dell''armillaria.','La foliota squarrosa odora in modo invadente di ravanello/porro, l''armillaria ha un mite odore di fungo.','Entrambe a ciuffi su legno di latifoglie/conifere e ceppaie, stessa stagione autunnale — la stazione NON serve a distinguerle.','Foliota squarrosa sporata bruno ruggine, armillaria sporata bianca — osservare il colore delle lamelle con l''età (fare la sporata).','Il colore della sporata decide: bruno ruggine = mai un''armillaria, non toccare. Esaminare sempre singolarmente i funghi a ciuffi su legno, non raccogliere mai in blocco come armillaria. L''armillaria inoltre è commestibile solo ben cotta.','{"Foliota squarrosa: squame brune secche, sporgenti (irte), grossolane sul cappello E sul gambo; l''armillaria ha solo fini fiocchi fugaci, aderenti, sul cappello.","Sporata: foliota bruno ruggine → lamelle che imbruniscono; armillaria bianca → lamelle che restano chiare/bianco crema.","L''armillaria ha un anello spesso, membranoso, bianco; l''anello della foliota è irto-fibroso/lanoso e indistinto.","La foliota squarrosa odora in modo invadente speziato-ravanello/porro, l''armillaria piuttosto mite-fungina.","Sapore della foliota amaro/sgradevole (sputare l''assaggio, non inghiottire mai crudo)."}','f'),
('hypholoma_capnoides','hypholoma_lateritium','en','Edible conifer tuft with grey/grey-blue gills and a honey-ochre cap; brick tuft (brick cap) with olive-grey to olive-grey-brown gills and a brick-red cap centre. Caution: greenish-yellow gills mean the deadly sulphur tuft with green gills, not the brick tuft.','Both mushroomy-mild in smell; the brick tuft, however, tastes distinctly bitter (sample, spit out).','Conifer tuft on conifer stumps, brick tuft predominantly on hardwood (beech, oak).','In both purple-brown to violet-brown — unsuitable as a distinguishing feature.','Never identify tufts without a taste test (spit out): bitter = leave it. Conifer substrate + mild taste argue for the edible conifer tuft. Greenish-yellow gills indicate the deadly sulphur tuft with green gills.','{"Conifer tuft (edible) has grey to grey-blue gills; the brick tuft has olive-grey to olive-grey-brown gills (NOT greenish-yellow — that would be the deadly-poisonous sulphur tuft with green gills, Hypholoma fasciculare)","Cap colour of the edible one lighter, honey-yellow to ochre-brown; in the brick tuft brick-red with a lighter margin","Taste of the edible one mild, the brick tuft bitter","Conifer tuft grows on conifers (spruce/pine), brick tuft prefers hardwood (beech/oak)","Spore print in both purple-brown — not a distinguishing feature; therefore pay attention to gill hue, substrate and taste"}','f'),
('hypholoma_capnoides','hypholoma_lateritium','es','Hifoloma comestible con láminas grises/gris-azuladas y sombrero miel-ocre; hifoloma color ladrillo con láminas gris-oliva a gris-pardo oliváceo y centro del sombrero color ladrillo. Atención: láminas verde-amarillentas significan el hifoloma de láminas verdes mortal, no el hifoloma color ladrillo.','Ambos de olor fúngico-suave; el hifoloma color ladrillo, sin embargo, sabe claramente amargo (prueba, escupir).','Hifoloma de láminas grises sobre tocones de coníferas, hifoloma color ladrillo predominantemente sobre madera de frondosas (haya, roble).','En ambos púrpura-pardo a pardo-violáceo — inadecuado como carácter distintivo.','Nunca determinar los hifolomas sin prueba de sabor (escupir): amargo = dejarlo. Sustrato de coníferas + sabor suave hablan a favor del hifoloma de láminas grises comestible. Láminas verde-amarillentas indican el hifoloma de láminas verdes mortal.','{"El hifoloma de láminas grises (comestible) tiene láminas grises a gris-azuladas; el hifoloma color ladrillo tiene láminas gris-oliva a gris-pardo oliváceo (NO verde-amarillentas — eso sería el hifoloma de láminas verdes mortalmente tóxico, Hypholoma fasciculare)","Color del sombrero del comestible más claro, amarillo miel a pardo ocre; en el hifoloma color ladrillo color ladrillo con margen más claro","Sabor del comestible suave, el hifoloma color ladrillo amargo","El hifoloma de láminas grises crece sobre coníferas (abeto rojo/pino), el hifoloma color ladrillo prefiere la madera de frondosas (haya/roble)","Esporada en ambos púrpura-pardo — no es un carácter distintivo; por eso prestar atención al matiz de las láminas, al sustrato y al sabor"}','f'),
('hypholoma_capnoides','hypholoma_lateritium','fr','Hypholome comestible à lames couleur de fumée avec des lamelles gris/gris-bleu et un chapeau miel-ocre ; hypholome couleur de brique avec des lamelles olive-gris à olive-gris-brun et un centre du chapeau couleur de brique. Attention : des lamelles vert-jaunâtre signifient l''hypholome en touffes mortel, pas l''hypholome couleur de brique.','Les deux fongiques-doux à l''odeur ; l''hypholome couleur de brique a cependant un goût nettement amer (échantillon gustatif à recracher).','Hypholome à lames couleur de fumée sur souches de conifères, hypholome couleur de brique surtout sur bois de feuillus (hêtre, chêne).','Chez les deux brun pourpre à brun violet — non adapté comme critère de séparation.','Ne jamais déterminer les hypholomes sans échantillon gustatif (à recracher) : amer = laisser sur place. Substrat bois de conifères + goût doux plaident pour l''hypholome à lames couleur de fumée comestible. En cas de lamelles vert-jaunâtre, il s''agit de l''hypholome en touffes mortel.','{"Hypholome à lames couleur de fumée (comestible) a des lamelles grises à gris-bleu ; l''hypholome couleur de brique a des lamelles gris-olive à olive-gris-brun (PAS vert-jaunâtre — ce serait l''hypholome en touffes mortellement toxique, Hypholoma fasciculare)","Couleur du chapeau du comestible plus claire miel-jaune à brun-ocre, chez l''hypholome couleur de brique couleur de brique avec un bord plus clair","Goût du comestible doux, l''hypholome couleur de brique amer","Hypholome à lames couleur de fumée pousse sur bois de conifères (épicéa/pin), hypholome couleur de brique préfère le bois de feuillus (hêtre/chêne)","Sporée chez les deux brun pourpre — pas un critère distinctif ; donc faire attention à la nuance des lamelles, au substrat et au goût"}','f'),
('hypholoma_capnoides','hypholoma_lateritium','it','Ipoloma commestibile con lamelle grigie/grigio-blu e cappello miele-ocra; ipoloma color mattone con lamelle grigio-oliva a grigio-bruno olivastro e centro del cappello color mattone. Attenzione: lamelle verde-giallastre indicano l''ipoloma fascicolare mortale a lamelle verdi, non l''ipoloma color mattone.','Entrambi d''odore fungino-mite; l''ipoloma color mattone ha però un gusto nettamente amaro (assaggio da sputare).','Ipoloma a lamelle grigie su ceppi di conifere, ipoloma color mattone prevalentemente su legno di latifoglie (faggio, quercia).','In entrambi porpora-bruno a bruno-violaceo — inadatto come carattere distintivo.','Non determinare mai gli ipolomi senza prova di assaggio (sputare): amaro = da lasciare. Substrato di conifere + gusto mite parlano per l''ipoloma a lamelle grigie commestibile. Lamelle verde-giallastre indicano l''ipoloma fascicolare mortale a lamelle verdi.','{"L''ipoloma a lamelle grigie (commestibile) ha lamelle grigie a grigio-blu; l''ipoloma color mattone ha lamelle grigio-oliva a grigio-bruno olivastro (NON verde-giallastre — sarebbe l''ipoloma fascicolare mortalmente tossico a lamelle verdi, Hypholoma fasciculare)","Colore del cappello del commestibile più chiaro, giallo miele a bruno ocra, nell''ipoloma color mattone color mattone con margine più chiaro","Gusto del commestibile mite, l''ipoloma color mattone amaro","L''ipoloma a lamelle grigie cresce su conifere (abete rosso/pino), l''ipoloma color mattone predilige il legno di latifoglie (faggio/quercia)","Sporata in entrambi porpora-bruno — nessun carattere distintivo; quindi fare attenzione alla tonalità delle lamelle, al substrato e al gusto"}','f'),
('infundibulicybe_geotropa','ampulloclitocybe_clavipes','en','The large trooping funnel is cream-white to ochre with a central umbo and a firm stem vs. the small clavipes, white-grey to grey-brown with a soft clavate base.','The trooping funnel smells pleasantly spicy-sweet; clavipes faintly fruity.','The trooping funnel in fairy rings on grassy sites/woodland edges; clavipes in mixed and coniferous forest.','Both with white to cream spore print; not distinguishing.','With small, soft funnels with a spongy-clavate stem, as a rule keep your hands off and never combine with alcohol.','{"The trooping funnel is much larger and more robust (cap up to about 20 cm) with firm-tough, dry flesh and a firm, NON-spongy stem; clavipes small with a soft, watery-spongy clavate stem base.","The trooping funnel has a typically central flat umbo in an otherwise depressed cap and cream-white to ochre colouring; clavipes white-grey to grey-brown with a darker centre.","The trooping funnel grows mostly in large fairy rings/rows at woodland edges and grassy sites; clavipes rather scattered in the forest.","Clavipes is poisonous with alcohol (coprine syndrome); the trooping funnel is a good edible when cooked."}','f'),
('infundibulicybe_geotropa','ampulloclitocybe_clavipes','es','El gran platera blanco-crema a ocre con mamelón central y pie firme vs. el pequeño clavipes blanco-gris a gris-pardo con base claviforme blanda.','La platera huele agradablemente especiada-dulzona; el clavipes débilmente afrutado.','La platera en corros de brujas sobre lugares herbosos/bordes de bosque; el clavipes en bosque mixto y de coníferas.','Ambos con esporada de blanca a crema; no distintivo.','Ante pequeños clitocibes blandos con pie esponjoso-claviforme, por principio no tocar y nunca combinar con alcohol.','{"La platera es mucho más grande y robusta (sombrero hasta unos 20 cm) con carne firme-tenaz, seca, y pie firme, NO esponjoso; el clavipes pequeño con base del pie claviforme blanda, acuosa-esponjosa.","La platera tiene un mamelón central típicamente plano en un sombrero por lo demás deprimido y coloración blanco-crema a ocre; el clavipes blanco-gris a gris-pardo con centro más oscuro.","La platera crece en su mayoría en grandes corros de brujas/hileras en bordes de bosque y lugares herbosos; el clavipes más bien disperso en el bosque.","El clavipes es tóxico con alcohol (síndrome coprínico); la platera es un buen comestible una vez cocinada."}','f'),
('infundibulicybe_geotropa','ampulloclitocybe_clavipes','fr','Grand clitocybe géotrope crème-blanc-ocré avec un mamelon central et un pied ferme vs. petit clavipes blanc-gris à gris-brun avec une base molle en massue.','Clitocybe géotrope agréablement épicé-sucré ; clavipes faiblement fruité.','Clitocybe géotrope en ronds de sorcières sur stations herbeuses/lisières de forêt ; clavipes en forêt mixte et de conifères.','Les deux à sporée blanche à crème ; non discriminant.','Pour les petits clitocybes mous à pied spongieux en massue, par principe ne pas toucher et ne jamais combiner avec de l''alcool.','{"Le clitocybe géotrope est bien plus grand et robuste (chapeau jusqu''à env. 20 cm) avec une chair ferme-coriace, sèche, et un pied ferme, NON spongieux ; clavipes petit avec une base du pied molle, aqueuse-spongieuse, en massue.","Le clitocybe géotrope a un mamelon central typique, plat, dans un chapeau par ailleurs déprimé et une coloration crème-blanc-ocré ; clavipes blanc-gris à gris-brun avec un centre plus sombre.","Le clitocybe géotrope pousse le plus souvent en grands ronds de sorcières/rangées aux lisières de forêt et stations herbeuses ; clavipes plutôt dispersé en forêt.","clavipes toxique avec l''alcool (syndrome coprinien) ; le clitocybe géotrope cuit est un bon comestible."}','f'),
('infundibulicybe_geotropa','ampulloclitocybe_clavipes','it','Il grande clitocybe geotropo bianco-crema-ocra con umbone centrale e gambo sodo vs. il piccolo clavipes bianco-grigio a grigio-bruno con base clavata molle.','Il clitocybe geotropo profuma gradevolmente speziato-dolciastro; il clavipes debolmente fruttato.','Il clitocybe geotropo in cerchi delle streghe su stazioni erbose/margini boschivi; il clavipes in bosco misto e di conifere.','Entrambi con sporata da bianca a crema; non distintivo.','Di fronte ai piccoli clitocybe molli con gambo spugnoso-clavato, per principio non toccare e mai combinare con l''alcol.','{"Il clitocybe geotropo è molto più grande e robusto (cappello fino a circa 20 cm) con carne soda-tenace, asciutta, e gambo sodo, NON spugnoso; il clavipes piccolo con base del gambo clavata molle, acquosa-spugnosa.","Il clitocybe geotropo ha un umbone centrale tipicamente piatto in un cappello per il resto depresso e colorazione bianco-crema-ocra; il clavipes bianco-grigio a grigio-bruno con centro più scuro.","Il clitocybe geotropo cresce per lo più in grandi cerchi delle streghe/file ai margini boschivi e su stazioni erbose; il clavipes piuttosto sparso nel bosco.","Il clavipes è tossico con l''alcol (sindrome coprinica); il clitocybe geotropo è un buon commestibile da cotto."}','f'),
('infundibulicybe_geotropa','clitocybe_dealbata','en','Trooping Funnel (Monk''s Head): 12-25 cm, cream/buff-coloured to reddish-ochre with age, central palpable umbo, robust club-shaped stem. Ivory Funnel (Sweating Mushroom): only 2-5 cm, chalk-white pruinose, depressed/flat without an umbo, thin slender stem.','Trooping Funnel smells aromatically sweetish with a distinct bitter-almond note; Ivory Funnel is insignificant to faintly mealy. Caution: smell is a SUPPORTING feature, never the sole safety criterion - always combine it with size/umbo/flesh thickness.','Ivory Funnel: open grassland, meadows, pastures, lawns, path edges, parks. Trooping Funnel: deciduous and coniferous forest, forest edges, forest meadows on moist calcareous soil. Both can form fairy rings - the habitat type (forest vs. open grass) is more relevant than the ring growth.','Both WHITE - the spore print does NOT help to distinguish here. Separation is made via size, flesh thickness, cap umbo and stem thickness.','Golden rule: NEVER eat SMALL white funnel caps (under about 6 cm, thin-fleshed, without a palpable cap umbo) - they contain muscarine and are dangerously confusable as a group. Take only the large (12-25 cm), thick-fleshed Trooping Funnel with a clearly palpable central cap umbo and a robust stem. Fairy rings and white spore print are present in BOTH - they are NOT useful for distinguishing.','{"Size/flesh: Ivory Funnel only 2-5 cm cap, thin-fleshed (a few mm); Trooping Funnel 12-25 cm, thick-fleshed and with a clearly palpable central umbo/bump in the centre of the cap (finger test) - the umbo is always absent in the Ivory Funnel.","Both white/cream-coloured & funnel-shaped with decurrent gills and WHITE spore print - the cap colour and spore print do NOT help, only size + flesh thickness + umbo + habitat separate them reliably.","Habitat/season: Ivory Funnel on meadows, pastures, path edges, lawns, parks (early summer-late autumn, often in fairy rings); Trooping Funnel in deciduous/coniferous forest, at forest edges and on forest meadows on moist calcareous soil (late summer-autumn, likewise fairy rings - habitat alone is NOT sufficient).","Stem: Trooping Funnel has a robust, often club-thickened stem (2-4 cm thick, 8-15 cm long); Ivory Funnel slender and thin."}','t'),
('infundibulicybe_geotropa','clitocybe_dealbata','es','Cabeza de monje (Mönchskopf): 12-25 cm, color crema/cuero hasta ocre-rojizo en la vejez, mamelón central palpable, pie robusto-claviforme. Clitocybe de los campos (Feldtrichterling): solo 2-5 cm, blanco tiza pruinoso, deprimido/plano sin mamelón, pie delgado y delicado.','La cabeza de monje huele aromática y dulzona con una clara nota de almendra amarga; el clitocybe de los campos insignificante a débilmente harinoso. Atención: el olor es un carácter DE APOYO, nunca el único criterio de seguridad - combinar siempre con el tamaño/mamelón/grosor de la carne.','Clitocybe de los campos: pastizal abierto, prados, pastos, céspedes, bordes de caminos, parques. Cabeza de monje: bosque de frondosas y coníferas, lindes de bosque, claros de bosque sobre suelo calcáreo húmedo. Ambos pueden formar corros de brujas - el tipo de localización (bosque frente a hierba abierta) es más relevante que el crecimiento en corros.','Ambos BLANCO - el polvo de esporas NO ayuda aquí a distinguirlos. La separación se realiza por el tamaño, el grosor de la carne, el mamelón del sombrero y el grosor del pie.','Regla de oro: los clitocybes blancos PEQUEÑOS (de menos de aprox. 6 cm, de carne delgada, sin mamelón palpable en el sombrero) NUNCA comerlos - contienen muscarina y como grupo son confundibles de forma potencialmente mortal. Tomar únicamente la cabeza de monje grande (12-25 cm), de carne gruesa, con un mamelón central claramente palpable en el sombrero y pie robusto. Los corros de brujas y el polvo de esporas blanco los tienen AMBOS - NO sirven para distinguirlos.','{"Tamaño/carne: el clitocybe de los campos solo 2-5 cm de sombrero, de carne delgada (pocos mm); la cabeza de monje 12-25 cm, de carne gruesa y con un mamelón/verruga central claramente palpable en el centro del sombrero (prueba del dedo) - el mamelón le falta siempre al clitocybe de los campos.","Ambos blanco/cremosos e infundibuliformes con láminas decurrentes y polvo de esporas BLANCO - el color del sombrero y el polvo de esporas NO ayudan, solo el tamaño + el grosor de la carne + el mamelón + la localización los separan con seguridad.","Localización/temporada: el clitocybe de los campos en prados, pastos, bordes de caminos, céspedes, parques (de principios de verano a finales de otoño, a menudo en corros de brujas); la cabeza de monje en bosque de frondosas/coníferas, en lindes de bosque y en claros de bosque sobre suelo calcáreo húmedo (de finales de verano a otoño, también corros de brujas - la localización por sí sola NO basta).","Pie: la cabeza de monje tiene un pie robusto, a menudo claviformemente engrosado (2-4 cm de grosor, 8-15 cm de largo); el clitocybe de los campos delicado y delgado."}','t'),
('infundibulicybe_geotropa','clitocybe_dealbata','fr','Tête-de-moine (Infundibulicybe geotropa) : 12-25 cm, crème/couleur cuir à ocre-rougeâtre avec l''âge, mamelon central perceptible au toucher, pied robuste et clavé. Clitocybe blanchi des champs (Clitocybe dealbata) : seulement 2-5 cm, blanc craie pruineux, déprimé/aplati sans mamelon, pied mince et grêle.','La Tête-de-moine dégage une odeur aromatique douceâtre avec une nette note d''amande amère ; le Clitocybe blanchi des champs est insignifiant à faiblement farineux. Attention : l''odeur est un caractère COMPLÉMENTAIRE, jamais le seul critère de sécurité — toujours le combiner avec la taille/le mamelon/l''épaisseur de la chair.','Clitocybe blanchi des champs : prairies ouvertes, prés, pâturages, pelouses, bords de chemins, parcs. Tête-de-moine : forêts de feuillus et de conifères, lisières de forêt, clairières herbeuses sur sol calcaire humide. Les deux peuvent former des ronds de sorcière — le type de station (forêt vs herbe ouverte) est plus pertinent que la croissance en ronds.','Les deux BLANC — la sporée n''aide PAS ici à les distinguer. La distinction se fait par la taille, l''épaisseur de la chair, le mamelon du chapeau et l''épaisseur du pied.','Règle d''or : les PETITS clitocybes blancs (moins d''environ 6 cm, à chair mince, sans mamelon perceptible au toucher) ne JAMAIS les manger — ils contiennent de la muscarine et, en tant que groupe, sont confusibles de manière mortelle. Ne prendre que la grande Tête-de-moine (12-25 cm), à chair épaisse, avec un mamelon central nettement perceptible au toucher et un pied robuste. Ronds de sorcière et sporée blanche : les DEUX les présentent — ils ne servent PAS à les distinguer.','{"Taille/chair : le Clitocybe blanchi des champs n''a que 2-5 cm de chapeau, chair mince (quelques mm) ; la Tête-de-moine 12-25 cm, à chair épaisse et avec un mamelon/une verrue central nettement perceptible au toucher au centre du chapeau (test au doigt) — ce mamelon manque toujours au Clitocybe blanchi des champs.","Tous deux blancs/crème & en entonnoir avec des lamelles décurrentes et une sporée BLANCHE — la couleur du chapeau et la sporée n''aident PAS, seuls la taille + l''épaisseur de la chair + le mamelon + la station les séparent avec certitude.","Station/saison : le Clitocybe blanchi des champs dans les prés, pâturages, bords de chemins, pelouses, parcs (début d''été à fin d''automne, souvent en ronds de sorcière) ; la Tête-de-moine en forêt de feuillus/conifères, en lisière de forêt et dans les clairières herbeuses sur sol calcaire humide (fin d''été à automne, également en ronds de sorcière — la station seule ne SUFFIT PAS).","Pied : la Tête-de-moine a un pied robuste, souvent clavé et épaissi (2-4 cm d''épaisseur, 8-15 cm de long) ; le Clitocybe blanchi des champs grêle et mince."}','t'),
('infundibulicybe_geotropa','clitocybe_dealbata','it','Infundibulicybe geotropa: 12-25 cm, crema/color cuoio fino a ocra-rossastro con l''età, umbone centrale percepibile al tatto, gambo robusto-clavato. Clitocybe dealbata: solo 2-5 cm, bianco-gesso pruinosa, depressa/piana senza umbone, gambo sottile e gracile.','L''Infundibulicybe geotropa odora aromatico e dolciastro con netta nota di mandorla amara; la Clitocybe dealbata insignificante fino a debolmente farinoso. Attenzione: l''odore è un carattere DI SUPPORTO, mai l''unico criterio di sicurezza - combinarlo sempre con dimensione/umbone/spessore della carne.','Clitocybe dealbata: prateria aperta, prati, pascoli, tappeti erbosi, bordi dei sentieri, parchi. Infundibulicybe geotropa: bosco di latifoglie e conifere, margini boschivi, radure boschive su suolo calcareo umido. Entrambi possono formare cerchi delle streghe - il tipo di stazione (bosco vs. erba aperta) è più rilevante della crescita in cerchi.','Entrambi BIANCO - il polverino sporale qui NON aiuta nella distinzione. La separazione avviene tramite dimensione, spessore della carne, umbone del cappello e spessore del gambo.','Regola d''oro: i PICCOLI imbutini bianchi (sotto ca. 6 cm, a carne sottile, senza umbone percepibile) MAI mangiarli - contengono muscarina e come gruppo sono pericolosamente confondibili in modo letale. Prendere solo il grande (12-25 cm) Infundibulicybe geotropa a carne spessa, con umbone centrale chiaramente percepibile al tatto e gambo robusto. Cerchi delle streghe e polverino sporale bianco li hanno ENTRAMBI - NON servono alla distinzione.','{"Dimensione/carne: la Clitocybe dealbata solo 2-5 cm di cappello, a carne sottile (pochi mm); l''Infundibulicybe geotropa 12-25 cm, a carne spessa e con umbone/verruca centrale nettamente percepibile al tatto al centro del cappello (test con le dita) - l''umbone manca sempre alla Clitocybe dealbata.","Entrambi bianchi/color crema e imbutiformi con lamelle decorrenti e polverino sporale BIANCO - il colore del cappello e il polverino sporale NON aiutano, solo dimensione + spessore della carne + umbone + stazione separano con sicurezza.","Stazione/stagione: la Clitocybe dealbata su prati, pascoli, bordi dei sentieri, tappeti erbosi, parchi (inizio estate-tardo autunno, spesso in cerchi delle streghe); l''Infundibulicybe geotropa nel bosco di latifoglie/conifere, ai margini boschivi e nelle radure boschive su suolo calcareo umido (tardo estate-autunno, anch''esso cerchi delle streghe - la stazione da sola NON basta).","Gambo: l''Infundibulicybe geotropa ha gambo robusto, spesso ingrossato a clava (2-4 cm di spessore, 8-15 cm di lunghezza); la Clitocybe dealbata gracile e sottile."}','t'),
('infundibulicybe_geotropa','clitocybe_rivulosa','en','Fool''s Funnel (Frosty Funnel): up to 4-5 cm, chalk-white pruinose, depressed without an umbo, thin stem. Trooping Funnel (Monk''s Head): 12-25 cm, cream/buff-coloured, with a central umbo, thick club-shaped stem.','Trooping Funnel aromatically sweetish with a bitter-almond note; Fool''s Funnel inconspicuous to faint. Use smell only as an additional feature, never alone.','Fool''s Funnel: lawns, meadows, path edges, dunes, embankments, parks (in the grass, in troops/fairy rings). Trooping Funnel: deciduous/coniferous forest on calcareous soil, forest edges, forest meadows. Forest vs. open grassland is the relevant location criterion.','Both WHITE - no distinction via spore colour possible; size + flesh thickness + habitat + umbo decide.','Every small, chalk-white pruinose funnel cap in the grass/lawn is muscarine-suspect - if in doubt, leave it standing. The Trooping Funnel is large (12-25 cm), thick-fleshed, forest-bound and has a palpable central umbo - not the dainty small white meadow mushroom. White spore powder does NOT rule out the poisonous funnel cap, since it too produces a white spore print.','{"Size: Fool''s Funnel only up to approx. 4-5 cm cap, chalk-white pruinose, depressed/indented without an umbo; Trooping Funnel 12-25 cm, thick-fleshed, with a clearly palpable central umbo.","Both whitish-funnel-shaped with decurrent gills and WHITE spore print - only size, flesh thickness and cap umbo separate them reliably, colour and spore print do NOT.","Highly toxic due to muscarine (muscarine syndrome: heavy salivation/sweating/lacrimation within 15-30 min, in severe cases circulatory collapse), often on the same meadow/path-edge/dune locations in troops or fairy rings.","Stem dainty/thin in the poisonous funnel cap vs. robust-club-shaped (2-4 cm thick) in the Trooping Funnel."}','t'),
('infundibulicybe_geotropa','clitocybe_rivulosa','es','Clitocybe acanalado y pruinoso (Rinnigbereifter Trichterling): hasta 4-5 cm, blanco tiza pruinoso, deprimido sin mamelón, pie delgado. Cabeza de monje (Mönchskopf): 12-25 cm, crema/pardo cuero, con mamelón central, pie grueso y claviforme.','La cabeza de monje es aromática y dulzona con una nota de almendra amarga; el clitocybe acanalado y pruinoso es inconspicuo a débil. Utilizar el olor solo como carácter complementario, nunca de forma aislada.','Clitocybe acanalado y pruinoso: céspedes, prados, bordes de caminos, dunas, taludes, parques (en la hierba, en grupos/corros de brujas). Cabeza de monje: bosque de frondosas/coníferas sobre suelo calcáreo, lindes de bosque, claros de bosque. Bosque frente a pastizal abierto es el criterio de localización relevante.','Ambos BLANCO - no es posible distinguirlos por el color de las esporas; deciden el tamaño + el grosor de la carne + la localización + el mamelón.','Cualquier clitocybe pequeño, blanco tiza y pruinoso en la hierba/césped es sospechoso de muscarina - en caso de sospecha, dejarlo. La cabeza de monje es grande (12-25 cm), de carne gruesa, ligada al bosque y tiene un mamelón central palpable - no es la delicada y pequeña seta blanca de prado. Un polvo de esporas blanco NO descarta el clitocybe venenoso, ya que este también esporula en blanco.','{"Tamaño: el clitocybe acanalado y pruinoso solo hasta aprox. 4-5 cm de sombrero, blanco tiza pruinoso, deprimido/hundido sin mamelón; la cabeza de monje 12-25 cm, de carne gruesa, con un mamelón central claramente palpable.","Ambos blanquecino-infundibuliformes con láminas decurrentes y polvo de esporas BLANCO - solo el tamaño, el grosor de la carne y el mamelón del sombrero los separan con seguridad, el color y el polvo de esporas NO.","Muy venenoso por muscarina (síndrome muscarínico: fuerte salivación/sudoración/lagrimeo en 15-30 min, en casos graves colapso circulatorio), a menudo en las mismas localizaciones de prados/bordes de caminos/dunas en grupos o corros de brujas.","Pie delicado/delgado en el clitocybe venenoso frente a robusto-claviforme (2-4 cm de grosor) en la cabeza de monje."}','t'),
('infundibulicybe_geotropa','clitocybe_rivulosa','fr','Clitocybe rivulé (Clitocybe rivulosa) : jusqu''à 4-5 cm, blanc craie pruineux, déprimé sans mamelon, pied mince. Tête-de-moine : 12-25 cm, crème/couleur cuir, avec un mamelon central, pied épais et clavé.','La Tête-de-moine aromatique douceâtre avec une note d''amande amère ; le Clitocybe rivulé discret à faible. N''utiliser l''odeur que comme caractère complémentaire, jamais seule.','Clitocybe rivulé : gazons, prairies, bords de chemins, dunes, talus, parcs (dans l''herbe, en troupes/ronds de sorcière). Tête-de-moine : forêt de feuillus/conifères sur sol calcaire, lisières de forêt, clairières herbeuses. Forêt vs herbage ouvert est le critère de station pertinent.','Les deux BLANC — aucune distinction possible par la couleur de la sporée ; taille + épaisseur de la chair + station + mamelon décident.','Tout petit clitocybe pruineux blanc craie dans l''herbe/le gazon est suspect de muscarine — en cas de doute, le laisser sur place. La Tête-de-moine est grande (12-25 cm), à chair épaisse, liée à la forêt et présente un mamelon central perceptible au toucher — ce n''est pas le gracile petit champignon blanc des prairies. Une sporée blanche n''EXCLUT PAS le clitocybe toxique, car lui aussi a une sporée blanche.','{"Taille : le Clitocybe rivulé seulement jusqu''à env. 4-5 cm de chapeau, blanc craie pruineux, déprimé/creusé sans mamelon ; la Tête-de-moine 12-25 cm, à chair épaisse, avec un mamelon central nettement perceptible au toucher.","Tous deux blanchâtres-en entonnoir avec des lamelles décurrentes et une sporée BLANCHE — seules la taille, l''épaisseur de la chair et le mamelon du chapeau les séparent avec certitude, la couleur et la sporée NON.","Très toxique par la muscarine (syndrome muscarinien : forte salivation/transpiration/larmoiement en 15-30 min, dans les cas graves collapsus circulatoire), souvent dans les mêmes stations de prairies/bords de chemins/dunes, en troupes ou en ronds de sorcière.","Pied grêle/mince chez le clitocybe toxique vs robuste-clavé (2-4 cm d''épaisseur) chez la Tête-de-moine."}','t'),
('infundibulicybe_geotropa','clitocybe_rivulosa','it','Clitocybe rivulosa: fino a 4-5 cm, bianco-gesso pruinoso, depresso senza umbone, gambo sottile. Infundibulicybe geotropa: 12-25 cm, crema/bruno-cuoio, con umbone centrale, gambo spesso e clavato.','L''Infundibulicybe geotropa aromatico e dolciastro con nota di mandorla amara; la Clitocybe rivulosa inappariscente fino a debole. Usare l''odore solo come carattere accessorio, mai da solo.','Clitocybe rivulosa: tappeti erbosi, prati, bordi dei sentieri, dune, scarpate, parchi (nell''erba, in gruppi/cerchi delle streghe). Infundibulicybe geotropa: bosco di latifoglie/conifere su suolo calcareo, margini boschivi, radure boschive. Bosco vs. prateria aperta è il criterio di stazione rilevante.','Entrambi BIANCO - nessuna distinzione possibile tramite il colore delle spore; decidono dimensione + spessore della carne + stazione + umbone.','Ogni piccolo imbutino bianco-gesso pruinoso nell''erba/prato è sospetto di muscarina - in caso di dubbio lasciarlo stare. L''Infundibulicybe geotropa è grande (12-25 cm), a carne spessa, legato al bosco e ha un umbone centrale percepibile al tatto - non il piccolo, gracile fungo bianco dei prati. Il polverino sporale bianco NON esclude la Clitocybe velenosa, poiché anch''essa sporula bianco.','{"Dimensione: la Clitocybe rivulosa solo fino a ca. 4-5 cm di cappello, bianco-gesso pruinosa, depressa/infossata senza umbone; l''Infundibulicybe geotropa 12-25 cm, a carne spessa, con umbone centrale nettamente percepibile al tatto.","Entrambi biancastri-imbutiformi con lamelle decorrenti e polverino sporale BIANCO - solo dimensione, spessore della carne e umbone del cappello li separano con sicurezza, NON il colore né il polverino sporale.","Altamente velenosa per la muscarina (sindrome muscarinica: forte salivazione/sudorazione/lacrimazione entro 15-30 min, nei casi gravi collasso circolatorio), spesso nelle stesse stazioni di prati/bordi di sentieri/dune in gruppi o cerchi delle streghe.","Gambo gracile/sottile nella Clitocybe velenosa vs. robusto-clavato (2-4 cm di spessore) nell''Infundibulicybe geotropa."}','t'),
('infundibulicybe_geotropa','entoloma_sinuatum','en','Livid Pinkgill (Lead Poisoner): 5-20 cm, ivory/pale grey-brown to pale lilac-grey, convex with a wavy margin without an umbo, thick rigid gills that turn pink. Trooping Funnel (Monk''s Head): funnel-shaped with a central umbo, white decurrent gills, cream/buff-coloured.','Livid Pinkgill mealy with an unpleasant sourish-radish-like accompanying smell; Trooping Funnel aromatically sweetish with a bitter-almond aroma. Smell only as an additional feature, the spore print is decisive.','Livid Pinkgill: open deciduous forest (often beech/oak-hornbeam) on fresh to moist, calcareous soil, summer-autumn, mycorrhizal. Trooping Funnel: deciduous/coniferous forest, forest edges, forest meadows on moist calcareous soil, late summer-autumn - habitats overlap, therefore a spore-print and gill check is mandatory.','Decisive: Livid Pinkgill FLESH-PINK/flesh-reddish spore print vs. Trooping Funnel WHITE. This is the most reliable distinguishing feature between these two.','Make a spore print: pink/flesh-coloured powder = Livid Pinkgill = leave it standing. Additionally check whether the gills run down the stem (Trooping Funnel) or are merely emarginate/straight-attached and turn pink with maturity (Livid Pinkgill). If the central umbo is missing and the cap is not truly funnel-shaped, caution is required.','{"SPORE PRINT: Livid Pinkgill has FLESH-PINK (flesh-reddish) spore print; Trooping Funnel has WHITE spore print - the most reliable distinguishing feature via spore print.","GILLS: Livid Pinkgill gills whitish when young, then yellowish, finally flesh-pink due to the spores, emarginate/straight-attached at the stem (NOT decurrent); Trooping Funnel gills remain white/cream-coloured and run clearly down the stem.","CAP SHAPE: Livid Pinkgill convex with an inrolled, later wavy margin, WITHOUT a central umbo and without a pronounced funnel shape; Trooping Funnel funnel-shaped with a palpable central umbo.","SMELL: Livid Pinkgill mealy with an unpleasant sourish-radish-like note; Trooping Funnel aromatically sweetish with a bitter-almond note."}','t'),
('infundibulicybe_geotropa','entoloma_sinuatum','es','Entoloma gigante (Riesenrötling): 5-20 cm, marfil/pardo grisáceo claro hasta gris liláceo pálido, convexo con margen ondulado sin mamelón, láminas gruesas y rígidas que viran a rosa. Cabeza de monje (Mönchskopf): infundibuliforme con mamelón central, láminas blancas decurrentes, color crema/cuero.','El entoloma gigante harinoso con un olor secundario desagradablemente agrio-rabanoso; la cabeza de monje aromática y dulzona con aroma de almendra amarga. El olor solo como carácter complementario, la esporada es decisiva.','Entoloma gigante: bosque claro de frondosas (a menudo haya/roble-carpe) sobre suelo fresco a húmedo, rico en cal, de verano a otoño, micorrízico. Cabeza de monje: bosque de frondosas/coníferas, lindes de bosque, claros de bosque sobre suelo calcáreo húmedo, de finales de verano a otoño - las localizaciones se solapan, por ello la comprobación de la esporada y de las láminas es imprescindible.','Decisivo: el entoloma gigante tiene polvo de esporas ROSA CARNE/rosa carnoso frente a la cabeza de monje BLANCO. Este es el carácter de separación más seguro entre ambos.','Hacer la esporada: polvo rosa/color carne = entoloma gigante = dejarlo. Adicionalmente comprobar si las láminas son decurrentes (cabeza de monje) o solo escotadas/insertadas rectas y viran a rosa con la madurez (entoloma gigante). Si falta el mamelón central y el sombrero no es realmente infundibuliforme, hay que extremar la precaución.','{"POLVO DE ESPORAS: el entoloma gigante tiene polvo de esporas ROSA CARNE (rosa carnoso); la cabeza de monje tiene polvo de esporas BLANCO - el carácter de separación más seguro mediante la esporada.","LÁMINAS: las láminas del entoloma gigante de jóvenes blanquecinas, luego amarillentas, finalmente rosa carne por las esporas, escotadas/insertadas rectas en el pie (NO decurrentes); las láminas de la cabeza de monje permanecen blancas/cremosas y descienden claramente por el pie.","FORMA DEL SOMBRERO: el entoloma gigante convexo con margen enrollado, después ondulado, SIN mamelón central y sin forma infundibuliforme marcada; la cabeza de monje infundibuliforme con mamelón central palpable.","OLOR: el entoloma gigante harinoso con una nota desagradablemente agria-rabanosa; la cabeza de monje aromática y dulzona con nota de almendra amarga."}','t'),
('infundibulicybe_geotropa','entoloma_sinuatum','fr','Entolome livide (Entoloma sinuatum) : 5-20 cm, ivoire/brun-gris clair à gris lilas pâle, convexe à marge ondulée sans mamelon, lamelles épaisses et rigides qui virent au rose. Tête-de-moine : en forme d''entonnoir avec un mamelon central, lamelles blanches décurrentes, crème/couleur cuir.','L''Entolome livide farineux avec une odeur secondaire désagréablement acidulée-raphanoïde ; la Tête-de-moine aromatique douceâtre avec un arôme d''amande amère. N''utiliser l''odeur que comme caractère complémentaire, la sporée est décisive.','Entolome livide : forêt de feuillus claire (souvent hêtre/chêne-charme) sur sol frais à humide, riche en calcaire, été-automne, mycorhizien. Tête-de-moine : forêt de feuillus/conifères, lisières de forêt, clairières herbeuses sur sol calcaire humide, fin d''été-automne — les stations se recouvrent, c''est pourquoi le contrôle de la sporée et des lamelles est impératif.','Décisif : l''Entolome livide a une sporée ROSE CHAIR/rose-rougeâtre chair vs la Tête-de-moine BLANCHE. C''est le caractère de distinction le plus sûr entre ces deux espèces.','Faire une sporée : poudre rose/couleur chair = Entolome livide = laisser sur place. Vérifier en plus si les lamelles sont décurrentes (Tête-de-moine) ou seulement échancrées/à insertion droite et virant au rose à maturité (Entolome livide). Si le mamelon central manque et que le chapeau n''est pas véritablement en entonnoir, la prudence s''impose.','{"SPORÉE : l''Entolome livide a une sporée ROSE CHAIR (rose-rougeâtre chair) ; la Tête-de-moine a une sporée BLANCHE — le caractère de distinction le plus sûr par la sporée.","LAMELLES : les lamelles de l''Entolome livide sont blanchâtres jeunes, puis jaunâtres, finalement rose chair par les spores, échancrées/à insertion droite au pied (NON décurrentes) ; les lamelles de la Tête-de-moine restent blanches/crème et sont nettement décurrentes sur le pied.","FORME DU CHAPEAU : l''Entolome livide convexe à marge enroulée puis ondulée, SANS mamelon central et sans forme d''entonnoir prononcée ; la Tête-de-moine en forme d''entonnoir avec un mamelon central perceptible au toucher.","ODEUR : l''Entolome livide farineux avec une note désagréablement acidulée-raphanoïde ; la Tête-de-moine aromatique douceâtre avec une note d''amande amère."}','t'),
('infundibulicybe_geotropa','entoloma_sinuatum','it','Entoloma sinuatum: 5-20 cm, avorio/grigio-bruno chiaro fino a grigio-lillaceo pallido, convesso con margine ondulato senza umbone, lamelle spesse e rigide che virano al rosa. Infundibulicybe geotropa: imbutiforme con umbone centrale, lamelle bianche decorrenti, crema/color cuoio.','L''Entoloma sinuatum farinoso con sgradevole odore acidulo-rafanoide; l''Infundibulicybe geotropa aromatico e dolciastro con aroma di mandorla amara. L''odore solo come carattere accessorio, lo sporata è decisivo.','Entoloma sinuatum: bosco rado di latifoglie (spesso faggio/quercia-carpino) su suolo fresco fino a umido, ricco di calcare, estate-autunno, micorrizico. Infundibulicybe geotropa: bosco di latifoglie/conifere, margini boschivi, radure boschive su suolo calcareo umido, tardo estate-autunno - le stazioni si sovrappongono, quindi il controllo dello sporata e delle lamelle è obbligatorio.','Decisivo: l''Entoloma sinuatum ha polverino sporale ROSA-CARNE/rosato-carnicino vs. l''Infundibulicybe geotropa BIANCO. Questo è il carattere distintivo più sicuro tra questi due.','Eseguire lo sporata: polvere rosa/color carne = Entoloma sinuatum = lasciarlo stare. Inoltre verificare se le lamelle decorrono (Infundibulicybe geotropa) o sono solo smarginate/diritte e adnate e con la maturazione virano al rosa (Entoloma sinuatum). Se manca l''umbone centrale e il cappello non è realmente imbutiforme, è doverosa la prudenza.','{"POLVERINO SPORALE: l''Entoloma sinuatum ha polverino sporale ROSA-CARNE (rosato-carnicino); l''Infundibulicybe geotropa ha polverino sporale BIANCO - il carattere distintivo più sicuro tramite lo sporata.","LAMELLE: le lamelle dell''Entoloma sinuatum da giovani biancastre, poi giallastre, infine rosa-carne per le spore, smarginate/diritte e adnate al gambo (NON decorrenti); le lamelle dell''Infundibulicybe geotropa restano bianche/color crema e decorrono nettamente lungo il gambo.","FORMA DEL CAPPELLO: l''Entoloma sinuatum convesso con margine inrotolato, poi ondulato, SENZA umbone centrale e senza marcata forma a imbuto; l''Infundibulicybe geotropa imbutiforme con umbone centrale percepibile al tatto.","ODORE: l''Entoloma sinuatum farinoso con sgradevole nota acidula-rafanoide; l''Infundibulicybe geotropa aromatico e dolciastro con nota di mandorla amara."}','t'),
('infundibulicybe_gibba','ampulloclitocybe_clavipes','en','The club-shaped, swollen stem base is the key feature of clavipes; the ochre-brown funnel cap (gibba) has a slender, even stem with a central cap umbo.','The ochre-brown funnel cap is almost odourless to faintly sweetish; clavipes is pleasantly mushroomy with a faint fruity note.','Both in deciduous/coniferous/mixed forest (summer to late autumn); habitat is not a reliable distinguishing feature.','Both have a white spore print; not distinguishing.','Discard any whitish-grey funnel cap with a thick, club-shaped, spongy stem base, and never eat it together with alcohol.','{"Ochre-brown funnel cap: stem base NOT club-thickened, evenly slender/cylindrical; clavipes has a strikingly club-swollen, inflated, spongy-watery stem base.","The cap of the ochre-brown is warm ochre/flesh-brown with a small central umbo/papilla; clavipes is whitish-grey to grey-brown with a distinctly darker cap centre and a pale, long-inrolled margin.","The flesh of the ochre-brown is thin, tough-elastic and dry; clavipes flesh is soft, spongy, strongly water-soaked when wet.","clavipes causes a coprine/acetaldehyde syndrome in combination with alcohol; the ochre-brown is edible and alcohol-tolerant."}','f'),
('infundibulicybe_gibba','ampulloclitocybe_clavipes','es','La base del pie engrosada en maza es el carácter clave de clavipes; el clitocibe acopado ocre-pardo (gibba) tiene un pie esbelto y regular con umbón central en el sombrero.','El clitocibe ocre-pardo es casi inodoro o ligeramente dulzón; clavipes tiene olor agradable a hongo con una débil nota afrutada.','Ambos en bosque de frondosas/coníferas/mixto (de verano a finales de otoño); el hábitat no es un carácter distintivo fiable.','Ambos con esporada blanca; no distintivo.','Descartar todo clitocibe blanquecino-gris con base del pie gruesa, en maza y esponjosa, y no consumirlo nunca junto con alcohol.','{"Clitocibe ocre-pardo: base del pie NO engrosada en maza, regularmente esbelta/cilíndrica; clavipes tiene una base del pie llamativamente engrosada en maza, hinchada, esponjosa-acuosa.","El sombrero del ocre-pardo es ocre/pardo-carne cálido con un pequeño umbón/papila central; clavipes es blanco-grisáceo a gris-pardo con el centro del sombrero claramente más oscuro y un margen claro largo tiempo enrollado.","La carne del ocre-pardo es delgada, tenaz-elástica y seca; la carne de clavipes es blanda, esponjosa, fuertemente empapada de agua con la humedad.","clavipes provoca, en combinación con alcohol, un síndrome coprínico/de acetaldehído; el ocre-pardo es comestible y tolerante al alcohol."}','f'),
('infundibulicybe_gibba','ampulloclitocybe_clavipes','fr','La base du pied en massue, renflée, est le critère clé de clavipes ; le clitocybe en entonnoir a un pied élancé, régulier, avec un mamelon central sur le chapeau.','Clitocybe en entonnoir presque inodore à légèrement sucré ; clavipes fongique-agréable avec une faible note fruitée.','Les deux en forêt de feuillus/conifères/mixte (été à fin d''automne) ; pas de critère de séparation fiable via l''habitat.','Les deux à sporée blanche ; non discriminant.','Écarter tout clitocybe blanchâtre-gris à base du pied épaisse en massue, spongieuse, et ne jamais le consommer avec de l''alcool.','{"Clitocybe en entonnoir : base du pied NON épaissie en massue, régulièrement élancée/cylindrique ; clavipes a une base du pied visiblement renflée en massue, spongieuse-aqueuse.","Le chapeau du clitocybe en entonnoir est ocre/brun-chair chaud avec un petit mamelon/papille central ; clavipes blanc-grisâtre à gris-brun avec un centre nettement plus sombre et un bord clair longtemps enroulé.","La chair du clitocybe en entonnoir est mince, coriace-élastique et sèche ; la chair de clavipes molle, spongieuse, fortement imbibée d''eau par temps humide.","clavipes provoque en liaison avec l''alcool un syndrome coprinien/acétaldéhyde ; le clitocybe en entonnoir est comestible et tolérant à l''alcool."}','f'),
('infundibulicybe_gibba','ampulloclitocybe_clavipes','it','La base del gambo ingrossata a clava è il carattere chiave di clavipes; il clitocybe a imbuto ocra-bruno ha un gambo slanciato e regolare con umbone centrale sul cappello.','Il clitocybe ocra-bruno è quasi inodore o leggermente dolciastro; clavipes ha odore gradevole di fungo con una debole nota fruttata.','Entrambi in bosco di latifoglie/conifere/misto (dall''estate al tardo autunno); l''habitat non è un carattere distintivo affidabile.','Entrambi con sporata bianca; non distintivo.','Scartare ogni clitocybe biancastro-grigio con base del gambo grossa, a clava e spugnosa, e non consumarlo mai insieme ad alcol.','{"Clitocybe ocra-bruno: base del gambo NON ingrossata a clava, regolarmente slanciata/cilindrica; clavipes ha una base del gambo vistosamente ingrossata a clava, gonfia, spugnosa-acquosa.","Il cappello dell''ocra-bruno è ocra/bruno-carne caldo con un piccolo umbone/papilla centrale; clavipes è bianco-grigiastro fino a grigio-bruno con il centro del cappello nettamente più scuro e un margine chiaro a lungo arrotolato.","La carne dell''ocra-bruno è sottile, tenace-elastica e asciutta; la carne di clavipes è molle, spugnosa, fortemente imbevuta d''acqua con l''umidità.","clavipes provoca, in combinazione con l''alcol, una sindrome coprinica/da acetaldeide; l''ocra-bruno è commestibile e tollerante all''alcol."}','f'),
('infundibulicybe_gibba','clitocybe_fragrans','en','Warm ochre-brown, deeply funnel-shaped gibba with a small point vs. pale grey, small fragrans with a striate margin.','fragrans smells of aniseed; the ochre-brown funnel cap is nearly odourless - a clear distinguishing feature.','Both widespread in woodland; habitat is not a reliable distinguishing feature.','Both have a white spore print; not distinguishing.','Lack of odour argues against fragrans, but as a rule leave small aniseed-smelling funnel caps alone (muscarine).','{"The ochre-brown funnel cap is warm ochre/flesh-brown, larger, with a deeply funnel-shaped cap and a small central point; fragrans is small, pale grey-brown and watery-pale.","fragrans smells distinctly of aniseed and contains muscarine; the ochre-brown funnel cap is nearly odourless and edible.","The cap margin of fragrans is translucently striate; in the ochre-brown it is non-striate.","Ochre-brown with tough-elastic, thin flesh; fragrans flesh fragile and thin."}','f'),
('infundibulicybe_gibba','clitocybe_fragrans','es','gibba ocre-pardo cálido, profundamente acopado con pequeña punta, frente a fragrans gris pálido, pequeño, con margen estriado.','fragrans huele a anís; el clitocibe ocre-pardo es casi inodoro - un carácter distintivo claro.','Ambos ampliamente extendidos en los bosques; el hábitat no es un carácter distintivo fiable.','Ambos con esporada blanca; no distintivo.','La ausencia de olor descarta fragrans, pero por regla general dejar en su sitio los pequeños clitocibes con olor a anís (muscarina).','{"El clitocibe ocre-pardo es de un ocre/pardo-carne cálido, más grande, con sombrero profundamente acopado y una pequeña punta central; fragrans es pequeño, gris-pardo pálido y claro-acuoso.","fragrans huele claramente a anís y contiene muscarina; el clitocibe ocre-pardo es casi inodoro y comestible.","El margen del sombrero de fragrans es estriado por transparencia; en el ocre-pardo es no estriado.","Ocre-pardo con carne tenaz-elástica y delgada; carne de fragrans frágil y delgada."}','f'),
('infundibulicybe_gibba','clitocybe_fragrans','fr','gibba ocre-brun chaud, profondément en entonnoir avec un petit mamelon vs. fragrans gris pâle, petit, à bord strié.','fragrans d''anis ; clitocybe en entonnoir presque inodore - un critère de séparation clair.','Les deux largement répandus en forêt ; pas de critère de séparation fiable via l''habitat.','Les deux à sporée blanche ; non discriminant.','L''absence d''odeur va contre fragrans, mais laisser sur place en général les petits clitocybes à odeur d''anis (muscarine).','{"Le clitocybe en entonnoir est ocre/brun-chair chaud, plus grand, avec un chapeau profondément en entonnoir et un petit mamelon central ; fragrans est petit, gris-brun pâle et aqueux clair.","fragrans sent nettement l''anis et contient de la muscarine ; le clitocybe en entonnoir est presque inodore et comestible.","Bord du chapeau strié par transparence chez fragrans ; non strié chez le clitocybe en entonnoir.","Clitocybe en entonnoir à chair coriace-élastique, mince ; chair de fragrans fragile et mince."}','f'),
('infundibulicybe_gibba','clitocybe_fragrans','it','gibba ocra-bruno caldo, profondamente a imbuto con piccolo umbone, contro fragrans grigio pallido, piccolo, con margine striato.','fragrans odora di anice; il clitocybe ocra-bruno è pressoché inodore - un carattere distintivo netto.','Entrambi ampiamente diffusi nei boschi; l''habitat non è un carattere distintivo affidabile.','Entrambi con sporata bianca; non distintivo.','L''assenza di odore esclude fragrans, ma in generale lasciare sul posto i piccoli clitocybe con odore di anice (muscarina).','{"Il clitocybe ocra-bruno è di un ocra/bruno-carne caldo, più grande, con cappello profondamente a imbuto e un piccolo umbone centrale; fragrans è piccolo, grigio-bruno pallido e chiaro-acquoso.","fragrans odora nettamente di anice e contiene muscarina; il clitocybe ocra-bruno è pressoché inodore e commestibile.","Il margine del cappello di fragrans è striato per trasparenza; nell''ocra-bruno è non striato.","Ocra-bruno con carne tenace-elastica e sottile; carne di fragrans fragile e sottile."}','f'),
('kuehneromyces_mutabilis','conocybe_filaris','en','The decisive feature is the stem below the ring: brown with spreading scales (sheathed woodtuft) versus smooth to silvery longitudinally fibrillose (conocybe). The cap colours are in both honey to cinnamon brown and do NOT separate them.','Sheathed woodtuft smells pleasantly mushroomy-aromatic; the conocybe is odourless to faintly mealy — smell is NOT a reliable distinguishing feature.','Sheathed woodtuft in clusters on rotting hardwood/conifer wood (stumps, deadwood); Conocybe filaris terrestrial on lawns, meadows, wood chips, compost and conifer needle litter on the ground — the growth site (wood vs ground) is an important clue, but on its own not conclusive.','Both rust-brown to cinnamon-brown — UNUSABLE as a distinguishing feature. Therefore the stem scaling below the ring must absolutely be checked.','Only collect sheathed woodtuft if the stem below the ring is clearly brown and scaly/snake-patterned AND the mushroom grows in clusters on wood. If the stem is smooth/silvery-fibrillose or it grows on the ground on lawn, discard immediately — life-threatening due to amatoxins. When in doubt, go to mushroom inspection (VAPKO).','{"Sheathed woodtuft: stem below the ring distinctly brown, with spreading scales/snake-patterned — conifer conocybe (Conocybe filaris/Pholiotina rugosa): stem smooth to silvery longitudinally fibrillose, without scales. The stem feature is the most important distinguishing factor.","The conocybe contains amatoxins (the same poison as the death cap) — even a few caps can trigger fatal liver failure, with a 6-24 h symptom-free latency before organ damage.","The conocybe usually grows terrestrially on lawns, meadows, wood chips, compost soil and conifer needle litter on the ground — sheathed woodtuft in clusters directly on rotting hardwood/conifer wood (stumps, fallen trunks).","Sheathed woodtuft typically grows in dense clusters on the same piece of wood; the conocybe usually stands singly to gregariously on the ground, not in clusters out of wood.","The cap of sheathed woodtuft typically dries out two-toned (hygrophanous watery margin); the conocybe cap is more uniformly ochre-cinnamon-brown and barely two-tone zoned."}','f'),
('kuehneromyces_mutabilis','conocybe_filaris','es','El rasgo decisivo es el pie por debajo del anillo: pardo con escamas erizadas (seta de chopo/foliota cambiante) frente a liso o fibriloso-plateado longitudinalmente (conocybe). Los colores del sombrero son en ambos pardo miel a pardo canela y NO sirven para distinguirlos.','La foliota cambiante huele agradablemente a champiñón, aromática; el conocybe es inodoro o ligeramente harinoso — el olor NO es un carácter distintivo seguro.','Foliota cambiante en grupos densos sobre madera podrida de frondosas/coníferas (tocones, madera muerta); Conocybe filaris terrícola sobre césped, prados, astillas de madera, compost y hojarasca de acículas en el suelo — el lugar de crecimiento (madera vs suelo) es un indicio importante, pero por sí solo no concluyente.','Ambos pardo herrumbre a pardo canela — INUTILIZABLE como carácter distintivo. Por ello hay que verificar obligatoriamente las escamas del pie por debajo del anillo.','Recolectar la foliota cambiante SOLO si el pie por debajo del anillo es claramente pardo y escamoso/jaspeado Y si el hongo crece en grupos sobre madera. Si el pie es liso/fibriloso-plateado o crece en el suelo sobre césped, descartar de inmediato — peligro mortal por amatoxinas. En caso de duda, control de setas (VAPKO).','{"Foliota cambiante: pie por debajo del anillo claramente pardo, con escamas erizadas/jaspeado — conocybe de coníferas (Conocybe filaris/Pholiotina rugosa): pie liso o fibriloso-plateado longitudinalmente, sin escamas. El carácter del pie es el principal factor distintivo.","El conocybe contiene amatoxinas (el mismo veneno que la oronja verde/Amanita phalloides) — bastan unos pocos sombreros para provocar una insuficiencia hepática mortal, con una latencia sin síntomas de 6-24 h antes del daño orgánico.","El conocybe crece sobre todo de forma terrícola en césped, prados, astillas de madera, tierra de compost y hojarasca de acículas en el suelo — la foliota cambiante en grupos directamente sobre madera podrida de frondosas/coníferas (tocones, troncos caídos).","La foliota cambiante crece típicamente en grupos densos sobre la misma madera; el conocybe se presenta casi siempre aislado o gregario en el suelo, no en grupos saliendo de la madera.","El sombrero de la foliota cambiante seca típicamente en dos tonos (margen higrófano empapado de agua); el sombrero del conocybe es más uniformemente ocre pardo canela y apenas zonado en dos colores."}','f'),
('kuehneromyces_mutabilis','conocybe_filaris','fr','Le critère décisif est le pied sous l''anneau : brun et couvert d''écailles dressées (pholiote changeante) contre lisse à fibrilleux argenté longitudinalement (conocybe). Les couleurs du chapeau sont chez les deux brun miel à brun cannelle et NE permettent PAS de les distinguer.','La pholiote changeante a une odeur agréable de champignon, aromatique ; le conocybe est inodore à légèrement farineux — l''odeur n''est PAS un critère de distinction sûr.','Pholiote changeante en touffes sur bois mort de feuillus/conifères (souches, bois mort) ; Conocybe filaris terrestre sur gazon, prairies, copeaux de bois, compost et litière d''aiguilles au sol — le lieu de croissance (bois vs sol) est un indice important, mais à lui seul non probant.','Les deux brun rouille à brun cannelle — INUTILISABLE comme critère de distinction. Il faut donc impérativement vérifier les écailles du pied sous l''anneau.','Ne récolter la pholiote changeante QUE si le pied sous l''anneau est nettement brun et écailleux/chiné ET si le champignon pousse en touffes sur du bois. En cas de pied lisse/fibrilleux argenté ou de pousse au sol sur gazon, rejeter immédiatement — danger mortel par amatoxines. En cas de doute, contrôle des champignons (VAPKO).','{"Pholiote changeante : pied sous l''anneau nettement brun, à écailles dressées/chiné — conocybe des conifères (Conocybe filaris/Pholiotina rugosa) : pied lisse à fibrilleux argenté longitudinalement, sans écailles. Le caractère du pied est le principal facteur de distinction.","Le conocybe contient des amatoxines (le même poison que l''amanite phalloïde) — quelques chapeaux suffisent à provoquer une insuffisance hépatique mortelle, avec une latence sans symptômes de 6 à 24 h avant l''atteinte des organes.","Le conocybe pousse le plus souvent de façon terrestre sur gazon, prairies, copeaux de bois, terre de compost et litière d''aiguilles au sol — la pholiote changeante en touffes directement sur bois mort de feuillus/conifères (souches, troncs couchés).","La pholiote changeante pousse typiquement en touffes denses sur le même bois ; le conocybe se tient le plus souvent isolé à grégaire au sol, non en touffes sortant du bois.","Le chapeau de la pholiote changeante sèche typiquement en deux teintes (marge hygrophane gorgée d''eau) ; le chapeau du conocybe est plus uniformément ocre brun cannelle et à peine zoné en deux couleurs."}','f'),
('kuehneromyces_mutabilis','conocybe_filaris','it','Il criterio decisivo è il gambo sotto l''anello: bruno e squamoso-sporgente (foliota mutabile) contro liscio o fibrilloso-argenteo longitudinalmente (conocybe). I colori del cappello sono in entrambi dal bruno miele al bruno cannella e NON sono distintivi.','La foliota mutabile ha un odore gradevole, fungino-aromatico; il conocybe è inodore o leggermente farinoso — l''odore NON è un carattere distintivo sicuro.','Foliota mutabile a ciuffi su legno marcescente di latifoglie/conifere (ceppaie, legno morto); Conocybe filaris terricolo su prati, erba, cippato, compost e lettiera di aghi al suolo — il luogo di crescita (legno vs suolo) è un indizio importante, ma da solo non probante.','Entrambi bruno ruggine o bruno cannella — INUTILIZZABILE come carattere distintivo. È quindi indispensabile verificare la squamosità del gambo sotto l''anello.','Raccogliere la foliota mutabile SOLO se il gambo sotto l''anello è chiaramente bruno e squamoso/zigrinato E se il fungo cresce a ciuffi su legno. In caso di gambo liscio/fibrilloso-argenteo o di crescita al suolo su prato, scartare subito — pericolo di morte per amatossine. In caso di dubbio, controllo dei funghi (VAPKO).','{"Foliota mutabile: gambo sotto l''anello nettamente bruno, con squame sporgenti/zigrinato — conocybe delle conifere (Conocybe filaris/Pholiotina rugosa): gambo liscio o fibrilloso-argenteo longitudinalmente, senza squame. Il carattere del gambo è il principale fattore distintivo.","Il conocybe contiene amatossine (lo stesso veleno dell''amanita falloide) — pochi cappelli bastano a scatenare un''insufficienza epatica mortale, con una latenza priva di sintomi di 6-24 h prima del danno d''organo.","Il conocybe cresce per lo più terricolo su prati, erba, cippato, terriccio di compost e lettiera di aghi al suolo — la foliota mutabile a ciuffi direttamente su legno marcescente di latifoglie/conifere (ceppaie, tronchi a terra).","La foliota mutabile cresce tipicamente a ciuffi densi sullo stesso legno; il conocybe si presenta per lo più isolato o gregario al suolo, non a ciuffi dal legno.","Il cappello della foliota mutabile si asciuga tipicamente in due colori (margine igrofano imbevuto d''acqua); il cappello del conocybe è più uniformemente ocra bruno cannella e quasi privo di zonatura bicolore."}','f'),
('kuehneromyces_mutabilis','galerina_marginata','en','Both honey-brown, hygrophanous, clustered on wood - visually very similar; only the stem below the ring zone differs (scaly vs. smooth).','both mushroomy, no reliable distinction by smell','both on dead wood/stumps, often mixed','both rust-brown','DEADLY. Taboo for beginners. Harvest only with the complete stem and check every single mushroom - when in doubt, take it to the VAPKO inspection.','{"Stem below the ring: Sheathed Woodtuft scaly/frosted, Funeral Bell smooth-silky","Funeral Bell contains deadly amatoxins"}','t'),
('kuehneromyces_mutabilis','galerina_marginata','es','Ambos de color pardo miel, higrófanos, en grupos cespitosos sobre madera — ópticamente muy similares; lo único que los distingue es el pie por debajo de la zona anular (escamoso frente a liso).','ambos con olor fúngico, sin distinción olfativa fiable','ambos sobre madera muerta/tocones, a menudo mezclados','ambos pardo herrumbre','MORTAL. Prohibido para principiantes. Recolectar únicamente con el pie completo y revisar cada ejemplar por separado — en caso de duda, llevar al control de VAPKO.','{"Pie por debajo del anillo: la seta de los tocones (Stockschwämmchen) es escamosa/pruinosa, la Galerina venenosa (Gifthäubling) es lisa-sedosa","La Galerina venenosa contiene amatoxinas mortales"}','t'),
('kuehneromyces_mutabilis','galerina_marginata','fr','Tous deux brun miel, hygrophanes, en touffes sur le bois — très semblables visuellement ; seul le pied sous la zone annulaire les distingue (squameux vs lisse).','tous deux fongiques, aucune distinction olfactive fiable','tous deux sur bois mort/souches, souvent mêlés','tous deux brun rouille','MORTEL. Interdit aux débutants. Ne récolter qu''avec le pied complet et vérifier chaque champignon individuellement — en cas de doute, au contrôle VAPKO.','{"Pied au-dessous de l''anneau : la Pholiote changeante squameux/pruineux, la Galère marginée lisse-soyeux","La Galère marginée contient des amatoxines mortelles"}','t'),
('kuehneromyces_mutabilis','galerina_marginata','it','Entrambi color bruno-miele, igrofani, in fascetti sul legno — otticamente molto simili; a distinguere è unicamente il gambo sotto la zona dell''anello (squamoso vs. liscio).','entrambi di odore fungino, nessuna distinzione olfattiva sicura','entrambi su legno morto/ceppi, spesso mescolati','entrambi bruno-ruggine','MORTALE. Per principianti vietato. Raccogliere solo con il gambo completo e controllare ogni singolo fungo — nel dubbio al controllo VAPKO.','{"Gambo sotto l''anello: il Kuehneromyces mutabilis squamoso/pruinoso, la Galerina marginata liscio-setoso","La Galerina marginata contiene amatossine mortali"}','t'),
('kuehneromyces_mutabilis','gymnopilus_junonius','en','G. junonius is distinctly larger, uniformly orange and finely scaly; the sheathed woodtuft is small with a hygrophanous two-coloured cap and a brown-scaly stem below the ring.','Sheathed woodtuft pleasantly mushroomy; G. junonius mealy-rancid, plus an extremely bitter taste.','Both clustered on wood/stumps; G. junonius on stumps of broadleaf and conifer trees as well as at trunk bases, the sheathed woodtuft mostly on broadleaf stumps.','Both rust-brown - the spore colour does NOT separate these two. IMPORTANT: the real deadly risk for the sheathed woodtuft is the deadly galerina (Galerina marginata), which also drops a rust-brown spore print - a separate, life-threatening confusion topic.','Bitter taste (spit out the taste test) and conspicuous size = rustgill = throw away. Only collect the sheathed woodtuft if the identification is absolutely certain - the deadly galerina risk must be considered separately.','{"Gymnopilus junonius grows very large (cap 5-15 cm) and in dense clusters; the sheathed woodtuft stays small (cap 2-6 cm).","Taste: G. junonius extremely bitter; sheathed woodtuft mild.","Cap surface: the sheathed woodtuft has a two-coloured, hygrophanous cap with a translucently striate margin; G. junonius uniformly orange-rust-yellow, finely scaly.","Stem: sheathed woodtuft distinctly brown-scaly/snake-patterned below the ring; G. junonius fibrillose without snake-patterning.","Caution: both have a rust-brown spore print - the spore print does NOT separate them here, so check size/bitterness."}','f'),
('kuehneromyces_mutabilis','gymnopilus_junonius','es','G. junonius es claramente más grande, uniformemente naranja y finamente escamoso; la seta de chopo (kuehneromyces) es pequeña, con sombrero higrófano bicolor y pie pardo-escamoso bajo el anillo.','Seta de chopo con olor agradable a hongo; G. junonius harinoso-rancio, además con sabor extremadamente amargo.','Ambos cespitosos sobre madera/tocones; G. junonius sobre tocones de frondosas y coníferas así como en la base de troncos, la seta de chopo sobre todo en tocones de frondosas.','Ambos pardo-herrumbre - el color de la esporada NO separa estas dos especies. IMPORTANTE: el verdadero riesgo mortal asociado a la seta de chopo es la Galerina marginata, que también esporula pardo-herrumbre - un tema de confusión distinto y potencialmente mortal.','Sabor amargo (escupir la prueba de sabor) y tamaño llamativo = gimnopilo = desechar. Recolectar la seta de chopo solo si la determinación es absolutamente segura - el riesgo mortal de la Galerina marginata debe considerarse por separado.','{"Gymnopilus junonius llega a ser muy grande (sombrero 5-15 cm) y crece en densos cespitosos; la seta de chopo permanece pequeña (sombrero 2-6 cm).","Sabor: G. junonius extremadamente amargo; seta de chopo suave.","Superficie del sombrero: la seta de chopo tiene un sombrero bicolor, higrófano, con margen estriado por transparencia; G. junonius uniformemente naranja-amarillo-herrumbre, finamente escamoso.","Pie: seta de chopo claramente pardo-escamoso/con dibujo de serpiente bajo el anillo; G. junonius fibriloso sin dibujo de serpiente.","Atención: ambos tienen esporada pardo-herrumbre - la esporada aquí NO los separa, por lo que hay que comprobar tamaño/amargor."}','f'),
('kuehneromyces_mutabilis','gymnopilus_junonius','fr','G. junonius est nettement plus grand, uniformément orange et finement écailleux ; la pholiote changeante est petite avec un chapeau hygrophane bicolore et un pied brun-écailleux sous l''anneau.','Pholiote changeante agréablement fongique ; G. junonius farineux-rance, avec en plus un goût extrêmement amer.','Les deux en touffes sur bois/souches ; G. junonius sur souches de feuillus et de conifères ainsi que sur bases de troncs, pholiote changeante le plus souvent sur souches de feuillus.','Les deux brun rouille – la couleur des spores ne sépare PAS ces deux-là. IMPORTANT : le véritable risque mortel de la pholiote changeante est la galère marginée (Galerina marginata), qui sporule aussi en brun rouille – un sujet de confusion séparé, mortel.','Goût amer (test gustatif à recracher) et taille remarquable = gymnopile = jeter. Ne récolter la pholiote changeante que si la détermination est absolument sûre – le risque mortel de la galère marginée doit être considéré séparément.','{"Gymnopilus junonius devient très grand (chapeau 5–15 cm) et pousse en touffes denses ; la pholiote changeante reste petite (chapeau 2–6 cm).","Goût : G. junonius extrêmement amer ; pholiote changeante doux.","Surface du chapeau : pholiote changeante a un chapeau bicolore, hygrophane avec un bord strié par transparence ; G. junonius uniformément orange-jaune rouille, finement écailleux.","Pied : pholiote changeante nettement brun-écailleux/chiné sous l''anneau ; G. junonius fibrilleux sans chinure.","Attention : les deux ont une sporée brun rouille – la sporée ne sépare PAS ici, donc vérifier la taille/l''amertume."}','f'),
('kuehneromyces_mutabilis','gymnopilus_junonius','it','G. junonius è nettamente più grande, uniformemente arancio e finemente squamoso; la pholiota mutevole è piccola, con cappello igrofano bicolore e gambo bruno-squamoso sotto l''anello.','Pholiota mutevole con odore gradevole di fungo; G. junonius farinoso-rancido, inoltre con sapore estremamente amaro.','Entrambi cespitosi su legno/ceppi; G. junonius su ceppi di latifoglie e conifere nonché alla base dei tronchi, la pholiota mutevole per lo più su ceppi di latifoglie.','Entrambi bruno-ruggine - il colore della sporata NON distingue queste due specie. IMPORTANTE: il vero rischio mortale legato alla pholiota mutevole è la Galerina marginata, che pure sporula bruno-ruggine - un tema di confusione distinto e potenzialmente mortale.','Sapore amaro (sputare la prova gustativa) e dimensione vistosa = gimnopilo = da gettare. Raccogliere la pholiota mutevole solo se la determinazione è assolutamente sicura - il rischio mortale della Galerina marginata va considerato separatamente.','{"Gymnopilus junonius diventa molto grande (cappello 5-15 cm) e cresce in densi cespi; la pholiota mutevole resta piccola (cappello 2-6 cm).","Sapore: G. junonius estremamente amaro; pholiota mutevole mite.","Superficie del cappello: la pholiota mutevole ha cappello bicolore, igrofano, con margine striato per trasparenza; G. junonius uniformemente arancio-giallo-ruggine, finemente squamoso.","Gambo: pholiota mutevole nettamente bruno-squamoso/zigrinato sotto l''anello; G. junonius fibrilloso senza zigrinatura.","Attenzione: entrambi hanno sporata bruno-ruggine - la sporata qui NON distingue, quindi verificare dimensione/amarezza."}','f'),
('kuehneromyces_mutabilis','hypholoma_fasciculare','en','The sulphur tuft''s gills carry a greenish sulphur-yellow tone that the brown-gilled sheathed woodtuft (Kuehneromyces mutabilis) lacks; the brown-scaly snakeskin-patterned stem below the membranous ring is the woodtuft''s most important feature.','The sheathed woodtuft smells pleasantly mushroomy; the sulphur tuft is intensely bitter. CAUTION: a taste test ONLY rules out the sulphur tuft — the deadly funeral bell (Galerina) is not bitter, so tasting does NOT protect against it.','Both grow in clusters on deadwood/stumps of hardwood and conifer, so the habitat is NOT suitable for distinction.','Sheathed woodtuft: brown spore print (cinnamon/rust-brown); sulphur tuft: dark violet/purple-brown spore print. Both are dark-spored — the spore print only separates them roughly, so checking the stem and gill colour is mandatory.','Never trust the bitter taste alone: that only protects against the sulphur tuft, NOT against the deadly, mild-tasting funeral bell. Harvest the sheathed woodtuft exclusively if EVERY fruiting body shows the membranous ring AND below it the brown-scaly snakeskin-patterned stem AND no green tinge is visible on the gills — when in doubt, leave it.','{"Sheathed woodtuft: mild, nutty taste; sulphur tuft: distinctly and persistently BITTER","Sheathed woodtuft gills pale when young, then cinnamon to rust-brown; sulphur tuft gills sulphur-yellow, then greenish to greenish-black","Sheathed woodtuft has a membranous ring + below it dark, projecting scales on the stem; sulphur tuft has at most a fleeting ring zone, stem bare yellow-rust-brown","Sheathed woodtuft stem below the ring brown-scaly, snakeskin-patterned; sulphur tuft stem sulphur-yellow above, rust-brown towards the base, smooth","MORE IMPORTANT than the sulphur tuft: the DEADLY funeral bell (Galerina marginata) likewise grows in clusters on deadwood, looks very similar to the sheathed woodtuft and is NOT bitter — only harvest the sheathed woodtuft if you reliably recognise every fruiting body by its brown-scaly stem"}','f'),
('kuehneromyces_mutabilis','hypholoma_fasciculare','es','Las láminas del hifoloma de láminas verdes (Schwefelkopf) tienen un tono amarillo azufre verdoso que le falta a la seta de chopo de láminas pardas (Kuehneromyces mutabilis); el pie con escamas pardas en disposición de piel de serpiente bajo el anillo membranoso es el carácter más importante del Kuehneromyces.','El Kuehneromyces huele agradablemente a hongo; el hifoloma es intensamente amargo. ATENCIÓN: una cata SOLO descarta el hifoloma — la Galerina mortal no es amarga, así que catar NO protege contra ella.','Ambos crecen en grupos sobre madera muerta/tocones de frondosas y coníferas, por lo que el hábitat NO sirve para la distinción.','Kuehneromyces: esporada parda (canela/pardo herrumbre); hifoloma de láminas verdes: esporada pardo violácea/púrpura oscura. Ambos tienen esporada oscura — la esporada solo los separa de forma aproximada, por eso es obligatorio comprobar el pie y el color de las láminas.','Nunca fiarse solo del sabor amargo: eso protege únicamente del hifoloma, NO de la Galerina mortal de sabor suave. Recolectar el Kuehneromyces exclusivamente si CADA carpóforo muestra el anillo membranoso Y, debajo, el pie con escamas pardas en piel de serpiente Y ninguna tonalidad verde visible en las láminas — en caso de duda, dejarlo.','{"Kuehneromyces: sabor suave-a nuez; hifoloma de láminas verdes: clara y persistentemente AMARGO","Láminas del Kuehneromyces de jóvenes claras, luego canela a pardo herrumbre; láminas del hifoloma amarillo azufre, luego verdosas a verde negruzco","El Kuehneromyces tiene un anillo membranoso + debajo escamas oscuras salientes en el pie; el hifoloma tiene a lo sumo una zona anular fugaz, pie glabro amarillo-pardo herrumbre","Pie del Kuehneromyces bajo el anillo con escamas pardas en piel de serpiente; pie del hifoloma amarillo azufre arriba, pardo herrumbre hacia abajo, liso","MÁS IMPORTANTE que el hifoloma: la Galerina marginata MORTAL crece igualmente en grupos sobre madera muerta, se parece mucho al Kuehneromyces y NO es amarga — recolectar el Kuehneromyces solo si se reconoce con certeza cada carpóforo por su pie con escamas pardas"}','f'),
('kuehneromyces_mutabilis','hypholoma_fasciculare','fr','Les lames de l''hypholome (Schwefelkopf) portent une teinte jaune soufre verdâtre qui manque à la pholiote ridée à lames brunes (Stockschwämmchen / Kuehneromyces) ; le pied chiné de squames brunes sous l''anneau membraneux est le caractère le plus important du Kuehneromyces.','Le Kuehneromyces sent agréablement le champignon ; l''hypholome est intensément amer. ATTENTION : une dégustation ne distingue QUE l''hypholome — la galère mortelle (Galerina) n''est pas amère, une dégustation ne protège donc PAS d''elle.','Tous deux poussent en touffes sur bois mort/souches de feuillus et de conifères, de sorte que l''habitat ne convient PAS à la distinction.','Kuehneromyces : sporée brune (cannelle/brun rouille) ; hypholome à lames vertes : sporée brun violacé/pourpre foncé. Tous deux ont une sporée sombre — la sporée ne les sépare que grossièrement, vérifier donc impérativement le pied et la couleur des lames.','Ne jamais se fier uniquement au goût amer : cela protège seulement de l''hypholome, PAS de la galère mortelle au goût doux. Ne récolter le Kuehneromyces que si CHAQUE carpophore montre l''anneau membraneux ET, en dessous, le pied chiné de squames brunes ET aucune teinte verte visible sur les lames — dans le doute, laisser sur place.','{"Kuehneromyces : goût doux-noisette ; hypholome à lames vertes : nettement et durablement AMER","Lames du Kuehneromyces jeunes claires, puis cannelle à brun rouille ; lames de l''hypholome jaune soufre, puis verdâtres à vert noirâtre","Le Kuehneromyces a un anneau membraneux + en dessous des squames sombres dressées sur le pied ; l''hypholome a tout au plus une zone annulaire fugace, pied glabre jaune-brun rouille","Pied du Kuehneromyces sous l''anneau chiné de squames brunes ; pied de l''hypholome jaune soufre en haut, brun rouille vers le bas, lisse","PLUS IMPORTANT que l''hypholome : la galère marginée MORTELLE (Galerina marginata) pousse aussi en touffes sur bois mort, ressemble beaucoup au Kuehneromyces et n''est PAS amère — ne récolter le Kuehneromyces que si l''on reconnaît avec certitude chaque carpophore à son pied chiné de squames brunes"}','f'),
('kuehneromyces_mutabilis','hypholoma_fasciculare','it','Le lamelle dell''ipoloma (Schwefelkopf) hanno una tinta giallo zolfo verdastra che manca alla foliota mutabile a lamelle brune (Kuehneromyces); il gambo zigrinato di squame brune sotto l''anello membranoso è il carattere più importante del Kuehneromyces.','Il Kuehneromyces ha odore gradevolmente fungino; l''ipoloma è intensamente amaro. ATTENZIONE: un assaggio distingue SOLO l''ipoloma — la galerina mortale (Galerina) non è amara, un assaggio quindi NON protegge da essa.','Entrambi crescono a ciuffi su legno morto/ceppi di latifoglie e conifere, per cui l''habitat NON è adatto alla distinzione.','Kuehneromyces: sporata bruna (cannella/bruno ruggine); ipoloma a lamelle verdi: sporata bruno violaceo/porpora scuro. Entrambi hanno sporata scura — la sporata li separa solo grossolanamente, verificare quindi obbligatoriamente il gambo e il colore delle lamelle.','Non affidarsi mai solo al sapore amaro: questo protegge soltanto dall''ipoloma, NON dalla galerina mortale dal sapore mite. Raccogliere il Kuehneromyces esclusivamente se OGNI carpoforo mostra l''anello membranoso E, sotto, il gambo zigrinato di squame brune E nessuna tinta verde visibile sulle lamelle — nel dubbio lasciare sul posto.','{"Kuehneromyces: sapore mite-nocciola; ipoloma a lamelle verdi: nettamente e durevolmente AMARO","Lamelle del Kuehneromyces da giovani chiare, poi cannella fino a bruno ruggine; lamelle dell''ipoloma giallo zolfo, poi verdastre fino a verde nerastro","Il Kuehneromyces ha un anello membranoso + sotto squame scure sporgenti sul gambo; l''ipoloma ha al massimo una zona anulare fugace, gambo glabro giallo-bruno ruggine","Gambo del Kuehneromyces sotto l''anello zigrinato di squame brune; gambo dell''ipoloma giallo zolfo in alto, bruno ruggine verso il basso, liscio","PIÙ IMPORTANTE dell''ipoloma: la galerina marginata MORTALE (Galerina marginata) cresce anch''essa a ciuffi su legno morto, somiglia molto al Kuehneromyces e NON è amara — raccogliere il Kuehneromyces solo se si riconosce con certezza ogni carpoforo dal gambo zigrinato di squame brune"}','f'),
('kuehneromyces_mutabilis','hypholoma_lateritium','en','Sheathed woodtuft with a scaly stem and ring zone, hygrophanous fading cap; brick cap (lateritium) with a smooth stem without scales, uniformly brick-red.','Sheathed woodtuft pleasantly mushroomy and mild, brick cap bitter in taste.','Both clustered on broadleaf stumps - habitat does not separate them, but stem scales and spore colour do.','Sheathed woodtuft rust-/tobacco-brown, brick cap purple-brown - an important distinguishing feature.','Stem scales below the ring zone are the key feature of the sheathed woodtuft - if they are missing, hands off. Even more important: the sheathed woodtuft is confused with the DEADLY galerina (Galerina marginata), so only collect when absolutely certain.','{"The sheathed woodtuft (edible) has a snake-patterned/scaly stem below the ring zone; the brick caps (Hypholoma) have at most a fleeting ring zone without scales","Sheathed woodtuft with a hygrophanous cap drying out two-coloured (water-spot effect), brick cap uniformly brick-red","Taste sheathed woodtuft mild, brick cap bitter","Spore print sheathed woodtuft tobacco-brown/rust-brown, brick cap purple-brown","Both grow clustered on wood - growth form alone is deceptive, so stem scales and spore colour are decisive"}','f'),
('kuehneromyces_mutabilis','hypholoma_lateritium','es','Seta de chopo con pie escamoso y zona anular, sombrero higrófano que se decolora; hifoloma color ladrillo (lateritium) con pie liso sin escamas, uniformemente rojo-ladrillo.','Seta de chopo con olor agradable a hongo y suave, hifoloma color ladrillo amargo al gusto.','Ambos cespitosos sobre tocones de frondosas - el hábitat no los separa, sino las escamas del pie y el color de la esporada.','Seta de chopo pardo-herrumbre/tabaco, hifoloma color ladrillo pardo-púrpura - carácter distintivo importante.','Las escamas del pie por debajo de la zona anular son el carácter clave de la seta de chopo - si faltan, no tocar. Más importante aún: la seta de chopo se confunde con la Galerina marginata MORTAL, por lo que solo se debe recolectar con absoluta certeza.','{"La seta de chopo (comestible) tiene un pie con dibujo de serpiente/escamoso por debajo de la zona anular; los hifolomas (cabezas de azufre) tienen como mucho una zona anular fugaz sin escamas","Seta de chopo con sombrero higrófano que al secarse se vuelve bicolor (efecto mancha de agua), hifoloma color ladrillo uniformemente rojo-ladrillo","Sabor seta de chopo suave, hifoloma color ladrillo amargo","Esporada seta de chopo pardo-tabaco/pardo-herrumbre, hifoloma color ladrillo pardo-púrpura","Ambos crecen cespitosos sobre madera - la forma de crecimiento por sí sola engaña, por eso las escamas del pie y el color de la esporada son decisivos"}','f'),
('kuehneromyces_mutabilis','hypholoma_lateritium','fr','Pholiote changeante à pied écailleux et zone annulaire, chapeau hygrophane se décolorant ; hypholome couleur de brique à pied lisse sans écailles, uniformément couleur de brique.','Pholiote changeante agréablement fongique et douce, hypholome couleur de brique amer au goût.','Les deux en touffes sur souches de feuillus — l''habitat ne sépare pas, mais les écailles du pied et la couleur des spores.','Pholiote changeante brun rouille/tabac, hypholome couleur de brique brun pourpre — critère de séparation important.','Les écailles du pied sous la zone annulaire sont le critère clé de la pholiote changeante — si elles manquent, ne pas toucher. Plus important encore : la pholiote changeante est confondue avec la galère marginée MORTELLE (Galerina marginata), donc ne récolter qu''avec une certitude absolue.','{"Pholiote changeante (comestible) a un pied chiné/écailleux sous la zone annulaire, les hypholomes ont tout au plus une zone annulaire fugace sans écailles","Pholiote changeante à chapeau hygrophane, séchant bicolore (effet de tache d''eau), hypholome couleur de brique uniformément couleur de brique","Goût pholiote changeante doux, hypholome couleur de brique amer","Sporée pholiote changeante brun tabac/brun rouille, hypholome couleur de brique brun pourpre","Les deux poussent en touffes sur bois — la forme de croissance seule trompe, donc les écailles du pied et la couleur des spores sont décisives"}','f'),
('kuehneromyces_mutabilis','hypholoma_lateritium','it','Pholiota mutevole con gambo squamoso e zona anulare, cappello igrofano che si scolora; hypholoma color mattone con gambo liscio senza squame, uniformemente bruno-mattone.','Pholiota mutevole con odore gradevole di fungo e mite, hypholoma color mattone amaro al gusto.','Entrambi cespitosi su ceppi di latifoglie - l''habitat non distingue, bensì le squame del gambo e il colore della sporata.','Pholiota mutevole bruno-ruggine/tabacco, hypholoma color mattone bruno-purpureo - carattere distintivo importante.','Le squame del gambo sotto la zona anulare sono il carattere chiave della pholiota mutevole - se mancano, non toccare. Ancora più importante: la pholiota mutevole viene confusa con la Galerina marginata MORTALE, quindi raccogliere solo in caso di assoluta certezza.','{"La pholiota mutevole (commestibile) ha un gambo zigrinato/squamoso sotto la zona anulare, gli hypholoma (teste di zolfo) hanno al massimo una zona anulare fugace senza squame","Pholiota mutevole con cappello igrofano che si scolora in bicolore (effetto macchia d''acqua), hypholoma color mattone uniformemente bruno-mattone","Sapore pholiota mutevole mite, hypholoma color mattone amaro","Sporata pholiota mutevole bruno-tabacco/bruno-ruggine, hypholoma color mattone bruno-purpureo","Entrambi crescono cespitosi sul legno - la sola forma di crescita inganna, perciò squame del gambo e colore della sporata sono decisivi"}','f'),
('kuehneromyces_mutabilis','pholiota_squarrosa','en','Dry, coarsely shaggy-scaly cap in the shaggy scalycap (Pholiota squarrosa) vs smooth, hygrophanous, two-toned cap with a fading margin in the sheathed woodtuft.','The scalycap smells obtrusively radish-like, the sheathed woodtuft pleasantly spicy-mild.','Both in clusters on wood/stumps — site not distinguishing.','Both rust-brown — does NOT serve for distinction here, so other features are mandatory.','Caution: the sheathed woodtuft is itself off-limits for beginners because of the deadly funeral bell (Galerina marginata). Scalycap, sheathed woodtuft and funeral bell all grow in clusters on wood — only harvest this group with expert knowledge and a spore print.','{"The shaggy scalycap has a dry, shaggy-scaly cap; the sheathed woodtuft has a smooth to finely fibrillose, hygrophanous cap with a fading margin (two-toned)","The scalycap is clearly larger and more robust, cap often 5–12 cm; the sheathed woodtuft is small, 3–6 cm","Sheathed woodtuft stem below the ring dark brown and finely scaly/snakeskin-patterned; scalycap stem coarsely shaggy-scaly","Taste: scalycap bitter/unpleasant, sheathed woodtuft mild","Both rust-brown spore print — no distinguishing feature here"}','f'),
('kuehneromyces_mutabilis','pholiota_squarrosa','es','Sombrero seco y groseramente erizado-escamoso en la foliota escamosa (Pholiota squarrosa) frente a sombrero liso, higrófano y bicolor con margen que palidece en el Kuehneromyces.','La foliota escamosa tiene un olor invasivo a rábano, el Kuehneromyces un olor agradablemente especiado y suave.','Ambos en grupos sobre madera/tocones — el lugar no distingue.','Ambos pardo herrumbre — aquí NO sirve para la distinción, por lo que otros caracteres son imprescindibles.','Precaución: el Kuehneromyces es ya un tabú para principiantes a causa de la Galerina mortal (Galerina marginata). Foliota escamosa, Kuehneromyces y Galerina crecen todos en grupos sobre madera — recolectar este grupo solo con conocimientos de experto y una esporada.','{"La foliota escamosa tiene un sombrero seco, erizado-escamoso; el Kuehneromyces tiene un sombrero de liso a finamente fibriloso, higrófano, con margen que palidece (bicolor)","La foliota escamosa es claramente más grande y robusta, sombrero a menudo 5–12 cm; el Kuehneromyces es pequeño, 3–6 cm","Pie del Kuehneromyces bajo el anillo pardo oscuro y finamente escamoso/en piel de serpiente; pie de la foliota escamosa groseramente erizado de escamas","Sabor: foliota escamosa amargo/desagradable, Kuehneromyces suave","Ambos con esporada pardo herrumbre — aquí no es un criterio de distinción"}','f'),
('kuehneromyces_mutabilis','pholiota_squarrosa','fr','Chapeau sec et grossièrement hérissé-squameux chez la pholiote (Schüppling) vs chapeau lisse, hygrophane et bicolore à marge se décolorant chez le Kuehneromyces.','La pholiote a une odeur envahissante de radis, le Kuehneromyces une odeur agréablement épicée et douce.','Tous deux en touffes sur bois/souches — le site ne distingue pas.','Tous deux brun rouille — ne convient PAS ici à la distinction, d''autres caractères sont donc impératifs.','Prudence : le Kuehneromyces est lui-même tabou pour les débutants à cause de la galère mortelle (Galerina marginata). Pholiote, Kuehneromyces et galère poussent tous en touffes sur bois — ne récolter ce groupe qu''avec un savoir d''expert et une sporée.','{"La pholiote hérissée a un chapeau sec, hérissé-squameux ; le Kuehneromyces a un chapeau lisse à finement fibrilleux, hygrophane, à marge se décolorant (bicolore)","La pholiote est nettement plus grande et plus robuste, chapeau souvent 5–12 cm ; le Kuehneromyces est petit, 3–6 cm","Pied du Kuehneromyces sous l''anneau brun foncé et finement squameux/chiné ; pied de la pholiote grossièrement hérissé de squames","Goût : pholiote amer/désagréable, Kuehneromyces doux","Tous deux à sporée brun rouille — ici pas un critère de distinction"}','f'),
('kuehneromyces_mutabilis','pholiota_squarrosa','it','Cappello secco e grossolanamente irto-squamoso nella foliota squarrosa (Schüppling) vs cappello liscio, igrofano e bicolore con margine che sbiadisce nel Kuehneromyces.','La foliota squarrosa ha un odore invadente di ravanello, il Kuehneromyces un odore gradevolmente speziato e mite.','Entrambi a ciuffi su legno/ceppi — il sito non distingue.','Entrambi bruno ruggine — qui NON è adatto alla distinzione, altri caratteri sono quindi imperativi.','Prudenza: il Kuehneromyces è esso stesso un tabù per i principianti a causa della galerina mortale (Galerina marginata). Foliota squarrosa, Kuehneromyces e galerina crescono tutti a ciuffi su legno — raccogliere questo gruppo solo con conoscenze da esperto e una sporata.','{"La foliota squarrosa ha un cappello secco, irto-squamoso; il Kuehneromyces ha un cappello da liscio a finemente fibrilloso, igrofano, con margine che sbiadisce (bicolore)","La foliota squarrosa è nettamente più grande e robusta, cappello spesso 5–12 cm; il Kuehneromyces è piccolo, 3–6 cm","Gambo del Kuehneromyces sotto l''anello bruno scuro e finemente squamoso/zigrinato; gambo della foliota squarrosa grossolanamente irto di squame","Sapore: foliota squarrosa amaro/sgradevole, Kuehneromyces mite","Entrambi a sporata bruno ruggine — qui non un criterio di distinzione"}','f'),
('kuehneromyces_mutabilis','pholiotina_rugosa','en','The sheathed woodtuft in clusters on wood with a snakeskin-patterned dark stem; Pholiotina solitary/gregarious on soil, smooth pale stem, wrinkled cap.','Sheathed woodtuft pleasantly spicy; Pholiotina rugosa inconspicuous to slightly rancid — smell is NOT a reliable distinguishing criterion.','Decisive, but do NOT rely on it alone: sheathed woodtuft in clusters on wood; Pholiotina rugosa on ground/lawn/mulch/wood chips. Since Pholiotina can also fruit on wood chips, proximity to wood alone is no free pass — always check several features.','Sheathed woodtuft rust-brown; Pholiotina rugosa rust-brown to cinnamon-brown — spore colour does NOT separate them, so site, stem snakeskin pattern and habit are decisive.','Never mistake little brown mushrooms (LBMs) with a ring for sheathed woodtufts if they grow on soil/lawn/mulch instead of in clusters on wood — danger to life from amatoxins. In an emergency call Tox Info Suisse 145.','{"Pholiotina rugosa (= Conocybe filaris) is a little brown mushroom (LBM) with a thin, brittle stem and a movable, membranous ring — contains deadly amatoxins like the death cap","Pholiotina grows SOLITARY to gregarious on soil, lawn, path edges, mulch, wood chips/compost soil — NOT in clusters on stumps; the sheathed woodtuft grows in dense clusters on rotten wood/stumps","Sheathed woodtuft stem below the ring distinctly dark brown and finely scaly snakeskin-patterned; Pholiotina stem smooth, pale, without snakeskin pattern","Sheathed woodtuft cap hygrophanous, two-toned with a fading margin; Pholiotina cap ochre-brown, wrinkled, without this two-tone colouring","Pholiotina is mostly much smaller and more slender than a typical sheathed woodtuft"}','f'),
('kuehneromyces_mutabilis','pholiotina_rugosa','es','El Kuehneromyces en grupos sobre la madera con pie oscuro en piel de serpiente; Pholiotina solitaria/gregaria sobre la tierra, pie liso pálido, sombrero rugoso.','Kuehneromyces agradablemente especiado; Pholiotina rugosa inapreciable a ligeramente rancia — el olor NO es un criterio de distinción seguro.','Decisivo, pero NO fiarse de él solo: Kuehneromyces en grupos sobre madera; Pholiotina rugosa sobre suelo/césped/mantillo/astillas. Como Pholiotina también puede fructificar sobre astillas de madera, la mera cercanía a la madera no es un salvoconducto — comprobar siempre varios caracteres.','Kuehneromyces pardo herrumbre; Pholiotina rugosa pardo herrumbre a pardo canela — el color de las esporas NO distingue, por eso el lugar, el dibujo de piel de serpiente del pie y el porte son decisivos.','NUNCA tomar pequeños hongos pardos (LBM) con anillo por Kuehneromyces si crecen sobre tierra/césped/mantillo en lugar de en grupos sobre madera — peligro de muerte por amatoxinas. En caso de emergencia llamar a Tox Info Suisse 145.','{"Pholiotina rugosa (= Conocybe filaris) es un pequeño hongo pardo (LBM) con pie delgado y quebradizo y un anillo membranoso móvil — contiene amatoxinas mortales como la oronja verde (Amanita phalloides)","Pholiotina crece SOLITARIA a gregaria sobre tierra, césped, bordes de caminos, mantillo, astillas de madera/tierra de compost — NO en grupos sobre tocones; el Kuehneromyces crece en grupos densos sobre madera podrida/tocones","Pie del Kuehneromyces bajo el anillo claramente pardo oscuro y finamente escamoso en piel de serpiente; pie de Pholiotina liso, pálido, sin dibujo de piel de serpiente","Sombrero del Kuehneromyces higrófano, bicolor con margen que palidece; sombrero de Pholiotina pardo ocre, rugoso, sin esta bicromía","Pholiotina suele ser mucho más pequeña y grácil que un Kuehneromyces típico"}','f'),
('kuehneromyces_mutabilis','pholiotina_rugosa','fr','Le Kuehneromyces en touffes sur le bois avec pied sombre chiné ; Pholiotina isolé/grégaire sur la terre, pied lisse pâle, chapeau ridé.','Kuehneromyces agréablement épicé ; Pholiotina rugosa discret à légèrement rance — l''odeur n''est PAS un critère de distinction sûr.','Décisif, mais à ne PAS utiliser seul : Kuehneromyces en touffes sur bois ; Pholiotina rugosa sur sol/gazon/paillis/copeaux. Comme Pholiotina peut aussi fructifier sur copeaux de bois, la proximité du bois seule n''est pas un blanc-seing — toujours vérifier plusieurs caractères.','Kuehneromyces brun rouille ; Pholiotina rugosa brun rouille à brun cannelle — la couleur des spores ne distingue PAS, le site, le chiné du pied et le port sont donc décisifs.','Ne JAMAIS prendre de petits champignons bruns (LBM) à anneau pour des Kuehneromyces s''ils poussent sur terre/gazon/paillis plutôt qu''en touffes sur bois — danger de mort par amatoxines. En cas d''urgence, appeler Tox Info Suisse 145.','{"Pholiotina rugosa (= Conocybe filaris) est un petit champignon brun (LBM) à pied mince et cassant et à anneau membraneux mobile — contient des amatoxines mortelles comme l''amanite phalloïde","Pholiotina pousse ISOLÉ à grégaire sur terre, gazon, bords de chemins, paillis, copeaux de bois/terreau de compost — PAS en touffes sur souches ; le Kuehneromyces pousse en touffes denses sur bois pourri/souches","Pied du Kuehneromyces sous l''anneau nettement brun foncé et finement chiné de squames ; pied de Pholiotina lisse, pâle, sans chiné","Chapeau du Kuehneromyces hygrophane, bicolore à marge se décolorant ; chapeau de Pholiotina brun ocre, ridé, sans cette bicoloration","Pholiotina est le plus souvent bien plus petit et plus gracile qu''un Kuehneromyces typique"}','f'),
('kuehneromyces_mutabilis','pholiotina_rugosa','it','Il Kuehneromyces a ciuffi sul legno con gambo scuro zigrinato; Pholiotina isolata/gregaria sulla terra, gambo liscio pallido, cappello rugoso.','Kuehneromyces gradevolmente speziato; Pholiotina rugosa inappariscente fino a leggermente rancido — l''odore NON è un criterio di distinzione sicuro.','Decisivo, ma da NON usare da solo: Kuehneromyces a ciuffi su legno; Pholiotina rugosa su suolo/prato/pacciame/cippato. Poiché Pholiotina può fruttificare anche su cippato di legno, la sola vicinanza al legno non è un lasciapassare — verificare sempre più caratteri.','Kuehneromyces bruno ruggine; Pholiotina rugosa bruno ruggine fino a bruno cannella — il colore delle spore NON distingue, perciò il sito, la zigrinatura del gambo e il portamento sono decisivi.','Non scambiare MAI piccoli funghi bruni (LBM) con anello per Kuehneromyces se crescono su terra/prato/pacciame invece che a ciuffi su legno — pericolo di morte da amatossine. In caso d''emergenza chiamare Tox Info Suisse 145.','{"Pholiotina rugosa (= Conocybe filaris) è un piccolo fungo bruno (LBM) a gambo sottile e fragile e con un anello membranoso mobile — contiene amatossine mortali come l''amanita falloide","Pholiotina cresce ISOLATA fino a gregaria su terra, prato, bordi dei sentieri, pacciame, cippato di legno/terriccio di compost — NON a ciuffi su ceppi; il Kuehneromyces cresce a ciuffi densi su legno marcio/ceppi","Gambo del Kuehneromyces sotto l''anello nettamente bruno scuro e finemente zigrinato di squame; gambo di Pholiotina liscio, pallido, senza zigrinatura","Cappello del Kuehneromyces igrofano, bicolore con margine che sbiadisce; cappello di Pholiotina bruno ocra, rugoso, senza questa bicromia","Pholiotina è per lo più molto più piccola e gracile di un tipico Kuehneromyces"}','f'),
('lactarius_deliciosus','paxillus_involutus','en','Saffron Milkcap: consistently orange to carrot-red, cap with darker concentric zones, often greenish spots with age/when injured, stem frequently with pits. Brown Rollrim: dull yellow-brown to umber-brown, permanently inrolled felty cap margin, no orange, no concentric milkcap zones.','Saffron Milkcap: mild, fruity. Brown Rollrim: inconspicuous, slightly sourish; no typical milkcap scent.','Habitat overlap possible: Saffron Milkcap is a mycorrhizal partner of pines (partly spruces), rather calcareous soil. Brown Rollrim forms mycorrhiza with pine, spruce, birch, beech on acidic, fresh to moist soils. Habitat is therefore NOT a reliable distinguishing feature - only the milk test and colour count.','Saffron Milkcap: cream-white to pale ochre-yellowish spore print. Brown Rollrim: brownish (clay-brown) spore print - clearly darker. Clear diagnostic direction: the Rollrim is always noticeably darker.','The cut/milk test is mandatory: whoever sees NO orange-red milky sap at the cut surface does not have a Milkcap - leave it standing. The Brown Rollrim never exudes milk and turns brown-black under pressure (the Milkcap only slowly turns green). Paxillus syndrome (immune-haemolytic) can be fatal after years of repeated consumption - therefore never taste it ''to try'', not even cooked.','{"MILK TEST (decisive): Saffron Milkcap releases abundant carrot-/orange-red milky sap when cut. The Brown Rollrim releases NO milk - it is not a milk mushroom. No orange-red milky sap = no Milkcap.","Pressure discolouration: Rollrim gills and flesh discolour immediately to brown to dark-red-/black-brown when pressed/injured. Milkcap flesh/milk discolours only slowly greenish (never brown-black).","Gills: Rollrim ochre-yellow to olive-brown, decurrent at the stem and easily detachable from the cap flesh. Milkcap gills are orange/saffron-coloured and not detachable.","Cap colour + cap margin: Milkcap orange to carrot-red with darker concentric ring zones. Rollrim dull yellow-brown to umber-brown, without orange, with a permanently inrolled, felty cap margin (even with age)."}','t'),
('lactarius_deliciosus','paxillus_involutus','es','Níscalo (Edel-Reizker): por completo naranja a rojo zanahoria, sombrero con zonas concéntricas más oscuras, a menudo con manchas verdosas en la vejez/al dañarse, pie frecuentemente con hoyuelos. Paxilo enrollado (Kahler Krempling): pardo amarillento mate hasta pardo umbra, margen del sombrero permanentemente enrollado y afieltrado, sin naranja, sin zonas concéntricas de níscalo.','Níscalo: suave, afrutado-frutal. Paxilo enrollado: inconspicuo, ligeramente agrio; sin el aroma típico del níscalo.','Posible solapamiento de hábitat: el níscalo es compañero micorrízico de los pinos (en parte abetos rojos), preferentemente suelo calcáreo. El paxilo enrollado forma micorriza con pino, abeto rojo, abedul, haya sobre suelos ácidos, frescos a húmedos. Por ello la localización NO es un carácter de separación seguro – solo cuentan la prueba de la leche y el color.','Níscalo: polvo de esporas blanco cremoso hasta ocre amarillento pálido. Paxilo enrollado: polvo de esporas parduzco (pardo arcilla) – claramente más oscuro. Dirección diagnóstica clara: el paxilo siempre notablemente más oscuro.','La prueba de corte/leche es obligatoria: quien NO vea látex rojo anaranjado en el corte, no tiene un níscalo – dejarlo. El paxilo enrollado nunca segrega leche y vira al pardo-negruzco bajo presión (el níscalo solo verdea lentamente). El síndrome de Paxillus (inmuno-hemolítico) puede tener un desenlace mortal tras un consumo repetido durante años – por ello nunca catarlo ''para probar'', ni siquiera cocinado.','{"PRUEBA DE LA LECHE (decisiva): el níscalo segrega abundante látex rojo zanahoria/anaranjado al corte. El paxilo enrollado NO segrega leche – no es un hongo lechoso. Sin látex rojo anaranjado = no es un níscalo.","Cambio de color por presión: las láminas y la carne del paxilo se tornan al instante pardo hasta pardo rojo-/negruzco oscuro bajo presión/lesión. La carne/leche del níscalo cambia solo lentamente a verdoso (nunca pardo-negruzco).","Láminas: el paxilo de ocre amarillento → pardo oliva, decurrentes en el pie y fácilmente separables de la carne del sombrero. Las láminas del níscalo son anaranjadas/color azafrán y no separables.","Color del sombrero + margen del sombrero: el níscalo naranja a rojo zanahoria con zonas anulares concéntricas más oscuras. El paxilo pardo amarillento mate hasta pardo umbra, sin naranja, con margen del sombrero permanentemente enrollado y afieltrado (también en la vejez)."}','t'),
('lactarius_deliciosus','paxillus_involutus','fr','Lactaire délicieux : entièrement orange à rouge carotte, chapeau à zones concentriques plus foncées, souvent des taches verdâtres avec l''âge/en cas de blessure, pied souvent à scrobicules. Paxille enroulé : terne brun jaunâtre à brun ombré, marge du chapeau durablement enroulée et feutrée, pas d''orange, pas de zones concentriques de lactaire.','Lactaire délicieux : douce, fruitée. Paxille enroulé : discrète, légèrement acidulée ; pas de parfum typique de lactaire.','Chevauchement d''habitat possible : le Lactaire délicieux est partenaire de mycorhize des pins (en partie épicéas), plutôt sur sol calcaire. Le Paxille enroulé forme une mycorhize avec le pin, l''épicéa, le bouleau, le hêtre sur sols acides, frais à humides. La station n''est donc PAS un caractère de distinction sûr — seuls le test du lait et la couleur comptent.','Lactaire délicieux : sporée blanc crème à ocre-jaunâtre pâle. Paxille enroulé : sporée brunâtre (brun argile) — nettement plus foncée. Direction diagnostique claire : le paxille toujours sensiblement plus foncé.','Le test de coupe/du lait est obligatoire : qui ne voit AUCUN latex orange-rouge à la coupe n''a pas un lactaire — le laisser sur place. Le Paxille enroulé ne sécrète jamais de lait et noircit-brunit à la pression (le lactaire ne fait que verdir lentement). Le syndrome paxillien (immuno-hémolytique) peut être mortel après des années de consommation répétée — ne jamais le goûter ''pour essayer'', même cuit.','{"TEST DU LAIT (décisif) : le Lactaire délicieux libère à la coupe un latex abondant rouge carotte/orange. Le Paxille enroulé ne libère AUCUN lait — ce n''est pas un lactaire. Pas de latex orange-rouge = pas de lactaire.","Changement de couleur à la pression : les lamelles et la chair du Paxille se colorent immédiatement à la pression/blessure du brun au brun foncé rougeâtre/noirâtre. La chair/le lait du Lactaire ne se colore que lentement en verdâtre (jamais brun-noir).","Lamelles : le Paxille ocre-jaune → brun olive, décurrentes sur le pied et facilement détachables de la chair du chapeau. Les lamelles du Lactaire sont orange/safran et non détachables.","Couleur du chapeau + marge : le Lactaire orange à rouge carotte avec des zones annulaires concentriques plus foncées. Le Paxille terne brun jaunâtre à brun ombré, sans orange, à marge du chapeau durablement enroulée et feutrée (même avec l''âge)."}','t'),
('lactarius_deliciosus','paxillus_involutus','it','Lactarius deliciosus: interamente da arancione a rosso-carota, cappello con zone concentriche più scure, spesso macchie verdastre con l''età/in caso di lesione, gambo spesso con scrobicoli. Paxillus involutus: opaco da giallo-bruno a bruno-umbra, margine del cappello permanentemente inrotolato e feltroso, nessun arancione, nessuna zona concentrica da Lactarius.','Lactarius deliciosus: mite, fruttato-fragrante. Paxillus involutus: inappariscente, leggermente acidulo; nessun tipico profumo da Lactarius.','Sovrapposizione di habitat possibile: il Lactarius deliciosus è partner micorrizico dei pini (in parte abeti rossi), preferibilmente suolo calcareo. Il Paxillus involutus forma micorriza con pino, abete rosso, betulla, faggio su suoli acidi, freschi fino a umidi. La stazione NON è quindi un carattere distintivo sicuro - contano solo il test del latice e il colore.','Lactarius deliciosus: polverino sporale da bianco-crema a ocra-giallastro pallido. Paxillus involutus: polverino sporale brunastro (bruno-argilla) - nettamente più scuro. Indicazione diagnostica chiara: il Paxillus sempre marcatamente più scuro.','Il test del taglio/del latice è obbligatorio: chi NON vede latice arancio-rosso al taglio non ha un Lactarius deliciosus - lasciarlo stare. Il Paxillus involutus non emette mai latice e alla pressione vira al bruno-nerastro (il Lactarius vira solo lentamente al verde). La sindrome paxillica (immuno-emolitica) può avere esito mortale dopo anni di consumo ripetuto - perciò non assaggiarlo mai ''per provare'', nemmeno cotto.','{"TEST DEL LATICE (decisivo): il Lactarius deliciosus emette al taglio abbondante latice rosso-carota/arancione. Il Paxillus involutus NON emette latice - non è un fungo lattario. Nessun latice arancio-rosso = nessun Lactarius deliciosus.","Viraggio alla pressione: lamelle e carne del Paxillus virano subito alla pressione/lesione da bruno a bruno-rossastro scuro/bruno-nerastro. La carne/il latice del Lactarius vira solo lentamente al verdastro (mai al bruno-nerastro).","Lamelle: il Paxillus da giallo-ocra a bruno-oliva, decorrenti lungo il gambo e facilmente staccabili dalla carne del cappello. Le lamelle del Lactarius sono arancioni/color zafferano e non staccabili.","Colore del cappello + margine del cappello: il Lactarius da arancione a rosso-carota con zone anulari concentriche più scure. Il Paxillus opaco da giallo-bruno a bruno-umbra, senza arancione, con margine del cappello permanentemente inrotolato e feltroso (anche con l''età)."}','t'),
('lactarius_deterrimus','paxillus_involutus','en','False saffron milkcap (Lactarius deterrimus): orange-red to orange-brownish cap, with age/in frost developing dirty green spots, pale orange gills that turn dark red to grey-green when injured. Brown rollrim (Paxillus involutus): yellowish to umber-brown, moist glossy cap, when young with a long inrolled felty cap margin, when old distinctly funnel-shaped and depressed; ochre-yellowish to olive-brown, thin and crowded, decurrent and detachable gills that stain STRONGLY rust- to blackish-brown when pressed/touched (milkcap gills do not turn rust-brown). Both can appear funnel-shaped and orange-brown -> hence the confusion.','False saffron milkcap: mild, fruity-spicy (taste slightly bitter). Brown rollrim: sourish-nondescript; smell is NOT a reliable distinguishing feature — the milk test and the gill pressure test are decisive.','Overlap exists: the brown rollrim is a mycorrhizal partner of, among others, spruce (also pine, birch, beech, hornbeam) and grows in the same acidic coniferous/mixed-forest soil in which the false saffron milkcap occurs with spruce. Habitat does NOT separate them reliably.','Secondary feature, not sharply separating: the false saffron milkcap, depending on the source, cream to pale ochre to ochre-brownish; the brown rollrim distinctly clay- to rust-brown. The colours overlap towards ochre — therefore only as a supporting clue, not as the main criterion. The milk test remains decisive. When in doubt, take a spore print.','Always do the milk test: cut a fresh section and check for milk exuding. If NO milk exudes, it is not a milkcap — the brown rollrim is milkless and, via the cumulative Paxillus syndrome (haemolytic anaemia, kidney failure), can become life-threatening even after years of consumption. Milkcaps, by contrast, exude orange/carrot-red milk that turns wine-red. Rule of thumb: only collect milkcaps with red/orange milk — never those with pale/white milk or with no milk at all.','{"MILK TEST (decisive, verified): the false saffron milkcap exudes orange/carrot-red milk when cut, which turns wine-red within 15-20 min (later grey-green); the brown rollrim exudes NO milk/fluid — no milk at all = NEVER eat it if you are expecting a milkcap.","Gill pressure test (verified): rollrim gills stain strongly rust- to blackish-brown when pressed and can be detached from the cap; milkcap gills are brittle, firmly attached to the cap, and turn dark red/grey-green when injured, not rust-brown.","Cap margin & shape: the rollrim has a long felty-inrolled cap margin and a glossy olive-brown cap; the milkcap cap is orange with green spots, without a permanently felty inrolled margin.","Spore print (supplementary, not reliable on its own): milkcap cream to ochre vs. rollrim clay/rust-brown — overlaps towards ochre, therefore only supplementary."}','t'),
('lactarius_deterrimus','paxillus_involutus','es','Níscalo de abeto (Lactarius deterrimus): sombrero de color rojo anaranjado a pardo anaranjado, con el tiempo o con las heladas presenta manchas verdosas sucias; láminas de color naranja pálido que, al ser dañadas, viran a rojo oscuro hasta verde grisáceo. Paxillus involutus (paxilo enrollado): sombrero de color pardo amarillento a pardo umbría, brillante en húmedo, de joven con el margen del sombrero enrollado y afieltrado durante mucho tiempo, de viejo claramente deprimido en forma de embudo; láminas de color ocre amarillento a pardo oliváceo, delgadas y apretadas, decurrentes y separables, que bajo presión o al tacto se manchan FUERTEMENTE de pardo ferruginoso a pardo negruzco (las láminas del níscalo no se vuelven pardo ferruginosas). Ambos pueden parecer anaranjado-pardos y en forma de embudo, de ahí la confusión.','Níscalo de abeto (Lactarius deterrimus): suave, afrutado-aromático (sabor ligeramente amargo). Paxillus involutus: agrio-discreto; el olor NO es un rasgo distintivo fiable: la prueba de la leche y la prueba de presión de las láminas son las decisivas.','Existe solapamiento: Paxillus involutus es micorrízico, entre otros, del abeto rojo (también del pino, abedul, haya, carpe) y crece en el mismo suelo ácido de bosque de coníferas/mixto en el que aparece el níscalo de abeto junto al abeto rojo. El hábitat NO separa de forma fiable.','Rasgo secundario, no claramente discriminante: el níscalo de abeto, según la fuente, va de crema a ocre pálido hasta pardo ocráceo; Paxillus involutus es claramente pardo arcilloso a pardo ferruginoso. Los colores se solapan hacia el ocre, por lo que solo sirve como prueba complementaria, no como criterio principal. Lo decisivo sigue siendo la prueba de la leche. En caso de duda, tomar una esporada.','Haz siempre la prueba de la leche: corta en fresco y comprueba si exuda leche. Si NO sale leche, no es un níscalo: Paxillus involutus carece de leche y, a través del síndrome acumulativo de Paxillus (anemia hemolítica, insuficiencia renal), puede llegar a poner en peligro la vida incluso tras años de consumo. Los níscalos, en cambio, exudan leche de color naranja/rojo zanahoria que vira a rojo vino. Regla práctica: recoge únicamente lactarios con leche roja/naranja, nunca con leche clara/blanca o sin leche alguna.','{"PRUEBA DE LA LECHE (decisiva, verificada): el níscalo de abeto (Lactarius deterrimus) exuda al cortarlo leche de color naranja/rojo zanahoria que en 15-20 min vira a rojo vino (más tarde a verde grisáceo); Paxillus involutus NO exuda leche ni líquido alguno: ausencia total de leche = NUNCA comer si se espera un níscalo.","Prueba de presión de las láminas (verificada): las láminas de Paxillus involutus se manchan fuertemente de pardo ferruginoso a pardo negruzco bajo presión y se desprenden del sombrero; las láminas del níscalo son quebradizas, están firmemente unidas al sombrero y, al ser dañadas, viran a rojo oscuro/verde grisáceo, no a pardo ferruginoso.","Margen del sombrero y forma: Paxillus involutus tiene el margen del sombrero afieltrado y enrollado durante mucho tiempo y el sombrero pardo oliváceo brillante; el sombrero del níscalo es anaranjado con manchas verdes, sin un enrollamiento afieltrado permanente del margen.","Esporada (complementaria, no fiable por sí sola): níscalo de crema a ocre frente a Paxillus involutus pardo arcilloso/ferruginoso; se solapan hacia el ocre, por lo que solo sirve de forma complementaria."}','t'),
('lactarius_deterrimus','paxillus_involutus','fr','Lactaire de l''épicéa (lactaire saumon) : chapeau rouge orangé à brun orangé, devenant taché de vert sale avec l''âge ou par le gel, lamelles orange pâle qui virent au rouge foncé puis au gris-vert lorsqu''on les blesse. Paillet enroulé (paxille enroulé) : chapeau jaunâtre à brun ombré, luisant à l''humidité, jeune avec une marge feutrée longtemps enroulée, devenant nettement déprimé en entonnoir avec l''âge ; lamelles ocre-jaunâtre à brun olive, fines et serrées, décurrentes et détachables, qui brunissent FORTEMENT en brun rouille à noirâtre à la pression ou au toucher (les lamelles du lactaire ne brunissent pas en rouille). Les deux peuvent paraître en entonnoir et brun orangé -> d''où la confusion.','Lactaire de l''épicéa : doux, fruité-épicé (saveur légèrement amère). Paillet enroulé : aigrelet et discret ; l''odeur n''est PAS un critère de distinction fiable — le test du lait et le test de pression des lamelles sont décisifs.','Recouvrement existant : le paillet enroulé est un partenaire mycorhizien, entre autres, de l''épicéa (mais aussi du pin, du bouleau, du hêtre, du charme) et pousse dans le même sol acide de forêt de conifères/forêt mixte où le lactaire de l''épicéa apparaît auprès de l''épicéa. L''habitat ne permet PAS une distinction fiable.','Caractère secondaire, ne séparant pas nettement : lactaire de l''épicéa, selon les sources, crème à ocre pâle à brun ocracé ; paillet enroulé nettement brun argile à brun rouille. Les couleurs se chevauchent vers l''ocre — donc à utiliser seulement comme preuve complémentaire, pas comme critère principal. Le test du lait reste décisif. En cas de doute, prendre une sporée.','Toujours faire le test du lait : couper à frais et vérifier l''écoulement de lait. Si AUCUN lait ne s''écoule, ce n''est pas un lactaire — le paillet enroulé est dépourvu de lait et peut, par le syndrome cumulatif de Paxillus (anémie hémolytique, insuffisance rénale), devenir mortel même après des années de consommation. Les lactaires, eux, libèrent un lait orange/rouge carotte qui vire au rouge vineux. Règle de base : ne récolter que les lactaires à lait rouge/orange — jamais à lait clair/blanc ni totalement dépourvus de lait.','{"TEST DU LAIT (décisif, vérifié) : le lactaire de l''épicéa libère à la coupe un lait orange/rouge carotte qui vire au rouge vineux en 15-20 min (puis au gris-vert) ; le paillet enroulé ne libère AUCUN lait/liquide — aucun lait du tout = NE JAMAIS manger lorsqu''on s''attend à un lactaire.","Test de pression des lamelles (vérifié) : les lamelles du paillet se colorent fortement en brun rouille à noirâtre sous la pression et se détachent du chapeau ; les lamelles du lactaire sont cassantes, solidement attachées au chapeau et virent au rouge foncé/gris-vert lorsqu''on les blesse, pas au brun rouille.","Marge du chapeau & forme : le paillet a une marge longuement feutrée-enroulée et un chapeau brun olive luisant ; le chapeau du lactaire est orange à taches vertes, sans marge durablement feutrée-enroulée.","Sporée (complément, pas fiable à elle seule) : lactaire crème à ocre vs paillet brun argile/rouille — chevauchement vers l''ocre, donc seulement à titre complémentaire."}','t'),
('lactarius_deterrimus','paxillus_involutus','it','Lactarius deterrimus (lattario degli abeti): cappello da rosso-arancio a bruno-arancio, con l''età/in caso di gelo macchiato di verde sporco, lamelle arancio pallido che, se lese, diventano da rosso scuro a grigio-verde. Paxillus involutus (paxillo): cappello da giallastro a bruno-umbra, lucido se umido, da giovane con margine a lungo arrotolato e feltroso, da vecchio nettamente depresso a imbuto; lamelle da ocra-giallastre a oliva-brune, sottili e fitte, decorrenti e separabili, che a pressione/contatto si colorano FORTEMENTE di bruno-ruggine fino a bruno-nero (le lamelle del lattario non diventano bruno-ruggine). Entrambi possono apparire a imbuto e bruno-arancio -> da qui la confusione.','Lactarius deterrimus: mite, fruttato-speziato (sapore leggermente amaro). Paxillus involutus: acidulo-insignificante; l''odore NON è un carattere distintivo affidabile — la prova del latte e la prova di pressione sulle lamelle sono decisive.','Sovrapposizione presente: il Paxillus involutus è partner micorrizico tra l''altro dell''abete rosso (anche pino, betulla, faggio, carpino) e cresce nello stesso terreno acido di bosco di conifere/misto in cui il Lactarius deterrimus compare presso l''abete rosso. L''habitat NON separa in modo affidabile.','Carattere secondario, non nettamente distintivo: il Lactarius deterrimus, a seconda della fonte, da crema a ocra pallido fino a bruno-ocraceo; il Paxillus involutus nettamente da bruno-argilla a bruno-ruggine. I colori si sovrappongono verso l''ocra — quindi solo come prova aggiuntiva, non come criterio principale. Resta decisiva la prova del latte. In caso di dubbio prelevare la sporata.','Fare sempre la prova del latte: tagliare il fungo fresco e verificare la fuoriuscita di latte. Se NON esce latte, non è un lattario — il Paxillus involutus è privo di latte e, attraverso la sindrome cumulativa da Paxillus (anemia emolitica, insufficienza renale), può diventare pericoloso per la vita anche dopo anni di consumo. I lattari invece emettono latte arancio/rosso-carota che vira al rosso-vino. Regola pratica: raccogliere solo lattari con latte rosso/arancio — mai con latte chiaro/bianco o del tutto privo di latte.','{"PROVA DEL LATTE (decisiva, verificata): il Lactarius deterrimus al taglio emette latte arancio/rosso-carota che in 15-20 min vira al rosso-vino (poi grigio-verde); il Paxillus involutus NON emette alcun latte/liquido — nessun latte = MAI mangiare, se ci si aspetta un lattario.","Prova di pressione sulle lamelle (verificata): le lamelle del Paxillus a pressione si colorano fortemente da bruno-ruggine a bruno-nero e si lasciano staccare dal cappello; le lamelle del lattario sono fragili, saldamente unite al cappello e, se lese, diventano rosso scuro/grigio-verde, non bruno-ruggine.","Margine del cappello e forma: il Paxillus ha margine del cappello a lungo arrotolato e feltroso e cappello bruno-oliva lucido; il cappello del lattario è arancio con macchie verdi, senza arrotolamento feltroso permanente del margine.","Sporata (aggiuntiva, non affidabile da sola): lattario da crema a ocra vs. Paxillus da bruno-argilla a bruno-ruggine — si sovrappongono verso l''ocra, quindi solo a complemento."}','t'),
('lactarius_rufus','lactarius_helvus','en','Maggi milkcap (helvus) pale ochre-grey-brown with watery-colourless milk; rufous milkcap (rufus) deep red-brown with white milk.','The Maggi milkcap smells characteristically of Maggi/lovage (especially when dried); the rufous is practically odourless.','Maggi milkcap in bogs/wet Sphagnum, the rufous in drier acidic coniferous forest.','Both cream-coloured - no distinguishing feature.','Watery-colourless instead of white milk plus Maggi smell = Maggi milkcap, leave it. Do not eat any milkcaps with clear/watery milk.','{"Maggi milkcap (toxic) smells intensely of Maggi/lovage when drying - a unique feature; rufous milkcap odourless to faint","Maggi milkcap with an ochre-grey-brown, finely velvety, often dry cap and WATERY, colourless milk; the rufous with a deep red-brown cap and white milk","Maggi milkcap grows in bog/Sphagnum under pine/birch, the rufous in acidic coniferous forest","Taste rufous burning-acrid (inedible), Maggi milkcap mild - so taste is no protection here"}','f'),
('lactarius_rufus','lactarius_helvus','es','Lactario con olor a apio de monte (helvus) ocre-gris-pardo pálido con leche acuosa-incolora; lactario rojizo (rufus) pardo-rojizo intenso con leche blanca.','El lactario con olor a apio de monte huele característicamente a Maggi/levístico (sobre todo seco); el rojizo es prácticamente inodoro.','Lactario con olor a apio de monte en turberas/Sphagnum húmedo, el rojizo en bosque de coníferas ácido más seco.','Ambos de color crema - ningún carácter distintivo.','Leche acuosa-incolora en lugar de blanca más olor a Maggi = lactario con olor a apio de monte, dejarlo. No consumir ningún lactario con leche clara/acuosa.','{"Lactario con olor a apio de monte (tóxico) huele intensamente al secarse a Maggi/levístico - carácter único; lactario rojizo inodoro a débilmente oloroso","Lactario con olor a apio de monte con sombrero ocre-gris-pardo, finamente aterciopelado, a menudo seco, y leche ACUOSA, incolora; el rojizo con sombrero pardo-rojizo intenso y leche blanca","Lactario con olor a apio de monte crece en turbera/Sphagnum bajo pino/abedul, el rojizo en bosque de coníferas ácido","Sabor del rojizo ardiente-acre (no comestible), del lactario con olor a apio de monte suave - por eso el sabor aquí no protege"}','f'),
('lactarius_rufus','lactarius_helvus','fr','Lactaire à odeur de chicorée ocre-gris-brun pâle avec un lait aqueux-incolore ; lactaire roux fortement brun-rouge avec un lait blanc.','Lactaire à odeur de chicorée sent de façon caractéristique le Maggi/livèche (surtout séché) ; le roux pratiquement inodore.','Lactaire à odeur de chicorée dans les tourbières/sphaigne humide, le roux en forêt de conifères acide plus sèche.','Les deux crème — pas un critère de séparation.','Lait aqueux-incolore au lieu de blanc plus odeur de Maggi = lactaire à odeur de chicorée, laisser sur place. Ne pas consommer les lactaires à lait clair/aqueux.','{"Lactaire à odeur de chicorée/odeur de Maggi (toxique) sent intensément le Maggi/livèche au séchage — caractère unique ; lactaire roux inodore à faible","Lactaire à odeur de chicorée à chapeau ocre-gris-brun, finement velouté, souvent sec, et lait AQUEUX, incolore ; le roux à chapeau fortement brun-rouge et lait blanc","Lactaire à odeur de chicorée pousse en tourbière/sphaigne sous pin/bouleau, le roux en forêt de conifères acide","Goût roux brûlant-âcre (non comestible), lactaire à odeur de chicorée doux — donc le goût n''est ici pas une protection"}','f'),
('lactarius_rufus','lactarius_helvus','it','Lattario con odore di levistico ocra-grigio-bruno pallido con latte acquoso-incolore; lattario dal latte rosso bruno-rosso vivo con latte bianco.','Il lattario con odore di levistico odora caratteristicamente di Maggi/levistico (soprattutto essiccato); il rosso è praticamente inodore.','Lattario con odore di levistico nelle torbiere/sfagni umidi, il rosso in bosco di conifere acido più asciutto.','Entrambi crema - nessun carattere distintivo.','Latte acquoso-incolore invece che bianco più odore di Maggi = lattario con odore di levistico, da lasciare. Non consumare alcun lattario a latte chiaro/acquoso.','{"Lattario con odore di levistico (tossico) odora intensamente nell''essiccazione di Maggi/levistico - carattere unico; lattario dal latte rosso inodore o debolmente odoroso","Lattario con odore di levistico con cappello ocra-grigio-bruno, finemente vellutato, spesso asciutto, e latte ACQUOSO, incolore; il rosso con cappello bruno-rosso vivo e latte bianco","Lattario con odore di levistico cresce in torbiera/sfagno sotto pino/betulla, il rosso in bosco di conifere acido","Sapore del rosso bruciante-acre (immangiabile), del lattario con odore di levistico mite - quindi il sapore qui non protegge"}','f'),
('lactarius_subdulcis','lactarius_blennius','en','Grey-green milkcap (blennius) with a slimy, greenish-grey, spotted cap; mild milkcap (subdulcis) with a dry, red-brown, unzoned cap.','Both inconspicuous; decisive is the acrid taste of the grey-green against the mild taste of the mild one.','Both under beech - habitat does not separate them; watch the cap surface (slimy vs dry) and the milk''s colour change.','Both cream to pale ochre - no reliable distinguishing feature.','Slimy grey-green cap + acrid milk drying greenish = toxic grey-green milkcap. Acrid milkcaps generally do not belong in the basket.','{"Grey-green milkcap (toxic) with a greasy-slimy, grey-olive-green cap, often with concentric spots; mild beech milkcap dry, red-brown to cinnamon-coloured","Milk of the grey-green white, drying grey-green in air and acrid/burning; milk of the mild white, mild to slightly bitterish, not changing colour","Grey-green distinctly larger and more robust, the mild one small and fragile","Taste grey-green acrid-scratchy, mild one mild-sweetish (hence the name)"}','f'),
('lactarius_subdulcis','lactarius_blennius','es','Lactario gris-verde (blennius) con sombrero viscoso, verde-grisáceo, manchado; lactario dulce (subdulcis) con sombrero seco, pardo-rojizo, no zonado.','Ambos insignificantes; decisivo es el sabor acre del gris-verde frente al suave del dulce.','Ambos bajo haya - el hábitat no los separa; observar la superficie del sombrero (viscosa vs seca) y el cambio de color de la leche.','Ambos crema a ocre pálido - ningún carácter distintivo fiable.','Sombrero gris-verde viscoso + leche acre que seca verdosa = lactario gris-verde tóxico. Los lactarios de leche acre en general no van en la cesta.','{"Lactario gris-verde (tóxico) con sombrero grasiento-viscoso, gris-verde oliva, a menudo con manchas concéntricas; lactario dulce del haya seco, pardo-rojizo a color canela","Leche del gris-verde blanca, que seca gris-verde al aire y acre/ardiente; leche del dulce blanca, suave a ligeramente amarga, sin cambiar de color","Gris-verde claramente más grande y más robusto, el dulce pequeño y frágil","Sabor gris-verde acre-raspante, dulce suave-dulzón (de ahí el nombre)"}','f'),
('lactarius_subdulcis','lactarius_blennius','fr','Lactaire muqueux à chapeau visqueux, gris-verdâtre, tacheté ; lactaire subdoux à chapeau sec, brun-rouge, non zoné.','Les deux discrets ; décisif est le goût âcre du muqueux contre le doux du subdoux.','Les deux sous le hêtre — l''habitat ne sépare pas ; faire attention à la surface du chapeau (visqueux vs. sec) et à la décoloration du lait.','Les deux crème à ocre pâle — pas un critère de séparation fiable.','Chapeau gris-vert visqueux + lait âcre séchant en vert = lactaire muqueux toxique. Les lactaires âcres n''ont en général pas leur place dans le panier.','{"Lactaire muqueux (toxique) à chapeau gluant-visqueux, gris-vert-olive, souvent à taches concentriques ; lactaire subdoux du hêtre sec, brun-rouge à cannelle","Lait du muqueux blanc, séchant gris-vert à l''air et âcre/brûlant ; lait du subdoux blanc, doux à légèrement amer, non décolorant","Muqueux nettement plus grand et plus robuste, subdoux petit et fragile","Goût muqueux âcre-râpeux, subdoux doux-subdoux (d''où le nom)"}','f'),
('lactarius_subdulcis','lactarius_blennius','it','Lattario grigio-verde con cappello viscido, verde-grigio, macchiato; lattario dolce con cappello asciutto, bruno-rosso, non zonato.','Entrambi insignificanti; decisivo è il sapore acre del grigio-verde contro quello mite del dolce.','Entrambi sotto faggio - l''habitat non distingue; osservare la superficie del cappello (viscida vs asciutta) e il viraggio del latte.','Entrambi crema fino a ocra pallido - nessun carattere distintivo affidabile.','Cappello grigio-verde viscido + latte acre che secca verdastro = lattario grigio-verde tossico. I lattari a latte acre in generale non vanno nel cesto.','{"Lattario grigio-verde (tossico) con cappello viscido-mucillaginoso, grigio-verde oliva, spesso con macchie concentriche; lattario dolce del faggio asciutto, bruno-rosso fino a color cannella","Latte del grigio-verde bianco, che secca grigio-verde all''aria e acre/bruciante; latte del dolce bianco, mite fino a leggermente amarognolo, non virante","Grigio-verde nettamente più grande e più robusto, dolce piccolo e fragile","Sapore grigio-verde acre-graffiante, dolce mite-dolciastro (da cui il nome)"}','f'),
('laetiporus_sulphureus','hapalopilus_nidulans','en','The sulphur polypore (chicken-of-the-woods) is, when young, a bright sulphur-yellow to orange and pale inside; the cinnamon bracket (Hapalopilus nidulans) is uniformly matt ochre, cinnamon to pinkish-brown throughout and clearly smaller (max. ~18 cm).','The smell is faint and unreliable in both; the mild taste of the poisonous fungus gives no warning — so NEVER rely on smell/taste, but do the KOH (potassium hydroxide) test.','The cinnamon bracket grows mostly on dead hardwood (oak, hazel); the sulphur polypore frequently in clustered brackets on (even living) hardwoods and fruit trees (oak, willow, black locust, plum).','The spore print is whitish in both polypores and barely checkable without collecting — so use the KOH test instead of the spore print.','Never collect brown/ochre polypores without testing them with potassium hydroxide (KOH): violet/lilac = poisonous cinnamon bracket, leave it. Only sulphur polypores growing young in bright sulphur-yellow to orange on hardwood, cooked and only the soft outer margin, are considered edible.','{"Cinnamon bracket (poisonous): KOH/potassium hydroxide on the pores or flesh → immediately strong violet/lilac (even on dried material). Sulphur polypore: no violet reaction. This is the most reliable distinguishing feature.","Colour of the sulphur polypore: when young bright sulphur-yellow to orange. Cinnamon bracket: at most dull ochre/leather-yellow when young, quickly turning cinnamon to pinkish/reddish-brown — never the bright sulphur-yellow-orange of the sulphur polypore.","The cinnamon bracket is the same cinnamon/pinkish-brown colour through and through (including the flesh/trama) and mostly small (bracket 3-12 cm, max. ~18 cm); the young sulphur polypore is whitish-yellow inside and grows clearly larger.","Growth site of the cinnamon bracket: mostly dead hardwood, readily oak and hazel; sulphur polypore often on (even living) hardwoods and fruit trees (oak, willow, black locust, plum, walnut).","Toxin: polyporic acid → after ~12 h latency central nervous disturbances, visual disturbances, vomiting, kidney/liver damage, violet urine — the mild taste gives NO warning, potentially fatal."}','f'),
('laetiporus_sulphureus','hapalopilus_nidulans','es','El políporo azufrado (pollo del bosque) es de joven de un amarillo azufre-anaranjado brillante y claro por dentro; el políporo canela (Hapalopilus nidulans) es de un tono uniformemente mate ocre, canela a pardo rosado en todo su cuerpo y claramente más pequeño (máx. ~18 cm).','El olor es débil y poco fiable en ambos; el sabor suave del hongo venenoso no advierte — por eso NUNCA fiarse del olor/sabor, sino hacer la prueba con potasa (KOH).','El políporo canela crece sobre todo en madera muerta de frondosas (roble, avellano); el políporo azufrado con frecuencia en ménsulas agrupadas sobre frondosas y árboles frutales (incluso vivos) (roble, sauce, robinia, ciruelo).','La esporada es blanquecina en ambos políporos y apenas comprobable sin recolectar — por eso usar la prueba KOH en lugar de la esporada.','Nunca recolectar políporos pardos/ocre sin probarlos con potasa (KOH): violeta/lila = políporo canela venenoso, dejarlo. Solo los políporos azufrados que crecen de jóvenes de un amarillo azufre-anaranjado brillante sobre frondosas, cocinados y solo el margen externo tierno, se consideran comestibles.','{"Políporo canela (venenoso): KOH/potasa sobre los poros o la carne → de inmediato violeta/lila intenso (incluso en material seco). Políporo azufrado: ninguna reacción violeta. Es el criterio de distinción más seguro.","Color del políporo azufrado: de joven amarillo azufre brillante a anaranjado. Políporo canela: a lo sumo de joven ocre/amarillo cuero apagado, vira pronto a canela y pardo rosado/rojizo — nunca el amarillo azufre-anaranjado brillante del políporo azufrado.","El políporo canela es de un mismo color canela/pardo rosado de parte a parte (incluida la trama) y por lo general pequeño (ménsula 3-12 cm, máx. ~18 cm); el políporo azufrado joven es blanquecino-amarillo por dentro y se vuelve claramente más grande.","Lugar de crecimiento del políporo canela: sobre todo madera muerta de frondosas, de buena gana roble y avellano; políporo azufrado a menudo sobre frondosas y árboles frutales (incluso vivos) (roble, sauce, robinia, ciruelo, nogal).","Toxina: ácido polipórico → tras ~12 h de latencia, trastornos del sistema nervioso central, trastornos visuales, vómitos, daños renales/hepáticos, orina violeta — el sabor suave NO advierte, posiblemente mortal."}','f'),
('laetiporus_sulphureus','hapalopilus_nidulans','fr','Le polypore soufré est jeune d''un jaune soufre-orange éclatant et clair à l''intérieur ; le polypore cannelle (Hapalopilus) est d''une teinte uniformément mate ocre, cannelle à brun rosé et nettement plus petit (max. ~18 cm).','L''odeur est faible et peu fiable chez les deux ; le goût doux du champignon vénéneux n''avertit pas — ne JAMAIS se fier à l''odeur/au goût, mais faire le test à la potasse (KOH).','Le polypore cannelle pousse surtout sur bois feuillu mort (chêne, noisetier) ; le polypore soufré fréquemment en touffes de consoles sur des feuillus et arbres fruitiers (même vivants) (chêne, saule, robinier, prunier).','La sporée est blanchâtre chez les deux polypores et à peine vérifiable sans récolte — utiliser donc le test KOH plutôt que la sporée.','Ne jamais récolter de polypores bruns/ocre sans les tester à la potasse (KOH) : violet/lilas = polypore cannelle vénéneux, à laisser. Seuls les polypores soufrés poussant jeunes d''un jaune soufre-orange éclatant sur feuillu, cuits et seulement la marge externe tendre, sont considérés comme comestibles.','{"Polypore cannelle (vénéneux) : KOH/potasse sur les pores ou la chair → immédiatement violet/lilas intense (même sur matériel sec). Polypore soufré : aucune réaction violette. C''est le critère de distinction le plus sûr.","Couleur du polypore soufré : jeune, jaune soufre éclatant à orange. Polypore cannelle : au mieux jeune ocre/jaune cuir terne, vire vite cannelle à brun rosé/rougeâtre — jamais le jaune soufre-orange éclatant du polypore soufré.","Le polypore cannelle est de part en part d''une même couleur cannelle/brun rosé (y compris la trame) et le plus souvent petit (console 3-12 cm, max. ~18 cm) ; le jeune polypore soufré est blanchâtre-jaune à l''intérieur et devient nettement plus grand.","Lieu de croissance du polypore cannelle : surtout bois feuillu mort, volontiers chêne et noisetier ; polypore soufré souvent sur feuillus et arbres fruitiers (même vivants) (chêne, saule, robinier, prunier, noyer).","Toxine : acide polyporique → après ~12 h de latence, troubles du système nerveux central, troubles visuels, vomissements, atteintes rénales/hépatiques, urine violette — le goût doux n''AVERTIT PAS, potentiellement mortel."}','f'),
('laetiporus_sulphureus','hapalopilus_nidulans','it','Il poliporo zolfino da giovane è di un giallo zolfo-arancio brillante e chiaro all''interno; il poliporo cannella (Hapalopilus) è di una tinta uniformemente opaca ocra, cannella fino a bruno rosato e nettamente più piccolo (max. ~18 cm).','L''odore è debole e inaffidabile in entrambi; il sapore mite del fungo velenoso non avverte — NON affidarsi MAI a odore/sapore, ma fare il test con la potassa (KOH).','Il poliporo cannella per lo più su legno di latifoglie morto (quercia, nocciolo); il poliporo zolfino spesso a ciuffi di mensole su latifoglie e alberi da frutto (anche vivi) (quercia, salice, robinia, susino).','La sporata è biancastra in entrambi i polipori e quasi non verificabile senza raccolta — usare quindi il test KOH invece della sporata.','Non raccogliere mai polipori bruni/ocra senza testarli con la potassa (KOH): viola/lilla = poliporo cannella velenoso, da lasciare. Solo i polipori zolfini che crescono da giovani di un giallo zolfo-arancio brillante su latifoglie, cotti e soltanto il margine esterno tenero, sono considerati commestibili.','{"Poliporo cannella (velenoso): KOH/potassa sui pori o sulla carne → subito viola/lilla intenso (anche su materiale secco). Poliporo zolfino: nessuna reazione viola. È il criterio di distinzione più sicuro.","Colore del poliporo zolfino: da giovane giallo zolfo brillante fino all''arancio. Poliporo cannella: al massimo da giovane ocra/giallo cuoio spento, vira presto al cannella fino al bruno rosato/rossastro — mai il giallo zolfo-arancio brillante del poliporo zolfino.","Il poliporo cannella è da parte a parte dello stesso colore cannella/bruno rosato (anche la trama) e per lo più piccolo (mensola 3-12 cm, max. ~18 cm); il giovane poliporo zolfino è biancastro-giallo all''interno e diventa nettamente più grande.","Luogo di crescita del poliporo cannella: per lo più legno di latifoglie morto, volentieri quercia e nocciolo; poliporo zolfino spesso su latifoglie e alberi da frutto (anche vivi) (quercia, salice, robinia, susino, noce).","Tossina: acido poliporico → dopo ~12 h di latenza disturbi del sistema nervoso centrale, disturbi della vista, vomito, danni renali/epatici, urina viola — il sapore mite NON avverte, potenzialmente mortale."}','f'),
('lepista_glaucocana','clitocybe_fragrans','en','Large blewit (Lepista) with a lavender-violet flush vs. small pale grey fragrans.','The blewit smells pleasantly perfumed; fragrans smells of aniseed.','Both in woodland in late autumn; habitat is not a reliable distinguishing feature.','Lavender blewit with a pinkish-white spore print, fragrans white.','On principle, discard small, aniseed-smelling, white-spored funnel caps because of muscarine.','{"The lavender-coloured blewit is distinctly larger, fleshier and flushed with pale violet-lavender; fragrans is small, thin-fleshed and pale grey-brown with no violet tones.","fragrans smells of aniseed and contains muscarine; the lavender blewit smells pleasantly perfumed and is edible.","The gills of the blewit are emarginate-adnexed and easily pushed off; fragrans gills are decurrent.","The spore print distinguishes: blewit pinkish-white, fragrans white."}','f'),
('lepista_glaucocana','clitocybe_fragrans','es','Gran lepista (pie azul) con velo lavanda-violeta frente a fragrans pequeño y gris pálido.','La lepista huele agradablemente perfumada; fragrans huele a anís.','Ambos en el bosque a finales de otoño; el hábitat no es un carácter distintivo fiable.','Lepista lavanda con esporada blanco-rosada, fragrans blanca.','Descartar por principio los pequeños clitocibes de esporada blanca con olor a anís, a causa de la muscarina.','{"La lepista de color lavanda es claramente más grande, más carnosa y con velo lavanda-violeta pálido; fragrans es pequeño, de carne delgada y gris-pardo pálido sin tonos violetas.","fragrans huele a anís y contiene muscarina; la lepista lavanda huele agradablemente perfumada y es comestible.","Las láminas de la lepista son escotadas-adnadas y se desprenden fácilmente; las láminas de fragrans son decurrentes.","La esporada distingue: lepista blanco-rosada, fragrans blanca."}','f'),
('lepista_glaucocana','clitocybe_fragrans','fr','Grand lépiste teinté de lavande-violet vs. petit fragrans gris pâle.','Lépiste agréablement parfumé ; fragrans d''anis.','Les deux à la fin de l''automne en forêt ; pas de critère de séparation fiable via l''habitat.','Lépiste lavande à sporée rose-blanchâtre, fragrans blanche.','Écarter en général les petits clitocybes à spores blanches, à odeur d''anis, à cause de la muscarine.','{"Le lépiste couleur lavande est nettement plus grand, plus charnu et teinté de violet-lavande pâle ; fragrans est petit, à chair mince et gris-brun pâle sans teintes violettes.","fragrans sent l''anis et contient de la muscarine ; le lépiste lavande sent agréablement parfumé et est comestible.","Lamelles du lépiste échancrées-adnées et facilement détachables ; lamelles de fragrans décurrentes.","La sporée sépare : lépiste rose-blanchâtre, fragrans blanche."}','f'),
('lepista_glaucocana','clitocybe_fragrans','it','Grande lepista soffusa di lavanda-violetto contro fragrans piccolo e grigio pallido.','La lepista profuma gradevolmente; fragrans odora di anice.','Entrambi nel bosco nel tardo autunno; l''habitat non è un carattere distintivo affidabile.','Lepista lavanda con sporata bianco-rosata, fragrans con sporata bianca.','Scartare per principio i piccoli clitocybe a sporata bianca con odore di anice, a causa della muscarina.','{"La lepista color lavanda è nettamente più grande, più carnosa e soffusa di lavanda-violetto pallido; fragrans è piccolo, a carne sottile e grigio-bruno pallido senza toni violetti.","fragrans odora di anice e contiene muscarina; la lepista lavanda profuma gradevolmente ed è commestibile.","Le lamelle della lepista sono smarginate-adnate e si staccano facilmente; le lamelle di fragrans sono decorrenti.","La sporata distingue: lepista bianco-rosata, fragrans bianca."}','f'),
('lepista_glaucocana','cortinarius_traganus','en','Both are a pale lilac-lavender, but C. traganus has a clavate stem with a veil zone and ochre rust-brown gills, while Lepista glaucocana has pale, removable gills without a veil.','Lepista glaucocana smells mild and pleasant; C. traganus repulsively goaty.','C. traganus in coniferous-forest litter; Lepista glaucocana in deciduous/mixed and coniferous forest at nutrient-rich sites, often at higher elevations.','Lepista glaucocana: pale pink-cream. C. traganus: rust-brown — the spore print separates reliably.','Rust-brown spore print or veil remnants on the stem = Cortinarius = do not eat. Never rely on colour alone.','{"Lepista glaucocana without veil/cortina; C. traganus with a fibrillose veil zone on the clavate stem.","Spore print: Lepista glaucocana pale pink-cream, C. traganus rust-brown.","Smell: Lepista glaucocana mild-pleasant; C. traganus goaty, unpleasant.","Gills: C. traganus young saffron-ochre, never blue-violet, later rust-brown; Lepista glaucocana whitish to pale lavender/lilac, easily removable."}','f'),
('lepista_glaucocana','cortinarius_traganus','es','Ambos son de un lila-lavanda pálido, pero C. traganus tiene un pie claviforme con una zona velada y láminas ocre pardo-herrumbre, mientras que Lepista glaucocana tiene láminas claras, separables, sin velo.','Lepista glaucocana huele suave y agradable; C. traganus repugnantemente a macho cabrío.','C. traganus en la hojarasca de bosques de coníferas; Lepista glaucocana en bosque de frondosas/mixto y de coníferas en lugares ricos en nutrientes, a menudo en altitudes elevadas.','Lepista glaucocana: rosa-crema pálido. C. traganus: pardo-herrumbre — la esporada separa de forma fiable.','Esporada pardo-herrumbre o restos de velo en el pie = Cortinarius = no consumir. Nunca te fíes solo del color.','{"Lepista glaucocana sin velo/cortina; C. traganus con una zona de velo fibrillosa en el pie claviforme.","Esporada: Lepista glaucocana rosa-crema pálido, C. traganus pardo-herrumbre.","Olor: Lepista glaucocana suave-agradable; C. traganus a macho cabrío/cabra, desagradable.","Láminas: C. traganus joven azafrán-ocre, nunca azul-violeta, luego pardo-herrumbre; Lepista glaucocana blanquecina hasta lavanda/lila pálido, fácilmente separable."}','f'),
('lepista_glaucocana','cortinarius_traganus','fr','Les deux lilas-lavande pâle, mais C. traganus a un pied en massue avec une zone de voile et des lamelles ocre-brun rouille, Lepista glaucocana a des lamelles claires, détachables, sans voile.','Lepista glaucocana sent doux et agréable ; C. traganus répugnant, de bouc.','C. traganus dans la litière de forêt de conifères ; Lepista glaucocana en forêt de feuillus/mixte et de conifères sur stations riches en nutriments, souvent en altitude.','Lepista glaucocana : rose-crème pâle. C. traganus : brun rouille – la sporée sépare sûrement.','Sporée brun rouille ou restes de voile au pied = cortinaire = ne pas manger. Ne te fie jamais à la seule couleur.','{"Lepista glaucocana sans voile/cortine ; C. traganus avec une zone de voile fibrilleuse au pied en massue.","Sporée : Lepista glaucocana rose-crème pâle, C. traganus brun rouille.","Odeur : Lepista glaucocana douce-agréable ; C. traganus de bouc/chèvre désagréable.","Lamelles : C. traganus jeune safran-ocre, jamais bleu-violet, plus tard brun rouille ; Lepista glaucocana blanchâtre à lavande/lilas pâle, facilement détachables."}','f'),
('lepista_glaucocana','cortinarius_traganus','it','Entrambi sono di un lilla-lavanda pallido, ma C. traganus ha un gambo clavato con zona velata e lamelle ocra-bruno ruggine, mentre Lepista glaucocana ha lamelle chiare, asportabili, prive di velo.','Lepista glaucocana ha odore mite e gradevole; C. traganus odore ripugnante di becco.','C. traganus nella lettiera dei boschi di conifere; Lepista glaucocana in boschi di latifoglie/misti e di conifere in stazioni ricche di nutrienti, spesso in quota.','Lepista glaucocana: rosa-crema pallido. C. traganus: bruno-ruggine — la sporata separa con sicurezza.','Sporata bruno-ruggine o residui di velo sul gambo = Cortinarius = non consumare. Non fidarti mai del solo colore.','{"Lepista glaucocana senza velo/cortina; C. traganus con zona velata fibrillosa sul gambo clavato.","Sporata: Lepista glaucocana rosa-crema pallido, C. traganus bruno-ruggine.","Odore: Lepista glaucocana mite-gradevole; C. traganus di becco/caprino, sgradevole.","Lamelle: C. traganus da giovane zafferano-ocra, mai blu-violetto, poi bruno-ruggine; Lepista glaucocana biancastra fino a lavanda/lilla pallido, facilmente asportabile."}','f'),
('lepista_nuda','cortinarius_orellanus','en','Cortinarius orellanus: yellow-/red-brown, slightly umbonate, finely scaly-fibrous cap, yellow-cinnamon-brown gills, rust-brown veil fibres on the stem. Lepista nuda: uniformly violet, smooth domed cap without a veil.','Lepista nuda distinctly aromatic-sweet (perfume-like). orellanus smells faintly radish-like, without the sweet scent. Smell only as a clue, never reliable on its own.','orellanus: deciduous/mixed forest with oak and beech (mycorrhiza), summer to late autumn, rather rare/warmth-favoured. Lepista nuda: nutrient-rich litter, hedges, compost, very late in the season.','Lepista nuda pale pink-whitish; Cortinarius orellanus rust-brown. A rust-brown print rules out Lepista nuda.','A spore print is mandatory: rust-brown = webcap, life-threatening. Cortinarius orellanus is considered one of the most dangerous mushrooms in Europe (orellanine, latency up to 14 days, kidney and liver damage). A cobweb-like veil on the young mushroom or rust-brown stem fibres = never eat. When in the slightest doubt, discard.','{"Spore print (most reliable distinguisher from the entire webcap genus): Lepista nuda pale pink-whitish vs. Cortinarius orellanus rust-brown. A rust-brown print rules out Lepista nuda.","Cortina/veil: orellanus has a (when young yellowish) cobweb-like veil with rust-brown veil remnants on the stem; Lepista nuda has no velum whatsoever.","Cap colour: orellanus yellow- to red-brown/foxy (NEVER violet), often slightly umbonate; Lepista nuda uniformly violet in youth.","Gill colour: orellanus yellow-/cinnamon-brown, distantly spaced, emarginate (notched) attachment; Lepista nuda violet/violet-pink and staying pale."}','t'),
('lepista_nuda','cortinarius_orellanus','es','Cortinarius orellanus: sombrero de color pardo amarillento a pardo rojizo, ligeramente mamelonado, finamente escamoso-fibroso; láminas de color pardo amarillo-canela; fibras del velo de color pardo ferruginoso en el pie. Lepista nuda: completamente violeta, sombrero liso y convexo sin velo.','Lepista nuda con olor claramente aromático-dulzón (como a perfume). Cortinarius orellanus huele débilmente a rábano, sin el aroma dulzón. El olor solo como indicio, nunca fiable por sí solo.','Cortinarius orellanus: bosque de frondosas/mixto junto a roble y haya (micorriza), de verano a finales de otoño, más bien raro/favorecido por el calor. Lepista nuda: hojarasca rica en nutrientes, setos, compost, muy tarde en la temporada.','Lepista nuda de color rosa-blanquecino pálido; Cortinarius orellanus de color pardo ferruginoso. Una esporada pardo ferruginosa excluye a Lepista nuda.','La esporada es obligatoria: pardo ferruginoso = Cortinarius, mortalmente peligroso. Cortinarius orellanus está considerado uno de los hongos más peligrosos de Europa (orellanina, latencia de hasta 14 días, daños renales y hepáticos). Un velo aracnoideo en el ejemplar joven o fibras pardo ferruginosas en el pie = no comer nunca. Ante la menor duda, descartar.','{"Esporada (el discriminante más fiable frente a todo el género Cortinarius): Lepista nuda rosa-blanquecino pálido frente a Cortinarius orellanus pardo ferruginoso. Una esporada pardo ferruginosa excluye a Lepista nuda.","Cortina/velo: Cortinarius orellanus tiene un velo aracnoideo (de joven amarillento) con restos del velo pardo ferruginosos en el pie; Lepista nuda no tiene velo alguno.","Color del sombrero: Cortinarius orellanus pardo amarillento a pardo rojizo/zorruno (NUNCA violeta), a menudo ligeramente mamelonado; Lepista nuda completamente violeta en su juventud.","Color de las láminas: Cortinarius orellanus pardo amarillo/canela, separadas, escotado-adheridas; Lepista nuda violeta/violeta-rosado y manteniéndose clara."}','t'),
('lepista_nuda','cortinarius_orellanus','fr','Cortinarius orellanus : chapeau brun jaunâtre/brun rougeâtre, légèrement mamelonné, finement squameux-fibrilleux, lamelles brun jaune-cannelle, fibrilles de voile brun rouille sur le pied. Lepista nuda : entièrement violet, chapeau lisse et bombé sans voile.','Lepista nuda nettement aromatique-sucré (parfumé). orellanus a une odeur faiblement raphanoïde (de radis), sans parfum sucré. L''odeur seulement comme indice, jamais fiable à elle seule.','orellanus : forêt de feuillus/forêt mixte auprès du chêne et du hêtre (mycorhize), de l''été à la fin de l''automne, plutôt rare/thermophile. Lepista nuda : litière riche en nutriments, haies, compost, très tard dans la saison.','Lepista nuda rose-blanchâtre pâle ; Cortinarius orellanus brun rouille. Une sporée brun rouille exclut Lepista nuda.','La prise d''une sporée est obligatoire : brun rouille = cortinaire, danger mortel. Cortinarius orellanus est considéré comme l''un des champignons les plus dangereux d''Europe (orellanine, latence jusqu''à 14 jours, lésions rénales et hépatiques). Un voile arachnéen sur le jeune champignon ou des fibrilles brun rouille sur le pied = ne jamais manger. Au moindre doute, jeter.','{"Sporée (critère le plus fiable face à tout le genre des cortinaires) : Lepista nuda rose-blanchâtre pâle vs Cortinarius orellanus brun rouille. Une sporée brun rouille exclut Lepista nuda.","Cortine/voile : orellanus possède un voile arachnéen (jaunâtre quand jeune) avec des restes de voile brun rouille sur le pied ; Lepista nuda n''a aucun velum.","Couleur du chapeau : orellanus brun jaune à brun rougeâtre/fauve (JAMAIS violet), souvent légèrement mamelonné ; Lepista nuda entièrement violet dans la jeunesse.","Couleur des lamelles : orellanus brun jaune/cannelle, espacées, échancrées-adnées ; Lepista nuda violet/violet-rose et restant clair."}','t'),
('lepista_nuda','cortinarius_orellanus','it','Cortinarius orellanus: cappello da giallo a rosso-bruno, leggermente umbonato, finemente squamoso-fibrilloso, lamelle da giallo a bruno-cannella, fibre del velo bruno-ruggine sul gambo. Lepista nuda: interamente violetta, cappello liscio e convesso senza velo.','Lepista nuda nettamente aromatica-dolciastra (profumata). orellanus odora debolmente di ravanello, senza profumo dolciastro. L''odore solo come indizio, mai affidabile da solo.','orellanus: bosco di latifoglie/misto presso quercia e faggio (micorriza), dall''estate al tardo autunno, piuttosto raro/in stazioni calde. Lepista nuda: lettiera ricca di nutrienti, siepi, compost, molto tardi nella stagione.','Lepista nuda da rosa pallido a biancastro; Cortinarius orellanus bruno-ruggine. Una sporata bruno-ruggine esclude la Lepista nuda.','La sporata è obbligatoria: bruno-ruggine = cortinario, pericoloso per la vita. Cortinarius orellanus è considerato uno dei funghi più pericolosi d''Europa (orellanina, latenza fino a 14 giorni, danni a reni e fegato). Un velo a ragnatela sul fungo giovane o fibre bruno-ruggine sul gambo = mai mangiare. Al minimo dubbio scartare.','{"Sporata (il distintivo più affidabile per l''intero genere dei cortinari): Lepista nuda da rosa pallido a biancastro vs. Cortinarius orellanus bruno-ruggine. Una sporata bruno-ruggine esclude la Lepista nuda.","Cortina/velo: orellanus ha un velo a ragnatela (da giovane giallastro) con resti del velo bruno-ruggine sul gambo; Lepista nuda non ha alcun velo (velum).","Colore del cappello: orellanus da giallo a rosso-bruno/fulvo (MAI violetto), spesso leggermente umbonato; Lepista nuda in gioventù interamente violetta.","Colore delle lamelle: orellanus da giallo a bruno-cannella, distanziate, attaccate in modo smarginato; Lepista nuda violetta/violetto-rosa e che rimane chiara."}','t'),
('lepista_nuda','cortinarius_rubellus','en','Lepista nuda: when young uniformly violet throughout (cap, gills, stem), domed smooth cap without a pointed umbo, no veil. Cortinarius rubellus: rust- to foxy-orange cap with a pointed (umbonate) apex, finely felty-fibrous, cinnamon-/rust-brown gills, rust-brown veil fibres on the stem.','Lepista nuda smells aromatic-sweet (perfume-like, reminiscent of biscuit/orange blossom). Cortinarius rubellus smells faintly radish-like, without the typical sweet scent. Smell is only a clue, NEVER reliable on its own — spore print + cortina are decisive.','Webcap (Raukopf): acidic coniferous forests (spruce/spruce-pine mixed forest), boggy-moist and montane sites, Aug-Oct. Wood blewit (Roetelritterling): nutrient-rich deciduous/mixed-forest litter, hedges, compost heaps, very late in the season up to after the first frosts.','Decisive: Lepista nuda = pale pink-whitish/cream-pink spore print. Cortinarius rubellus = rust-brown spore print. A rust-brown print reliably rules out Lepista nuda.','ALWAYS take a spore print (cap overnight on white paper). Pale pink-whitish = possibly Lepista nuda. Rust-brown OR a cobweb-like veil (cortina) on the young mushroom = STOP, webcap — never eat. Orellanine poisoning only manifests after 3-14 days, by which point the kidney is already irreversibly damaged. When in the slightest doubt, do not eat.','{"Spore print (most reliable separation check): Lepista nuda pale pink-whitish/cream-pink — EVERY Cortinarius/webcap has RUST-BROWN spore powder. A rust-brown print reliably rules out the wood blewit.","Cortina/veil: the webcap as a young mushroom has a cobweb-like veil (cortina) between the cap margin and the stem; veil remnants on the stem stain rust-brown. The wood blewit NEVER has a veil — no velum at all.","Cap shape/colour: Cortinarius rubellus rust- to cinnamon-/foxy-orange with a pointed, umbonate apex; Lepista nuda when young uniformly violet, domed cap without a pointed umbo.","Gill colour: wood blewit violet/violet-pink and staying pale; webcap cinnamon-/rust-brown, distantly spaced, emarginate (notched) attachment.","Habitat: webcap near conifers (spruce) on acidic, often boggy-moist soil in the mountains; wood blewit in nutrient-rich deciduous/mixed-forest litter, hedges, compost heaps, late in the season up to after frost."}','t'),
('lepista_nuda','cortinarius_rubellus','es','Lepista nuda: de joven completamente violeta (sombrero, láminas, pie), sombrero convexo y liso sin mamelón puntiagudo, sin velo. Cortinarius rubellus: sombrero de color anaranjado herrumbre a anaranjado zorruno con vértice puntiagudo (mamelonado), finamente afieltrado-fibroso, láminas de color pardo canela/herrumbre, fibras del velo de color pardo ferruginoso en el pie.','Lepista nuda huele aromático-dulzón (como a perfume, recordando a galleta/flor de naranjo). Cortinarius rubellus huele débilmente a rábano, sin el típico aroma dulzón. El olor es solo un indicio, NUNCA fiable por sí solo: lo decisivo son la esporada + la cortina.','Cortinarius rubellus: bosques de coníferas ácidos (abeto rojo/bosque mixto de abeto rojo y pino), ubicaciones turbosas-húmedas y de montaña, de agosto a octubre. Lepista nuda: hojarasca de bosque de frondosas/mixto rica en nutrientes, setos, montones de compost, muy tarde en la temporada hasta después de las primeras heladas.','Decisivo: Lepista nuda = esporada de color rosa-blanquecino pálido/crema-rosado. Cortinarius rubellus = esporada de color pardo ferruginoso. Una esporada pardo ferruginosa excluye con seguridad a Lepista nuda.','Toma SIEMPRE una esporada (sombrero sobre papel blanco durante la noche). Rosa-blanquecino pálido = posiblemente Lepista nuda. Pardo ferruginoso O un velo aracnoideo (cortina) en el ejemplar joven = ALTO, es un Cortinarius: no comer nunca. La intoxicación por orellanina se manifiesta solo tras 3-14 días, cuando el riñón ya está irreversiblemente dañado. Ante la menor duda, no comer.','{"Esporada (la prueba de separación más segura): Lepista nuda rosa-blanquecino pálido/crema-rosado; CUALQUIER Cortinarius tiene esporada PARDO FERRUGINOSA. Una esporada pardo ferruginosa excluye con seguridad a Lepista nuda.","Cortina/velo: Cortinarius rubellus tiene de joven un velo aracnoideo (cortina) entre el margen del sombrero y el pie; los restos del velo en el pie se tiñen de pardo ferruginoso. Lepista nuda NUNCA tiene velo, ningún velo en absoluto.","Forma/color del sombrero: Cortinarius rubellus anaranjado herrumbre a anaranjado canela/zorruno con vértice puntiagudo y mamelonado; Lepista nuda de joven completamente violeta, sombrero convexo sin mamelón puntiagudo.","Color de las láminas: Lepista nuda violeta/violeta-rosado y manteniéndose clara; Cortinarius rubellus pardo canela/herrumbre, separadas, escotado-adheridas.","Hábitat: Cortinarius rubellus junto a coníferas (abeto rojo) sobre suelo ácido, a menudo turboso-húmedo, en zonas de montaña; Lepista nuda en hojarasca de bosque de frondosas/mixto rica en nutrientes, setos, montones de compost, tarde en la temporada hasta después de las heladas."}','t'),
('lepista_nuda','cortinarius_rubellus','fr','Lepista nuda : jeune, entièrement violet (chapeau, lamelles, pied), chapeau bombé et lisse sans mamelon pointu, sans voile. Cortinarius rubellus : chapeau orange rouille à orange roux avec un sommet pointu (mamelonné), finement feutré-fibrilleux, lamelles brun cannelle/rouille, fibrilles de voile brun rouille sur le pied.','Lepista nuda sent l''aromatique-sucré (parfumé, rappelant le biscuit/la fleur d''oranger). Cortinarius rubellus a une faible odeur raphanoïde (de radis), sans le parfum sucré typique. L''odeur n''est qu''un indice, JAMAIS fiable à elle seule — la sporée + la cortine sont décisives.','Cortinaire (rubellus) : forêts de conifères acides (épicéa/forêt mixte épicéa-pin), stations tourbeuses-humides et de montagne, août-octobre. Pied bleu (lepista) : litière de forêt de feuillus/mixte riche en nutriments, haies, tas de compost, très tard dans la saison jusqu''après les premières gelées.','Décisif : Lepista nuda = sporée rose-blanchâtre pâle/rose crème. Cortinarius rubellus = sporée brun rouille. Une empreinte brun rouille exclut Lepista nuda avec certitude.','TOUJOURS prendre une sporée (chapeau posé une nuit sur du papier blanc). Rose-blanchâtre pâle = possiblement Lepista nuda. Brun rouille OU un voile arachnéen (cortine) sur le jeune champignon = STOP, cortinaire — ne jamais manger. L''intoxication par l''orellanine ne se manifeste qu''après 3-14 jours, alors le rein est déjà irréversiblement endommagé. Au moindre doute, ne pas manger.','{"Sporée (test de séparation le plus sûr) : Lepista nuda rose-blanchâtre pâle/rose crème — TOUT cortinaire a une sporée BRUN ROUILLE. Une empreinte brun rouille exclut le pied bleu avec certitude.","Cortine/voile : le cortinaire a, à l''état jeune, un voile arachnéen (cortine) entre la marge du chapeau et le pied ; les restes de voile sur le pied se colorent en brun rouille. Le pied bleu n''a JAMAIS de voile — aucun velum.","Forme/couleur du chapeau : Cortinarius rubellus orange rouille à orange cannelle/roux avec un sommet pointu et mamelonné ; Lepista nuda jeune entièrement violet, chapeau bombé sans mamelon pointu.","Couleur des lamelles : le pied bleu violet/violet-rose et restant clair ; le cortinaire brun cannelle/rouille, espacé, échancré-adné.","Habitat : le cortinaire auprès des conifères (épicéa) sur sol acide, souvent tourbeux-humide en montagne ; le pied bleu dans la litière de forêt de feuillus/mixte riche en nutriments, haies, tas de compost, tard dans la saison jusqu''après le gel."}','t'),
('lepista_nuda','cortinarius_rubellus','it','Lepista nuda: da giovane interamente violetta (cappello, lamelle, gambo), cappello convesso e liscio senza umbone appuntito, senza velo. Cortinarius rubellus: cappello da ruggine ad arancio-volpe con apice appuntito (umbonato), finemente feltroso-fibrilloso, lamelle da cannella a bruno-ruggine, fibre del velo bruno-ruggine sul gambo.','Lepista nuda odora aromatica-dolciastra (profumata, ricorda biscotto/fiore d''arancio). Cortinarius rubellus odora debolmente di ravanello, senza il tipico profumo dolciastro. L''odore è solo un indizio, MAI affidabile da solo — sporata + cortina sono decisive.','Cortinario (Raukopf): boschi di conifere acidi (abete rosso/bosco misto abete rosso-pino), stazioni torbose-umide e di montagna, ago-ott. Lepista nuda (Roetelritterling): lettiera di bosco di latifoglie/misto ricca di nutrienti, siepi, cumuli di compost, molto tardi nella stagione fino a dopo le prime gelate.','Decisivo: Lepista nuda = sporata da rosa pallido a biancastra/crema-rosa. Cortinarius rubellus = sporata bruno-ruggine. Una sporata bruno-ruggine esclude con sicurezza la Lepista nuda.','Prelevare SEMPRE una sporata (cappello sulla carta bianca per una notte). Da rosa pallido a biancastra = possibilmente Lepista nuda. Bruno-ruggine OPPURE un velo a ragnatela (cortina) sul fungo giovane = STOP, cortinario — non mangiare mai. L''avvelenamento da orellanina si manifesta solo dopo 3-14 giorni, quando il rene è già danneggiato in modo irreversibile. Al minimo dubbio non mangiare.','{"Sporata (il controllo distintivo più sicuro): Lepista nuda da rosa pallido a biancastra/crema-rosa — OGNI Cortinarius/cortinario ha sporata BRUNO-RUGGINE. Una sporata bruno-ruggine esclude con sicurezza la Lepista nuda.","Cortina/velo: il cortinario da fungo giovane ha un velo a ragnatela (cortina) tra il margine del cappello e il gambo; i resti del velo sul gambo si colorano di bruno-ruggine. La Lepista nuda non ha MAI un velo — nessun velum.","Forma/colore del cappello: Cortinarius rubellus da ruggine a cannella/arancio-volpe con apice appuntito e umbonato; Lepista nuda da giovane interamente violetta, cappello convesso senza umbone appuntito.","Colore delle lamelle: Lepista nuda violetta/violetto-rosa e che rimane chiara; cortinario da cannella a bruno-ruggine, distanziate, attaccate in modo smarginato.","Habitat: il cortinario presso conifere (abete rosso) su terreno acido, spesso torboso-umido di montagna; la Lepista nuda in lettiera di bosco di latifoglie/misto ricca di nutrienti, siepi, cumuli di compost, tardi nella stagione fino a dopo il gelo."}','t'),
('lepista_nuda','cortinarius_traganus','en','Both are violet when young, but C. traganus has a clavate, thickened stem with a veil zone and never has violet gills, whereas Lepista nuda shows entirely violet, slightly removable gills without a veil.','Lepista nuda smells pleasantly aromatic and perfumed; C. traganus smells repulsively goaty — a reliable warning sign.','C. traganus prefers coniferous forest (especially under spruce/fir in moss); Lepista nuda grows more in deciduous/mixed forest and on compost heaps, often in fairy rings.','Lepista nuda: pink-cream spore print. C. traganus: rust-brown spore print. The spore print is the decisive safety criterion.','For EVERY violet mushroom make a spore print: rust-brown = Cortinarius = leave it. Only a pink-cream spore print with no veil remnants speaks for the edible wood blewit.','{"Lepista nuda has NO veil/cortina and no veil remnants on the stem; C. traganus shows a fibrillose, veil-like ring zone (a Cortinarius feature).","Spore print: Lepista nuda pink-cream, C. traganus rust-brown — the spore print makes the confusion reliably distinguishable.","Smell: Lepista nuda pleasantly perfumed-aromatic; C. traganus unpleasantly goaty.","Gills: Lepista nuda remaining entirely violet, detach easily; C. traganus young saffron-ochre, never violet, later rust-brown.","Flesh: Lepista nuda violet-coloured throughout; C. traganus saffron-brownish/ochre when cut."}','f'),
('lepista_nuda','cortinarius_traganus','es','Ambos son violetas cuando jóvenes, pero C. traganus tiene un pie claviforme engrosado con una zona velada y nunca tiene láminas violetas, mientras que Lepista nuda muestra láminas enteramente violetas, ligeramente separables, sin velo.','Lepista nuda huele agradablemente aromático y perfumado; C. traganus huele repugnantemente a macho cabrío/cabra — una señal de alarma fiable.','C. traganus prefiere el bosque de coníferas (sobre todo bajo abetos/píceas en el musgo); Lepista nuda crece más bien en bosque de frondosas/mixto y en montones de compost, a menudo en corros de brujas.','Lepista nuda: esporada rosa-crema. C. traganus: esporada pardo-herrumbre. La esporada es el criterio de seguridad decisivo.','Para CADA hongo violeta hacer una esporada: pardo-herrumbre = Cortinarius = dejarlo. Solo una esporada rosa-crema sin restos de velo habla a favor del comestible pie azul.','{"Lepista nuda NO tiene velo/cortina ni restos de velo en el pie; C. traganus presenta una zona anular fibrillosa y velada (carácter de los Cortinarius).","Esporada: Lepista nuda rosa-crema, C. traganus pardo-herrumbre — la esporada hace la confusión distinguible con seguridad.","Olor: Lepista nuda agradablemente perfumado-aromático; C. traganus desagradable, a macho cabrío/cabra.","Láminas: Lepista nuda permanecen enteramente violetas, se separan fácilmente; C. traganus joven azafrán-ocre, nunca violeta, luego pardo-herrumbre.","Carne: Lepista nuda teñida de violeta en toda su masa; C. traganus azafrán-parduzco/ocre al corte."}','f'),
('lepista_nuda','cortinarius_traganus','fr','Les deux jeunes violets, mais C. traganus a un pied épaissi en massue avec une zone de voile et jamais de lamelles violettes, tandis que Lepista nuda montre des lamelles entièrement violettes, facilement détachables, sans voile.','Lepista nuda sent agréablement aromatique-parfumé ; C. traganus sent répugnant, de bouc/chèvre – un signe d''alarme fiable.','C. traganus préfère la forêt de conifères (surtout sous épicéas/sapins dans la mousse) ; Lepista nuda pousse plutôt en forêt de feuillus/mixte et tas de compost, souvent en ronds de sorcières.','Lepista nuda : sporée rose-crème. C. traganus : sporée brun rouille. La sporée est le critère de sécurité décisif.','Pour TOUT champignon violet, faire une sporée : brun rouille = cortinaire = laisser sur place. Seule une sporée rose-crème sans restes de voile plaide pour le pied violet comestible.','{"Lepista nuda n''a AUCUN voile/cortine ni restes de voile au pied ; C. traganus montre une zone annulaire fibrilleuse-voilée (caractère de cortinaire).","Sporée : Lepista nuda rose-crème, C. traganus brun rouille – la sporée rend la confusion distinguable sûrement.","Odeur : Lepista nuda agréablement parfumée-aromatique ; C. traganus désagréable, de bouc/chèvre.","Lamelles : Lepista nuda restant entièrement violettes, se détachent facilement ; C. traganus jeune safran-ocre, jamais violet, plus tard brun rouille.","Chair : Lepista nuda colorée de violet à cœur ; C. traganus safran-brunâtre/ocre à la coupe."}','f'),
('lepista_nuda','cortinarius_traganus','it','Entrambi da giovani sono violetti, ma C. traganus ha un gambo clavato ingrossato con zona velata e non ha mai lamelle violette, mentre Lepista nuda presenta lamelle interamente violette, leggermente asportabili, prive di velo.','Lepista nuda ha odore gradevole, aromatico e profumato; C. traganus ha odore ripugnante di becco/caprino — un segnale d''allarme affidabile.','C. traganus predilige i boschi di conifere (soprattutto sotto abeti rossi/abeti bianchi nel muschio); Lepista nuda cresce piuttosto in boschi di latifoglie/misti e su cumuli di compost, spesso in cerchi delle streghe.','Lepista nuda: sporata rosa-crema. C. traganus: sporata bruno-ruggine. La sporata è il criterio di sicurezza decisivo.','Per OGNI fungo violetto fare la sporata: bruno-ruggine = Cortinarius = lasciare sul posto. Solo una sporata rosa-crema senza residui di velo depone per il commestibile agarico violetto.','{"Lepista nuda NON ha velo/cortina né residui di velo sul gambo; C. traganus presenta una zona anulare fibrillosa e velata (carattere dei Cortinarius).","Sporata: Lepista nuda rosa-crema, C. traganus bruno-ruggine — la sporata rende la confusione distinguibile con sicurezza.","Odore: Lepista nuda gradevolmente profumato-aromatico; C. traganus sgradevole, di becco/caprino.","Lamelle: Lepista nuda rimangono interamente violette, si asportano facilmente; C. traganus da giovane zafferano-ocra, mai violetto, poi bruno-ruggine.","Carne: Lepista nuda colorata di violetto in tutta la sua massa; C. traganus zafferano-brunastro/ocra al taglio."}','f'),
('lepista_nuda','mycena_pura','en','Lepista nuda: large, fleshy, uniformly strong violet with an unstriated cap; Mycena pura: small, glassy-striate, pale lilac and fading quickly.','Mycena pura smells strongly and penetratingly of radish; Lepista nuda smells pleasantly spicy-perfumed — the radish smell is the most important warning signal.','Both in broadleaf and conifer forest on the leaf litter; Lepista nuda often gregarious or in fairy rings in fallen leaves, Mycena pura solitary to gregarious on litter and needles.','Lepista nuda: pink to pale lilac spore print; Mycena pura: white spore print — the spore print colour separates the two unambiguously.','Any small, thin-fleshed, striate-glassy lilac mushroom with a strong radish smell is suspect — radish smell + white spore print reliably rule out the edible wood blewit (Lepista nuda).','{"Mycena pura is poisonous (contains muscarine, formerly wrongly listed as edible); the wood blewit (Lepista nuda) is edible only THOROUGHLY COOKED","Mycena pura smells intensely and penetratingly of radish; Lepista nuda smells pleasantly spicy-perfumed, never of radish","Mycena pura is small and thin-fleshed (cap only up to ~4 cm, glassy-helmet-shaped, striate); Lepista nuda strongly fleshy (cap 5-15 cm, not striate)","Mycena pura with a thin, hollow, fragile stem; Lepista nuda with a firm, fibrous-solid, often violet stem","Lepista nuda uniformly strong violet to grey-lilac throughout (cap, gills, stem); Mycena pura only pale lilac/pink and fading rapidly"}','f'),
('lepista_nuda','mycena_pura','es','Lepista nuda: grande, carnoso, uniformemente de un violeta intenso con sombrero no estriado; Mycena pura: pequeña, vítrea-estriada, lila pálido y que palidece rápidamente.','Mycena pura huele fuerte y penetrantemente a rábano; Lepista nuda tiene un olor agradablemente especiado-perfumado — el olor a rábano es la principal señal de alarma.','Ambos en bosque de frondosas y coníferas sobre la hojarasca; Lepista nuda a menudo gregario o en corros de brujas en la hojarasca caída, Mycena pura de solitaria a gregaria sobre hojarasca y acículas.','Lepista nuda: esporada rosa a lila pálido; Mycena pura: esporada blanca — el color de la esporada los distingue inequívocamente.','Todo hongo lila pequeño, de carne fina, estriado-vítreo y con fuerte olor a rábano es sospechoso — olor a rábano + esporada blanca descartan con seguridad la pie azul comestible (Lepista nuda).','{"Mycena pura es venenosa (contiene muscarina, antiguamente catalogada erróneamente como comestible); la pie azul (Lepista nuda) es comestible solo BIEN COCINADA","Mycena pura huele intensa y penetrantemente a rábano; Lepista nuda huele agradablemente especiado-perfumado, nunca a rábano","Mycena pura es pequeña y de carne fina (sombrero solo hasta ~4 cm, vítreo-en casco, estriado); Lepista nuda marcadamente carnoso (sombrero 5-15 cm, no estriado)","Mycena pura con pie fino, hueco y frágil; Lepista nuda con pie firme, fibroso-macizo, a menudo violeta","Lepista nuda uniformemente de un violeta intenso a gris-lila en todo su cuerpo (sombrero, láminas, pie); Mycena pura solo lila/rosa pálido y que palidece rápidamente"}','f'),
('lepista_nuda','mycena_pura','fr','Lepista nuda : grand, charnu, uniformément d''un violet vif avec chapeau non strié ; Mycena pura : petit, vitreux-strié, lilas pâle et se décolorant vite.','Mycena pura sent fortement et de façon pénétrante le radis ; Lepista nuda a une odeur agréablement épicée-parfumée — l''odeur de radis est le principal signal d''alarme.','Tous deux en forêt de feuillus et de conifères sur la litière ; Lepista nuda souvent en groupe ou en ronds de sorcière dans les feuilles mortes, Mycena pura isolé à grégaire sur litière et aiguilles.','Lepista nuda : sporée rose à lilas pâle ; Mycena pura : sporée blanche — la couleur de la sporée les distingue clairement.','Tout petit champignon lilas à chair mince, strié-vitreux et à forte odeur de radis est suspect — odeur de radis + sporée blanche excluent avec certitude le pied-bleu comestible.','{"Mycena pura est vénéneux (contient de la muscarine, autrefois faussement réputé comestible) ; le pied-bleu (Lepista nuda) n''est comestible que BIEN CUIT","Mycena pura sent intensément et de façon pénétrante le radis ; Lepista nuda sent agréablement épicé-parfumé, jamais le radis","Mycena pura est petit et à chair mince (chapeau jusqu''à ~4 cm seulement, vitreux-en casque, strié) ; Lepista nuda est nettement charnu (chapeau 5-15 cm, non strié)","Mycena pura a un pied mince, creux et fragile ; Lepista nuda a un pied ferme, fibreux-plein, souvent violet","Lepista nuda est uniformément d''un violet vif à gris-lilas (chapeau, lames, pied) ; Mycena pura n''est que lilas/rose pâle et se décolore rapidement"}','f'),
('lepista_nuda','mycena_pura','it','Lepista nuda: grande, carnoso, uniformemente di un viola intenso con cappello non striato; Mycena pura: piccola, vitrea-striata, lilla pallido e che sbiadisce rapidamente.','Mycena pura odora fortemente e in modo penetrante di ravanello; Lepista nuda ha un odore gradevolmente speziato-profumato — l''odore di ravanello è il principale segnale d''allarme.','Entrambi in bosco di latifoglie e conifere sulla lettiera; Lepista nuda spesso in gruppo o in cerchi delle streghe nelle foglie cadute, Mycena pura da isolata a gregaria su lettiera e aghi.','Lepista nuda: sporata rosa fino a lilla pallido; Mycena pura: sporata bianca — il colore della sporata li distingue chiaramente.','Ogni piccolo fungo lilla a carne sottile, striato-vitreo e con forte odore di ravanello è sospetto — odore di ravanello + sporata bianca escludono con certezza l''agarico violetto commestibile (Lepista nuda).','{"Mycena pura è velenosa (contiene muscarina, un tempo erroneamente ritenuta commestibile); l''agarico violetto (Lepista nuda) è commestibile solo BEN COTTO","Mycena pura odora intensamente e in modo penetrante di ravanello; Lepista nuda odora gradevolmente speziato-profumato, mai di ravanello","Mycena pura è piccola e a carne sottile (cappello solo fino a ~4 cm, vitreo-a elmo, striato); Lepista nuda nettamente carnoso (cappello 5-15 cm, non striato)","Mycena pura con gambo sottile, cavo e fragile; Lepista nuda con gambo sodo, fibroso-pieno, spesso viola","Lepista nuda uniformemente di un viola intenso fino a grigio-lilla (cappello, lamelle, gambo); Mycena pura solo lilla/rosa pallido e che sbiadisce rapidamente"}','f'),
('lycoperdon_perlatum','amanita_phalloides','en','From the outside, a white, closed death cap egg can superficially resemble a young white puffball. Reliable separation only in longitudinal section: homogeneous white mass (puffball) vs. a preformed mushroom with a gill/stem silhouette and a volva (Amanita).','Young puffball odourless to mushroomy-mild. Young death cap almost odourless, only when old sweetish-honey-like to carrion-like. Smell is NOT a reliable feature at the critical egg stage.','A. phalloides is a mycorrhizal mushroom mainly with oak and beech (also chestnut), preferring acidic soils; the puffball is saprotrophic and ubiquitous in all forest types, meadows and gardens. The habitats often overlap → habitat does NOT help with the distinction, only the section test is reliable.','In the puffball, yellow- to olive-brown spore powder matures inside (the mushroom is then no longer edible). A. phalloides has white spore powder — but not testable at the egg stage, therefore irrelevant for the collector.','Halve EVERY spherical puffball completely lengthwise before eating and check the cut surface. Only eat it if the inside is COMPLETELY pure white and homogeneous — without the slightest outline of gills, stem or cap. A single recognizable mushroom outline means deadly amatoxin poisoning (liver failure). When in doubt, go to the mushroom inspection centre (VAPKO).','{"LONGITUDINAL SECTION (the decisive test): in the puffball the inside is a completely uniform, pure white, marshmallow-like mass WITHOUT any structure. In the young death cap egg, the section already shows the preformed mushroom — the embryonic gills and the stem as a darker silhouette/outline. Even a single recognizable gill or stem base = discard.","Stem base/volva: the young Amanita sits inside a white membranous universal veil (velum) and has a lobed, membranous bulb/volva at the base. The puffball has no volva, no distinct stem and no veil of this kind — it sits in the soil with a short sterile base.","Outer skin: the common puffball bears fine wipeable spine-/wart-warts that leave a net pattern, and is white inside. The Amanita egg is smooth-membranous white on the outside.","Ripening changes the puffball: as soon as the inside turns yellowish/olive/brownish (spore formation), it is no longer edible — the Amanita flesh stays white in section and shows the mushroom silhouette."}','t'),
('lycoperdon_perlatum','amanita_phalloides','es','Desde fuera, un huevo cerrado y blanco de oronja verde (Amanita phalloides) puede parecerse superficialmente a un bejín blanco joven. Solo se distinguen con seguridad en sección longitudinal: masa blanca homogénea (bejín) frente a un hongo preformado con la silueta de láminas/pie y volva (Amanita).','El bejín joven es inodoro hasta de olor suave a hongo. La oronja verde joven es casi inodora; solo de vieja huele dulzón-amielado hasta a carroña. El olor NO es un rasgo fiable en el crítico estadio de huevo.','Amanita phalloides es un hongo micorrízico sobre todo junto a roble y haya (también castaño), prefiere suelos ácidos; el bejín es saprótrofo y ubicuo en todo tipo de bosques, prados y jardines. Las ubicaciones se solapan con frecuencia, por lo que la ubicación NO ayuda a distinguir: solo la prueba del corte es segura.','En el bejín madura en su interior una esporada de color pardo amarillento a pardo oliváceo (entonces el hongo ya no es comestible). Amanita phalloides tiene esporada blanca, pero en el estadio de huevo no es comprobable, por lo que resulta irrelevante para el recolector.','Antes de consumirlo, parte por la mitad y a lo largo TODO bejín esférico y examina la imagen del corte. Cómelo solo si el interior es COMPLETAMENTE blanco puro y homogéneo, sin la menor silueta de láminas, pie o sombrero. Una sola silueta de hongo reconocible significa una intoxicación mortal por amatoxinas (insuficiencia hepática). En caso de duda, acude al puesto de control de setas (VAPKO).','{"SECCIÓN LONGITUDINAL (la prueba decisiva): en el bejín, el interior es una masa totalmente uniforme, blanca pura, parecida a un malvavisco, SIN estructura alguna. En el huevo joven de la oronja verde ya se ve en el corte el hongo preformado: las láminas y el pie esbozados como silueta más oscura. Basta un solo arranque reconocible de láminas o de pie = tirar.","Base del pie/volva: la Amanita joven está dentro de una envoltura general blanca y membranosa (velo) y tiene en la base un bulbo/volva membranoso y lobulado. El bejín no tiene volva, ni pie diferenciado, ni envoltura de este tipo: se asienta en el suelo con una base estéril corta.","Piel externa: el bejín común lleva finas espinas/verrugas frotables que dejan un patrón reticulado y es blanco por dentro. El huevo de Amanita es por fuera blanco, liso y membranoso.","La madurez cambia al bejín: en cuanto el interior se vuelve amarillento/oliváceo/parduzco (formación de esporas), ya no es comestible; la carne de la Amanita permanece blanca en el corte y muestra la silueta del hongo."}','t'),
('lycoperdon_perlatum','amanita_phalloides','fr','De l''extérieur, un œuf d''amanite phalloïde blanc et fermé peut superficiellement ressembler à une jeune vesse-de-loup blanche. Distinction sûre seulement à la coupe longitudinale : masse blanche homogène (vesse-de-loup) vs champignon préformé avec silhouette de lamelles/pied et volve (amanite).','La jeune vesse-de-loup est inodore à odeur fongique douce. La jeune amanite phalloïde est presque inodore, ne devenant que tardivement sucrée-mielleuse à cadavérique. L''odeur n''est PAS un critère fiable au stade critique de l''œuf.','A. phalloides est un champignon mycorhizien surtout du chêne et du hêtre (aussi du châtaignier), préférant les sols acides ; la vesse-de-loup est saprotrophe et ubiquiste dans tous les types de forêts, prairies et jardins. Les stations se recoupent souvent → le lieu n''aide PAS à la distinction, seul le test de la coupe est sûr.','Chez la vesse-de-loup, une sporée brun jaune à brun olive mûrit à l''intérieur (le champignon n''est alors plus comestible). A. phalloides a une sporée blanche — non vérifiable au stade de l''œuf, donc sans intérêt pour le cueilleur.','Halver entièrement CHAQUE vesse-de-loup sphérique dans le sens de la longueur avant de la consommer et examiner l''image de la coupe. Ne manger que si l''intérieur est ENTIÈREMENT blanc pur et homogène — sans la moindre ombre de lamelles, de pied ou de chapeau. Un seul contour de champignon reconnaissable signifie une intoxication mortelle par amatoxines (insuffisance hépatique). En cas de doute, s''adresser à un poste de contrôle des champignons (VAPKO).','{"COUPE LONGITUDINALE (le test décisif) : chez la vesse-de-loup, l''intérieur est une masse parfaitement uniforme, blanc pur, de type guimauve, SANS aucune structure. Dans le jeune œuf d''amanite phalloïde, on voit déjà à la coupe le champignon préformé — les lamelles ébauchées et le pied comme silhouette/ombre plus foncée. Le moindre départ de lamelle ou de pied reconnaissable = jeter.","Base du pied/volve : la jeune amanite est enfermée dans un voile général membraneux blanc (velum) et possède à la base un bulbe/une volve lobée et membraneuse. La vesse-de-loup n''a pas de volve, pas de pied distinct ni de voile de ce type — elle est implantée dans le sol par une courte base stérile.","Peau externe : la vesse-de-loup perlée porte de fines verrues/aiguillons effaçables qui laissent un motif en réseau, et est blanche à l''intérieur. L''œuf d''amanite est lisse-membraneux et blanc à l''extérieur.","La maturation modifie la vesse-de-loup : dès que l''intérieur devient jaunâtre/olivâtre/brunâtre (formation des spores), elle n''est plus comestible — la chair de l''amanite reste blanche à la coupe et montre la silhouette du champignon."}','t'),
('lycoperdon_perlatum','amanita_phalloides','it','Dall''esterno un uovo bianco e chiuso di tignosa verdognola (Amanita phalloides) può somigliare superficialmente a un giovane vesce bianco. Separabili con sicurezza solo nella sezione longitudinale: massa bianca omogenea (vesce) vs. fungo preformato con silhouette di lamelle/gambo e volva (Amanita).','Il giovane vesce è inodore o di odore fungino-mite. La giovane tignosa verdognola è quasi inodore, solo da vecchia dolciastra-melliflua fino a odore di carogna. L''odore NON è un carattere affidabile nello stadio critico a uovo.','A. phalloides è fungo micorrizico soprattutto presso quercia e faggio (anche castagno), predilige terreni acidi; il vesce è saprotrofo e ubiquitario in tutti i tipi di bosco, prati e giardini. Le stazioni si sovrappongono spesso → l''habitat NON aiuta nella distinzione, solo la prova del taglio è sicura.','Nel vesce all''interno matura una sporata da giallo a bruno-oliva (il fungo allora non è più commestibile). A. phalloides ha sporata bianca – nello stadio a uovo però non verificabile, quindi irrilevante per il raccoglitore.','Dividere SEMPRE per il lungo, completamente a metà, ogni vesce sferico prima del consumo e verificare l''immagine in sezione. Mangiare solo se l''interno è COMPLETAMENTE bianco puro e omogeneo – senza il minimo profilo in controluce di lamelle, gambo o cappello. Un solo contorno di fungo riconoscibile significa avvelenamento mortale da amatossine (insufficienza epatica). In caso di dubbio recarsi all''ufficio di controllo funghi (VAPKO).','{"SEZIONE LONGITUDINALE (il test decisivo): nel vesce l''interno è una massa del tutto uniforme, bianca pura, simile a marshmallow, SENZA alcuna struttura. Nel giovane uovo di tignosa verdognola si vede già in sezione il fungo preformato – le lamelle abbozzate e il gambo come silhouette/profilo in controluce più scuro. Già un solo accenno riconoscibile di lamelle o gambo = scartare.","Base del gambo/volva: la giovane Amanita è racchiusa in un velo generale bianco e membranoso (velum) e ha alla base un bulbo/volva lobato e membranoso. Il vesce non ha volva, né gambo distinto, né un involucro di questo tipo – siede nel terreno con una breve base sterile.","Superficie esterna: il vesce (Lycoperdon perlatum) porta fini aculei/verruche asportabili, che lasciano un disegno a rete, ed è bianco all''interno. L''uovo dell''Amanita è esternamente bianco, liscio e membranoso.","La maturazione cambia il vesce: appena l''interno diventa giallastro/olivastro/brunastro (formazione di spore), non è più commestibile – la carne dell''Amanita rimane bianca in sezione e mostra la silhouette del fungo."}','t'),
('lycoperdon_perlatum','amanita_verna','en','Outwardly very similar to the young white puffball (pure white membranous egg); reliably distinguishable only in cross-section by the preformed mushroom structure (gills+stem) and the pronounced volva — not by the outer shape.','A. verna when young odourless to faint; when old unpleasantly sweetish. Not a reliable distinguishing feature at the egg stage.','A. verna occurs mainly in spring/early summer (deciduous forests, rather calcareous/warmer soils); puffballs appear rather in summer–autumn and are ubiquitous. Season/habitat are clues, but NOT a reliable substitute for the section test.','A. verna: white spore powder. Puffball: yellow-/olive-brown spore powder at maturity (then no longer edible). Not testable at the egg stage, therefore irrelevant for identification.','Here too: halve every spherical white find — only eat it if the inside is completely homogeneous white without a gill/stem silhouette and without a volva. A preformed mushroom in the section means deadly amatoxin poisoning. Inspection centre (VAPKO) at any uncertainty.','{"Like all white death caps (section Phalloideae), A. verna is spherical at the young egg stage enveloped by the white velum and can be confused with white puffballs. The LONGITUDINAL SECTION decides: homogeneous white mass (puffball) vs. preformed gills + stem in the egg (Amanita).","Stem base: A. verna shows a distinctly pronounced, lobed, sack-like membranous sheath (volva) at the base — the puffball lacks any volva.","Gills stay white to cream-white (even when mature) — laid down in the egg as a pale silhouette in section; the puffball never has gill rudiments.","Outside pure white-membranous (Amanita) vs. finely warty/spiny with wipeable warts (common puffball)."}','t'),
('lycoperdon_perlatum','amanita_verna','es','Externamente muy parecida al bejín blanco joven (huevo blanco puro y membranoso); solo se distingue con seguridad en sección transversal por la estructura de hongo esbozada (láminas + pie) y la pronunciada volva, no por la forma externa.','Amanita verna de joven inodora hasta de olor débil; de vieja, dulzón-desagradable. No es un rasgo distintivo fiable en el estadio de huevo.','Amanita verna aparece sobre todo en primavera/principios de verano (bosques de frondosas, más bien suelos calcáreos/cálidos); los bejines aparecen más bien de verano a otoño y son ubicuos. Temporada/ubicación son indicios, pero NO un sustituto seguro de la prueba del corte.','Amanita verna: esporada blanca. Bejín: esporada de color pardo amarillento/oliváceo al madurar (entonces ya no es comestible). En el estadio de huevo no es comprobable, por lo que es irrelevante para la determinación.','También aquí: parte por la mitad todo hallazgo esférico blanco; cómelo solo si el interior es completamente homogéneo y blanco, sin silueta de láminas/pie y sin volva. Un hongo esbozado en el corte significa una intoxicación mortal por amatoxinas. Puesto de control (VAPKO) ante cualquier inseguridad.','{"Como todas las oronjas blancas (sección Phalloideae), Amanita verna en su joven estadio de huevo, envuelta por el velo blanco, es esférica y puede confundirse con bejines blancos. La SECCIÓN LONGITUDINAL es decisiva: masa blanca homogénea (bejín) frente a láminas + pie preformados en el huevo (Amanita).","Base del pie: Amanita verna muestra en la base una vaina (volva) claramente pronunciada, lobulada y membranosa en forma de saco; en el bejín falta toda volva.","Las láminas permanecen blancas hasta blanco crema (también maduras), esbozadas en el huevo como silueta clara en el corte; el bejín nunca tiene esbozos de láminas.","Por fuera blanco puro y membranoso (Amanita) frente a finamente verrugoso/espinoso con verrugas frotables (bejín común)."}','t'),
('lycoperdon_perlatum','amanita_verna','fr','Extérieurement très semblable à la jeune vesse-de-loup blanche (œuf blanc-membraneux pur) ; distinction sûre uniquement en coupe transversale par la structure ébauchée du champignon (lamelles+pied) et la volve marquée — pas par la forme extérieure.','A. verna jeune inodore à faible ; sucrée-désagréable avec l''âge. Pas de critère de distinction fiable au stade de l''œuf.','A. verna apparaît surtout au printemps/début de l''été (forêts de feuillus, sols plutôt calcaires/chauds) ; les vesses-de-loup apparaissent plutôt de l''été à l''automne et sont ubiquistes. La saison/la station sont des indices, mais PAS un substitut fiable au test de la coupe.','A. verna : sporée blanche. Vesse-de-loup : sporée brun jaune/olive à maturité (alors plus comestible). Non vérifiable au stade de l''œuf, donc sans intérêt pour la détermination.','Ici aussi : halver chaque trouvaille blanche sphérique — ne manger que si l''intérieur est entièrement homogène et blanc, sans silhouette de lamelles/pied et sans volve. Un champignon ébauché à la coupe signifie une intoxication mortelle par amatoxines. Poste de contrôle (VAPKO) à la moindre incertitude.','{"Comme toutes les amanites phalloïdes blanches (section Phalloideae), A. verna est sphérique au stade jeune de l''œuf enveloppé du velum blanc et peut être confondue avec les vesses-de-loup blanches. La COUPE LONGITUDINALE décide : masse blanche homogène (vesse-de-loup) vs lamelles + pied préformés dans l''œuf (amanite).","Base du pied : A. verna montre à la base une gaine (volve) nettement marquée, lobée, en sac-membraneuse — chez la vesse-de-loup, toute volve fait défaut.","Les lamelles restent blanches à blanc crème (même à maturité) — ébauchées dans l''œuf comme silhouette claire à la coupe ; la vesse-de-loup n''a jamais de départs de lamelles.","Extérieur blanc-membraneux pur (amanite) vs finement verruqueux/aiguillonné avec des verrues effaçables (vesse-de-loup perlée)."}','t'),
('lycoperdon_perlatum','amanita_verna','it','Esternamente molto simile al giovane vesce bianco (uovo bianco puro e membranoso); distinguibile con sicurezza solo in sezione trasversale, attraverso la struttura del fungo abbozzata (lamelle+gambo) e la volva pronunciata – non dalla forma esterna.','A. verna da giovane inodore o di odore debole; da vecchia di odore sgradevole-dolciastro. Nessun carattere distintivo affidabile nello stadio a uovo.','A. verna compare soprattutto in primavera/inizio estate (boschi di latifoglie, piuttosto su terreni calcarei/caldi); i vesci compaiono piuttosto in estate-autunno e sono ubiquitari. Stagione/stazione sono indizi, ma NON un sostituto sicuro della prova del taglio.','A. verna: sporata bianca. Vesce: sporata da giallo a bruno-oliva a maturità (allora non più commestibile). Nello stadio a uovo non verificabile, quindi irrilevante per la determinazione.','Anche qui: dividere a metà ogni reperto bianco sferico – mangiare solo se l''interno è completamente omogeneo e bianco, senza silhouette di lamelle/gambo e senza volva. Un fungo abbozzato in sezione significa avvelenamento mortale da amatossine. Ufficio di controllo (VAPKO) a ogni incertezza.','{"Come tutte le tignose bianche (sezione Phalloideae), A. verna nello stadio giovane a uovo, avvolto dal velum bianco, è sferica e può essere confusa con i vesci bianchi. La SEZIONE LONGITUDINALE decide: massa bianca omogenea (vesce) vs. lamelle + gambo preformati nell''uovo (Amanita).","Base del gambo: A. verna mostra alla base una guaina (volva) nettamente pronunciata, lobata, a sacco e membranosa – nel vesce manca ogni volva.","Le lamelle rimangono bianche fino a bianco-crema (anche a maturità) – nell''uovo abbozzate in sezione come silhouette chiara; il vesce non ha mai accenni di lamelle.","Esternamente bianco puro e membranoso (Amanita) vs. finemente verrucoso/aculeato con verruche asportabili (Lycoperdon perlatum)."}','t'),
('lycoperdon_perlatum','gemeiner-fliegenpilz-var-alba','en','From above/outside hardly distinguishable from a young white puffball, because A. virosa is completely pure white. Reliable distinction only in cross-section: a pre-formed white mushroom with crowded gills + volva (Amanita) vs. a homogeneous white mass (puffball).','Older A. virosa smells unpleasantly sweetish-repulsive; but the young ''egg'' is inconspicuous. Smell is not reliable at the critical egg stage.','A. virosa grows mainly in moist (acidic) coniferous/mixed forests, with mycorrhiza preferentially with spruce (finds also documented under beech/oak/birch), often at higher/montane elevations — ecologically partly different from the ubiquitous saprotrophic puffball, but location is NOT a reliable criterion.','A. virosa: white spore powder. In the puffball, yellow-/olive-brown spore powder matures (= then no longer edible). At the egg stage it cannot be checked, therefore irrelevant for identification.','Because the white destroying-angel egg is pure white and especially resembles a white puffball, the following applies all the more strictly: halve it completely, and eat ONLY if the inner flesh is absolutely homogeneous white, without any gill/stem silhouette and without a volva. Any mushroom outline = mortal danger (amatoxins, liver failure). When in doubt, go to the mushroom inspection office (VAPKO).','{"Young stages of Amanita virosa are explicitly noted in mushroom/poison databases as being confused with bovistas and puffballs. Decisive is the LONGITUDINAL CUT: puffball = homogeneous pure white mass; Amanita egg = already pre-formed (white, crowded) gills and a stem recognisable as a silhouette.","Stem base: A. virosa has a membranous, lobed white sheath (volva) at the base. The puffball has no volva and no distinct stem.","Outer contour: the virosa egg is pure white and smooth-membranous; the common puffball bears fine, wipe-off-able warts/spines.","Since A. virosa is completely white (cap, gills, stem all stay white), the colour clue is absent — only the cut image and the volva separate them reliably."}','t'),
('lycoperdon_perlatum','gemeiner-fliegenpilz-var-alba','es','Desde arriba/desde fuera apenas se distingue del joven bejín blanco, ya que A. virosa es completamente blanco puro. La distinción segura solo es posible en el corte transversal: hongo preformado de color blanco con láminas apretadas + volva (Amanita) frente a una masa blanca homogénea (bejín).','El A. virosa más viejo huele desagradablemente dulzón-repugnante; pero el huevo joven es inodoro/discreto. El olor no es fiable en la fase crítica de huevo.','A. virosa crece sobre todo en bosques húmedos (ácidos) de coníferas/mixtos, formando micorriza preferentemente con la pícea (también hay hallazgos documentados con haya/roble/abedul), a menudo en zonas más altas/montanas; ecológicamente en parte distinto del bejín saprótrofo ubicuo, pero el lugar de crecimiento NO es un criterio seguro.','A. virosa: esporada blanca. En el bejín madura una esporada de color pardo amarillento/oliváceo (= entonces ya no comestible). En la fase de huevo no es comprobable, por lo que es irrelevante para la identificación.','Como el huevo blanco de la oronja blanca (Knollenblätterpilz) es blanco puro y se parece especialmente a un bejín blanco, rige con mayor rigor: cortar completamente por la mitad y comer SOLO si el interior es de carne blanca absolutamente homogénea, sin ninguna silueta de láminas/pie y sin volva. Cualquier contorno de hongo = peligro de muerte (amatoxinas, fallo hepático). En caso de duda, acudir al centro de control de setas (VAPKO).','{"Los estadios jóvenes de Amanita virosa se confunden expresamente en las bases de datos de hongos/venenos con bejines y pedos de lobo. Lo decisivo es el CORTE LONGITUDINAL: bejín = masa blanca pura homogénea; huevo de Amanita = láminas ya esbozadas (blancas, apretadas) y pie reconocibles como silueta.","Base del pie: A. virosa tiene una vaina blanca membranosa y lobulada (volva) en la base. El bejín no tiene volva ni un pie diferenciado.","Contorno exterior: el huevo de virosa es blanco puro y de superficie lisa-membranosa; el bejín común lleva finas verruguitas/espinitas que se pueden frotar/quitar.","Como A. virosa es completamente blanco (sombrero, láminas y pie permanecen blancos), no sirve la pista del color: solo la imagen del corte y la volva separan con seguridad."}','t'),
('lycoperdon_perlatum','gemeiner-fliegenpilz-var-alba','fr','Vu de dessus / de l''extérieur, à peine distinguable de la jeune vesse-de-loup blanche, car A. virosa est entièrement blanc pur. Distinction sûre seulement en coupe : champignon préformé blanc avec lamelles serrées + volve (Amanita) versus masse blanche homogène (vesse-de-loup).','Un A. virosa plus âgé dégage une odeur désagréable, douceâtre et écœurante ; mais le jeune œuf reste discret. L''odeur n''est pas fiable au stade critique de l''œuf.','A. virosa pousse surtout dans les forêts de conifères / mixtes humides (acides), en mycorhize de préférence avec l''épicéa (des trouvailles sont aussi documentées sous le hêtre / le chêne / le bouleau), souvent en altitude / en zones montagnardes — écologiquement parfois différent de la vesse-de-loup saprotrophe ubiquiste, mais la station n''est PAS un critère sûr.','A. virosa : sporée blanche. Chez la vesse-de-loup, la sporée mûrit en brun-jaune / brun-olive (= alors plus comestible). Au stade de l''œuf, non vérifiable, donc sans pertinence pour la détermination.','Comme l''œuf de l''amanite vireuse blanche est blanc pur et ressemble particulièrement à une vesse-de-loup blanche, la règle est d''autant plus stricte : couper entièrement en deux, et ne consommer QUE si la chair intérieure est absolument homogène et blanche, sans la moindre silhouette de lamelles ou de pied et sans volve. Toute esquisse de champignon = danger de mort (amatoxines, insuffisance hépatique). En cas de doute, s''adresser au contrôle officiel des champignons (VAPKO).','{"Les jeunes stades d''Amanita virosa sont expressément signalés dans les bases de données mycologiques / toxicologiques comme étant confondus avec des bovistes et des vesses-de-loup. Décisive est la COUPE LONGITUDINALE : vesse-de-loup = masse homogène entièrement blanche ; œuf d''Amanita = lamelles (blanches, serrées) déjà ébauchées et pied reconnaissable en silhouette.","Base du pied : A. virosa possède une gaine blanche membraneuse et lobée (volve) à la base. La vesse-de-loup n''a ni volve ni pied distinct.","Contour extérieur : l''œuf de virosa est blanc pur et lisse-membraneux ; la vesse-de-loup perlée porte de fines verrues / épines effaçables.","Comme A. virosa est entièrement blanc (chapeau, lamelles, pied restent blancs), l''indice de couleur est inutilisable — seules l''image de coupe et la volve permettent une distinction sûre."}','t'),
('lycoperdon_perlatum','gemeiner-fliegenpilz-var-alba','it','Visto dall''alto/dall''esterno è quasi impossibile distinguerlo dalla giovane vescia bianca, poiché A. virosa è completamente bianca pura. Una distinzione sicura è possibile solo in sezione trasversale: fungo bianco già preformato con lamelle fitte + volva (Amanita) contro massa bianca omogenea (vescia).','L''A. virosa più vecchia ha un odore sgradevole dolciastro-nauseante; l''uovo giovane però è inodore/non caratteristico. L''odore nello stadio critico a uovo non è affidabile.','L''A. virosa cresce soprattutto in boschi di conifere/misti umidi (acidi), in micorriza preferibilmente con l''abete rosso (ritrovamenti documentati anche presso faggio/quercia/betulla), spesso a quote più alte/montane – ecologicamente in parte diversa dalla vescia saprotrofa ubiquitaria, ma la stazione di crescita NON è un criterio sicuro.','A. virosa: sporata bianca. Nella vescia matura una sporata da gialla a oliva-bruna (= a quel punto non più commestibile). Allo stadio a uovo non è verificabile, quindi irrilevante per la determinazione.','Poiché l''uovo bianco dell''Amanita virosa è bianco puro e assomiglia in modo particolare a una vescia bianca, vale a maggior ragione la regola severa: sezionare completamente a metà, e mangiare SOLO in presenza di carne interna bianca assolutamente omogenea, senza alcuna sagoma di lamelle/gambo e senza volva. Qualunque contorno di fungo = pericolo di vita (amatossine, insufficienza epatica). Nel dubbio rivolgersi al controllo dei funghi (VAPKO).','{"Gli stadi giovani di Amanita virosa vengono espressamente confusi con vesce e vescioni nelle banche dati micologiche/tossicologiche. Decisiva è la SEZIONE LONGITUDINALE: vescia = massa bianca pura omogenea; uovo di Amanita = lamelle (bianche, fitte) e gambo già abbozzati, riconoscibili come sagoma.","Base del gambo: A. virosa ha una guaina bianca membranosa e lobata (volva) alla base. La vescia non ha volva né un gambo distinto.","Contorno esterno: l''uovo di virosa è bianco puro e liscio-membranoso; la vescia comune porta fini verruche/aculei asportabili.","Poiché A. virosa è completamente bianca (cappello, lamelle, gambo restano bianchi), viene meno l''indizio del colore – solo l''immagine in sezione e la volva distinguono con sicurezza."}','t'),
('lycoperdon_perlatum','scleroderma_citrinum','en','The common earthball (Scleroderma citrinum) is yellow-brown, hard, coarsely scurfy-areolate, without a true distinct stem; the common puffball (Lycoperdon perlatum) is white-grey with fine pyramidal spines and a distinctly set-off stem-like lower part.','The earthball smells unpleasantly metallic-rubbery; the puffball when young mild-mushroomy, inconspicuous.','The earthball on acidic, poor forest soil, mycorrhizal with trees (oak, beech, birch); the puffball on forest and meadow soils in conifer and broadleaf forest, on path edges.','Maturity assessment instead of spore print: the earthball already has, in half-ripe pieces, a brown-black spore mass inside; the young puffball in section is still completely white without a dark spore mass.','Cut EVERY round puffball lengthwise completely in two BEFORE eating: if the inside is not pure white and homogeneous throughout (dark-marbled, greyish or hard-shelled), throw it away — that is the poisonous earthball.','{"The cut test is decisive: puffball when young pure white and homogeneous-soft inside; earthball already when young with a greyish, then violet-black-marbled, hard inside.","The earthball has a thick (up to 5 mm), tough, hard outer rind with a coarse, scurfy-areolate surface; the puffball has a thin, soft skin with fine pyramidal spines/warts that fall off later.","The earthball smells unpleasantly metallic/rubbery; the puffball when young inconspicuously mild-mushroomy.","The earthball sits almost stemless and tuberous on the ground; the puffball has a distinctly set-off, slender sterile stem part (pear/bottle shape)."}','f'),
('lycoperdon_perlatum','scleroderma_citrinum','es','El escleroderma (Scleroderma citrinum) es pardo amarillento, duro, groseramente costroso-areolado, sin un verdadero pie diferenciado; el pedo de lobo perlado (Lycoperdon perlatum) es blanco-gris con finas espinas piramidales y una parte inferior a modo de pie claramente diferenciada.','El escleroderma huele desagradablemente metálico-gomoso; el pedo de lobo joven suave-a hongo, inapreciable.','El escleroderma sobre suelo forestal ácido y pobre, micorrízico con árboles (roble, haya, abedul); el pedo de lobo sobre suelos de bosques y prados en bosque de coníferas y frondosas, en bordes de caminos.','Determinación por la madurez en lugar de la esporada: el escleroderma ya tiene, en piezas semimaduras, una masa esporal pardo-negra en el interior; el pedo de lobo joven en sección está aún completamente blanco sin masa esporal oscura.','Cortar en dos a lo largo CADA pedo de lobo redondo ANTES de comerlo: si el interior no es de un blanco puro y homogéneo en su totalidad (jaspeado oscuro, grisáceo o de cáscara dura), tirarlo — ese es el escleroderma venenoso.','{"La prueba del corte es decisiva: pedo de lobo joven blanco puro y homogéneo-blando por dentro; escleroderma ya de joven con interior grisáceo, luego jaspeado negro-violeta, duro.","El escleroderma tiene una corteza externa gruesa (hasta 5 mm), coriácea y dura con superficie grosera, costrosa-areolada; el pedo de lobo tiene una piel fina y blanda con finas espinas/verrugas piramidales que se desprenden más tarde.","El escleroderma huele desagradablemente metálico/gomoso; el pedo de lobo joven inapreciablemente suave-a hongo.","El escleroderma se asienta casi sin pie y tuberoso sobre el suelo; el pedo de lobo tiene una parte estéril a modo de pie claramente diferenciada y esbelta (forma de pera/botella)."}','f'),
('lycoperdon_perlatum','scleroderma_citrinum','fr','Le scléroderme (Kartoffelbovist) est jaune-brun, dur, grossièrement croûteux-aréolé, sans véritable pied distinct ; la vesse-de-loup perlée (Lycoperdon) est blanc-gris avec de fins aiguillons pyramidaux et une partie inférieure nettement distincte en forme de pied.','Le scléroderme a une odeur désagréable métallique-caoutchouteuse ; la vesse-de-loup jeune douce-fongique, discrète.','Le scléroderme sur sol forestier acide et pauvre, mycorhizien sur les arbres (chêne, hêtre, bouleau) ; la vesse-de-loup sur sols de forêts et de prairies en forêt de conifères et de feuillus, sur les bords de chemins.','Détermination par la maturité plutôt que par sporée : le scléroderme a déjà, sur des pièces à demi mûres, une masse sporale brun-noir à l''intérieur ; la jeune vesse-de-loup en coupe est encore entièrement blanche sans masse sporale sombre.','Couper en deux dans la longueur CHAQUE vesse ronde AVANT de la manger : si l''intérieur n''est pas d''un blanc pur et homogène en continu (marbré sombre, grisâtre ou à coque dure), la jeter — c''est le scléroderme vénéneux.','{"Le test de coupe est décisif : vesse-de-loup jeune blanche pure et homogène-molle à l''intérieur ; scléroderme déjà jeune à intérieur grisâtre, puis marbré noir-violet, dur.","Le scléroderme a une enveloppe externe épaisse (jusqu''à 5 mm), coriace et dure à surface grossière, croûteuse-aréolée ; la vesse-de-loup a une peau mince et molle à fins aiguillons/verrues pyramidaux qui tombent plus tard.","Le scléroderme sent désagréablement métallique/caoutchouteux ; la vesse-de-loup jeune discrètement douce-fongique.","Le scléroderme repose au sol presque sans pied, tubéreux ; la vesse-de-loup a une partie inférieure stérile nettement distincte et élancée (forme de poire/bouteille)."}','f'),
('lycoperdon_perlatum','scleroderma_citrinum','it','Lo scleroderma (Kartoffelbovist) è giallo-bruno, duro, grossolanamente crostoso-areolato, senza un vero gambo distinto; la vescia perlata (Lycoperdon) è bianco-grigia con fini aculei piramidali e una parte inferiore nettamente distinta a forma di gambo.','Lo scleroderma ha un odore sgradevole metallico-gommoso; la vescia da giovane mite-fungina, inappariscente.','Lo scleroderma su suolo forestale acido e povero, micorrizico sugli alberi (quercia, faggio, betulla); la vescia su suoli di boschi e prati in bosco di conifere e latifoglie, sui bordi dei sentieri.','Determinazione tramite la maturità invece della sporata: lo scleroderma ha già, in pezzi semimaturi, una massa sporale bruno-nera all''interno; la giovane vescia in sezione è ancora completamente bianca senza massa sporale scura.','Tagliare in due per il lungo OGNI vescia rotonda PRIMA di mangiarla: se l''interno non è di un bianco puro e omogeneo in modo continuo (marmorizzato scuro, grigiastro o a guscio duro), buttarla — è lo scleroderma velenoso.','{"Il test di taglio è decisivo: vescia da giovane bianca pura e omogenea-molle all''interno; scleroderma già da giovane con interno grigiastro, poi marmorizzato nero-viola, duro.","Lo scleroderma ha un involucro esterno spesso (fino a 5 mm), coriaceo e duro a superficie grossolana, crostosa-areolata; la vescia ha una pelle sottile e molle con fini aculei/verruche piramidali che cadono più tardi.","Lo scleroderma odora sgradevolmente metallico/gommoso; la vescia da giovane inappariscentemente mite-fungina.","Lo scleroderma siede al suolo quasi senza gambo, tuberoso; la vescia ha una parte inferiore sterile nettamente distinta e slanciata (forma di pera/bottiglia)."}','f'),
('lycoperdon_perlatum','scleroderma_verrucosum','en','The thin-skinned earthball (Scleroderma verrucosum) is yellow-brown, finely warty, with a distinctly furrowed sterile stem base; the common puffball is white-grey with fine spines and a smooth, set-off stem part.','Earthball metallic-unpleasant; puffball when young mild-mushroomy.','The thin-skinned earthball on sandy soils in heath, broadleaf and conifer forest, often on path edges; the puffball in forests and on meadows.','Earthball in section early on dark-brown-spored; young puffball still with white flesh without a dark spore mass.','Cut every globular mushroom lengthwise: a dark, marbled or violet-black inside means earthball — never eat it. Only a pure white, homogeneous inside throughout is safe.','{"The thin-skinned earthball has — unlike the thick-skinned one — a distinctly developed, furrowed, sterile stem base with mycelial cords, which makes it outwardly more similar to the stalked puffball and therefore especially easy to confuse.","The cut flesh of the earthball turns greyish to dark-marbled already when young; the puffball when young pure white and homogeneous.","Earthball rind leathery-tough, finely brown-warty; puffball skin soft with fine, deciduous pyramidal spines.","The earthball smells metallic-unpleasant; the young puffball mild-mushroomy."}','f'),
('lycoperdon_perlatum','scleroderma_verrucosum','es','El escleroderma de cáscara fina (Scleroderma verrucosum) es pardo amarillento, finamente verrugoso, con una base estéril a modo de pie claramente surcada; el pedo de lobo perlado es blanco-gris con finas espinas y una parte a modo de pie lisa y diferenciada.','Escleroderma metálico-desagradable; pedo de lobo joven suave-a hongo.','El escleroderma de cáscara fina sobre suelos arenosos en brezal, bosque de frondosas y coníferas, a menudo en bordes de caminos; el pedo de lobo en bosques y sobre prados.','Escleroderma en sección tempranamente de esporas pardo oscuras; pedo de lobo joven aún con carne blanca sin masa esporal oscura.','Cortar cada hongo globoso a lo largo: un interior oscuro, jaspeado o negro-violeta significa escleroderma — no comerlo nunca. Solo un interior de un blanco puro y homogéneo en su totalidad es seguro.','{"El escleroderma de cáscara fina tiene — a diferencia del de cáscara gruesa — una base estéril a modo de pie claramente marcada, surcada, con cordones miceliales, lo que lo hace exteriormente más parecido al pedo de lobo pedunculado y por ello especialmente confundible.","La carne de corte del escleroderma se vuelve ya de joven grisácea a jaspeada oscura; el pedo de lobo de joven es de un blanco puro y homogéneo.","Corteza del escleroderma coriácea, finamente verrugosa de pardo; piel del pedo de lobo blanda con finas espinas piramidales caducas.","El escleroderma huele metálico-desagradable; el pedo de lobo joven suave-a hongo."}','f'),
('lycoperdon_perlatum','scleroderma_verrucosum','fr','Le scléroderme à coque mince (Scleroderma verrucosum) est jaune-brun, finement verruqueux, avec une base stérile nettement sillonnée en forme de pied ; la vesse-de-loup perlée est blanc-gris avec de fins aiguillons et une partie en pied lisse et distincte.','Scléroderme métallique-désagréable ; vesse-de-loup jeune douce-fongique.','Le scléroderme à coque mince sur sols sableux en lande, forêt de feuillus et de conifères, souvent sur les bords de chemins ; la vesse-de-loup en forêts et sur prairies.','Scléroderme en coupe précocement à spores brun foncé ; jeune vesse-de-loup encore à chair blanche sans masse sporale sombre.','Couper chaque champignon sphérique dans la longueur : un intérieur sombre, marbré ou noir-violet signifie scléroderme — ne jamais le manger. Seul un intérieur d''un blanc pur et homogène en continu est sûr.','{"Le scléroderme à coque mince a — contrairement à celui à coque épaisse — une base stérile nettement marquée, sillonnée, avec des cordons mycéliens, ce qui le rend extérieurement plus semblable à la vesse-de-loup pédicellée et donc particulièrement confondable.","La chair de coupe du scléroderme devient déjà jeune grisâtre à marbrée sombre ; la vesse-de-loup jeune est d''un blanc pur et homogène.","Coque du scléroderme coriace, finement verruqueuse de brun ; peau de la vesse-de-loup molle à fins aiguillons pyramidaux caducs.","Le scléroderme sent métallique-désagréable ; la jeune vesse-de-loup douce-fongique."}','f'),
('lycoperdon_perlatum','scleroderma_verrucosum','it','Lo scleroderma a guscio sottile (Scleroderma verrucosum) è giallo-bruno, finemente verrucoso, con una base sterile nettamente solcata a forma di gambo; la vescia perlata è bianco-grigia con fini aculei e una parte a gambo liscia e distinta.','Scleroderma metallico-sgradevole; vescia da giovane mite-fungina.','Lo scleroderma a guscio sottile su suoli sabbiosi in brughiera, bosco di latifoglie e conifere, spesso sui bordi dei sentieri; la vescia in boschi e su prati.','Scleroderma in sezione precocemente a spore bruno scuro; giovane vescia ancora a carne bianca senza massa sporale scura.','Tagliare ogni fungo sferico per il lungo: un interno scuro, marmorizzato o nero-viola significa scleroderma — non mangiarlo mai. Solo un interno di un bianco puro e omogeneo in modo continuo è sicuro.','{"Lo scleroderma a guscio sottile ha — a differenza di quello a guscio spesso — una base sterile nettamente marcata, solcata, con cordoni miceliali, il che lo rende esteriormente più simile alla vescia peduncolata e quindi particolarmente confondibile.","La carne di taglio dello scleroderma diventa già da giovane grigiastra fino a marmorizzata scura; la vescia da giovane è di un bianco puro e omogenea.","Guscio dello scleroderma coriaceo, finemente verrucoso di bruno; pelle della vescia molle con fini aculei piramidali caduchi.","Lo scleroderma odora metallico-sgradevole; la giovane vescia mite-fungina."}','f'),
('macrolepiota_mastoidea','lepiota_brunneoincarnata','en','The slender parasol (Macrolepiota mastoidea) shows a pronounced pointed central nipple and a movable ring; the deadly dapperling stays distinctly smaller, flesh-pink-brown in appearance, with an unpatterned, scale-belted stem.','Both inconspicuous to slightly sweetish - smell does NOT separate them, never rely on it.','Both at grassy forest edges, meadows and parks - strong overlap, so reliably separable only by size, the pointed nipple, stem features and the movable ring.','Both with a white spore print - no separating feature.','Since the size difference here is smaller, it applies all the more: accept only dapperlings with a clearly movable ring, a pointed central nipple and a cap clearly above 8 cm; when in doubt leave every small dapperling standing.','{"Slender parasol: cap 6-12 cm with a striking pointed nipple in the centre; flesh-pink dapperling: only 2-5 cm","Slender parasol: movable ring; poisonous dapperling: fleeting, non-movable fibrous ring zone","Slender parasol: stem at most finely/delicately snakeskin-patterned (weaker than in the parasol); poisonous dapperling: stem unpatterned, with flesh-brown scale belts","Slender parasol cap finely light-brown scaly on a whitish ground; poisonous dapperling cap flesh-pink-brown, broken up into concentric scales","The flesh-pink dapperling contains deadly amatoxins; the slender parasol is edible - because the size difference here is smaller, this confusion is especially tricky"}','f'),
('macrolepiota_mastoidea','lepiota_brunneoincarnata','es','La galamperna mamelonada (Macrolepiota mastoidea) muestra un marcado mamelón central puntiagudo y un anillo deslizante; la lepiota mortal permanece claramente más pequeña, de aspecto pardo-rosa carne, con pie no jaspeado y ceñido de escamas.','Ambos discretos hasta ligeramente dulzones - el olor NO los separa, no fiarse nunca de él.','Ambos en bordes de bosque herbosos, prados y parques - fuerte solapamiento, por lo que solo separables con seguridad mediante el tamaño, el mamelón puntiagudo, los caracteres del pie y el anillo deslizante.','Ambos con esporada blanca - ningún rasgo de separación.','Como aquí la diferencia de tamaño es menor, vale con mayor razón: aceptar solo lepiotas con anillo claramente deslizante, mamelón central puntiagudo y sombrero claramente superior a 8 cm; en caso de duda dejar en su sitio toda lepiota pequeña.','{"Galamperna mamelonada: sombrero 6-12 cm con un mamelón puntiagudo llamativo en el centro; lepiota pardo-rosada: solo 2-5 cm","Galamperna mamelonada: anillo deslizante; lepiota tóxica: zona anular fibrosa fugaz, no deslizante","Galamperna mamelonada: pie a lo sumo fina/delicadamente jaspeado (más débil que en el parasol); lepiota tóxica: pie no jaspeado, con cinturones de escamas pardo carne","Sombrero de la galamperna mamelonada finamente escamoso pardo claro sobre fondo blanquecino; sombrero de la lepiota tóxica pardo-rosa carne, disgregado en escamas concéntricas","La lepiota pardo-rosada contiene amatoxinas mortales; la galamperna mamelonada es comestible - como aquí la diferencia de tamaño es menor, esta confusión es especialmente delicada"}','f'),
('macrolepiota_mastoidea','lepiota_brunneoincarnata','fr','La lépiote mamelonnée présente un mamelon central pointu marqué et un anneau coulissant ; la lépiote mortelle reste nettement plus petite, d''aspect brun-rose chair, à pied non chiné et ceinturé de squames.','Tous deux discrets à légèrement douceâtres - l''odeur ne les sépare PAS, ne jamais s''y fier.','Tous deux en lisières de forêt herbeuses, prairies et parcs - fort chevauchement, donc séparables de façon sûre uniquement par la taille, le mamelon pointu, les caractères du pied et l''anneau coulissant.','Tous deux à sporée blanche - pas de critère de séparation.','Comme la différence de taille est ici plus faible, cela vaut d''autant plus : n''accepter que les lépiotes à anneau nettement coulissant, à mamelon central pointu et à chapeau nettement supérieur à 8 cm ; au moindre doute, laisser sur place toute petite lépiote.','{"Lépiote mamelonnée : chapeau 6-12 cm avec un mamelon pointu marquant au centre ; lépiote brun-incarnat : seulement 2-5 cm","Lépiote mamelonnée : anneau coulissant ; lépiote toxique : zone annulaire fibreuse fugace, non coulissante","Lépiote mamelonnée : pied tout au plus finement/délicatement chiné (plus faible que chez le parasol) ; lépiote toxique : pied non chiné, à ceintures de squames brun chair","Chapeau de la lépiote mamelonnée finement squameux brun clair sur fond blanchâtre ; chapeau de la lépiote toxique brun-rose chair, dissocié en squames concentriques","La lépiote brun-incarnat contient des amatoxines mortelles ; la lépiote mamelonnée est comestible - comme la différence de taille est ici plus faible, cette confusion est particulièrement délicate"}','f'),
('macrolepiota_mastoidea','lepiota_brunneoincarnata','it','La lepiota mammellonata mostra un marcato umbone centrale appuntito e un anello scorrevole; la lepiota mortale resta nettamente più piccola, di aspetto bruno-rosa carne, con gambo non zebrato e cinto di squame.','Entrambi insignificanti fino a leggermente dolciastri - l''odore NON li distingue, non fidarsene mai.','Entrambi ai margini erbosi dei boschi, prati e parchi - forte sovrapposizione, quindi distinguibili in sicurezza solo tramite dimensione, umbone appuntito, caratteri del gambo e anello scorrevole.','Entrambi con sporata bianca - nessun criterio di separazione.','Poiché qui la differenza di dimensione è minore, vale a maggior ragione: accettare solo lepiote con anello chiaramente scorrevole, umbone centrale appuntito e cappello nettamente superiore a 8 cm; nel dubbio lasciare sul posto ogni piccola lepiota.','{"Lepiota mammellonata: cappello 6-12 cm con marcato umbone appuntito al centro; lepiota bruno-incarnata: solo 2-5 cm","Lepiota mammellonata: anello scorrevole; lepiota tossica: zona anulare fibrosa fugace, non scorrevole","Lepiota mammellonata: gambo al massimo finemente/delicatamente zebrato (più debole che nel parasol); lepiota tossica: gambo non zebrato, con cinture di squame bruno carne","Cappello della lepiota mammellonata finemente squamoso bruno chiaro su fondo biancastro; cappello della lepiota tossica bruno-rosa carne, dissociato in squame concentriche","La lepiota bruno-incarnata contiene amatossine mortali; la lepiota mammellonata è commestibile - poiché qui la differenza di dimensione è minore, questa confusione è particolarmente insidiosa"}','f'),
('marasmius_oreades','clitocybe_dealbata','en','Ivory funnel / field funnel (Feldtrichterling): smaller, chalky lead-white to cream-yellow, often depressed cap with crowded decurrent gills. Fairy ring mushroom (Nelkenschwindling): leathery brown-yellow cap with an umbo, widely spaced gills, distinctly tougher stem.','Fairy ring mushroom pleasantly spicy (clove/bitter almond) — not perceptible to ~25% of people for genetic reasons, therefore not a stand-alone feature. Field funnel mealy to odourless.','Like C. rivulosa, a typical meadow/lawn mushroom on grassy spots, possibly in fairy rings — exactly within the habitat of the fairy ring mushroom. Location is not suitable for distinguishing them.','Both with WHITE spore powder — not a distinguishing feature. What remains decisive is the gill attachment and the tough stem.','Muscarine acts already in small amounts (sweating, salivation, watering eyes after 15-30 min). Never collect if the gills are crowded and run down the stem — the edible fairy ring mushroom ALWAYS has widely spaced, non-decurrent gills and a tough, pliable stem. The clove smell is only an additional confirmation.','{"Gills: the field funnel has crowded gills, attached to shortly DECURRENT (running down the stem) — the fairy ring mushroom has widely distant, emarginate (notched) gills, NOT decurrent","Cap: the field funnel is chalky lead-white to cream-yellow, smooth/frosted, flat to depressed — the fairy ring mushroom is leather-coloured with a blunt umbo, hygrophanous","Stem: the fairy ring mushroom is tough-pliable, cartilaginous-fibrous — the field funnel is more fibrous and more brittle","Reviving test: the fairy ring mushroom revives after drying — the field funnel does not"}','t'),
('marasmius_oreades','clitocybe_dealbata','es','Clitocybe dealbata: más pequeño, sombrero de color blanco yeso-plomizo a amarillo crema, a menudo deprimido, con láminas apretadas y decurrentes. Marasmius oreades (senderuela): sombrero de color pardo cuero-amarillento con mamelón, láminas separadas, pie claramente más correoso.','La senderuela huele agradablemente especiada (clavo de especia/almendra amarga); ~25% de las personas no lo perciben por causas genéticas, por lo que no es un rasgo aislado. Clitocybe dealbata, harinoso a inodoro.','Como C. rivulosa, es un típico hongo de pradera/césped en lugares cubiertos de hierba, eventualmente en corros de brujas, exactamente en el hábitat de la senderuela. El lugar de crecimiento no sirve para la distinción.','Ambos con esporada BLANCA: no es un rasgo diferenciador. Lo decisivo siguen siendo la disposición de las láminas y el pie correoso.','La muscarina actúa ya en pequeñas cantidades (sudoración, salivación, lagrimeo a los 15-30 min). Nunca recolectar si las láminas están apretadas y decurren por el pie: la comestible senderuela tiene SIEMPRE láminas separadas, no decurrentes, y un pie correoso y flexible. El olor a clavo es solo una confirmación adicional.','{"Láminas: Clitocybe dealbata apretadas, adheridas al pie hasta brevemente DECURRENTES; senderuela muy separadas, escotadas en la inserción, NO decurrentes","Sombrero: Clitocybe dealbata blanco yeso-plomizo a amarillo crema, liso/pruinoso, plano a deprimido; senderuela de color cuero con mamelón obtuso, higrófano","Pie: senderuela correoso-flexible, cartilaginoso-fibroso; Clitocybe dealbata más fibroso y quebradizo","Test de revivificación: la senderuela revive tras secarse; Clitocybe dealbata no"}','t'),
('marasmius_oreades','clitocybe_dealbata','fr','Clitocybe blanc (clitocybe du bord des routes) : chapeau plus petit, blanc plombé crayeux à jaune crème, souvent déprimé, avec des lamelles serrées et décurrentes. Marasme des Oréades (faux mousseron) : chapeau brun-jaune cuir avec un mamelon, lamelles espacées, pied nettement plus coriace.','Le marasme des Oréades a une odeur agréable et épicée (clou de girofle / amande amère) — non perceptible par ~25 % des gens pour des raisons génétiques, donc pas un critère à lui seul. Le clitocybe blanc a une odeur farineuse à inodore.','Comme C. rivulosa, c''est un champignon typique des prairies / pelouses, sur les endroits herbeux, éventuellement en ronds de sorcière — exactement dans l''habitat du marasme des Oréades. La station ne convient pas à la distinction.','Tous deux ont une sporée BLANCHE — aucun critère de distinction. Restent décisifs la disposition des lamelles et le pied coriace.','La muscarine agit déjà à petites doses (sueurs, salivation, larmoiement après 15-30 min). Ne jamais récolter lorsque les lamelles sont serrées et décurrentes le long du pied — le marasme des Oréades comestible a TOUJOURS des lamelles espacées et non décurrentes, ainsi qu''un pied coriace et flexible. L''odeur de clou de girofle n''est qu''une confirmation complémentaire.','{"Lamelles : clitocybe blanc serrées, adnées à brièvement DÉCURRENTES le long du pied — marasme des Oréades très espacées, attachées de façon échancrée, NON décurrentes","Chapeau : clitocybe blanc, blanc plombé crayeux à jaune crème, lisse / pruineux, plan à déprimé — marasme des Oréades couleur cuir avec un mamelon obtus, hygrophane","Pied : marasme des Oréades coriace-flexible, cartilagineux-fibreux — clitocybe blanc plus fibreux et plus cassant","Test de revivification : le marasme des Oréades reprend vie après séchage — le clitocybe blanc non"}','t'),
('marasmius_oreades','clitocybe_dealbata','it','Clitocybe dealbata: più piccolo, cappello da bianco-gesso a giallo-crema, spesso depresso, con lamelle fitte e decorrenti. Marasmius oreades: cappello bruno-giallo cuoio con umbone, lamelle distanziate, gambo nettamente più tenace.','Marasmius oreades dall''odore gradevolmente speziato (chiodo di garofano/mandorla amara) — non percepibile geneticamente da circa il 25% delle persone, quindi non è un carattere a sé stante. Clitocybe dealbata da farinoso a inodore.','Come C. rivulosa è un tipico fungo di prati/tappeti erbosi in punti erbosi, eventualmente in cerchi delle streghe — esattamente nell''habitat del Marasmius oreades. La stazione di crescita non serve alla distinzione.','Entrambi con sporata BIANCA — non è un carattere distintivo. Restano decisivi l''inserzione delle lamelle e il gambo tenace.','La muscarina agisce già in piccole quantità (sudorazione, salivazione, lacrimazione dopo 15-30 min). Non raccogliere mai quando le lamelle sono fitte e decorrono lungo il gambo — il commestibile Marasmius oreades ha SEMPRE lamelle distanziate, non decorrenti, e un gambo tenace e flessibile. L''odore di chiodo di garofano è solo una conferma aggiuntiva.','{"Lamelle: Clitocybe dealbata fitte, da adnate a brevemente DECORRENTI lungo il gambo — Marasmius oreades distanziate, inserite in modo smarginato, NON decorrenti","Cappello: Clitocybe dealbata da bianco-gesso a giallo-crema, liscio/pruinoso, da piano a depresso — Marasmius oreades color cuoio con umbone ottuso, igrofano","Gambo: Marasmius oreades tenace-flessibile, cartilagineo-fibroso — Clitocybe dealbata più fibroso e fragile","Test di rivitalizzazione: il Marasmius oreades rivive dopo l''essiccazione — la Clitocybe dealbata no"}','t'),
('marasmius_oreades','clitocybe_phyllophila','en','The fairy ring mushroom is leather-yellow to beige with an umbo and widely spaced, non-decurrent gills; the white funnel caps are pure white and frosted, with crowded, (weakly) decurrent gills.','The fairy ring mushroom smells pleasantly spicy (clove/bitter almond); the funnel cap is musty-sweetish/perfumed — smell alone is not proof.','The fairy ring mushroom grows in meadows, pastures and lawns (often in fairy rings). Clitocybe phyllophila occurs mainly in the leaf/needle litter of forests, parks and gardens; the truly dangerous WHITE MEADOW funnel caps (C. rivulosa/dealbata), by contrast, share the grassy habitat of the fairy ring mushroom.','Fairy ring mushroom white, frosty funnel cap likewise white/cream — spore colour does NOT separate them here. Therefore check gill arrangement (widely spaced/non-decurrent) and stem toughness.','On meadow/lawn take only mushrooms with a tough-pliable, non-breaking stem and widely spaced, NON-decurrent gills — every white funnel cap with decurrent gills (whether forest or meadow species) is consistently left standing.','{"Fairy ring mushroom: gills widely spaced, pale, NOT decurrent, stem tough-pliable (twists without breaking) — frosty funnel cap: gills crowded and weakly decurrent, stem brittle.","The fairy ring mushroom smells spicy-sweetish (clove/bitter almond); the frosty funnel cap is musty-sweetish/perfumed.","White funnel caps (Clitocybe phyllophila and especially the meadow species C. rivulosa/dealbata) are muscarine-suspect/poisonous — they are the classic dangerous confusion among white-capped meadow mushrooms.","Fairy ring mushroom cap leather-yellow to beige with a blunt central umbo and a translucent-striate margin; white funnel caps glassy-white frosted, often depressed/funnel-shaped.","Safety rule: on grassy sites also watch for the more dangerous white meadow funnel caps (C. rivulosa/dealbata) — not just C. phyllophila."}','f'),
('marasmius_oreades','clitocybe_phyllophila','es','El senderuela (Marasmius oreades) es de color amarillo cuero-beige con mamelón y láminas espaciadas, no decurrentes; los clitocibes blancos son de un blanco puro pruinoso, con láminas apretadas y (débilmente) decurrentes.','La senderuela huele agradablemente a especias (clavo/almendra amarga); el clitocibe es a moho-dulzón/perfumado — el olor por sí solo no es prueba.','La senderuela crece en prados, pastos y céspedes (a menudo en corros de brujas). Clitocybe phyllophila se encuentra sobre todo en la hojarasca de hojas/acículas de bosques, parques y jardines; en cambio, los clitocibes BLANCOS DE PRADO realmente peligrosos (C. rivulosa/dealbata) comparten el hábitat herboso de la senderuela.','Senderuela blanca, clitocibe blanquecino también blanco/crema — el color de las esporas aquí NO separa. Por ello, verificar la disposición de las láminas (espaciadas/no decurrentes) y la tenacidad del pie.','En prado/césped tomar solo setas con pie correoso-flexible, que no se rompe, y con láminas espaciadas, NO decurrentes — todo clitocibe blanco con láminas decurrentes (sea de bosque o de prado) se deja sistemáticamente en su sitio.','{"Senderuela: láminas espaciadas, pálidas, NO decurrentes, pie correoso-flexible (se retuerce sin romperse) — clitocibe blanquecino: láminas apretadas y débilmente decurrentes, pie quebradizo.","La senderuela huele a especias-dulzón (clavo/almendra amarga); el clitocibe blanquecino es a moho-dulzón/perfumado.","Los clitocibes blancos (Clitocybe phyllophila y sobre todo las especies de prado C. rivulosa/dealbata) son sospechosos de muscarina/tóxicos — son la clásica confusión peligrosa de las setas de prado de sombrero blanco.","Sombrero de la senderuela amarillo cuero-beige con mamelón central obtuso y margen translúcido-estriado; clitocibes blancos blanco vítreo pruinoso, a menudo deprimidos/en embudo.","Regla de seguridad: en estaciones herbosas vigilar además los clitocibes blancos de prado más peligrosos (C. rivulosa/dealbata) — no solo C. phyllophila."}','f'),
('marasmius_oreades','clitocybe_phyllophila','fr','Le marasme des Oréades (faux mousseron) est jaune cuir-beige avec un mamelon et des lames espacées, non décurrentes ; les clitocybes blancs sont d''un blanc pur pruineux, à lames serrées et (faiblement) décurrentes.','Le marasme des Oréades a une odeur agréable épicée (clou de girofle/amande amère) ; le clitocybe est moisi-douceâtre/parfumé — l''odeur seule n''est pas une preuve.','Le marasme des Oréades pousse dans les prairies, pâturages et pelouses (souvent en ronds de sorcière). Clitocybe phyllophila se rencontre surtout dans la litière de feuilles/aiguilles des forêts, parcs et jardins ; en revanche les clitocybes BLANCS DES PRAIRIES réellement dangereux (C. rivulosa/dealbata) partagent le milieu gazonné du marasme des Oréades.','Marasme des Oréades blanc, clitocybe blanchâtre également blanc/crème — la couleur des spores ne sépare PAS ici. Vérifier donc la disposition des lames (espacées/non décurrentes) et la ténacité du pied.','En prairie/pelouse, ne prendre que des champignons à pied coriace et souple, ne cassant pas, et à lames espacées, NON décurrentes — tout clitocybe blanc à lames décurrentes (qu''il soit forestier ou prairial) reste systématiquement sur place.','{"Marasme des Oréades : lames espacées, pâles, NON décurrentes, pied coriace-souple (se tord sans casser) — clitocybe blanchâtre : lames serrées et faiblement décurrentes, pied cassant.","Le marasme des Oréades sent l''épicé-douceâtre (clou de girofle/amande amère) ; le clitocybe blanchâtre est moisi-douceâtre/parfumé.","Les clitocybes blancs (Clitocybe phyllophila et surtout les espèces prairiales C. rivulosa/dealbata) sont suspects de teneur en muscarine/toxiques — ils constituent la confusion dangereuse classique des champignons prairiaux à chapeau blanc.","Chapeau du marasme des Oréades jaune cuir-beige avec mamelon central obtus et marge translucide-striée ; clitocybes blancs blanc vitreux pruineux, souvent déprimés/en entonnoir.","Règle de sécurité : sur les stations herbeuses, surveiller en plus les clitocybes blancs des prairies plus dangereux (C. rivulosa/dealbata) — pas seulement C. phyllophila."}','f'),
('marasmius_oreades','clitocybe_phyllophila','it','Il gambesecco (marasmio delle Oreadi) è giallo cuoio-beige con umbone e lamelle distanziate, non decorrenti; i clitocybe bianchi sono bianco puro pruinosi, con lamelle fitte e (debolmente) decorrenti.','Il gambesecco ha un odore gradevole speziato (chiodi di garofano/mandorla amara); il clitocybe è ammuffito-dolciastro/profumato — l''odore da solo non è probante.','Il gambesecco cresce in prati, pascoli e tappeti erbosi (spesso in cerchi delle streghe). Clitocybe phyllophila si trova soprattutto nella lettiera di foglie/aghi di boschi, parchi e giardini; invece i clitocybe BIANCHI DEI PRATI realmente pericolosi (C. rivulosa/dealbata) condividono l''habitat erboso del gambesecco.','Gambesecco bianco, clitocybe biancastro anch''esso bianco/crema — il colore delle spore qui NON distingue. Verificare quindi la disposizione delle lamelle (distanziate/non decorrenti) e la tenacia del gambo.','In prato/tappeto erboso prendere solo funghi con gambo tenace-flessibile, che non si spezza, e con lamelle distanziate, NON decorrenti — ogni clitocybe bianco con lamelle decorrenti (sia di bosco sia di prato) si lascia coerentemente sul posto.','{"Gambesecco: lamelle distanziate, pallide, NON decorrenti, gambo tenace-flessibile (si torce senza spezzarsi) — clitocybe biancastro: lamelle fitte e debolmente decorrenti, gambo fragile.","Il gambesecco profuma di speziato-dolciastro (chiodi di garofano/mandorla amara); il clitocybe biancastro è ammuffito-dolciastro/profumato.","I clitocybe bianchi (Clitocybe phyllophila e soprattutto le specie dei prati C. rivulosa/dealbata) sono sospetti di muscarina/tossici — costituiscono la classica confusione pericolosa dei funghi dei prati a cappello bianco.","Cappello del gambesecco giallo cuoio-beige con umbone centrale ottuso e margine traslucido-striato; clitocybe bianchi bianco vitreo pruinoso, spesso depressi/imbutiformi.","Regola di sicurezza: nelle stazioni erbose fare attenzione anche ai più pericolosi clitocybe bianchi dei prati (C. rivulosa/dealbata) — non solo a C. phyllophila."}','f'),
('marasmius_oreades','clitocybe_rivulosa','en','Fairy ring mushroom (Nelkenschwindling): brownish-yellow cap with a blunt umbo, widely spaced pale gills, tough pliable stem. Fool''s funnel / poison funnel (Gifttrichterling): lead-white to creamy-grey, often depressed/funnel-shaped cap, crowded decurrent gills.','Fairy ring mushroom: pleasantly spicy, of cloves/bitter almond (a hydrocyanic-acid note) — CAUTION: ~25% of people are genetically unable to perceive this smell, so it is not a stand-alone feature. Poison funnel: mealy to odourless. Use smell only as additional confirmation, never as the sole proof of safety.','Both grow in the SAME habitat: meadows, pastures, lawns in gardens/parks; both form fairy rings — no separation by location is possible. This greatly increases the risk of confusion.','Both have WHITE spore powder — a spore print does NOT separate these two. What remains decisive is the gill attachment (decurrent vs. widely spaced/emarginate) and the tough stem.','Golden rule in the meadow: check the gills. The fairy ring mushroom has WIDELY spaced, NON-decurrent gills and a tough, pliable stem. If the gills are crowded and run down the stem — leave it standing (suspicion of the muscarine-containing poison funnel). The spicy clove smell is only an additional confirmation (a quarter of people cannot smell it).','{"Gills (THE main feature): the poison funnel has crowded, shortly DECURRENT (running down the stem) gills — the fairy ring mushroom has DISTANT (widely) spaced gills that are emarginate (notched) at the stem and NOT decurrent","Stem: the fairy ring mushroom''s stem is tough, pliable, cartilaginous-fibrous (can be twisted without breaking) — the funnel cap''s stem is brittle","Cap: the funnel cap is lead-white/creamy-grey, hygrophanous, often depressed/funnel-shaped — the fairy ring mushroom is leathery brownish-yellow with a blunt umbo","Reviving test: the fairy ring mushroom''s fruiting bodies revive after drying (typical of the Marasmius genus) — the poison funnel does not"}','t'),
('marasmius_oreades','clitocybe_rivulosa','es','Senderuela (Nelkenschwindling): sombrero de color pardusco-amarillo con mamelón obtuso, láminas pálidas y separadas, pie correoso y flexible. Clitocybe rivulosa (clitocibe tóxico): sombrero de color blanco plomizo-gris crema, a menudo deprimido/embudado, láminas apretadas y decurrentes.','Senderuela: agradablemente especiada, a clavo de especia/almendra amarga (nota de ácido cianhídrico). ATENCIÓN: ~25% de las personas NO pueden percibir este olor por causas genéticas, por lo que no es un rasgo aislado. Clitocybe tóxico: harinoso a inodoro. Usar el olor solo como confirmación adicional, nunca como única prueba de seguridad.','Ambos crecen en el MISMO lugar: prados, pastos, céspedes en jardines/parques; ambos forman corros de brujas; no es posible separarlos por el hábitat. Esto aumenta enormemente el riesgo de confusión.','Ambos tienen esporada BLANCA: la esporada NO separa a estos dos. Lo decisivo siguen siendo la disposición de las láminas (decurrentes frente a separadas/escotadas) y el pie correoso.','Regla de oro en la pradera: comprobar las láminas. La senderuela tiene láminas MUY separadas, NO decurrentes, y un pie correoso y flexible. Si las láminas están apretadas y decurren por el pie, dejarlo (sospecha de clitocibe tóxico con muscarina). El olor especiado a clavo es solo una confirmación adicional (una cuarta parte de las personas no lo huele).','{"Láminas (EL rasgo principal): el clitocibe tóxico tiene láminas apretadas, brevemente DECURRENTES por el pie; la senderuela tiene láminas SEPARADAS (distanciadas), de inserción escotada en el pie, NO decurrentes","Pie: el pie de la senderuela es correoso, flexible, cartilaginoso-fibroso (se puede retorcer sin romperse); el pie del clitocibe es quebradizo","Sombrero: el clitocibe es blanco plomizo/gris crema, higrófano, a menudo deprimido/embudado; la senderuela de color cuero pardo-amarillento con mamelón obtuso","Test de revivificación: los cuerpos fructíferos de la senderuela reviven tras el secado (típico de los Marasmius); el clitocibe tóxico no"}','t'),
('marasmius_oreades','clitocybe_rivulosa','fr','Marasme des Oréades (faux mousseron) : chapeau brunâtre-jaune avec un mamelon obtus, lamelles pâles espacées, pied coriace et flexible. Clitocybe vénéneux : chapeau blanc plombé à gris crème, souvent déprimé / en entonnoir, lamelles serrées et décurrentes.','Marasme des Oréades : agréablement épicé, odeur de clou de girofle / amande amère (note d''acide cyanhydrique) — ATTENTION : ~25 % des gens ne peuvent PAS percevoir cette odeur pour des raisons génétiques, donc ce n''est pas un critère à lui seul. Clitocybe vénéneux : farineux à inodore. N''utiliser l''odeur que comme confirmation complémentaire, jamais comme seule preuve de sécurité.','Tous deux poussent au MÊME endroit : prairies, pâturages, pelouses de jardins / parcs, et tous deux forment des ronds de sorcière — aucune séparation possible par la station. Cela augmente massivement le risque de confusion.','Tous deux ont une sporée BLANCHE — la sporulation ne sépare PAS ces deux-là. Restent décisifs la disposition des lamelles (décurrentes versus espacées / échancrées) et le pied coriace.','Règle d''or dans la prairie : examiner les lamelles. Le marasme des Oréades a des lamelles TRÈS espacées, NON décurrentes, et un pied coriace et flexible. Si les lamelles sont serrées et décurrentes le long du pied — laisser sur place (suspicion de clitocybe vénéneux contenant de la muscarine). L''odeur épicée de clou de girofle n''est qu''une confirmation complémentaire (un quart des gens ne la sentent pas).','{"Lamelles (LE critère principal) : le clitocybe vénéneux a des lamelles serrées, brièvement DÉCURRENTES le long du pied — le marasme des Oréades a des lamelles ESPACÉES (largement), attachées de façon échancrée au pied, NON décurrentes","Pied : le pied du marasme des Oréades est coriace, flexible, cartilagineux-fibreux (il se tord sans casser) — le pied du clitocybe est cassant","Chapeau : clitocybe blanc plombé / gris crème, hygrophane, souvent déprimé / en entonnoir — marasme des Oréades brun-jaune cuir avec un mamelon obtus","Test de revivification : les carpophores du marasme des Oréades reprennent vie après séchage (typique des marasmes) — le clitocybe vénéneux non"}','t'),
('marasmius_oreades','clitocybe_rivulosa','it','Marasmius oreades: cappello da brunastro a giallo con umbone ottuso, lamelle pallide distanziate, gambo tenace e flessibile. Clitocybe rivulosa: cappello da bianco-piombo a grigio-crema, spesso depresso/imbutiforme, lamelle fitte e decorrenti.','Marasmius oreades: gradevolmente speziato di chiodi di garofano/mandorla amara (nota di acido cianidrico) — ATTENZIONE: circa il 25% delle persone, per ragioni genetiche, NON può percepire questo odore, quindi non è un carattere a sé stante. Clitocybe rivulosa: da farinoso a inodore. Usare l''odore solo come conferma aggiuntiva, mai come unica prova di sicurezza.','Entrambi crescono nella STESSA stazione: prati, pascoli, tappeti erbosi in giardini/parchi, entrambi formano cerchi delle streghe — nessuna separazione possibile in base alla stazione. Questo aumenta enormemente il rischio di confusione.','Entrambi hanno sporata BIANCA — la sporata NON distingue questi due. Restano decisivi l''inserzione delle lamelle (decorrenti vs. distanziate/smarginate) e il gambo tenace.','Regola d''oro sul prato: controllare le lamelle. Il Marasmius oreades ha lamelle DISTANZIATE, NON decorrenti, e un gambo tenace e flessibile. Se le lamelle sono fitte e decorrono lungo il gambo — lasciarlo stare (sospetto di Clitocybe contenente muscarina). Il gradevole odore di chiodo di garofano è solo una conferma aggiuntiva (un quarto delle persone non lo sente).','{"Lamelle (IL carattere principale): la Clitocybe rivulosa ha lamelle fitte, brevemente DECORRENTI (decorrenti) lungo il gambo — il Marasmius oreades ha lamelle DISTANZIATE (distanti), inserite in modo smarginato al gambo, NON decorrenti","Gambo: il gambo del Marasmius oreades è tenace, flessibile, cartilagineo-fibroso (si può torcere senza spezzarsi) — il gambo della Clitocybe è fragile","Cappello: la Clitocybe da bianco-piombo/grigio-crema, igrofano, spesso depresso/imbutiforme — il Marasmius oreades da bruno-cuoio a giallo con umbone ottuso","Test di rivitalizzazione: i corpi fruttiferi del Marasmius oreades rivivono dopo l''essiccazione (tipico dei Marasmius) — la Clitocybe no"}','t'),
('marasmius_oreades','gymnopus_peronatus','en','The fairy ring mushroom (Marasmius oreades) has broad, distant gills and a leather-yellow umbonate cap; the wood woollyfoot (Gymnopus peronatus) has more crowded gills and a strigose stem base.','The fairy ring mushroom smells pleasantly spicy and almond-like; Gymnopus peronatus has an inconspicuous to vinegary smell (when rubbed) and a burning, acrid taste.','The fairy ring mushroom grows in meadows/lawns in fairy rings; Gymnopus peronatus in forest leaf/needle litter — the habitat helps clearly to separate them.','Both have a whitish spore print — no distinguishing feature.','Meadow habitat + distant gills + almond smell = fairy ring mushroom; forest litter + sharp burning taste = Gymnopus peronatus, suspected toxic. Spit out the taste test.','{"Gymnopus peronatus: sharp, burning, peppery taste, crowded gills, in deciduous forest litter, strigose-felty stem base.","Fairy ring mushroom: mild, pleasant smell (spicy, almond-like/hydrocyanic note), broad and DISTANT gills, grows in meadows/lawns (fairy rings), tough flexible stem.","Fairy ring mushroom cap with a distinct blunt umbo, leather-yellow to buff; Gymnopus peronatus yellowish-brown to leather-brown without clove smell.","Gymnopus peronatus acrid/suspected toxic-stomach-irritating — the fairy ring mushroom is a classic mild edible."}','f'),
('marasmius_oreades','gymnopus_peronatus','es','El senderuela (Marasmius oreades) tiene láminas anchas y separadas y un sombrero amarillo cuero con mamelón; Gymnopus peronatus tiene láminas más apretadas y una base del pie estrigosa.','La senderuela huele agradablemente especiado y a almendra; Gymnopus peronatus tiene un olor discreto a avinagrado (al frotar) y un sabor ardiente y acre.','La senderuela crece en prados/céspedes en corros de brujas; Gymnopus peronatus en la hojarasca de hojas/acículas del bosque — la estación ayuda claramente a separarlos.','Ambos tienen esporada blanquecina — ningún criterio distintivo.','Estación de pradera + láminas separadas + olor a almendra = senderuela; hojarasca forestal + sabor acre ardiente = Gymnopus peronatus, sospechoso de ser tóxico. Escupir la prueba de sabor.','{"Gymnopus peronatus: sabor acre, ardiente, picante, láminas apretadas, en la hojarasca de frondosas del bosque, base del pie estrigosa-afieltrada.","Senderuela: suave, olor agradable (especiado, a almendra/nota de ácido cianhídrico), láminas anchas y SEPARADAS, crece en prados/céspedes (corros de brujas), pie tenaz y flexible.","Sombrero de la senderuela con un mamelón obtuso neto, amarillo cuero-color pan; Gymnopus peronatus pardo amarillento-pardo cuero sin olor a clavel.","Gymnopus peronatus acre/sospechoso de ser tóxico-irritante para el estómago — la senderuela es un comestible suave clásico."}','f'),
('marasmius_oreades','gymnopus_peronatus','fr','Le marasme des Oréades a des lamelles espacées, écartées et un chapeau mamelonné jaune-cuir ; le collybie à pied feutré des lamelles plus serrées et une base du pied strigueuse.','Marasme des Oréades sent agréablement épicé-amande ; le collybie à pied feutré sent discret à vinaigré (au frottement) et a un goût brûlant-âcre.','Marasme des Oréades pousse sur prairies/pelouses en ronds de sorcières ; le collybie à pied feutré dans la litière de feuillus/conifères en forêt – la station aide nettement à séparer.','Les deux à sporée blanchâtre – pas un critère de séparation.','Station prairie + lamelles espacées + odeur d''amande = marasme des Oréades ; litière forestière + goût brûlant-âcre = collybie à pied feutré suspect de toxicité. Recracher l''échantillon gustatif.','{"Collybie à pied feutré : goût âcre-brûlant poivré, lamelles serrées, dans la litière de feuillus en forêt, base du pied strigueuse-feutrée","Marasme des Oréades : doux, odeur agréable (épicée, d''amande/note cyanhydrique), lamelles larges et ÉCARTÉES, pousse sur prairies/pelouses (ronds de sorcières), pied coriace flexible","Chapeau du marasme des Oréades avec un mamelon obtus net, jaune-cuir-fauve ; collybie à pied feutré jaune-brun-brun-cuir sans odeur d''œillet","Collybie à pied feutré âcre/suspect de toxicité-irritant pour l''estomac – marasme des Oréades comestible doux classique"}','f'),
('marasmius_oreades','gymnopus_peronatus','it','Il gambosecco (Marasmius oreades) ha lamelle larghe e distanziate e un cappello giallo-cuoio umbonato; Gymnopus peronatus ha lamelle più fitte e una base del gambo strigosa.','Il gambosecco ha odore gradevole, speziato e di mandorla; Gymnopus peronatus ha odore poco appariscente fino ad acetoso (allo sfregamento) e sapore bruciante e acre.','Il gambosecco cresce nei prati/tappeti erbosi in cerchi delle streghe; Gymnopus peronatus nella lettiera di foglie/aghi del bosco — la stazione aiuta nettamente a separarli.','Entrambi hanno sporata biancastra — nessun criterio distintivo.','Stazione di prato + lamelle distanziate + odore di mandorla = gambosecco; lettiera forestale + sapore acre bruciante = Gymnopus peronatus sospetto velenoso. Sputare la prova di assaggio.','{"Gymnopus peronatus: sapore acre-bruciante pepato, lamelle fitte, nella lettiera di latifoglie del bosco, base del gambo strigosa-feltrata.","Gambosecco: mite, odore gradevole (speziato, di mandorla/nota di acido cianidrico), lamelle larghe e DISTANZIATE, cresce nei prati/tappeti erbosi (cerchi delle streghe), gambo tenace e flessibile.","Cappello del gambosecco con umbone ottuso netto, giallo-cuoio-color pane; Gymnopus peronatus bruno-giallastro-bruno cuoio senza odore di garofano.","Gymnopus peronatus acre/sospetto velenoso-irritante per lo stomaco — il gambosecco è un classico fungo commestibile mite."}','f'),
('marasmius_oreades','inocybe_erubescens','en','Fibrecap (Risspilz): conical-umbonate cap, radially split open, whitish and turning brick-red over time/under pressure, with darkening (olive-pink-brownish) gills. Fairy ring mushroom (Nelkenschwindling): smooth leather-coloured cap with a blunt umbo, gills staying pale and widely spaced.','Fairy ring mushroom pleasantly spicy (clove/bitter almond; not perceptible to ~25%). Brick-red fibrecap faintly fruity, unpleasantly sweetish-spermatic with age. Use smell only as an addition, never alone.','The brick-red fibrecap grows lime-loving (calcareous), mainly in deciduous/mixed forests, parks and under shrubbery (mycorrhiza with beech/lime), partly also on lawns — not primarily open meadow like the fairy ring mushroom. Location helps but is NOT a stand-alone safety feature (also possible on lawns/park lawns).','DECISIVE and life-saving: the fibrecap has dark-brown spore powder — the fairy ring mushroom white. A spore print separates the two unambiguously.','Spore-powder check as a lifesaver: white = fairy ring mushroom possible, brown = NEVER eat. In addition, these expose the deadly fibrecap: fissured-radially-fibrous cap, brick-red discolouration (under pressure) and the spermatic smell. Muscarine — a deadly amount already from approx. 40-500 g of fresh mushroom.','{"Spore powder (DECISIVE): the fibrecap has DARK-BROWN spore powder, the gills change from white/cream over olive-grey-pink to mottled-brownish — the fairy ring mushroom has WHITE spore powder and persistently pale gills","Reddening: the fibrecap reddens brick-red (cap/stem/flesh, especially under pressure and with age) — the fairy ring mushroom does NOT redden","Cap surface: the fibrecap is conical-umbonate, radially fibrous and splitting open/fissured (''Risspilz'', i.e. fissure mushroom) — the fairy ring mushroom is smooth, hygrophanous, with a blunt umbo","Smell: the fibrecap is spermatic/fruity-unpleasant — the fairy ring mushroom spicy, of cloves/bitter almond"}','t'),
('marasmius_oreades','inocybe_erubescens','es','Inocybe (seta de fibrillas): sombrero cónico-mamelonado, agrietado radialmente, blanquecino y que con el tiempo/la presión se torna rojo ladrillo, láminas que oscurecen (de color oliváceo-rosado-parduzco). Senderuela: sombrero liso de color cuero con mamelón obtuso, láminas separadas que permanecen pálidas.','Senderuela agradablemente especiada (clavo de especia/almendra amarga; no perceptible por ~25%). Inocybe erubescens (rojo ladrillo) débilmente afrutado, con la edad desagradablemente dulzón-espermático. El olor solo como complemento, nunca aislado.','Inocybe erubescens crece, amante de la cal, sobre todo en bosques de frondosas/mixtos, parques y bajo matorrales (micorriza con haya/tilo), en parte también en céspedes; no principalmente en pradera abierta como la senderuela. El lugar de crecimiento ayuda, pero NO es un rasgo de seguridad aislado (también posible en césped/césped de parque).','DECISIVO y salvavidas: el inocybe tiene esporada de color pardo oscuro; la senderuela, blanca. Una esporada separa a ambos de forma inequívoca.','La comprobación de la esporada como salvavidas: blanca = posible senderuela; parda = NUNCA comer. Además delatan al mortal inocybe: sombrero agrietado-radialmente fibroso, el tornarse rojo ladrillo (a la presión) y el olor espermático. Muscarina: cantidad mortal ya a partir de ~40-500 g de hongo fresco.','{"Esporada (DECISIVO): el inocybe tiene esporada PARDA OSCURA, las láminas viran de blanco/crema pasando por gris oliva-rosado a parduzco-manchado; la senderuela tiene esporada BLANCA y láminas que permanecen pálidas","Enrojecimiento: el inocybe se torna rojo ladrillo (sombrero/pie/carne, sobre todo a la presión y con la edad); la senderuela NO se enrojece","Superficie del sombrero: el inocybe es cónico-mamelonado, radialmente fibroso y agrietado/resquebrajado (''Risspilz''); la senderuela es lisa, higrófana, con mamelón obtuso","Olor: el inocybe espermático/afrutado-desagradable; la senderuela especiada a clavo de especia/almendra amarga"}','t'),
('marasmius_oreades','inocybe_erubescens','fr','Inocybe (de Patouillard) : chapeau conique mamelonné, fendillé radialement, blanchâtre et virant au rouge brique avec le temps / la pression, lamelles se ternissant (gris rosé-brunâtre). Marasme des Oréades : chapeau lisse couleur cuir avec un mamelon obtus, lamelles espacées restant pâles.','Marasme des Oréades : agréablement épicé (clou de girofle / amande amère ; non perceptible par ~25 % des gens). Inocybe rouge brique : faiblement fruité, désagréablement douceâtre-spermatique avec l''âge. L''odeur seulement en complément, jamais seule.','L''inocybe rouge brique pousse de préférence sur sol calcaire, surtout dans les forêts de feuillus / mixtes, les parcs et sous les buissons (mycorhize avec le hêtre / le tilleul), parfois aussi sur des pelouses — pas principalement en prairie ouverte comme le marasme des Oréades. La station aide, mais n''est PAS un critère de sécurité à lui seul (possible aussi sur pelouse / gazon de parc).','DÉCISIF et vital : l''inocybe a une sporée brun foncé — le marasme des Oréades une sporée blanche. Une sporulation sépare les deux de façon univoque.','Le contrôle de la sporée comme sauveur de vie : blanc = marasme des Oréades possible, brun = NE JAMAIS manger. En outre, démasquent l''inocybe mortel : chapeau fendillé-radialement fibreux, virage au rouge brique (à la pression) et l''odeur spermatique. Muscarine — dose mortelle dès ~40-500 g de champignon frais.','{"Sporée (DÉCISIF) : l''inocybe a une sporée BRUN FONCÉ, les lamelles passent du blanc / crème au gris-olive rosé puis au brunâtre tacheté — le marasme des Oréades a une sporée BLANCHE et des lamelles restant pâles","Rougissement : l''inocybe rougit au rouge brique (chapeau / pied / chair, surtout à la pression et avec l''âge) — le marasme des Oréades ne rougit PAS","Surface du chapeau : l''inocybe conique-mamelonné, radialement fibreux et se fendillant / fissurant (''Risspilz'', inocybe) — le marasme des Oréades lisse, hygrophane, avec un mamelon obtus","Odeur : l''inocybe spermatique / fruité-désagréable — le marasme des Oréades épicé, de clou de girofle / amande amère"}','t'),
('marasmius_oreades','inocybe_erubescens','it','Inocybe erubescens: cappello conico-umbonato, lacerato radialmente, biancastro e che con il tempo/la pressione vira al rosso-mattone, lamelle che scuriscono (da oliva-rosa a brunastre). Marasmius oreades: cappello liscio color cuoio con umbone ottuso, lamelle distanziate che restano pallide.','Marasmius oreades gradevolmente speziato (chiodo di garofano/mandorla amara; non percepibile da circa il 25%). Inocybe erubescens debolmente fruttato, da vecchio sgradevolmente dolciastro-spermatico. L''odore solo come aggiunta, mai da solo.','L''Inocybe erubescens cresce, amante del calcare, soprattutto in boschi di latifoglie/misti, parchi e sotto cespugli (micorriza con faggio/tiglio), in parte anche su tappeti erbosi — non principalmente in prato aperto come il Marasmius oreades. La stazione aiuta, ma NON è un carattere di sicurezza a sé stante (possibile anche su tappeti erbosi/prati di parco).','DECISIVO e salvavita: l''Inocybe erubescens ha sporata bruno-scura — il Marasmius oreades bianca. Una sporata distingue i due in modo inequivocabile.','Controllo della sporata come salvavita: bianca = possibile Marasmius oreades, bruna = NON mangiare MAI. Inoltre smascherano il mortale Inocybe erubescens: il cappello fessurato-radialmente fibroso, il viraggio al rosso-mattone (sotto pressione) e l''odore spermatico. Muscarina — quantità mortale già a partire da circa 40-500 g di fungo fresco.','{"Sporata (DECISIVA): l''Inocybe erubescens ha sporata BRUNO-SCURA, le lamelle virano da bianco/crema attraverso grigio-oliva-rosa fino a brunastro-macchiato — il Marasmius oreades ha sporata BIANCA e lamelle che restano pallide","Arrossamento: l''Inocybe erubescens arrossa al rosso-mattone (cappello/gambo/carne, soprattutto sotto pressione e da vecchio) — il Marasmius oreades NON arrossa","Superficie del cappello: l''Inocybe erubescens conico-umbonato, fibroso-radiale e fessurato/lacerato (''Risspilz'') — il Marasmius oreades liscio, igrofano, con umbone ottuso","Odore: l''Inocybe erubescens spermatico/fruttato-sgradevole — il Marasmius oreades speziato di chiodi di garofano/mandorla amara"}','t'),
('marasmius_oreades','inocybe_geophylla','en','The pure white-silky, sharply umbonate cap surface of the white fibrecap differs from the leather-yellow-brownish, bluntly umbonate fairy ring mushroom.','Fairy ring mushroom: of bitter almond; white fibrecap: spermatic-earthy.','Both at the edges of meadows, paths and woods in short grass; habitat does not separate them, so check gill colour, smell and stem consistency.','Fairy ring mushroom: WHITE spore print; white fibrecap: tobacco-/ochre-brown spore print - a sure separating feature.','Eat small white/light-brown meadow mushrooms only if the spore print stays WHITE; any silky-white cap with brown spore dust and a spermatic smell is a fibrecap - discard.','{"Fairy ring mushroom: gills whitish-cream, thick and distant; white fibrecap: gills whitish when young, soon clay-/tobacco-brown","Fairy ring mushroom: cap leather-yellow-light brown with a blunt umbo; white form of the fibrecap: pure white to cream, silky-fibrous with a pointed umbo","Fairy ring mushroom: stem tough-pliable (bends around the finger); fibrecap: stem brittle, thin","The white fibrecap contains much muscarine (sweating, salivation, watering eyes 15-30 min after eating); the fairy ring mushroom is edible"}','f'),
('marasmius_oreades','inocybe_geophylla','es','La superficie del sombrero de un blanco puro-sedoso, con mamelón puntiagudo, del inocibe terrígeno se distingue de la senderuela amarillo cuero-parduzca con mamelón obtuso.','Senderuela: a almendra amarga; inocibe terrígeno: espermático-terroso.','Ambos en los bordes de prados, caminos y bosques en hierba corta; el hábitat no separa, por lo que hay que verificar el color de las láminas, el olor y la consistencia del pie.','Senderuela: esporada BLANCA; inocibe terrígeno: esporada pardo tabaco/ocre - rasgo de separación seguro.','Comer las setas pequeñas blancas/pardo claro de prado solo si la esporada permanece BLANCA; todo sombrero blanco sedoso con polvo de esporas pardo y olor espermático es un inocibe - desechar.','{"Senderuela: láminas blanquecinas-crema, gruesas y espaciadas; inocibe terrígeno: láminas de joven blanquecinas, pronto arcillosas-/pardo tabaco","Senderuela: sombrero amarillo cuero-pardo claro con mamelón obtuso; forma blanca del inocibe: blanco puro a crema, sedoso-fibrilloso con mamelón puntiagudo","Senderuela: pie correoso-flexible (se dobla alrededor del dedo); inocibe: pie quebradizo, delgado","El inocibe terrígeno contiene mucha muscarina (sudoración, salivación, lagrimeo 15-30 min después de comerlo); la senderuela es comestible"}','f'),
('marasmius_oreades','inocybe_geophylla','fr','La surface du chapeau d''un blanc pur soyeux, à mamelon pointu, de l''inocybe à feuilles le distingue du marasme des Oréades jaune cuir-brunâtre à mamelon obtus.','Marasme des Oréades : odeur d''amande amère ; inocybe à feuilles : spermatique-terreux.','Tous deux en bordure de prairies, de chemins et de forêts dans l''herbe rase ; l''habitat ne sépare pas, donc vérifier la couleur des lames, l''odeur et la consistance du pied.','Marasme des Oréades : sporée BLANCHE ; inocybe à feuilles : sporée brun tabac/ocre - critère de séparation sûr.','Ne consommer les petits champignons blancs/brun clair des prairies que si la sporée reste BLANCHE ; tout chapeau blanc soyeux à poussière sporale brune et à odeur spermatique est un inocybe - à rejeter.','{"Marasme des Oréades : lames blanchâtres-crème, épaisses et espacées ; inocybe à feuilles : lames jeunes blanchâtres, bientôt argilo-/brun tabac","Marasme des Oréades : chapeau jaune cuir-brun clair à mamelon obtus ; forme blanche de l''inocybe : blanc pur à crème, soyeux-fibrilleux avec mamelon pointu","Marasme des Oréades : pied coriace-souple (se plie autour du doigt) ; inocybe : pied cassant, mince","L''inocybe à feuilles contient beaucoup de muscarine (sueur, salivation, larmoiement 15-30 min après ingestion) ; le marasme des Oréades est comestible"}','f'),
('marasmius_oreades','inocybe_geophylla','it','La superficie del cappello bianco puro-setoso, ad umbone appuntito, dell''inocibe terrigeno si distingue dal gambesecco giallo cuoio-brunastro ad umbone ottuso.','Gambesecco: di mandorla amara; inocibe terrigeno: spermatico-terroso.','Entrambi ai margini di prati, sentieri e boschi nell''erba corta; l''habitat non distingue, quindi verificare colore delle lamelle, odore e consistenza del gambo.','Gambesecco: sporata BIANCA; inocibe terrigeno: sporata bruno tabacco/ocra - criterio di separazione sicuro.','Mangiare i piccoli funghi bianchi/bruno chiaro dei prati solo se la sporata resta BIANCA; ogni cappello bianco setoso con polvere sporale bruna e odore spermatico è un inocibe - scartare.','{"Gambesecco: lamelle biancastre-crema, spesse e distanziate; inocibe terrigeno: lamelle da giovani biancastre, presto argillose-/bruno tabacco","Gambesecco: cappello giallo cuoio-bruno chiaro con umbone ottuso; forma bianca dell''inocibe: bianco puro fino a crema, setoso-fibrilloso con umbone appuntito","Gambesecco: gambo tenace-flessibile (si piega attorno al dito); inocibe: gambo fragile, sottile","L''inocibe terrigeno contiene molta muscarina (sudorazione, salivazione, lacrimazione 15-30 min dopo l''ingestione); il gambesecco è commestibile"}','f'),
('marasmius_oreades','inocybe_rimosa','en','The fairy ring mushroom''s tough, pliable stem and smooth leather-yellow cap distinguish it from the fissured-conical, brittle fibrecap.','Fairy ring mushroom: pleasant bitter-almond smell; fibrecap: spermatic-unpleasant.','Both in meadows and short grass; the fairy ring mushroom often grows in fairy rings, but habitat does not separate them reliably.','Fairy ring mushroom: WHITE spore print; conical fibrecap: tobacco-/grey-brown spore print - a sure separating feature.','In meadows take only mushrooms with whitish gills, a white spore print and a pliable-tough stem; any fissured, brown-spored, spermatic-smelling cap is a poisonous fibrecap - discard at once.','{"Fairy ring mushroom: gills whitish-cream, thick, distant; fibrecap: gills soon clay-grey-brown, more crowded","Fairy ring mushroom: cap light brown-leather yellow, smooth with a blunt umbo, stem tough-pliable (bends without breaking); fibrecap: cap radially SPLIT, conical, stem brittle","The fairy ring mushroom smells pleasantly of bitter almond; the fibrecap smells spermatic-earthy","Fibrecaps contain muscarine - dangerous in quantity; the fairy ring mushroom is edible (cook thoroughly)"}','f'),
('marasmius_oreades','inocybe_rimosa','es','El pie correoso y flexible y el sombrero liso amarillo cuero de la senderuela la distinguen del inocibe fisurado-cónico y quebradizo.','Senderuela: agradable olor a almendra amarga; inocibe: espermático-desagradable.','Ambos en prados y hierba corta; la senderuela crece a menudo en corros de brujas, pero el hábitat no los separa de forma fiable.','Senderuela: esporada BLANCA; inocibe de sombrero cónico: esporada pardo tabaco/gris-parda - rasgo de separación seguro.','En el prado tomar solo setas con láminas blanquecinas, esporada blanca y pie flexible-correoso; todo sombrero fisurado, de esporas pardas, de olor espermático es un inocibe tóxico - desechar de inmediato.','{"Senderuela: láminas blanquecinas-crema, gruesas, espaciadas; inocibe: láminas pronto arcillosas-gris-pardas, más apretadas","Senderuela: sombrero pardo claro-amarillo cuero, liso con mamelón obtuso, pie correoso-flexible (se dobla sin romperse); inocibe: sombrero RASGADO radialmente, cónico, pie quebradizo","La senderuela huele agradablemente a almendra amarga; el inocibe huele a espermático-terroso","Los inocibes contienen muscarina - peligrosos en cantidad; la senderuela es comestible (cocinar bien)"}','f'),
('marasmius_oreades','inocybe_rimosa','fr','Le pied coriace et souple et le chapeau lisse jaune cuir du marasme des Oréades le distinguent de l''inocybe fissuré-conique et cassant.','Marasme des Oréades : agréable odeur d''amande amère ; inocybe : spermatique-désagréable.','Tous deux dans les prairies et l''herbe rase ; le marasme des Oréades pousse souvent en ronds de sorcière, mais l''habitat ne les sépare pas de façon fiable.','Marasme des Oréades : sporée BLANCHE ; inocybe à chapeau conique : sporée brun tabac/gris-brun - critère de séparation sûr.','En prairie, ne prendre que des champignons à lames blanchâtres, sporée blanche et pied souple-coriace ; tout chapeau fissuré, à spores brunes, à odeur spermatique est un inocybe toxique - à rejeter aussitôt.','{"Marasme des Oréades : lames blanchâtres-crème, épaisses, espacées ; inocybe : lames bientôt argilo-gris-brun, plus denses","Marasme des Oréades : chapeau brun clair-jaune cuir, lisse à mamelon obtus, pied coriace-souple (se plie sans casser) ; inocybe : chapeau FENDU radialement, conique, pied cassant","Le marasme des Oréades sent agréablement l''amande amère ; l''inocybe sent le spermatique-terreux","Les inocybes contiennent de la muscarine - dangereux en quantité ; le marasme des Oréades est comestible (bien cuire)"}','f'),
('marasmius_oreades','inocybe_rimosa','it','Il gambo tenace e flessibile e il cappello liscio giallo cuoio del gambesecco lo distinguono dall''inocibe fessurato-conico e fragile.','Gambesecco: gradevole odore di mandorla amara; inocibe: spermatico-sgradevole.','Entrambi in prati ed erba corta; il gambesecco cresce spesso in cerchi delle streghe, ma l''habitat non li distingue in modo affidabile.','Gambesecco: sporata BIANCA; inocibe a cappello conico: sporata bruno tabacco/grigio-bruna - criterio di separazione sicuro.','In prato prendere solo funghi con lamelle biancastre, sporata bianca e gambo flessibile-tenace; ogni cappello fessurato, a spore brune, dall''odore spermatico è un inocibe tossico - scartare subito.','{"Gambesecco: lamelle biancastre-crema, spesse, distanziate; inocibe: lamelle presto argillose-grigio-brune, più fitte","Gambesecco: cappello bruno chiaro-giallo cuoio, liscio con umbone ottuso, gambo tenace-flessibile (si piega senza spezzarsi); inocibe: cappello FESSURATO radialmente, conico, gambo fragile","Il gambesecco profuma gradevolmente di mandorla amara; l''inocibe profuma di spermatico-terroso","Gli inocibi contengono muscarina - pericolosi in quantità; il gambesecco è commestibile (cuocere bene)"}','f'),
('marasmius_oreades','lepiota_cristata','en','Lepiota cristata whitish cap with a red-brown concentric ring of scales, dark centre and stem ring; fairy ring mushroom smooth ochre umbonate cap without scales and without a ring.','Lepiota cristata pungently unpleasant of coal gas/burnt rubber; fairy ring mushroom pleasant of bitter almond/hydrocyanic acid - the coal-gas smell is a clear warning signal.','Both at grassy spots, path edges, in parks and on meadows - the same habitat favours the confusion.','Both white (in Lepiota cristata occasionally minimally cream-coloured) spore print - no reliable separating feature.','As a matter of principle leave small ringed dapperlings standing in meadows; the ringless, tough, twistable stem is the only reliable feature of the fairy ring mushroom - if it is missing, do not collect.','{"Lepiota cristata is poisonous (gastrointestinal upset; in this genus every small dapperling is regarded as amatoxin-suspect); the fairy ring mushroom is edible","Lepiota cristata smells unpleasantly pungent of coal gas/burnt rubber; the fairy ring mushroom smells pleasantly of bitter almond/hydrocyanic acid to sweetish","Lepiota cristata has a (fleeting) ring and a brittle stem; the fairy ring mushroom has NO ring and a tough, pliable stem","Lepiota cristata: whitish cap with red-brown concentrically arranged scales and a small dark disc in the centre; fairy ring mushroom: smooth ochre- to buff-coloured umbonate cap without scales","Lepiota cristata with crowded, free, white gills; fairy ring mushroom with thick, widely spaced, emarginate-adnate gills"}','f'),
('marasmius_oreades','lepiota_cristata','es','Lepiota cristata: sombrero blanquecino con una corona de escamas concéntricas pardo-rojas, centro oscuro y anillo en el pie; senderuela: sombrero liso ocre con mamelón, sin escamas y sin anillo.','Lepiota cristata: olor acre desagradable a gas de alumbrado/goma quemada; senderuela: agradable a almendra amarga/ácido cianhídrico - el olor a gas de alumbrado es una clara señal de alarma.','Ambos en lugares herbosos, bordes de caminos, parques y prados - el mismo hábitat favorece la confusión.','Ambos con esporada blanca (en Lepiota cristata ocasionalmente mínimamente color crema) - ningún rasgo de separación fiable.','Por principio dejar en su sitio en el prado las lepiotas pequeñas con anillo; el pie sin anillo, correoso y retorcible es el único rasgo fiable de la senderuela - si falta, no recolectar.','{"Lepiota cristata es tóxica (trastornos gastrointestinales; en este género toda lepiota pequeña se considera sospechosa de amatoxinas); la senderuela es comestible","Lepiota cristata huele desagradablemente acre a gas de alumbrado/goma quemada; la senderuela huele agradablemente a almendra amarga/ácido cianhídrico hasta dulzón","Lepiota cristata tiene un anillo (fugaz) y un pie quebradizo; la senderuela NO tiene anillo y tiene un pie correoso, flexible","Lepiota cristata: sombrero blanquecino con escamas pardo-rojas dispuestas concéntricamente y un pequeño disco oscuro en el centro; senderuela: sombrero con mamelón liso ocre hasta color pan sin escamas","Lepiota cristata con láminas apretadas, libres, blancas; senderuela con láminas gruesas, espaciadas, escotado-adnadas"}','f'),
('marasmius_oreades','lepiota_cristata','fr','Lepiota cristata : chapeau blanchâtre à couronne de squames concentriques brun-rouge, centre sombre et anneau au pied ; marasme des Oréades : chapeau lisse ocre à mamelon, sans squames et sans anneau.','Lepiota cristata : odeur âcre désagréable de gaz d''éclairage/caoutchouc brûlé ; marasme des Oréades : agréable odeur d''amande amère/acide cyanhydrique - l''odeur de gaz d''éclairage est un signal d''alarme net.','Tous deux dans les endroits herbeux, bords de chemins, parcs et prairies - le même habitat favorise la confusion.','Tous deux à sporée blanche (parfois minimalement crème chez Lepiota cristata) - pas de critère de séparation fiable.','Par principe, laisser sur place en prairie les petites lépiotes annelées ; le pied sans anneau, coriace et torsadable est le seul critère fiable du marasme des Oréades - s''il manque, ne pas ramasser.','{"Lepiota cristata est toxique (troubles gastro-intestinaux ; dans ce genre, toute petite lépiote est considérée comme suspecte d''amatoxines) ; le marasme des Oréades est comestible","Lepiota cristata sent désagréablement âcre le gaz d''éclairage/caoutchouc brûlé ; le marasme des Oréades sent agréablement l''amande amère/acide cyanhydrique à douceâtre","Lepiota cristata a un anneau (fugace) et un pied cassant ; le marasme des Oréades n''a PAS d''anneau et a un pied coriace, souple","Lepiota cristata : chapeau blanchâtre à squames brun-rouge disposées concentriquement et petit disque sombre au centre ; marasme des Oréades : chapeau à mamelon lisse ocre à couleur pain sans squames","Lepiota cristata à lames serrées, libres, blanches ; marasme des Oréades à lames épaisses, espacées, échancrées-adnées"}','f'),
('marasmius_oreades','lepiota_cristata','it','Lepiota cristata: cappello biancastro con corona di squame concentriche bruno-rosse, centro scuro e anello al gambo; gambesecco: cappello liscio ocra con umbone, senza squame e senza anello.','Lepiota cristata: odore acre sgradevole di gas illuminante/gomma bruciata; gambesecco: gradevole di mandorla amara/acido cianidrico - l''odore di gas illuminante è un chiaro segnale d''allarme.','Entrambi in luoghi erbosi, bordi di sentieri, parchi e prati - lo stesso habitat favorisce la confusione.','Entrambi con sporata bianca (in Lepiota cristata occasionalmente minimamente color crema) - nessun criterio di separazione affidabile.','Per principio lasciare sul posto in prato le piccole lepiote con anello; il gambo senza anello, tenace e torcibile è l''unico criterio affidabile del gambesecco - se manca, non raccogliere.','{"Lepiota cristata è tossica (disturbi gastro-intestinali; nel genere ogni piccola lepiota è considerata sospetta di amatossine); il gambesecco è commestibile","Lepiota cristata odora sgradevolmente acre di gas illuminante/gomma bruciata; il gambesecco odora gradevolmente di mandorla amara/acido cianidrico fino a dolciastro","Lepiota cristata ha un anello (fugace) e un gambo fragile; il gambesecco NON ha anello e ha un gambo tenace, flessibile","Lepiota cristata: cappello biancastro con squame bruno-rosse disposte concentricamente e piccolo disco scuro al centro; gambesecco: cappello con umbone liscio ocra fino a color pane senza squame","Lepiota cristata con lamelle fitte, libere, bianche; gambesecco con lamelle spesse, distanziate, smarginato-adnate"}','f'),
('marasmius_oreades','lepiota_helveola','en','Fairy ring mushroom smooth ochre umbonate cap, ringless tough stem, thick widely spaced gills; Lepiota helveola finely scaly flesh-pinkish cap with a stem ring and crowded free gills.','The fairy ring mushroom smells pleasantly of hydrocyanic acid/bitter almond to sweetish (HCN + benzaldehyde, not perceptible to about a quarter of people); small poisonous dapperlings smell inconspicuous to slightly unpleasant - smell is NOT a sure separating feature.','Both on meadows, lawns, pastures and in parks - identical habitat, which is exactly what makes the confusion so dangerous.','Fairy ring mushroom white spore print, Lepiota helveola likewise white - no separating feature; watch for the ring, free gills and brittle stem.','NEVER eat small dapperlings (Lepiota) with a cap under about 8 cm - several species are deadly. In meadows do not collect any small, ringed, brittle mushroom; when in doubt leave it entirely standing.','{"Lepiota helveola is DEADLY poisonous (amatoxins -> liver failure); the fairy ring mushroom is a good edible - the confusion can end fatally","The fairy ring mushroom has a strikingly tough, pliable-elastic, solid stem (twists without breaking); small poisonous dapperlings have a fragile, easily breaking stem","Lepiota helveola has an (often fleeting) membranous ring on the stem; the fairy ring mushroom NEVER has a ring","The fairy ring mushroom has thick, widely spaced, emarginate-adnate, cream-coloured gills; Lepiota helveola crowded, free, white gills","Lepiota helveola: finely scaly flesh-pink to brownish-red cap with a darker centre; fairy ring mushroom: smooth ochre- to buff-coloured cap with a blunt umbo"}','f'),
('marasmius_oreades','lepiota_helveola','es','Senderuela: sombrero liso ocre con mamelón, pie correoso sin anillo, láminas gruesas espaciadas; Lepiota helveola: sombrero finamente escamoso pardo-rosado carne con anillo en el pie y láminas libres apretadas.','La senderuela huele agradablemente a ácido cianhídrico/almendra amarga hasta dulzón (HCN + benzaldehído, no perceptible para alrededor de un cuarto de las personas); las pequeñas lepiotas tóxicas huelen discreto hasta ligeramente desagradable - el olor NO es un rasgo de separación seguro.','Ambos en prados, céspedes, pastos y parques - hábitat idéntico, justamente esto hace la confusión tan peligrosa.','Senderuela esporada blanca, Lepiota helveola también blanca - ningún rasgo de separación; vigilar el anillo, las láminas libres y el pie quebradizo.','NUNCA comer lepiotas pequeñas (Lepiota) con sombrero de menos de unos 8 cm - varias especies son mortales. En el prado no recolectar ninguna seta pequeña, con anillo y quebradiza; en caso de duda dejarla completamente en su sitio.','{"Lepiota helveola es MORTALMENTE tóxica (amatoxinas -> insuficiencia hepática); la senderuela es un buen comestible - la confusión puede acabar de forma mortal","La senderuela tiene un pie llamativamente correoso, flexible-elástico, lleno (se retuerce sin romperse); las pequeñas lepiotas tóxicas tienen un pie frágil, que se rompe fácilmente","Lepiota helveola posee un anillo membranoso (a menudo fugaz) en el pie; la senderuela NUNCA tiene anillo","La senderuela tiene láminas gruesas, espaciadas, escotado-adnadas al pie, de color crema; Lepiota helveola láminas apretadas, libres, blancas","Lepiota helveola: sombrero finamente escamoso pardo-rosado carne hasta pardo-rojizo con centro más oscuro; senderuela: sombrero liso ocre hasta color pan con mamelón obtuso"}','f'),
('marasmius_oreades','lepiota_helveola','fr','Marasme des Oréades : chapeau lisse ocre à mamelon, pied coriace sans anneau, lames épaisses espacées ; Lepiota helveola : chapeau finement squameux brun-rosé chair avec anneau au pied et lames libres serrées.','Le marasme des Oréades sent agréablement l''acide cyanhydrique/amande amère à douceâtre (HCN + benzaldéhyde, non perçu par environ un quart des gens) ; les petites lépiotes toxiques ont une odeur discrète à légèrement désagréable - l''odeur n''est PAS un critère de séparation sûr.','Tous deux dans les prairies, pelouses, pâturages et parcs - habitat identique, c''est précisément ce qui rend la confusion si dangereuse.','Marasme des Oréades sporée blanche, Lepiota helveola également blanche - pas de critère de séparation ; surveiller l''anneau, les lames libres et le pied cassant.','Ne JAMAIS manger les petites lépiotes (Lepiota) à chapeau de moins de 8 cm environ - plusieurs espèces sont mortelles. En prairie, ne ramasser aucun petit champignon annelé et cassant ; au moindre doute, laisser entièrement sur place.','{"Lepiota helveola est MORTELLEMENT toxique (amatoxines -> insuffisance hépatique) ; le marasme des Oréades est un bon comestible - la confusion peut être mortelle","Le marasme des Oréades a un pied remarquablement coriace, souple-élastique, plein (se tord sans casser) ; les petites lépiotes toxiques ont un pied fragile, cassant facilement","Lepiota helveola possède un anneau membraneux (souvent fugace) au pied ; le marasme des Oréades n''a JAMAIS d''anneau","Le marasme des Oréades a des lames épaisses, espacées, échancrées-adnées au pied, couleur crème ; Lepiota helveola des lames serrées, libres, blanches","Lepiota helveola : chapeau finement squameux brun-rosé chair à brun-rougeâtre avec centre plus foncé ; marasme des Oréades : chapeau lisse ocre à couleur pain avec mamelon obtus"}','f'),
('marasmius_oreades','lepiota_helveola','it','Gambesecco: cappello liscio ocra con umbone, gambo tenace senza anello, lamelle spesse distanziate; Lepiota helveola: cappello finemente squamoso bruno-rosato carne con anello al gambo e lamelle libere fitte.','Il gambesecco profuma gradevolmente di acido cianidrico/mandorla amara fino a dolciastro (HCN + benzaldeide, non percepito da circa un quarto delle persone); le piccole lepiote tossiche hanno odore insignificante fino a leggermente sgradevole - l''odore NON è un criterio di separazione sicuro.','Entrambi in prati, tappeti erbosi, pascoli e parchi - habitat identico, proprio questo rende la confusione così pericolosa.','Gambesecco sporata bianca, Lepiota helveola anch''essa bianca - nessun criterio di separazione; fare attenzione all''anello, alle lamelle libere e al gambo fragile.','Non mangiare MAI le piccole lepiote (Lepiota) con cappello sotto i circa 8 cm - diverse specie sono mortali. In prato non raccogliere alcun fungo piccolo, anellato e fragile; nel dubbio lasciare completamente sul posto.','{"Lepiota helveola è MORTALMENTE tossica (amatossine -> insufficienza epatica); il gambesecco è un buon commestibile - la confusione può finire in modo mortale","Il gambesecco ha un gambo notevolmente tenace, flessibile-elastico, pieno (si torce senza spezzarsi); le piccole lepiote tossiche hanno un gambo fragile, che si spezza facilmente","Lepiota helveola possiede un anello membranoso (spesso fugace) al gambo; il gambesecco non ha MAI un anello","Il gambesecco ha lamelle spesse, distanziate, smarginato-adnate al gambo, color crema; Lepiota helveola lamelle fitte, libere, bianche","Lepiota helveola: cappello finemente squamoso bruno-rosato carne fino a bruno-rossastro con centro più scuro; gambesecco: cappello liscio ocra fino a color pane con umbone ottuso"}','f'),
('marasmius_oreades','panaeolina_foenisecii','en','The fairy ring mushroom has distant, white, free gills and a leather-yellow umbonate cap; the mower''s mushroom (Panaeolina foenisecii) shows crowded, mottled-spotted, dark-brown gills.','Fairy ring mushroom: often a characteristic bitter-almond/marzipan or spicy smell (not always clearly pronounced). Panaeolina foenisecii: nearly odourless.','Both grow in meadows and lawns; Panaeolina foenisecii prefers fertilised, freshly mown lawns, the fairy ring mushroom often in fairy rings on poorer grassland — the habitat does NOT separate them reliably.','Fairy ring mushroom: white spore print. Panaeolina foenisecii: dark purple-/blackish-brown spore print — the safest distinguishing feature.','Always let small brown-capped mushrooms growing in the lawn drop spores — white spore print = possible fairy ring mushroom, dark brown = mottlegill, then never eat. Never take the smell alone as proof.','{"Fairy ring mushroom: tough, flexible stem that can be twisted without breaking; Panaeolina foenisecii has a brittle, hollow stem.","Fairy ring mushroom: whitish-cream gills, free, broad/distant; Panaeolina foenisecii has spotted grey-brown, speckled (mottled) gills due to uneven spore ripening.","Fairy ring mushroom: pale leather-yellow to buff cap with umbo, hygrophanous; Panaeolina foenisecii smaller, darker grey-brown, without a clear umbo.","Spore print fairy ring mushroom white, Panaeolina foenisecii dark purple-brown to blackish — the decisive safe separation step.","The fairy ring mushroom often smells of bitter almond/hydrocyanic acid or spicy; Panaeolina foenisecii is nearly odourless."}','f'),
('marasmius_oreades','panaeolina_foenisecii','es','La senderuela tiene láminas separadas, blancas, libres y un sombrero amarillo cuero con mamelón; el panaeolina de los henos (Panaeolina foenisecii) presenta láminas apretadas, jaspeadas-moteadas, pardo oscuro.','Senderuela: a menudo un olor característico a almendra amarga/mazapán o especiado (no siempre claramente marcado). Panaeolina foenisecii: casi inodoro.','Ambos crecen en prados y céspedes; Panaeolina foenisecii prefiere los céspedes abonados y recién segados, la senderuela a menudo en corros de brujas sobre praderas más pobres — el hábitat NO los separa de forma fiable.','Senderuela: esporada blanca. Panaeolina foenisecii: esporada pardo-purpúrea/negruzca oscura — el rasgo distintivo más seguro.','Dejar siempre esporular los pequeños hongos de sombrero pardo que crecen en el césped — esporada blanca = posible senderuela, pardo oscuro = panaeolina, entonces nunca comer. Nunca tomar el olor solo como prueba.','{"Senderuela: pie tenaz y flexible que se deja retorcer sin romperse; Panaeolina foenisecii tiene un pie frágil y hueco.","Senderuela: láminas blanquecinas-crema, libres, anchas/separadas; Panaeolina foenisecii tiene láminas gris-parduzcas manchadas, moteadas (jaspeadas) por la maduración desigual de las esporas.","Senderuela: sombrero amarillo cuero-color pan claro con mamelón, higrófano; Panaeolina foenisecii más pequeño, más oscuro gris-pardo, sin mamelón claro.","Esporada de la senderuela blanca, Panaeolina foenisecii pardo-púrpura oscuro-negruzca — el paso distintivo decisivo y seguro.","La senderuela huele a menudo a almendra amarga/ácido cianhídrico o especiado; Panaeolina foenisecii es casi inodoro."}','f'),
('marasmius_oreades','panaeolina_foenisecii','fr','Le marasme des Oréades a des lames espacées, blanches, libres et un chapeau jaune cuir mamelonné ; le panéole des foins (Panaeolina foenisecii) présente des lames serrées, marbrées-tachetées, brun foncé.','Marasme des Oréades : souvent une odeur caractéristique d''amande amère/de massepain ou épicée (pas toujours nettement marquée). Panaeolina foenisecii : presque inodore.','Les deux poussent dans les prés et pelouses ; Panaeolina foenisecii préfère les pelouses fertilisées fraîchement tondues, le marasme des Oréades souvent en ronds de sorcière sur des prairies plus maigres — l''habitat ne les sépare PAS de façon fiable.','Marasme des Oréades : sporée blanche. Panaeolina foenisecii : sporée brun pourpre/noirâtre foncé — le critère de distinction le plus sûr.','Toujours laisser sporuler les petits champignons à chapeau brun poussant dans la pelouse — sporée blanche = marasme des Oréades possible, brun foncé = panéole, alors ne jamais manger. Ne jamais prendre l''odeur seule comme preuve.','{"Marasme des Oréades : pied tenace et flexible qui se laisse tordre sans casser ; Panaeolina foenisecii a un pied fragile et creux.","Marasme des Oréades : lames blanchâtres-crème, libres, larges/espacées ; Panaeolina foenisecii a des lames gris-brun tachetées, mouchetées (marbrées) du fait d''une maturation inégale des spores.","Marasme des Oréades : chapeau jaune cuir-couleur pain clair avec mamelon, hygrophane ; Panaeolina foenisecii plus petit, plus foncé gris-brun, sans mamelon net.","Sporée du marasme des Oréades blanche, Panaeolina foenisecii brun pourpre foncé-noirâtre — l''étape de séparation décisive et sûre.","Le marasme des Oréades sent souvent l''amande amère/l''acide cyanhydrique ou est épicé ; Panaeolina foenisecii est presque inodore."}','f'),
('marasmius_oreades','panaeolina_foenisecii','it','Il gambosecco ha lamelle distanziate, bianche, libere e un cappello giallo-cuoio umbonato; il panaeolina dei fienili (Panaeolina foenisecii) presenta lamelle fitte, marmorizzate-macchiate, bruno scuro.','Gambosecco: spesso un odore caratteristico di mandorla amara/marzapane o speziato (non sempre nettamente marcato). Panaeolina foenisecii: quasi inodore.','Entrambi crescono nei prati e tappeti erbosi; Panaeolina foenisecii predilige i tappeti erbosi concimati e appena falciati, il gambosecco spesso in cerchi delle streghe su prati più magri — l''habitat NON li separa in modo affidabile.','Gambosecco: sporata bianca. Panaeolina foenisecii: sporata bruno-purpurea/nerastra scura — il criterio distintivo più sicuro.','Lasciare sempre sporulare i piccoli funghi a cappello bruno che crescono nel tappeto erboso — sporata bianca = possibile gambosecco, bruno scuro = panaeolina, allora non mangiare mai. Non prendere mai l''odore da solo come prova.','{"Gambosecco: gambo tenace e flessibile che si lascia attorcigliare senza spezzarsi; Panaeolina foenisecii ha un gambo fragile e cavo.","Gambosecco: lamelle biancastre-crema, libere, larghe/distanziate; Panaeolina foenisecii ha lamelle grigio-brune macchiate, screziate (marmorizzate) per la maturazione disuguale delle spore.","Gambosecco: cappello giallo-cuoio-color pane chiaro con umbone, igrofano; Panaeolina foenisecii più piccolo, più scuro grigio-bruno, senza umbone netto.","Sporata del gambosecco bianca, Panaeolina foenisecii bruno-purpurea scura-nerastra — il passo distintivo decisivo e sicuro.","Il gambosecco odora spesso di mandorla amara/acido cianidrico o è speziato; Panaeolina foenisecii è quasi inodore."}','f'),
('marasmius_oreades','panaeolus_cinctulus','en','Panaeolus cinctulus shows mottled gills turning grey to black and a moist red-brown, often banded cap margin; the fairy ring mushroom stays uniformly leather-yellow with white gills.','Fairy ring mushroom often of bitter almond/spicy; Panaeolus cinctulus inconspicuous, plain mushroomy smell.','Panaeolus cinctulus grows on dung, compost and fertilised lawns, the fairy ring mushroom in fairy rings on meadows/lawns — overlap on fertilised lawn areas.','Fairy ring mushroom white, Panaeolus cinctulus deep black.','Never collect small lawn/dung mushrooms with grey gills turning black — a black spore print reliably rules out the edible fairy ring mushroom.','{"Fairy ring mushroom: tough, elastic stem; Panaeolus cinctulus has a thinner, more brittle, hollow stem.","Fairy ring mushroom: white, broad and free gills; Panaeolus cinctulus has mottled gills turning cream to grey and finally black.","The fairy ring mushroom''s cap is leather-yellow with umbo, hygrophanous; Panaeolus cinctulus darker red-brown (moist) with an often darker, banded cap margin, lightening to cream-white on drying.","Spore print fairy ring mushroom white, Panaeolus cinctulus deep black — unambiguous separation.","Panaeolus cinctulus grows preferentially on dung, compost and heavily fertilised lawns; contains psilocybin (bluing pressure marks possible)."}','f'),
('marasmius_oreades','panaeolus_cinctulus','es','Panaeolus cinctulus presenta láminas abigarradas que se vuelven grises a negras y un margen del sombrero pardo-rojo húmedo, a menudo zonado; la senderuela permanece uniformemente amarillo cuero con láminas blancas.','Senderuela a menudo a almendra amarga/especiado; Panaeolus cinctulus discreto, olor fúngico banal.','Panaeolus cinctulus crece sobre estiércol, compost y céspedes abonados, la senderuela en corros de brujas sobre prados/céspedes — solapamiento en las superficies de césped abonadas.','Senderuela blanca, Panaeolus cinctulus negro profundo.','Nunca recolectar pequeños hongos de césped/de estiércol con láminas grises que se vuelven negras — una esporada negra excluye con seguridad la senderuela comestible.','{"Senderuela: pie tenaz, elástico; Panaeolus cinctulus tiene un pie más delgado, más frágil, hueco.","Senderuela: láminas blancas, anchas y libres; Panaeolus cinctulus tiene láminas abigarradas que se vuelven de crema a grises y finalmente negras.","El sombrero de la senderuela es amarillo cuero con mamelón, higrófano; Panaeolus cinctulus más oscuro pardo-rojo (húmedo) con un margen del sombrero a menudo más oscuro y zonado, que se aclara a blanco-crema al secarse.","Esporada de la senderuela blanca, Panaeolus cinctulus negro profundo — separación inequívoca.","Panaeolus cinctulus crece preferentemente sobre estiércol, compost y céspedes fuertemente abonados; contiene psilocibina (posibles manchas de presión que viran al azul)."}','f'),
('marasmius_oreades','panaeolus_cinctulus','fr','Panaeolus cinctulus présente des lames bigarrées devenant grises à noires et un bord du chapeau brun rouge humide, souvent zoné ; le marasme des Oréades reste uniformément jaune cuir avec des lames blanches.','Marasme des Oréades souvent à l''amande amère/épicé ; Panaeolus cinctulus discret, odeur fongique banale.','Panaeolus cinctulus pousse sur le fumier, le compost et les pelouses fertilisées, le marasme des Oréades en ronds de sorcière sur prés/pelouses — chevauchement sur les surfaces de pelouse fertilisées.','Marasme des Oréades blanc, Panaeolus cinctulus noir profond.','Ne jamais récolter les petits champignons de pelouse/de fumier à lames grises devenant noires — une sporée noire exclut de façon sûre le marasme des Oréades comestible.','{"Marasme des Oréades : pied tenace, élastique ; Panaeolus cinctulus a un pied plus mince, plus fragile, creux.","Marasme des Oréades : lames blanches, larges et libres ; Panaeolus cinctulus a des lames bigarrées devenant crème à grises puis finalement noires.","Le chapeau du marasme des Oréades est jaune cuir avec mamelon, hygrophane ; Panaeolus cinctulus plus foncé brun rouge (humide) avec un bord du chapeau souvent plus foncé et zoné, s''éclaircissant en blanc crème en séchant.","Sporée du marasme des Oréades blanche, Panaeolus cinctulus noir profond — séparation sans équivoque.","Panaeolus cinctulus pousse de préférence sur le fumier, le compost et les pelouses fortement fertilisées ; contient de la psilocybine (taches de pression bleuissantes possibles)."}','f'),
('marasmius_oreades','panaeolus_cinctulus','it','Panaeolus cinctulus presenta lamelle screziate che diventano grigie fino a nere e un margine del cappello bruno-rosso umido, spesso zonato; il gambosecco resta uniformemente giallo-cuoio con lamelle bianche.','Gambosecco spesso di mandorla amara/speziato; Panaeolus cinctulus poco appariscente, odore fungino banale.','Panaeolus cinctulus cresce su letame, compost e tappeti erbosi concimati, il gambosecco in cerchi delle streghe su prati/tappeti erbosi — sovrapposizione sulle superfici erbose concimate.','Gambosecco bianco, Panaeolus cinctulus nero profondo.','Non raccogliere mai i piccoli funghi di prato/di letame con lamelle grigie che diventano nere — una sporata nera esclude con sicurezza il gambosecco commestibile.','{"Gambosecco: gambo tenace, elastico; Panaeolus cinctulus ha un gambo più sottile, più fragile, cavo.","Gambosecco: lamelle bianche, larghe e libere; Panaeolus cinctulus ha lamelle screziate che diventano da crema a grigie e infine nere.","Il cappello del gambosecco è giallo-cuoio con umbone, igrofano; Panaeolus cinctulus più scuro bruno-rosso (umido) con un margine del cappello spesso più scuro e zonato, che schiarisce a bianco-crema asciugandosi.","Sporata del gambosecco bianca, Panaeolus cinctulus nero profondo — separazione inequivocabile.","Panaeolus cinctulus cresce preferibilmente su letame, compost e tappeti erbosi fortemente concimati; contiene psilocibina (possibili macchie da pressione che virano al blu)."}','f'),
('marone','flockenstieliger_hexenpilz','en','Bay bolete (Marone): brown, light blueing. Witch''s bolete (Hexenpilz): brown, rapid strong blueing, red dots.',NULL,'Both in forest.',NULL,'Both edible. The witch''s bolete MUST be cooked for 15+ min.','{"Both are edible mushrooms; the witch''s bolete blues FASTER","Witch''s bolete has little red dots on the stem"}','t'),
('marone','flockenstieliger_hexenpilz','es','Marone (boleto bayo): marrón, azulea ligeramente. Hexenpilz de pie punteado (Neoboletus, pie con finos puntitos/escamillas rojas, NO reticulado): marrón, azulea rápida e intensamente, con puntos rojos.',NULL,'Ambos en el bosque',NULL,'Ambos comestibles. El Hexenpilz DEBE cocinarse 15+ min.','{"Ambos comestibles; el Hexenpilz azulea MÁS RÁPIDO","El Hexenpilz tiene puntitos rojos en el pie"}','t'),
('marone','flockenstieliger_hexenpilz','fr','Bolet bai : brun, léger bleuissement. Bolet à pied rouge (bolet Satan flocculeux / bolet à beau pied) : brun, bleuissement fort et rapide, points rouges.',NULL,'Tous deux en forêt',NULL,'Tous deux comestibles. Le bolet à pied rouge DOIT être cuit 15+ min.','{"Tous deux comestibles, le bolet à pied rouge bleuit PLUS VITE","Le bolet à pied rouge a de petits points rouges sur le pied"}','t'),
('marone','flockenstieliger_hexenpilz','it','Marone (Imleria badia): bruno, viraggio leggero al blu. Boleto dal gambo fioccoso (Neoboletus): bruno, viraggio rapido e intenso al blu, punti rossi.',NULL,'Entrambi nel bosco',NULL,'Entrambi commestibili. Il boleto dal gambo fioccoso DEVE essere cotto 15+ min.','{"Entrambi funghi commestibili, il boleto dal gambo fioccoso vira al blu PIÙ RAPIDAMENTE","Il boleto dal gambo fioccoso ha puntini rossi sul gambo"}','t'),
('marone','tricholoma_ustale','en','The bay bolete (marone) has tubes/spongy flesh under the cap, the burnt knight (Tricholoma ustale) has gills — the underside of the cap clears up the confusion immediately.','Bay bolete mild-mushroomy, ustale faintly mealy — not a primary distinguishing feature.','Bay bolete under spruce/pine on acidic soil, ustale mainly in deciduous forest (beech/oak).','Bay bolete olive-brown spore print (bolete), ustale white spore print (gilled mushroom) — clearly different.','Always check the underside of the cap: tubes = bolete, gills = gilled mushroom. A gilled mushroom with a brown slimy cap is never a bay bolete.','{"Decisive: the bay bolete (edible) has TUBES/pores under the cap, the burnt knight has GILLS — immediately distinguishable by looking at the underside of the cap.","The bay bolete is a bolete (Boletales) with a thick stem and yellowish tubes that bruise blue under pressure; ustale is a gilled mushroom.","The resemblance exists only from a distance via the brown cap, slimy when moist — so the ustale cap can resemble a bay bolete from above.","Bay bolete flesh tastes mild-nutty, ustale bitterish.","In the bay bolete the tubes can be peeled off as a layer — impossible in knights (true gills)."}','f'),
('marone','tricholoma_ustale','es','El boleto bayo (marone) tiene tubos/carne esponjosa bajo el sombrero, el tricoloma quemado (Tricholoma ustale) láminas — la cara inferior del sombrero aclara la confusión inmediatamente.','Boleto bayo suave-fúngico, ustale débilmente harinoso — no es un criterio distintivo primario.','Boleto bayo bajo abeto rojo/pino en suelo ácido, ustale sobre todo en bosque de frondosas (haya/roble).','Boleto bayo esporada pardo-olivácea (boleto), ustale esporada blanca (hongo laminado) — claramente diferentes.','Comprobar siempre la cara inferior del sombrero: tubos = boleto, láminas = hongo laminado. Un hongo laminado con sombrero pardo viscoso nunca es un boleto bayo.','{"Decisivo: el boleto bayo (comestible) tiene TUBOS/poros bajo el sombrero, el tricoloma quemado tiene LÁMINAS — inmediatamente distinguibles mirando la cara inferior del sombrero.","El boleto bayo es un boleto (Boletales) con pie grueso y tubos amarillentos que viran al azul a la presión; ustale es un hongo laminado.","El parecido existe solo de lejos a través del sombrero pardo, viscoso con la humedad — así el sombrero de ustale puede recordar desde arriba a un boleto bayo.","La carne del boleto bayo sabe suave-a nuez, ustale amarguita.","En el boleto bayo los tubos se dejan separar como una capa — imposible en los tricolomas (láminas verdaderas)."}','f'),
('marone','tricholoma_ustale','fr','Le bolet bai (marone) a des tubes/une chair spongieuse sous le chapeau, le tricholome brûlé (Tricholoma ustale) des lames — la face inférieure du chapeau lève la confusion immédiatement.','Bolet bai doux-fongique, ustale faiblement farineux — pas de critère distinctif primaire.','Bolet bai sous épicéa/pin sur sol acide, ustale surtout en forêt de feuillus (hêtre/chêne).','Bolet bai sporée brun olive (bolet), ustale sporée blanche (champignon à lames) — nettement différentes.','Toujours vérifier la face inférieure du chapeau : tubes = bolet, lames = champignon à lames. Un champignon à lames à chapeau brun visqueux n''est jamais un bolet bai.','{"Décisif : le bolet bai (comestible) a des TUBES/pores sous le chapeau, le tricholome brûlé a des LAMES — immédiatement distinguables en regardant la face inférieure du chapeau.","Le bolet bai est un bolet (Boletales) à pied épais et à tubes jaunâtres bleuissant à la pression ; ustale est un champignon à lames.","La ressemblance n''existe que de loin via le chapeau brun, visqueux par temps humide — ainsi le chapeau d''ustale peut rappeler de dessus un bolet bai.","La chair du bolet bai a un goût doux-noisette, ustale amère.","Chez le bolet bai, les tubes se laissent retirer en couche — impossible chez les tricholomes (vraies lames)."}','f'),
('marone','tricholoma_ustale','it','Il boleto baio (marone) ha tubuli/carne spugnosa sotto il cappello, il tricoloma bruciato (Tricholoma ustale) lamelle — la faccia inferiore del cappello risolve la confusione immediatamente.','Boleto baio mite-fungino, ustale debolmente farinoso — nessun criterio distintivo primario.','Boleto baio sotto abete rosso/pino su suolo acido, ustale soprattutto nel bosco di latifoglie (faggio/quercia).','Boleto baio sporata bruno-olivacea (boleto), ustale sporata bianca (fungo a lamelle) — nettamente diverse.','Controllare sempre la faccia inferiore del cappello: tubuli = boleto, lamelle = fungo a lamelle. Un fungo a lamelle con cappello bruno viscido non è mai un boleto baio.','{"Decisivo: il boleto baio (commestibile) ha TUBULI/pori sotto il cappello, il tricoloma bruciato ha LAMELLE — immediatamente distinguibili guardando la faccia inferiore del cappello.","Il boleto baio è un boleto (Boletales) con gambo spesso e tubuli giallastri che virano al blu alla pressione; ustale è un fungo a lamelle.","La somiglianza esiste solo da lontano tramite il cappello bruno, viscido con l''umidità — così il cappello di ustale può ricordare dall''alto un boleto baio.","La carne del boleto baio ha sapore mite-nocciola, ustale amarognola.","Nel boleto baio i tubuli si lasciano staccare come strato — impossibile nei tricolomi (vere lamelle)."}','f'),
('mitrophora_semilibera','gyromitra_gigas','en','The half-free morel shows a small bell-shaped, pitted cap with a free, projecting margin on a long slender stem; the snow morel (Gyromitra gigas) a large, bulging brain-like cap on a short thick stem.','No reliable distinguishing smell feature.','Both are spring mushrooms; the half-free morel on calcareous soils/floodplain forest, the snow morel as a wood saprobiont on rotting stumps — the habitat does not separate reliably.','Both with a pale spore print (ascomycetes) — no distinguishing feature.','Watch for pits (morel) vs. brain-like convolutions (false morel) and always cut lengthwise. Only collect a spring ''morel'' if it is clearly pitted and has a continuous hollow inside; leave convoluted false morels behind.','{"Half-free morel: small bell-shaped to conical, distinctly pitted cap, attached to the long, hollow, whitish stem only to about its lower half (cap margin free, projecting)","Snow morel: massive, brain-like convoluted cap without pits, short thick stem, internally traversed by several hollow chambers","Half-free morel completely hollow in cap and stem; false morel stem chambered/traversed by hollows","IMPORTANT: the half-free morel is edible only when well cooked (indigestible raw). The snow morel itself contains hardly any gyromitrin, but is barely separable from the deadly spring false morel (Gyromitra esculenta) — therefore avoid every brain-like find"}','f'),
('mitrophora_semilibera','gyromitra_gigas','es','La colmenilla semilibre muestra un pequeño sombrero campanulado alveolado con margen libre saliente sobre un pie largo y esbelto; la giromitra gigante un gran sombrero cerebriforme abultado sobre un pie corto y grueso.','Ningún criterio olfativo distintivo fiable.','Ambos son hongos primaverales; la colmenilla semilibre sobre suelos calcáreos/bosque de ribera, la giromitra gigante como saprobionte de la madera sobre tocones podridos — el hábitat no separa con seguridad.','Ambos con esporada clara (ascomicetos) — ningún criterio distintivo.','Prestar atención a los alvéolos (colmenilla) vs. circunvoluciones cerebriformes (giromitra) y cortar siempre a lo largo. Recolectar una «colmenilla» primaveral solo si está claramente alveolada y por dentro presenta una cavidad continua; dejar sobre el terreno las giromitras circunvolucionadas.','{"Colmenilla semilibre: pequeño sombrero campanulado-cónico, claramente alveolado, que está soldado solo hasta aproximadamente su mitad inferior al pie largo, hueco y blanquecino (margen del sombrero libre, saliente)","Giromitra gigante: sombrero macizo, de circunvoluciones cerebriformes sin alvéolos, pie corto y grueso, recorrido internamente por varias cavidades","Colmenilla semilibre completamente hueca en el sombrero y el pie; pie de la giromitra tabicado/recorrido por cavidades","IMPORTANTE: la colmenilla semilibre solo es comestible bien cocida (indigesta cruda). La giromitra gigante misma contiene apenas giromitrina, pero es difícilmente separable de la giromitra primaveral mortal (Gyromitra esculenta) — por eso evitar todo hallazgo cerebriforme"}','f'),
('mitrophora_semilibera','gyromitra_gigas','fr','La morille demi-libre montre un petit chapeau en cloche alvéolé à bord libre écarté sur un long pied élancé ; le gyromitre géant un grand chapeau en cerveau bosselé sur un pied court et épais.','Pas de critère olfactif fiable de séparation.','Les deux champignons de printemps ; morille demi-libre sur sols riches en calcaire/forêt alluviale, gyromitre géant comme saprobionte lignicole sur souches pourries – l''habitat ne sépare pas sûrement.','Les deux à sporée claire (ascomycètes) – pas un critère de séparation.','Faire attention aux alvéoles (morille) vs. circonvolutions en forme de cerveau (gyromitre) et toujours couper en long. Ne récolter une « morille » de printemps que si elle est nettement alvéolée et qu''elle présente à l''intérieur une cavité continue ; laisser sur place les gyromitres circonvolués.','{"Morille demi-libre : petit chapeau conique-en cloche, nettement alvéolé, qui n''est attaché au long pied creux blanchâtre qu''environ à sa moitié inférieure (bord du chapeau libre, écarté)","Gyromitre géant : chapeau massif, circonvolué en forme de cerveau sans alvéoles, pied court et épais, traversé à l''intérieur de plusieurs cavités","Morille demi-libre creuse de manière continue dans le chapeau et le pied ; pied du gyromitre cloisonné/traversé de cavités","IMPORTANT : morille demi-libre comestible seulement bien cuite (crue mal tolérée). Le gyromitre géant lui-même contient peu de gyromitrine, mais est à peine séparable du gyromitre comestible printanier mortel – c''est pourquoi éviter toute trouvaille en forme de cerveau"}','f'),
('mitrophora_semilibera','gyromitra_gigas','it','La spugnola semilibera mostra un piccolo cappello campanulato alveolato con margine libero distaccato su un gambo lungo e slanciato; la gyromitra gigante un grande cappello cerebriforme rigonfio su un gambo corto e grosso.','Nessun criterio olfattivo distintivo affidabile.','Entrambi sono funghi primaverili; la spugnola semilibera su suoli calcarei/bosco ripariale, la gyromitra gigante come saprobionte del legno su ceppi marcescenti — l''habitat non separa con sicurezza.','Entrambi con sporata chiara (ascomiceti) — nessun criterio distintivo.','Fare attenzione agli alveoli (spugnola) vs. circonvoluzioni cerebriformi (gyromitra) e tagliare sempre per il lungo. Raccogliere una «spugnola» primaverile solo se è chiaramente alveolata e all''interno presenta una cavità continua; lasciare sul posto le gyromitre circonvolute.','{"Spugnola semilibera: piccolo cappello campanulato-conico, nettamente alveolato, che è saldato solo fino a circa la metà inferiore al gambo lungo, cavo e biancastro (margine del cappello libero, distaccato)","Gyromitra gigante: cappello massiccio, a circonvoluzioni cerebriformi senza alveoli, gambo corto e grosso, percorso internamente da più cavità","Spugnola semilibera completamente cava nel cappello e nel gambo; gambo della gyromitra concamerato/percorso da cavità","IMPORTANTE: la spugnola semilibera è commestibile solo ben cotta (indigesta cruda). La gyromitra gigante stessa contiene scarsa gyromitrina, ma è a malapena separabile dalla gyromitra primaverile mortale (Gyromitra esculenta) — perciò evitare ogni ritrovamento cerebriforme"}','f'),
('mitrophora_semilibera','helvella_crispa','en','The half-free morel has a honeycomb-pitted bell-shaped cap ; the white saddle (Helvella crispa) a pitless, saddle-folded lobed cap on a ribbed-chambered stem.','Both inconspicuously mushroomy – no reliable distinguishing feature.','Half-free morel in spring (floodplain forest/calcareous) ; white saddle mainly summer–autumn in deciduous/mixed forest along path and forest edges – season helps to separate.','Both ascomycetes with pale, cream-white spore print – not a distinguishing feature.','Honeycombed = morel candidate ; saddle-/lobe-shaped without pits = false morel (Helvella) = leave it. Do not treat Helvella species as an edible mushroom.','{"Half-free morel : honeycombed bell-conical cap (true chambers), cap and long stem entirely hollow, pale whitish-ochre","White saddle : multi-lobed saddle-folded/lobed cap WITHOUT pits, whitish-cream, stem deeply longitudinally furrowed/ribbed and chambered (not one smooth hollow)","The white saddle contains gyromitrin → toxic raw ; do not treat it as a harmless edible mushroom","Appearance time : half-free morel in spring, white saddle mainly summer–late autumn (July–November)"}','f'),
('mitrophora_semilibera','helvella_crispa','es','La colmenilla semilibre tiene un sombrero acampanado alveolado-hundido ; la helvella crespa un sombrero con lóbulos plegados en silla de montar, sin alvéolos, sobre un pie acostillado-tabicado.','Ambas inodoras-fúngicas – ningún criterio de distinción fiable.','Colmenilla semilibre en primavera (bosque de ribera/calcáreo) ; helvella crespa sobre todo en verano–otoño en bosque caducifolio/mixto en bordes de caminos y linderos – la estación ayuda a separar.','Ambos ascomicetos con esporada clara, blanco-crema – no es un criterio de distinción.','Alveolado = candidato colmenilla ; en forma de silla/con lóbulos sin alvéolos = helvella = dejar en el sitio. No tratar las helvellas como seta comestible.','{"Colmenilla semilibre : sombrero campanulado-cónico alveolado (verdaderas cámaras), sombrero y largo pie completamente huecos, blanquecino-ocre pálido","Helvella crespa : sombrero multilobulado enrollado en silla/con lóbulos SIN alvéolos, blanquecino-crema, pie profundamente surcado/acostillado a lo largo y tabicado (no una cavidad lisa)","La helvella crespa contiene gyromitrina → tóxica cruda ; no tratarla como una seta comestible inofensiva","Período de aparición : colmenilla semilibre en primavera, helvella crespa sobre todo verano–otoño tardío (julio–noviembre)"}','f'),
('mitrophora_semilibera','helvella_crispa','fr','La morille demi-libre a un chapeau en cloche alvéolé-creusé ; l''helvelle crépue un chapeau en lobes plié en selle, sans alvéoles, sur un pied côtelé-cannelé.','Les deux fongiques discrets – pas un critère de séparation fiable.','Morille demi-libre au printemps (forêt alluviale/calcaire) ; helvelle crépue surtout été–automne en forêt de feuillus/mixte aux bords de chemins et lisières – la saison aide à séparer.','Les deux ascomycètes à sporée claire, crème-blanchâtre – pas un critère de séparation.','Alvéolé = candidat morille ; en forme de selle/lobes sans alvéoles = helvelle = laisser sur place. Ne pas traiter les helvelles comme comestibles.','{"Morille demi-libre : chapeau en cloche-conique alvéolé (véritables loges), chapeau et long pied complètement creux, blanchâtre-ocre pâle","Helvelle crépue : chapeau circonvolué en selle/lobes, multilobé SANS alvéoles, blanchâtre-crème, pied profondément cannelé-côtelé et cloisonné (pas une cavité lisse)","L''helvelle crépue contient de la gyromitrine → crue toxique ; ne pas la traiter comme un comestible inoffensif","Période d''apparition : morille demi-libre au printemps, helvelle crépue surtout été–fin d''automne (juillet–novembre)"}','f'),
('mitrophora_semilibera','helvella_crispa','it','La spugnola semilibera ha un cappello a campana alveolato-scavato ; l''helvella crespa un cappello a lobi pieghettati a sella, senza alveoli, su un gambo costolato-camerato.','Entrambe inodore-fungine – nessun criterio di distinzione affidabile.','Spugnola semilibera in primavera (foresta golenale/calcarea) ; helvella crespa soprattutto in estate–autunno in bosco di latifoglie/misto ai bordi dei sentieri e ai margini – la stagione aiuta a separare.','Entrambi ascomiceti con sporata chiara, bianco-crema – non un criterio di distinzione.','Alveolato = candidato spugnola ; a forma di sella/a lobi senza alveoli = helvella = lasciare sul posto. Non trattare le helvelle come fungo commestibile.','{"Spugnola semilibera : cappello campanulato-conico alveolato (vere camere), cappello e lungo gambo completamente cavi, biancastro-ocra pallido","Helvella crespa : cappello plurilobato avvolto a sella/a lobi SENZA alveoli, biancastro-crema, gambo profondamente solcato/costolato per il lungo e camerato (non una cavità liscia)","L''helvella crespa contiene gyromitrina → tossica da cruda ; non trattarla come un fungo commestibile innocuo","Periodo di comparsa : spugnola semilibera in primavera, helvella crespa soprattutto estate–tardo autunno (luglio–novembre)"}','f'),
('morchelchampignon','gyromitra_gigas','en','The edible morel has a regularly pitted-honeycombed cap surface, the giant false morel an irregularly brain-/walnut-kernel-like convoluted, bulging-swollen surface without true pits.','Both rather inconspicuously mushroomy ; smell does NOT separate them reliably.','Edible morel in spring on calcareous soils ; giant false morel a spring wood saprobiont on rotten stumps, buried wood and bark mulch (often conifer). Appearance times overlap – habitat does not separate with certainty.','Both ascomycetes (asci) with pale, cream-coloured spore print – unsuitable for distinction.','Cut lengthwise : the true morel forms ONE continuous hollow from the tip to the stem base and is honeycombed. Leave anything brain-like convoluted with a chambered/cavity-riddled stem – not because this find is surely deadly, but because deadly false morel species cannot be reliably excluded. Never eat false morels raw. When in doubt : Tox Info Suisse 145.','{"Edible morel : cap honeycomb-pitted with true chambers ; cap AND stem form ONE continuous hollow from the stem base to the cap tip (longitudinal cut shows a shared hollow body)","Giant false morel : cap brain-like convoluted, bulging-folded (NO honeycomb pits) ; stem internally riddled with several hollows/chambers, not one single smooth hollow","IMPORTANT : the danger is NOT that Gyromitra gigas itself is strongly toxic (according to more recent research it contains little to no gyromitrin), but that it can hardly be reliably separated from the DEADLY spring false morel (Gyromitra esculenta) – therefore every brain-like convoluted false-morel find is to be avoided","The morel''s cap margin is attached to the stem ; the false morel''s cap is bulging-swollen and partly hangs free","Morel honeycomb walls are evenly ribbed ; false morel surface is irregularly furrowed like a walnut kernel/brain"}','f'),
('morchelchampignon','gyromitra_gigas','es','La colmenilla comestible tiene una superficie del sombrero regularmente alveolada-hundida, la gyromitra gigante una superficie irregularmente enrollada como cerebro/nuez, abultada e hinchada, sin verdaderos alvéolos.','Ambas más bien inodoras-fúngicas ; el olor NO las separa de forma fiable.','Colmenilla comestible en primavera sobre suelos calcáreos ; gyromitra gigante saprobionte de la madera en primavera, sobre tocones podridos, madera enterrada y mantillo de corteza (a menudo coníferas). El período de aparición se solapa – el hábitat no separa con certeza.','Ambos ascomicetos (ascas) con esporada pálida, color crema – inadecuado para la distinción.','Cortar a lo largo : la verdadera colmenilla forma UNA sola cavidad continua desde la punta hasta la base del pie y es alveolada. Dejar en el sitio todo lo que esté enrollado como cerebro con pie tabicado/recorrido por cavidades – no porque este hallazgo sea con seguridad mortal, sino porque no se pueden excluir de forma fiable las especies de gyromitra mortales. Nunca consumir las gyromitras crudas. En caso de duda : Tox Info Suisse 145.','{"Colmenilla comestible : sombrero alveolado-hundido con verdaderas cámaras ; sombrero Y pie forman UNA cavidad continua desde la base del pie hasta la punta del sombrero (el corte longitudinal muestra un cuerpo hueco común)","Gyromitra gigante : sombrero enrollado como cerebro, abultado-plegado (SIN alvéolos hundidos) ; pie recorrido internamente por varias cavidades/cámaras, no por una sola cavidad lisa","IMPORTANTE : el peligro NO es que Gyromitra gigas sea en sí muy tóxica (según investigaciones recientes apenas contiene gyromitrina o ninguna), sino que apenas se distingue con certeza de la gyromitra primaveral MORTAL (Gyromitra esculenta) – por ello todo hallazgo de gyromitra enrollada como cerebro debe evitarse","El borde del sombrero de la colmenilla está soldado al pie ; el sombrero de la gyromitra está hinchado-abultado y cuelga en parte libremente","Las paredes de los alvéolos de la colmenilla están regularmente acostilladas ; la superficie de la gyromitra está irregularmente surcada como una nuez/un cerebro"}','f'),
('morchelchampignon','gyromitra_gigas','fr','La morille comestible a une surface de chapeau régulièrement alvéolée-creusée, le gyromitre géant une surface irrégulièrement circonvoluée en cerveau/cerneau de noix, bosselée-gonflée sans véritables alvéoles.','Les deux plutôt fongiques discrets ; l''odeur ne les sépare PAS de façon fiable.','Morille comestible au printemps sur sols riches en calcaire ; gyromitre géant un saprobionte lignicole de printemps sur souches pourries, bois enterré et paillis d''écorce (souvent conifères). La période d''apparition se chevauche – l''habitat ne sépare pas sûrement.','Les deux ascomycètes (asques) à sporée pâle, crème – non adapté à la distinction.','Couper en long : la vraie morille est UNE cavité continue de la pointe à la base du pied et alvéolée. Laisser sur place tout ce qui est circonvolué en cerveau avec un pied cloisonné/traversé de cavités – non parce que cette trouvaille est sûrement mortelle, mais parce qu''on ne peut pas exclure de façon fiable les espèces de gyromitres mortelles. Gyromitres jamais crus. En cas de doute : Tox Info Suisse 145.','{"Morille comestible : chapeau alvéolé-creusé avec de véritables loges ; chapeau ET pied forment UNE cavité continue de la base du pied à la pointe du chapeau (la coupe longitudinale montre un corps creux commun)","Gyromitre géant : chapeau circonvolué en cerveau, bosselé-plissé (AUCUNE alvéole creusée) ; pied traversé à l''intérieur de plusieurs cavités/loges, pas une seule cavité lisse","IMPORTANT : le danger n''est PAS que Gyromitra gigas elle-même soit fortement toxique (selon des recherches récentes elle ne contient que peu ou pas de gyromitrine), mais qu''elle soit à peine séparable sûrement du gyromitre comestible MORTEL (Gyromitra esculenta) – c''est pourquoi toute trouvaille de gyromitre circonvoluée en cerveau est à éviter","Le bord du chapeau de la morille est attaché au pied ; le chapeau du gyromitre est bosselé-gonflé et pend en partie librement","Parois des alvéoles de la morille régulièrement côtelées ; surface du gyromitre irrégulièrement creusée comme un cerneau de noix/cerveau"}','f'),
('morchelchampignon','gyromitra_gigas','it','La spugnola commestibile ha una superficie del cappello regolarmente alveolata-scavata, la gyromitra gigante una superficie irregolarmente avvolta a cervello/gheriglio di noce, bitorzoluta e rigonfia, senza veri alveoli.','Entrambe piuttosto inodori-fungine ; l''odore NON le separa in modo affidabile.','Spugnola commestibile in primavera su suoli calcarei ; gyromitra gigante saprobionte del legno in primavera, su ceppi marci, legno interrato e pacciame di corteccia (spesso conifere). Il periodo di comparsa si sovrappone – l''habitat non separa con certezza.','Entrambi ascomiceti (aschi) con sporata pallida, color crema – inadatto alla distinzione.','Tagliare per il lungo : la vera spugnola forma UNA sola cavità continua dalla punta fino alla base del gambo ed è alveolata. Lasciare sul posto tutto ciò che è avvolto a cervello con gambo camerato/percorso da cavità – non perché questo ritrovamento sia sicuramente mortale, ma perché non si possono escludere in modo affidabile le specie di gyromitra mortali. Mai consumare le gyromitre crude. In caso di dubbio : Tox Info Suisse 145.','{"Spugnola commestibile : cappello alveolato-scavato con vere camere ; cappello E gambo formano UNA cavità continua dalla base del gambo fino alla punta del cappello (la sezione longitudinale mostra un corpo cavo comune)","Gyromitra gigante : cappello avvolto a cervello, bitorzoluto-pieghettato (NESSUN alveolo scavato) ; gambo percorso internamente da più cavità/camere, non da una sola cavità liscia","IMPORTANTE : il pericolo NON è che Gyromitra gigas sia di per sé fortemente tossica (secondo ricerche recenti contiene quasi o per nulla gyromitrina), ma che si distingua a malapena con certezza dalla gyromitra primaverile MORTALE (Gyromitra esculenta) – perciò ogni ritrovamento di gyromitra avvolta a cervello è da evitare","Il bordo del cappello della spugnola è saldato al gambo ; il cappello della gyromitra è rigonfio e pende in parte liberamente","Le pareti degli alveoli della spugnola sono regolarmente costolate ; la superficie della gyromitra è irregolarmente solcata come un gheriglio di noce/un cervello"}','f'),
('morchelchampignon','helvella_crispa','en','The edible morel shows a true honeycomb structure ; the white saddle a pitless, white, saddle-lobed cap and a markedly ribbed-chambered stem.','No reliable smell-based distinguishing feature.','Edible morel mainly spring on calcareous soils ; white saddle mainly summer–autumn along forest paths/edges in deciduous/mixed forest – season usually separates.','Both with pale spore print – no practical distinguishing feature.','Accept as morel only honeycombed caps with an internally continuous hollow. White saddle-/lobe forms with a furrowed chambered stem are false morels – do not eat.','{"Edible morel : rounded-ovoid, honeycomb-pitted cap ; cap and stem form a continuous hollow","White saddle : whitish, saddle-/lobe-folded cap without pits ; stem deeply longitudinally ribbed-furrowed with hollow chambers","The white saddle is gyromitrin-containing/toxic raw, not a harmless edible mushroom ; the morel is edible only cooked (poorly tolerated raw)","The morel surface consists of clear honeycomb pits ; the false morel surface of smooth convoluted lobes"}','f'),
('morchelchampignon','helvella_crispa','es','La colmenilla comestible presenta una verdadera estructura alveolar ; la helvella crespa un sombrero blanco, lobulado en silla de montar, sin alvéolos, y un pie marcadamente acostillado-tabicado.','Ningún criterio olfativo de distinción fiable.','Colmenilla comestible sobre todo en primavera en suelos calcáreos ; helvella crespa sobre todo en verano–otoño a lo largo de caminos forestales/linderos en bosque caducifolio/mixto – la estación separa la mayoría de las veces.','Ambas con esporada clara – ningún criterio práctico de distinción.','Aceptar como colmenilla solo los sombreros alveolados con cavidad interna continua. Las formas blancas en silla/con lóbulos con pie tabicado y surcado son helvellas – no comer.','{"Colmenilla comestible : sombrero redondeado-ovoide, alveolado-hundido ; sombrero y pie forman una cavidad continua","Helvella crespa : sombrero blanquecino, plegado en silla/con lóbulos sin alvéolos ; pie profundamente acostillado-surcado a lo largo con cámaras huecas","La helvella crespa contiene gyromitrina/es tóxica cruda, no es una seta comestible inofensiva ; la colmenilla es comestible solo cocinada (mal tolerada cruda)","La superficie de la colmenilla está formada por alvéolos nítidos ; la superficie de la helvella por lóbulos lisos enrollados"}','f'),
('morchelchampignon','helvella_crispa','fr','La morille comestible montre une véritable structure alvéolaire ; l''helvelle crépue un chapeau blanc, sans alvéoles, lobé en selle et un pied nettement côtelé-cloisonné.','Pas de critère olfactif fiable de séparation.','Morille comestible surtout au printemps sur sols riches en calcaire ; helvelle crépue surtout été–automne aux bords de chemins forestiers/lisières en forêt de feuillus/mixte – la saison sépare le plus souvent.','Les deux à sporée claire – pas un critère de séparation pratique.','N''accepter comme morille que les chapeaux alvéolés à cavité interne continue. Les formes blanches en selle/lobes à pied creux cloisonné sont des helvelles – ne pas manger.','{"Morille comestible : chapeau arrondi-ovoïde, alvéolé-creusé ; chapeau et pied forment une cavité continue","Helvelle crépue : chapeau blanchâtre, plié en selle/lobes sans alvéoles ; pied profondément côtelé-cannelé avec des loges creuses","L''helvelle crépue est contenant de la gyromitrine/crue toxique, pas un comestible inoffensif ; morille comestible seulement cuite (crue mal tolérée)","Surface de la morille faite d''alvéoles nettes ; surface de l''helvelle faite de lobes lisses circonvolués"}','f'),
('morchelchampignon','helvella_crispa','it','La spugnola commestibile presenta una vera struttura alveolare ; l''helvella crespa un cappello bianco, lobato a sella, senza alveoli, e un gambo marcatamente costolato-camerato.','Nessun criterio olfattivo di distinzione affidabile.','Spugnola commestibile soprattutto in primavera su suoli calcarei ; helvella crespa soprattutto in estate–autunno lungo i sentieri forestali/margini in bosco di latifoglie/misto – la stagione separa il più delle volte.','Entrambe con sporata chiara – nessun criterio pratico di distinzione.','Accettare come spugnola solo i cappelli alveolati con cavità interna continua. Le forme bianche a sella/a lobi con gambo camerato e solcato sono helvelle – non mangiare.','{"Spugnola commestibile : cappello arrotondato-ovoidale, alveolato-scavato ; cappello e gambo formano una cavità continua","Helvella crespa : cappello biancastro, pieghettato a sella/a lobi senza alveoli ; gambo profondamente costolato-solcato per il lungo con camere cave","L''helvella crespa contiene gyromitrina/è tossica da cruda, non è un fungo commestibile innocuo ; la spugnola è commestibile solo da cotta (mal tollerata cruda)","La superficie della spugnola è fatta di alveoli netti ; la superficie dell''helvella di lobi lisci avvolti"}','f'),
('morchelchampignon','verpa_bohemica','en','Common morel: deeply pitted cap, fully fused to the stem; verpa: smooth-wrinkled, freely hanging thimble-like cap.','Both with a discreet pleasant mushroomy smell — smell does NOT help to tell them apart here, only structure and a cut do.','Both in spring; Verpa bohemica often somewhat earlier under ash/poplar in floodplain forests.',NULL,'Always cut lengthwise: if the cap is attached only at the tip and otherwise hangs free, it is NOT a true morel — and never eat it raw.','{"In the common morel the cap is fused to the stem over its entire length (a completely hollow unit); in the verpa the cap hangs free like a bell and is attached only at the very top, at the stem tip","The common morel''s cap shows deep honeycomb-like pits; Verpa bohemica has only longitudinal/transverse brain-like folds without true pits","The lengthwise cut is decisive: the common morel is hollow throughout from cap to stem base; the verpa''s stem is filled/chambered with a cottony-flaky interior","Both should be eaten only well cooked and never raw — Verpa bohemica is gastrointestinally toxic raw or insufficiently cooked"}','f'),
('morchelchampignon','verpa_bohemica','es','Colmenilla común: sombrero profundamente alveolado, totalmente soldado al pie; verpa: sombrerillo liso-rugoso en forma de dedal, colgante libremente.','Ambas con olor fúngico-agradable discreto — el olor NO ayuda aquí a distinguirlas, solo la estructura y el corte lo permiten.','Ambas en primavera; Verpa bohemica a menudo algo antes bajo fresnos/álamos en bosques de ribera.',NULL,'Cortar siempre a lo largo: si el sombrerillo está unido solo en la punta y por lo demás cuelga libre, NO es una colmenilla verdadera — y nunca consumirla cruda.','{"En la colmenilla común el sombrero está soldado al pie en toda su longitud (unidad totalmente hueca); en la verpa el sombrerillo cuelga libre en forma de campana y solo está unido arriba del todo, en la punta del pie","El sombrero de la colmenilla común muestra alvéolos profundos en panal; Verpa bohemica solo tiene pliegues longitudinales/transversales cerebriformes sin verdaderos alvéolos","El corte longitudinal es decisivo: la colmenilla común es hueca de forma continua del sombrero a la base del pie; el pie de la verpa está relleno/tabicado internamente de modo algodonoso-flocoso","Ambas solo se comen bien cocinadas y nunca crudas — Verpa bohemica es gastrointestinalmente tóxica cruda o insuficientemente cocida"}','f'),
('morchelchampignon','verpa_bohemica','fr','Morille commune : chapeau profondément alvéolé, entièrement soudé au pied ; verpe : chapeau lisse-ridé en forme de dé à coudre, librement pendant.','Toutes deux d''une odeur fongique-agréable discrète — l''odeur n''aide PAS ici à les distinguer, seuls la structure et la coupe le permettent.','Toutes deux au printemps ; Verpa bohemica souvent un peu plus tôt sous les frênes/peupliers en forêts alluviales.',NULL,'Toujours couper en long : si le chapeau n''est soudé qu''à son sommet et pend librement par ailleurs, ce n''est PAS une vraie morille — et ne jamais la consommer crue.','{"Chez la morille commune, le chapeau est soudé au pied sur toute sa longueur (unité entièrement creuse) ; chez la verpe, le chapeau pend librement en cloche et n''est soudé qu''tout en haut, à la pointe du pied","Le chapeau de la morille commune présente des alvéoles profondes en nid d''abeille ; Verpa bohemica n''a que des plis longitudinaux/transversaux cérébriformes sans véritables alvéoles","La coupe longitudinale tranche : la morille commune est entièrement creuse du chapeau jusqu''à la base du pied ; le pied de la verpe est rempli/cloisonné de manière cotonneuse-floconneuse à l''intérieur","Toutes deux ne se mangent que bien cuites et jamais crues — Verpa bohemica est toxique pour l''estomac et les intestins crue ou insuffisamment cuite"}','f'),
('morchelchampignon','verpa_bohemica','it','Spugnola comune: cappello profondamente alveolato, completamente saldato al gambo; verpa: cappellino liscio-rugoso a forma di ditale, liberamente pendente.','Entrambe con odore fungino-gradevole discreto — l''odore NON aiuta qui a distinguerle, solo la struttura e il taglio lo permettono.','Entrambe in primavera; Verpa bohemica spesso un po'' prima sotto frassini/pioppi nei boschi ripariali.',NULL,'Tagliare sempre per il lungo: se il cappellino è attaccato solo all''apice e per il resto pende libero, NON è una vera spugnola — e non consumarla mai cruda.','{"Nella spugnola comune il cappello è saldato al gambo per tutta la lunghezza (unità completamente cava); nella verpa il cappellino pende libero a campana ed è attaccato solo in cima, alla punta del gambo","Il cappello della spugnola comune mostra profonde depressioni alveolate a nido d''ape; Verpa bohemica ha solo pieghe longitudinali/trasversali cerebriformi senza vere alveolature","Il taglio longitudinale è decisivo: la spugnola comune è cava in modo continuo dal cappello alla base del gambo; il gambo della verpa è riempito/camerato internamente in modo cotonoso-floccoso","Entrambe si mangiano solo ben cotte e mai crude — Verpa bohemica è gastro-intestinale-tossica cruda o cotta insufficientemente"}','f'),
('morchella_elata','fliegenpilz-grosspilz','en','Morel honeycombed/regular vs. false morel brain-like/irregular.','both unspecific','both spring, burn sites/floodplain forest/coniferous forest','no gill spore powder (ascomycetes)','The spring false morel is highly toxic (potentially deadly). Longitudinal cut: continuously hollow (morel) vs. cottony-chambered (false morel).','{"Black morel: honeycombed-pitted cap, cap+stem completely hollow","Spring false morel: brain-like convoluted, stem chambered (not hollow), gyromitrin (highly toxic)"}','t'),
('morchella_elata','fliegenpilz-grosspilz','es','Colmenilla: alveolada/regular frente a la falsa colmenilla cerebriforme-irregular.','ambas inespecíficas','ambas en primavera, zonas quemadas/bosque de ribera/bosque de coníferas','sin esporada laminar (hongos ascomicetos)','La falsa colmenilla de primavera es muy tóxica (potencialmente mortal). Corte longitudinal: completamente hueco (colmenilla) frente a algodonoso-tabicado (falsa colmenilla).','{"Colmenilla puntiaguda: sombrero alveolado-acanalado, sombrero+pie completamente huecos","Falsa colmenilla de primavera: cerebriforme y retorcida, pie tabicado (no hueco), giromitrina (muy tóxica)"}','t'),
('morchella_elata','fliegenpilz-grosspilz','fr','Morille à structure alvéolée/régulière vs. gyromitre à aspect cérébriforme/irrégulier.','Les deux : odeur non spécifique.','Les deux : au printemps, zones brûlées/forêt alluviale/forêt de conifères.','Pas de sporée de lamelles (ascomycètes).','La gyromitre (gyromitre printanier) est hautement toxique (potentiellement mortelle). Coupe longitudinale : entièrement creux (morille) vs. ouaté-cloisonné (gyromitre).','{"Morille conique (Morchella elata) : chapeau alvéolé-creusé, chapeau + pied entièrement creux","Gyromitre printanier : forme cérébriforme contournée, pied cloisonné (non creux), gyromitrine (hautement toxique)"}','t'),
('morchella_elata','fliegenpilz-grosspilz','it','La spugnola è alveolata/regolare, mentre la girella (Gyromitra) è cerebriforme-irregolare.','entrambe aspecifiche','entrambe in primavera, su zone bruciate/boschi golenali/boschi di conifere','nessuna sporata lamellare (funghi ascomiceti)','La girella primaverile (Gyromitra esculenta) è altamente tossica (potenzialmente mortale). Taglio longitudinale: completamente cava (spugnola) vs. ovattata-camerata (girella).','{"Spugnola appuntita (Morchella elata): cappello alveolato-fossettato, cappello e gambo completamente cavi","Girella primaverile (Gyromitra esculenta): contorta in modo cerebriforme, gambo camerato (non cavo), giromitrina (altamente tossica)"}','t'),
('morchella_elata','gyromitra_gigas','en','The black morel is tall-conical with elongated, ladder-like arranged dark ridges ; the giant false morel is squat-rounded and brain-like folded.','Smell of both species unspecifically mushroomy – not a distinguishing feature.','Black morel in spring on disturbed/calcareous soils and bark mulch ; giant false morel in spring as a wood saprobiont on rotten stumps/buried wood – habitat overlap possible.','Both ascomycetes with pale spore dust – no practical distinguishing feature.','Accept as morel only conical caps with true honeycomb AND a continuous hollow (longitudinal cut). Brain-like convoluted with a cavity-riddled stem = false morel = leave it, because deadly false morel species cannot be excluded with certainty.','{"Black morel : cap conical-pointed with longitudinally aligned, sharply delimited pits/chambers ; cap and stem form a continuous hollow","Giant false morel : cap rounded-bulbous, brain-like convoluted, NO conical tip and no true pits","Giant false morel stem internally riddled with several hollows ; black morel stem one continuous hollow","IMPORTANT : Gyromitra gigas itself contains, according to more recent research, little to no gyromitrin – the critical point is its confusability with the DEADLY spring false morel (G. esculenta) ; therefore avoid all false morel finds"}','f'),
('morchella_elata','gyromitra_gigas','es','La colmenilla cónica es alta y cónica con costillas oscuras alargadas dispuestas en escalera ; la gyromitra gigante es achaparrada-redondeada y plegada como cerebro.','Olor de ambas especies fúngico inespecífico – no es un criterio de distinción.','Colmenilla cónica en primavera sobre suelos alterados/calcáreos y mantillo de corteza ; gyromitra gigante en primavera como saprobionte de la madera sobre tocones podridos/madera enterrada – solapamiento de hábitat posible.','Ambos ascomicetos con polvo esporal claro – ningún criterio práctico de distinción.','Aceptar como colmenilla solo los sombreros cónicos con verdaderos alvéolos Y con cavidad continua (corte longitudinal). Enrollado como cerebro con pie recorrido por cavidades = gyromitra = dejar en el sitio, porque las especies de gyromitra mortales no se pueden excluir con certeza.','{"Colmenilla cónica : sombrero cónico-puntiagudo con alvéolos/cámaras orientados longitudinalmente, nítidamente delimitados ; sombrero y pie forman una cavidad continua","Gyromitra gigante : sombrero redondeado-bulboso, enrollado como cerebro, SIN punta cónica y sin verdaderos alvéolos","Pie de la gyromitra gigante recorrido internamente por varias cavidades ; pie de la colmenilla cónica una cavidad continua","IMPORTANTE : Gyromitra gigas en sí contiene, según investigaciones recientes, apenas gyromitrina o ninguna – el punto crítico es la confundibilidad con la gyromitra primaveral MORTAL (G. esculenta) ; por ello evitar todos los hallazgos de gyromitra"}','f'),
('morchella_elata','gyromitra_gigas','fr','La morille conique est haute-conique avec des côtes sombres allongées disposées en échelle ; le gyromitre géant est trapu-arrondi et plissé en forme de cerveau.','Odeur des deux espèces fongique non spécifique – pas un critère de séparation.','Morille conique au printemps sur sols perturbés/riches en calcaire et paillis d''écorce ; gyromitre géant au printemps comme saprobionte lignicole sur souches pourries/bois enterré – chevauchement possible dans l''habitat.','Les deux ascomycètes à poussière sporale claire – pas un critère de séparation pratique.','N''accepter comme morille que les chapeaux coniques à véritables alvéoles ET avec une cavité continue (coupe longitudinale). Circonvolué en cerveau avec un pied traversé de cavités = gyromitre = laisser sur place, parce que les espèces de gyromitres mortelles ne peuvent pas être exclues sûrement.','{"Morille conique : chapeau conique-pointu avec alvéoles/loges orientées longitudinalement, nettement délimitées ; chapeau et pied forment une cavité continue","Gyromitre géant : chapeau arrondi-bosselé, circonvolué en cerveau, AUCUNE pointe conique et pas de véritables alvéoles","Pied du gyromitre traversé à l''intérieur de plusieurs cavités ; pied de la morille conique une cavité continue","IMPORTANT : Gyromitra gigas elle-même contient selon des recherches récentes peu ou pas de gyromitrine – critique est la confusion possible avec le gyromitre printanier mortel (G. esculenta) ; c''est pourquoi éviter toutes les trouvailles de gyromitres"}','f'),
('morchella_elata','gyromitra_gigas','it','La spugnola conica è alta e conica con costole scure allungate disposte a scala ; la gyromitra gigante è tozza-arrotondata e pieghettata a cervello.','Odore di entrambe le specie fungino aspecifico – non un criterio di distinzione.','Spugnola conica in primavera su suoli disturbati/calcarei e pacciame di corteccia ; gyromitra gigante in primavera come saprobionte del legno su ceppi marci/legno interrato – sovrapposizione di habitat possibile.','Entrambi ascomiceti con polvere sporale chiara – nessun criterio pratico di distinzione.','Accettare come spugnola solo i cappelli conici con veri alveoli E con cavità continua (sezione longitudinale). Avvolto a cervello con gambo percorso da cavità = gyromitra = lasciare sul posto, perché le specie di gyromitra mortali non si possono escludere con certezza.','{"Spugnola conica : cappello conico-appuntito con alveoli/camere orientati longitudinalmente, nettamente delimitati ; cappello e gambo formano una cavità continua","Gyromitra gigante : cappello arrotondato-bulboso, avvolto a cervello, NESSUNA punta conica e nessun vero alveolo","Gambo della gyromitra gigante percorso internamente da più cavità ; gambo della spugnola conica una cavità continua","IMPORTANTE : Gyromitra gigas di per sé contiene, secondo ricerche recenti, quasi o per nulla gyromitrina – il punto critico è la confondibilità con la gyromitra primaverile MORTALE (G. esculenta) ; perciò evitare tutti i ritrovamenti di gyromitra"}','f'),
('morchella_elata','verpa_bohemica','en','Black morel: conical-pointed pitted cap, fully fused; verpa: rounded-blunt wrinkled cap, freely hanging.',NULL,'Black morel on wood chips/burn sites/in gardens; Verpa bohemica rather in moist floodplain forests under ash/poplar.',NULL,'Lengthwise-cut rule: it is a true morel only if the cap is fused to the stem over its entire length and is hollow throughout.','{"The black morel has a conical-pointed, longitudinally ribbed cap fully fused to the stem with true honeycomb chambers; Verpa bohemica bears a rounded cap attached only at the tip, hanging freely","The black morel is hollow over its whole height (cap + stem a single chamber); the verpa''s stem is filled inside in a cottony-flaky manner","The black morel''s cap surface is net-like-pitted with longitudinal ribs; the verpa is only irregularly brain-like wrinkled","Verpa bohemica raw/insufficiently cooked is gastrointestinally toxic — like all morels, enjoy only well cooked"}','f'),
('morchella_elata','verpa_bohemica','es','Colmenilla cónica: sombrero alveolado cónico-puntiagudo, totalmente soldado; verpa: sombrerillo rugoso redondeado-obtuso, colgante libremente.',NULL,'Colmenilla cónica sobre virutas de madera/zonas quemadas/en jardines; Verpa bohemica más bien en bosques de ribera húmedos bajo fresno/álamo.',NULL,'Regla del corte longitudinal: solo es una colmenilla verdadera si el sombrero está soldado al pie en toda su longitud y es hueco de extremo a extremo.','{"La colmenilla cónica tiene un sombrero cónico-puntiagudo, costillado longitudinalmente y totalmente soldado al pie con verdaderas cámaras alveolares; Verpa bohemica lleva un sombrerillo redondeado, unido solo en la punta, colgante libremente","La colmenilla cónica es hueca en toda su altura (sombrero + pie una sola cámara); el pie de la verpa está relleno internamente de modo algodonoso-flocoso","La superficie del sombrero de la colmenilla cónica es reticulado-alveolada con costillas longitudinales; la verpa solo está rugosa irregularmente de modo cerebriforme","Verpa bohemica cruda/insuficientemente cocida es gastrointestinalmente tóxica — como todas las colmenillas, disfrutar solo bien cocida"}','f'),
('morchella_elata','verpa_bohemica','fr','Morille conique : chapeau alvéolé conique-pointu, entièrement soudé ; verpe : chapeau ridé arrondi-obtus, librement pendant.',NULL,'Morille conique sur copeaux de bois/zones brûlées/dans les jardins ; Verpa bohemica plutôt en forêts alluviales humides sous frêne/peuplier.',NULL,'Règle de la coupe longitudinale : ce n''est une vraie morille que si le chapeau est soudé au pied sur toute sa longueur et est creux de bout en bout.','{"La morille conique a un chapeau conique-pointu, côtelé longitudinalement et entièrement soudé au pied, avec de vraies alvéoles ; Verpa bohemica porte un chapeau arrondi, soudé seulement au sommet, librement pendant","La morille conique est creuse sur toute sa hauteur (chapeau + pied une seule cavité) ; le pied de la verpe est rempli à l''intérieur de manière cotonneuse-floconneuse","La surface du chapeau de la morille conique est réticulée-alvéolée avec des côtes longitudinales ; la verpe est seulement ridée irrégulièrement de façon cérébriforme","Verpa bohemica crue/insuffisamment cuite est toxique pour l''estomac et les intestins — comme toutes les morilles, à déguster uniquement bien cuite"}','f'),
('morchella_elata','verpa_bohemica','it','Spugnola conica: cappello alveolato conico-appuntito, completamente saldato; verpa: cappellino rugoso arrotondato-ottuso, liberamente pendente.',NULL,'Spugnola conica su cippato/aree bruciate/nei giardini; Verpa bohemica piuttosto in boschi ripariali umidi sotto frassino/pioppo.',NULL,'Regola del taglio longitudinale: è una vera spugnola solo se il cappello è saldato al gambo per tutta la lunghezza ed è cavo per intero.','{"La spugnola conica ha un cappello conico-appuntito, costolato longitudinalmente e completamente saldato al gambo con vere camere alveolari; Verpa bohemica porta un cappellino arrotondato, attaccato solo all''apice, liberamente pendente","La spugnola conica è cava per tutta l''altezza (cappello + gambo una sola camera); il gambo della verpa è riempito internamente in modo cotonoso-floccoso","La superficie del cappello della spugnola conica è reticolato-alveolata con coste longitudinali; la verpa è solo irregolarmente rugosa in modo cerebriforme","Verpa bohemica cruda/cotta insufficientemente è gastro-intestinale-tossica — come tutte le spugnole, da gustare solo ben cotta"}','f'),
('paralepista_flaccida','ampulloclitocybe_clavipes','en','Strongly funnel-shaped, foxy orange-red-brown cap and slender stem in the Tawny Funnel Cap vs. greyish-white to grey-brown cap and club-swollen stem base in clavipes.','Tawny Funnel Cap inconspicuous to faintly sweetish ; clavipes weakly fruity.','The Tawny often clustered in thick needle/leaf litter ; clavipes in mixed and coniferous forests.','Both with cream-white spore print ; not reliably separating.','Check the stem base : club-shaped, spongy-swollen indicates clavipes ; not for the basket, never with alcohol.','{"Tawny Funnel Cap : deeply funnel-depressed, foxy orange-red-brown (strongly hygrophanous) cap and slender, NOT club-thickened stem ; clavipes with greyish-white to grey-brown cap and club-swollen stem base.","The Tawny often grows clustered/in rows in leaf litter and needle mulch ; clavipes rather single to gregarious.","Gills of the Tawny very crowded, forked and far decurrent, whitish to ochre-yellowish ; clavipes gills whitish, far decurrent.","clavipes toxic with alcohol (coprine syndrome) ; the Tawny is edible cooked (larger amounts can be hard to digest)."}','f'),
('paralepista_flaccida','ampulloclitocybe_clavipes','es','Sombrero fuertemente infundibuliforme, pardo-anaranjado leonado a pardo-rojizo, y pie esbelto en el Clitocybe invertido ; sombrero gris-blanco a gris-pardo y base del pie engrosada-claviforme en clavipes.','Clitocybe invertido inodoro o ligeramente dulzón ; clavipes débilmente afrutado.','El invertido a menudo cespitoso en gruesa hojarasca de acículas/hojas ; clavipes en bosques mixtos y de coníferas.','Ambos con esporada blanco-crema ; no separa de forma fiable.','Examinar la base del pie : claviforme-esponjosa e hinchada indica clavipes ; no al cesto, nunca con alcohol.','{"Clitocybe invertido : sombrero profundamente infundibuliforme, pardo-anaranjado leonado a pardo-rojizo (fuertemente higrófano) y pie esbelto NO engrosado en maza ; clavipes con sombrero gris-blanco a gris-pardo y base del pie hinchada en maza.","El invertido crece a menudo cespitoso/en hileras en la hojarasca y el mantillo de acículas ; clavipes más bien solitario a gregario.","Láminas del invertido muy apretadas, bifurcadas y largamente decurrentes, blanquecinas a ocre-amarillentas ; láminas de clavipes blanquecinas, largamente decurrentes.","clavipes tóxico con alcohol (síndrome coprínico) ; el invertido es comestible cocinado (grandes cantidades pueden ser de difícil digestión)."}','f'),
('paralepista_flaccida','ampulloclitocybe_clavipes','fr','Chapeau roux orange-rouge-brun, fortement en entonnoir, et pied élancé chez le clitocybe inversé vs. chapeau blanc-gris à gris-brun et base du pied renflée en massue chez clavipes.','Clitocybe inversé discret à légèrement sucré ; clavipes faiblement fruité.','Clitocybe inversé souvent en touffes dans une épaisse litière de conifères/feuillus ; clavipes en forêt mixte et de conifères.','Les deux à sporée blanc-crème ; non discriminant de façon fiable.','Vérifier la base du pied : renflée en massue-spongieuse indique clavipes, pas dans le panier, jamais avec de l''alcool.','{"Clitocybe inversé : chapeau profondément en entonnoir, roux orange-rouge-brun (fortement hygrophane) et pied élancé, NON épaissi en massue ; clavipes avec chapeau blanc-gris à gris-brun et base du pied renflée en massue.","Clitocybe inversé souvent en touffes/rangées dans la litière de feuillus et le paillis de conifères ; clavipes plutôt isolé à grégaire.","Lamelles du clitocybe inversé très serrées, fourchues et largement décurrentes, blanchâtres à ocre-jaunâtre ; lamelles de clavipes blanchâtres, largement décurrentes.","clavipes toxique avec l''alcool (syndrome coprinien) ; le clitocybe inversé est comestible cuit (de grandes quantités peuvent être difficiles à digérer)."}','f'),
('paralepista_flaccida','ampulloclitocybe_clavipes','it','Cappello fortemente imbutiforme, bruno-arancio fulvo o bruno-rosso, e gambo slanciato nel Clitocybe rovesciato ; cappello grigio-bianco o grigio-bruno e base del gambo ingrossata-clavata in clavipes.','Clitocybe rovesciato inodore o lievemente dolciastro ; clavipes debolmente fruttato.','Il rovesciato spesso cespitoso in spessa lettiera di aghi/foglie ; clavipes in boschi misti e di conifere.','Entrambi con sporata bianco-crema ; non separa in modo affidabile.','Controllare la base del gambo : clavata-spugnosa e gonfia indica clavipes ; non metterlo nel cestino, mai con alcol.','{"Clitocybe rovesciato : cappello profondamente imbutiforme, bruno-arancio fulvo o bruno-rosso (fortemente igrofano) e gambo slanciato NON ingrossato a clava ; clavipes con cappello grigio-bianco o grigio-bruno e base del gambo gonfiata a clava.","Il rovesciato cresce spesso cespitoso/in file nella lettiera di foglie e nella pacciamatura di aghi ; clavipes piuttosto isolato o gregario.","Lamelle del rovesciato molto fitte, biforcate e lungamente decorrenti, biancastre o ocra-giallastre ; lamelle di clavipes biancastre, lungamente decorrenti.","clavipes tossico con l''alcol (sindrome coprinica) ; il rovesciato è commestibile da cotto (grandi quantità possono essere di difficile digestione)."}','f'),
('parasol','amanita_pantherina','en','Parasol: light-brown cap, snakeskin-patterned stem. Panther: brown with white warts, white stem with bulbs.','Parasol: nutty, pleasant. Panther: radish-like.','Parasol: meadows, forest edge. Panther: deciduous forest.','Both white.','PARASOL test: ring movable-slidable, stem snakeskin-patterned. With warts, NEVER eat.','{"Parasol ring MOVABLE, Panther ring fixed","Parasol snakeskin-patterned stem, Panther white-smooth","Panther has a bulb with 2-3 ring-like rolls"}','t'),
('parasol','amanita_pantherina','es','Parasol: sombrero pardo claro, pie con dibujo de piel de serpiente. Pantera: pardo con motas blancas, pie blanco con bulbos.','Parasol: a nuez, agradable. Pantera: a rábano.','Parasol: praderas, lindes del bosque. Pantera: bosque de frondosas.','Ambas blancas.','Prueba del PARASOL: anillo móvil-desplazable, pie con dibujo de piel de serpiente. Si hay motas, NUNCA comerlo.','{"Anillo del parasol MÓVIL, anillo de la pantera fijo","Parasol con pie de piel de serpiente, pantera de pie blanco-liso","La pantera tiene un bulbo con 2-3 rebordes anulares"}','t'),
('parasol','amanita_pantherina','fr','Lépiote élevée (parasol) : chapeau brun clair, pied chiné (motif de peau de serpent). Amanite panthère : brune avec des flocons blancs, pied blanc à bulbe.','Lépiote élevée (parasol) : odeur de noisette agréable. Amanite panthère : odeur de radis (raifort).','Lépiote élevée (parasol) : prairies, lisières de forêt. Amanite panthère : forêt de feuillus.','Les deux : blanc.','Test PARASOL : anneau mobile (coulissant), pied chiné. En présence de flocons, NE JAMAIS consommer.','{"Anneau de la lépiote élevée (parasol) MOBILE, anneau de l''amanite panthère fixe","Lépiote élevée (parasol) à pied chiné, amanite panthère à pied blanc et lisse","L''amanite panthère possède un bulbe à 2-3 bourrelets"}','t'),
('parasol','amanita_pantherina','it','Mazza di tamburo (parasol): cappello bruno chiaro, gambo zebrato a pelle di serpente. Tignosa bigia (Amanita pantherina): bruna con verruche bianche, gambo bianco con bulbo.','Mazza di tamburo (parasol): nocciolato, gradevole. Tignosa bigia (Amanita pantherina): odore di ravanello.','Mazza di tamburo (parasol): prati, margini del bosco. Tignosa bigia (Amanita pantherina): bosco di latifoglie.','Entrambe bianca.','Test della MAZZA DI TAMBURO: anello mobile-scorrevole, gambo zebrato. In presenza di verruche NON mangiarla MAI.','{"Anello della mazza di tamburo (parasol) MOBILE, anello della tignosa bigia (Amanita pantherina) fisso","Mazza di tamburo (parasol) con gambo zebrato, tignosa bigia (Amanita pantherina) con gambo bianco-liscio","La tignosa bigia (Amanita pantherina) ha un bulbo con 2-3 cercini"}','t'),
('parasol','chlorophyllum_brunneum','en','Stem snakeskin patterning (Parasol yes) + reddening (toxic shaggy parasol yes) + bulb.','both unspecific','Parasol forest/meadow; toxic shaggy parasol often compost/garden','both white-cream','Gastrointestinal toxin. Snakeskin-patterned stem + no reddening = Parasol; smooth stem + saffron-red discoloration = hands off.','{"Parasol: snakeskin-patterned (snakeskin-like) stem, slidable double ring, flesh does NOT redden","Toxic shaggy parasol: smooth stem, rimmed bulb, flesh/gills discolor saffron-red"}','t'),
('parasol','chlorophyllum_brunneum','es','Dibujo serpenteado del pie (parasol sí) + enrojecimiento (lepiota tóxica/Chlorophyllum sí) + bulbo.','ambas inespecíficas','Parasol en bosque/pradera; la lepiota tóxica (Chlorophyllum) a menudo en compost/jardín','ambas blanco-crema','Tóxico gastrointestinal. Pie con dibujo serpenteado + sin enrojecimiento = parasol; pie liso + coloración rojo azafrán = no tocar.','{"Parasol: pie con dibujo serpenteado (tipo piel de serpiente), anillo doble desplazable, la carne NO enrojece","Lepiota tóxica (Chlorophyllum): pie liso, bulbo marginado, la carne/láminas se tiñen de rojo azafrán"}','t'),
('parasol','chlorophyllum_brunneum','fr','Chinure du pied (présente chez la lépiote élevée/parasol) + rougissement (présent chez la lépiote vénéneuse/Chlorophyllum) + bulbe.','Les deux : odeur non spécifique.','Lépiote élevée (parasol) : forêt/prairie ; lépiote vénéneuse (Chlorophyllum) : souvent compost/jardin.','Les deux : blanc-crème.','Poison gastro-intestinal. Pied chiné + pas de rougissement = lépiote élevée (parasol) ; pied lisse + coloration rouge safran = on n''y touche pas.','{"Lépiote élevée (parasol) : pied chiné (motif de peau de serpent), double anneau coulissant, chair qui NE rougit PAS","Lépiote vénéneuse (Chlorophyllum) : pied lisse, bulbe marginé, chair/lamelles se colorant en rouge safran"}','t'),
('parasol','chlorophyllum_brunneum','it','Zebratura del gambo (mazza di tamburo/parasol sì) + arrossamento (lepiota tossica/Chlorophyllum sì) + bulbo.','entrambi aspecifico','Mazza di tamburo (parasol) bosco/prato; lepiota tossica (Chlorophyllum) spesso su compost/giardino','entrambi bianco-crema','Veleno gastrointestinale. Gambo zebrato + nessun arrossamento = mazza di tamburo (parasol); gambo liscio + viraggio rosso zafferano = giù le mani.','{"Mazza di tamburo (parasol): gambo zebrato (a pelle di serpente), doppio anello scorrevole, la carne NON arrossa","Lepiota tossica (Chlorophyllum): gambo liscio, bulbo marginato, la carne/le lamelle virano al rosso zafferano"}','t'),
('parasol','lepiota_brunneoincarnata','en','The parasol mushroom is large with a distinctly snakeskin-patterned stem and a double movable ring; the deadly dapperling stays small (under 5 cm) with a flesh-pink-brown, finely scaly cap surface and an unpatterned stem.','The parasol smells mild-nutty; the poisonous dapperling sweetish-fruity - smell is NOT a sure separating feature, never rely on it.','Parasol at forest edges/meadows; the poisonous dapperling in warm, sandy-grassy spots, parks and path edges - overlap possible.','Both have a WHITE spore print - the spore print does NOT separate them, so size, stem patterning and the double movable ring must absolutely be checked.','Accept a dapperling as a parasol only if the cap clearly exceeds 10 cm AND the stem is snakeskin-patterned AND the ring is double and movable - as a matter of principle NEVER eat small dapperlings under 8-10 cm.','{"The parasol is large: cap 10-30 cm; the flesh-pink dapperling is small: cap only 2-5 cm - SIZE is the first warning signal","The parasol has a DOUBLE, freely movable ring on the stem; the poisonous dapperling has only a fleeting, fibrous, NON-movable ring zone","Parasol stem distinctly snakeskin-patterned (snakeskin-like banded); poisonous dapperling stem with flesh-brown fibrous scale belts, without snakeskin pattern","Parasol cap with large, coarse brown scales on a pale ground + umbo; poisonous dapperling cap finely flesh-brown-pink scaly, small","The flesh-pink dapperling contains amatoxins (like the death cap) - deadly, even a small amount damages the liver irreversibly"}','f'),
('parasol','lepiota_brunneoincarnata','es','La galamperna (parasol) es grande con pie claramente jaspeado (piel de serpiente) y anillo doble deslizante; la lepiota mortal permanece pequeña (menos de 5 cm) con superficie del sombrero pardo-rosa carne finamente escamosa y pie no jaspeado.','El parasol huele suave a nuez; la lepiota tóxica dulzón-afrutado - el olor NO es un rasgo de separación seguro, no fiarse nunca de él.','Parasol en bordes de bosque/prados; la lepiota tóxica en lugares cálidos, arenoso-herbosos, parques y bordes de caminos - solapamiento posible.','Ambos tienen esporada BLANCA - la esporada NO los separa, por lo que es imprescindible verificar el tamaño, el jaspeado del pie y el anillo doble deslizante.','Aceptar una lepiota como parasol solo si el sombrero mide claramente más de 10 cm Y el pie está jaspeado Y el anillo es doble y deslizante - por principio NUNCA comer lepiotas pequeñas de menos de 8-10 cm.','{"El parasol es grande: sombrero 10-30 cm; la lepiota pardo-rosada es pequeña: sombrero solo 2-5 cm - el TAMAÑO es la primera señal de alarma","El parasol tiene un anillo DOBLE, libremente deslizante en el pie; la lepiota tóxica solo tiene una zona anular fugaz, fibrosa, NO deslizante","Pie del parasol claramente jaspeado (bandeado como piel de serpiente); pie de la lepiota tóxica con cinturones de escamas pardo-carne fibrosas, sin jaspeado","Sombrero del parasol con escamas pardas grandes y bastas sobre fondo claro + mamelón; sombrero de la lepiota tóxica finamente escamoso pardo-rosa carne, pequeño","La lepiota pardo-rosada contiene amatoxinas (como la oronja verde/Amanita phalloides) - mortal, ya una pequeña cantidad daña el hígado de forma irreversible"}','f'),
('parasol','lepiota_brunneoincarnata','fr','La lépiote élevée (parasol) est grande, à pied nettement chiné et anneau double coulissant ; la lépiote mortelle reste petite (moins de 5 cm) avec une surface du chapeau brun-rose chair finement squameuse et un pied non chiné.','Le parasol sent l''odeur douce de noisette ; la lépiote toxique douceâtre-fruitée - l''odeur n''est PAS un critère de séparation sûr, ne jamais s''y fier.','Parasol en lisière de forêt/prairies ; la lépiote toxique dans les endroits chauds, sablo-herbeux, parcs et bords de chemins - chevauchement possible.','Tous deux ont une sporée BLANCHE - la sporée ne les sépare PAS, il faut donc impérativement vérifier la taille, le chinage du pied et l''anneau double coulissant.','N''accepter une lépiote comme parasol que si le chapeau mesure nettement plus de 10 cm ET que le pied est chiné ET que l''anneau est double et coulissant - ne JAMAIS manger par principe les petites lépiotes de moins de 8-10 cm.','{"Le parasol est grand : chapeau 10-30 cm ; la lépiote brun-incarnat est petite : chapeau seulement 2-5 cm - la TAILLE est le premier signal d''alarme","Le parasol a un anneau DOUBLE, librement coulissant sur le pied ; la lépiote toxique n''a qu''une zone annulaire fugace, fibreuse, NON coulissante","Pied du parasol nettement chiné (bandé comme une peau de serpent) ; pied de la lépiote toxique à ceintures de squames brun-chair fibreuses, sans chinage","Chapeau du parasol à grandes squames brunes grossières sur fond clair + mamelon ; chapeau de la lépiote toxique finement squameux brun-rose chair, petit","La lépiote brun-incarnat contient des amatoxines (comme l''amanite phalloïde) - mortelle, une petite quantité suffit à léser le foie de façon irréversible"}','f'),
('parasol','lepiota_brunneoincarnata','it','La mazza di tamburo (parasol) è grande con gambo nettamente zebrato e anello doppio scorrevole; la lepiota mortale resta piccola (sotto i 5 cm) con superficie del cappello bruno-rosa carne finemente squamosa e gambo non zebrato.','Il parasol odora di nocciola dolce; la lepiota tossica dolciastro-fruttato - l''odore NON è un criterio di separazione sicuro, non fidarsene mai.','Parasol ai margini dei boschi/prati; la lepiota tossica in luoghi caldi, sabbioso-erbosi, parchi e bordi di sentieri - sovrapposizione possibile.','Entrambi hanno sporata BIANCA - la sporata NON li distingue, quindi verificare obbligatoriamente la dimensione, la zebratura del gambo e l''anello doppio scorrevole.','Accettare una lepiota come parasol solo se il cappello misura nettamente più di 10 cm E il gambo è zebrato E l''anello è doppio e scorrevole - per principio non mangiare MAI le piccole lepiote sotto gli 8-10 cm.','{"Il parasol è grande: cappello 10-30 cm; la lepiota bruno-incarnata è piccola: cappello solo 2-5 cm - la DIMENSIONE è il primo segnale d''allarme","Il parasol ha un anello DOPPIO, liberamente scorrevole sul gambo; la lepiota tossica ha solo una zona anulare fugace, fibrosa, NON scorrevole","Gambo del parasol nettamente zebrato (fasciato come pelle di serpente); gambo della lepiota tossica con cinture di squame bruno-carne fibrose, senza zebratura","Cappello del parasol con grandi squame brune grossolane su fondo chiaro + umbone; cappello della lepiota tossica finemente squamoso bruno-rosa carne, piccolo","La lepiota bruno-incarnata contiene amatossine (come l''amanita falloide) - mortale, già una piccola quantità danneggia il fegato in modo irreversibile"}','f'),
('pluteus_cervinus','megacollybia_platyphylla','en','Deer shield with pink gills (when mature) and free gill attachment ; the broad-gilled fungus with white, broad, adnate gills and white rhizomorphs at the base.','Both inconspicuously mushroomy, not a distinguishing feature.','Both on/in rotten deciduous wood ; the broad-gilled fungus with conspicuous white mycelial cords at the stem foot.','Deer shield pink, broad-gilled fungus white — THE decisive distinguishing feature.','Make a spore print : pink = deer shield, white = broad-gilled fungus. The broad-gilled fungus is regarded as toxic/indigestible (gastrointestinal) and does not belong in the basket.','{"Deer shield (edible) has PINK spore print and, when old, pink gills, free at the stem ; the broad-gilled fungus has WHITE spore print and white gills adnate to the stem","The broad-gilled fungus with conspicuous coarse white rhizomorphs (mycelial cords) at the stem base ; the deer shield without such cords","Gills of the broad-gilled fungus very broad and distant ; deer shield more crowded","The deer shield mostly grows singly on wood, the broad-gilled fungus on wood/roots with cords"}','f'),
('pluteus_cervinus','megacollybia_platyphylla','es','Plúteo con láminas rosas (al madurar) y inserción libre de las láminas ; la colibia de láminas anchas con láminas blancas, anchas, adnatas y rizomorfos blancos en la base.','Ambos inodoros-fúngicos, no es un criterio de distinción.','Ambos sobre/en madera caduca podrida ; la colibia de láminas anchas con llamativos cordones miceliares blancos en el pie.','Plúteo rosa, colibia de láminas anchas blanco — EL criterio de distinción decisivo.','Hacer una esporada : rosa = plúteo, blanco = colibia de láminas anchas. La colibia de láminas anchas se considera tóxica/indigesta (gastrointestinal) y no debe ir al cesto.','{"Plúteo color corzo (comestible) tiene esporada ROSA y, con la edad, láminas rosas, libres en el pie ; la colibia de láminas anchas tiene esporada BLANCA y láminas blancas, adnatas al pie","La colibia de láminas anchas con llamativos rizomorfos blancos gruesos (cordones miceliares) en la base del pie ; el plúteo sin tales cordones","Láminas de la colibia de láminas anchas muy anchas y separadas ; plúteo más apretado","El plúteo crece la mayoría de las veces solitario sobre madera, la colibia de láminas anchas sobre madera/raíces con cordones"}','f'),
('pluteus_cervinus','megacollybia_platyphylla','fr','Plutée brun de cerf à lamelles roses (mûres) et insertion libre des lamelles ; mégacollybie à lamelles blanches, larges, adnées et rhizomorphes blancs à la base.','Les deux discrets-fongiques, pas un critère de séparation.','Les deux sur/dans le bois de feuillus pourri ; la mégacollybie avec des cordons mycéliens blancs remarquables au pied.','Plutée rose, mégacollybie blanche — LE critère de séparation décisif.','Faire une sporée : rose = plutée, blanche = mégacollybie. La mégacollybie est considérée comme toxique/indigeste (gastro-intestinal) et n''a pas sa place dans le panier.','{"Plutée brun de cerf (comestible) a une sporée ROSE et avec l''âge des lamelles roses, libres au pied ; mégacollybie a une sporée BLANCHE et des lamelles blanches, adnées au pied","Mégacollybie avec des rhizomorphes blancs grossiers remarquables (cordons mycéliens) à la base du pied ; plutée sans de tels cordons","Lamelles de la mégacollybie très larges et espacées ; plutée plus serrées","Plutée pousse le plus souvent isolé sur bois, mégacollybie sur bois/racines avec des cordons"}','f'),
('pluteus_cervinus','megacollybia_platyphylla','it','Pluteo con lamelle rosa (a maturità) e attacco libero delle lamelle ; la collibia a lamelle larghe con lamelle bianche, larghe, adnate e rizomorfe bianche alla base.','Entrambi inodori-fungini, non un criterio di distinzione.','Entrambi su/in legno di latifoglie marcio ; la collibia a lamelle larghe con evidenti cordoni miceliari bianchi al piede.','Pluteo rosa, collibia a lamelle larghe bianco — IL criterio di distinzione decisivo.','Fare una sporata : rosa = pluteo, bianco = collibia a lamelle larghe. La collibia a lamelle larghe è considerata tossica/indigesta (disturbi gastrointestinali) e non va nel cestino.','{"Pluteo color cerbiatto (commestibile) ha sporata ROSA e, con l''età, lamelle rosa, libere al gambo ; la collibia a lamelle larghe ha sporata BIANCA e lamelle bianche, adnate al gambo","La collibia a lamelle larghe con evidenti rizomorfe bianche grossolane (cordoni miceliari) alla base del gambo ; il pluteo senza tali cordoni","Lamelle della collibia a lamelle larghe molto larghe e distanziate ; pluteo più fitto","Il pluteo cresce per lo più isolato su legno, la collibia a lamelle larghe su legno/radici con cordoni"}','f'),
('pluteus_cervinus','pluteus_salicinus','en','Both have free, flesh-pink gills on dead wood ; the decisive feature is the grey-greenish hue and the possible blue-green discolouration at pressure/cut points of the toxic willow shield, as opposed to the deer-brown, non-bluing edible.','Deer shield mildly radish-/earthy-smelling ; willow shield faintly radish-like — smell does not separate reliably.','Both grow on rotten deciduous wood/dead wood ; the willow shield prefers willows/poplars/alders (floodplain forest), overlap with the deer shield possible.','Both have a pink spore print — identical, therefore not a distinguishing feature ; watch the colour and the blue discolouration.','Leave shields with a grey-greenish cap or blue-green discolouration at cut/pressure points — psychoactive and toxic.','{"Deer shield : warm deer-brown to dark-brown, often radially fibrillose cap ; willow shield paler grey to grey-greenish/bluish-grey, darker towards the cap centre.","The willow shield often discolours bluish-greenish on injury/pressure (especially the stem base) — psilocybin indicator ; the deer shield does not blue.","Both have free gills, white when young, turning flesh-pink through the pink spore print — NOT a distinguishing feature.","The willow shield is usually smaller and more slender than the often sturdy deer shield ; grows preferentially on willow/poplar/alder.","The willow shield contains psilocybin/psilocin and is toxic (psychoactive)."}','f'),
('pluteus_cervinus','pluteus_salicinus','es','Ambos tienen láminas libres, rosa carne, sobre madera muerta ; el elemento decisivo es el tono gris-verdoso y el posible viraje azul-verde en los puntos de presión/corte del plúteo gris-verde tóxico, frente al comestible color corzo que no vira al azul.','Plúteo color corzo suavemente rabanoso/terroso ; plúteo gris-verde débilmente rabanoso — el olor no separa de forma fiable.','Ambos crecen sobre madera caduca podrida/madera muerta ; el gris-verde prefiere sauces/álamos/alisos (bosque de ribera), solapamiento con el color corzo posible.','Ambos tienen esporada rosa — idéntica, por lo que no es un criterio de distinción ; prestar atención al color y al viraje azul.','Dejar en el sitio los plúteos con sombrero gris-verdoso o con viraje azul-verde en los puntos de corte/presión — psicoactivo y tóxico.','{"Plúteo color corzo : sombrero pardo-corzo cálido a pardo oscuro, a menudo radialmente fibriloso ; plúteo gris-verde más pálido gris a gris-verdoso/azul-grisáceo, más oscuro hacia el centro del sombrero.","El plúteo gris-verde vira a menudo a azulado-verdoso al herirlo/presionarlo (sobre todo la base del pie) — indicio de psilocibina ; el plúteo color corzo no vira al azul.","Ambos tienen láminas libres, blancas de jóvenes, que se vuelven rosa carne por la esporada rosa — NO es un criterio de distinción.","El plúteo gris-verde es generalmente más pequeño y grácil que el plúteo color corzo a menudo robusto ; crece de preferencia sobre sauce/álamo/aliso.","El plúteo gris-verde contiene psilocibina/psilocina y es tóxico (psicoactivo)."}','f'),
('pluteus_cervinus','pluteus_salicinus','fr','Les deux ont des lames libres, rose chair, sur bois mort ; l''élément décisif est la teinte gris-verdâtre et le possible bleuissement vert-bleu aux points de pression/coupure du plutée gris-vert toxique, par opposition au comestible couleur de chevreuil qui ne bleuit pas.','Plutée couleur de chevreuil doucement raviforme/terreux ; plutée gris-vert faiblement raviforme — l''odeur ne sépare pas de façon fiable.','Les deux poussent sur bois feuillu pourri/bois mort ; le gris-vert préfère saules/peupliers/aulnes (forêt alluviale), chevauchement avec le couleur de chevreuil possible.','Les deux ont une sporée rose — identique, donc pas un critère de distinction ; faire attention à la couleur et au bleuissement.','Laisser sur place les plutées à chapeau gris-verdâtre ou à bleuissement vert-bleu aux points de coupure/pression — psychoactif et toxique.','{"Plutée couleur de chevreuil : chapeau brun-chevreuil chaud à brun foncé, souvent radialement fibrilleux ; plutée gris-vert plus pâle gris à gris-verdâtre/bleu-gris, plus foncé vers le centre du chapeau.","Le plutée gris-vert se colore souvent en bleu-vert à la blessure/pression (surtout la base du pied) — indice de psilocybine ; le plutée couleur de chevreuil ne bleuit pas.","Les deux ont des lames libres, blanches jeunes, devenant rose chair par la sporée rose — PAS un critère de distinction.","Le plutée gris-vert est généralement plus petit et plus gracile que le plutée couleur de chevreuil souvent robuste ; pousse de préférence sur saule/peuplier/aulne.","Le plutée gris-vert contient de la psilocybine/psilocine et est toxique (psychoactif)."}','f'),
('pluteus_cervinus','pluteus_salicinus','it','Entrambi hanno lamelle libere, rosa carne, su legno morto ; l''elemento decisivo è la tonalità grigio-verdastra e il possibile viraggio blu-verde nei punti di pressione/taglio del pluteo grigio-verde tossico, rispetto al commestibile color cerbiatto che non vira al blu.','Pluteo color cerbiatto delicatamente rafanoide/terroso ; pluteo grigio-verde debolmente rafanoide — l''odore non separa in modo affidabile.','Entrambi crescono su legno di latifoglie marcio/legno morto ; il grigio-verde preferisce salici/pioppi/ontani (foresta golenale), sovrapposizione col color cerbiatto possibile.','Entrambi hanno sporata rosa — identica, quindi non un criterio di distinzione ; fare attenzione al colore e al viraggio blu.','Lasciare sul posto i plutei con cappello grigio-verdastro o con viraggio blu-verde nei punti di taglio/pressione — psicoattivo e tossico.','{"Pluteo color cerbiatto : cappello bruno-cerbiatto caldo o bruno scuro, spesso radialmente fibrilloso ; pluteo grigio-verde più pallido grigio o grigio-verdastro/azzurro-grigio, più scuro verso il centro del cappello.","Il pluteo grigio-verde vira spesso al bluastro-verdastro alla lesione/pressione (soprattutto la base del gambo) — indizio di psilocibina ; il pluteo color cerbiatto non vira al blu.","Entrambi hanno lamelle libere, bianche da giovani, che diventano rosa carne per la sporata rosa — NON un criterio di distinzione.","Il pluteo grigio-verde è generalmente più piccolo e più gracile del pluteo color cerbiatto spesso robusto ; cresce di preferenza su salice/pioppo/ontano.","Il pluteo grigio-verde contiene psilocibina/psilocina ed è tossico (psicoattivo)."}','f'),
('ramaria_botrytis','ramaria_formosa','en','Rosso coral / cauliflower coral: fleshy white stem, whitish/buff branches with wine-red/pinkish tips; the beautiful coral (Ramaria formosa) is uniformly orange-salmon with yellow tips and lacks a thick white stem.','Both mild and mushroomy; smell does not distinguish them — watch for the bitter taste of Ramaria formosa.','Both grow on the ground in woodland; Ramaria formosa prefers deciduous forest (often beech), the cauliflower coral deciduous/mixed forest — habitat does not distinguish them.','Both have ochre-yellowish spore print — no practical distinguishing feature; rely on colour, stem shape, colour change and taste.','Never eat corals with an orange body, yellow tips, wine-red bruising on pressure or a bitter taste — only corals with pure white flesh and a mild taste are considered suitable for beginners.','{"Cauliflower coral (Ramaria botrytis): thick, squat whitish stem with cauliflower-like branched arms whose tips are coloured wine-red/purple-pink; Ramaria formosa is overall pale orange-salmon with yellow branch tips.","Ramaria formosa often bruises brownish-wine-red on pressure/injury; the flesh of the cauliflower coral stays white or hardly changes colour.","Ramaria formosa tastes bitter (spit out the taste sample!), cauliflower coral is mild.","Ramaria formosa has thinner, orange-salmon branches with yellow tips; the cauliflower coral has a massive white basal stem and wine-red tones only at the branch tips.","Ramaria formosa is gastrointestinally poisonous (nausea, vomiting, diarrhoea, cramps)."}','f'),
('ramaria_botrytis','ramaria_formosa','es','Ramaria botrytis (coliflor): pie carnoso blanco, ramas blanquecinas/ante con puntas rojo-vino/rosadas; la Ramaria formosa es enteramente naranja-salmón con puntas amarillas y sin pie blanco grueso.','Ambas con olor suave a hongo; el olor no las distingue — atender al sabor amargo de la Ramaria formosa.','Ambas crecen en el suelo del bosque; la Ramaria formosa prefiere el bosque de frondosas (a menudo haya), la Ramaria botrytis el bosque de frondosas/mixto — el hábitat no las distingue.','Ambas con esporada amarillo-ocre — sin criterio distintivo práctico; basarse en color, forma del pie, viraje de color y sabor.','Nunca comer ramarias con cuerpo naranja, puntas amarillas, viraje rojo-vino a la presión o sabor amargo — solo las ramarias con carne blanco puro y sabor suave se consideran aptas para principiantes.','{"Ramaria botrytis: pie blanquecino grueso y rechoncho con ramas ramificadas como coliflor cuyas puntas están coloreadas de rojo-vino/púrpura-rosado; la Ramaria formosa en conjunto naranja-salmón pálido con puntas de las ramas amarillas.","La Ramaria formosa vira a menudo al pardusco-rojo-vino a la presión/lesión; la carne de la Ramaria botrytis permanece blanca o apenas vira.","La Ramaria formosa sabe amarga (¡escupir la prueba de sabor!), la Ramaria botrytis es suave.","La Ramaria formosa tiene ramas más finas, naranja-salmón, con puntas amarillas; la Ramaria botrytis tiene un pie basal blanco macizo y tonos rojo-vino solo en las puntas de las ramas.","La Ramaria formosa es tóxica para el aparato gastrointestinal (náuseas, vómitos, diarrea, cólicos)."}','f'),
('ramaria_botrytis','ramaria_formosa','fr','Clavaire chou-fleur : pied charnu blanc, rameaux blanchâtres/chamois à pointes lie-de-vin/rosées ; la Clavaire jolie est entièrement orange-saumon avec des pointes jaunes et sans gros pied blanc.','Toutes deux à odeur douce de champignon ; l''odeur ne distingue pas — prêter attention au goût amer de la Clavaire jolie.','Toutes deux poussent au sol en forêt ; la Clavaire jolie préfère la forêt de feuillus (souvent hêtre), la Clavaire chou-fleur la forêt de feuillus/mixte — l''habitat ne distingue pas.','Toutes deux à sporée jaune ocre — pas de critère de distinction pratique ; se fier à la couleur, à la forme du pied, au changement de couleur et au goût.','Ne jamais manger une clavaire à corps orange, à pointes jaunes, à virage lie-de-vin à la pression ou au goût amer — seules les clavaires à chair d''un blanc pur et au goût doux sont considérées comme adaptées aux débutants.','{"Clavaire chou-fleur (Ramaria botrytis) : pied blanchâtre épais et trapu avec des rameaux ramifiés en chou-fleur dont les pointes sont colorées en lie-de-vin/pourpre-rosé ; la Clavaire jolie est dans l''ensemble d''un orange-saumon pâle avec des pointes de rameaux jaunes.","La Clavaire jolie vire souvent au brunâtre-lie-de-vin à la pression/blessure ; la chair de la Clavaire chou-fleur reste blanche ou ne change presque pas de couleur.","La Clavaire jolie a un goût amer (recracher la prise de goût !), la Clavaire chou-fleur est douce.","La Clavaire jolie a des rameaux plus fins, orange-saumon, à pointes jaunes ; la Clavaire chou-fleur a un pied de base blanc massif et des tons lie-de-vin seulement aux pointes des rameaux.","La Clavaire jolie est toxique pour l''appareil gastro-intestinal (nausées, vomissements, diarrhée, coliques)."}','f'),
('ramaria_botrytis','ramaria_formosa','it','Ramaria botrytis : gambo carnoso bianco, rami biancastri/camoscio con apici rosso-vinato/rosati ; la Ramaria formosa è interamente arancio-salmone con apici gialli e senza grosso gambo bianco.','Entrambe con odore mite di fungo ; l''odore non distingue — fare attenzione al sapore amaro della Ramaria formosa.','Entrambe crescono al suolo nel bosco ; la Ramaria formosa predilige il bosco di latifoglie (spesso faggio), la Ramaria botrytis il bosco di latifoglie/misto — l''habitat non distingue.','Entrambe con sporata giallo-ocra — nessun criterio distintivo pratico ; basarsi su colore, forma del gambo, viraggio e sapore.','Non mangiare mai ramarie con corpo arancione, apici gialli, viraggio vinato alla pressione o sapore amaro — solo le ramarie con carne bianco puro e sapore mite sono considerate adatte ai principianti.','{"Ramaria botrytis : gambo biancastro spesso e tozzo con rami ramificati a cavolfiore le cui punte sono colorate di rosso-vinato/porpora-rosato ; la Ramaria formosa nel complesso arancio-salmone pallido con apici dei rami gialli.","La Ramaria formosa vira spesso al brunastro-vinato alla pressione/lesione ; la carne della Ramaria botrytis resta bianca ovvero quasi non vira.","La Ramaria formosa ha sapore amaro (sputare la prova di assaggio !), la Ramaria botrytis è mite.","La Ramaria formosa ha rami più sottili, arancio-salmone, con apici gialli ; la Ramaria botrytis ha un massiccio gambo basale bianco e toni vinati solo alle punte dei rami.","La Ramaria formosa è tossica per l''apparato gastro-intestinale (nausea, vomito, diarrea, coliche)."}','f'),
('rhodocollybia_butyracea','gymnopus_peronatus','en','The buttery collybia has a greasy-glossy, hygrophanous zonally fading cap; the wood woollyfoot (Gymnopus peronatus) a matt, uniformly leather-brown cap with a felted stem base.','Both inconspicuous; the acrid-burning taste (taste sample) is the reliable distinguishing feature.','Both in conifer/deciduous woodland litter, often in troops — habitat does not distinguish.','Buttery collybia with cream spore print, often with a faint pink tone; wood woollyfoot whitish-cream — only faintly distinguishable in the spore print.','Bite test: if it burns acridly, leave it. The greasy-slimy, mild-tasting cap is the buttery collybia — nevertheless only collect it when identification is certain.','{"Wood woollyfoot: acrid-burning taste, tough stem with strigose-felted base, matt leather-brown cap","Buttery collybia: mild taste, greasy-smooth/''buttery'' glossy slimy cap, hygrophanous, longitudinally grooved-cartilaginous stem without strigose felt","The buttery collybia has a pale, often faintly pink-tinged spore print (Rhodocollybia) and a softer consistency; the wood woollyfoot has a cream-white spore print and is tough-leathery","Wood woollyfoot acrid/suspected toxic-stomach-irritating — buttery collybia mild, edible (gastronomically little esteemed)"}','f'),
('rhodocollybia_butyracea','gymnopus_peronatus','es','La colibia mantecosa tiene un sombrero graso-brillante, higrófano que se decolora por zonas; la colibia ardiente (Gymnopus peronatus) un sombrero mate, uniformemente pardo-cuero, con base del pie afieltrada.','Ambas discretas; el sabor acre-ardiente (prueba de sabor) es el carácter distintivo seguro.','Ambas en la hojarasca de bosque de coníferas/frondosas, a menudo en grupos — el hábitat no distingue.','Colibia mantecosa con esporada color crema, a menudo con tono rosado débil; colibia ardiente blanquecino-crema — distinguibles solo débilmente en la esporada.','Prueba de mordisco: si arde acremente, dejarla en el sitio. El sombrero graso-viscoso de sabor suave es la colibia mantecosa — recogerla no obstante solo con determinación segura.','{"Colibia ardiente: sabor acre-ardiente, pie tenaz con base estrigosa-afieltrada, sombrero mate pardo-cuero","Colibia mantecosa: sabor suave, sombrero graso-liso/''mantecoso'' brillante y viscoso, higrófano, pie longitudinalmente estriado-cartilaginoso sin fieltro estrigoso","La colibia mantecosa tiene esporada pálida, a menudo débilmente teñida de rosa (Rhodocollybia) y consistencia más blanda; la colibia ardiente con esporada blanco-crema y tenaz-coriácea","Colibia ardiente acre/sospechosa de toxicidad-irritante para el estómago — colibia mantecosa suave, comestible (gastronómicamente poco apreciada)"}','f'),
('rhodocollybia_butyracea','gymnopus_peronatus','fr','Le collybie beurré a un chapeau gras-brillant, hygrophane se décolorant en zones ; le collybie à pied feutré un chapeau mat, uniformément brun-cuir avec une base du pied feutrée.','Les deux discrets ; le goût brûlant-âcre (échantillon) est le critère de séparation sûr.','Les deux dans la litière de forêt de conifères/feuillus, souvent en troupe – l''habitat ne sépare pas.','Collybie beurré crème, souvent avec une faible teinte rose ; collybie à pied feutré blanchâtre-crème – distinguable seulement faiblement à la sporée.','Test de morsure : si cela brûle âcrement, laisser. Pour le chapeau gras-graisseux, doux au goût, il s''agit du collybie beurré – néanmoins ne récolter qu''avec une détermination sûre.','{"Collybie à pied feutré : goût âcre-brûlant, pied coriace avec une base strigueuse-feutrée, chapeau mat brun-cuir","Collybie beurré : goût doux, chapeau gras-lisse/« beurré » graisseux brillant, hygrophane, pied longitudinalement rainuré-cartilagineux sans feutre strigueux","Collybie beurré a une sporée pâle, souvent faiblement teintée de rose (Rhodocollybia) et une consistance plus molle ; collybie à pied feutré à sporée crème-blanche et coriace-cuir","Collybie à pied feutré âcre/suspect de toxicité-irritant pour l''estomac – collybie beurré doux, comestible (peu apprécié gustativement)"}','f'),
('rhodocollybia_butyracea','gymnopus_peronatus','it','Il Rhodocollybia butyracea ha un cappello grasso-lucente, igrofano che sbiadisce a zone ; il Gymnopus peronatus un cappello opaco, uniformemente bruno-cuoio, con base del gambo feltrata.','Entrambi poco appariscenti ; il sapore acre-bruciante (prova di assaggio) è il sicuro carattere distintivo.','Entrambi nella lettiera di bosco di conifere/latifoglie, spesso in gruppi — l''habitat non distingue.','Rhodocollybia butyracea a sporata color crema, spesso con debole tono rosa ; Gymnopus peronatus biancastro-crema — distinguibili solo debolmente nella sporata.','Prova di morso : se brucia acremente, lasciare sul posto. Il cappello grasso-vischioso dal sapore mite è il Rhodocollybia butyracea — raccoglierlo comunque solo con determinazione sicura.','{"Gymnopus peronatus : sapore acre-bruciante, gambo tenace con base strigosa-feltrata, cappello opaco bruno-cuoio","Rhodocollybia butyracea : sapore mite, cappello grasso-liscio/''burroso'' lucente e vischioso, igrofano, gambo longitudinalmente striato-cartilagineo senza feltro strigoso","Il Rhodocollybia butyracea ha sporata pallida, spesso debolmente sfumata di rosa (Rhodocollybia) e consistenza più molle ; il Gymnopus peronatus con sporata bianco-crema e tenace-coriaceo","Gymnopus peronatus acre/sospetto di tossicità-irritante per lo stomaco — Rhodocollybia butyracea mite, commestibile (poco apprezzato gustativamente)"}','f'),
('roetling','agaricus_xanthodermus','en','Yellow-staining mushroom: cap white to chalk-white, when young spherical/hemispherical, later flattened, smooth to finely scaly; stem base in longitudinal cut IMMEDIATELY bright chrome-yellow. Sheep mushroom: cap cream-white, silky-fibrous to slightly scaly, convex to flat; yellows only weakly over the whole mushroom and without the concentrated chrome-yellow spot at the stem base.','Decisive feature: the sheep mushroom smells pleasantly of anise/marzipan. The yellow-staining mushroom smells unpleasantly of ink/carbolic/phenol (medicinal-iodine-like); the smell intensifies when rubbing the stem base and especially when heating/cooking.','Yellow-staining mushroom: gardens, parks, forest edges, compost heaps, ruderal/near-settlement areas. Sheep mushroom: fertilized meadows and pastures, especially sheep and horse pastures. Habitat alone does NOT separate them reliably (overlap possible).','In both species dark chocolate-brown to purple-brown (genus Agaricus) - NOT a distinguishing feature.','Cut the stem base lengthwise: if it turns immediately intense chrome-yellow AND the mushroom smells of ink/carbolic instead of anise, leave it - yellow-staining mushroom. Rule of thumb: any champignon with a carbolic/ink smell or a bright chrome-yellow stem base = toxic, do not eat.','{"Smell is the most important feature: sheep mushroom pleasantly of anise/marzipan; yellow-staining mushroom unpleasantly of ink/carbolic/phenol - intensifying when rubbing the stem base and when heating.","Cut the stem base lengthwise: yellow-staining mushroom discolors IMMEDIATELY intense chrome-yellow, concentrated at the stem base; sheep mushroom yellows only weakly over the whole fruiting body and not concentrated at the stem base.","Both have a ring and gills that mature from pale-pink to chocolate-brown, and both have dark-brown spore powder - therefore ONLY the stem-base cut (chrome-yellow) AND the smell test reliably separate them, not the gills or spore color."}','t'),
('roetling','agaricus_xanthodermus','es','Champiñón amarilleante (de carbol): sombrero blanco a blanco calizo, de joven globoso/hemisférico, después aplanado, liso a finamente escamoso; la base del pie, en corte longitudinal, INMEDIATAMENTE de un amarillo cromo intenso. Champiñón de oveja: sombrero blanco crema, sedoso-fibrilloso a ligeramente escamoso, convexo a plano; amarillea solo débilmente en todo el hongo y sin la mancha concentrada de amarillo cromo en la base del pie.','Rasgo decisivo: el champiñón de oveja huele agradablemente a anís/mazapán. El champiñón amarilleante (de carbol) huele desagradablemente a tinta/carbol/fenol (medicinal-yodado); el olor se intensifica al frotar la base del pie y, sobre todo, al calentar/cocinar.','Champiñón amarilleante (de carbol): jardines, parques, lindes de bosque, montones de compost, áreas ruderales/próximas a poblaciones. Champiñón de oveja: prados y pastos abonados, sobre todo pastizales de ovejas y caballos. El hábitat por sí solo NO separa con seguridad (es posible la superposición).','En ambas especies pardo chocolate oscuro a pardo púrpura (género Agaricus); NO es un rasgo distintivo.','Cortar longitudinalmente la base del pie: si se tiñe de inmediato de un amarillo cromo intenso Y el hongo huele a tinta/carbol en lugar de a anís, descartarlo: es el champiñón amarilleante (de carbol). Regla práctica: todo champiñón con olor a carbol/tinta o base del pie de amarillo cromo intenso = tóxico, no comerlo.','{"El olor es el rasgo más importante: el champiñón de oveja agradable a anís/mazapán; el champiñón amarilleante (de carbol) desagradable a tinta/carbol/fenol, intensificándose al frotar la base del pie y al calentar.","Cortar longitudinalmente la base del pie: el champiñón amarilleante (de carbol) se tiñe DE INMEDIATO de un amarillo cromo intenso, concentrado en la base del pie; el champiñón de oveja amarillea solo débilmente en todo el cuerpo fructífero y no concentrado en la base del pie.","Ambos tienen anillo y láminas que maduran de rosa pálido a pardo chocolate, y ambos tienen esporada pardo oscura; por eso SOLO el corte de la base del pie (amarillo cromo) Y la prueba del olor separan con seguridad, no las láminas ni el color de la esporada."}','t'),
('roetling','agaricus_xanthodermus','fr','Agaric jaunissant (agaric à odeur de phénol) : chapeau blanc à blanc crayeux, jeune globuleux/hémisphérique, puis aplati, lisse à finement squamuleux ; base du pied virant IMMÉDIATEMENT au jaune chrome vif en coupe longitudinale. Agaric des moutons : chapeau blanc crème, soyeux-fibrilleux à légèrement squamuleux, convexe à plan ; jaunit faiblement sur l''ensemble du champignon, sans la tache jaune chrome concentrée à la base du pied.','Caractère décisif : l''agaric des moutons sent agréablement l''anis/le massepain. L''agaric jaunissant (à odeur de phénol) sent désagréablement l''encre/le phénol (odeur médicinale-iodée) ; l''odeur se renforce au froissement de la base du pied et surtout à la chauffe/cuisson.','Agaric jaunissant (à odeur de phénol) : jardins, parcs, lisières de forêt, tas de compost, terrains rudéraux/proches des habitations. Agaric des moutons : prairies et pâturages fumés, surtout pâturages à moutons et à chevaux. L''habitat seul ne permet PAS de distinguer sûrement (recoupement possible).','Chez les deux espèces : brun chocolat foncé à brun pourpre (genre Agaricus) - PAS un critère de distinction.','Couper la base du pied dans le sens de la longueur : si elle vire aussitôt à un jaune chrome intense ET que le champignon sent l''encre/le phénol au lieu de l''anis, le laisser sur place - agaric jaunissant (à odeur de phénol). Règle empirique : tout agaric à odeur de phénol/d''encre ou à base du pied jaune chrome vif = toxique, ne pas consommer.','{"L''odeur est le critère le plus important : agaric des moutons agréablement anisé/massepain ; agaric jaunissant (à odeur de phénol) désagréablement encre/phénol - renforcé au froissement de la base du pied et à la chauffe.","Couper la base du pied dans le sens de la longueur : l''agaric jaunissant (à odeur de phénol) vire IMMÉDIATEMENT au jaune chrome intense, concentré à la base du pied ; l''agaric des moutons jaunit faiblement sur tout le carpophore et pas de façon concentrée à la base du pied.","Les deux ont un anneau et des lamelles qui mûrissent du rose pâle au brun chocolat, et les deux ont une sporée brun foncé - seuls la coupe de la base du pied (jaune chrome) ET le test olfactif distinguent de façon sûre, et non les lamelles ou la couleur de la sporée."}','t'),
('roetling','agaricus_xanthodermus','it','Prataiolo giallescente (Agaricus xanthodermus): cappello da bianco a bianco gesso, da giovane sferico/emisferico, poi appianato, liscio fino a finemente squamoso; la base del gambo, nel taglio longitudinale, vira SUBITO a giallo cromo brillante. Prataiolo (Schaf-Champignon, Agaricus arvensis): cappello bianco crema, sericeo-fibrilloso fino a leggermente squamoso, da convesso a piano; ingiallisce su tutto il fungo solo debolmente e senza la macchia concentrata di giallo cromo alla base del gambo.','Carattere decisivo: il prataiolo (Schaf-Champignon, Agaricus arvensis) ha un odore gradevole di anice/marzapane. Il prataiolo giallescente (Agaricus xanthodermus) ha un odore sgradevole di inchiostro/fenolo/carbolo (medicinale-iodato); l''odore si intensifica strofinando la base del gambo e soprattutto con il riscaldamento/la cottura.','Prataiolo giallescente (Agaricus xanthodermus): giardini, parchi, margini del bosco, cumuli di compost, superfici ruderali/vicine agli insediamenti. Prataiolo (Schaf-Champignon, Agaricus arvensis): prati e pascoli concimati, soprattutto pascoli di pecore e cavalli. L''habitat da solo NON consente una distinzione sicura (possibile sovrapposizione).','In entrambe le specie da bruno cioccolato scuro a bruno porpora (genere Agaricus) - NESSUN carattere distintivo.','Tagliare longitudinalmente la base del gambo: se vira subito a giallo cromo intenso E il fungo odora di inchiostro/carbolo invece che di anice, lasciarlo stare - prataiolo giallescente (Agaricus xanthodermus). Regola pratica: ogni prataiolo con odore di carbolo/inchiostro o con base del gambo giallo cromo brillante = tossico, non mangiare.','{"L''odore è il carattere più importante: il prataiolo (Schaf-Champignon, Agaricus arvensis) profuma gradevolmente di anice/marzapane; il prataiolo giallescente (Agaricus xanthodermus) odora sgradevolmente di inchiostro/carbolo/fenolo - si intensifica strofinando la base del gambo e con il riscaldamento.","Tagliare longitudinalmente la base del gambo: il prataiolo giallescente (Agaricus xanthodermus) vira SUBITO a giallo cromo intenso, concentrato alla base del gambo; il prataiolo (Schaf-Champignon, Agaricus arvensis) ingiallisce su tutto il carpoforo solo debolmente e non concentrato alla base del gambo.","Entrambi hanno anello e lamelle che maturano da rosa pallido a bruno cioccolato, ed entrambi hanno sporata bruno scuro - perciò distinguono con sicurezza SOLO il taglio della base del gambo (giallo cromo) E il test dell''odore, non le lamelle o il colore delle spore."}','t'),
('roetling','amanita_phalloides','en','Death cap: cap olive/yellow-greenish with ingrown radial fibers (the white form var. alba also pure white), PURE WHITE gills, bulbous stem base with a membranous sheath (volva). Sheep mushroom: cream-white cap, gills pink -> chocolate-brown, NO membranous sheath.','Sheep mushroom: pleasant anise/marzipan smell. Death cap: when young sweetish-honey-like, with age unpleasant - NO anise.','Amanita phalloides: mycorrhizal mushroom predominantly with oaks and beeches in the forest. Sheep mushroom: free-standing on meadows and pastures without tree association. Habitat alone is NOT a reliable feature.','DECISIVE: sheep mushroom dark chocolate-brown to purple-brown; Amanita phalloides PURE WHITE. White spore deposit = never eat.','Never collect young, still-closed white ''champignons'' with pale gills - precisely in the button stage the deadly death cap looks most similar to the champignon. Dig up the entire stem base (volva present?) and treat pure-white gills as well as a white spore deposit as an absolute stop signal.','{"Gills: the death cap always has PURE WHITE gills; champignon gills are pale-pink when young (very young buttons exceptionally cream-white) and mature via gray-pink to chocolate-brown. In the button stage do not trust gill color alone - then volva + spore deposit are mandatory.","Stem base: distinctly set-off bulb with a membranous sheath (volva) in the death cap; the champignon lacks the volva. Always dig up the stem base completely.","Do NOT use cap color as the main feature: typically olive/yellow-green, but as var. alba also pure white - therefore always check gills + volva + spore powder, never just the color.","Spore powder white (champignon dark brown) - the most reliable single feature."}','t'),
('roetling','amanita_phalloides','es','Oronja verde (cicuta verde): sombrero verde oliva/amarillo-verdoso con fibras radiales incrustadas (la forma blanca var. alba también puede ser blanca pura), láminas BLANCO PURO, base del pie bulbosa con vaina membranosa (volva). Champiñón de oveja: sombrero blanco crema, láminas de rosa -> pardo chocolate, SIN vaina membranosa.','Champiñón de oveja: olor agradable a anís/mazapán. Oronja verde (cicuta verde): de joven dulzón-amelado, en la vejez desagradable; NADA de anís.','Amanita phalloides: hongo micorrízico predominantemente bajo robles y hayas en el bosque. Champiñón de oveja: aislado en prados y pastos sin asociación a árboles. El hábitat por sí solo NO es un rasgo seguro.','DECISIVO: champiñón de oveja pardo chocolate oscuro a pardo púrpura; Amanita phalloides BLANCO PURO. Esporada blanca = nunca comer.','No recoger nunca ''champiñones'' blancos jóvenes, aún cerrados, con láminas claras: precisamente en estado de botón el mortal Amanita phalloides es el que más se parece al champiñón. Desenterrar por completo la base del pie (¿hay volva?) y considerar las láminas blanco puro y la esporada blanca como señal de parada absoluta.','{"Láminas: la oronja verde (cicuta verde) tiene siempre láminas BLANCO PURO; las láminas del champiñón son de joven rosa pálido (los botones muy jóvenes excepcionalmente blanco crema) y maduran pasando por gris rosado hasta pardo chocolate. En estado de botón no fiarse solo del color de las láminas: entonces volva + esporada son obligatorios.","Base del pie: bulbo claramente diferenciado con vaina membranosa (volva) en la cicuta verde; en el champiñón falta la volva. Desenterrar siempre por completo la base del pie.","No usar el color del sombrero como rasgo principal: típicamente verde oliva/amarillo-verdoso, pero como var. alba también blanco puro; por eso comprobar siempre láminas + volva + esporada, nunca solo el color.","Esporada blanca (champiñón pardo oscuro): el rasgo individual más fiable."}','t'),
('roetling','amanita_phalloides','fr','Amanite phalloïde (amanite verte) : chapeau vert olive/vert jaunâtre avec des fibrilles radiales incrustées (la forme blanche var. alba également entièrement blanche), lamelles BLANC PUR, base du pied bulbeuse avec une volve membraneuse. Agaric des moutons : chapeau blanc crème, lamelles roses -> brun chocolat, PAS de volve membraneuse.','Agaric des moutons : odeur agréable d''anis/de massepain. Amanite phalloïde (amanite verte) : jeune, odeur douceâtre-mielleuse, désagréable avec l''âge - PAS d''anis.','Amanita phalloides : champignon mycorhizien surtout sous les chênes et les hêtres en forêt. Agaric des moutons : isolé sur prairies et pâturages, sans lien avec les arbres. L''habitat seul n''est PAS un critère fiable.','DÉCISIF : agaric des moutons brun chocolat foncé à brun pourpre ; Amanita phalloides BLANC PUR. Sporée blanche = ne jamais consommer.','Ne jamais récolter de ''champignons'' blancs jeunes, encore fermés, à lamelles claires - c''est précisément au stade bouton que la mortelle amanite phalloïde ressemble le plus à l''agaric. Déterrer entièrement la base du pied (volve présente ?) et considérer des lamelles blanc pur ainsi qu''une sporée blanche comme un signal d''arrêt absolu.','{"Lamelles : l''amanite phalloïde (amanite verte) a toujours des lamelles BLANC PUR ; les lamelles de l''agaric sont jeunes rose pâle (les très jeunes boutons exceptionnellement blanc crème) et mûrissent en passant par le gris-rose jusqu''au brun chocolat. Au stade bouton, ne pas se fier à la seule couleur des lamelles - alors la volve + la sporée sont impératives.","Base du pied : bulbe nettement détaché avec volve membraneuse chez l''amanite phalloïde ; chez l''agaric, la volve est absente. Toujours déterrer entièrement la base du pied.","Ne PAS utiliser la couleur du chapeau comme critère principal : typiquement vert olive/vert jaunâtre, mais aussi entièrement blanc en var. alba - donc toujours vérifier lamelles + volve + sporée, jamais la seule couleur.","Sporée blanche (agaric brun foncé) - le critère isolé le plus fiable."}','t'),
('roetling','amanita_phalloides','it','Tignosa verdognola/falloide (Amanita phalloides): cappello da verde oliva/giallo-verdognolo con fibrille radiali innate (la forma bianca var. alba anche bianca pura), lamelle BIANCHE PURE, base del gambo bulbosa con guaina membranosa (volva). Prataiolo (Schaf-Champignon, Agaricus arvensis): cappello bianco crema, lamelle da rosa -> bruno cioccolato, NESSUNA guaina membranosa.','Prataiolo (Schaf-Champignon, Agaricus arvensis): gradevole odore di anice/marzapane. Tignosa verdognola/falloide (Amanita phalloides): da giovane dolciastro-mielato, da vecchio sgradevole - NESSUN anice.','Amanita phalloides: fungo micorrizico prevalentemente presso querce e faggi nel bosco. Prataiolo (Schaf-Champignon, Agaricus arvensis): isolato su prati e pascoli senza legame con gli alberi. L''habitat da solo NON è un carattere sicuro.','DECISIVO: il prataiolo (Schaf-Champignon, Agaricus arvensis) da bruno cioccolato scuro a bruno porpora; Amanita phalloides BIANCA PURA. Sporata bianca = non mangiare mai.','Non raccogliere mai ''prataioli'' giovani, ancora chiusi, bianchi e con lamelle chiare - proprio allo stadio di bottone la mortale tignosa falloide somiglia di più al prataiolo. Dissotterrare completamente la base del gambo (volva presente?) e considerare le lamelle bianche pure e la sporata bianca come segnale di stop assoluto.','{"Lamelle: la tignosa verdognola/falloide (Amanita phalloides) ha sempre lamelle BIANCHE PURE; le lamelle del prataiolo sono da giovani rosa pallido (i bottoni molto giovani eccezionalmente bianco-crema) e maturano attraverso il grigio-rosa fino al bruno cioccolato. Allo stadio di bottone non fidarsi del solo colore delle lamelle - allora volva + sporata obbligatori.","Base del gambo: bulbo nettamente distinto con guaina membranosa (volva) nella tignosa falloide; nel prataiolo manca la volva. Dissotterrare sempre completamente la base del gambo.","NON usare il colore del cappello come carattere principale: tipicamente verde oliva/giallo-verdognolo, ma come var. alba anche bianco puro - perciò controllare sempre lamelle + volva + sporata, mai solo il colore.","Sporata bianca (prataiolo bruno scuro) - il carattere singolo più affidabile."}','t'),
('roetling','amanita_verna','en','Spring destroying angel (Amanita verna): pure white cap, PURE WHITE gills (even when old), stem base with a bulbous, membranous, sack-like sheath (volva), often deep in the soil. Sheep mushroom (field/horse champignon): cream-white cap, gills mature pink -> grey-pink -> chocolate brown, NO volva, at most a slightly thickened stem base.','Sheep mushroom: pleasant anise/marzipan smell. Amanita verna: nearly odorless to faintly sweetish/honey-like, unpleasant when old - NO anise.','Amanita verna: mycorrhizal fungus, grows in woodland (deciduous/mixed forest), mainly in spring, with a tree association. Sheep mushroom: saprotrophic on open meadows and pastures without a tree association. Caution: habitat alone is NOT a reliable feature.','DECISIVE and 100% reliable: sheep mushroom dark chocolate brown to purple-brown; Amanita verna PURE WHITE. With a white spore print NEVER eat it as a champignon.','With every white ''champignon'' ALWAYS fully dig out and expose the stem base: if a bulbous membranous sheath (volva) is found OR the gills stay pure white - life-threatening, leave it standing. When in doubt make a spore print: white = death cap (Knollenblätterpilz), never eat. Do not even collect young, closed white buttons in the first place.','{"Gills: Amanita verna has pure white gills at EVERY age; the sheep mushroom has them pale-pink when young (very young buttons can be cream-white!), later grey-pink to chocolate brown. IMPORTANT: In the button stage the gill color alone is NOT reliable - then you must check volva + spore print.","Stem base: Amanita verna has a distinctly set-off bulb with a membranous, sack-like sheath (volva); the champignon has NO volva. Always dig out the stem base completely as well - the volva often sits deep in the soil.","Spore powder: champignon dark brown, Amanita verna pure WHITE - the spore print is the most reliable single feature.","Smell: sheep mushroom smells of anise; Amanita verna without anise smell (neutral to sweetish-honey-like) - a missing anise smell is a warning sign, but NEVER replaces the volva/spore check."}','t'),
('roetling','amanita_verna','es','Amanita verna (oronja mortal de primavera): sombrero blanco puro, láminas BLANCO PURO (también en la vejez), base del pie con una vaina (volva) bulbosa, membranosa y en forma de saco, a menudo hundida profundamente en la tierra. Champiñón de oveja: sombrero blanco cremoso, láminas que maduran de rosa -> gris-rosado -> marrón chocolate, SIN volva, a lo sumo con la base del pie ligeramente engrosada.','Champiñón de oveja: agradable olor a anís/mazapán. Amanita verna: casi inodora a ligeramente dulzona/melosa, desagradable en la vejez - SIN anís.','Amanita verna: hongo micorrízico, crece en el bosque (bosque caducifolio/mixto), sobre todo en primavera, ligado a árboles. Champiñón de oveja: saprótrofo en prados y pastizales abiertos sin ligazón a árboles. Atención: el hábitat por sí solo NO es un criterio seguro.','DECISIVO y fiable al 100 %: el champiñón de oveja es de un marrón chocolate oscuro a marrón purpúreo; Amanita verna es BLANCO PURO. Ante una esporada blanca, NUNCA comerlo como champiñón.','Ante cualquier ''champiñón'' blanco, desentierra y deja al descubierto SIEMPRE la base del pie por completo: si aparece una vaina membranosa bulbosa (volva) O si las láminas permanecen blanco puro - es peligroso para la vida, déjalo en su sitio. En caso de duda, haz una esporada: blanca = oronja mortal, no comer nunca. No recolectar siquiera los botones blancos jóvenes y cerrados.','{"Láminas: Amanita verna tiene a CUALQUIER edad láminas blanco puro; el champiñón de oveja las tiene de joven rosa pálido (¡los botones muy jóvenes pueden ser blanco crema!), más tarde de gris-rosado a marrón chocolate. IMPORTANTE: en el estadio de botón el color de las láminas por sí solo NO es seguro - entonces hay que comprobar obligatoriamente la volva + la esporada.","Base del pie: Amanita verna tiene un bulbo claramente diferenciado con una vaina membranosa en forma de saco (volva); el champiñón NO tiene volva. Por ello desentierra siempre la base del pie por completo - la volva está a menudo hundida profundamente en la tierra.","Polvo de esporas: el champiñón es marrón oscuro, Amanita verna es BLANCO puro - la esporada es el carácter individual más fiable.","Olor: el champiñón de oveja huele a anís; Amanita verna sin olor a anís (neutro a dulzón-meloso) - la ausencia de olor a anís es una señal de alarma, pero NUNCA sustituye la comprobación de la volva/de las esporas."}','t'),
('roetling','amanita_verna','fr','Amanite printanière (Amanita verna): chapeau d''un blanc pur, LAMELLES D''UN BLANC PUR (même à un âge avancé), base du pied munie d''une volve bulbeuse, membraneuse et en forme de sac, souvent enfoncée profondément dans la terre. Agaric des moutons (agaric champêtre): chapeau blanc crème, lamelles virant au rose -> gris-rose -> brun chocolat en mûrissant, PAS de volve, tout au plus une base du pied légèrement épaissie.','Agaric des moutons: odeur agréable d''anis / de massepain. Amanita verna: quasiment inodore à légèrement sucrée / mielleuse, désagréable à un âge avancé - PAS d''anis.','Amanita verna: champignon mycorhizien, pousse en forêt (forêt de feuillus / forêt mixte), surtout au printemps, en lien avec les arbres. Agaric des moutons: saprotrophe, sur les prairies et pâturages ouverts, sans lien avec les arbres. Attention: l''habitat seul n''est PAS un critère sûr.','DÉCISIF et fiable à 100 %: agaric des moutons brun chocolat foncé à brun pourpré; Amanita verna BLANC PUR. En cas de sporée blanche, ne JAMAIS consommer comme agaric.','Pour chaque ''agaric'' blanc, TOUJOURS déterrer entièrement la base du pied et la dégager: si l''on trouve une volve bulbeuse et membraneuse (volve) OU si les lamelles restent d''un blanc pur - danger de mort, laisser sur place. En cas de doute, faire une sporée: blanc = amanite, ne jamais consommer. Les jeunes boutons blancs fermés, ne pas les récolter du tout.','{"Lamelles: Amanita verna a à TOUT âge des lamelles d''un blanc pur; l''agaric des moutons les a jeunes d''un rose pâle (les très jeunes boutons peuvent être blanc crème!), puis gris-rose à brun chocolat. IMPORTANT: au stade bouton, la couleur des lamelles seule n''est PAS sûre - vérifier alors impérativement la volve + la sporée.","Base du pied: Amanita verna a un bulbe nettement délimité avec une volve membraneuse en forme de sac (volve); l''agaric n''a PAS de volve. De plus, toujours déterrer entièrement la base du pied - la volve se trouve souvent profondément dans la terre.","Sporée: agaric brun foncé, Amanita verna d''un blanc pur - la sporée est le critère isolé le plus fiable.","Odeur: agaric des moutons à l''anis; Amanita verna sans odeur d''anis (neutre à sucrée-mielleuse) - l''absence d''odeur d''anis est un signal d''alerte, mais ne remplace JAMAIS la vérification de la volve / de la sporée."}','t'),
('roetling','amanita_verna','it','Tignosa primaverile (Amanita verna): cappello bianco puro, lamelle BIANCO PURO (anche da vecchio), base del gambo con guaina bulbosa, membranosa, a sacco (volva), spesso profonda nel terreno. Prataiolo (Agaricus): cappello bianco crema, lamelle che maturano da rosa -> grigio-rosa -> bruno cioccolato, NESSUNA volva, al massimo base del gambo leggermente ingrossata.','Prataiolo: gradevole odore di anice/marzapane. Amanita verna: pressoché inodore fino a leggermente dolciastro/mielato, da vecchia sgradevole - NESSUN anice.','Amanita verna: fungo micorrizico, cresce nel bosco (bosco di latifoglie/misto), soprattutto in primavera, in simbiosi con gli alberi. Prataiolo: saprofita su prati e pascoli aperti senza legame con gli alberi. Attenzione: l''habitat da solo NON è un carattere sicuro.','DECISIVO e affidabile al 100 %: prataiolo bruno-cioccolato scuro fino a bruno-purpureo; Amanita verna BIANCO PURO. Con sporata bianca NON mangiare MAI come prataiolo.','Con ogni ''prataiolo'' bianco estrarre e liberare SEMPRE completamente la base del gambo: se si trova una guaina bulbosa membranosa (volva) OPPURE le lamelle restano bianco puro - pericolo di vita, lasciare stare. In caso di dubbio fare la sporata: bianca = tignosa (Amanita), non mangiare mai. I giovani bottoni bianchi chiusi non raccoglierli nemmeno.','{"Lamelle: Amanita verna ha in OGNI età lamelle bianco puro; il prataiolo le ha da giovane rosa pallido (i bottoni molto giovani possono essere bianco-crema!), poi grigio-rosa fino a bruno cioccolato. IMPORTANTE: allo stadio di bottone il colore delle lamelle da solo NON è sicuro - allora verificare obbligatoriamente volva + sporata.","Base del gambo: Amanita verna ha un bulbo nettamente distinto con guaina membranosa a sacco (volva); il prataiolo NON ha volva. Estrarre sempre completamente anche la base del gambo - la volva si trova spesso in profondità nel terreno.","Sporata: prataiolo bruno scuro, Amanita verna bianco puro - la sporata è il carattere singolo più affidabile.","Odore: prataiolo odore di anice; Amanita verna senza odore di anice (neutro fino a dolciastro-mielato) - l''assenza dell''odore di anice è un segnale d''allarme, ma non sostituisce MAI la verifica di volva/sporata."}','t'),
('russula_cyanoxantha','amanita_phalloides','en','Violet-green specimens can be confused visually; the gill test (flexible vs. not) + the stem base are decisive.','Russula mild','both deciduous forest (beech/oak)','both white','DEADLY. Expose the stem base: any bulb with a membranous sheath = mortal danger.','{"Charcoal burner (Russula cyanoxantha): flexible, greasy gills (do not splinter), NO ring, NO volva","Death cap: ring + volva, deadly amatoxins"}','t'),
('russula_cyanoxantha','amanita_phalloides','es','Los ejemplares de tonos violeta-verdosos son confundibles visualmente; la prueba de las láminas (flexibles vs. no flexibles) + la base del pie son decisivas.','La rúsula es suave','ambas en bosque caducifolio (haya/roble)','ambas blanco','MORTAL. Deja al descubierto la base del pie: cualquier bulbo con vaina membranosa = peligro de muerte.','{"Rúsula cárdena (Russula cyanoxantha): láminas flexibles y untuosas (no se astillan), SIN anillo, SIN volva","Oronja mortal (Amanita phalloides): anillo + volva, amatoxinas mortales"}','t'),
('russula_cyanoxantha','amanita_phalloides','fr','Exemplaires violet-vert visuellement confondables; le test des lamelles (souples vs non) + la base du pied sont décisifs.','Russule douce.','Toutes deux en forêt de feuillus (hêtre / chêne).','Toutes deux blanches.','MORTEL. Dégager la base du pied: tout bulbe muni d''une gaine membraneuse = danger de mort.','{"Russule charbonnière: lamelles souples et lardacées (ne se brisent pas en éclats), PAS d''anneau, PAS de volve.","Amanite phalloïde: anneau + volve, amatoxines mortelles."}','t'),
('russula_cyanoxantha','amanita_phalloides','it','Esemplari violetto-verdastri otticamente confondibili; decisive la prova delle lamelle (flessibili vs. non flessibili) + la base del gambo.','Russola dolce','entrambe bosco di latifoglie (faggio/quercia)','entrambe bianche','MORTALE. Liberare la base del gambo: ogni bulbo con guaina membranosa = pericolo di vita.','{"Russola maggiore (R. cyanoxantha): lamelle flessibili-lardacee (non si frantumano), NESSUN anello, NESSUNA volva","Tignosa verdognola (Amanita phalloides): anello + volva, amatossine mortali"}','t'),
('russula_paludosa','russula_queletii','en','Tall russula (apple brittlegill) bright blood-red/orange-red with an almost white stem; primrose brittlegill a darker purple-violet with a violet-flushed stem.','Primrose brittlegill smells fruity like gooseberry compote; tall russula is low in odour.','Tall russula often in damp spots/bog edges under pine/spruce; primrose brittlegill prefers spruce on lime.','Tall russula has an ochre-yellow spore print, primrose brittlegill a cream-yellow one.','Only eat russulas that stay completely mild after 30 s of chewing - lasting acridity means poisonous.','{"The primrose brittlegill tastes persistently EXTREMELY acrid; the tall russula is mild or only slightly acrid at first and turns mild (brittlegill rule).","The tall russula has a blood-red/orange-red/copper-red cap; the primrose brittlegill a darker purple-violet-red.","Tall russula stem white, often faintly flushed pink; primrose brittlegill stem distinctly flushed violet-purple.","The primrose brittlegill smells fruity of gooseberry compote; the tall russula is inconspicuous.","Both under conifers (spruce/pine) - taste is the safety criterion."}','f'),
('russula_paludosa','russula_queletii','es','Rúsula de las turberas rojo sangre/anaranjado vivo con pie casi blanco; rúsula de Quélet de un púrpura-violeta más oscuro con pie teñido de violeta.','Rúsula de Quélet con olor afrutado a compota de grosella espinosa; rúsula de las turberas poco olorosa.','Rúsula de las turberas a menudo en lugares húmedos/bordes de turberas bajo pino/abeto rojo; rúsula de Quélet prefiere el abeto rojo sobre cal.','Esporada amarillo ocre en la rúsula de las turberas, amarillo crema en la rúsula de Quélet.','Comer solo las rúsulas que permanecen completamente suaves tras 30 s de masticación - un picor persistente significa venenosa.','{"La rúsula de Quélet sabe de forma duradera EXTREMADAMENTE picante; la rúsula de las turberas es suave o solo ligeramente picante al principio y se vuelve suave (regla de las rúsulas).","La rúsula de las turberas tiene sombrero rojo sangre/rojo anaranjado/rojo cobrizo; la rúsula de Quélet de un rojo púrpura-violeta más oscuro.","Pie de la rúsula de las turberas blanco, a menudo débilmente teñido de rosa; pie de la rúsula de Quélet claramente teñido de violeta-púrpura.","La rúsula de Quélet huele afrutado a compota de grosella espinosa; la rúsula de las turberas es poco llamativa.","Ambas bajo coníferas (abeto rojo/pino) - el sabor es el criterio de seguridad."}','f'),
('russula_paludosa','russula_queletii','fr','Russule des marais rouge sang/orangé vif avec un pied presque blanc ; russule de Quélet d''un pourpre-violet plus sombre avec un pied lavé de violet.','Russule de Quélet à odeur fruitée de compote de groseille à maquereau ; russule des marais peu odorante.','Russule des marais souvent dans les endroits humides/bordures de tourbières sous pin/épicéa ; russule de Quélet préfère l''épicéa sur calcaire.','Sporée jaune ocre pour la russule des marais, jaune crème pour la russule de Quélet.','Ne consommer que les russules qui restent entièrement douces après 30 s de mastication - une âcreté persistante signifie toxique.','{"La russule de Quélet a un goût durablement EXTRÊMEMENT âcre ; la russule des marais est douce ou seulement légèrement âcre au début puis devient douce (règle des russules).","La russule des marais a un chapeau rouge sang/rouge orangé/rouge cuivré ; la russule de Quélet d''un rouge pourpre-violet plus sombre.","Pied de la russule des marais blanc, souvent faiblement teinté de rose ; pied de la russule de Quélet nettement lavé de violet-pourpre.","La russule de Quélet sent le fruité de compote de groseille à maquereau ; la russule des marais est discrète.","Les deux sous conifères (épicéa/pin) - le goût est le critère de sécurité."}','f'),
('russula_paludosa','russula_queletii','it','Russula delle paludi rosso sangue/arancio vivo con gambo quasi bianco; russula di Quélet di un porpora-violetto più scuro con gambo soffuso di violetto.','Russula di Quélet con odore fruttato di composta di uva spina; russula delle paludi poco odorosa.','Russula delle paludi spesso in luoghi umidi/bordi di torbiere sotto pino/abete rosso; russula di Quélet predilige l''abete rosso su calcare.','Sporata giallo ocra per la russula delle paludi, giallo crema per la russula di Quélet.','Mangiare solo le russule che restano completamente miti dopo 30 s di masticazione - una piccantezza persistente significa velenosa.','{"La russula di Quélet ha sapore durevolmente ESTREMAMENTE piccante; la russula delle paludi è mite o solo leggermente piccante all''inizio e poi diventa mite (regola delle russule).","La russula delle paludi ha cappello rosso sangue/rosso arancio/rosso ramato; la russula di Quélet di un rosso porpora-violetto più scuro.","Gambo della russula delle paludi bianco, spesso debolmente soffuso di rosa; gambo della russula di Quélet nettamente soffuso di violetto-porpora.","La russula di Quélet odora di fruttato di composta di uva spina; la russula delle paludi è inappariscente.","Entrambe sotto conifere (abete rosso/pino) - il gusto è il criterio di sicurezza."}','f'),
('russula_paludosa','russula_sardonia','en','Strikingly lemon-yellow gills and a violet stem in the primrose/sardonia (dark-purple) russula; tall russula with cream gills and a white stem.','Sardonia russula faintly fruity; tall russula low in odour - smell hardly separates, taste all the more.','Both under pine on acidic soils - habitat does not separate them.','Sardonia russula has a cream spore print, tall russula an ochre-yellow one.','Lemon-yellow gills under a violet cap plus acrid taste = poisonous, leave it standing, never confuse with the mild tall russula.','{"The sardonia russula tastes very acrid (one of the most acrid); the tall russula turns mild (brittlegill rule: acrid = poisonous).","The sardonia russula has bright LEMON-YELLOW gills; the tall russula cream-white to ochre-yellow gills.","The sardonia russula has a purple-violet-blackish cap and a violet stem; the tall russula a blood-red/orange-red cap with an almost white stem.","In damp weather the sardonia russula weeps droplets on the gills (''weeping russula''); the tall russula does not.","Both under pine/spruce - only taste and gill colour separate them reliably."}','f'),
('russula_paludosa','russula_sardonia','es','Láminas de un amarillo limón llamativo y pie violeta en la rúsula sardonia; rúsula de las turberas con láminas crema y pie blanco.','Rúsula sardonia débilmente afrutada; rúsula de las turberas poco olorosa - el olor apenas distingue, el sabor mucho más.','Ambas bajo pino en suelos ácidos - el hábitat no distingue.','Esporada crema en la rúsula sardonia, amarillo ocre en la rúsula de las turberas.','Láminas amarillo limón bajo un sombrero violeta más sabor picante = venenosa, dejarla, nunca confundir con la rúsula de las turberas suave.','{"La rúsula sardonia sabe muy picante (una de las más picantes); la rúsula de las turberas se vuelve suave (regla de las rúsulas: picante = venenosa).","La rúsula sardonia tiene láminas de un AMARILLO LIMÓN intenso; la rúsula de las turberas láminas de blanco crema a amarillo ocre.","La rúsula sardonia tiene sombrero púrpura-violeta-negruzco y pie violeta; la rúsula de las turberas sombrero rojo sangre/anaranjado con pie casi blanco.","Con tiempo húmedo la rúsula sardonia llora gotas en las láminas (''rúsula llorona''); la rúsula de las turberas no.","Ambas bajo pino/abeto rojo - solo el sabor y el color de las láminas distinguen con seguridad."}','f'),
('russula_paludosa','russula_sardonia','fr','Lames d''un jaune citron frappant et pied violet chez la russule sardonie ; russule des marais à lames crème et pied blanc.','Russule sardonie faiblement fruitée ; russule des marais peu odorante - l''odeur distingue à peine, le goût d''autant plus.','Les deux sous pin sur sols acides - l''habitat ne distingue pas.','Sporée crème pour la russule sardonie, jaune ocre pour la russule des marais.','Des lames jaune citron sous un chapeau violet plus un goût âcre = toxique, laisser sur place, ne jamais confondre avec la russule des marais douce.','{"La russule sardonie a un goût très âcre (l''une des plus âcres) ; la russule des marais devient douce (règle des russules : âcre = toxique).","La russule sardonie a des lames d''un JAUNE CITRON éclatant ; la russule des marais des lames blanc crème à jaune ocre.","La russule sardonie a un chapeau pourpre-violet-noirâtre et un pied violet ; la russule des marais un chapeau rouge sang/orangé avec un pied presque blanc.","Par temps humide la russule sardonie pleure des gouttes sur les lames (''russule larmoyante'') ; pas la russule des marais.","Les deux sous pin/épicéa - seuls le goût et la couleur des lames distinguent avec certitude."}','f'),
('russula_paludosa','russula_sardonia','it','Lamelle di un giallo limone appariscente e gambo violetto nella russula sardonia; russula delle paludi con lamelle crema e gambo bianco.','Russula sardonia debolmente fruttata; russula delle paludi poco odorosa - l''odore distingue appena, il gusto molto di più.','Entrambe sotto pino su suoli acidi - l''habitat non distingue.','Sporata crema per la russula sardonia, giallo ocra per la russula delle paludi.','Lamelle giallo limone sotto un cappello violetto più sapore piccante = velenosa, lasciar stare, mai confondere con la russula delle paludi mite.','{"La russula sardonia ha sapore molto piccante (una delle più piccanti); la russula delle paludi diventa mite (regola delle russule: piccante = velenosa).","La russula sardonia ha lamelle di un GIALLO LIMONE sgargiante; la russula delle paludi lamelle da bianco crema a giallo ocra.","La russula sardonia ha cappello porpora-violetto-nerastro e gambo violetto; la russula delle paludi cappello rosso sangue/arancio con gambo quasi bianco.","Con tempo umido la russula sardonia lacrima gocce sulle lamelle (''russula lacrimosa''); non la russula delle paludi.","Entrambe sotto pino/abete rosso - solo il gusto e il colore delle lamelle distinguono con sicurezza."}','f'),
('russula_vesca','amanita_phalloides','en','Decisive and binding is the stem base: in A. phalloides a membranous white volva around a bulbous stem base plus a hanging, grooved ring; free, soft gills. R. vesca has a straight-tapering, bulb- and ringless stem base and brittle-breaking, attached gills. Color is NOT a reliable criterion: phalloides is usually olive-/yellow-green (also white as var. alba); the flesh-red cap color of vesca is at most a hint. The typical color confusion of the death cap is with GREEN edible Russulas, not with the red vesca – therefore always secure the identification morphologically at the stem base.','Older death cap smells sweetish like artificial honey to unpleasant; edible Russula smells mild/inconspicuous. Smell is ONLY an indication, never the safety criterion.','Both mycorrhizal fungi with deciduous trees (oak, beech, sweet chestnut) – location does NOT separate them reliably, hence morphological examination at the stem base is mandatory.','Both white – the spore powder does NOT distinguish these species and must not be used as an all-clear.','ALWAYS dig out the mushroom whole with the stem base (do not cut it off!) and check for bulb + membranous white volva + stem ring. If a volva/bulb/ring is found or the gills are soft and free, it is NOT a Russula – do not apply the Russula rule/taste test, because amatoxins taste MILD and are deadly. Color is never the criterion. In Switzerland: at any doubt go to the official VAPKO mushroom inspection.','{"Bulb/volva at the stem base: A. phalloides ALWAYS has a membranous, sack-like white sheath (volva) around a distinct bulb – Russulas NEVER have a volva and no bulb. This is the binding criterion, color is NOT.","Stem ring: A. phalloides carries a hanging, membranous, grooved ring (skirt) on the upper stem – Russulas are ringless.","Gills: Russula = brittle-breaking, splintering gills attached to the stem (brittle-gilled); A. phalloides = soft, flexible, FREE (not attached to the stem) gills. The taste test fails here because amatoxins taste MILD/nutty!","Cap color as a weak hint: A. phalloides is white-green/green/olive/yellow-green (rarely white, var. alba) – the flesh-red/wine-red color of R. vesca does NOT match it, but never replaces the stem-base check. The classic color confusion is with GREEN Russulas, not with the red edible Russula."}','t'),
('russula_vesca','amanita_phalloides','es','Decisiva y vinculante es la base del pie: en A. phalloides una volva blanca membranosa alrededor de una base bulbosa del pie más un anillo colgante y estriado; láminas libres y blandas. R. vesca tiene una base del pie que se afina de forma recta, sin bulbo ni anillo, y láminas adheridas y de rotura quebradiza. El color NO es un criterio fiable: phalloides es por lo general verde oliva/amarillo-verdoso (también blanca como var. alba); el color rojo carne del sombrero de vesca es a lo sumo un indicio. La confusión de color típica de la oronja mortal se da con las rúsulas comestibles VERDES, no con la vesca roja - por eso, asegúrate siempre morfológicamente en la base del pie.','La oronja mortal más vieja huele dulzona a miel artificial hasta desagradable; la rúsula comestible huele suave/discreta. El olor es SOLO un indicio, nunca el criterio de seguridad.','Ambas son hongos micorrízicos junto a árboles caducifolios (roble, haya, castaño) - el emplazamiento NO las separa de forma fiable, por ello es imprescindible la comprobación morfológica en la base del pie.','Ambas blanco - el polvo de esporas NO DISTINGUE estas especies y no debe servir para dar el visto bueno.','Desentierra SIEMPRE el hongo entero con la base del pie (¡no lo cortes!) y comprueba si hay bulbo + volva blanca membranosa + anillo en el pie. Si aparece volva/bulbo/anillo o si las láminas son blandas y libres, NO es una rúsula - no apliques la regla de las rúsulas/la prueba de sabor, ya que las amatoxinas saben SUAVES y son mortales. El color nunca es el criterio. En Suiza: ante cualquier duda, acude al control oficial de setas VAPKO.','{"Bulbo/volva en la base del pie: A. phalloides tiene SIEMPRE una vaina blanca membranosa y en forma de saco (volva) alrededor de un bulbo bien marcado - las rúsulas NUNCA tienen volva ni bulbo. Este es el criterio vinculante, el color NO lo es.","Anillo del pie: A. phalloides lleva un anillo (manguito) colgante, membranoso y estriado en la parte superior del pie - las rúsulas carecen de anillo.","Láminas: rúsula = láminas de rotura quebradiza, que se astillan, adheridas al pie (de láminas quebradizas); A. phalloides = láminas blandas, flexibles y LIBRES (no adheridas al pie). ¡La prueba de sabor falla aquí, porque las amatoxinas saben SUAVES/a nuez!","El color del sombrero como indicio débil: A. phalloides es blanco-verdosa/verde/oliva/amarillo-verdosa (rara vez blanca, var. alba) - el color rojo carne/rojo vino de R. vesca NO encaja con ello, pero nunca sustituye la comprobación de la base del pie. La confusión de color clásica se da con las rúsulas VERDES, no con la rúsula comestible roja."}','t'),
('russula_vesca','amanita_phalloides','fr','Décisif et impératif est la base du pied: chez A. phalloides une volve blanche membraneuse autour d''une base bulbeuse plus un anneau pendant et strié; lamelles libres et molles. R. vesca a une base du pied s''amincissant droit, sans bulbe ni anneau, et des lamelles cassantes et fragiles, adnées. La couleur n''est PAS un critère fiable: phalloides est le plus souvent vert olive / vert jaunâtre (aussi blanche en var. alba); la couleur rouge chair de vesca n''est tout au plus qu''un indice. La confusion classique de couleur de l''amanite phalloïde se fait avec les russules comestibles VERTES, et non avec le rouge vesca - c''est pourquoi il faut toujours s''assurer morphologiquement à la base du pied.','L''amanite phalloïde âgée sent le sucré, le miel artificiel, jusqu''au désagréable; la russule comestible a une odeur douce / discrète. L''odeur n''est QU''un indice, jamais le critère de sécurité.','Toutes deux champignons mycorhiziens sous feuillus (chêne, hêtre, châtaignier) - le lieu ne les distingue PAS de manière fiable, d''où la vérification morphologique impérative à la base du pied.','Toutes deux blanches - la sporée ne DISTINGUE PAS ces espèces et ne doit pas servir à donner le feu vert.','TOUJOURS déterrer le champignon entièrement avec la base du pied (ne pas couper!) et vérifier la présence de bulbe + volve blanche membraneuse + anneau. Si l''on trouve une volve / un bulbe / un anneau, ou si les lamelles sont molles et libres, ce n''est PAS une russule - ne pas appliquer la règle des russules / le test gustatif, car les amatoxines ont un goût DOUX et sont mortelles. La couleur n''est jamais le critère. En Suisse: au moindre doute, se rendre au contrôle officiel des champignons VAPKO.','{"Bulbe / volve à la base du pied: A. phalloides a TOUJOURS une gaine blanche membraneuse en forme de sac (volve) autour d''un bulbe net - les russules n''ont JAMAIS de volve ni de bulbe. C''est le critère impératif, la couleur ne l''est PAS.","Anneau du pied: A. phalloides porte un anneau pendant, membraneux et strié (manchette) sur le haut du pied - les russules sont sans anneau.","Lamelles: russule = lamelles cassantes, fragiles, qui se brisent en éclats, adnées au pied (sporés fragiles); A. phalloides = lamelles molles, souples, LIBRES (non adnées au pied). Le test gustatif échoue ici, car les amatoxines ont un goût DOUX / de noisette!","Couleur du chapeau comme indice faible: A. phalloides est blanc-vert / vert / olive / vert jaunâtre (rarement blanche, var. alba) - la couleur rouge chair / rouge vineux de R. vesca n''y correspond PAS, mais ne remplace jamais la vérification de la base du pied. La confusion classique de couleur se fait avec les russules VERTES, et non avec la russule comestible rouge."}','t'),
('russula_vesca','amanita_phalloides','it','Decisiva e vincolante è la base del gambo: in A. phalloides una volva membranosa bianca attorno a una base del gambo bulbosa più un anello pendulo e striato; lamelle libere e molli. R. vesca ha una base del gambo che termina diritta, senza bulbo e senza anello, e lamelle fragili-friabili e adnate. Il colore NON è un criterio affidabile: phalloides è perlopiù verde-oliva/verde-giallastra (anche bianca come var. alba); il colore rosso-carne di vesca è al massimo un indizio. La tipica confusione di colore della tignosa verdognola riguarda le russole commestibili VERDI, non la vesca rossa - perciò assicurarsi sempre morfologicamente alla base del gambo.','La tignosa verdognola più vecchia odora di dolciastro come miele artificiale fino a sgradevole; la russola commestibile odora di dolce/poco appariscente. L''odore è SOLO un indizio, mai il criterio di sicurezza.','Entrambi funghi micorrizici presso latifoglie (quercia, faggio, castagno) - l''habitat NON li distingue in modo affidabile, quindi è obbligatoria la verifica morfologica alla base del gambo.','Entrambe bianca - la sporata NON distingue queste specie e non deve servire da rassicurazione.','Estrarre SEMPRE il fungo intero con la base del gambo (non tagliare!) e verificare bulbo + volva membranosa bianca + anello al gambo. Se si trova volva/bulbo/anello oppure le lamelle sono molli e libere, NON è una russola - non applicare la regola delle russole/prova di sapore, poiché le amatossine hanno sapore DOLCE e sono mortali. Il colore non è mai il criterio. In Svizzera: in caso di qualsiasi dubbio recarsi al controllo ufficiale dei funghi VAPKO.','{"Bulbo/volva alla base del gambo: A. phalloides ha SEMPRE una guaina bianca membranosa, a sacco (volva) attorno a un bulbo evidente - le russole non hanno MAI una volva né un bulbo. Questo è il criterio vincolante, il colore NON lo è.","Anello al gambo: A. phalloides porta un anello pendulo, membranoso e striato (manicotto) nella parte alta del gambo - le russole sono prive di anello.","Lamelle: russola = lamelle fragili-friabili, che si frantumano, adnate al gambo (a lamelle fragili); A. phalloides = lamelle molli, flessibili, LIBERE (non adnate al gambo). Qui la prova di sapore fallisce, perché le amatossine hanno sapore DOLCE/nocciolato!","Colore del cappello come debole indizio: A. phalloides è bianco-verde/verde/oliva/verde-giallastra (raramente bianca, var. alba) - il colore rosso-carne/vinato di R. vesca NON corrisponde, ma non sostituisce mai la verifica della base del gambo. La classica confusione di colore riguarda le russole VERDI, non la russola commestibile rossa."}','t'),
('russula_vesca','russula_emetica','en','R. vesca: dull flesh- to wine-red/red-brown, often faded and irregularly blotchy, cap margin with a receding (too-short) cap skin, so that the gill edges protrude tooth-like. R. emetica: uniformly bright cherry-/blood-red, slimy-glossy when moist, cap skin covering right to the margin and peelable far (often to the center of the cap).','Both largely inconspicuous/slightly fruity; the smell does NOT separate these two species. The taste is decisive (mild vs. burning sharp).','R. emetica: moist/acidic bog and coniferous forests (spruce, pine, silver fir), often mossy. R. vesca: deciduous and mixed forest with beech and oak, rather fresh to dry soils.','Both white to whitish – the spore powder does NOT separate these two species. Do not use for distinguishing.','Taste test by the Russula rule: chew a small piece of cap with gills, spit it out, do not swallow – mild = edible Russula, sharp/burning = sickener (Speitäubling, poisonous, discard). The rule applies ONLY if the mushroom has been identified beyond doubt as a Russula (brittle-breaking, splintering gills, no stem ring, no volva). R. emetica is not deadly, but causes days of severe gastrointestinal distress.','{"Taste (Russula rule, the decisive distinguishing feature): R. vesca is mild and pleasantly nutty; R. emetica tastes immediately burning sharp/peppery. Briefly chew a small piece of cap with gills, do NOT swallow, spit out completely – only apply if the mushroom has been identified beyond doubt as a Russula (brittle-breaking gills, no ring, no volva).","Cap color: R. vesca dull flesh-/wine-red to red-brown, often blotchily fading; R. emetica bright blood-, cherry- to purple-red, sticky-glossy when wet.","Shortened cap skin (key feature of R. vesca): the cap margin recedes, so that cap flesh and gill ends protrude tooth-like beyond the margin – absent in R. emetica (cap skin covers to the margin and can be peeled far, often to the center of the cap).","Location: R. emetica typically in moist bog and coniferous forests (spruce, pine, silver fir, often mossy/acidic); R. vesca mainly in deciduous/mixed forest with beech and oak."}','t'),
('russula_vesca','russula_emetica','es','R. vesca: rojo carne mate a rojo vino/rojo pardo, a menudo desvaído y con manchas irregulares, con el borde del sombrero de cutícula retraída (demasiado corta), de modo que los bordes de las láminas sobresalen a modo de dientecillos. R. emetica: rojo cereza/rojo sangre brillante y uniforme, viscosa y reluciente con la humedad, con la cutícula cubriendo hasta el borde y desprendible en gran parte (a menudo hasta el centro del sombrero).','Ambas en gran medida discretas/ligeramente afrutadas; el olor NO separa estas dos especies. Lo decisivo es el sabor (suave vs. ardiente y picante).','R. emetica: bosques húmedos/ácidos de turbera y coníferas (abeto rojo, pino, abeto blanco), a menudo con musgo. R. vesca: bosque caducifolio y mixto junto a haya y roble, en suelos más bien frescos a secos.','Ambas blanco a blanquecino – el polvo de esporas NO separa estas dos especies. No usar para la distinción.','Prueba de sabor según la regla de las rúsulas: masticar un trozo pequeño del sombrero con láminas, escupir, no tragar – suave = rúsula comestible, picante/ardiente = rúsula vomitiva (tóxica, descartar). La regla SOLO es válida si el hongo se ha reconocido sin lugar a dudas como rúsula (láminas quebradizas que se astillan, sin anillo en el pie, sin volva). R. emetica no es mortal, pero provoca trastornos gastrointestinales intensos durante días.','{"Sabor (regla de las rúsulas, el carácter distintivo decisivo): R. vesca es suave y agradablemente a nuez; R. emetica sabe de inmediato ardiente/picante como la pimienta. Masticar brevemente un trozo pequeño del sombrero con láminas, NO tragar, escupir por completo – aplicar solo si el hongo se ha reconocido sin lugar a dudas como rúsula (láminas quebradizas, sin anillo, sin volva).","Color del sombrero: R. vesca rojo carne/rojo vino mate hasta rojo pardo, a menudo desvaído con manchas; R. emetica rojo sangre, rojo cereza brillante hasta rojo púrpura, pegajosa y reluciente con la humedad.","Cutícula acortada (carácter guía de R. vesca): el borde del sombrero queda retraído, de modo que la carne del sombrero y los extremos de las láminas sobresalen del borde a modo de dientecillos – falta en R. emetica (la cutícula cubre hasta el borde y se desprende en gran parte, a menudo hasta el centro del sombrero).","Emplazamiento: R. emetica típicamente en bosques húmedos de turbera y coníferas (abeto rojo, pino, abeto blanco, a menudo con musgo/ácidos); R. vesca sobre todo en bosque caducifolio/mixto junto a haya y roble."}','t'),
('russula_vesca','russula_emetica','fr','R. vesca: rouge chair à rouge vineux / brun rougeâtre mat, souvent décoloré et irrégulièrement taché, marge du chapeau avec une cuticule en retrait (trop courte), de sorte que les arêtes des lamelles dépassent en forme de petites dents. R. emetica: rouge cerise / rouge sang vif et uniforme, visqueux et brillant par temps humide, la cuticule couvre jusqu''à la marge et est largement séparable (souvent jusqu''au centre du chapeau).','Toutes deux largement discrètes / légèrement fruitées; l''odeur ne sépare PAS ces deux espèces. Le décisif est le goût (doux vs brûlant et âcre).','R. emetica: forêts marécageuses / acides humides et forêts de conifères (épicéa, pin, sapin blanc), souvent moussues. R. vesca: forêt de feuillus et forêt mixte sous hêtre et chêne, sols plutôt frais à secs.','Toutes deux blanches à blanchâtres - la sporée ne sépare PAS ces deux espèces. Ne pas l''utiliser pour la distinction.','Test gustatif selon la règle des russules: mâcher un petit morceau de chapeau avec lamelles, recracher, ne pas avaler - doux = russule comestible, âcre / brûlant = russule émétique (toxique, à jeter). La règle ne s''applique QUE si le champignon est reconnu sans aucun doute comme une russule (lamelles cassantes et fragiles qui se brisent en éclats, pas d''anneau au pied, pas de volve). R. emetica n''est pas mortelle, mais provoque des troubles gastro-intestinaux violents durant plusieurs jours.','{"Goût (règle des russules, le critère de distinction décisif): R. vesca est doux et agréablement noisette; R. emetica a immédiatement un goût brûlant, âcre / poivré. Mâcher brièvement un petit morceau de chapeau avec lamelles, NE PAS avaler, recracher entièrement - à n''appliquer que si le champignon est reconnu sans aucun doute comme une russule (lamelles cassantes, pas d''anneau, pas de volve).","Couleur du chapeau: R. vesca rouge chair / rouge vineux mat à brun rougeâtre, souvent taché et se décolorant; R. emetica rouge sang, rouge cerise à pourpre vif, collant et brillant par temps humide.","Cuticule raccourcie (caractère distinctif de R. vesca): la marge du chapeau est en retrait, de sorte que la chair du chapeau et les extrémités des lamelles dépassent la marge en forme de petites dents - absent chez R. emetica (la cuticule couvre jusqu''à la marge et se sépare largement, souvent jusqu''au centre du chapeau).","Station: R. emetica typiquement dans les forêts marécageuses et de conifères humides (épicéa, pin, sapin blanc, souvent moussues / acides); R. vesca surtout en forêt de feuillus / forêt mixte sous hêtre et chêne."}','t'),
('russula_vesca','russula_emetica','it','R. vesca: rosso-carne opaco fino a rosso-vinato/bruno-rossastro, spesso scolorita e macchiata in modo irregolare, con cuticola del bordo del cappello retratta (troppo corta), così che i bordi delle lamelle sporgono a denti. R. emetica: rosso-ciliegia/sangue uniforme e brillante, viscida e lucida con l''umidità, con cuticola che copre fino al bordo e si stacca ampiamente (spesso fino al centro del cappello).','Entrambe perlopiù poco appariscenti/leggermente fruttate; l''odore NON distingue queste due specie. Decisivo è il sapore (dolce vs. bruciante-acre).','R. emetica: boschi umidi/acidi di torbiera e di conifere (abete rosso, pino, abete bianco), spesso muscosi. R. vesca: bosco di latifoglie e misto presso faggio e quercia, suoli piuttosto freschi fino a secchi.','Entrambe bianca fino a biancastra - la sporata NON distingue queste due specie. Non usarla per la distinzione.','Prova di sapore secondo la regola delle russole: masticare un pezzetto di cappello con lamelle, sputare, non ingoiare - dolce = russola commestibile, acre/bruciante = russola emetica (velenosa, scartare). La regola vale SOLO se il fungo è riconosciuto senza dubbio come russola (lamelle fragili-friabili che si frantumano, nessun anello al gambo, nessuna volva). R. emetica non è mortale, ma provoca per giorni violenti disturbi gastrointestinali.','{"Sapore (regola delle russole, il carattere distintivo decisivo): R. vesca è dolce e gradevolmente nocciolata; R. emetica ha sapore subito bruciante-acre/pepato. Masticare brevemente un pezzetto di cappello con lamelle, NON ingoiare, sputare completamente - applicare solo se il fungo è riconosciuto senza dubbio come russola (lamelle fragili-friabili, nessun anello, nessuna volva).","Colore del cappello: R. vesca rosso-carne/vinato opaco fino a bruno-rossastro, spesso scolorita a macchie; R. emetica rosso sangue, ciliegia fino a purpureo brillante, appiccicosa-lucida con l''umidità.","Cuticola accorciata (carattere distintivo di R. vesca): il bordo del cappello è retratto, così che la carne del cappello e le estremità delle lamelle sporgono a denti oltre il bordo - assente in R. emetica (la cuticola copre fino al bordo e si lascia staccare ampiamente, spesso fino al centro del cappello).","Habitat: R. emetica tipica in boschi umidi di torbiera e di conifere (abete rosso, pino, abete bianco, spesso muscosi/acidi); R. vesca soprattutto in bosco di latifoglie/misto presso faggio e quercia."}','t'),
('russula_vesca','russula_nobilis','en','Bare-toothed russula (the flirt) with characteristically retracted cap cuticle (free cap margin) and a duller red; beechwood sickener vivid vermilion-red with cuticle covering the margin.','The beechwood sickener smells sweetish-fruity; the bare-toothed russula is almost odourless to faintly nutty.','Both under beech on rather dry soils - habitat does not separate them.','Both have a whitish spore print - hardly distinguishing.','With red russulas ALWAYS chew a small piece of the cap margin and spit it out - burning/acrid means poisonous and does not belong in the basket.','{"The beechwood sickener tastes immediately EXTREMELY acrid/burning; the bare-toothed russula tastes mild and nutty (brittlegill rule: acrid = poisonous).","In the bare-toothed russula the cap cuticle is typically too short and leaves the cap margin free (''coat too short''); in the beechwood sickener it covers the margin.","The beechwood sickener has a vivid vermilion-red cap colour; the bare-toothed russula rather flesh-red, wine-red to brownish, often blotchily faded.","The gills of the bare-toothed russula become rust-spotted with age; in the beechwood sickener they stay whitish to pale cream-yellow.","Both have a white stem and grow in beech forest - only the taste test separates them reliably."}','f'),
('russula_vesca','russula_nobilis','es','Rúsula comestible con cutícula característicamente retraída (margen del sombrero libre) y tono rojo más apagado; rúsula del haya rojo bermellón vivo con cutícula que cubre el margen.','La rúsula del haya huele dulzón-afrutado; la rúsula comestible es casi inodora o débilmente a nuez.','Ambas bajo haya en suelos más bien secos - el hábitat no distingue.','Ambas esporada blanquecina - apenas distintivo.','Con las rúsulas rojas SIEMPRE masticar un trocito del margen del sombrero y escupir - ardiente y picante significa venenosa y no va a la cesta.','{"La rúsula del haya sabe de inmediato EXTREMADAMENTE picante/ardiente; la rúsula comestible sabe suave y a nuez (regla de las rúsulas: picante = venenosa).","En la rúsula comestible la cutícula es típicamente demasiado corta y deja libre el margen del sombrero (''manto demasiado corto''); en la rúsula del haya cubre el margen.","La rúsula del haya tiene color de sombrero rojo bermellón vivo; la rúsula comestible más bien rojo carne, rojo vinoso a parduzco, a menudo descolorida a manchas.","Las láminas de la rúsula comestible se manchan de herrumbre con la edad; en la rúsula del haya permanecen blanquecinas a amarillo crema pálido.","Ambas tienen pie blanco y crecen en hayedo - solo la prueba de sabor distingue con seguridad."}','f'),
('russula_vesca','russula_nobilis','fr','Russule comestible avec une cuticule caractéristiquement rétractée (marge du chapeau dégagée) et un rouge plus terne ; russule des hêtres rouge vermillon vif avec cuticule couvrant la marge.','La russule des hêtres sent le sucré et le fruité ; la russule comestible est presque inodore à faiblement de noisette.','Les deux sous hêtre sur sols plutôt secs - l''habitat ne distingue pas.','Les deux ont une sporée blanchâtre - guère discriminant.','Pour les russules rouges, TOUJOURS mâcher un petit morceau de la marge du chapeau et recracher - brûlant et âcre signifie toxique et n''a pas sa place dans le panier.','{"La russule des hêtres a un goût immédiatement EXTRÊMEMENT âcre/brûlant ; la russule comestible a un goût doux et de noisette (règle des russules : âcre = toxique).","Chez la russule comestible la cuticule est typiquement trop courte et laisse la marge du chapeau dégagée (''manteau trop court'') ; chez la russule des hêtres elle couvre la marge.","La russule des hêtres a une couleur de chapeau rouge vermillon vif ; la russule comestible plutôt rouge chair, rouge vineux à brunâtre, souvent décolorée par plaques.","Les lames de la russule comestible se tachent de rouille avec l''âge ; chez la russule des hêtres elles restent blanchâtres à jaune crème pâle.","Les deux ont un pied blanc et poussent en hêtraie - seul le test gustatif distingue avec certitude."}','f'),
('russula_vesca','russula_nobilis','it','Russula commestibile con cuticola caratteristicamente ritratta (margine del cappello libero) e tonalità rossa più spenta; russula del faggio rosso cinabro vivo con cuticola che copre il margine.','La russula del faggio odora di dolciastro-fruttato; la russula commestibile è quasi inodore o debolmente di nocciola.','Entrambe sotto faggio su suoli piuttosto secchi - l''habitat non distingue.','Entrambe sporata biancastra - poco distintivo.','Con le russule rosse SEMPRE masticare un pezzetto del margine del cappello e sputare - bruciante e piccante significa velenosa e non va nel cesto.','{"La russula del faggio ha sapore subito ESTREMAMENTE piccante/bruciante; la russula commestibile ha sapore mite e di nocciola (regola delle russule: piccante = velenosa).","Nella russula commestibile la cuticola è tipicamente troppo corta e lascia libero il margine del cappello (''mantello troppo corto''); nella russula del faggio copre il margine.","La russula del faggio ha colore del cappello rosso cinabro vivo; la russula commestibile piuttosto rosso carne, rosso vinoso fino a brunastro, spesso scolorita a chiazze.","Le lamelle della russula commestibile si macchiano di ruggine con l''età; nella russula del faggio restano biancastre fino a giallo crema pallido.","Entrambe hanno gambo bianco e crescono in faggeta - solo il test del gusto distingue con sicurezza."}','f'),
('russula_virescens','amanita_phalloides','en','Green coloration similar, especially when young; the Russula cap skin cracks into a mosaic-like (felty) pattern.','Russula mild/nutty; death cap honey-like (when old)','both deciduous forest','Russula white, A. phalloides white','DEADLY. With green mushrooms ALWAYS dig out the whole mushroom: are BOTH ring AND volva absent? Otherwise do not eat.','{"Russula: brittle gills, NO ring, NO bulb/volva","Death cap: ring + membranous volva at a bulbous base, flexible gills"}','t'),
('russula_virescens','amanita_phalloides','es','Coloración verde similar, sobre todo de joven; la cutícula de la rúsula se resquebraja en placas.','La rúsula es suave/a nuez; la oronja mortal huele a miel (de vieja)','ambas en bosque caducifolio','La rúsula blanco, A. phalloides blanco','MORTAL. Ante hongos verdes, desentierra SIEMPRE el hongo entero: ¿faltan el anillo Y la volva? Si no, no comer.','{"Rúsula: láminas quebradizas, SIN anillo, SIN bulbo/volva","Oronja mortal: anillo + volva membranosa en una base bulbosa, láminas flexibles"}','t'),
('russula_virescens','amanita_phalloides','fr','Coloration verte semblable, surtout jeune; la cuticule de la russule se craquelle en aréoles.','Russule douce / de noisette; amanite phalloïde mielleuse (à un âge avancé).','Toutes deux en forêt de feuillus.','Russule blanche, A. phalloides blanche.','MORTEL. Pour les champignons verts, TOUJOURS déterrer le champignon entier: l''anneau ET la volve sont-ils absents? Sinon, ne pas consommer.','{"Russule: lamelles cassantes et fragiles, PAS d''anneau, PAS de bulbe / volve.","Amanite phalloïde: anneau + volve membraneuse à la base bulbeuse, lamelles souples."}','t'),
('russula_virescens','amanita_phalloides','it','Colorazione verde simile, soprattutto da giovane; la cuticola della russola si screpola a placche (areolata).','Russola dolce/nocciolata; tignosa verdognola (Amanita phalloides) odore mielato (da vecchia)','entrambe bosco di latifoglie','Russola bianca, A. phalloides bianca','MORTALE. Con i funghi verdi estrarre SEMPRE il fungo intero: mancano anello E volva? Altrimenti non mangiare.','{"Russola: lamelle fragili, NESSUN anello, NESSUN bulbo/volva","Tignosa verdognola (Amanita phalloides): anello + volva membranosa su base bulbosa, lamelle flessibili"}','t'),
('russula_xerampelina','russula_queletii','en','The crab brittlegill browns in the flesh and on the stem; the primrose brittlegill stays purple-red to violet without browning.','The crab brittlegill smells of fish/herring, the primrose brittlegill smells fruity like gooseberry compote.','Both under spruce on rather calcareous soil - habitat does not separate them.','Crab brittlegill has an ochre-yellow spore print, primrose brittlegill a cream-yellow one.','The taste test decides: burning hot/acrid = poisonous primrose brittlegill; mild plus fishy smell = edible crab brittlegill.','{"The primrose brittlegill tastes EXTREMELY acrid (one of the most acrid brittlegills); the crab brittlegill is mild (brittlegill rule: acrid = poisonous).","The crab brittlegill smells typically of herring/fish brine (especially in a warm hand and with age); the primrose brittlegill smells fruity like gooseberry compote.","Crab brittlegill flesh browns/yellows and gives a green reaction with iron sulphate; the primrose brittlegill does not.","The primrose brittlegill has a stem flushed purple-red and tinted violet; the crab brittlegill often has a pink-reddish stem that later browns.","Both grow under spruce - taste and smell separate them reliably."}','f'),
('russula_xerampelina','russula_queletii','es','La rúsula de arenque pardea en la carne y en el pie; la rúsula de Quélet permanece rojo púrpura-violácea sin pardear.','La rúsula de arenque huele a pescado/arenque, la rúsula de Quélet tiene olor afrutado a compota de grosella espinosa.','Ambas bajo abeto rojo en suelo más bien calcáreo - el hábitat no distingue.','Esporada amarillo ocre en la rúsula de arenque, amarillo crema en la rúsula de Quélet.','La prueba de sabor decide: ardiente y picante = rúsula de Quélet venenosa; suave más olor a pescado = rúsula de arenque comestible.','{"La rúsula de Quélet sabe EXTREMADAMENTE picante (una de las rúsulas más picantes); la rúsula de arenque es suave (regla de las rúsulas: picante = venenosa).","La rúsula de arenque huele típicamente a arenque/salmuera de pescado (sobre todo en mano caliente y con la edad); la rúsula de Quélet huele afrutado a compota de grosella espinosa.","La carne de la rúsula de arenque pardea/amarillea y da reacción verde con sulfato de hierro; la rúsula de Quélet no.","La rúsula de Quélet tiene el pie teñido de rojo púrpura, matizado de violeta; la rúsula de arenque suele tener el pie rosa-rojizo, que luego pardea.","Ambas crecen bajo abeto rojo - el sabor y el olor distinguen con seguridad."}','f'),
('russula_xerampelina','russula_queletii','fr','La russule des chevreuils brunit dans la chair et sur le pied ; la russule de Quélet reste rouge pourpre-violacé sans brunissement.','La russule des chevreuils sent le poisson/hareng, la russule de Quélet a une odeur fruitée de compote de groseille à maquereau.','Les deux sous épicéa sur sol plutôt calcaire - l''habitat ne distingue pas.','Sporée jaune ocre pour la russule des chevreuils, jaune crème pour la russule de Quélet.','Le test gustatif tranche : brûlant et âcre = russule de Quélet toxique ; doux plus odeur de poisson = russule des chevreuils comestible.','{"La russule de Quélet a un goût EXTRÊMEMENT âcre (l''une des russules les plus âcres) ; la russule des chevreuils est douce (règle des russules : âcre = toxique).","La russule des chevreuils sent typiquement le hareng/la saumure de poisson (surtout dans une main chaude et avec l''âge) ; la russule de Quélet a une odeur fruitée de compote de groseille à maquereau.","La chair de la russule des chevreuils brunit/jaunit et donne une réaction verte au sulfate de fer ; pas la russule de Quélet.","La russule de Quélet a un pied lavé de rouge pourpre, teinté de violet ; la russule des chevreuils a souvent un pied rose rougeâtre, brunissant plus tard.","Les deux poussent sous épicéa - le goût et l''odeur distinguent avec certitude."}','f'),
('russula_xerampelina','russula_queletii','it','La russula delle aringhe imbrunisce nella carne e sul gambo; la russula di Quélet resta rosso porpora-violaceo senza imbrunire.','La russula delle aringhe odora di pesce/aringa, la russula di Quélet ha odore fruttato di composta di uva spina.','Entrambe sotto abete rosso su suolo piuttosto calcareo - l''habitat non distingue.','Sporata giallo ocra per la russula delle aringhe, giallo crema per la russula di Quélet.','Il test del gusto è decisivo: bruciante e piccante = russula di Quélet velenosa; mite più odore di pesce = russula delle aringhe commestibile.','{"La russula di Quélet ha un sapore ESTREMAMENTE piccante (una delle russule più piccanti); la russula delle aringhe è mite (regola delle russule: piccante = velenosa).","La russula delle aringhe odora tipicamente di aringa/salamoia di pesce (specie in mano calda e con l''età); la russula di Quélet ha odore fruttato di composta di uva spina.","La carne della russula delle aringhe imbrunisce/ingiallisce e dà reazione verde con il solfato di ferro; non così la russula di Quélet.","La russula di Quélet ha il gambo soffuso di rosso porpora, tinto di violetto; la russula delle aringhe ha spesso il gambo rosa-rossastro, poi imbrunente.","Entrambe crescono sotto abete rosso - il gusto e l''odore distinguono con sicurezza."}','f'),
('russula_xerampelina','russula_sardonia','en','Sardonia russula with lemon-yellow gills and a violet cap; crab brittlegill brownish-red with browning gills and stem.','Crab brittlegill distinctly of fish/herring; sardonia russula faintly fruity, never fishy.','Both under conifers (pine/spruce) - habitat does not separate them.','Crab brittlegill has an ochre-yellow spore print, sardonia russula a cream one.','Mild plus fishy smell = edible crab brittlegill; acrid with lemon-yellow gills = poisonous sardonia russula.','{"The sardonia russula tastes very acrid; the crab brittlegill is mild (brittlegill rule: acrid = poisonous).","The crab brittlegill smells of herring/fish brine and browns in the flesh; the sardonia russula smells faintly fruity and does not brown.","The sardonia russula has bright lemon-yellow gills; the crab brittlegill cream-ochre, browning later.","The crab brittlegill reacts green with iron sulphate; the sardonia russula does not turn green.","Both under pine/spruce - taste and fishy smell are the safety criteria."}','f'),
('russula_xerampelina','russula_sardonia','es','Rúsula sardonia con láminas amarillo limón y sombrero violeta; rúsula de arenque pardo-rojiza con láminas y pie que pardean.','Rúsula de arenque claramente a pescado/arenque; rúsula sardonia débilmente afrutada, nunca a pescado.','Ambas bajo coníferas (pino/abeto rojo) - el hábitat no distingue.','Esporada amarillo ocre en la rúsula de arenque, crema en la rúsula sardonia.','Suave más olor a pescado = rúsula de arenque comestible; picante con láminas amarillo limón = rúsula sardonia venenosa.','{"La rúsula sardonia sabe muy picante; la rúsula de arenque es suave (regla de las rúsulas: picante = venenosa).","La rúsula de arenque huele a arenque/salmuera de pescado y pardea en la carne; la rúsula sardonia huele débilmente afrutado y no pardea.","La rúsula sardonia tiene láminas de un amarillo limón intenso; la rúsula de arenque ocre crema, que pardea más tarde.","La rúsula de arenque reacciona en verde con sulfato de hierro; la rúsula sardonia no se vuelve verde.","Ambas bajo pino/abeto rojo - el sabor y el olor a pescado son los criterios de seguridad."}','f'),
('russula_xerampelina','russula_sardonia','fr','Russule sardonie à lames jaune citron et chapeau violet ; russule des chevreuils brun-rougeâtre avec lames et pied brunissants.','Russule des chevreuils nettement de poisson/hareng ; russule sardonie faiblement fruitée, jamais de poisson.','Les deux sous conifères (pin/épicéa) - l''habitat ne distingue pas.','Sporée jaune ocre pour la russule des chevreuils, crème pour la russule sardonie.','Doux plus odeur de poisson = russule des chevreuils comestible ; âcre avec lames jaune citron = russule sardonie toxique.','{"La russule sardonie a un goût très âcre ; la russule des chevreuils est douce (règle des russules : âcre = toxique).","La russule des chevreuils sent le hareng/la saumure de poisson et brunit dans la chair ; la russule sardonie sent faiblement le fruité et ne brunit pas.","La russule sardonie a des lames d''un jaune citron éclatant ; la russule des chevreuils ocre crème, brunissant plus tard.","La russule des chevreuils réagit en vert au sulfate de fer ; la russule sardonie pas en vert.","Les deux sous pin/épicéa - le goût et l''odeur de poisson sont les critères de sécurité."}','f'),
('russula_xerampelina','russula_sardonia','it','Russula sardonia con lamelle giallo limone e cappello violetto; russula delle aringhe bruno-rossastra con lamelle e gambo imbrunenti.','Russula delle aringhe nettamente di pesce/aringa; russula sardonia debolmente fruttata, mai di pesce.','Entrambe sotto conifere (pino/abete rosso) - l''habitat non distingue.','Sporata giallo ocra per la russula delle aringhe, crema per la russula sardonia.','Mite più odore di pesce = russula delle aringhe commestibile; piccante con lamelle giallo limone = russula sardonia velenosa.','{"La russula sardonia ha sapore molto piccante; la russula delle aringhe è mite (regola delle russule: piccante = velenosa).","La russula delle aringhe odora di aringa/salamoia di pesce e imbrunisce nella carne; la russula sardonia odora debolmente di fruttato e non imbrunisce.","La russula sardonia ha lamelle di un giallo limone sgargiante; la russula delle aringhe ocra crema, poi imbrunente.","La russula delle aringhe reagisce in verde con il solfato di ferro; la russula sardonia non in verde.","Entrambe sotto pino/abete rosso - il gusto e l''odore di pesce sono i criteri di sicurezza."}','f'),
('schopftintling','amanita_phalloides','en','Inky cap (Shaggy ink cap): white-scaly, egg-shaped. Death cap (Amanita phalloides): olive-green, smooth.',NULL,'Inky cap: meadows, roadsides. Death cap: deciduous forest.','Inky cap: black. Death cap: white.','The inky cap''s gills turn black; the death cap''s NEVER do.','{"Shaggy ink cap: egg-shaped, scaly cap; death cap: smooth","Inky cap in meadows, death cap in woodland"}','t'),
('schopftintling','amanita_phalloides','es','Coprino (Schopftintling): blanco-escamoso, de forma ovoide. Oronja verde (Knollenblätterpilz / Amanita phalloides): verde oliva, lisa.',NULL,'Coprino: prados, bordes de caminos. Oronja verde: bosque de frondosas.','Coprino: negra. Oronja verde: blanca.','Las láminas del coprino se vuelven negras; las de la oronja verde NUNCA lo hacen.','{"Coprino melenudo (Schopftintling): sombrero ovoide y escamoso; la oronja verde tiene el sombrero liso","El coprino crece en prados; la oronja verde, en el bosque"}','t'),
('schopftintling','amanita_phalloides','fr','Coprin chevelu: blanc-écailleux, ovoïde. Amanite phalloïde: vert olive, lisse.',NULL,'Coprin chevelu: prairies, bords de chemin. Amanite phalloïde: forêt de feuillus.','Coprin chevelu: noire. Amanite phalloïde: blanche.','Les lamelles du coprin chevelu noircissent, celles de l''amanite phalloïde JAMAIS.','{"Coprin chevelu: chapeau ovoïde écailleux; amanite phalloïde lisse","Coprin chevelu dans les prairies, amanite phalloïde en forêt"}','t'),
('schopftintling','amanita_phalloides','it','Coprino chiomato: bianco-squamoso, ovoidale. Amanita falloide (Amanita phalloides): verde oliva, liscia.',NULL,'Coprino chiomato: prati, bordi dei sentieri. Amanita falloide: bosco di latifoglie.','Coprino chiomato: nera. Amanita falloide: bianca.','Le lamelle del coprino chiomato diventano nere, quelle dell''Amanita falloide MAI.','{"Coprino chiomato: cappello ovoidale, squamoso; Amanita falloide liscia","Coprino nei prati, Amanita falloide nel bosco"}','t'),
('schopftintling','coprinopsis_picacea','en','Pure white, scaly shaggy ink cap with ring vs. the brown-black magpie inkcap with white veil flecks and without a ring.','Magpie inkcap unpleasantly musty-tarry; shaggy ink cap neutral and pleasant.','Magpie inkcap prefers humus- and lime-rich deciduous/beech forests and forest-path edges; shaggy ink cap on nutrient-rich meadows, path and road verges, ruderal areas.','Both black spore print (deliquescent); not distinguishing.','A black-and-white spotted inkcap specimen smelling musty-tarry and without a stem ring should as a rule be left standing.','{"Shaggy ink cap: white, cylindrical-elongated cap with erect white scales and a movable ring on the stem; magpie inkcap with dark-brown-black cap covered with white, wipeable veil flecks (magpie/woodpecker pattern), without a ring.","Shaggy ink cap when young neutral and pleasant in smell; magpie inkcap smells unpleasantly musty-tarry.","Magpie inkcap slimmer, taller and more fragile; the young shaggy ink cap stouter/squatter.","The magpie inkcap is inedible (musty-tarry taste); the shaggy ink cap when young (gills still white) is an excellent edible mushroom."}','f'),
('schopftintling','coprinopsis_picacea','es','Coprino melenudo de un blanco puro, escamoso, con anillo, frente al coprino picazo pardo-negro con copos de velo blancos y sin anillo.','El coprino picazo huele desagradablemente a moho-alquitrán; el coprino melenudo es neutro y agradable.','El coprino picazo prefiere bosques de frondosas/hayas ricos en humus y cal y los bordes de senderos forestales; el coprino melenudo en praderas ricas en nutrientes, bordes de senderos y caminos, áreas ruderales.','Ambos con esporada negra (delicuescente); no distintivo.','Un ejemplar de coprino moteado de blanco y negro, con olor a moho-alquitrán y sin anillo en el pie, debe por principio dejarse en el sitio.','{"Coprino melenudo: sombrero blanco, cilíndrico-alargado con escamas blancas erguidas y anillo móvil en el pie; coprino picazo con sombrero pardo oscuro-negro cubierto de copos de velo blancos que se pueden frotar (patrón urraca/pico), sin anillo.","Coprino melenudo joven de olor neutro y agradable; el coprino picazo huele desagradablemente a moho-alquitrán.","Coprino picazo más esbelto, más alto y más frágil; el joven coprino melenudo más robusto/rechoncho.","El coprino picazo es incomible (sabor a moho-alquitrán); el coprino melenudo joven (láminas aún blancas) es un excelente hongo comestible."}','f'),
('schopftintling','coprinopsis_picacea','fr','Coprin chevelu blanc pur, écailleux avec anneau vs. coprin pie brun-noir avec des flocons de voile blancs et sans anneau.','Coprin pie désagréablement moisi-goudronné ; coprin chevelu neutre et agréable.','Coprin pie préfère les forêts de feuillus/hêtres riches en humus et calcaire et les bords de chemins forestiers ; coprin chevelu sur prairies riches en nutriments, bords de chemins, friches.','Les deux à sporée noire (déliquescente) ; non discriminant.','Laisser par principe sur place tout exemplaire de coprin tacheté noir-blanc à odeur moisi-goudronnée sans anneau au pied.','{"Coprin chevelu : chapeau blanc, cylindrique-allongé avec des écailles blanches dressées et un anneau mobile au pied ; coprin pie avec un chapeau brun foncé-noir couvert de flocons de voile blancs, essuyables (motif pie/écaille), sans anneau.","Coprin chevelu jeune neutre d''odeur et agréable ; coprin pie sent désagréablement le moisi-goudronné.","Coprin pie plus élancé, plus haut et plus fragile ; le jeune coprin chevelu plus robuste/trapu.","Coprin pie non comestible (goût moisi-goudronné) ; coprin chevelu jeune (avec lamelles encore blanches) un excellent comestible."}','f'),
('schopftintling','coprinopsis_picacea','it','Coprinus comatus di un bianco puro, squamoso, con anello, contro il Coprinopsis picacea bruno-nero con fiocchi di velo bianchi e senza anello.','Il Coprinopsis picacea odora sgradevolmente di muffa-catrame ; il Coprinus comatus è neutro e gradevole.','Il Coprinopsis picacea predilige boschi di latifoglie/faggi ricchi di humus e calcare e i margini dei sentieri forestali ; il Coprinus comatus su prati ricchi di nutrienti, margini di sentieri e strade, aree ruderali.','Entrambi con sporata nera (deliquescente) ; non distintivo.','Un esemplare di coprino macchiato di bianco e nero, dall''odore di muffa-catrame e senza anello sul gambo, va per principio lasciato sul posto.','{"Coprinus comatus : cappello bianco, cilindrico-allungato con squame bianche erette e anello mobile sul gambo ; Coprinopsis picacea con cappello bruno scuro-nero ricoperto di fiocchi di velo bianchi asportabili (motivo gazza/picchio), senza anello.","Coprinus comatus giovane dall''odore neutro e gradevole ; Coprinopsis picacea odora sgradevolmente di muffa-catrame.","Coprinopsis picacea più slanciato, più alto e più fragile ; il giovane Coprinus comatus più robusto/tozzo.","Il Coprinopsis picacea è immangiabile (sapore di muffa-catrame) ; il Coprinus comatus giovane (lamelle ancora bianche) è un eccellente fungo commestibile."}','f'),
('semmelstoppelpilz','austernpilz','en','Hedgehog mushroom: on the ground in mixed forest. Oyster mushroom: on a tree trunk.',NULL,'Ground vs. tree',NULL,'Both are suitable for beginners.','{"Hedgehog mushroom has SPINES; oyster mushroom has GILLS","Ground vs. tree trunk"}','t'),
('semmelstoppelpilz','austernpilz','es','Lengua de vaca (Semmelstoppelpilz): sobre el suelo, en bosque mixto. Seta de ostra (Austernpilz): sobre el tronco de un árbol.',NULL,'Suelo frente a árbol',NULL,'Ambas son aptas para principiantes.','{"La lengua de vaca tiene PÚAS; la seta de ostra tiene LÁMINAS","Suelo frente a tronco de árbol"}','t'),
('semmelstoppelpilz','austernpilz','fr','Pied-de-mouton sur le sol en forêt mixte. Pleurote en huître sur un tronc d''arbre.',NULL,'Sol vs arbre',NULL,'Tous deux adaptés aux débutants.','{"Le pied-de-mouton a des AIGUILLONS, le pleurote en huître des LAMELLES","Sol vs tronc d''arbre"}','t'),
('semmelstoppelpilz','austernpilz','it','Steccherino dorato sul terreno, nel bosco misto. Gelone (orecchione) sul tronco d''albero.',NULL,'Terreno contro albero',NULL,'Entrambi adatti ai principianti.','{"Lo steccherino ha ACULEI, il gelone (orecchione) ha LAMELLE","Terreno contro tronco d''albero"}','t'),
('steinpilz','butterpilz','en','Porcini (cep): white-netted stem, no ring. Slippery jack (Butterpilz): slimy cap, ring.',NULL,'Both in coniferous forest; slippery jack under pine.',NULL,'Peel the skin off the slippery jack''s cap.','{"Porcini: smooth stem; slippery jack: ring + slimy cap"}','t'),
('steinpilz','butterpilz','es','Boletus (Steinpilz): pie con retículo blanco, sin anillo. Boleto granulado anillado (Butterpilz): sombrero viscoso, con anillo.',NULL,'Ambos en bosque de coníferas; el Butterpilz, junto al pino silvestre.',NULL,'Al Butterpilz se le puede retirar la cutícula (piel del sombrero).','{"El boletus tiene el pie liso; el Butterpilz tiene anillo + sombrero viscoso"}','t'),
('steinpilz','butterpilz','fr','Le cèpe a un pied à réseau blanc, sans anneau. Le bolet jaune a un chapeau visqueux et un anneau.',NULL,'Tous deux en forêt de conifères, le bolet jaune sous le pin sylvestre.',NULL,'Peler la cuticule du chapeau du bolet jaune.','{"Cèpe: pied lisse; bolet jaune: anneau + chapeau visqueux"}','t'),
('steinpilz','butterpilz','it','Porcino: gambo con reticolo bianco, senza anello. Pinarolo: cappello vischioso, con anello.',NULL,'Entrambi nel bosco di conifere, il pinarolo sotto il pino silvestre.',NULL,'Staccare la pellicola del cappello del pinarolo.','{"Porcino: gambo liscio; pinarolo: anello + cappello vischioso"}','t'),
('steinpilz','caloboletus_calopus','en','Bitter beech bolete: clay-grey cap, bright red netted stem, blue-staining flesh. Porcini (cep): brown cap, beige netted stem, flesh staying white.','Porcini with a pleasant mushroomy smell; bitter beech bolete inconspicuous - the bitter taste decides.','Both in mixed conifer/broadleaf forest; habitat does not separate them reliably.','Both have an olive-brown spore print - NO distinguishing feature.','Taste test (tiny piece of the tube layer on the tongue, do NOT swallow, spit out): bitter plus red stem net plus blue-staining = bitter beech bolete (gastrointestinally toxic/inedible), not a porcini.','{"The bitter beech bolete tastes extremely BITTER (bitter even after cooking, inedible) - the porcini tastes mild and nutty","The bitter beech bolete quickly stains blue-green in flesh and tubes when cut; porcini flesh stays white and unchanged (does not stain blue)","The stem of the bitter beech bolete is strongly red with a fine net (red below, yellow above); the porcini stem is brown-beige with a pale net, NEVER red","The cap of the bitter beech bolete is clay-grey/grey-brown; the porcini is warm brown to chestnut brown","Tubes/pores of the porcini white to yellow-green without blue-staining; in the poisonous mushroom yellow and blue-staining on pressure"}','f'),
('steinpilz','caloboletus_calopus','es','Boleto de pie hermoso: sombrero gris arcilloso, pie reticulado rojo intenso, carne que azulea. Boleto comestible (porcini): sombrero pardo, pie reticulado beige, carne que permanece blanca.','Boleto comestible con agradable olor a hongo; boleto de pie hermoso poco llamativo - el sabor amargo decide.','Ambos en bosque mixto de coníferas/frondosas; el hábitat no distingue de forma fiable.','Ambos esporada pardo-oliva - NINGÚN rasgo distintivo.','Prueba de sabor (trocito diminuto de la capa de tubos sobre la lengua, NO tragar, escupir): amargo más red roja en el pie más azulamiento = boleto de pie hermoso (tóxico gastrointestinal/no comestible), no un boleto comestible.','{"El boleto de pie hermoso sabe extremadamente AMARGO (amargo incluso tras la cocción, no comestible) - el boleto comestible sabe suave y a nuez","El boleto de pie hermoso azulea rápidamente a azul-verdoso en carne y tubos al herirlo; la carne del boleto comestible permanece blanca e inalterada (no azulea)","El pie del boleto de pie hermoso es de un rojo intenso con red fina (rojo abajo, amarillo arriba); el pie del boleto comestible es pardo-beige con red clara, NUNCA rojo","El sombrero del boleto de pie hermoso es gris arcilloso/gris-pardo; el boleto comestible es pardo cálido hasta pardo castaño","Tubos/poros del boleto comestible blancos a amarillo-verdoso sin azulear; en el hongo venenoso amarillos y azuleantes a la presión"}','f'),
('steinpilz','caloboletus_calopus','fr','Bolet à beau pied : chapeau gris argileux, pied réticulé rouge vif, chair bleuissante. Cèpe : chapeau brun, pied réticulé beige, chair restant blanche.','Cèpe à odeur agréable de champignon ; bolet à beau pied discret - le goût amer tranche.','Les deux en forêt mixte de conifères/feuillus ; l''habitat ne distingue pas de façon fiable.','Les deux ont une sporée brun olive - AUCUN critère de distinction.','Épreuve gustative (minuscule morceau de la couche de tubes sur la langue, NE PAS avaler, recracher) : amer plus réseau rouge sur le pied plus bleuissement = bolet à beau pied (toxique gastro-intestinal/immangeable), pas un cèpe.','{"Le bolet à beau pied a un goût extrêmement AMER (amer même après cuisson, immangeable) - le cèpe a un goût doux et de noisette","Le bolet à beau pied bleuit rapidement en bleu-vert à la chair et aux tubes en cas de blessure ; la chair du cèpe reste blanche et inchangée (ne bleuit pas)","Le pied du bolet à beau pied est franchement rouge avec un fin réseau (rouge en bas, jaune en haut) ; le pied du cèpe est brun-beige avec un réseau clair, JAMAIS rouge","Le chapeau du bolet à beau pied est gris argileux/gris-brun ; le cèpe est brun chaud à brun châtaigne","Les tubes/pores du cèpe sont blancs à jaune-vert sans bleuir ; chez le champignon toxique ils sont jaunes et bleuissent à la pression"}','f'),
('steinpilz','caloboletus_calopus','it','Boleto dal bel piede: cappello grigio argilloso, gambo reticolato rosso vivo, carne virante al blu. Porcino: cappello bruno, gambo reticolato beige, carne che resta bianca.','Porcino con gradevole odore fungino; boleto dal bel piede inappariscente - il sapore amaro è decisivo.','Entrambi in bosco misto di conifere/latifoglie; l''habitat non distingue in modo affidabile.','Entrambi sporata bruno-olivacea - NESSUN criterio distintivo.','Prova di sapore (minuscolo pezzo dello strato dei tubuli sulla lingua, NON ingoiare, sputare): amaro più reticolo rosso sul gambo più viraggio al blu = boleto dal bel piede (tossico gastrointestinale/immangiabile), non un porcino.','{"Il boleto dal bel piede ha sapore estremamente AMARO (amaro anche dopo la cottura, immangiabile) - il porcino ha sapore mite e di nocciola","Il boleto dal bel piede vira rapidamente al blu-verde nella carne e nei tubuli alla lesione; la carne del porcino resta bianca e immutata (non vira al blu)","Il gambo del boleto dal bel piede è di un rosso intenso con fine reticolo (rosso in basso, giallo in alto); il gambo del porcino è bruno-beige con reticolo chiaro, MAI rosso","Il cappello del boleto dal bel piede è grigio argilloso/grigio-bruno; il porcino è bruno caldo fino a bruno castagna","Tubuli/pori del porcino bianchi fino a giallo-verde senza virare al blu; nel fungo velenoso gialli e viranti al blu alla pressione"}','f'),
('steinpilz','roehrling_flockenstielig','en','Red stem net + blue-staining yellow pore surface in the bitter beech bolete vs. white net + stably white flesh and non-staining tubes in the porcini.','Both pleasantly mushroomy; the taste test decides — bitter beech bolete bitter, porcini mild and nutty.','Large overlap in mixed/coniferous forest — location does not separate them reliably.','Both olive-brown — no distinguishing feature.','Mnemonic: if the flesh/pores stain blue or the stem net is red, it is not a porcini. In the porcini the flesh stays white and the net pale — any blue-staining or red net = not a porcini, not in the basket.','{"The bitter beech bolete tastes bitter and its flesh STAINS BLUE when cut; the porcini tastes nutty-mild and its flesh stays white/unchanged (does not stain blue)","The bitter beech bolete has a distinctly RED net/red area on the stem; the porcini has a white to pale-brown net on a pale stem","Bitter beech bolete pores yellow (staining blue on pressure); porcini tubes white → yellow → olive-green, without staining blue","Bitter beech bolete cap clay-grey/grey-brown matt; porcini cap warm light to dark brown, often greasy and shiny","Taste sample: bitter beech bolete bitter, porcini mild — a reliable separating criterion"}','f'),
('steinpilz','roehrling_flockenstielig','es','Red roja en el pie + superficie de poros amarilla azuleante en el boleto de pie hermoso vs. red blanca + carne establemente blanca y tubos no azuleantes en el boleto comestible.','Ambos con agradable olor a hongo; la prueba de sabor decide — boleto de pie hermoso amargo, boleto comestible suave y a nuez.','Gran solapamiento en bosque mixto/de coníferas — la estación no distingue de forma fiable.','Ambos pardo-oliva — ningún rasgo distintivo.','Regla mnemotécnica: si la carne/los poros azulean o la red del pie es roja, no es un boleto comestible. En el boleto comestible la carne permanece blanca y la red clara — cualquier azulamiento o red roja = no es boleto comestible, no a la cesta.','{"El boleto de pie hermoso sabe amargo y su carne AZULEA al corte; el boleto comestible sabe a nuez suave y su carne permanece blanca/inalterada (no azulea)","El boleto de pie hermoso tiene una red/zona claramente ROJA en el pie; el boleto comestible tiene una red de blanca a pardo claro sobre pie claro","Poros del boleto de pie hermoso amarillos (azuleantes a la presión); tubos del boleto comestible blancos → amarillos → verde oliva, sin azulear","Sombrero del boleto de pie hermoso gris arcilloso/gris-pardo mate; sombrero del boleto comestible pardo claro a oscuro cálido, a menudo lustroso y graso","Cata de sabor: boleto de pie hermoso amargo, boleto comestible suave — criterio de separación seguro"}','f'),
('steinpilz','roehrling_flockenstielig','fr','Réseau rouge sur le pied + champ de pores jaune bleuissant chez le bolet à beau pied vs. réseau blanc + chair restant blanche et tubes ne bleuissant pas chez le cèpe.','Les deux à odeur agréable de champignon ; le test gustatif tranche — bolet à beau pied amer, cèpe doux et de noisette.','Grande superposition en forêt mixte/de conifères — la station ne distingue pas de façon fiable.','Les deux brun olive — aucun critère de distinction.','Aide-mémoire : si la chair/les pores bleuissent ou si le réseau du pied est rouge, ce n''est pas un cèpe. Chez le cèpe la chair reste blanche et le réseau clair — tout bleuissement ou réseau rouge = pas un cèpe, pas dans le panier.','{"Le bolet à beau pied a un goût amer et sa chair BLEUIT à la coupe ; le cèpe a un goût doux de noisette et sa chair reste blanche/inchangée (ne bleuit pas)","Le bolet à beau pied a un réseau/une zone nettement ROUGE sur le pied ; le cèpe a un réseau blanc à brun clair sur un pied clair","Pores du bolet à beau pied jaunes (bleuissant à la pression) ; tubes du cèpe blancs → jaunes → vert olive, sans bleuir","Chapeau du bolet à beau pied gris argileux/gris-brun mat ; chapeau du cèpe brun clair à foncé chaud, souvent luisant et gras","Dégustation : bolet à beau pied amer, cèpe doux — critère de séparation sûr"}','f'),
('steinpilz','roehrling_flockenstielig','it','Reticolo rosso sul gambo + campo dei pori giallo virante al blu nel boleto dal bel piede vs. reticolo bianco + carne stabilmente bianca e tubuli non viranti nel porcino.','Entrambi con gradevole odore fungino; il test del gusto è decisivo — boleto dal bel piede amaro, porcino mite e di nocciola.','Ampia sovrapposizione in bosco misto/di conifere — la stazione non distingue in modo affidabile.','Entrambi bruno-olivacei — nessun criterio distintivo.','Promemoria: se la carne/i pori virano al blu o se il reticolo del gambo è rosso, non è un porcino. Nel porcino la carne resta bianca e il reticolo chiaro — qualsiasi viraggio al blu o reticolo rosso = non porcino, non nel cesto.','{"Il boleto dal bel piede ha sapore amaro e la sua carne VIRA AL BLU al taglio; il porcino ha sapore di nocciola mite e la sua carne resta bianca/immutata (non vira al blu)","Il boleto dal bel piede ha un reticolo/una zona nettamente ROSSA sul gambo; il porcino ha un reticolo da bianco a bruno chiaro su gambo chiaro","Pori del boleto dal bel piede gialli (viranti al blu alla pressione); tubuli del porcino bianchi → gialli → verde olivastro, senza virare al blu","Cappello del boleto dal bel piede grigio argilloso/grigio-bruno opaco; cappello del porcino bruno chiaro fino a scuro caldo, spesso lucido e untuoso","Assaggio: boleto dal bel piede amaro, porcino mite — criterio di separazione sicuro"}','f'),
('steinpilz','rubroboletus_satanas','en','The decisive feature is pore colour: red/orange in the Devil''s bolete, never in the porcino (cep) — plus the red stem net instead of a white net, and the faint bluing instead of no colour change at all.','The old Devil''s bolete stinks of carrion/rot, the cep smells pleasantly nutty and mushroomy.','Both in warm deciduous woods on lime under oak/beech — the habitat does not separate them reliably.','Both have an olive-brown spore print — no practical distinguishing feature.','Always leave behind any bolete with even a hint of red/orange pores — a true cep NEVER has red pores.','{"The Devil''s bolete has RED to orange-red pores; the cep NEVER has red pores (white when young, then yellowish-olive).","The Devil''s bolete''s flesh bluish only weakly to moderately when cut; the cep''s flesh stays completely white and does not change colour.","The Devil''s bolete has a distinctly red, close-meshed stem net on a yellow ground (later blood-red) on a bulbous-tuberous stem; the cep has a fine white to brownish net.","The mature/old Devil''s bolete smells repulsively of carrion; the cep smells pleasantly mushroomy and nutty.","Both have a pale, whitish-grey-green to chalk-white cap when young — the pale cap colour alone must NEVER be used for identification."}','f'),
('steinpilz','rubroboletus_satanas','es','El criterio decisivo es el color de los poros: rojo/naranja en el boleto de Satanás, nunca en el cep (boletus edulis) — además de la red roja del pie en lugar de la red blanca, y el ligero azuleamiento en lugar de no cambiar de color.','El boleto de Satanás viejo apesta a carroña/putrefacción, el cep huele agradablemente a avellana y a champiñón.','Ambos en bosques caducifolios cálidos sobre caliza bajo roble/haya — el hábitat no los distingue de forma fiable.','Ambos esporada pardo-oliva — ningún criterio de distinción práctico.','Dejar siempre en el sitio cualquier boleto con poros aunque sea levemente rojizos/anaranjados — un cep verdadero NUNCA tiene poros rojos.','{"El boleto de Satanás tiene poros ROJOS hasta rojo anaranjado; el cep NUNCA tiene poros rojos (blancos de joven, luego amarillento-oliva).","La carne del boleto de Satanás al corte azulea solo débil a moderadamente; la carne del cep permanece completamente blanca y no cambia de color.","El boleto de Satanás tiene una red claramente roja, de malla densa sobre fondo amarillo (más tarde rojo sangre) en el pie ventrudo-bulboso; el cep tiene una red fina blanca a parduzca.","El boleto de Satanás maduro/viejo huele repugnantemente a carroña; el cep huele agradablemente a champiñón y avellana.","Ambos tienen de jóvenes un sombrero claro, blanquecino-gris-verde a blanco calizo — el color claro del sombrero por sí solo NUNCA debe servir para la identificación."}','f'),
('steinpilz','rubroboletus_satanas','fr','Le critère décisif est la couleur des pores : rouge/orange chez le bolet Satan, jamais chez le cèpe — plus le réseau rouge sur le pied au lieu d''un réseau blanc, et le léger bleuissement au lieu d''aucun changement de couleur.','Le vieux bolet Satan empeste la charogne/la putréfaction, le cèpe sent agréablement la noisette et le champignon.','Tous deux dans les forêts feuillues chaudes sur calcaire sous chêne/hêtre — l''habitat ne permet pas de les distinguer de façon fiable.','Tous deux une sporée brun-olive — aucun critère de distinction pratique.','Laisser systématiquement sur place tout bolet présentant ne serait-ce qu''une nuance de pores rouges/orange — un vrai cèpe n''a JAMAIS de pores rouges.','{"Le bolet Satan a des pores ROUGES à rouge orangé ; le cèpe n''a JAMAIS de pores rouges (blancs jeunes, puis jaunâtre-olive).","La chair du bolet Satan bleuit faiblement à modérément à la coupe ; la chair du cèpe reste entièrement blanche et ne change pas de couleur.","Le bolet Satan a un réseau nettement rouge, à mailles serrées sur fond jaune (plus tard rouge sang) sur un pied ventru-bulbeux ; le cèpe a un fin réseau blanc à brunâtre.","Le bolet Satan mûr/vieux dégage une odeur répugnante de charogne ; le cèpe sent agréablement le champignon et la noisette.","Tous deux ont jeune un chapeau clair, blanchâtre-gris-vert à blanc calcaire — la couleur claire du chapeau seule ne doit JAMAIS servir à l''identification."}','f'),
('steinpilz','rubroboletus_satanas','it','Il criterio decisivo è il colore dei pori: rosso/arancione nel boleto di Satana, mai nel porcino — più il reticolo rosso sul gambo invece del reticolo bianco e il leggero viraggio al blu invece di nessun cambiamento di colore.','Il vecchio boleto di Satana puzza di carogna/putrefazione, il porcino profuma gradevolmente di nocciola e di fungo.','Entrambi nei boschi di latifoglie caldi su calcare sotto quercia/faggio — l''habitat non li distingue in modo affidabile.','Entrambi sporata bruno-olivacea — nessun criterio di distinzione pratico.','Lasciare sempre sul posto ogni boleto con pori anche solo accennati al rosso/arancione — un vero porcino non ha MAI pori rossi.','{"Il boleto di Satana ha pori ROSSI fino a rosso-arancio; il porcino non ha MAI pori rossi (da giovane bianchi, poi giallastro-olivacei).","La carne del boleto di Satana al taglio vira al blu solo debolmente o moderatamente; la carne del porcino rimane completamente bianca e non cambia colore.","Il boleto di Satana ha un reticolo nettamente rosso a maglie fitte su fondo giallo (più tardi rosso sangue) sul gambo ventricoso-bulboso; il porcino ha un reticolo fine bianco fino a brunastro.","Il boleto di Satana maturo/vecchio emana un odore disgustoso di carogna; il porcino profuma gradevolmente di fungo e nocciola.","Entrambi da giovani hanno un cappello chiaro, biancastro-grigio-verde fino a bianco calce — il colore chiaro del cappello da solo non deve MAI servire all''identificazione."}','f'),
('steinpilz','tylopilus_felleus','en','Pore colour (white/yellow vs. pink) + netting (fine-white vs. coarse-dark).','Bitter bolete (Tylopilus felleus) is extremely bitter (tiny taste sample, spit it out)','Both in acidic coniferous/mixed forests, often together','Porcini olive, bitter bolete pink','Not poisonous, but a single bitter bolete ruins an entire dish. Pink pores + coarse netting + bitterness give it away.','{"Porcini: fine white netting, white/yellow pores, mild","Bitter bolete: coarse dark netting, pink pores, extremely bitter"}','t'),
('steinpilz','tylopilus_felleus','es','Color de los tubos (blanco/amarillo frente a rosa) + retículo (fino y blanco frente a grueso y oscuro).','Tylopilus felleus (boleto de hiel) extremadamente amargo (probar una porción mínima y escupirla).','Ambos en bosques de coníferas/mixtos de suelo ácido, a menudo juntos.','Boletus (Steinpilz) oliva; Tylopilus felleus (boleto de hiel) rosa.','No es venenoso, pero un solo boleto de hiel arruina un plato entero. Los tubos rosados + el retículo grueso + el amargor lo delatan.','{"Boletus (Steinpilz): retículo fino y blanco, tubos blancos/amarillos, sabor suave","Tylopilus felleus (boleto de hiel): retículo grueso y oscuro, tubos rosados, extremadamente amargo"}','t'),
('steinpilz','tylopilus_felleus','fr','Couleur des tubes (blanc/jaune vs rose) + réseau (fin et blanc vs grossier et foncé).','Le bolet amer (Tylopilus felleus) est extrêmement amer (en goûter une toute petite quantité, puis recracher).','Tous deux dans les forêts acides de conifères ou mixtes, souvent ensemble.','Cèpe: olive; bolet amer: rose.','Pas toxique, mais un seul bolet amer gâte tout un plat. Les tubes roses + le réseau grossier + l''amertume le démasquent.','{"Cèpe: réseau fin et blanc, tubes blancs/jaunes, doux","Bolet amer: réseau grossier et foncé, tubes roses, extrêmement amer"}','t'),
('steinpilz','tylopilus_felleus','it','Colore dei tubuli (bianco/giallo contro rosa) + reticolo (fine-bianco contro grossolano-scuro).','Il boleto del fiele (Tylopilus felleus) è estremamente amaro (assaggio minimo, sputare).','Entrambi in boschi acidi di conifere/misti, spesso insieme.','Porcino oliva, boleto del fiele rosa.','Non velenoso, ma un solo boleto del fiele rovina un intero piatto. Tubuli rosa + reticolo grossolano + amarezza lo smascherano.','{"Porcino: reticolo bianco fine, tubuli bianchi/gialli, dolce","Boleto del fiele: reticolo scuro grossolano, tubuli rosa, estremamente amaro"}','t'),
('suillellus_luridus','caloboletus_calopus','en','Lurid bolete (netted-stem): red-orange pores, red stem net, Batsch line. Bitter beech bolete (Caloboletus calopus): yellow pores, grey cap, red-yellow netted stem.','Both inconspicuous — the bitter taste of the Caloboletus calopus is the separating feature.','Both with broadleaf trees; the lurid bolete prefers lime-rich soil. Habitat does not separate them reliably.','Both have an olive-brown spore print — NO distinguishing feature.','Check the pores AND do a taste test (spit out): yellow pores plus bitter = Caloboletus calopus (discard); red/orange pores without bitterness = lurid bolete — this one is toxic raw and edible only when thoroughly cooked, never taste it raw except for the spit-out taste test.','{"The Caloboletus calopus tastes strongly BITTER (inedible/gastrointestinal-toxic even when cooked); the lurid bolete is mild, but edible ONLY when thoroughly cooked (toxic raw).","The lurid bolete has RED-ORANGE pores and a reddish line (Batsch line) above the tubes; the Caloboletus calopus has yellow pores.","The lurid bolete''s cap is olive-brown/leather-brown, often cushion-shaped; the Caloboletus calopus is clay-grey.","Both bruise strongly blue — but the lurid bolete with red pores and a red net on a brownish-yellow stem, the Caloboletus calopus with yellow pores and a red-yellow stem.","Taste decides: Caloboletus calopus is bitter (discard); the lurid bolete is mild and edible only after sufficient cooking."}','f'),
('suillellus_luridus','caloboletus_calopus','es','Boleto lúrido (de pie reticulado): poros rojo-anaranjados, red roja en el pie, línea de Batsch. Boleto de pie bonito (Caloboletus calopus): poros amarillos, sombrero gris, pie reticulado rojo-amarillo.','Ambos discretos — el sabor amargo del boleto de pie bonito es el criterio de separación.','Ambos junto a frondosas; el boleto lúrido prefiere suelos calcáreos. El hábitat no separa de forma fiable.','Ambos esporada pardo-oliva — NINGÚN criterio de distinción.','Comprobar los poros Y hacer una prueba de sabor (escupir): poros amarillos más amargo = boleto de pie bonito (descartar); poros rojos/anaranjados sin amargor = boleto lúrido — este es tóxico crudo y comestible solo bien cocinado, nunca probarlo crudo salvo para la prueba de sabor en la que se escupe.','{"El boleto de pie bonito sabe fuertemente AMARGO (incomible/tóxico gastrointestinal incluso cocinado); el boleto lúrido es suave, pero comestible SOLO bien cocinado (tóxico crudo).","El boleto lúrido tiene poros ROJO-ANARANJADOS y una línea rojiza (línea de Batsch) sobre los tubos; el boleto de pie bonito tiene poros amarillos.","El sombrero del boleto lúrido es pardo-oliva/pardo-cuero, a menudo acolchado; el boleto de pie bonito es gris-arcilla.","Ambos azulean fuertemente — pero el boleto lúrido con poros rojos y red roja sobre pie parduzco-amarillo, el boleto de pie bonito con poros amarillos y pie rojo-amarillo.","El sabor decide: el pie bonito es amargo (descartar); el boleto lúrido es suave y comestible solo tras una cocción suficiente."}','f'),
('suillellus_luridus','caloboletus_calopus','fr','Bolet blafard (à pied réticulé) : pores rouge-orange, réseau rouge sur le pied, ligne de Batsch. Bolet à beau pied : pores jaunes, chapeau gris, pied réticulé rouge-jaune.','Tous deux discrets — le goût amer du bolet à beau pied est le critère de séparation.','Tous deux sous feuillus ; le bolet blafard préfère les sols calcaires. L''habitat ne sépare pas de façon fiable.','Tous deux sporée brun-olive — AUCUN critère de distinction.','Vérifier les pores ET faire un test gustatif (recracher) : pores jaunes plus goût amer = bolet à beau pied (à écarter) ; pores rouges/orange sans amertume = bolet blafard — celui-ci est toxique cru et comestible uniquement bien cuit, ne jamais le goûter cru sauf pour le test gustatif où l''on recrache.','{"Le bolet à beau pied a un goût fortement AMER (immangeable/toxique gastro-intestinal même cuit) ; le bolet blafard est doux, mais comestible UNIQUEMENT bien cuit (toxique cru).","Le bolet blafard a des pores ROUGE-ORANGE et une ligne rougeâtre (ligne de Batsch) au-dessus des tubes ; le bolet à beau pied a des pores jaunes.","Le chapeau du bolet blafard est brun-olive/brun-cuir, souvent en coussin ; le bolet à beau pied est gris-argile.","Tous deux bleuissent fortement — mais le bolet blafard avec des pores rouges et un réseau rouge sur un pied brunâtre-jaune, le bolet à beau pied avec des pores jaunes et un pied rouge-jaune.","Le goût décide : le beau pied est amer (à écarter) ; le bolet blafard est doux et comestible seulement après une cuisson suffisante."}','f'),
('suillellus_luridus','caloboletus_calopus','it','Boleto lurido (a gambo reticolato): pori rosso-arancio, reticolo rosso sul gambo, linea di Batsch. Boleto dal bel piede: pori gialli, cappello grigio, gambo reticolato rosso-giallo.','Entrambi poco appariscenti — il sapore amaro del boleto dal bel piede è il criterio distintivo.','Entrambi presso latifoglie; il boleto lurido predilige suoli calcarei. L''habitat non separa in modo affidabile.','Entrambi sporata bruno-olivacea — NESSUN criterio di distinzione.','Controllare i pori E fare una prova di sapore (sputare): pori gialli più amaro = boleto dal bel piede (da scartare); pori rossi/arancio senza amaro = boleto lurido — quest''ultimo è tossico crudo e commestibile solo ben cotto, non assaggiarlo mai crudo se non per la prova di sapore con sputo.','{"Il boleto dal bel piede ha un sapore fortemente AMARO (immangiabile/tossico gastrointestinale anche cotto); il boleto lurido è dolce, ma commestibile SOLO ben cotto (tossico crudo).","Il boleto lurido ha pori ROSSO-ARANCIO e una linea rossastra (linea di Batsch) sopra i tubuli; il boleto dal bel piede ha pori gialli.","Il cappello del boleto lurido è bruno-olivaceo/bruno-cuoio, spesso pulvinato; il boleto dal bel piede è grigio-argilla.","Entrambi virano fortemente al blu — ma il boleto lurido con pori rossi e reticolo rosso su gambo brunastro-giallo, il boleto dal bel piede con pori gialli e gambo rosso-giallo.","Il sapore decide: il bel piede è amaro (da scartare); il boleto lurido è dolce e commestibile solo dopo cottura sufficiente."}','f'),
('suillellus_luridus','rubroboletus_legaliae','en','Pale whitish/grey-pink cap in Le Gal''s bolete vs ochre/brick-red-dark-olive cap in the lurid bolete; in Le Gal''s NO bluing of the cap cuticle, in the lurid bolete strong bluing.','Le Gal''s distinctly of celery/lovage; the lurid bolete neutral in smell.','Le Gal''s rare, warmth-loving under old oaks/beeches on lime; the lurid bolete more frequent in deciduous/mixed woodland on lime — overlap possible, the site does not separate them with certainty.','Both olive-brown spore print — no separating feature.','Take red-pored boletes only as an experienced forager: pale/pink cap + celery smell + only faint bluing = Le Gal/Satan group, toxic. The so-called Bataille line (red line above the tubes) is NOT a reliable identification feature — it is absent in many true lurid boletes and is overrated. When in doubt, leave it standing.','{"Le Gal''s bolete (Rubroboletus legaliae) has a pale, whitish/grey to wine-pink-old-rose cap; the lurid bolete has an ochre-brown to brick-red-dark-olive cap.","Le Gal''s smells conspicuously spicy of lovage/celery/chicory; the lurid bolete smells neutral, mushroomy.","Le Gal''s bluish only weakly/moderately in the flesh and NOT in the cap cuticle; the lurid bolete bluish immediately and strongly dark blue (cap cuticle/flesh too).","Both have red/carmine pores and a stem net — these features do NOT separate them; decisive are cap colour, celery smell and bluing intensity.","Le Gal''s is toxic/intolerable even well heated (severe gastrointestinal disturbances reported); the lurid bolete is toxic ONLY raw, edible after sufficient heating (even then not with alcohol)."}','f'),
('suillellus_luridus','rubroboletus_legaliae','es','Sombrero pálido blanco/gris-rosado en el boleto de Le Gal vs sombrero ocre/rojo-ladrillo-verde oliva oscuro en el boleto lúrido; en el Le Gal NINGÚN azuleamiento de la cutícula, en el boleto lúrido fuerte azuleamiento.','Le Gal claramente a olor de apio/levístico; el boleto lúrido neutro olfativamente.','Le Gal raro, termófilo bajo viejos robles/hayas sobre caliza; el boleto lúrido más frecuente en bosque caducifolio/mixto sobre caliza — solapamiento posible, el lugar no separa con certeza.','Ambos esporada pardo-oliva — ningún criterio de separación.','Recoger boletos de poros rojos solo como recolector experimentado: sombrero pálido/rosado + olor a apio + azuleamiento solo débil = grupo Le Gal/Satanás, tóxico. La llamada línea de Bataille (línea roja sobre los tubos) NO es un criterio de identificación fiable — falta en muchos boletos lúridos verdaderos y está sobrevalorada. En caso de duda, dejar en el sitio.','{"El boleto de Le Gal (Rubroboletus legaliae) tiene un sombrero pálido, blanquecino/gris hasta rosa vinoso-rosa viejo; el boleto lúrido tiene un sombrero ocre-pardo hasta rojo-ladrillo-verde oliva oscuro.","Le Gal huele de forma llamativa y especiada a levístico/apio/achicoria; el boleto lúrido huele neutro, a champiñón.","Le Gal azulea solo débil/moderadamente en la carne y NO en la cutícula; el boleto lúrido azulea de inmediato e intensamente en azul oscuro (también cutícula/carne).","Ambos tienen poros rojos/rojo carmín y una red en el pie — estos caracteres NO los separan; decisivos son el color del sombrero, el olor a apio y la intensidad del azuleamiento.","Le Gal es tóxico/indigesto incluso bien calentado (se han notificado trastornos gastrointestinales graves); el boleto lúrido es tóxico SOLO crudo, comestible tras un calentamiento suficiente (ni siquiera entonces con alcohol)."}','f'),
('suillellus_luridus','rubroboletus_legaliae','fr','Chapeau pâle blanc/gris-rosé chez le bolet de Le Gal vs chapeau ocre/rouge-brique-vert olive foncé chez le bolet blafard ; chez Le Gal AUCUN bleuissement de la cuticule, chez le bolet blafard fort bleuissement.','Le Gal nettement odeur de céleri/livèche ; le bolet blafard neutre du point de vue olfactif.','Le Gal rare, thermophile sous vieux chênes/hêtres sur calcaire ; le bolet blafard plus fréquent en forêt feuillue/mixte sur calcaire — chevauchement possible, le site ne sépare pas avec certitude.','Tous deux sporée brun-olive — pas de critère de séparation.','Ne prendre les bolets à pores rouges qu''en tant que cueilleur expérimenté : chapeau pâle/rosé + odeur de céleri + bleuissement seulement faible = groupe Le Gal/Satan, toxique. La fameuse ligne de Bataille (ligne rouge au-dessus des tubes) n''est PAS un critère d''identification fiable — elle manque à beaucoup de vrais bolets blafards et est surestimée. En cas de doute, laisser sur place.','{"Le bolet de Le Gal (Rubroboletus legaliae) a un chapeau pâle, blanchâtre/gris à rose vineux-vieux rose ; le bolet blafard a un chapeau ocre-brun à rouge-brique-vert olive foncé.","Le Gal sent de façon marquée et épicée la livèche/le céleri/la chicorée ; le bolet blafard sent neutre, comme un champignon.","Le Gal bleuit seulement faiblement/modérément dans la chair et PAS dans la cuticule ; le bolet blafard bleuit aussitôt fortement en bleu foncé (cuticule/chair également).","Tous deux ont des pores rouges/rouge carmin et un réseau sur le pied — ces caractères ne séparent PAS ; ce qui est décisif, c''est la couleur du chapeau, l''odeur de céleri et l''intensité du bleuissement.","Le Gal est toxique/indigeste même bien chauffé (graves troubles gastro-intestinaux signalés) ; le bolet blafard est toxique UNIQUEMENT cru, comestible après une cuisson suffisante (même alors pas avec de l''alcool)."}','f'),
('suillellus_luridus','rubroboletus_legaliae','it','Cappello pallido bianco/grigio-rosato nel boleto di Le Gal vs cappello ocra/rosso-mattone-verde oliva scuro nel boleto lurido; nel Le Gal NESSUN viraggio al blu della cuticola, nel boleto lurido forte viraggio al blu.','Le Gal odore netto di sedano/levistico; il boleto lurido neutro dal punto di vista olfattivo.','Le Gal raro, termofilo sotto vecchie querce/faggi su calcare; il boleto lurido più frequente in bosco di latifoglie/misto su calcare — sovrapposizione possibile, il sito non separa con certezza.','Entrambi sporata bruno-olivacea — nessun criterio distintivo.','Raccogliere i boleti a pori rossi solo da raccoglitori esperti: cappello pallido/rosato + odore di sedano + viraggio solo debole = gruppo Le Gal/Satana, tossico. La cosiddetta linea di Bataille (linea rossa sopra i tubuli) NON è un criterio di identificazione affidabile — manca a molti veri boleti luridi ed è sopravvalutata. In caso di dubbio, lasciare sul posto.','{"Il boleto di Le Gal (Rubroboletus legaliae) ha un cappello pallido, biancastro/grigio fino a rosa vinoso-rosa antico; il boleto lurido ha un cappello ocra-bruno fino a rosso-mattone-verde oliva scuro.","Le Gal odora in modo marcato e speziato di levistico/sedano/cicoria; il boleto lurido odora neutro, di fungo.","Le Gal vira al blu solo debolmente/moderatamente nella carne e NON nella cuticola; il boleto lurido vira subito intensamente al blu scuro (anche cuticola/carne).","Entrambi hanno pori rossi/rosso carminio e un reticolo sul gambo — questi caratteri NON separano; decisivi sono il colore del cappello, l''odore di sedano e l''intensità del viraggio al blu.","Le Gal è tossico/indigesto anche ben riscaldato (segnalati gravi disturbi gastrointestinali); il boleto lurido è tossico SOLO crudo, commestibile dopo cottura sufficiente (anche allora non con alcol)."}','f'),
('suillellus_luridus','rubroboletus_satanas','en','Pale whitish-grey cap in the Devil''s bolete vs olive-yellow-brown cap in the lurid bolete; the lurid bolete bluish immediately and intensely, the Devil''s bolete only weakly.','Devil''s bolete when old of carrion, the netted-stem lurid bolete neutral, mushroomy.','Both on lime under broadleaf trees — no reliable separating feature.','Both olive-brown — not separating.','Eat red-pored boletes only if identified beyond doubt as the edible lurid bolete AND thoroughly heated — when in doubt, to the mushroom inspection (VAPKO).','{"The netted-stem lurid bolete bluish QUICKLY and intensely deep blue when cut; the Devil''s bolete bluish only weakly/with delay.","The netted-stem lurid bolete has an olive-yellow to grey-brown cap; the Devil''s bolete when young a pale, chalk-white-grey-green cap.","Both have red/orange-red pores AND a red stem net — the red pore colour does NOT separate them, only bluing speed, cap colour and smell.","The Devil''s bolete smells repulsively of carrion with age; the netted-stem lurid bolete smells neutral, mushroomy.","The netted-stem lurid bolete is toxic/intolerable raw and edible only when well heated; the Devil''s bolete remains toxic even when cooked."}','f'),
('suillellus_luridus','rubroboletus_satanas','es','Sombrero claro blanquecino-gris en el boleto de Satanás vs sombrero amarillo-oliva-pardo en el boleto lúrido; el boleto lúrido azulea de inmediato e intensamente, el boleto de Satanás solo débilmente.','Boleto de Satanás viejo a carroña, el boleto lúrido de pie reticulado neutro, a champiñón.','Ambos sobre caliza bajo frondosas — ningún criterio de separación seguro.','Ambos pardo-oliva — no distintivo.','Comer boletos de poros rojos solo si se identifican sin lugar a dudas como boleto lúrido comestible Y bien calentados — en caso de duda, al control de setas (VAPKO).','{"El boleto lúrido de pie reticulado al corte azulea RÁPIDAMENTE e intensamente en azul profundo; el boleto de Satanás azulea solo débilmente/con retraso.","El boleto lúrido de pie reticulado tiene un sombrero amarillo-oliva a gris-pardo; el boleto de Satanás de joven un sombrero claro, blanco calizo-gris-verde.","Ambos tienen poros rojos/rojo anaranjado Y una red roja en el pie — el color rojo de los poros NO los separa, solo la velocidad del azuleamiento, el color del sombrero y el olor.","El boleto de Satanás con la edad huele repugnantemente a carroña; el boleto lúrido de pie reticulado huele neutro, a champiñón.","El boleto lúrido de pie reticulado es tóxico/indigesto crudo y comestible solo bien calentado; el boleto de Satanás permanece tóxico incluso cocinado."}','f'),
('suillellus_luridus','rubroboletus_satanas','fr','Chapeau clair blanchâtre-gris chez le bolet Satan vs chapeau jaune-olive-brun chez le bolet blafard ; le bolet blafard bleuit aussitôt intensément, le bolet Satan seulement faiblement.','Bolet Satan vieux odeur de charogne, bolet blafard neutre, de champignon.','Tous deux sur calcaire sous feuillus — pas de critère de séparation sûr.','Tous deux brun-olive — non distinctif.','Ne manger les bolets à pores rouges que s''ils sont identifiés sans doute possible comme bolet blafard comestible ET bien cuits — en cas de doute, au contrôle des champignons (VAPKO).','{"Le bolet blafard bleuit à la coupe RAPIDEMENT et intensément en bleu profond ; le bolet Satan bleuit seulement faiblement/avec retard.","Le bolet blafard a un chapeau jaune-olive à gris-brun ; le bolet Satan jeune un chapeau clair, blanc calcaire-gris-vert.","Tous deux ont des pores rouges/rouge orangé ET un réseau rouge sur le pied — la couleur rouge des pores ne les sépare PAS, seules la vitesse de bleuissement, la couleur du chapeau et l''odeur.","Le bolet Satan sent avec l''âge de façon répugnante la charogne ; le bolet blafard sent neutre, de champignon.","Le bolet blafard est toxique/indigeste cru et comestible seulement bien cuit ; le bolet Satan reste toxique même cuit."}','f'),
('suillellus_luridus','rubroboletus_satanas','it','Cappello chiaro biancastro-grigio nel boleto di Satana vs cappello giallo-olivaceo-bruno nel boleto lurido; il boleto lurido vira subito intensamente al blu, il boleto di Satana solo debolmente.','Boleto di Satana vecchio odore di carogna, boleto lurido neutro, di fungo.','Entrambi su calcare sotto latifoglie — nessun criterio distintivo sicuro.','Entrambi bruno-olivacei — non distintivo.','Mangiare i boleti a pori rossi solo se identificati senza alcun dubbio come boleto lurido commestibile E ben cotti — in caso di dubbio, al controllo dei funghi (VAPKO).','{"Il boleto lurido al taglio vira RAPIDAMENTE e intensamente al blu profondo; il boleto di Satana vira solo debolmente/con ritardo.","Il boleto lurido ha un cappello giallo-olivaceo fino a grigio-bruno; il boleto di Satana da giovane un cappello chiaro, bianco calce-grigio-verde.","Entrambi hanno pori rossi/rosso-arancio E un reticolo rosso sul gambo — il colore rosso dei pori NON li separa, solo la velocità del viraggio al blu, il colore del cappello e l''odore.","Il boleto di Satana con l''età odora in modo disgustoso di carogna; il boleto lurido odora neutro, di fungo.","Il boleto lurido è tossico/indigesto crudo e commestibile solo ben cotto; il boleto di Satana rimane tossico anche cotto."}','f'),
('tricholoma_cingulatum','tricholoma_scalpturatum','en','cingulatum with a ring/veil zone on the stem, scalpturatum ringless and yellowing.','both mealy; cingulatum milder.','cingulatum by willows (often moist/floodplain forest), more rarely birches; scalpturatum widely in deciduous/mixed/coniferous forest and park stands.','Both white - not a distinguishing feature.','A distinct ring on the stem AND a willow/birch association argue for cingulatum; if the ring is missing and the flesh yellows, hands off. With grey earth knights in general, maximum caution (deadly tiger knight Tricholoma pardinum similar).','{"T. cingulatum (edible): has a distinct, membranous RING/veil zone on the stem - scalpturatum is ringless. The ring is the most important distinguishing feature from all other earth knights.","T. scalpturatum (suspected toxic/inferior, do NOT collect): no ring, gills and flesh yellow distinctly.","cingulatum lives in mycorrhiza with willows (Salix), more rarely birches (Betula) - often in moist/floodplain sites.","Smell of both mealy; cingulatum mild.","Ring zone present + willow/birch association = cingulatum; ringless + yellowing = scalpturatum."}','f'),
('tricholoma_cingulatum','tricholoma_scalpturatum','es','cingulatum con anillo/zona de velo en el pie, scalpturatum sin anillo y amarilleante.','ambos harinosos; cingulatum más suave.','cingulatum bajo los sauces (a menudo húmedo/bosque de ribera), más raramente abedules; scalpturatum ampliamente en bosque de frondosas/mixto/coníferas y masas de parques.','Ambos blancos - no es un criterio distintivo.','Un anillo neto en el pie Y una vinculación con sauce/abedul abogan por cingulatum; si falta el anillo y la carne amarillea, no tocar. En los Tricholoma terrosos grises en general, máxima prudencia (Tricholoma pardinum mortal, parecido).','{"T. cingulatum (comestible): posee un ANILLO/zona de velo membranoso neto en el pie - scalpturatum es sin anillo. El anillo es el carácter distintivo más importante respecto a todos los demás Tricholoma terrosos.","T. scalpturatum (sospechoso de toxicidad/inferior, NO recoger): sin anillo, láminas y carne amarillean netamente.","cingulatum vive en micorriza con los sauces (Salix), más raramente los abedules (Betula) - a menudo en estaciones húmedas/de ribera.","Olor de ambos harinoso; cingulatum suave.","Zona de anillo presente + vinculación sauce/abedul = cingulatum; sin anillo + amarilleante = scalpturatum."}','f'),
('tricholoma_cingulatum','tricholoma_scalpturatum','fr','cingulatum avec anneau/zone de voile au pied, scalpturatum sans anneau et jaunissant.','tous deux farineux ; cingulatum plus doux.','cingulatum sous les saules (souvent humide/forêt alluviale), plus rarement bouleaux ; scalpturatum largement en forêt de feuillus/mixte/conifères et peuplements de parcs.','Tous deux blancs - pas un critère de distinction.','Un anneau net au pied ET un lien avec saule/bouleau plaident pour cingulatum ; si l''anneau manque et que la chair jaunit, ne pas toucher. Chez les tricholomes terreux gris en général, prudence maximale (tricholome tigré mortel Tricholoma pardinum semblable).','{"T. cingulatum (comestible) : possède un ANNEAU/zone de voile membraneux net au pied - scalpturatum est sans anneau. L''anneau est le critère de distinction le plus important par rapport à tous les autres tricholomes terreux.","T. scalpturatum (suspect de toxicité/médiocre, NE PAS cueillir) : pas d''anneau, lames et chair jaunissent nettement.","cingulatum vit en mycorhize avec les saules (Salix), plus rarement les bouleaux (Betula) - souvent en stations humides/alluviales.","Odeur des deux farineuse ; cingulatum doux.","Zone d''anneau présente + lien saule/bouleau = cingulatum ; sans anneau + jaunissant = scalpturatum."}','f'),
('tricholoma_cingulatum','tricholoma_scalpturatum','it','cingulatum con anello/zona di velo al gambo, scalpturatum senza anello e ingiallente.','entrambi farinosi ; cingulatum più mite.','cingulatum sotto i salici (spesso umido/bosco golenale), più raramente betulle ; scalpturatum ampiamente in bosco di latifoglie/misto/conifere e popolamenti di parchi.','Entrambi bianchi - non un carattere distintivo.','Un anello netto al gambo E un legame con salice/betulla depongono per cingulatum ; se l''anello manca e la carne ingiallisce, non toccare. Nei Tricholoma terrei grigi in generale, massima prudenza (Tricholoma pardinum mortale, simile).','{"T. cingulatum (commestibile) : possiede un ANELLO/zona di velo membranoso netto al gambo - scalpturatum è senza anello. L''anello è il carattere distintivo più importante rispetto a tutti gli altri Tricholoma terrei.","T. scalpturatum (sospetto di tossicità/scadente, NON raccogliere) : nessun anello, lamelle e carne ingialliscono nettamente.","cingulatum vive in micorriza con i salici (Salix), più raramente le betulle (Betula) - spesso in stazioni umide/golenali.","Odore di entrambi farinoso ; cingulatum mite.","Zona d''anello presente + legame salice/betulla = cingulatum ; senza anello + ingiallente = scalpturatum."}','f'),
('tricholoma_columbetta','tricholoma_pardinum','en','The dove-coloured tricholoma (St George''s-grey relative) is pure silky-white and smooth; the tiger tricholoma (Tricholoma pardinum) is grey with a coarse dark scaly covering.','The dove tricholoma is mild to faintly mealy; the tiger tricholoma mealy/cucumber-like — the smell is not decisive, cap colour and scaliness count.','Both possible in deciduous and mountain forests; the site does not separate them reliably — cap colour and scaliness are decisive.','Both white spore print — no distinguishing feature.','EVEN more important than the tiger tricholoma: pure-white tricholomas can be confused with the deadly white death-cap relatives (Amanita) — always check for the absence of a bulb/volva and ring. Only flawlessly white, scale-free specimens without a stem bulb count as the dove tricholoma.','{"The dove/silky tricholoma is pure white to silky shining with a smooth surface; the tiger tricholoma is grey to grey-brown with coarse dark scales on the cap.","A genuinely pure-white, scale-free cap argues clearly against the tiger tricholoma; any grey tinge or coarse scale is a warning sign.","The dove tricholoma may turn blue-greenish/pink on the stem under pressure but stays overall white-silky; the tiger tricholoma is grey from the base up and patterned-scaly.","The tiger tricholoma causes a severe gastrointestinal syndrome (vomiting/diarrhoea after 15-30 min) — with any grey tinge or scales never count it as the dove tricholoma."}','f'),
('tricholoma_columbetta','tricholoma_pardinum','es','Tricoloma colombeta de un blanco sedoso puro y liso; tricoloma atigrado gris con un grosero revestimiento escamoso oscuro.','Tricoloma colombeta suave hasta débilmente harinoso; tricoloma atigrado harinoso/a pepino — el olor no es decisivo, cuentan el color del sombrero y la escamosidad.','Ambos posibles en bosques caducifolios y de montaña; el lugar no los separa de forma fiable — el color del sombrero y la escamosidad son determinantes.','Ambos esporada blanca — ningún criterio de distinción.','AÚN más importante que el tricoloma atigrado: los tricolomas de un blanco puro pueden confundirse con las mortales amanitas blancas (Amanita) — comprobar siempre la ausencia de bulbo/volva y anillo. Solo ejemplares de un blanco impecable, sin escamas y sin bulbo en el pie, se consideran tricoloma colombeta.','{"El tricoloma colombeta/sedoso es de un blanco puro hasta sedoso brillante, con superficie lisa; el tricoloma atigrado es gris hasta gris-pardo con grandes escamas oscuras en el sombrero.","Un sombrero realmente de un blanco puro, sin escamas, habla claramente en contra del tricoloma atigrado; cualquier tonalidad gris o escama grande es una señal de alarma.","El tricoloma colombeta en el pie bajo presión puede virar a azul-verdoso/rosa, pero permanece en conjunto blanco-sedoso; el tricoloma atigrado es gris desde la base y escamoso-jaspeado.","El tricoloma atigrado provoca un síndrome gastrointestinal grave (vómitos/diarrea tras 15-30 min) — ante cualquier tonalidad gris o escamas, nunca considerarlo tricoloma colombeta."}','f'),
('tricholoma_columbetta','tricholoma_pardinum','fr','Tricholome colombette d''un blanc soyeux pur et lisse ; tricholome tigré gris avec un grossier revêtement écailleux sombre.','Tricholome colombette doux à faiblement farineux ; tricholome tigré farineux/concombre — l''odeur n''est pas décisive, ce qui compte c''est la couleur du chapeau et l''écaillure.','Tous deux possibles en forêts feuillues et de montagne ; le site ne les sépare pas de façon fiable — la couleur du chapeau et l''écaillure sont déterminantes.','Tous deux sporée blanche — aucun critère de distinction.','PLUS important encore que le tricholome tigré : les tricholomes d''un blanc pur peuvent être confondus avec les amanites blanches mortelles (Amanita) — toujours vérifier l''absence de bulbe/volve et d''anneau. Seuls des exemplaires d''un blanc impeccable, sans écailles et sans bulbe au pied, sont considérés comme tricholome colombette.','{"Le tricholome colombette/soyeux est d''un blanc pur à soyeux brillant, à surface lisse ; le tricholome tigré est gris à gris-brun avec de grosses écailles sombres sur le chapeau.","Un chapeau réellement d''un blanc pur, sans écailles, plaide clairement contre le tricholome tigré ; toute teinte grise ou grosse écaille est un signal d''alarme.","Le tricholome colombette peut se colorer en bleu-vert/rose au pied sous la pression, mais reste globalement blanc-soyeux ; le tricholome tigré est gris à la base et écailleux-tacheté.","Le tricholome tigré provoque un syndrome gastro-intestinal sévère (vomissements/diarrhée après 15-30 min) — en cas de teinte grise ou d''écailles, ne jamais le considérer comme tricholome colombette."}','f'),
('tricholoma_columbetta','tricholoma_pardinum','it','Tricoloma colombetta bianco-serico puro e liscio; tricoloma tigrato grigio con un grossolano rivestimento squamoso scuro.','Tricoloma colombetta dolce fino a debolmente farinoso; tricoloma tigrato farinoso/cetriolo — l''odore non è decisivo, contano il colore del cappello e la squamosità.','Entrambi possibili in boschi di latifoglie e di montagna; il sito non li separa in modo affidabile — il colore del cappello e la squamosità sono determinanti.','Entrambi sporata bianca — nessun criterio di distinzione.','ANCORA più importante del tricoloma tigrato: i tricolomi bianco puro possono essere confusi con le mortali amanite bianche (Amanita) — controllare sempre l''assenza di bulbo/volva e anello. Solo esemplari di un bianco impeccabile, privi di squame e senza bulbo al gambo, sono considerati tricoloma colombetta.','{"Il tricoloma colombetta/serico è bianco puro fino a serico brillante, con superficie liscia; il tricoloma tigrato è grigio fino a grigio-bruno con grosse squame scure sul cappello.","Un cappello davvero bianco puro, privo di squame, depone chiaramente contro il tricoloma tigrato; ogni tonalità grigia o grossa squama è un segnale d''allarme.","Il tricoloma colombetta al gambo sotto pressione può virare al blu-verdastro/rosa, ma rimane nel complesso bianco-serico; il tricoloma tigrato è grigio sin dalla base e squamoso-screziato.","Il tricoloma tigrato provoca una sindrome gastrointestinale grave (vomito/diarrea dopo 15-30 min) — in caso di tonalità grigia o squame, non considerarlo mai tricoloma colombetta."}','f'),
('tricholoma_columbetta','tricholoma_scalpturatum','en','columbetta pure white and silky without yellowing; scalpturatum grey-brown and yellowing.','columbetta almost odourless/mild, scalpturatum mealy.','columbetta prefers deciduous forest (beech, oak) on richer soils; scalpturatum in deciduous/mixed/coniferous forest and parks.','Both white spore print - not a distinguishing feature.','Colour and yellowing reaction are decisive: never dismiss a grey, yellowing knight as a white knight. Pure white knights are in turn confusable with poisonous white funnels/fibrecaps - only collect with identification certainty.','{"T. columbetta (edible): pure white, silky-glossy, gills and flesh do NOT yellow (at most spot-wise blue-/pinkish-greenish on the stem).","T. scalpturatum (suspected toxic/inferior, do NOT collect): grey to grey-brown, yellows distinctly on gills and flesh.","Smell: columbetta almost odourless to faintly mushroomy-mild, scalpturatum mealy.","columbetta has firm, white, non-discolouring flesh; in scalpturatum yellowish discolouration on the cut or when scratched.","Cap colour as a quick test: pure white = check towards columbetta, grey/yellowing = earth knight suspected toxic."}','f'),
('tricholoma_columbetta','tricholoma_scalpturatum','es','columbetta de un blanco puro y sedoso sin amarilleo; scalpturatum gris-pardo y amarilleante.','columbetta casi inodoro/suave, scalpturatum harinoso.','columbetta prefiere el bosque de frondosas (haya, roble) sobre suelos mejores; scalpturatum en bosque de frondosas/mixto/coníferas y parques.','Ambos con esporada blanca - no es un criterio distintivo.','El color y la reacción de amarilleo son decisivos: nunca tomar un Tricholoma gris amarilleante por un Tricholoma blanco. Los Tricholoma de un blanco puro son a su vez confundibles con clitocibes/inocibes blancos tóxicos - recoger solo con certeza de determinación.','{"T. columbetta (comestible): de un blanco puro, sedoso-brillante, láminas y carne NO amarillean (a lo sumo puntualmente azul-/rosa-verdoso en el pie).","T. scalpturatum (sospechoso de toxicidad/inferior, NO recoger): gris hasta gris-pardo, amarillea netamente en las láminas y la carne.","Olor: columbetta casi inodoro hasta débilmente a hongo-suave, scalpturatum harinoso.","columbetta tiene carne firme, blanca, no virante; en scalpturatum coloración amarillenta al corte o al rascar.","Color del sombrero como prueba rápida: blanco puro = verificar hacia columbetta, gris/amarilleante = Tricholoma terroso sospechoso de toxicidad."}','f'),
('tricholoma_columbetta','tricholoma_scalpturatum','fr','columbetta d''un blanc pur et soyeux sans jaunissement ; scalpturatum gris-brun et jaunissant.','columbetta quasiment inodore/doux, scalpturatum farineux.','columbetta préfère la forêt de feuillus (hêtre, chêne) sur sols plus riches ; scalpturatum en forêt de feuillus/mixte/conifères et parcs.','Tous deux à sporée blanche - pas un critère de distinction.','La couleur et la réaction de jaunissement sont décisives : ne jamais prendre un tricholome gris jaunissant pour un tricholome blanc. Les tricholomes d''un blanc pur sont à leur tour confondables avec des clitocybes/inocybes blancs toxiques - ne cueillir qu''avec une certitude de détermination.','{"T. columbetta (comestible) : d''un blanc pur, soyeux-luisant, lames et chair ne jaunissent PAS (tout au plus ponctuellement bleu-/rose-verdâtre au pied).","T. scalpturatum (suspect de toxicité/médiocre, NE PAS cueillir) : gris à gris-brun, jaunit nettement aux lames et à la chair.","Odeur : columbetta quasiment inodore à faiblement champignon-doux, scalpturatum farineux.","columbetta a une chair ferme, blanche, non décolorante ; chez scalpturatum coloration jaunâtre à la coupe ou au grattage.","Couleur du chapeau comme test rapide : blanc pur = vérifier vers columbetta, gris/jaunissant = tricholome terreux suspect de toxicité."}','f'),
('tricholoma_columbetta','tricholoma_scalpturatum','it','columbetta di un bianco puro e setoso senza ingiallimento ; scalpturatum grigio-bruno e ingiallente.','columbetta quasi inodore/mite, scalpturatum farinoso.','columbetta predilige il bosco di latifoglie (faggio, quercia) su suoli migliori ; scalpturatum in bosco di latifoglie/misto/conifere e parchi.','Entrambi con sporata bianca - non un carattere distintivo.','Il colore e la reazione di ingiallimento sono decisivi : non scambiare mai un Tricholoma grigio ingiallente per un Tricholoma bianco. I Tricholoma di un bianco puro sono a loro volta confondibili con clitocybe/inocybe bianchi tossici - raccogliere solo con certezza di determinazione.','{"T. columbetta (commestibile) : di un bianco puro, setoso-lucente, lamelle e carne NON ingialliscono (tutt''al più puntualmente blu-/rosa-verdastro sul gambo).","T. scalpturatum (sospetto di tossicità/scadente, NON raccogliere) : grigio fino a grigio-bruno, ingiallisce nettamente alle lamelle e alla carne.","Odore : columbetta quasi inodore fino a debolmente fungino-mite, scalpturatum farinoso.","columbetta ha carne soda, bianca, non virante ; in scalpturatum colorazione giallastra al taglio ovvero al grattamento.","Colore del cappello come test rapido : bianco puro = verificare verso columbetta, grigio/ingiallente = Tricholoma terreo sospetto di tossicità."}','f'),
('tricholoma_portentosum','tricholoma_equestre','en','The man-on-horseback (Tricholoma equestre) is yellowish throughout, especially the sulphur-yellow gills; the dingy/grey tricholoma (Tricholoma portentosum) is grey with black radial fibrils and pale, when-young white gills.','Both mild, mealy to cucumber-like — the smell does NOT distinguish them reliably.','Both under pines/Scots pines on poor sandy soils — hence a high risk of confusion; the site does not separate them.','Both white spore print — no distinguishing feature.','Avoid every yellowish tricholoma with sulphur-yellow gills from the pinewood — the man-on-horseback, despite its former edible status, is today classified as toxic because of documented fatal muscle-breakdown poisonings.','{"Man-on-horseback (toxic): gills and stem flesh conspicuously sulphur- to lemon-yellow; dingy tricholoma (edible): gills white when young, at most faintly tinged yellow-green with age, never deep sulphur-yellow.","Man-on-horseback cap yellowish-olive-brown with a distinct yellow ground tone; dingy tricholoma silver-grey with black radial fibrous streaks, often with a lilac/greenish sheen.","Both grow under pines on sandy soil — the site is NOT a distinguishing feature; gill and stem colour are decisive.","The man-on-horseback can, with repeated consumption of larger amounts (several meals within a few days), trigger rhabdomyolysis (muscle breakdown) — in 2001 in France 12 cases, 3 deaths; classified as toxic for this reason and protected in some countries."}','f'),
('tricholoma_portentosum','tricholoma_equestre','es','El tricoloma ecuestre (Tricholoma equestre) enteramente amarillento, sobre todo las láminas amarillo azufre; el tricoloma portentoso gris con fibrillas radiales negras y láminas pálidas, blancas de joven.','Ambos suaves, harinosos hasta olor a pepino — el olor NO los distingue de forma fiable.','Ambos bajo pinos/silvestres en suelos arenosos pobres — de ahí un alto riesgo de confusión; el lugar no los separa.','Ambos esporada blanca — ningún criterio de distinción.','Evitar todo tricoloma amarillento con láminas amarillo azufre del pinar — el tricoloma ecuestre, pese a su antiguo estatus de comestible, hoy está clasificado como tóxico debido a envenenamientos mortales documentados por destrucción muscular.','{"Tricoloma ecuestre (tóxico): láminas y carne del pie claramente amarillo azufre hasta amarillo limón; tricoloma portentoso (comestible): láminas blancas de joven, con la edad a lo sumo débilmente teñidas de amarillo-verde, nunca de un amarillo azufre intenso.","Sombrero del tricoloma ecuestre amarillento-pardo oliva con un claro fondo amarillo; tricoloma portentoso gris plateado con estrías fibrosas radiales negras, a menudo con un reflejo lila/verdoso.","Ambos crecen bajo pinos en suelo arenoso — el lugar NO es un criterio de distinción; el color de las láminas y del pie es determinante.","El tricoloma ecuestre puede, con el consumo repetido de grandes cantidades (varias comidas en pocos días), desencadenar una rabdomiólisis (destrucción muscular) — en 2001 en Francia 12 casos, 3 muertes; clasificado por ello como tóxico y protegido en algunos países."}','f'),
('tricholoma_portentosum','tricholoma_equestre','fr','Le tricholome équestre (bidaou) entièrement jaunâtre, surtout les lames jaune soufre ; le tricholome prétentieux gris à fibrilles radiales noires et lames pâles, blanches dans la jeunesse.','Tous deux doux, farineux à odeur de concombre — l''odeur ne les distingue PAS de façon fiable.','Tous deux sous pins/sylvestres sur sols sableux pauvres — d''où un fort risque de confusion ; le site ne les sépare pas.','Tous deux sporée blanche — aucun critère de distinction.','Éviter tout tricholome jaunâtre à lames jaune soufre de la pinède — le tricholome équestre, malgré son ancien statut de comestible, est aujourd''hui classé toxique en raison d''empoisonnements mortels documentés par destruction musculaire.','{"Tricholome équestre (toxique) : lames et chair du pied nettement jaune soufre à jaune citron ; tricholome prétentieux (comestible) : lames blanches dans la jeunesse, au plus faiblement teintées de jaune-vert avec l''âge, jamais d''un jaune soufre soutenu.","Chapeau du tricholome équestre jaunâtre-brun olive avec un net fond jaune ; tricholome prétentieux gris argenté avec des stries fibreuses radiales noires, souvent avec un reflet lilas/verdâtre.","Tous deux poussent sous les pins sur sol sableux — le site n''est PAS un critère de distinction ; la couleur des lames et du pied est déterminante.","Le tricholome équestre peut, en cas de consommation répétée de grandes quantités (plusieurs repas en quelques jours), déclencher une rhabdomyolyse (destruction musculaire) — en 2001 en France 12 cas, 3 décès ; classé de ce fait toxique et protégé dans certains pays."}','f'),
('tricholoma_portentosum','tricholoma_equestre','it','Il tricoloma equestre (giallone) interamente giallastro, soprattutto le lamelle giallo zolfo; il tricoloma portentoso grigio con fibrille radiali nere e lamelle pallide, da giovani bianche.','Entrambi dolci, farinosi fino a odore di cetriolo — l''odore NON li distingue in modo affidabile.','Entrambi sotto pini/silvestri su suoli sabbiosi poveri — da cui un alto rischio di confusione; il sito non li separa.','Entrambi sporata bianca — nessun criterio di distinzione.','Evitare ogni tricoloma giallastro con lamelle giallo zolfo del bosco di pini — il tricoloma equestre, nonostante il suo precedente status di commestibile, è oggi classificato come tossico a causa di documentati avvelenamenti mortali per disgregazione muscolare.','{"Tricoloma equestre (tossico): lamelle e carne del gambo nettamente giallo zolfo fino a giallo limone; tricoloma portentoso (commestibile): lamelle da giovani bianche, con l''età al più debolmente sfumate di giallo-verde, mai di un giallo zolfo intenso.","Cappello del tricoloma equestre giallastro-bruno olivaceo con un netto fondo giallo; tricoloma portentoso grigio argenteo con striature fibrose radiali nere, spesso con un riflesso lilla/verdastro.","Entrambi crescono sotto i pini su suolo sabbioso — il sito NON è un criterio di distinzione; il colore delle lamelle e del gambo è determinante.","Il tricoloma equestre può, in caso di consumo ripetuto di grandi quantità (più pasti in pochi giorni), scatenare una rabdomiolisi (disgregazione muscolare) — nel 2001 in Francia 12 casi, 3 decessi; classificato perciò come tossico e protetto in alcuni Paesi."}','f'),
('tricholoma_portentosum','tricholoma_pardinum','en','The tiger tricholoma is coarsely scaly-patterned/felty with a covering of scales; the dingy tricholoma is smooth with fine black radial fibrils, no covering of scales.','Both mealy/cucumber-like — the smell does not separate them and must not be used for identification.','The tiger tricholoma prefers calcareous mountain forests under beech/spruce; the dingy tricholoma under pines on acidic sandy soils.','Both white spore print — no distinguishing feature.','Always leave behind grey tricholomas with a coarsely scaly-patterned cap surface — the tiger tricholoma is one of the most frequent causes of severe mushroom poisoning in Central Europe.','{"The tiger tricholoma has a coarsely scaly-patterned, felty cap surface with dark-grey scales on a lighter ground; the dingy tricholoma has a smooth, radially fibrillose cap surface, greasy when wet, WITHOUT coarse scales.","Tiger tricholoma often more robust/larger (cap up to 15 cm) with a thick stem; dingy tricholoma slenderer with a grey-fibrous cap, often with a lilac/greenish tone.","Tiger tricholoma readily grows in mountain forests on lime under beech/spruce; dingy tricholoma typically under pines on acidic sand.","The tiger tricholoma causes a violent gastrointestinal syndrome (vomiting/diarrhoea already after 15-30 min), severe poisonings are possible; even a spat-out taste test can trigger symptoms."}','f'),
('tricholoma_portentosum','tricholoma_pardinum','es','Tricoloma atigrado groseramente escamoso-jaspeado/afieltrado con un revestimiento de escamas; tricoloma portentoso liso con finas fibrillas radiales negras, sin revestimiento de escamas.','Ambos harinosos/a pepino — el olor no los separa y no debe usarse para la identificación.','Tricoloma atigrado prefiere los bosques montanos calcáreos bajo haya/pícea; tricoloma portentoso bajo pinos en suelos arenosos ácidos.','Ambos esporada blanca — ningún criterio de distinción.','Dejar siempre en el sitio los tricolomas grises con superficie del sombrero groseramente escamosa-jaspeada — el tricoloma atigrado es uno de los más frecuentes causantes de intoxicaciones graves por setas de Europa central.','{"El tricoloma atigrado tiene una superficie del sombrero groseramente escamosa-jaspeada, afieltrada, con escamas gris oscuro sobre fondo más claro; el tricoloma portentoso tiene una superficie del sombrero lisa, fibrillosa radialmente, viscosa con la humedad, SIN escamas grandes.","Tricoloma atigrado a menudo más robusto/grande (sombrero hasta 15 cm) con pie grueso; tricoloma portentoso más esbelto con sombrero gris-fibroso, a menudo con una tonalidad lila/verdosa.","Tricoloma atigrado crece de buena gana en bosques montanos sobre caliza bajo haya/pícea; tricoloma portentoso típicamente bajo pinos sobre arena ácida.","El tricoloma atigrado provoca un violento síndrome gastrointestinal (vómitos/diarrea ya tras 15-30 min), son posibles intoxicaciones graves; incluso una prueba de sabor escupida puede desencadenar molestias."}','f'),
('tricholoma_portentosum','tricholoma_pardinum','fr','Tricholome tigré grossièrement écailleux-tacheté/feutré avec un revêtement d''écailles ; tricholome prétentieux lisse avec de fines fibrilles radiales noires, sans revêtement d''écailles.','Tous deux farineux/concombre — l''odeur ne les sépare pas et ne doit pas servir à l''identification.','Tricholome tigré préfère les forêts de montagne calcaires sous hêtre/épicéa ; tricholome prétentieux sous les pins sur sols sableux acides.','Tous deux sporée blanche — aucun critère de distinction.','Laisser systématiquement sur place les tricholomes gris à surface du chapeau grossièrement écailleuse-tachetée — le tricholome tigré est l''un des plus fréquents responsables d''intoxications graves par champignons d''Europe centrale.','{"Le tricholome tigré a une surface du chapeau grossièrement écailleuse-tachetée, feutrée, avec des écailles gris foncé sur fond plus clair ; le tricholome prétentieux a une surface du chapeau lisse, à fibrilles radiales, visqueuse par temps humide, SANS grosses écailles.","Tricholome tigré souvent plus robuste/grand (chapeau jusqu''à 15 cm) à pied épais ; tricholome prétentieux plus élancé à chapeau gris-fibreux, souvent avec une tonalité lilas/verdâtre.","Tricholome tigré pousse volontiers en forêts de montagne sur calcaire sous hêtre/épicéa ; tricholome prétentieux typiquement sous les pins sur sable acide.","Le tricholome tigré provoque un violent syndrome gastro-intestinal (vomissements/diarrhée dès 15-30 min), des intoxications graves sont possibles ; même un test gustatif recraché peut déclencher des troubles."}','f'),
('tricholoma_portentosum','tricholoma_pardinum','it','Tricoloma tigrato grossolanamente squamoso-screziato/feltroso con un rivestimento di squame; tricoloma portentoso liscio con fini fibrille radiali nere, senza rivestimento di squame.','Entrambi farinosi/cetriolo — l''odore non li separa e non deve essere usato per l''identificazione.','Tricoloma tigrato predilige i boschi montani calcarei sotto faggio/abete rosso; tricoloma portentoso sotto i pini su suoli sabbiosi acidi.','Entrambi sporata bianca — nessun criterio di distinzione.','Lasciare sempre sul posto i tricolomi grigi con superficie del cappello grossolanamente squamosa-screziata — il tricoloma tigrato è uno dei più frequenti responsabili di gravi intossicazioni da funghi dell''Europa centrale.','{"Il tricoloma tigrato ha una superficie del cappello grossolanamente squamosa-screziata, feltrosa, con squame grigio scuro su fondo più chiaro; il tricoloma portentoso ha una superficie del cappello liscia, fibrillosa radialmente, viscida con l''umidità, SENZA grosse squame.","Tricoloma tigrato spesso più robusto/grande (cappello fino a 15 cm) con gambo spesso; tricoloma portentoso più slanciato con cappello grigio-fibroso, spesso con una tonalità lilla/verdastra.","Tricoloma tigrato cresce volentieri in boschi montani su calcare sotto faggio/abete rosso; tricoloma portentoso tipicamente sotto i pini su sabbia acida.","Il tricoloma tigrato provoca una violenta sindrome gastrointestinale (vomito/diarrea già dopo 15-30 min), sono possibili gravi intossicazioni; già una prova di sapore sputata può scatenare disturbi."}','f'),
('tricholoma_portentosum','tricholoma_saponaceum','en','portentosum has a moist-greasy cap streaked with black radial fibrils, with at most a faint yellow-green tint; saponaceum is matt, dry and highly variable in colour (grey to grey-/yellow-brown), finely scaly, and its flesh (especially the stem base) reddens when cut.','A soap/washing-lye smell points to saponaceum, mealy-mild to portentosum. WARNING: the soap smell is often faint or absent (especially after rain) — its absence is NOT an all-clear.','saponaceum, a symbiotic fungus, grows in mixed and coniferous forest (Aug-Nov); portentosum mainly under pine/spruce on sandy soil — the habitat does not separate them reliably.','Both have a white spore print — not a distinguishing feature.','Cut the stem base and smell it: reddening flesh and/or a soap/laundry-room smell mean soap knight (Tricholoma saponaceum) — do not eat. Since the soap smell may be missing, only collect grey knights when identification is 100% certain.','{"Soap knight (mildly toxic): typical SOAP/washing-powder smell — but NOT always present (often faint, almost absent after heavy rain), therefore not a sole criterion.","Soap knight: the flesh often turns slightly reddish when injured, especially at the stem base; taste unpleasantly bitter-mealy.","Sticky knight (edible): mealy-mild smell, NO distinct reddening of the flesh; cap moist greasy with black radial fibrils.","Soap knight cap very variable, grey to grey-/yellow-brown, finely scaly, matt — WITHOUT the greasy slimy sheen of portentosum; stem often spindle-shaped/twisted.","When in doubt, cut test at the stem base + smell test: reddening stem flesh and/or a soap/washing-lye smell are clear warning signs against consumption."}','f'),
('tricholoma_portentosum','tricholoma_saponaceum','es','portentosum tiene un sombrero húmedo-viscoso, surcado de fibrillas radiales negras, con a lo sumo un leve tono amarillo-verde; saponaceum es mate, seco y muy variable en color (del gris al gris-/amarillo-pardo), finamente escamoso, y su carne (sobre todo en la base del pie) enrojece al corte.','Un olor a jabón/a lejía apunta a saponaceum, harinoso-suave a portentosum. ATENCIÓN: el olor a jabón a menudo es débil o está ausente (sobre todo tras la lluvia) — su ausencia NO es una señal de vía libre.','saponaceum, hongo simbionte, crece en bosque mixto y de coníferas (ago-nov); portentosum sobre todo bajo pino/abeto rojo en suelo arenoso — la estación no los separa con seguridad.','Ambos tienen esporada blanca — no es un rasgo distintivo.','Cortar la base del pie y olerla: carne que enrojece y/o un olor a jabón/a lavadero significan tricholoma jabonoso (Tricholoma saponaceum) — no comer. Como el olor a jabón puede faltar, recolectar los tricholomas grises solo con identificación 100% segura.','{"Tricholoma jabonoso (ligeramente tóxico): olor típico a JABÓN/a detergente — pero NO siempre presente (a menudo débil, casi ausente tras lluvia intensa), por lo tanto no un criterio único.","Tricholoma jabonoso: la carne suele virar algo al rojizo al herirse, sobre todo en la base del pie; sabor desagradablemente amargo-harinoso.","Tricholoma portentosum (comestible): olor harinoso-suave, NINGÚN enrojecimiento neto de la carne; sombrero húmedo viscoso con fibrillas radiales negras.","Sombrero del tricholoma jabonoso muy variable, del gris al gris-/amarillo-pardo, finamente escamoso, mate — SIN el brillo viscoso y gelatinoso de portentosum; pie a menudo fusiforme/retorcido.","En caso de duda, prueba de corte en la base del pie + prueba olfativa: carne del pie que enrojece y/o olor a jabón/a lejía son señales de alarma claras contra el consumo."}','f'),
('tricholoma_portentosum','tricholoma_saponaceum','fr','portentosum a un chapeau humide-visqueux, strié de fibrilles radiales noires, avec tout au plus une faible teinte jaune-vert ; saponaceum est mat, sec et très variable en couleur (du gris au gris-/jaune-brun), finement squameux, et sa chair (surtout à la base du pied) rougit à la coupe.','Une odeur de savon/de lessive plaide pour saponaceum, farineuse-douce pour portentosum. ATTENTION : l''odeur de savon est souvent faible ou absente (surtout après la pluie) — son absence N''EST PAS un feu vert.','saponaceum, champignon symbiotique, pousse en forêt mixte et de conifères (août-nov.) ; portentosum surtout sous pin/épicéa sur sol sableux — la station ne sépare pas de façon sûre.','Les deux ont une sporée blanche — pas un critère de distinction.','Couper la base du pied et sentir : une chair qui rougit et/ou une odeur de savon/de buanderie signifient tricholome à odeur de savon — ne pas manger. Comme l''odeur de savon peut manquer, ne récolter les tricholomes gris que si l''identification est sûre à 100 %.','{"Tricholome à odeur de savon (légèrement toxique) : odeur typique de SAVON/de lessive — mais PAS toujours présente (souvent faible, presque absente après une forte pluie), donc non un critère unique.","Tricholome à odeur de savon : la chair vire souvent légèrement au rougeâtre à la blessure, surtout à la base du pied ; goût désagréablement amer-farineux.","Tricholome prétentieux (comestible) : odeur farineuse-douce, AUCUN rougissement net de la chair ; chapeau humide visqueux avec fibrilles radiales noires.","Chapeau du tricholome à odeur de savon très variable, du gris au gris-/jaune-brun, finement squameux, mat — SANS l''éclat visqueux et gluant de portentosum ; pied souvent fusiforme/tordu.","En cas de doute, test de coupe à la base du pied + test olfactif : une chair du pied qui rougit et/ou une odeur de savon/de lessive sont des signaux d''alarme nets contre la consommation."}','f'),
('tricholoma_portentosum','tricholoma_saponaceum','it','portentosum ha un cappello umido-viscido, striato di fibrille radiali nere, con tutt''al più una debole tonalità giallo-verde; saponaceum è opaco, asciutto e molto variabile nel colore (dal grigio al grigio-/giallo-bruno), finemente squamoso, e la sua carne (soprattutto alla base del gambo) arrossa al taglio.','Un odore di sapone/di lisciva depone per saponaceum, farinoso-mite per portentosum. ATTENZIONE: l''odore di sapone è spesso debole o assente (soprattutto dopo la pioggia) — la sua assenza NON è un via libera.','saponaceum, fungo simbionte, cresce in boschi misti e di conifere (ago-nov); portentosum soprattutto sotto pino/abete rosso su terreno sabbioso — la stazione non distingue con sicurezza.','Entrambi hanno sporata bianca — non un carattere distintivo.','Tagliare la base del gambo e annusare: carne che arrossa e/o odore di sapone/di lavanderia indicano il tricholoma saponaceo — non mangiare. Poiché l''odore di sapone può mancare, raccogliere i tricholomi grigi solo con identificazione sicura al 100%.','{"Tricholoma saponaceo (leggermente tossico): tipico odore di SAPONE/di detersivo — ma NON sempre presente (spesso debole, quasi assente dopo forti piogge), quindi non un criterio unico.","Tricholoma saponaceo: la carne vira spesso un po'' al rossastro alla lesione, soprattutto alla base del gambo; sapore sgradevolmente amaro-farinoso.","Tricholoma portentosum (commestibile): odore farinoso-mite, NESSUN netto arrossamento della carne; cappello umido viscido con fibrille radiali nere.","Cappello del tricholoma saponaceo molto variabile, dal grigio al grigio-/giallo-bruno, finemente squamoso, opaco — SENZA la lucentezza viscida e gelatinosa di portentosum; gambo spesso fusiforme/contorto.","In caso di dubbio, prova di taglio alla base del gambo + prova olfattiva: carne del gambo che arrossa e/o odore di sapone/di lisciva sono chiari segnali d''allarme contro il consumo."}','f'),
('tricholoma_portentosum','tricholoma_scalpturatum','en','T. portentosum shows black radial fibres on a grey cap without yellowing; T. scalpturatum yellows on the gills and cut surface when scratched/pressed.','portentosum mild and pleasantly mealy-cucumbery, scalpturatum obtrusively mealy.','portentosum in late autumn under conifers (pine/spruce) on acidic soil, scalpturatum from May to November in deciduous/mixed/coniferous forest, parks and gardens.','Both white spore print - the spore print does NOT distinguish here; use exclusively yellowing (scalpturatum) + cap colour + season.','Any grey-brown earth knight whose gills or cut surface yellow is NOT an edible mushroom - when in doubt, leave it. Grey earth knights in general only with absolute identification certainty; several poisonous to deadly species (e.g. Tricholoma pardinum) look similar.','{"T. portentosum (edible): cap grey-brown with distinctly black-fibrous radial markings, often a violet-/yellowish sheen; flesh and gills do NOT yellow.","T. scalpturatum (suspected toxic/inferior, do NOT collect): gills and flesh yellow distinctly (yellowish spots on pressure, on scratching or with age) - central distinguishing feature.","Smell: portentosum mild to faintly mealy-cucumbery, pleasant; scalpturatum distinctly mealy.","portentosum typically grows late in the year (late autumn/frost) under pine/spruce; scalpturatum from May to November in deciduous/mixed and coniferous forest, parks, gardens.","Cap surface portentosum slimy-glossy when moist, scalpturatum dry-finely scaly/with ingrown fibres."}','f'),
('tricholoma_portentosum','tricholoma_scalpturatum','es','T. portentosum muestra fibras radiales negras sobre un sombrero gris sin amarilleo; T. scalpturatum amarillea en las láminas y la superficie de corte al rascar/presionar.','portentosum suave y agradablemente harinoso-pepino, scalpturatum harinoso invasivo.','portentosum a finales de otoño bajo coníferas (pino/abeto rojo) en suelo ácido, scalpturatum de mayo a noviembre en bosque de frondosas/mixto/coníferas, parques y jardines.','Ambos con esporada blanca - la esporada aquí NO distingue; usar exclusivamente el amarilleo (scalpturatum) + el color del sombrero + la temporada.','Todo Tricholoma terroso gris-pardo cuyas láminas o superficie de corte amarillean NO es un hongo comestible - en la duda, dejar en el sitio. Los Tricholoma terrosos grises en general solo con certeza de determinación absoluta; varias especies tóxicas hasta mortales (p. ej. Tricholoma pardinum) se parecen.','{"T. portentosum (comestible): sombrero gris-pardo con diseño radial netamente negro-fibroso, a menudo reflejo violáceo/amarillento; carne y láminas NO amarillean.","T. scalpturatum (sospechoso de toxicidad/inferior, NO recoger): láminas y carne amarillean netamente (manchas amarillentas a la presión, al rascar o con la edad) - carácter distintivo central.","Olor: portentosum suave hasta débilmente harinoso-pepino, agradable; scalpturatum netamente harinoso.","portentosum crece típicamente tarde en el año (finales de otoño/helada) bajo pino/abeto rojo; scalpturatum de mayo a noviembre en bosque de frondosas/mixto y coníferas, parques, jardines.","Superficie del sombrero portentosum viscoso-brillante con tiempo húmedo, scalpturatum seco-finamente escamoso/con fibras incrustadas."}','f'),
('tricholoma_portentosum','tricholoma_scalpturatum','fr','T. portentosum montre des fibres radiales noires sur un chapeau gris sans jaunissement ; T. scalpturatum jaunit aux lames et à la surface de coupe au grattage/à la pression.','portentosum doux et agréablement farineux-concombre, scalpturatum farineux envahissant.','portentosum en fin d''automne sous conifères (pin/épicéa) sur sol acide, scalpturatum de mai à novembre en forêt de feuillus/mixte/conifères, parcs et jardins.','Tous deux à sporée blanche - la sporée ne distingue PAS ici ; utiliser exclusivement le jaunissement (scalpturatum) + la couleur du chapeau + la saison.','Tout tricholome terreux gris-brun dont les lames ou la surface de coupe jaunissent n''est PAS un champignon comestible - dans le doute, laisser sur place. Les tricholomes terreux gris ne se cueillent en général qu''avec une certitude de détermination absolue ; plusieurs espèces toxiques à mortelles (p. ex. Tricholoma pardinum) se ressemblent.','{"T. portentosum (comestible) : chapeau gris-brun à motif radial nettement noir-fibreux, souvent reflet violacé/jaunâtre ; chair et lames ne jaunissent PAS.","T. scalpturatum (suspect de toxicité/médiocre, NE PAS cueillir) : lames et chair jaunissent nettement (taches jaunâtres à la pression, au grattage ou avec l''âge) - critère de distinction central.","Odeur : portentosum doux à faiblement farineux-concombre, agréable ; scalpturatum nettement farineux.","portentosum pousse typiquement tard dans l''année (fin d''automne/gel) sous pin/épicéa ; scalpturatum de mai à novembre en forêt de feuillus/mixte et conifères, parcs, jardins.","Surface du chapeau portentosum visqueuse-luisante par temps humide, scalpturatum sèche-finement écailleuse/à fibres incrustées."}','f'),
('tricholoma_portentosum','tricholoma_scalpturatum','it','T. portentosum mostra fibre radiali nere su cappello grigio senza ingiallimento ; T. scalpturatum ingiallisce alle lamelle e alla superficie di taglio al grattamento/alla pressione.','portentosum mite e gradevolmente farinoso-cetriolo, scalpturatum farinoso invadente.','portentosum a tardo autunno sotto conifere (pino/abete rosso) su suolo acido, scalpturatum da maggio a novembre in bosco di latifoglie/misto/conifere, parchi e giardini.','Entrambi con sporata bianca - la sporata qui NON distingue ; usare esclusivamente l''ingiallimento (scalpturatum) + il colore del cappello + la stagione.','Ogni Tricholoma terreo grigio-bruno le cui lamelle o superficie di taglio ingialliscono NON è un fungo commestibile - nel dubbio, lasciare sul posto. I Tricholoma terrei grigi si raccolgono in generale solo con assoluta certezza di determinazione ; più specie tossiche fino a mortali (es. Tricholoma pardinum) si somigliano.','{"T. portentosum (commestibile) : cappello grigio-bruno con disegno radiale nettamente nero-fibroso, spesso riflesso violaceo/giallastro ; carne e lamelle NON ingialliscono.","T. scalpturatum (sospetto di tossicità/scadente, NON raccogliere) : lamelle e carne ingialliscono nettamente (macchie giallastre alla pressione, al grattamento o con l''età) - carattere distintivo centrale.","Odore : portentosum mite fino a debolmente farinoso-cetriolo, gradevole ; scalpturatum nettamente farinoso.","portentosum cresce tipicamente tardi nell''anno (tardo autunno/gelo) sotto pino/abete rosso ; scalpturatum da maggio a novembre in bosco di latifoglie/misto e conifere, parchi, giardini.","Superficie del cappello portentosum vischioso-lucente con tempo umido, scalpturatum asciutto-finemente squamoso/a fibre incrostate."}','f'),
('tricholoma_portentosum','tricholoma_terreum','en','The sticky/dingy knight (Tricholoma portentosum) has a moist-greasy (slimy) cap with ingrown black radial fibrils and at most a faint yellow-green tint; the grey knight (Tricholoma terreum) is dry, finely felty-scaly and pure mouse-grey. The slimy cap in damp weather is the most striking distinguishing feature.','portentosum is mildly mealy; terreum is almost odourless. A strong mealy smell on a grey knight is NOT an all-clear — it also fits the deadly tiger knight.','Both grow under conifers (especially pine, also spruce) on rather sandy, lime-poor soils in autumn; the habitat does NOT separate them reliably.','Both have a white spore print — not usable as a distinguishing feature.','Grey knights are a beginner''s taboo: this colour group contains several toxic to deadly species (incl. the tiger knight T. pardinum). Only collect if the greasy cap WITH black radial fibrils is unambiguously identified and any suspicion of coarse scales/robust growth has been ruled out — when in doubt, leave it standing.','{"Black-fibrilled/sticky knight (edible): cap grey to grey-white with ingrown black RADIAL FIBRILS, distinctly greasy-sticky in damp weather (slimy cap), often a faint yellow-greenish sheen at the cap margin/bruised spots.","Grey knight (listed here as toxic): cap mouse-grey, finely FELTY-SCALY (not radially fibrilled, never greasy), dry and matt, without yellow-green tint.","portentosum flesh/gills can show a faint yellow-greenish tone (especially on pressure/cut) — do NOT use as the sole safety feature, as it is variable; terreum stays purely grey.","portentosum smells/tastes mealy-mild; terreum is practically odourless and mild.","WARNING life-threatening danger in the grey knight group: the deadly poisonous tiger knight (T. pardinum) looks similar (mealy smell, coarse tile-like scales, robust growth) — at any doubt, leave ALL grey knights standing."}','f'),
('tricholoma_portentosum','tricholoma_terreum','es','El tricholoma portentosum tiene un sombrero húmedo-viscoso (gelatinoso) con fibrillas radiales negras incrustadas y a lo sumo un leve tono amarillo-verde; el tricholoma terreum es seco, finamente afieltrado-escamoso y de un gris ratón puro. El sombrero viscoso con la humedad es el rasgo distintivo más llamativo.','portentosum es de olor harinoso suave; terreum es casi inodoro. Un fuerte olor harinoso en un tricholoma gris NO es una señal de vía libre — también encaja con el tricholoma atigrado, mortal.','Ambos crecen bajo coníferas (sobre todo pino, también abeto rojo), en suelos más bien arenosos y pobres en cal, en otoño; la estación NO los separa de forma fiable.','Ambos tienen esporada blanca — no utilizable como rasgo distintivo.','Los tricholomas grises son un tabú para principiantes: en este grupo cromático figuran varias especies de tóxicas a mortales (incl. el tricholoma atigrado T. pardinum). Recolectar solo si el sombrero viscoso CON fibrillas radiales negras está identificado sin ambigüedad y se ha descartado toda sospecha de escamas gruesas/porte robusto — en caso de duda, dejar en el sitio.','{"Tricholoma de fibrillas negras/portentosum (comestible): sombrero gris a gris-blanco con FIBRILLAS RADIALES negras incrustadas, claramente viscoso-pegajoso con la humedad (sombrero gelatinoso), a menudo un leve brillo amarillo-verdoso en el borde del sombrero/zonas magulladas.","Tricholoma terreum (aquí clasificado como tóxico): sombrero gris ratón, finamente AFIELTRADO-ESCAMOSO (no radial-fibrilloso, nunca viscoso), seco y mate, sin tono amarillo-verde.","La carne/las láminas de portentosum pueden mostrar un leve tono amarillo-verdoso (sobre todo a la presión/al corte) — NO usar como único rasgo de seguridad, pues es variable; terreum permanece puramente gris.","portentosum huele/sabe harinoso-suave; terreum es prácticamente inodoro y suave.","ATENCIÓN peligro de muerte en el grupo de los tricholomas grises: el tricholoma atigrado mortal (T. pardinum) se le parece (olor harinoso, escamas gruesas en forma de tejas, porte robusto) — ante cualquier duda, dejar TODOS los tricholomas grises en el sitio."}','f'),
('tricholoma_portentosum','tricholoma_terreum','fr','Le tricholome prétentieux a un chapeau humide-visqueux (gluant) avec des fibrilles radiales noires incluses et tout au plus une faible teinte jaune-vert ; le tricholome terreux est sec, finement feutré-squameux et d''un gris souris pur. Le chapeau visqueux par temps humide est le critère de distinction le plus marquant.','portentosum a une odeur farineuse douce ; terreum est presque inodore. Une forte odeur farineuse chez un tricholome gris N''EST PAS un feu vert — elle correspond aussi au tricholome tigré, mortel.','Les deux poussent sous les conifères (surtout pin, aussi épicéa), sur des sols plutôt sableux et pauvres en calcaire, en automne ; la station NE sépare PAS de façon fiable.','Les deux ont une sporée blanche — inutilisable comme critère de distinction.','Les tricholomes gris sont un tabou pour les débutants : dans ce groupe de couleur figurent plusieurs espèces toxiques à mortelles (dont le tricholome tigré T. pardinum). Ne récolter que si le chapeau visqueux AVEC fibrilles radiales noires est identifié sans ambiguïté et que tout soupçon de grosses squames/port robuste est écarté — en cas de doute, laisser sur place.','{"Tricholome à fibrilles noires/prétentieux (comestible) : chapeau gris à gris-blanc avec des FIBRILLES RADIALES noires incluses, nettement visqueux-collant par temps humide (chapeau gluant), souvent un faible reflet jaune-verdâtre au bord du chapeau/aux endroits meurtris.","Tricholome terreux (ici classé comme toxique) : chapeau gris souris, finement FEUTRÉ-SQUAMEUX (non radial-fibrilleux, jamais visqueux), sec et mat, sans teinte jaune-vert.","La chair/les lamelles de portentosum peuvent montrer une faible teinte jaune-verdâtre (surtout à la pression/coupe) — à NE PAS utiliser comme seul critère de sécurité, car variable ; terreum reste purement gris.","portentosum sent/a un goût farineux-doux ; terreum est pratiquement inodore et doux.","ATTENTION danger de mort dans le groupe des tricholomes gris : le tricholome tigré mortel (T. pardinum) lui ressemble (odeur farineuse, grosses squames en tuiles, port robuste) — au moindre doute, laisser TOUS les tricholomes gris sur place."}','f'),
('tricholoma_portentosum','tricholoma_terreum','it','Il tricholoma portentosum ha un cappello umido-viscido (gelatinoso) con fibrille radiali nere incluse e tutt''al più una debole tonalità giallo-verde; il tricholoma terreum è asciutto, finemente feltroso-squamoso e di un grigio topo puro. Il cappello viscido con l''umidità è il carattere distintivo più evidente.','portentosum ha odore farinoso mite; terreum è quasi inodore. Un forte odore farinoso in un tricholoma grigio NON è un via libera — è compatibile anche con il tricholoma tigrato, mortale.','Entrambi crescono sotto le conifere (soprattutto pino, anche abete rosso), su terreni piuttosto sabbiosi e poveri di calcare, in autunno; la stazione NON distingue in modo affidabile.','Entrambi hanno sporata bianca — non utilizzabile come carattere distintivo.','I tricholomi grigi sono un tabù per i principianti: in questo gruppo cromatico figurano diverse specie da tossiche a mortali (incluso il tricholoma tigrato T. pardinum). Raccogliere solo se il cappello viscido CON fibrille radiali nere è identificato con certezza e ogni sospetto di grosse squame/portamento robusto è escluso — in caso di dubbio, lasciare sul posto.','{"Tricholoma a fibrille nere/portentosum (commestibile): cappello da grigio a grigio-bianco con FIBRILLE RADIALI nere incluse, nettamente viscido-appiccicoso con l''umidità (cappello gelatinoso), spesso un debole riflesso giallo-verdastro al bordo del cappello/nei punti ammaccati.","Tricholoma terreum (qui classificato come tossico): cappello grigio topo, finemente FELTROSO-SQUAMOSO (non radial-fibrilloso, mai viscido), asciutto e opaco, senza tonalità giallo-verde.","La carne/le lamelle di portentosum possono mostrare una debole tonalità giallo-verdastra (soprattutto alla pressione/al taglio) — da NON usare come unico carattere di sicurezza, poiché variabile; terreum resta puramente grigio.","portentosum ha odore/sapore farinoso-mite; terreum è praticamente inodore e mite.","ATTENZIONE pericolo di morte nel gruppo dei tricholomi grigi: il tricholoma tigrato mortale (T. pardinum) gli assomiglia (odore farinoso, grosse squame embricate, portamento robusto) — al minimo dubbio, lasciare TUTTI i tricholomi grigi sul posto."}','f'),
('tricholoma_portentosum','tricholoma_ustale','en','ustale uniformly red-brown and slimy with gills becoming rust-spotted; portentosum grey with black radial fibrils.','ustale faintly mealy, portentosum mild mealy-cucumbery - smell here distinguishes only weakly, colour decides.','ustale in deciduous forest (beech preferred, also oak); portentosum under pine/spruce on acidic soil in late autumn.','Both white spore print - not a distinguishing feature.','Red-brown, slimy cap with rust-spotted gills and a bitter taste = poisonous burnt knight (Tricholoma ustale), do not collect.','{"T. ustale (poisonous): cap red-brown to chestnut-brown, slimy-mucilaginous when moist; gills quickly become rust-spotted; flesh browns, taste somewhat bitter.","T. portentosum (edible): cap grey with black radial fibres (not red-brown), gills grey-whitish, often tinged yellowish, without rust spots.","Raw taste: ustale unpleasantly bitter, portentosum mild - the taste test (chew, do NOT swallow, spit out) helps but is not a sole criterion.","Season/site: portentosum mainly late autumn until frost under conifers; ustale from high summer to late autumn predominantly in deciduous forest (beech/oak).","ustale stains the flesh brownish, portentosum hardly discolours."}','f'),
('tricholoma_portentosum','tricholoma_ustale','es','ustale unicolor pardo-rojo y viscoso con láminas que se manchan de herrumbre; portentosum gris con fibrillas radiales negras.','ustale débilmente harinoso, portentosum suave harinoso-pepino - el olor aquí distingue solo débilmente, el color decide.','ustale en bosque de frondosas (haya preferida, también roble); portentosum bajo pino/abeto rojo en suelo ácido a finales de otoño.','Ambos con esporada blanca - no es un criterio distintivo.','Sombrero pardo-rojo, viscoso, con láminas manchadas de herrumbre y sabor amargo = Tricholoma ustale tóxico, no recoger.','{"T. ustale (tóxico): sombrero pardo-rojo a pardo-castaño, viscoso-mucilaginoso con tiempo húmedo; láminas que se manchan rápidamente de herrumbre; carne que pardea, sabor amarguento.","T. portentosum (comestible): sombrero gris con fibras radiales negras (no pardo-rojo), láminas gris-blanquecinas, a menudo teñidas de amarillento, sin manchas de herrumbre.","Sabor crudo: ustale desagradablemente amargo, portentosum suave - la prueba de sabor (masticar, NO tragar, escupir) ayuda, pero no es un criterio único.","Temporada/estación: portentosum sobre todo finales de otoño hasta la helada bajo coníferas; ustale de pleno verano a finales de otoño predominantemente en bosque de frondosas (haya/roble).","ustale colorea la carne de pardusco, portentosum apenas vira."}','f'),
('tricholoma_portentosum','tricholoma_ustale','fr','ustale unicolore brun-rouge et visqueux avec des lames se tachant de rouille ; portentosum gris à fibrilles radiales noires.','ustale faiblement farineux, portentosum doux farineux-concombre - l''odeur ne distingue ici que faiblement, la couleur décide.','ustale en forêt de feuillus (hêtre de préférence, aussi chêne) ; portentosum sous pin/épicéa sur sol acide en fin d''automne.','Tous deux à sporée blanche - pas un critère de distinction.','Chapeau brun-rouge, visqueux, à lames tachées de rouille et goût amer = tricholome brûlant toxique, ne pas cueillir.','{"T. ustale (toxique) : chapeau brun-rouge à brun-châtain, visqueux-gluant par temps humide ; lames se tachant rapidement de rouille ; chair brunissant, goût amarescent.","T. portentosum (comestible) : chapeau gris à fibres radiales noires (non brun-rouge), lames gris-blanchâtre, souvent teintées de jaunâtre, sans taches de rouille.","Goût cru : ustale désagréablement amer, portentosum doux - la prise de goût (mâcher, NE PAS avaler, recracher) aide, mais n''est pas un critère unique.","Saison/station : portentosum surtout fin d''automne jusqu''au gel sous conifères ; ustale du plein été à la fin de l''automne, principalement en forêt de feuillus (hêtre/chêne).","ustale colore la chair en brunâtre, portentosum ne se décolore guère."}','f'),
('tricholoma_portentosum','tricholoma_ustale','it','ustale unicolore bruno-rosso e vischioso con lamelle che si macchiano di ruggine ; portentosum grigio con fibrille radiali nere.','ustale debolmente farinoso, portentosum mite farinoso-cetriolo - l''odore qui distingue solo debolmente, il colore decide.','ustale nel bosco di latifoglie (faggio preferito, anche quercia) ; portentosum sotto pino/abete rosso su suolo acido a fine autunno.','Entrambi con sporata bianca - non un carattere distintivo.','Cappello bruno-rosso, vischioso, con lamelle macchiate di ruggine e sapore amaro = Tricholoma ustale tossico, non raccogliere.','{"T. ustale (tossico) : cappello bruno-rosso a bruno-castano, vischioso-viscido con tempo umido ; lamelle che si macchiano rapidamente di ruggine ; carne che imbrunisce, sapore amarognolo.","T. portentosum (commestibile) : cappello grigio con fibre radiali nere (non bruno-rosso), lamelle grigio-biancastre, spesso sfumate di giallastro, senza macchie di ruggine.","Sapore crudo : ustale sgradevolmente amaro, portentosum mite - la prova di assaggio (masticare, NON inghiottire, sputare) aiuta, ma non è un criterio unico.","Stagione/stazione : portentosum soprattutto tardo autunno fino al gelo sotto conifere ; ustale da piena estate a tardo autunno, prevalentemente nel bosco di latifoglie (faggio/quercia).","ustale colora la carne di brunastro, portentosum vira appena."}','f'),
('zigeunerpilz','cortinarius_orellanus','en','Gypsy mushroom (Cortinarius caperatus): straw-yellow to yellow-brown, grey-whitish-lilac frosted, longitudinally wrinkled cap with a double-edged membranous ring. Fool''s webcap (Cortinarius orellanus): deep orange to copper-/rust-brown, dull-fibrous to finely scaly, dry cap WITHOUT any frosting; NO true ring, only a fleeting cortina; stem cylindrical, of the same colour or yellowish, not distinctly banded (unlike rubellus).','Gypsy mushroom: mild. Fool''s webcap: faintly radish-like.','Gypsy mushroom: coniferous and (rarely) deciduous forest, often on acidic sandy soil, near bilberry. Fool''s webcap: warmth-favoured deciduous forests near oak, beech, hazel, sweet chestnut on acidic to basic soils (July–October) — typically not coniferous forest.','Gypsy mushroom: pale cinnamon-brown/rust-yellow. Fool''s webcap: rust-brown. No single reliably distinguishing feature.','Only eat the gypsy mushroom if it has a clear, firm ring with a double edge. A deep orange-/rust-brown, dry-fibrous cap WITHOUT frosting and without a true ring (only veil fibres) points to the deadly fool''s webcap — hands off, take it to mushroom inspection (VAPKO).','{"The gypsy mushroom has a firm membranous stem ring with a double edge; the fool''s webcap has NO true ring, only fleeting veil fibres (cortina).","The gypsy mushroom''s cap is grey-lilac frosted and wrinkled; the webcap''s cap is dry-fibrous to finely scaly and uniformly deep orange-/copper-/rust-brown without frosting.","The webcap''s stem is of the same colour to yellowish and not distinctly banded; the gypsy mushroom''s stem bears the membranous double-edged collar.","The toxin orellanine is heat-/drying-resistant and, after a latency of days to weeks (3–14 days), leads to fatal kidney failure — no taste test and no detoxifying through cooking is possible."}','t'),
('zigeunerpilz','cortinarius_orellanus','es','Reifpilz (Cortinarius caperatus): sombrero de color amarillo pajizo a pardo amarillento, con velo escarchado de tono gris-blanquecino-lila, longitudinalmente arrugado, con un anillo membranoso de doble borde. Cortinarius orellanus (orellana, cortinario de montaña): sombrero de color naranja intenso a pardo cobrizo/herrumbroso, fibroso mate a finamente escamoso, seco, SIN escarcha; SIN anillo verdadero, solo una cortina fugaz; pie cilíndrico, del mismo color o amarillento, sin estar marcadamente jaspeado (a diferencia de rubellus).','Reifpilz: suave. Cortinarius orellanus (orellana): débilmente a rábano.','Reifpilz: bosque de coníferas y (raramente) de frondosas, a menudo en suelo ácido y arenoso, junto al arándano. Cortinarius orellanus (orellana): bosques de frondosas de clima cálido, junto a roble, haya, avellano, castaño, sobre suelos ácidos a básicos (julio-octubre); típicamente no en bosque de coníferas.','Reifpilz: pardo canela claro/amarillo herrumbroso. Cortinarius orellanus (orellana): pardo herrumbroso. No hay ningún rasgo aislado que los distinga de forma fiable.','Consumir el Reifpilz solo si presenta un anillo firme e inequívoco con doble borde. Un sombrero de color naranja/pardo herrumbroso intenso, seco y fibroso, SIN escarcha y sin anillo verdadero (solo fibras de velo), indica el mortal Cortinarius orellanus (orellana): no lo toques, llévalo al control de setas (VAPKO).','{"El Reifpilz posee un anillo membranoso firme en el pie, con doble borde; el Cortinarius orellanus (orellana) NO tiene anillo verdadero, sino solo fibras de velo fugaces (cortina).","El sombrero del Reifpilz está escarchado de gris-lila y es arrugado; el sombrero de la orellana es seco-fibroso a finamente escamoso y de un naranja/cobrizo/pardo herrumbroso intenso y uniforme, sin escarcha.","El pie de la orellana es del mismo color a amarillento y no está marcadamente jaspeado; el pie del Reifpilz lleva la manga membranosa de doble borde.","El tóxico orellanina es resistente al calor y a la desecación y, tras una latencia de días a semanas (3-14 días), provoca una insuficiencia renal mortal: no hay prueba de cata posible ni se puede destoxificar mediante la cocción."}','t'),
('zigeunerpilz','cortinarius_orellanus','fr','Rozite ridé (Cortinarius caperatus): chapeau jaune paille à brun jaunâtre, pruineux gris-blanchâtre-lilas, ridé longitudinalement, avec un anneau membraneux à double bord. Cortinaire des montagnes (Cortinarius orellanus): chapeau d''un orange soutenu à brun cuivré/rouille, mat-fibrilleux à finement écailleux, sec, SANS pruine; PAS de véritable anneau, seulement une cortine fugace; pied cylindrique, de même couleur ou jaunâtre, non nettement chiné/guirlandé (contrairement à rubellus).','Rozite ridé: doux. Cortinaire des montagnes: légèrement raveline (odeur de radis).','Rozite ridé: forêts de conifères et (rarement) de feuillus, souvent sur sol acide et sableux, près des myrtilles. Cortinaire des montagnes: forêts de feuillus thermophiles près des chênes, hêtres, noisetiers, châtaigniers, sur sols acides à basiques (juillet-octobre) — typiquement pas en forêt de conifères.','Rozite ridé: brun cannelle clair/jaune rouille. Cortinaire des montagnes: brun rouille. Aucun caractère unique permettant de les distinguer de façon fiable.','Ne consommer le rozite ridé qu''avec un anneau ferme et net à double bord. Un chapeau d''un orange/brun rouille soutenu, sec et fibrilleux, SANS pruine et sans véritable anneau (seulement des fibres de voile), indique le mortel cortinaire des montagnes — n''y touchez pas, direction le contrôle des champignons (VAPKO).','{"Le rozite ridé possède un anneau membraneux ferme à double bord sur le pied; le cortinaire des montagnes n''a PAS de véritable anneau, seulement des fibres de voile fugaces (cortine).","Le chapeau du rozite ridé est pruineux gris-lilas et ridé; le chapeau du cortinaire des montagnes est sec, fibrilleux à finement écailleux et d''un orange/cuivre/brun rouille uniforme et soutenu, sans pruine.","Le pied du cortinaire des montagnes est de même couleur à jaunâtre et non nettement chiné; le pied du rozite ridé porte la manchette membraneuse à double bord.","Le poison orellanine résiste à la chaleur et au séchage et provoque, après une latence de plusieurs jours à plusieurs semaines (3-14 jours), une insuffisance rénale mortelle — aucun test gustatif et aucune détoxification par la cuisson ne sont possibles."}','t'),
('zigeunerpilz','cortinarius_orellanus','it','Cortinario brunastro (Reifpilz): cappello giallo paglierino-bruno giallastro, pruinoso grigio-biancastro-lilla, rugoso longitudinalmente, con anello membranoso a doppio bordo. Cortinario arancio-fulvo (Cortinarius orellanus): cappello da arancio intenso a bruno ramato/ruggine, opaco-fibroso fino a finemente squamoso, secco, SENZA pruina; NESSUN vero anello, solo una cortina fugace; gambo cilindrico, dello stesso colore o giallastro, non marcatamente zigrinato (a differenza di rubellus).','Cortinario brunastro: mite. Cortinario arancio-fulvo: debolmente di ravanello.','Cortinario brunastro: bosco di conifere e (raramente) di latifoglie, spesso suolo acido e sabbioso, presso il mirtillo. Cortinario arancio-fulvo: boschi di latifoglie in posizioni calde presso quercia, faggio, nocciolo, castagno, su suoli da acidi a basici (luglio-ottobre) — tipicamente non in bosco di conifere.','Cortinario brunastro: bruno cannella chiaro/giallo ruggine. Cortinario arancio-fulvo: bruno ruggine. Nessun singolo carattere distintivo affidabile.','Consumare il cortinario brunastro solo con un anello fermo e ben definito a doppio bordo. Un cappello arancio/bruno ruggine intenso, secco-fibroso, SENZA pruina e senza vero anello (solo fibre del velo) indica il mortale cortinario arancio-fulvo — non toccarlo, portarlo al controllo dei funghi (VAPKO).','{"Il cortinario brunastro possiede un anello membranoso fermo sul gambo con doppio bordo; il cortinario arancio-fulvo NON ha un vero anello, ma solo fibre fugaci del velo (cortina).","Il cappello del cortinario brunastro è pruinoso grigio-lilla e rugoso; il cappello del cortinario arancio-fulvo è secco-fibroso fino a finemente squamoso e uniformemente arancio/ramato/bruno ruggine intenso, senza pruina.","Il gambo del cortinario arancio-fulvo è dello stesso colore fino a giallastro e non marcatamente zigrinato; il gambo del cortinario brunastro porta il manicotto membranoso a doppio bordo.","Il veleno orellanina è resistente al calore e all''essiccazione e provoca, dopo una latenza di giorni-settimane (3-14 giorni), un''insufficienza renale mortale — nessun test d''assaggio e nessuna disintossicazione tramite cottura possibile."}','t'),
('zigeunerpilz','cortinarius_rubellus','en','Gypsy mushroom (Reifpilz): straw-yellow to yellow-brown cap with a grey-whitish-lilac bloom (veil), surface characteristically longitudinally wrinkled/furrowed, with a distinct membranous stem ring that has a double margin. Cortinarius rubellus (Deadly webcap, Raukopf): yellow- to orange- or reddish-foxy cinnamon-brown, dry and finely felty cap with a pointed (or rounded) umbo, NO true ring (only fleeting cortina/veil remnants), stem slender and yellowish snake-banded (yellow veil girdles).','Gypsy mushroom (Reifpilz): pleasant/mild. Deadly webcap (Spitzgebuckelter Raukopf): faintly radish-like.','Gypsy mushroom (Reifpilz): coniferous and (rarely) deciduous forest, fond of growing near blueberry on acidic, sandy soil, August-October. Deadly webcap (Spitzgebuckelter Raukopf): above all coniferous forest (spruce stands), often in damp/boggy locations on acidic soils, near blueberry — the habitat overlap heightens the risk.','Gypsy mushroom (Reifpilz): pale cinnamon-brown to rusty-yellow. Cortinarius rubellus: rust-brown. The spore colour does NOT reliably separate them here — never use it as the sole feature.','Look on the stem for the firm membranous ring with its characteristic DOUBLE margin — if this ring is missing and the stem is instead yellowish snake-banded with only fleeting veil fibres, then it is not a Gypsy mushroom but possibly the deadly webcap. When in doubt about young specimens, ALWAYS take it to the mushroom inspection office (VAPKO).','{"The Gypsy mushroom has a firm, membranous stem ring with a characteristic DOUBLE margin; the deadly webcap (Spitzgebuckelter Raukopf) has NO true ring, only fleeting veil fibres (cortina).","The Gypsy mushroom''s cap is dull grey-whitish to lilac BLOOMED and longitudinally wrinkled; the webcap has a dry, finely felty-fibrous, reddish-foxy cinnamon-brown cap with a distinct POINTED umbo.","The webcap''s stem is slender and yellowish SNAKE-BANDED (yellow veil girdles); the Gypsy mushroom''s stem is thicker and bears the membranous cuff instead of girdles.","Eat only when an unambiguous double-margined ring is present; the toxin orellanine is heat- and drying-stable and causes irreversible kidney failure after a latency of 2-21 days — no cooking/drying detoxifies it."}','t'),
('zigeunerpilz','cortinarius_rubellus','es','Pie violeta (Cortinarius caperatus): sombrero de color amarillo paja a pardo amarillento con una pruina (velo) de tono gris-blanquecino-lila, superficie característicamente arrugada/surcada longitudinalmente, anillo membranoso bien marcado en el pie con un borde doble. Cortinarius rubellus: sombrero seco y finamente afieltrado de color pardo canela amarillento a anaranjado o rojo zorruno, con un mamelón puntiagudo (o redondeado), SIN anillo verdadero (solo restos fugaces de cortina/velo), pie esbelto y amarillento con bandas (cinturones amarillos de velo).','Pie violeta (Cortinarius caperatus): agradable/suave. Cortinarius rubellus: débilmente parecido al rábano.','Pie violeta (Cortinarius caperatus): bosque de coníferas y (raramente) de frondosas, preferentemente junto al arándano en suelos ácidos y arenosos, de agosto a octubre. Cortinarius rubellus: sobre todo bosque de coníferas (rodales de abeto rojo), a menudo en zonas húmedas/pantanosas sobre suelos ácidos, junto al arándano — la coincidencia de hábitat agrava el riesgo.','Pie violeta (Cortinarius caperatus): pardo canela claro a amarillo herrumbroso. Cortinarius rubellus: pardo herrumbroso. El color de las esporas NO separa de forma fiable aquí — nunca usarlo como único criterio.','Busca en el pie el anillo firme y membranoso con el característico borde DOBLE — si falta este anillo y el pie en su lugar está amarillento con bandas y solo presenta fibras fugaces de velo, no se trata del pie violeta (Cortinarius caperatus), sino posiblemente del mortal Cortinarius rubellus. En ejemplares jóvenes, en caso de duda, acude SIEMPRE a la oficina de control de setas (VAPKO).','{"El pie violeta (Cortinarius caperatus) tiene un anillo firme y membranoso en el pie con un característico borde DOBLE; Cortinarius rubellus NO tiene un anillo verdadero, solo fibras fugaces de velo (cortina).","El sombrero del pie violeta (Cortinarius caperatus) está cubierto de una PRUINA mate de tono gris-blanquecino a lila y es arrugado longitudinalmente; Cortinarius rubellus tiene un sombrero seco, finamente afieltrado-fibroso, de color pardo canela rojo zorruno con un marcado mamelón PUNTIAGUDO.","El pie de Cortinarius rubellus es esbelto y amarillento con BANDAS (cinturones amarillos de velo); el pie del pie violeta (Cortinarius caperatus) es más grueso y lleva el manguito membranoso en lugar de bandas.","Consumir solo cuando esté claramente presente el anillo de borde doble; el veneno orellanina es estable al calor y al secado y provoca, tras una latencia de 2 a 21 días, una insuficiencia renal irreversible — ni cocer ni secar lo desintoxica."}','t'),
('zigeunerpilz','cortinarius_rubellus','fr','Pholiote ridée (Reifpilz / Zigeunerpilz) : chapeau jaune paille à brun jaunâtre avec une pruine gris-blanchâtre-lilas (voile), surface caractéristiquement ridée/sillonnée dans le sens de la longueur, anneau membraneux net sur le pied avec un double bord. Cortinaire des montagnes (Cortinarius rubellus) : chapeau sec et finement feutré, jaune à orangé ou brun cannelle roussâtre, à mamelon pointu (ou arrondi), AUCUN véritable anneau (seulement des restes fugaces de cortine/voile), pied élancé et chiné de jaune (ceintures jaunes de voile).','Pholiote ridée (Reifpilz) : agréable/doux. Cortinaire à mamelon pointu (Cortinarius rubellus) : faiblement raphanoïde (odeur de radis).','Pholiote ridée (Reifpilz) : forêts de conifères et (rarement) de feuillus, volontiers auprès de la myrtille sur sol acide et sableux, août à octobre. Cortinaire à mamelon pointu (Cortinarius rubellus) : surtout forêt de conifères (peuplements d''épicéas), souvent dans des stations humides/marécageuses sur sols acides, auprès de la myrtille — le chevauchement d''habitat aggrave le risque.','Pholiote ridée (Reifpilz) : brun cannelle clair à jaune rouille. Cortinarius rubellus : brun rouille. La couleur des spores ne permet PAS de les distinguer de manière fiable ici — ne jamais l''utiliser comme unique critère.','Cherche sur le pied l''anneau membraneux ferme au DOUBLE bord caractéristique — si cet anneau manque et que le pied est au contraire chiné de jaune avec seulement de fugaces fibres de voile, ce n''est pas une pholiote ridée, mais peut-être le mortel cortinaire (Raukopf). En cas de doute, à l''état jeune, TOUJOURS s''adresser à un organe de contrôle des champignons (VAPKO).','{"La pholiote ridée (Reifpilz) possède un anneau membraneux ferme sur le pied, au DOUBLE bord caractéristique ; le cortinaire à mamelon pointu (Cortinarius rubellus) n''a AUCUN véritable anneau, seulement de fugaces fibres de voile (cortine).","Le chapeau de la pholiote ridée (Reifpilz) est mat, PRUINEUX gris-blanchâtre à lilas et ridé dans le sens de la longueur ; le cortinaire (Raukopf) a un chapeau sec, finement feutré-fibrilleux, brun cannelle roussâtre, avec un net mamelon POINTU.","Le pied du cortinaire (Raukopf) est élancé et CHINÉ de jaune (ceintures jaunes de voile) ; le pied de la pholiote ridée (Reifpilz) est plus épais et porte la manchette membraneuse au lieu de ceintures.","Ne consommer que si un anneau à double bord est présent sans ambiguïté ; le poison, l''orellanine, est stable à la chaleur et au séchage et provoque, après une latence de 2 à 21 jours, une insuffisance rénale irréversible — aucune cuisson/aucun séchage ne le détoxifie."}','t'),
('zigeunerpilz','cortinarius_rubellus','it','Cortinario violaceo-bruno (Reifpilz/Rozites caperatus): cappello da giallo paglierino a giallo-bruno con una pruinosità (velo) grigio-biancastro-lillacina, superficie caratteristicamente rugosa/solcata in senso longitudinale, anello del gambo nettamente membranoso con doppio margine. Cortinarius rubellus: cappello da giallo ad arancio o rosso-volpino-cannella, secco e finemente feltrato, con umbone appuntito (o arrotondato), SENZA un vero anello (solo resti fugaci di cortina/velo), gambo slanciato e giallastro screziato (cinte di velo gialle).','Cortinario violaceo-bruno (Reifpilz): gradevole/delicato. Cortinarius rubellus: debolmente rafanoide (di ravanello).','Cortinario violaceo-bruno (Reifpilz): bosco di conifere e (raramente) di latifoglie, predilige la presenza di mirtillo su terreno acido e sabbioso, da agosto a ottobre. Cortinarius rubellus: soprattutto bosco di conifere (peccete), spesso in stazioni umide/torbose su terreni acidi, presso il mirtillo — la sovrapposizione di habitat aggrava il rischio.','Cortinario violaceo-bruno (Reifpilz): da bruno-cannella chiaro a giallo-ruggine. Cortinarius rubellus: bruno-ruggine. Qui il colore delle spore NON distingue in modo affidabile — non utilizzarlo mai come unico carattere.','Cerca sul gambo l''anello membranoso e consistente con il caratteristico DOPPIO margine — se questo anello manca e il gambo è invece giallastro e screziato con sole fibre fugaci di velo, non si tratta del Reifpilz, bensì possibilmente del mortale Cortinarius rubellus. In caso di dubbio, allo stadio giovane rivolgiti SEMPRE all''organo ufficiale di controllo dei funghi (VAPKO).','{"Il cortinario violaceo-bruno (Reifpilz) ha un anello del gambo consistente e membranoso con il caratteristico DOPPIO margine; il Cortinarius rubellus NON ha un vero anello, solo fibre fugaci di velo (cortina).","Il cappello del cortinario violaceo-bruno (Reifpilz) è opaco, PRUINOSO da grigio-biancastro a lillacino e rugoso in senso longitudinale; il Cortinarius rubellus ha un cappello secco, finemente feltrato-fibrilloso, rosso-volpino-cannella, con un netto umbone APPUNTITO.","Il gambo del Cortinarius rubellus è slanciato e giallastro SCREZIATO (cinte di velo gialle); il gambo del cortinario violaceo-bruno (Reifpilz) è più spesso e porta il manicotto membranoso anziché le cinte.","Consumare solo in presenza inequivocabile dell''anello a doppio margine; il veleno orellanina è stabile al calore e all''essiccazione e provoca, dopo una latenza di 2-21 giorni, un''insufficienza renale irreversibile — nessuna cottura/essiccazione lo disintossica."}','t'),
('zigeunerpilz','cortinarius_semisanguineus','en','The Gypsy mushroom (Cortinarius caperatus) is large, grey-brown with a frost-like wrinkled cap and a membranous ring; C. semisanguineus is small, olive-brown with blood-red gills and no true ring.','Gypsy mushroom mild and pleasant; C. semisanguineus odourless to faintly radish-like.','Both grow in acidic coniferous/mixed forests, often near blueberry; therefore the gill colour is the decisive distinguishing feature, not the habitat.','Both have a rust-brown spore print – the spore print does NOT distinguish them; decisive are the blood-red gills (semisanguineus, poisonous) versus ochre gills and a membranous ring (caperatus, edible).','Check the gills: any trace of blood-red = webcap (Dermocybe) = leave it. The Gypsy mushroom is the ONLY recommended edible webcap (Cortinarius) – when in doubt, EVERY Cortinarius must be discarded uneaten.','{"C. semisanguineus has bright blood-red gills when young – a clear warning sign; the edible Gypsy mushroom (C. caperatus) has pale ochre-toned gills, NEVER red.","Cap: C. caperatus grey-brown ochre with a silvery, wrinkled ''frost-like'' coating at the crown; C. semisanguineus olive-ochre to umber-brown, smooth-fibrillose.","C. caperatus has a membranous ring on the stem; C. semisanguineus only has fleeting cortina remnants, no true ring.","Both webcaps (Cortinarius) have a rust-brown spore print – here the gill colour and the ring are the key.","Size: C. caperatus sturdy (cap 5–10 cm); C. semisanguineus small and slender (cap 2–5 cm)."}','f'),
('zigeunerpilz','cortinarius_semisanguineus','es','El cortinario gitano (Cortinarius caperatus) es grande, gris-pardo con un sombrero arrugado como escarchado y un anillo membranoso; C. semisanguineus es pequeño, pardo oliváceo con láminas rojo sangre y sin un verdadero anillo.','Cortinario gitano olor suave y agradable; C. semisanguineus inodoro o débilmente rafanoide (olor a rábano).','Ambos crecen en bosques ácidos de coníferas/mixtos, a menudo junto al arándano; por eso el color de las láminas es el rasgo distintivo decisivo, no el hábitat.','Ambos tienen esporada pardo-herrumbre – la esporada NO los distingue; lo decisivo son las láminas rojo sangre (semisanguineus, venenoso) frente a láminas ocre y un anillo membranoso (caperatus, comestible).','Controlar las láminas: cualquier rastro de rojo sangre = cortinario (Dermocybe) = dejarlo. El cortinario gitano es el ÚNICO cortinario comestible recomendado – en caso de duda, TODO Cortinarius debe desecharse sin consumir.','{"C. semisanguineus tiene de joven láminas de un rojo sangre brillante – una clara señal de alarma; el comestible cortinario gitano (C. caperatus) tiene láminas de tono ocre pálido, NUNCA rojas.","Sombrero: C. caperatus gris-pardo ocre con un recubrimiento plateado y arrugado «como escarchado» en el ápice; C. semisanguineus de pardo ocre oliváceo a pardo umbra, liso-fibrilloso.","C. caperatus tiene un anillo membranoso en el pie; C. semisanguineus solo presenta fugaces restos de cortina, ningún verdadero anillo.","Ambos cortinarios con esporada pardo-herrumbre – aquí el color de las láminas y el anillo son la clave.","Tamaño: C. caperatus robusto (sombrero 5–10 cm); C. semisanguineus pequeño y grácil (sombrero 2–5 cm)."}','f'),
('zigeunerpilz','cortinarius_semisanguineus','fr','Rozite ridée grande, gris-brun avec un chapeau pruineux-ridé et un anneau membraneux ; C. semisanguineus petit, brun-olive avec des lamelles rouge sang sans véritable anneau.','Rozite ridée douce-agréable ; C. semisanguineus inodore à faiblement de radis.','Les deux dans les forêts de conifères/mixtes acides, souvent près de la myrtille ; c''est pourquoi la couleur des lamelles est le critère de séparation décisif, pas la station.','Les deux brun rouille – la sporée ne sépare PAS ; décisives sont les lamelles rouge sang (semisanguineus, toxique) vs. ocre et anneau membraneux (caperatus, comestible).','Contrôler les lamelles : toute trace de rouge sang = cortinaire = laisser sur place. La rozite ridée est le SEUL cortinaire comestible recommandé – en cas de doute, TOUT cortinaire doit être jeté non mangé.','{"C. semisanguineus a jeune des lamelles rouge sang éclatant – un signal d''alarme clair ; la rozite ridée comestible (C. caperatus) a des lamelles ocre-pâle, JAMAIS rouges.","Chapeau : C. caperatus gris-brun-ocre avec un revêtement « pruineux » argenté-ridé au sommet ; C. semisanguineus ocre-olive à brun ombré, lisse-fibrilleux.","C. caperatus a un anneau membraneux au pied ; C. semisanguineus seulement des restes fugaces de cortine, pas de véritable anneau.","Les deux cortinaires à sporée brun rouille – la couleur des lamelles et l''anneau sont ici les clés.","Taille : C. caperatus robuste (chapeau 5–10 cm) ; C. semisanguineus petit-gracile (chapeau 2–5 cm)."}','f'),
('zigeunerpilz','cortinarius_semisanguineus','it','La rossola grinzosa (Cortinarius caperatus) è grande, grigio-bruna con cappello grinzoso come brinato e anello membranoso; C. semisanguineus è piccolo, bruno olivastro con lamelle rosso sangue senza un vero anello.','Rossola grinzosa odore mite e gradevole; C. semisanguineus inodore o debolmente rafanoide (odore di ravanello).','Entrambi crescono in boschi acidi di conifere/misti, spesso presso il mirtillo; perciò è il colore delle lamelle il carattere distintivo decisivo, non l''habitat.','Entrambi hanno sporata bruno-ruggine – la sporata NON li distingue; decisive sono le lamelle rosso sangue (semisanguineus, velenoso) contro lamelle ocra e anello membranoso (caperatus, commestibile).','Controllare le lamelle: ogni minima traccia di rosso sangue = Cortinario (Dermocybe) = lasciare sul posto. La rossola grinzosa è l''UNICO cortinario commestibile raccomandato – nel dubbio, OGNI Cortinarius va gettato senza essere consumato.','{"C. semisanguineus ha da giovane lamelle di un rosso sangue brillante – un chiaro segnale d''allarme; la commestibile rossola grinzosa (C. caperatus) ha lamelle di tonalità ocra pallida, MAI rosse.","Cappello: C. caperatus grigio-bruno ocra con rivestimento argenteo e grinzoso «come brinato» al centro; C. semisanguineus da bruno ocra olivastro a bruno ombra, liscio-fibrilloso.","C. caperatus ha un anello membranoso sul gambo; C. semisanguineus presenta solo fugaci resti di cortina, nessun vero anello.","Entrambi i Cortinari con sporata bruno-ruggine – qui il colore delle lamelle e l''anello sono la chiave.","Dimensione: C. caperatus robusto (cappello 5–10 cm); C. semisanguineus piccolo e gracile (cappello 2–5 cm)."}','f'),
('zigeunerpilz','cortinarius_splendens','en','Bright yellow = warning sign: any webcap (Cortinarius) that is uniformly sulphur/bright yellow is off-limits — the edible gypsy mushroom (Cortinarius caperatus) is dull greyish-ochre-brownish with a frosted cap and a membranous ring.','The gypsy mushroom smells pleasantly mushroomy; Cortinarius splendens is inconspicuous to slightly radish-like — smell does NOT reliably separate them.','The gypsy mushroom grows in acidic coniferous/mixed forests and bilberry stands; the splendid webcap (Cortinarius splendens), a mycorrhizal fungus, grows in calcareous broadleaf forests, typically with beech.','Both have a rust-brown spore print — therefore NO distinguishing criterion. Rely on cap colour (bright yellow!), a true membranous ring and a marginate yellow bulb.','No webcap (Cortinarius) with a rusty spore print for beginners — always leave bright yellow club-footed webcaps standing. The kidney toxin only acts after several days; the poisoning goes unnoticed at first. When in doubt, mushroom inspection (VAPKO).','{"Gypsy mushroom (Cortinarius caperatus): cap greyish-brown/ochreous with a whitish frosted sheen, NOT bright yellow — Cortinarius splendens: strong sulphur to bright yellow throughout.","The gypsy mushroom has a true membranous stem ring; the splendid webcap has only a fleeting yellow cortina (cobweb veil), NO firm membranous ring.","Cortinarius splendens has a marginate yellow bulb and yellow flesh; the gypsy mushroom has a faintly bulbous base without bright yellow.","The splendid webcap contains a nephrotoxic poison (orellanine-syndrome type, not yet definitively identified chemically — NOT necessarily orellanine itself) and can cause fatal kidney failure with a latency of days to weeks.","The gypsy mushroom grows in acidic coniferous/mixed forest and bilberry stands; C. splendens, a mycorrhizal fungus, prefers calcareous broadleaf forests (especially with beech)."}','f'),
('zigeunerpilz','cortinarius_splendens','es','Amarillo brillante = señal de alarma: todo cortinario (Cortinarius) uniformemente amarillo azufre/amarillo vivo está prohibido — la seta comestible (Cortinarius caperatus) es mate, gris-ocre-parduzca, con sombrero pruinoso y anillo membranoso.','Cortinarius caperatus huele agradablemente a hongo; Cortinarius splendens es inodoro o ligeramente rafanoide (a rábano) — el olor NO los separa de forma fiable.','Cortinarius caperatus crece en bosques ácidos de coníferas/mixtos y en arandaneras; el cortinario espléndido (Cortinarius splendens), hongo micorrízico, crece en bosques calcáreos de frondosas, típicamente bajo el haya.','Ambos tienen esporada pardo-herrumbre — por lo tanto NINGÚN criterio de separación. Fiarse del color del sombrero (¡amarillo vivo!), del verdadero anillo membranoso y del bulbo amarillo marginado.','Ningún cortinario (Cortinarius) con esporada herrumbre para principiantes — dejar siempre en el sitio los cortinarios de pie bulboso amarillo brillante. El veneno renal actúa solo tras varios días; la intoxicación pasa inadvertida al principio. En caso de duda, control de setas (VAPKO).','{"Cortinarius caperatus: sombrero gris-parduzco/ocráceo con un brillo pruinoso blanquecino, NO amarillo vivo — Cortinarius splendens: amarillo azufre a amarillo vivo intenso en todas sus partes.","Cortinarius caperatus posee un verdadero anillo membranoso en el pie; el cortinario espléndido solo tiene una cortina amarilla fugaz (velo aracnoideo), NINGÚN anillo membranoso firme.","Cortinarius splendens presenta un bulbo amarillo marginado y carne amarilla; Cortinarius caperatus tiene una base débilmente bulbosa sin amarillo brillante.","El cortinario espléndido contiene un veneno nefrotóxico (de tipo síndrome orellánico, aún no identificado químicamente de forma definitiva — NO necesariamente la orellanina misma) y puede provocar una insuficiencia renal mortal con una latencia de días a semanas.","Cortinarius caperatus crece en bosques ácidos de coníferas/mixtos y en arandaneras; C. splendens, hongo micorrízico, prefiere los bosques calcáreos de frondosas (especialmente bajo el haya)."}','f'),
('zigeunerpilz','cortinarius_splendens','fr','Jaune éclatant = signal d''alarme : tout cortinaire entièrement jaune soufre/jaune vif est à proscrire — le rozite comestible est terne, gris-ocre-brunâtre, avec un chapeau pruineux et un anneau membraneux.','Le rozite a une odeur agréable, fongique ; Cortinarius splendens est inodore à légèrement raphanoïde (de radis) — l''odeur ne sépare PAS de façon fiable.','Le rozite pousse dans les forêts de conifères/mixtes acides et les peuplements de myrtilles ; le cortinaire splendide (Cortinarius splendens), champignon mycorhizien, pousse dans les forêts feuillues calcaires, typiquement sous le hêtre.','Les deux ont une sporée brun-rouille — donc AUCUN critère de séparation. Se fier à la couleur du chapeau (jaune vif !), au véritable anneau membraneux et au bulbe jaune marginé.','Aucun cortinaire (Cortinarius) à sporée rouille pour les débutants — laisser systématiquement sur place les cortinaires à bulbe jaune vif. Le poison rénal n''agit qu''après plusieurs jours, l''intoxication passe d''abord inaperçue. En cas de doute, contrôle des champignons (VAPKO).','{"Rozite/Pholiote ridée (Cortinarius caperatus) : chapeau gris-brunâtre/ocré avec un reflet pruineux blanchâtre, PAS jaune vif — Cortinarius splendens : jaune soufre à jaune vif intense dans toutes ses parties.","Le rozite possède un véritable anneau membraneux sur le pied ; le cortinaire splendide n''a qu''une cortine jaune fugace (voile arachnéen), AUCUN anneau membraneux ferme.","Cortinarius splendens présente un bulbe jaune marginé et une chair jaune ; le rozite a une base faiblement bulbeuse sans jaune éclatant.","Le cortinaire splendide contient un poison néphrotoxique (de type syndrome orellanien, encore non identifié chimiquement de façon définitive — PAS forcément l''orellanine elle-même) et peut provoquer une insuffisance rénale mortelle avec une latence de plusieurs jours à plusieurs semaines.","Le rozite pousse dans les forêts de conifères/mixtes acides et les peuplements de myrtilles ; C. splendens, champignon mycorhizien, préfère les forêts feuillues calcaires (surtout sous le hêtre)."}','f'),
('zigeunerpilz','cortinarius_splendens','it','Giallo brillante = segnale d''allarme: ogni cortinario interamente giallo zolfo/giallo vivo è da evitare — il rozites commestibile è opaco, grigio-ocra-brunastro, con cappello pruinoso e anello membranoso.','Il rozites ha odore aromatico-fungino; Cortinarius splendens è inodore o leggermente rafanoide (di ravanello) — l''odore NON distingue in modo affidabile.','Il rozites cresce nei boschi acidi di conifere/misti e nelle brughiere a mirtillo; il cortinario splendente (Cortinarius splendens), fungo micorrizico, cresce nei boschi di latifoglie calcarei, tipicamente sotto il faggio.','Entrambi hanno sporata bruno-ruggine — quindi NESSUN criterio di distinzione. Affidarsi al colore del cappello (giallo vivo!), al vero anello membranoso e al bulbo giallo marginato.','Nessun cortinario (Cortinarius) con sporata ruggine per i principianti — lasciare sempre sul posto i cortinari con bulbo giallo brillante. Il veleno renale agisce solo dopo giorni, l''avvelenamento inizialmente passa inosservato. In caso di dubbio, controllo dei funghi (VAPKO).','{"Rozites/Pholiota raggrinzita (Cortinarius caperatus): cappello grigio-brunastro/ocraceo con riflesso pruinoso biancastro, NON giallo vivo — Cortinarius splendens: giallo zolfo o giallo vivo intenso in tutte le parti.","Il rozites possiede un vero anello membranoso sul gambo; il cortinario splendente ha solo una cortina gialla fugace (velo ragnateloso), NESSUN anello membranoso solido.","Cortinarius splendens presenta un bulbo giallo marginato e carne gialla; il rozites ha una base debolmente bulbosa senza giallo brillante.","Il cortinario splendente contiene un veleno nefrotossico (di tipo sindrome orellanica, ancora non identificato chimicamente in modo definitivo — NON necessariamente l''orellanina stessa) e può provocare un''insufficienza renale mortale con latenza da giorni a settimane.","Il rozites nei boschi acidi di conifere/misti e nelle brughiere a mirtillo; C. splendens, fungo micorrizico, predilige i boschi di latifoglie calcarei (soprattutto sotto il faggio)."}','f')
